COLLDATA("muslim","ur",[[6511,"قتیبہ بن سعید اور ہناد بن سری نے کہا : ہمیں ابواحوص نے منصور سے حدیث بیان کی ، انھوں نے ابراہیم بن یزید سے ، انھوں نے عبیدہ سلیمانی سے ، انھوں نے سیدنا عبداللہ ( بن مسعود رضی اللہ تعالیٰ عنہ ) سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" میر ی امت میں سے بہترین اس دور کے لوگ ہیں جو میرے ساتھ ہیں ( صحابہ ) ، پھر وہ ہیں جو ان کےساتھ ( کے دور میں ) ہوں گے ( تابعین ) ، پھر وہ جوان کے ساتھ ( کے دور میں ) ہوں گے ( تبع تابعین ) ، پھر ایسے لوگ آئیں گے کہ ان کی گواہی ان کی قسم سے پہلے ہوگی ۔ اور ان کی قسم ان کی گواہی سے پہلے ہوگی ۔ \" ہناد نے اپنی حدیث میں قرن ( دور ) کا ذکر نہیں کیا ۔ اور قتیبہ نے کہا : \" پھر ایسی اقوام آئیں گی ۔","",{"u2":"قتیبہ بن سعید اور ہناد بن سری نے کہا:ہمیں ابواحوص نے منصور سے حدیث بیان کی،انھوں نے ابراہیم بن یزید سے،انھوں نے عبیدہ سلیمانی سے،انھوں نے حضرت عبداللہ(بن مسعود رضی اللہ تعالیٰ عنہ) سے روایت کی،کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"میر ی امت میں سے بہترین اس دور کے لوگ ہیں جو میرے ساتھ ہیں(صحابہ)،پھر وہ ہیں جو ان کےساتھ(کے دور میں) ہوں گے(تابعین)،پھر وہ جوان کے ساتھ(کے دور میں)ہوں گے(تبع تابعین)،پھر ایسے لوگ آئیں گے کہ ان کی گواہی ان کی قسم سے پہلے ہوگی۔اور ان کی قسم ان کی گواہی سے پہلے ہوگی۔\"ہناد نے اپنی حدیث میں قرن(دور) کا ذکر نہیں کیا۔اور قتیبہ نے کہا:\"پھر ایسی اقوام آئیں گی۔\""}],[6512,"جریر نے منصور سے ، انھوں نے ابراہیم سے ، انھوں نے سیدنا عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم سے سوال کیا گیا : لوگوں میں سب سے بہتر کون ہیں؟آپ نے فرمایا : \"\" میرے دور کے لوگ پھر وہ جو ان کے ساتھ ( کے دور میں ) ہوں گے ، پھر وہ جو ان کے ساتھ ہوں گے ، پھر ایک ایسی قوم آئے گی کہ ان کی شہادت ان کی قسم سے جلدی ہوگی اور ان کی قسم انکی شہادت سے جلدی ہوگی ۔ \"\" ابراہیم ( نخعی ) نے کہا : جس وقت ہم کم عمر تھے ( تو بڑی عمر کے ) لوگ ہمیں قسم کھانے اور شہادت دینے سے منع کرتے تھے ۔","",{"u2":"جریر نے منصور سے،انھوں نے ابراہیم سے،انھوں نے حضرت عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ سے روایت کی،کہا:رسول اللہ صلی اللہ علیہ وسلم سے سوال کیا گیا:لوگوں میں سب سے بہتر کون ہیں؟آپ نے فرمایا:\"میرے دور کے لوگ پھر وہ جو ان کے ساتھ(کے دور میں) ہوں گے،پھر وہ جو ان کے ساتھ ہوں گے،پھر ایک ایسی قوم آئے گی کہ ان کی شہادت ان کی قسم سے جلدی ہوگی اور ان کی قسم انکی شہادت سے جلدی ہوگی۔\"\nابراہیم(نخعی) نے کہا:جس وقت ہم کم عمر تھے(تو بڑی عمرکے) لوگ ہمیں قسم کھانے اور شہادت دینے سے منع کرتے تھے۔"}],[6513,"شعبہ اور سفیان دونوں نے منصور سے ابو احوص اور جریر کی سند کے ساتھ انھی دونوں کی حدیث کے ہم معنی حدیث روایت کی ، دونوں کی حدیث میں \" رسول اللہ صلی اللہ علیہ وسلم سے سوال کیاگیا \" ( کے الفاظ ) نہیں ۔","",{"u2":"شعبہ اور سفیان دونوں نے منصور سے ابو احوص اور جریر کی سند کے ساتھ انھی دونوں کی حدیث کے ہم معنی حدیث روایت کی،دونوں کی حدیث میں\"رسول اللہ صلی اللہ علیہ وسلم سے سوال کیاگیا\"(کے الفاظ) نہیں۔"}],[6514,"ابن عون نے ابراہیم سے ، انھوں نے عبیدہ سے ، انھوں نے سیدنا عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ سے ، انھوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا؛ \" لوگوں میں سے بہترین میرے دور کے لوگ ( صحابہ رضوان اللہ عنھم اجمعین ) ہیں ، پھر وہ جو ان کے ساتھ ( کے دور کے ) ہوں گے ( تابعین رحمۃ اللہ علیہ ) ، پھر وہ جوان کے ساتھ ( کے دور کے ) ہوں گے ( تبع تابعین ۔ ) \" ( عبیدہ سلیمانی نے کہا : ) مجھے یاد نہیں ( کہ سیدنا عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ نے ) تیسری بار کہا یا چوتھی بار : \" پھر ان کے جانشین ایسے لوگ ہوں گے کہ ان میں سے کسی ایک کی گواہی قسم سے پہلے ہوگی اور اور اس کی قسم اس کی گواہی سے پہلے ہوگی ۔","",{"u2":"ابن عون نے ابراہیم سے،انھوں نے عبیدہ سے،انھوں نے حضرت عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ سے،انھوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا؛\"لوگوں میں سے بہترین میرے دور کے لوگ(صحابہ رضوان اللہ عنھم اجمعین)ہیں،پھر وہ جو ان کے ساتھ(کے دورکے) ہوں گے(تابعین رحمۃ اللہ علیہ)،پھر وہ جوان کے ساتھ(کے دور کے) ہوں گے(تبع تابعین۔)\"(عبیدہ سلیمانی نے کہا:)مجھے یاد نہیں(کہ حضرت عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ نے) تیسری بار کہا یاچوتھی بار:\"پھر ان کے جانشین ایسے لوگ ہوں گے کہ ان میں سے کسی ایک کی گواہی قسم سے پہلے ہوگی اوراور اس کی قسم اس کی گواہی سے پہلے ہوگی۔\""}],[6515,"ہشیم نے ابو بشر سے ، انھوں نے عبداللہ بن شقیق سے ، انھوں نے سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" میری امت کے بہترین لوگ اس زمانے کے ہیں جن میں میری بعثت ہوئی ہے ، پھر وہ لوگ ہیں جو ان کے ساتھ ( کے دور کے ) ہیں ۔ \" اللہ ہی خوب جانتا ہے کہ آپ نے تیسرے زمانے کا ذکر کیا تھا یا نہیں ، فرمایا؛ \" پھر ایک ایسی قوم آئے گی جو موٹا ہونا پسند کریں گے ، وہ شہادت طلب کیے جانے سے پہلے شہادت دیں گے ۔","",{"u2":"ہشیم نے ابو بشر سے،انھوں نے عبداللہ بن شقیق سے،انھوں نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی،کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"میری امت کے بہترین لوگ اس زمانے کے ہیں جن میں میری بعثت ہوئی ہے،پھر وہ لوگ ہیں جو ان کے ساتھ(کے دور کے) ہیں۔\"اللہ ہی خوب جانتا ہے کہ آپ نے تیسرے زمانے کا ذکر کیاتھا یا نہیں،فرمایا؛\" پھر ایک ایسی قوم آئے گی جو موٹا ہونا پسند کریں گے،وہ شہادت طلب کیے جانے سے پہلے شہادت دیں گے۔\""}],[6516,"شعبہ اور ابو عوانہ دونوں نے ابو بشر سے اسی سند کے ساتھ اسی کے مانند روایت کی ، مگر شعبہ کی حدیث میں ہے : ابو ہریرہ رضی اللہ تعالیٰ عنہ نے کہا : میں نہیں جانتا ( کہ آپ نے ) دوبار ( کہا ) یا تین بار ۔","",{"u2":"شعبہ اور ابو عوانہ دونوں نے ابو بشر سے اسی سند کے ساتھ اسی کے مانند روایت کی،مگر شعبہ کی حدیث میں ہے:ابو ہریرہ رضی اللہ تعالیٰ عنہ نے کہا:میں نہیں جانتا(کہ آپ نے) دوبار (کہا) یا تین بار۔"}],[6517,"محمد بن جعفر نے کہا : ہمیں شعبہ نے حدیث بیان کی ، انھوں نے کہا : میں نے ابو جمرہ سے سنا ، انھوں نےکہا : مجھے زہدم بن مضرب نے حدیث بیان کی ، انھوں نے کہا : میں نے سیدنا عمران بن حصین رضی اللہ تعالیٰ عنہ سے سنا ، وہ حدیث بیان کررہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تم میں سب سے اچھے میرے دور کے لوگ ہیں ، پھر وہ جو ان کے ساتھ ہیں ۔ پھر وہ جو ان کے ساتھ ہیں ، پھر وہ لوگ جو ان کے ساتھ ہیں ، \" سیدنا عمران رضی اللہ تعالیٰ عنہ نے کہا : مجھے یاد نہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے دور کے بعد دوبار فرمایا یا تین بار؟ ( پھر آپ نے فرمایا : ) \" پھر ان کے بعد وہ لوگ ہوں گے کہ وہ گواہی دیں گے جبکہ ان سے گواہی مطلوب نہیں ہوگی اورخیانت کریں جبکہ ان کو امانت دار نہیں بنایا جائے گا ( جس مال کی ذمہ داری ان کے پاس نہیں ہوگی اس میں بھی خیانت کے راستے نکالیں گے ) ، وہ نذر مانیں گے لیکن اپنی نذریں پوری نہیں کریں گے اور ان میں موٹاپا ظاہر ہوجائے گا ۔","",{"u2":"محمد بن جعفر نے کہا:ہمیں شعبہ نے حدیث بیان کی،انھوں نے کہا:میں نے ابو جمرہ سے سنا،انھوں نےکہا:مجھے زہدم بن مضرب نے حدیث بیان کی،انھوں نے کہا:میں نے حضرت عمران بن حصین رضی اللہ تعالیٰ عنہ سے سنا،وہ حدیث بیان کررہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"تم میں سب سے اچھے میرے دور کے لوگ ہیں،پھر وہ جو ان کے ساتھ ہیں۔پھر وہ جو ان کے ساتھ ہیں،پھر وہ لوگ جو ان کے ساتھ ہیں،\"حضرت عمران رضی اللہ تعالیٰ عنہ نے کہا:مجھے یاد نہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے دور کے بعد دوبار فرمایا یا تین بار؟(پھر آپ نے فرمایا:)\"پھر ان کے بعد وہ لوگ ہوں گے کہ وہ گواہی دیں گے جبکہ ان سے گواہی مطلوب نہیں ہوگی اورخیانت کریں جبکہ ان کو امانت دار نہیں بنایا جائے گا(جس مال کی ذمہ داری ان کے پاس نہیں ہوگی اس میں بھی خیانت کے راستے نکالیں گے)،وہ نذر مانیں گے لیکن اپنی نذریں پوری نہیں کریں گے اور ان میں موٹاپا ظاہر ہوجائے گا۔\""}],[6518,"یحییٰ بن سعید ، بہز اور شبابہ سب نے شعبہ سے اسی سند کے ساتھ حدیث بیان کی اور ان سب کی حدیث میں ہے ( سیدنا عمران بن حصین رضی اللہ تعالیٰ عنہ نے ) کہا : مجھے یاد نہیں کہ آپ صلی اللہ علیہ وسلم نے اپنے زمانے کےبعد دو زمانوں کا ذکر کیا یا تین کا ، شبابہ کی حدیث میں ہے کہ ( ابو جمرہ نے ) کہا : میں نے زہدم بن مضرب سےسنا ، وہ گھوڑے پرسوارہوکرمیرے پاس ایک کام کے لئے آئے تھے ، انھوں نے مجھے حدیث سنائی کہ انھوں نے سیدنا عمران بن حصین رضی اللہ تعالیٰ عنہ سے سنا ، نیز یحییٰ ( بن سعید ) اورشبابہ کی حدیث میں ہے : \" وہ نذریں مانیں گے لیکن وفا نہیں کریں گے ۔ \" اور بہز کی حدیث میں اسی طرح ہے جس طرح ابن جعفر کی حدیث میں ہے : \" وہ ( اپنی نذریں ) پوری نہیں کریں گے ۔","",{"u2":"یحییٰ بن سعید،بہز اور شبابہ سب نے شعبہ سے اسی سند کے ساتھ حدیث بیان کی اور ان سب کی حدیث میں ہے(حضرت عمران بن حصین رضی اللہ تعالیٰ عنہ نے) کہا:مجھے یاد نہیں کہ آپ صلی اللہ علیہ وسلم نے اپنے زمانے کےبعد دو زمانوں کا ذکر کیا یا تین کا،شبابہ کی حدیث میں ہے کہ(ابو جمرہ نے) کہا:میں نے زہدم بن مضرب سےسنا،وہ گھوڑے پرسوارہوکرمیرے پاس ایک کام کے لئے آئے تھے،انھوں نے مجھے حدیث سنائی کہ انھوں نے حضرت عمران بن حصین رضی اللہ تعالیٰ عنہ سے سنا،نیز یحییٰ(بن سعید) اورشبابہ کی حدیث میں ہے:\"وہ نذریں مانیں گے لیکن وفا نہیں کریں گے۔\"اور بہز کی حدیث میں اسی طرح ہے جس طرح ابن جعفر کی حدیث میں ہے:\"وہ(اپنی نذریں) پوری نہیں کریں گے۔\""}],[6519,"ابو عوانہ اور ہشام دونوں نے قتادہ سے ، انھوں نے زرارہ بن اوفیٰ سے ، انھوں نے سیدنا عمران بن حصین رضی اللہ تعالیٰ عنہ سے ، انھوں نے نبی کریم صلی اللہ علیہ وسلم سے یہ حدیث ( ان الفاظ میں ) روایت کی : \" اس امت کے بہترین لوگ اس دور کے ہیں جس میں مجھے ان میں بھیجاگیا ہے ، پھر وہ جوان کےساتھ ( کے دور میں ) ہوں گے ۔ \" ۔ ۔ ۔ ابو عوانہ کی حدیث میں مزید یہ ہے کہ ( سیدنا عمران رضی اللہ تعالیٰ عنہ نے ) کہا : اللہ زیادہ جاننے والا ہے کہ آپ صلی اللہ علیہ وسلم نے تیسرے ( دور ) کا ذکر کیا یا نہیں ، جس طرح سیدنا عمران بن حصین رضی اللہ تعالیٰ عنہ سےزہدم کی روایت کردہ حدیث ہے ۔ اور قتادہ سے ہشام کی روایت کردہ حدیث میں یہ الفاظ زائد ہیں : \" وہ قسمیں کھائیں گے جبکہ ان سے قسم کھانے کا مطالبہ نہیں کیا جائے گا ۔","",{"u2":"ابو عوانہ اور ہشام دونوں نے قتادہ سے،انھوں نے زرارہ بن اوفیٰ سے،انھوں نے حضرت عمران بن حصین رضی اللہ تعالیٰ عنہ سے،انھوں نے نبی کریم صلی اللہ علیہ وسلم سے یہ حدیث(ان الفاظ میں) روایت کی:\"اس امت کے بہترین لوگ اس دور کے ہیں جس میں مجھے ان میں بھیجاگیا ہے،پھر وہ جوان کےساتھ(کے دور میں)ہوں گے۔\"۔۔۔ابو عوانہ کی حدیث میں مزید یہ ہے کہ(حضرت عمران رضی اللہ تعالیٰ عنہ نے) کہا:اللہ زیادہ جاننے والا ہے کہ آپ صلی اللہ علیہ وسلم نے تیسرے(دور) کا ذکر کیا یا نہیں،جس طرح حضرت عمران بن حصین رضی اللہ تعالیٰ عنہ سےزہدم کی روایت کردہ حدیث ہے۔اور قتادہ سے ہشام کی روایت کردہ حدیث میں یہ الفاظ زائد ہیں:\" وہ قسمیں کھائیں گے جبکہ ان سے قسم کھانے کا مطالبہ نہیں کیا جائے گا۔\""}],[6520,"عبداللہ بہی نے سیدہ عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی ، کہا : ایک آدمی نے نبی کریم صلی اللہ علیہ وسلم سے سوال کیا کہ کون سے لوگ سب سے بہتر ہیں؟آپ صلی اللہ علیہ وسلم نے فرمایا : \" اس دور میں جس میں ہوں ، پھر دوسرے ( دور کے ) ، پھر تیسرے ( دور کے ۔)","",{"u2":"عبداللہ بہی نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی،کہا:ایک آدمی نے نبی کریم صلی اللہ علیہ وسلم سے سوال کیا کہ کون سے لوگ سب سے بہتر ہیں؟آپ صلی اللہ علیہ وسلم نے فرمایا:\"اس دور میں جس میں ہوں،پھر دوسرے(دورکے)،پھر تیسرے(دور کے۔)\""}],[6521,"معمر نے زہری سے روایت کی ، انھوں نے کہا : مجھے سالم بن عبداللہ اور ابو بکر بن سلیمان نے بتا یا کہ عبد اللہ بن عمر رضی اللہ تعالیٰ عنہ نے کہا : نبی صلی اللہ علیہ وسلم نے اپنی حیات مبا رکہ کے آخری حصے میں ایک را ت ہمیں عشاء کی نما ز پڑھا ئی ، جب آپ صلی اللہ علیہ وسلم نے سلا م پھیرا تو کھڑے ہو گئے تو فرما یا : \" کیا تم لوگوں نے اپنی اس را ت کو دیکھا ہے؟ ( اسے یا د رکھو ) بلا شبہ اس رات سے سو سال کے بعد جو لو گ ( اس را ت میں ) روئے زمین پر مو جودہیں ان میں سے کو ئی بھی باقی نہیں ہو گا ۔ \" سیدنا عمر رضی اللہ تعالیٰ عنہ نے کہا : ( بعض ) لو گ رسول اللہ صلی اللہ علیہ وسلم کے فر ما ن کے متعلق غلط فہمیوں میں مبتلا ہوئے ہیں جو اس میں سو سال کے حوالے سے مختلف باتیں کر رہے ہیں ( کہ سو سال بعد زندگی کا خاتمہ ہو جا ئے گا ۔ ) رسول اللہ صلی اللہ علیہ وسلم نے یہ فرما یا تھا ۔ \" آج جو لوگ روئےزمین پر مو جو د ہیں ان میں سے کو ئی باقی نہیں ہو گا ۔ \" آپ کا مقصود یہ تھا کہ اس قرن ( اس دور میں رہنے والے لوگوں ) کا خاتمہ ہو جائے گا ۔","",{"u2":"معمر نے زہری سے روایت کی، انھوں نے کہا: مجھے سالم بن عبداللہ اور ابو بکر بن سلیمان نے بتا یا کہ عبد اللہ بن عمر رضی اللہ تعالیٰ عنہ نے کہا: نبی صلی اللہ علیہ وسلم نے اپنی حیات مبا رکہ کے آخری حصے میں ایک را ت ہمیں عشاء کی نما ز پڑھا ئی،جب آپ صلی اللہ علیہ وسلم نے سلا م پھیرا تو کھڑے ہو گئے تو فرما یا:\" کیا تم لوگوں نے اپنی اس را ت کو دیکھا ہے؟(اسے یا د رکھو)بلا شبہ اس رات سے سو سال کے بعد جو لو گ (اس را ت میں) روئے زمین پر مو جودہیں ان میں سے کو ئی بھی باقی نہیں ہو گا۔\"حضرت عمر رضی اللہ تعالیٰ عنہ نے کہا: (بعض) لو گ رسول اللہ صلی اللہ علیہ وسلم کے فر ما ن کے متعلق غلط فہمیوں میں مبتلا ہوئے ہیں جو اس میں سو سال کے حوالے سے مختلف باتیں کر رہے ہیں (کہ سو سال بعد زندگی کا خاتمہ ہو جا ئے گا۔) رسول اللہ صلی اللہ علیہ وسلم نے یہ فرما یا تھا۔\"آج جو لوگ روئےزمین پر مو جو د ہیں ان میں سے کو ئی باقی نہیں ہو گا۔\"آپ کا مقصود یہ تھا کہ اس قرن (اس دور میں رہنے والے لوگوں) کا خاتمہ ہو جائے گا۔"}],[6522,"شعیب اور عبد الرحمٰن بن خالد بن مسافر دونوں نے زہری سے معمر کی سند کے ساتھ انھی کی حدیث کے مانند روایت کی ۔","",{"u2":"شعیب اور عبد الرحمٰن بن خالد بن مسافر دونوں نے زہری سے معمر کی سند کے ساتھ انھی کی حدیث کے مانند روایت کی۔"}],[6523,"حجاج بن محمد نے کہا : ابن جریج نے کہا : مجھے ابو زبیر نے بتا یا ، انھوں نے سیدنا جا بر بن عبد اللہ رضی اللہ تعالیٰ عنہ کو کہتے ہو ئے سناکہ میں نے نبی صلی اللہ علیہ وسلم کو اپنی وفات سے ایک مہینہ قبل یہ فر ما تے ہو ئے سنا : \" تم مجھ سے قیامت کے بارے میں سوال کرتے ہو ؟اس کا علم صرف اور صرف اللہ تعالیٰ کے پاس ہے ( البتہ اس بات پر ) میں اللہ کی قسم کھا تا ہوں کہ اس وقت کو ئی زندہ نفس موجود نہیں جس پر سوسال پورے ہوں ۔","",{"u2":"حجاج بن محمد نے کہا: ابن جریج نے کہا: مجھے ابو زبیر نے بتا یا،انھوں نے حضرت جا بر بن عبد اللہ رضی اللہ تعالیٰ عنہ کو کہتے ہو ئے سناکہ میں نے نبی صلی اللہ علیہ وسلم کو اپنی وفات سے ایک مہینہ قبل یہ فر ما تے ہو ئے سنا:\"تم مجھ سے قیامت کے بارے میں سوال کرتے ہو؟اس کا علم صرف اور صرف اللہ تعالیٰ کے پاس ہے(البتہ اس بات پر) میں اللہ کی قسم کھا تا ہوں کہ اس وقت کو ئی زندہ نفس موجود نہیں جس پر سوسال پورے ہوں۔\""}],[6524,"ابن جریج نے اسی سند کے ساتھ ہمیں خبر دی اور اس بات کا ذکر نہیں کیا کہ ( آپ نے ) اپنی وفات سے ایک ماہ قبل ( یہ ارشاد فرمایا تھا ۔)","",{"u2":"ابن جریج نے اسی سند کے ساتھ ہمیں خبر دی اور اس بات کا ذکر نہیں کیا کہ (آپ نے)اپنی وفات سے ایک ماہ قبل (یہ ارشاد فرمایا تھا۔)"}],[6525,"معتمر بن سلیمان نے کہا : میں نے اپنے والد سے سنا ، کہا : ابو نضرہ نے ہمیں سیدنا جابر بن عبد اللہ رضی اللہ تعالیٰ عنہ سے ، انھوں نے نبی صلی اللہ علیہ وسلم سے حدیث بیان کی ، انھوں نے کہا : آپ نے اپنی وفات سے ایک مہینہ یا قریباًاتنا عرصہ پہلے فرما یا : \" آج کو ئی ایسا سانس لیتا ہوا انسان موجود نہیں کہ اس پر سوسال گزریں تو وہ اس دن بھی زندہ ہو ۔ اور لوگوں کو پانی پلا نے والے عبدالرحمان ( بن آدم ) سے روایت ہے انھوں نے سیدنا جابر بن عبد اللہ رضی اللہ تعالیٰ عنہ سے انھوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی ۔ عبدالرحمان نے اس کا مفہوم بتا یا اور کہا : عمر کی کمی ( مراد ہے)"],[6526,"معتمر بن سلیمان نے کہا : میں نے اپنے والد سے سنا ، کہا : ابو نضرہ نے ہمیں سیدنا جابر بن عبد اللہ رضی اللہ تعالیٰ عنہ سے ، انھوں نے نبی صلی اللہ علیہ وسلم سے حدیث بیان کی ، انھوں نے کہا : آپ نے اپنی وفات سے ایک مہینہ یا قریباًاتنا عرصہ پہلے فرما یا : \" آج کو ئی ایسا سانس لیتا ہوا انسان موجود نہیں کہ اس پر سوسال گزریں تو وہ اس دن بھی زندہ ہو ۔ اور لوگوں کو پانی پلا نے والے عبدالرحمان ( بن آدم ) سے روایت ہے انھوں نے سیدنا جابر بن عبد اللہ رضی اللہ تعالیٰ عنہ سے انھوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی ۔ عبدالرحمان نے اس کا مفہوم بتا یا اور کہا : عمر کی کمی ( مراد ہے)","",{"u2":"معتمر بن سلیمان نے کہا: میں نے اپنے والد سے سنا،کہا: ابو نضرہ نے ہمیں حضرت جابر بن عبد اللہ رضی اللہ تعالیٰ عنہ سے،انھوں نے نبی صلی اللہ علیہ وسلم سے حدیث بیان کی، انھوں نے کہا: آپ نے اپنی وفات سے ایک مہینہ یا قریباًاتنا عرصہ پہلے فرما یا:\" آج کو ئی ایسا سانس لیتا ہوا انسان موجود نہیں کہ اس پر سوسال گزریں تو وہ اس دن بھی زندہ ہو۔اور لوگوں کو پانی پلا نے والے عبدالرحمان (بن آدم) سے روایت ہے انھوں نے حضرت جابر بن عبد اللہ رضی اللہ تعالیٰ عنہ سے انھوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی۔ عبدالرحمان نے اس کا مفہوم بتا یا اور کہا: عمر کی کمی (مراد ہے)"}],[6527,"یزید بن ہارون نے کہا : ہمیں سلیمان تیمی نے دونوں سندوں سے اسی کے مانند حدیث بیان کی ۔","",{"u2":"یزید بن ہارون نے کہا: ہمیں سلیمان تیمی نے دونوں سندوں سے اسی کے مانند حدیث بیان کی۔"}],[6528,"ابو نضر ہ نے سیدنا ابو سعید رضی اللہ تعالیٰ عنہ سے روایت کی ، کہا : جب نبی صلی اللہ علیہ وسلم غزوہ تبوک سے واپس آئے تو اس کے بعد لوگوں نے آپ سے قیامت کے بارے میں سوال کیا رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \" سو سال نہیں گزریں گے ۔ کہ آج زمین پر سانس لیتا ہوا کو ئی شخص موجود ہو ۔ \" ( اس سے پہلے یہ سب ختم ہو جا ئیں گے ۔)","",{"u2":"ابو نضر ہ نے حضرت ابو سعید رضی اللہ تعالیٰ عنہ سے روایت کی، کہا: جب نبی صلی اللہ علیہ وسلم غزوہ تبوک سے واپس آئے تو اس کے بعد لوگوں نے آپ سے قیامت کے بارے میں سوال کیا رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\" سو سال نہیں گزریں گے۔ کہ آج زمین پر سانس لیتا ہوا کو ئی شخص موجود ہو۔\"(اس سے پہلے یہ سب ختم ہو جا ئیں گے۔)"}],[6529,"حصین نے سالم سے ، انھوں نے سیدنا جابر بن عبد اللہ رضی اللہ تعالیٰ عنہ سے روایت کی ، کہا : نبی صلی اللہ علیہ وسلم نے فرما یا : \" ( آج ) سانس لیتا ہوا شخص سو سال ( کی مدت ) تک نہیں پہنچےگا ۔ \" سالم نے کہا : ہم نے ان ( سیدنا جابر رضی اللہ تعالیٰ عنہ ) کے سامنے اس کے بارے میں گفتگو کی اس سے مراد ہر وہ شخص ہے جو اس وقت پیدا ہو چکا تھا ۔","",{"u2":"حصین نے سالم سے، انھوں نے حضرت جابر بن عبد اللہ رضی اللہ تعالیٰ عنہ سے روایت کی،کہا: نبی صلی اللہ علیہ وسلم نے فرما یا:\" (آج) سانس لیتا ہوا شخص سو سال (کی مدت) تک نہیں پہنچےگا۔\" سالم نے کہا: ہم نے ان(حضرت جابر رضی اللہ تعالیٰ عنہ)کے سامنے اس کے بارے میں گفتگو کی اس سے مراد ہر وہ شخص ہے جو اس وقت پیدا ہو چکا تھا۔"}],[6530,"ابو معاویہ نے اعمش سے ، انھوں نے ابو صالح سے ، انھوں نے سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \" میرے صحابہ کرام رضوان اللہ عنھم اجمعین کو برا مت کہو ، میرے صحابہ کرام رضوان اللہ عنھم اجمعین کہو ، اس ذات کی قسم جس کے ہاتھ میں میری جان ہے ۔ !اگر تم میں سے کو ئی شخص اُحد پہا ڑ جتنا سونا بھی خرچ کرے تو وہ ( صحابہ کرام رضوان اللہ عنھم اجمعین ) میں سے کسی ایک کے دیے ہو ئے مد بلکہ اس کے آدھے کے برابر بھی ( اجر ) نہیں پاسکتا ۔","",{"u2":"ابو معاویہ نے اعمش سے، انھوں نے ابو صالح سے، انھوں نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\" میرے صحابہ کرام رضوان اللہ عنھم اجمعین کو برا مت کہو،میرے صحابہ کرام رضوان اللہ عنھم اجمعین کہو،اس ذات کی قسم جس کے ہاتھ میں میری جان ہے۔!اگر تم میں سے کو ئی شخص اُحد پہا ڑ جتنا سونا بھی خرچ کرے تو وہ (صحابہ کرام رضوان اللہ عنھم اجمعین)میں سے کسی ایک کے دیے ہو ئے مد بلکہ اس کے آدھے کے برابر بھی (اجر) نہیں پاسکتا۔\""}],[6531,"جریر نے اعمش سے ، انھوں نے ابو صالح سے ، انھوں نے سیدنا ابو سعید ( خدری ) رضی اللہ تعالیٰ عنہ سے روایت کی کہ سیدنا خالد بن ولید اور عبدالرحمان بن عوف رضی اللہ تعالیٰ عنہ کے درمیان کو ئی مناقشہ تھا ، سیدنا خالد رضی اللہ تعالیٰ عنہ نے ان کو برا کہا : تو رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا : \" میرے صحابہ کرام رضوان اللہ عنھم اجمعین میں سے کسی کو برا نہ کہو ، کیونکہ تم میں سے کسی شخص نے اگر اُحدپہاڑ کے برابر سونا بھی خرچ کیا تو وہ ان میں سے کسی کے دیے ہو ئے ایک مدکے برابر بلکہ اس کے آدھے کے برابر بھی ( اجر ) نہیں پاسکتا ۔","",{"u2":"جریر نے اعمش سے،انھوں نے ابو صالح سے، انھوں نے حضرت ابو سعید (خدری) رضی اللہ تعالیٰ عنہ سے روایت کی کہ حضرت خالد بن ولید اور عبدالرحمان بن عوف رضی اللہ تعالیٰ عنہ کے درمیان کو ئی مناقشہ تھا،حضرت خالد رضی اللہ تعالیٰ عنہ نے ان کو برا کہا: تو رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\" میرے صحابہ کرام رضوان اللہ عنھم اجمعین میں سے کسی کو برا نہ کہو، کیونکہ تم میں سے کسی شخص نے اگر اُحدپہاڑ کے برابرسونا بھی خرچ کیاتو وہ ان میں سے کسی کے دیے ہو ئے ایک مدکے برابر بلکہ اس کے آدھے کے برابر بھی (اجر) نہیں پاسکتا۔\""}],[6532,"وکیع اور شعبہ نے اعمش سے جریر اور ابو معاویہ کی سند کے ساتھ ان دونوں کی حدیث کے مانند روایت کی ، لیکن شعبہ اور وکیع کی حدیث میں عبدالرحمٰن بن عوف اور خالد بن ولید رضی اللہ تعالیٰ عنہ کا تذکرہ نہیں ہے ۔","",{"u2":"وکیع اور شعبہ نے اعمش سے جریر اور ابو معاویہ کی سند کے ساتھ ان دونوں کی حدیث کے مانند روایت کی، لیکن شعبہ اور وکیع کی حدیث میں عبدالرحمٰن بن عوف اور خالد بن ولید رضی اللہ تعالیٰ عنہ کا تذکرہ نہیں ہے۔"}],[6533,"سلیمان بن مغیرہ نے کہا : مجھے سعید جریری نے ابو نضرہ سے حدیث بیان کی ، انھوں نے اُسیر بن جابر رضی اللہ تعالیٰ عنہ سے روایت کی کہ اہل کوفہ ایک وفد میں سیدنا عمر فاروق رضی اللہ تعالیٰ عنہ کے پاس آئے ، ان میں ایک ایسا آدمی بھی تھا جو سیدنا اویس رضی اللہ تعالیٰ عنہ کا ٹھٹا اڑاتا تھا ، سیدنا عمر رضی اللہ تعالیٰ عنہ نے پوچھا : یہاں قرن کے رہنے والوں میں سے کوئی ہے؟وہ شخص ( آگے ) آگیا تو سیدنا عمر رضی اللہ تعالیٰ عنہ نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا : \" تمھارے پاس یمن سے ایک شخص آئے گا ، اس کا نام اویس ہوگا ، یمن میں اس کی والدہ کےسوا کوئی نہیں جسے وہ چھوڑ کرآئے ۔ اس ( کے جسم ) پر سفید ( برص کے ) نشان ہیں ۔ اس نے اللہ سے دعا کی تو اللہ نے ایک دینار یا درہم کے برابر چھوڑ کر باقی سارا نشان ہٹادیا ، وہ تم میں سے جس کو ملے ( وہ اس سے درخواست کرےکہ ) وہ تم لوگوں کےلیے مغفرت کی دعا کرے ۔","",{"u2":"سلیمان بن مغیرہ نے کہا:مجھے سعید جریری نے ابو نضرہ سے حدیث بیان کی،انھوں نے اُسیر بن جابر رضی اللہ تعالیٰ عنہ سے روایت کی کہ اہل کوفہ ایک وفد میں حضرت عمر فاروق رضی اللہ تعالیٰ عنہ کے پاس آئے،ان میں ایک ایسا آدمی بھی تھا جو حضرت اویس رضی اللہ تعالیٰ عنہ کا ٹھٹا اڑاتا تھا،حضرت عمر رضی اللہ تعالیٰ عنہ نے پوچھا:یہاں قرن کے رہنے والوں میں سے کوئی ہے؟وہ شخص(آگے) آگیاتوحضرت عمر رضی اللہ تعالیٰ عنہ نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا:\"تمھارے پاس یمن سے ایک شخص آئے گا،اس کا نام اویس ہوگا،یمن میں اس کی والدہ کےسوا کوئی نہیں جسے وہ چھوڑ کرآئے۔اس(کے جسم) پرسفید(برص کے) نشان ہیں۔اس نے اللہ سے دعا کی تو اللہ نے ایک دینار یا درہم کے برابر چھوڑ کر باقی سارا نشان ہٹادیا،وہ تم میں سے جس کو ملے(وہ اس سے درخواست کرےکہ)وہ تم لوگوں کےلیے مغفرت کی دعاکرے۔\""}],[6534,"حماد بن سلمہ نے سعید جریری سے اسی سند کےساتھ حدیث بیان کی ، کہا : سیدنا عمر بن خطاب رضی اللہ عنہ سے روایت ہے کہا : کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ صلی اللہ علیہ وسلم فرماتے تھے کہ تابعین میں ایک بہترین شخص ہے جس کو اویس کہتے ہیں ، اس کی ایک ماں ہے ( یعنی رشتہ داروں میں سے صرف ماں زندہ ہو گی ) اور اس کو ایک سفیدی ہو گی ۔ تم اس سے کہنا کہ تمہارے لئے دعا کرے ۔","",{"u2":"حماد بن سلمہ نے سعید جریری سے اسی سند کےساتھ حدیث بیان کی،کہا: سیدنا عمر بن خطاب رضی اللہ عنہ سے روایت ہے کہا: کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ صلی اللہ علیہ وسلم فرماتے تھے کہ تابعین میں ایک بہترین شخص ہے جس کو اویس کہتے ہیں، اس کی ایک ماں ہے (یعنی رشتہ داروں میں سے صرف ماں زندہ ہو گی) اور اس کو ایک سفیدی ہو گی۔ تم اس سے کہنا کہ تمہارے لئے دعا کرے۔"}],[6535,"زرارہ بن اوفیٰ نے اُسیر بن جابر رضی اللہ تعالیٰ عنہ سے روایت کی ، کہا : کہ سیدنا عمر بن خطاب رضی اللہ عنہ کے پاس جب یمن سے مدد کے لوگ آتے ( یعنی وہ لوگ جو ہر ملک سے اسلام کے لشکر کی مدد کے لئے جہاد کرنے کو آتے ہیں ) تو وہ ان سے پوچھتے کہ تم میں اویس بن عامر بھی کوئی شخص ہے؟ یہاں تک کہ سیدنا عمر رضی اللہ عنہ خود اویس کے پاس آئے اور پوچھا کہ تمہارا نام اویس بن عامر ہے؟ انہوں نے کہا کہ ہاں ۔ سیدنا عمر رضی اللہ عنہ نے کہا کہ تم مراد قبیلہ کی شاخ قرن سے ہو؟ انہوں نے کہا کہ ہاں ۔ انہوں نے پوچھا کہ تمہیں برص تھا وہ اچھا ہو گیا مگر درہم برابر باقی ہے؟ انہوں نے کہا کہ ہاں ۔ سیدنا عمر رضی اللہ عنہ نے کہا کہ تمہاری ماں ہے؟ انہوں نے کہا کہ ہاں ۔ تب سیدنا عمر رضی اللہ عنہ نے کہا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ صلی اللہ علیہ وسلم فرماتے تھے کہ تمہارے پاس اویس بن عامر یمن والوں کی کمکی فوج کے ساتھ آئے گا ، وہ قبیلہ مراد سے ہے جو قرن کی شاخ ہے ۔ اس کو برص تھا وہ اچھا ہو گیا مگر درہم باقی ہے ۔ اس کی ایک ماں ہے ۔ اس کا یہ حال ہے کہ اگر اللہ کے بھروسے پر قسم کھا بیٹھے تو اللہ تعالیٰ اس کو سچا کرے ۔ پھر اگر تجھ سے ہو سکے تو اس سے اپنے لئے دعا کرانا ۔ تو میرے لئے دعا کرو ۔ پس اویس نے سیدنا عمر رضی اللہ عنہ کے لئے بخشش کی دعا کی ۔ تو سیدنا عمر رضی اللہ عنہ نے کہا کہ تم کہاں جانا چاہتے ہو؟ انہوں نے کہا کہ کوفہ میں ۔ سیدنا عمر رضی اللہ عنہ نے کہا کہ میں تمہیں کوفہ کے حاکم کے نام ایک خط لکھ دوں؟ انہوں نے کہا کہ مجھے خاکساروں میں رہنا اچھا معلوم ہوتا ہے ۔ جب دوسرا سال آیا تو ایک شخص نے کوفہ کے رئیسوں میں سے حج کیا ۔ وہ سیدنا عمر رضی اللہ عنہ سے ملا تو سیدنا عمر رضی اللہ عنہ نے اس سے اویس کا حال پوچھا تو وہ بولا کہ میں نے اویس کو اس حال میں چھوڑا کہ ان کے گھر میں اسباب کم تھا اور ( خرچ سے ) تنگ تھے ۔ سیدنا عمر رضی اللہ عنہ نے کہا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ صلی اللہ علیہ وسلم فرماتے تھے کہ اویس بن عامر تمہارے پاس یمن والوں کے امدادی لشکر کے ساتھ آئے گا ، وہ مراد قبیلہ کی شاخ قرن میں سے ہے ۔ اس کو برص تھا وہ اچھا ہو گیا صرف درہم کے برابر باقی ہے ۔ اس کی ایک ماں ہے جس کے ساتھ وہ نیکی کرتا ہے ۔ اگر وہ اللہ پر قسم کھا بیٹھے تو اللہ تعالیٰ اس کو سچا کرے ۔ پھر اگر تجھ سے ہو سکے کہ وہ تیرے لئے دعا کرے تو اس سے دعا کرانا ۔ وہ شخص یہ سن کر اویس کے پاس آیا اور کہنے لگا کہ میرے لئے دعا کرو ۔ اویس نے کہا کہ تو ابھی نیک سفر کر کے آ رہا ہے ( یعنی حج سے ) میرے لئے دعا کر ۔ پھر وہ شخص بولا کہ میرے لئے دعا کر ۔ اویس نے یہی جواب دیا پھر پوچھا کہ تو سیدنا عمر رضی اللہ عنہ سے ملا؟ وہ شخص بولا کہ ہاں ملا ۔ اویس نے اس کے لئے دعا کی ۔ اس وقت لوگ اویس کا درجہ سمجھے ۔ وہ وہاں سے سیدھے چلے ۔ اسیر نے کہا کہ میں نے ان کو ان کا لباس ایک چادر پہنائی جب کوئی آدمی ان کو دیکھتا تو کہتا کہ اویس کے پاس یہ چادر کہاں سے آئی ہے؟ ( وہ ایسے تھے کہ ایک مناسب چادر بھی ان کے پاس ہونا باعث تعجب تھا ۔)","",{"u2":"زرارہ بن اوفیٰ نے اُسیر بن جابر رضی اللہ تعالیٰ عنہ سے روایت کی،کہا: کہ سیدنا عمر بن خطاب رضی اللہ عنہ کے پاس جب یمن سے مدد کے لوگ آتے (یعنی وہ لوگ جو ہر ملک سے اسلام کے لشکر کی مدد کے لئے جہاد کرنے کو آتے ہیں) تو وہ ان سے پوچھتے کہ تم میں اویس بن عامر بھی کوئی شخص ہے؟ یہاں تک کہ سیدنا عمر رضی اللہ عنہ خود اویس کے پاس آئے اور پوچھا کہ تمہارا نام اویس بن عامر ہے؟ انہوں نے کہا کہ ہاں۔ سیدنا عمر رضی اللہ عنہ نے کہا کہ تم مراد قبیلہ کی شاخ قرن سے ہو؟ انہوں نے کہا کہ ہاں۔ انہوں نے پوچھا کہ تمہیں برص تھا وہ اچھا ہو گیا مگر درہم برابر باقی ہے؟ انہوں نے کہا کہ ہاں۔ سیدنا عمر رضی اللہ عنہ نے کہا کہ تمہاری ماں ہے؟ انہوں نے کہا کہ ہاں۔ تب سیدنا عمر رضی اللہ عنہ نے کہا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ صلی اللہ علیہ وسلم فرماتے تھے کہ تمہارے پاس اویس بن عامر یمن والوں کی کمکی فوج کے ساتھ آئے گا، وہ قبیلہ مراد سے ہے جو قرن کی شاخ ہے۔ اس کو برص تھا وہ اچھا ہو گیا مگر درہم باقی ہے۔ اس کی ایک ماں ہے۔ اس کا یہ حال ہے کہ اگر اللہ کے بھروسے پر قسم کھا بیٹھے تو اللہ تعالیٰ اس کو سچا کرے۔ پھر اگر تجھ سے ہو سکے تو اس سے اپنے لئے دعا کرانا۔ تو میرے لئے دعا کرو۔ پس اویس نے سیدنا عمر رضی اللہ عنہ کے لئے بخشش کی دعا کی۔ تو سیدنا عمر رضی اللہ عنہ نے کہا کہ تم کہاں جانا چاہتے ہو؟ انہوں نے کہا کہ کوفہ میں۔ سیدنا عمر رضی اللہ عنہ نے کہا کہ میں تمہیں کوفہ کے حاکم کے نام ایک خط لکھ دوں؟ انہوں نے کہا کہ مجھے خاکساروں میں رہنا اچھا معلوم ہوتا ہے۔ جب دوسرا سال آیا تو ایک شخص نے کوفہ کے رئیسوں میں سے حج کیا۔ وہ سیدنا عمر رضی اللہ عنہ سے ملا تو سیدنا عمر رضی اللہ عنہ نے اس سے اویس کا حال پوچھا تو وہ بولا کہ میں نے اویس کو اس حال میں چھوڑا کہ ان کے گھر میں اسباب کم تھا اور (خرچ سے) تنگ تھے۔ سیدنا عمر رضی اللہ عنہ نے کہا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ صلی اللہ علیہ وسلم فرماتے تھے کہ اویس بن عامر تمہارے پاس یمن والوں کے امدادی لشکر کے ساتھ آئے گا، وہ مراد قبیلہ کی شاخ قرن میں سے ہے۔ اس کو برص تھا وہ اچھا ہو گیا صرف درہم کے برابر باقی ہے۔ اس کی ایک ماں ہے جس کے ساتھ وہ نیکی کرتا ہے۔ اگر وہ اللہ پر قسم کھا بیٹھے تو اللہ تعالیٰ اس کو سچا کرے۔ پھر اگر تجھ سے ہو سکے کہ وہ تیرے لئے دعا کرے تو اس سے دعا کرانا۔ وہ شخص یہ سن کر اویس کے پاس آیا اور کہنے لگا کہ میرے لئے دعا کرو۔ اویس نے کہا کہ تو ابھی نیک سفر کر کے آ رہا ہے (یعنی حج سے) میرے لئے دعا کر۔ پھر وہ شخص بولا کہ میرے لئے دعا کر۔ اویس نے یہی جواب دیا پھر پوچھا کہ تو سیدنا عمر رضی اللہ عنہ سے ملا؟ وہ شخص بولا کہ ہاں ملا۔ اویس نے اس کے لئے دعا کی۔ اس وقت لوگ اویس کا درجہ سمجھے۔ وہ وہاں سے سیدھے چلے۔ اسیر نے کہا کہ میں نے ان کو ان کا لباس ایک چادر پہنائی جب کوئی آدمی ان کو دیکھتا تو کہتا کہ اویس کے پاس یہ چادر کہاں سے آئی ہے؟(وہ ایسے تھے کہ ایک مناسب چادر بھی ان کے پاس ہونا باعث تعجب تھا۔)"}],[6536,"ابن وہب نے کہا : ہمیں حرملہ بن عمران تحبیی نے عبدالرحمٰن بن شماسہ مہری سے حدیث بیان کی ، انھوں نے کہا : میں نے سیدنا ابوذر رضی اللہ تعالیٰ عنہ سے سنا ، کہتے تھے : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا؛ \"\" تم عنقریب ایک زمین کو فتح کرو گےجس میں قیراط کا نام لیا جاتا ہوگا ( یہ ان کے چھوٹے سکے کا نام ہوگا ) تم اس سرزمین کے رہنے والوں کے ساتھ اچھا سلوک کرنے کی بات سن رکھو ، کیونکہ ان کا ( ہم پر ) حق بھی ہے اور رشتہ بھی ، پھر جب تم دو انسانوں کو ایک اینٹ کی جگہ کے لئے قتال پر آمادہ دیکھو تو وہاں سے چلے آنا ۔ \"\" ( حرملہ بن عمران نے ) کہا : تو ( عبدالرحمان بن شماسہ ) سیدنا شرجیل بن حسنہ رضی اللہ تعالیٰ عنہ کے دو بیٹوں ربیعہ اور عبدالرحمان کے قریب سے گزرے ، وہ ایک اینٹ کی جگہ پر جھگڑ رہے تھے تو وہ وہاں ( مصر ) سے نکل آئے ۔","",{"u2":"ابن وہب نے کہا:ہمیں حرملہ بن عمران تحبیی نے عبدالرحمٰن بن شماسہ مہری سے حدیث بیان کی،انھوں نے کہا:میں نے حضرت ابوذر رضی اللہ تعالیٰ عنہ سے سنا،کہتے تھے:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا؛\"تم عنقریب ایک زمین کو فتح کرو گےجس میں قیراط کا نام لیا جاتا ہوگا(یہ ان کے چھوٹے سکے کا نام ہوگا)تم اس سرزمین کے رہنے والوں کے ساتھ اچھا سلوک کرنے کی بات سن رکھو،کیونکہ ان کا(ہم پر) حق بھی ہے اور رشتہ بھی،پھر جب تم دو انسانوں کو ایک اینٹ کی جگہ کے لئے قتال پر آمادہ دیکھو تو وہاں سے چلے آنا۔\"\n(حرملہ بن عمران نے) کہا:تو(عبدالرحمان بن شماسہ) حضرت شرجیل بن حسنہ رضی اللہ تعالیٰ عنہ کے دو بیٹوں ربیعہ اور عبدالرحمان کے قریب سے گزرے،وہ ایک اینٹ کی جگہ پر جھگڑ رہے تھے تو وہ وہاں(مصر) سے نکل آئے۔"}],[6537,"حَدَّثَنِي زُهَيْرُ بْنُ حَرْبٍ ، وَعُبَيْدُ اللهِ بْنُ سَعِيدٍ ، قَالَا : حَدَّثَنَا وَهْبُ بْنُ جَرِيرٍ ، حَدَّثَنَا أَبِي ، سَمِعْتُ حَرْمَلَةَ الْمِصْرِيَّ ، يُحَدِّثُ عَنْ عَبْدِ الرَّحْمَنِ بْنِ شِمَاسَةَ ، عَنْ أَبِي بَصْرَةَ ، عَنْ أَبِي ذَرٍّ ، قَالَ : قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : «إِنَّكُمْ سَتَفْتَحُونَ مِصْرَ وَهِيَ أَرْضٌ يُسَمَّى فِيهَا الْقِيرَاطُ ، فَإِذَا فَتَحْتُمُوهَا فَأَحْسِنُوا إِلَى أَهْلِهَا ، فَإِنَّ لَهُمْ ذِمَّةً وَرَحِمًا» أَوْ قَالَ «ذِمَّةً وَصِهْرًا ، فَإِذَا رَأَيْتَ رَجُلَيْنِ يَخْتَصِمَانِ فِيهَا فِي مَوْضِعِ لَبِنَةٍ ، فَاخْرُجْ مِنْهَا» قَالَ : فَرَأَيْتُ عَبْدَ الرَّحْمَنِ بْنَ شُرَحْبِيلَ بْنِ حَسَنَةَ ، وَأَخَاهُ رَبِيعَةَ يَخْتَصِمَانِ فِي مَوْضِعِ لَبِنَةٍ فَخَرَجْتُ مِنْهَا","",{"u2":"حَدَّثَنِی زُہَیْرُ بْنُ حَرْبٍ، وَعُبَیْدُ اللہِ بْنُ سَعِیدٍ، قَالَا: حَدَّثَنَا وَہْبُ بْنُ جَرِیرٍ، حَدَّثَنَا أَبِی، سَمِعْتُ حَرْمَلَۃَ الْمِصْرِیَّ، یُحَدِّثُ عَنْ عَبْدِ الرَّحْمَنِ بْنِ شِمَاسَۃَ، عَنْ أَبِی بَصْرَۃَ، عَنْ أَبِی ذَرٍّ، قَالَ: قَالَ رَسُولُ اللہِ صَلَّی اللہُ عَلَیْہِ وَسَلَّمَ: «إِنَّکُمْ سَتَفْتَحُونَ مِصْرَ وَہِیَ أَرْضٌ یُسَمَّی فِیہَا الْقِیرَاطُ، فَإِذَا فَتَحْتُمُوہَا فَأَحْسِنُوا إِلَی أَہْلِہَا، فَإِنَّ لَہُمْ ذِمَّۃً وَرَحِمًا» أَوْ قَالَ «ذِمَّۃً وَصِہْرًا، فَإِذَا رَأَیْتَ رَجُلَیْنِ یَخْتَصِمَانِ فِیہَا فِی مَوْضِعِ لَبِنَۃٍ، فَاخْرُجْ مِنْہَا» قَالَ: فَرَأَیْتُ عَبْدَ الرَّحْمَنِ بْنَ شُرَحْبِیلَ بْنِ حَسَنَۃَ، وَأَخَاہُ رَبِیعَۃَ یَخْتَصِمَانِ فِی مَوْضِعِ لَبِنَۃٍ فَخَرَجْتُ مِنْہَا"}],[6538,"جابر بن عمرو راسبی نے کہا : میں نے سیدنا ابو برزہ رضی اللہ تعالیٰ عنہ کو یہ کہتے ہوئے سنا : رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص کو قبائل عرب میں سے ایک قبیلے کے پاس بھیجا تو ان لوگوں نے ان کو گالیاں دیں اور مارا ، وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور آپ کو خبر دی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اگر تم اہل عمان کے پاس جاتے تو وہ تمھیں گالیاں دیتے نہ مارتے ۔","",{"u2":"جابر بن عمرو راسبی نے کہا:میں نے حضرت ابو برزہ رضی اللہ تعالیٰ عنہ کو یہ کہتے ہوئے سنا:رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص کو قبائل عرب میں سے ایک قبیلے کے پاس بھیجا تو ان لوگوں نے ان کو گالیاں دیں اور مارا،وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور آپ کوخبر دی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"اگر تم اہل عمان کے پاس جاتے تو وہ تمھیں گالیاں دیتے نہ مارتے۔\""}],[6539,"ہمیں اسود بن شیبان نے ابو نوافل سے خبردی ، کہا : میں نے سیدنا عبداللہ بن زبیر رضی اللہ تعالیٰ عنہ ( کے جسد خاکی ) کو شہر کی گھاٹی میں ( کھجور کے ایک تنے سے لٹکا ہوا ) دیکھا ، کہا : تو قریش اور دوسرے لوگوں نے وہاں سے گزرنا شروع کردیا ، یہاں تک کہ سیدنا عبداللہ بن عمر رضی اللہ تعالیٰ عنہ وہاں سے گزرے تو وہ ان ( ابن زبیر رضی اللہ تعالیٰ عنہ ) کے پاس کھڑے ہوگئے ، اور ( انھیں مخاطب کرتے ہوئے ) کہا : ابو خبیب!آپ پر سلام! ابو خبیب!آپ پر سلام! ابو خبیب!آپ پر سلام!اللہ گواہ ہے کہ میں آپ کو اس سے روکتا تھا ، اللہ گواہ ہے کہ میں آپ کو اس سے روکتا تھا ، اللہ گواہ ہے کہ میں آپ کو اس سے روکتا تھا ، اللہ کی قسم!آپ ، جتنا مجھے علم ہے بہت روزے رکھنے والے ، بہت قیام کرنے والے ، بہت صلہ رحمی کرنے و الے تھے ۔ اللہ کی قسم!وہ امت جس میں آپ سب سے بُرے ( قرار دیے گئے ) ہوں ، وہ امت تو پوری کی پوری بہترین ہوگی ( جبکہ اس میں تو بڑے بڑے ظالم ، قاتل اور مجرم موجود ہیں ۔ آپ کسی طور پر اس سلوک کے مستحق نہ تھے ۔ ) پھر عبداللہ بن عمر رضی اللہ تعالیٰ عنہ وہاں سے چلے گئے ۔ حجاج کو عبداللہ بن عمر رضی اللہ تعالیٰ عنہ کے وہاں کھڑے ہونے کی خبر پہنچی تو اس نے کارندے بھیجے ، ان ( کے جسدخاکی ) کو کھجور کے تنے سے اتارا گیا اور انھیں جاہلی دور کی یہود کی قبروں میں پھینک دیا گیا ، پھر اس نے ( ابن زبیر رضی اللہ تعالیٰ عنہ کی والدہ ) سیدہ اسماء بنت ابی بکر رضی اللہ تعالیٰ عنہا کے پاس کارندہ بھیجا ۔ انھوں نے اس کے پاس جانے سے انکار کردیا ۔ اس نے دوبارہ قاصد بھیجا کہ یا تو تم میرے پاس آؤ گی یا پھر میں تمھارے پاس ان لوگوں کو بھیجو ں گا جو تمھیں تمھارے بالوں سے پکڑ کر گھسیٹتے ہوئے لے آئیں گے ۔ سیدہ اسماء رضی اللہ تعالیٰ عنہا نے پھر انکار کردیا اور فرمایا : میں ہرگز تیرے پاس نہ آؤں گی یہاں تک کہ تو میرے پاس ایسے شخص کو بھیجے جو مجھے میرے بالوں سے پکڑ کر گھسیٹتے ہوئے لےجائے ۔ کہا : تو حجاج کہنے لگا : مجھے میرے جوتے دکھاؤ ، اس نے جوتے پہنے اور اکڑتا ہوا تیزی سے چل پڑا ، یہاں تک کہ ان کے ہاں پہنچا اور کہا : تم نے مجھے دیکھا کہ میں نے اللہ کے دشمن کے ساتھ کیا کیا؟انھوں نے جواب دیا : میں نے تمھیں دیکھا ہے کہ تم نے اس پر اس کی دنیا تباہ کردی جبکہ اس نے تمھاری آخرت برباد کردی ، مجھے یہ بات پہنچی ہے کہ تو اسے دو پیٹیوں والی کا بیٹا ( ابن ذات النطاقین ) کہتا ہے ۔ ہاں ، اللہ کی قسم!میں دو پیٹیوں والی ہوں ۔ ایک پیٹی کے ساتھ میں رسول اللہ صلی اللہ علیہ وسلم اور ابو بکر رضی اللہ تعالیٰ عنہ کا کھانا سواری کے جانور پر باندھتی تھی اور دوسری پیٹی وہ ہے جس سے کوئی عورت مستغنی نہیں ہوسکتی ( سب کو لباس کے لیے اس کی ضرورت ہوتی ہے ۔ ) اور سنو!رسول اللہ صلی اللہ علیہ وسلم نے ہمیں بتایا تھا کہ بنو ثقیف میں ایک بہت بڑا کذاب ہوگا اور ایک بہت بڑا سفاک ہوگا ۔ کذاب ( مختار ثقفی ) کو تو ہم نے دیکھ لیا اور رہا سفاک تو میں نہیں سمجھتی کہ تیرے علاوہ کوئی اور ہوگا ، کہا : تو وہ وہاں سے اٹھ کھڑا ہوا اور انھیں کوئی جواب نہ دے سکا ۔","",{"u2":"ہمیں اسود بن شیبان نے ابو نوافل سے خبردی،کہا: میں نے حضرت عبداللہ بن زبیر رضی اللہ تعالیٰ عنہ (کے جسد خاکی) کو شہر کی گھاٹی میں (کھجور کے ایک تنے سے لٹکا ہوا) دیکھا،کہا:تو قریش اور دوسرے لوگوں نے وہاں سے گزرنا شروع کردیا،یہاں تک کہ حضرت عبداللہ بن عمر رضی اللہ تعالیٰ عنہ وہاں سے گزرے تو وہ ان (ابن زبیر رضی اللہ تعالیٰ عنہ) کے پاس کھڑے ہوگئے،اور (انھیں مخاطب کرتے ہوئے) کہا:ابو خبیب!آپ پر سلام! ابو خبیب!آپ پر سلام! ابو خبیب!آپ پر سلام!اللہ گواہ ہے کہ میں آپ کو اس سے روکتا تھا، اللہ گواہ ہے کہ میں آپ کو اس سے روکتا تھا، اللہ گواہ ہے کہ میں آپ کو اس سے روکتا تھا،اللہ کی قسم!آپ،جتنا مجھے علم ہے بہت روزے رکھنے والے،بہت قیام کرنے والے،بہت صلہ رحمی کرنے و الے تھے۔اللہ کی قسم!وہ امت جس میں آپ سب سے بُرے(قرار دیے گئے)ہوں،وہ امت تو پوری کی پوری بہترین ہوگی(جبکہ اس میں تو بڑے بڑے ظالم،قاتل اور مجرم موجود ہیں۔آپ کسی طور پر اس سلوک کے مستحق نہ تھے۔)\nپھر عبداللہ بن عمر رضی اللہ تعالیٰ عنہ وہاں سے چلے گئے۔حجاج کو عبداللہ بن عمر رضی اللہ تعالیٰ عنہ کے وہاں کھڑے ہونے کی خبر پہنچی تو اس نے کارندے بھیجے،ان(کے جسدخاکی) کو کھجور کے تنے سے اتارا گیا اور انھیں جاہلی دور کی یہود کی قبروں میں پھینک دیا گیا،پھر اس نے(ابن زبیر رضی اللہ تعالیٰ عنہ کی والدہ) حضرت اسماء بنت ابی بکر رضی اللہ تعالیٰ عنہا کے پاس کارندہ بھیجا۔انھوں نے اس کے پاس جانے سے انکار کردیا۔اس نے دوبارہ قاصد بھیجا کہ یا تو تم میرے پاس آؤ گی یا پھر میں تمھارے پاس ان لوگوں کو بھیجو ں گا جو تمھیں تمھارے بالوں سے پکڑ کر گھسیٹتے ہوئے لے آئیں گے۔حضرت اسماء رضی اللہ تعالیٰ عنہا نے پھر انکار کردیا اورفرمایا:میں ہرگز تیرے پاس نہ آؤں گی یہاں تک کہ تو میرے پاس ایسے شخص کو بھیجے جو مجھے میرے بالوں سے پکڑ کر گھسیٹتے ہوئے لےجائے۔کہا:توحجاج کہنے لگا:مجھے میرے جوتے دکھاؤ،اس نے جوتے پہنے اور اکڑتا ہوا تیزی سے چل پڑا،یہاں تک کہ ان کے ہاں پہنچا اور کہا:تم نے مجھے دیکھا کہ میں نے اللہ کے دشمن کے ساتھ کیا کیا؟انھوں نے جواب دیا:میں نے تمھیں دیکھا ہے کہ تم نے اس پر اس کی دنیا تباہ کردی جبکہ اس نے تمھاری آخرت برباد کردی،مجھے یہ بات پہنچی ہے کہ تو اسے دو پیٹیوں والی کا بیٹا(ابن ذات النطاقین) کہتا ہے۔\nہاں،اللہ کی قسم!میں دو پیٹیوں والی ہوں۔ایک پیٹی کے ساتھ میں رسول اللہ صلی اللہ علیہ وسلم اور ابو بکر رضی اللہ تعالیٰ عنہ کا کھانا سواری کے جانور پر باندھتی تھی اور دوسری پیٹی وہ ہے جس سے کوئی عورت مستغنی نہیں ہوسکتی(سب کو لباس کے لیے اس کی ضرورت ہوتی ہے۔)اور سنو!رسول اللہ صلی اللہ علیہ وسلم نے ہمیں بتایا تھا کہ بنو ثقیف میں ایک بہت بڑا کذاب ہوگا اور ایک بہت بڑا سفاک ہوگا۔کذاب(مختار ثقفی) کو تو ہم نے دیکھ لیا اور رہا سفاک تو میں نہیں سمجھتی کہ تیرے علاوہ کوئی اورہوگا،کہا:تو وہ وہاں سے اٹھ کھڑا ہوا اور انھیں کوئی جواب نہ دے سکا۔"}],[6540,"یزید بن اصم جزری نے سیدنا ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا؛ \" اگر دین ثریا پر ہوتا تب بھی فارس کا کوئی شخص ۔ ۔ ۔ یا آپ نے فرمایا ۔ ۔ ۔ فرزندان فارس میں سے کوئی شخص اس تک پہنچتا اور اسے حاصل کرلیتا ۔","",{"u2":"یزید بن اصم جزری نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی،کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا؛\"اگر دین ثریا پر ہوتا تب بھی فارس کا کوئی شخص۔۔۔یا آپ نے فرمایا۔۔۔فرزندان فارس میں سے کوئی شخص اس تک پہنچتا اور اسے حاصل کرلیتا۔\""}],[6541,"ابو غیث نے سیدنا ابو ہریر رضی اللہ تعالیٰ عنہ سے روایت کی ، کہا : جب نبی کریم صلی اللہ علیہ وسلم پر جمعہ نازل ہوئی اور آپ نے یہ پڑھا : ﴿ وَآخَرِينَ مِنْهُمْ لَمَّا يَلْحَقُوا﴾ \"\" ان میں اور بھی لوگ ہیں جو اب تک آکر ان سے نہیں ملے ہیں ۔ \"\" ( الجمعۃ 62 : 3 ) تو ایک نے عرض کی : اللہ کے رسول صلی اللہ علیہ وسلم !وہ کون لوگ ہیں؟نبی کریم صلی اللہ علیہ وسلم نے اس کا کوئی جواب نہ دیا ، حتی کہ اس نے آپ سے ایک یا دو یا تین بار سوال کیا ، کہا : اس وقت ہم میں سیدنا سلمان فارسی رضی اللہ تعالی عنہ بھی موجود تھے ، نبی کریم صلی اللہ علیہ وسلم نے سیدنا سلمان رضی اللہ تعالی عنہ پر ہاتھ رکھا ، پھر فرمایا؛ \"\" اگر ایمان ثریا کے قریب بھی ہوتا تو ان میں سے کچھ لوگ اس کو حاصل کرلیتے ۔","",{"u2":"ابو غیث نے حضرت ابو ہریر رضی اللہ تعالیٰ عنہ سے روایت کی،کہا:جب نبی کریم صلی اللہ علیہ وسلم پر جمعہ نازل ہوئی اور آپ نے یہ پڑھا:\n﴿ وَآخَرِینَ مِنْہُمْ لَمَّا یَلْحَقُوا﴾\"ان میں اور بھی لوگ ہیں جو اب تک آکر ان سے نہیں ملے ہیں۔\"(الجمعۃ 62:3)تو ایک نے عرض کی:اللہ کے رسول صلی اللہ علیہ وسلم!وہ کون لوگ ہیں؟نبی کریم صلی اللہ علیہ وسلم نے اس کا کوئی جواب نہ دیا،حتیٰ کہ اس نے آپ سے ایک یا دو یا تین بار سوال کیا،کہا:اس وقت ہم میں حضرت سلمان فارسی رضی اللہ تعالیٰ عنہ بھی موجود تھے،نبی کریم صلی اللہ علیہ وسلم نے حضرت سلمان رضی اللہ تعالیٰ عنہ پر ہاتھ رکھا،پھر فرمایا؛\" اگر ایمان ثریا کے قریب بھی ہوتا تو ان میں سے کچھ لوگ اس کو حاصل کرلیتے۔\""}],[6542,"سالم نے سیدنا ابن عمر رضی اللہ تعالی عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تم لوگوں کو ایسے سواونٹوں کی مثل پاؤ گے کہ آدمی ان میں سے ایک بھی سواری کے لائق نہیں پاتا ۔","",{"u2":"سالم نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے روایت کی،کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"تم لوگوں کو ایسے سواونٹوں کی مثل پاؤ گے کہ آدمی ان میں سے ایک بھی سواری کے لائق نہیں پاتا۔\""}],[6543,"قتیبہ بن سعید بن جمیل بن طریف ثقفی اور زہیر بن حرب نے کہا : ہمیں جریر نے عمارہ بن قعقاع سے حدیث بیان کی ، انہوں نے ابوزرعہ سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : ایک شخص رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور عرض کی : لوگوں میں سے حسنِ معاشرت ( خدمت اور حسن سلوک ) کا سب سے زیادہ حقدار کون ہے؟ آپ نے فرمایا : تمہاری ماں ۔ \"\" اس نے کہا : پھر کون؟ فرمایا : \"\" پھر تمہاری ماں ۔ \"\" اس نے پوچھا : اس کے بعد کون؟ فرمایا : \"\" پھر تمہاری ماں ۔ \"\" اس نے پوچھا : پھر کون؟ فرمایا : \"\" پھر تمہارا والد ۔ \"\" اور قتیبہ کی حدیث میں ہے : میرے اچھے برتاؤ کا زیادہ حقدار کون ہے؟ اور انہوں نے \"\" لوگوں میں سے \"\" کا ذکر نہیں کیا ۔","",{"u2":"قتیبہ بن سعید بن جمیل بن طریف ثقفی اور زہیر بن حرب نے کہا: ہمیں جریر نے عمارہ بن قعقاع سے حدیث بیان کی، انہوں نے ابوزرعہ سے، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: ایک شخص رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا اور عرض کی: لوگوں میں سے حسنِ معاشرت (خدمت اور حسن سلوک) کا سب سے زیادہ حقدار کون ہے؟ آپ نے فرمایا: تمہاری ماں۔\" اس نے کہا: پھر کون؟ فرمایا: \"پھر تمہاری ماں۔\" اس نے پوچھا: اس کے بعد کون؟ فرمایا: \"پھر تمہاری ماں۔\" اس نے پوچھا: پھر کون؟ فرمایا: \"پھر تمہارا والد۔\"\nاور قتیبہ کی حدیث میں ہے: میرے اچھے برتاؤ کا زیادہ حقدار کون ہے؟ اور انہوں نے \"لوگوں میں سے\" کا ذکر نہیں کیا۔"}],[6544,"فضیل نے عمارہ بن قعقاع سے ، انہوں نے ابوزرعہ سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : ایک شخص نے پوچھا : اللہ کے رسول! لوگوں میں سے ( میری طرف سے ) حسن معاشرت کا سب سے زیادہ حقدار کون ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا : \" تمہاری ماں ، پھر تمہاری ماں ، پھر تمہاری ماں ، پھر تمہارا باپ ، پھر جو تمہارا زیادہ قریبی ( رشتہ دار ) ہو ، ( پھر جو اس کے بعد ) تمہارا قریبی ہو ۔ \" ( اسی ترتیب سے آگے حق دار بنیں گے ۔)","",{"u2":"فضیل نے عمارہ بن قعقاع سے، انہوں نے ابوزرعہ سے، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: ایک شخص نے پوچھا: اللہ کے رسول! لوگوں میں سے (میری طرف سے) حسن معاشرت کا سب سے زیادہ حقدار کون ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"تمہاری ماں، پھر تمہاری ماں، پھر تمہاری ماں، پھر تمہارا باپ، پھر جو تمہارا زیادہ قریبی (رشتہ دار) ہو، (پھر جو اس کے بعد) تمہارا قریبی ہو۔\" (اسی ترتیب سے آگے حق دار بنیں گے۔)"}],[6545,"شریک نے عمارہ اور ابن شبرمہ سے حدیث بیان کی ، انہوں نے ابوزرعہ سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : نبی صلی اللہ علیہ وسلم کے پاس ایک شخص آیا ، اس کے بعد ( شریک نے ) جریر کی روایت کے مانند بیان کیا اور مزید کہا : پھر آپ صلی اللہ علیہ وسلم نے فرمایا : \" ہاں ، تمہارے باپ کی قسم! تمہیں ضرور بتایا جائے گا ۔","",{"u2":"شریک نے عمارہ اور ابن شبرمہ سے حدیث بیان کی، انہوں نے ابوزرعہ سے، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: نبی صلی اللہ علیہ وسلم کے پاس ایک شخص آیا، اس کے بعد (شریک نے) جریر کی روایت کے مانند بیان کیا اور مزید کہا: پھر آپ صلی اللہ علیہ وسلم نے فرمایا: \"ہاں، تمہارے باپ کی قسم! تمہیں ضرور بتایا جائے گا۔\""}],[6546,"محمد بن طلحہ اور وہیب دونوں نے ابن شبرمہ سے اسی سند کے ساتھ حدیث بیان کی ۔ وہیب کی حدیث میں ہے : میں کس کے ساتھ حسن سلوک کروں؟ اور محمد بن طلحہ کی حدیث میں ہے : لوگوں میں سے میری طرف سے حسن معاشرت کا سب سے زیادہ حقدار کون ہے؟ پھر جریر کی حدیث کے مانند بیان کیا ۔","",{"u2":"محمد بن طلحہ اور وہیب دونوں نے ابن شبرمہ سے اسی سند کے ساتھ حدیث بیان کی۔\nوہیب کی حدیث میں ہے: میں کس کے ساتھ حسن سلوک کروں؟ اور محمد بن طلحہ کی حدیث میں ہے: لوگوں میں سے میری طرف سے حسن معاشرت کا سب سے زیادہ حقدار کون ہے؟ پھر جریر کی حدیث کے مانند بیان کیا۔"}],[6547,"وکیع نے سفیان سے اور یحیی بن سعید قطان نے سفیان اور شعبہ دونوں سے روایت کی ، دونوں نے کہا : ہمیں حبیب نے ابوعباس سے حدیث سنائی ، انہوں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت کی ، کہا ایک شخص نبی صلی اللہ علیہ وسلم کے پاس جہاد کی اجازت طلب کرنے کے لیے آیا تو آپ نے فرمایا : \" کیا تمہارے والدین زندہ ہیں؟ \" اس نے کہا : جی ہاں ، آپ صلی اللہ علیہ وسلم نے کہا : جی ہاں ، آپ صلی اللہ علیہ وسلم نے فرمایا : \" پھر ان ( کی خدمت بجا لانے ) میں جہاد کرو ۔ ( اپنی جان اور مال کو ان کی خدمت میں صرف کرو ۔)","",{"u2":"وکیع نے سفیان سے اور یحییٰ بن سعید قطان نے سفیان اور شعبہ دونوں سے روایت کی، دونوں نے کہا: ہمیں حبیب نے ابوعباس سے حدیث سنائی، انہوں نے حضرت عبداللہ بن عمر رضی اللہ عنہ سے روایت کی، کہا ایک شخص نبی صلی اللہ علیہ وسلم کے پاس جہاد کی اجازت طلب کرنے کے لیے آیا تو آپ نے فرمایا: \"کیا تمہارے والدین زندہ ہیں؟\" اس نے کہا: جی ہاں، آپ صلی اللہ علیہ وسلم نے کہا: جی ہاں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"پھر ان (کی خدمت بجا لانے) میں جہاد کرو۔ (اپنی جان اور مال کو ان کی خدمت میں صرف کرو۔)\""}],[6548,"معاذ نے کہا : ہمیں شعبہ نے حبیب سے حدیث بیان کی ، انہوں نے کہا : میں نے ابوعباس سے سنا ، انہوں نے کہا : میں نے سیدنا عبداللہ بن عمرو بن عاص رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے ، ایک شخص نبی صلی اللہ علیہ وسلم کے پاس آیا ، پھر اسی ( سابقہ حدیث ) کے مانند بیان کیا ۔ امام مسلم نے کہا : ابوعباس کا نام سائب بن فروخ مکی ہے ۔","",{"u2":"معاذ نے کہا: ہمیں شعبہ نے حبیب سے حدیث بیان کی، انہوں نے کہا: میں نے ابوعباس سے سنا، انہوں نے کہا: میں نے حضرت عبداللہ بن عمرو بن عاص رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے، ایک شخص نبی صلی اللہ علیہ وسلم کے پاس آیا، پھر اسی (سابقہ حدیث) کے مانند بیان کیا۔\nامام مسلم نے کہا: ابوعباس کا نام سائب بن فروخ مکی ہے۔"}],[6549,"معاذ نے کہا : ہمیں شعبہ نے حبیب سے حدیث بیان کی ، انہوں نے کہا : میں نے ابوعباس سے سنا ، انہوں نے کہا : میں نے سیدنا عبداللہ بن عمرو بن عاص رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے ، ایک شخص نبی صلی اللہ علیہ وسلم کے پاس آیا ، پھر اسی ( سابقہ حدیث ) کے مانند بیان کیا ۔ امام مسلم نے کہا : ابوعباس کا نام سائب بن فروخ مکی ہے ۔","",{"u2":"ابن بشر نے مسعر سے، ابواسحاق اور زائدہ دونوں نے اعمش سے، سب نے حبیب سے اسی سند کے ساتھ اسی کے مانند روایت کی۔"}],[6550,"سیدنا عبداللہ بن عمرو رضی اللہ عنہ نے بیان کیا کہ ایک شخص نے نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہو کر عرض کی : میں آپ سے ہجرت اور جہاد پر بیعت کرتا ہوں اور اللہ تعالی سے اس کا اجر طلب کرتا ہوں ، آپ نے فرمایا : \" کیا تمہارے والدین میں سے کوئی ایک زندہ ہے؟ \" اس نے کہا : جی ہاں ، بلکہ دونوں زندہ ہیں ۔ آپ نے فرمایا : \" تم اللہ سے اجر کے طالب ہو؟ \" اس نے کہا : جی ہاں ۔ آپ نے فرمایا : \" اپنے والدین کے پاس جاؤ اور اچھے برتاؤ سے ان کے ساتھ رہو ۔","",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہ نے بیان کیا کہ ایک شخص نے نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہو کر عرض کی: میں آپ سے ہجرت اور جہاد پر بیعت کرتا ہوں اور اللہ تعالیٰ سے اس کا اجر طلب کرتا ہوں، آپ نے فرمایا: \"کیا تمہارے والدین میں سے کوئی ایک زندہ ہے؟\" اس نے کہا: جی ہاں، بلکہ دونوں زندہ ہیں۔ آپ نے فرمایا: \"تم اللہ سے اجر کے طالب ہو؟\" اس نے کہا: جی ہاں۔ آپ نے فرمایا: \"اپنے والدین کے پاس جاؤ اور اچھے برتاؤ سے ان کے ساتھ رہو۔\""}],[6551,"سلیمان بن مغیرہ نے کہا : ہمیں حمید بن ہلال نے ابورافع سے حدیث بیان کی ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : جریج نوکیلی چھت والی چھوٹی سی عبادت گاہ میں عبادت کر رہا تھا کہ اس کی ماں آئی ۔ حمید نے کہا : ابو رافع نے ہمیں ابوہریرہ رضی اللہ عنہ کی طرح واضح کر کے دکھایا جس طرح رسول اللہ صلی اللہ علیہ وسلم نے ان کے سامنے واضح کیا تھا کہ جب اس کی ماں نے اسے بلایا تو اس نے کس طرح اپنا ہاتھ اپنے ابروؤں پر رکھا تھا اور پھر اسے بلانے کے لیے اپنا سر اوپر کی طرف کیا تھا تو آواز دی : جریج! میں تیری ماں ہوں ، میرے ساتھ بات کر ۔ ماں نے عین اسی وقت ان ( جریج ) کو بلایا تھا جب وہ نماز پڑھ رہے تھے ۔ تو اس نے کہا : میرے اللہ! ( ایک طرف ) میری ماں ہے اور ( دوسری طرف ) میری نماز ہے؟ تو اس نے اپنی نماز کو ترجیح دی ۔ وہ واپس چلی گئیں ، پھر دوسری بار آئیں اور بلایا : جریج! میں تیری ماں ہوں ، میرے ساتھ بات کرو ۔ اس نے کہا : اے اللہ! میری ماں اور میری نماز ہے ، انہوں نے نماز کو ترجیح دی ، تو ماں نے دعا کی : اے اللہ! یہ جریج ہے ، یہ میرا بیٹا ہے ، میں نے اس سے بات کی ہے ، اس نے میرے ساتھ بات کرنے سے انکار کر دیا ہے ۔ یا اللہ! تو اسے بدکار عورتوں کا منہ دکھانے سے پہلے موت نہ دینا ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" اگر وہ اس کو یہ بددعا دیتیں کہ وہ فتنے میں مبتلا ہو جائے تو وہ ہو جاتا ۔ فرمایا : بھیڑوں کا ایک چرواہا ( بھی ) اس کی عبادت گاہ کی پناہ لیا کرتا تھا ( اس کے سائے میں آ بیٹھتا تھا ۔ ) فرمایا : بستی سے ایک عورت نکلی ، چرواہے نے اس کے ساتھ بدکاری کی ، وہ حاملہ ہو گئی اور ایک بیٹے کو جنم دیا ۔ اس عورت سے پوچھا گیا : یہ کیا ہے؟ اس نے کہا : یہ اس عبادت گاہ والے شخص سے ( ہوا ) ہے ۔ کہا : تو وہ ( بستی والے ) لوگ اپنے پھاؤڑے اور کدال لے کر آ گئے ، انہوں نے جریج کو بلایا ، انہوں نے اسی وقت ان کو بلایا تھا جب وہ نماز پڑھ رہے تھے ، اس لیے انہوں نے ان لوگوں سے یہ بات نہ کی ۔ لوگوں نے ان کی عبادت گاہ گرانی شروع کر دی ، جب انہوں نے یہ دیکھا تو اتر کر ان کی طرف آئے ۔ لوگوں نے ان سے کہا : اس عورت سے پوچھو ( کیا معاملہ ہے ) ، فرمایا : تو وہ مسکرائے ، بچے کے سر پر ہاتھ پھیرا ، پھر پوچھا : تمہارا باپ کون ہے؟ اس نے کہا : میرا باپ بھیڑوں کا چرواہا ہے ۔ جب انہوں نے اس ( شیر خوار ) سے یہ سنا تو کہنے لگے : ہم نے آپ کی عبادت گاہ کا جو حصہ گرایا ہے اسے سونے اور چاندی سے ( دوبارہ ) بنا دیتے ہیں ۔ انہوں نے کہا؛ نہیں ، لیکن اسی طرح مٹی سے بنا دو جس طرح پہلے تھی ، پھر وہ اس کے اوپر ( عبادت گاہ میں ) چلے گئے ۔","",{"u2":"سلیمان بن مغیرہ نے کہا: ہمیں حمید بن ہلال نے ابورافع سے حدیث بیان کی، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: جریج نوکیلی چھت والی چھوٹی سی عبادت گاہ میں عبادت کر رہا تھا کہ اس کی ماں آئی۔\nحمید نے کہا: ابو رافع نے ہمیں ابوہریرہ رضی اللہ عنہ کی طرح واضح کر کے دکھایا جس طرح رسول اللہ صلی اللہ علیہ وسلم نے ان کے سامنے واضح کیا تھا کہ جب اس کی ماں نے اسے بلایا تو اس نے کس طرح اپنا ہاتھ اپنے ابروؤں پر رکھا تھا اور پھر اسے بلانے کے لیے اپنا سر اوپر کی طرف کیا تھا تو آواز دی: جریج! میں تیری ماں ہوں، میرے ساتھ بات کر۔ ماں نے عین اسی وقت ان (جریج) کو بلایا تھا جب وہ نماز پڑھ رہے تھے۔ تو اس نے کہا: میرے اللہ! (ایک طرف) میری ماں ہے اور (دوسری طرف) میری نماز ہے؟ تو اس نے اپنی نماز کو ترجیح دی۔ وہ واپس چلی گئیں، پھر دوسری بار آئیں اور بلایا: جریج! میں تیری ماں ہوں، میرے ساتھ بات کرو۔ اس نے کہا: اے اللہ! میری ماں اور میری نماز ہے، انہوں نے نماز کو ترجیح دی، تو ماں نے دعا کی: اے اللہ! یہ جریج ہے، یہ میرا بیٹا ہے، میں نے اس سے بات کی ہے، اس نے میرے ساتھ بات کرنے سے انکار کر دیا ہے۔ یا اللہ! تو اسے بدکار عورتوں کا منہ دکھانے سے پہلے موت نہ دینا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر وہ اس کو یہ بددعا دیتیں کہ وہ فتنے میں مبتلا ہو جائے تو وہ ہو جاتا۔\nفرمایا: بھیڑوں کا ایک چرواہا (بھی) اس کی عبادت گاہ کی پناہ لیا کرتا تھا (اس کے سائے میں آ بیٹھتا تھا۔) فرمایا: بستی سے ایک عورت نکلی، چرواہے نے اس کے ساتھ بدکاری کی، وہ حاملہ ہو گئی اور ایک بیٹے کو جنم دیا۔ اس عورت سے پوچھا گیا: یہ کیا ہے؟ اس نے کہا: یہ اس عبادت گاہ والے شخص سے (ہوا) ہے۔ کہا: تو وہ (بستی والے) لوگ اپنے پھاؤڑے اور کدال لے کر آ گئے، انہوں نے جریج کو بلایا، انہوں نے اسی وقت ان کو بلایا تھا جب وہ نماز پڑھ رہے تھے، اس لیے انہوں نے ان لوگوں سے یہ بات نہ کی۔ لوگوں نے ان کی عبادت گاہ گرانی شروع کر دی، جب انہوں نے یہ دیکھا تو اتر کر ان کی طرف آئے۔ لوگوں نے ان سے کہا: اس عورت سے پوچھو (کیا معاملہ ہے)، فرمایا: تو وہ مسکرائے، بچے کے سر پر ہاتھ پھیرا، پھر پوچھا: تمہارا باپ کون ہے؟ اس نے کہا: میرا باپ بھیڑوں کا چرواہا ہے۔ جب انہوں نے اس (شیر خوار) سے یہ سنا تو کہنے لگے: ہم نے آپ کی عبادت گاہ کا جو حصہ گرایا ہے اسے سونے اور چاندی سے (دوبارہ) بنا دیتے ہیں۔ انہوں نے کہا؛ نہیں، لیکن اسی طرح مٹی سے بنا دو جس طرح پہلے تھی، پھر وہ اس کے اوپر (عبادت گاہ میں) چلے گئے۔"}],[6552,"محمد بن سیرین نے سیدنا ابوہریرہ رضی اللہ عنہ سے ، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فرمایا : \"\" صرف تین بچوں کے سوا پنگھوڑے میں کسی نے بات نہیں کی : حضرت عیسی بن مریم اور جریج ( کی گواہی دینے ) والے نے ۔ جریج ایک عبادت گزار آدمی تھی ۔ انہوں نے نوکیلی چھت والی ایک عبادت گاہ بنا لی ۔ وہ اس کے اندر تھے کہ ان کی والدہ آئی اور وہ نماز پڑھ رہے تھے ۔ تو اس نے پکار کر کہا : جریج! انہوں نے کہا : میرے رب! ( ایک طرف ) میری ماں ہے اور ( دوسری طرف ) میری نماز ہے ، پھر وہ اپنی نماز کی طرف متوجہ ہو گئے اور وہ چلی گئی ۔ جب دوسرا دن ہوا تو وہ آئی ، وہ نماز پڑھ رہے تھے ۔ اس نے بلایا : او جریج! تو جریج نے کہا : میرے پروردگار! میری ماں ہے اور میری نماز ہے ۔ انہوں نے نماز کی طرف توجہ کر لی ۔ وہ چلی گئی ، پھر جب اگلا دن ہوا تو وہ آئی اور آواز دی : جریج! انہوں نے کہا : میرے پروردگار! میری ماں ہے اور میری نماز ہے ، پھر وہ اپنی نماز میں لگ گئے ، تو اس نے کہا : اے اللہ! بدکار عورتوں کا منہ دیکھنے سے پہلے اسے موت نہ دینا ۔ بنی اسرائیل آپس میں جریج اور ان کی عبادت گزاری کا چرچا کرنے لگے ۔ وہاں ایک بدکار عورت تھی جس کے حسن کی مثال دی جاتی تھی ، وہ کہنے لگی : اگر تم چاہو تو میں تمہاری خاطر اسے فتنے میں ڈال سکتی ہوں ، کہا : تو اس عورت نے اپنے آپ کو اس کے سامنے پیش کیا ، لیکن وہ اس کی طرف متوجہ نہ ہوئے ۔ وہ ایک چرواہے کے پاس گئی جو ( دھوپ اور بارش مین ) ان کی عبادت گاہ کی پناہ لیا کرتا تھا ۔ اس عورت نے چرواہے کو اپنا آپ پیش کیا تو اس نے عورت کے ساتھ بدکاری کی اور اسے حمل ہو گیا ۔ جب اس نے بچے کو جنم دیا تو کہا : یہ جریج سے ہے ۔ لوگ ان کے پاس آئے ، انہیں ( عبادت گاہ سے ) نیچے آنے کا کہا ، ان کی عبادت گاہ ڈھا دی اور انہیں مار کا شروع کر دیا ۔ انہوں نے کہا : تم لوگوں کو کیا ہوا ہے؟ لوگوں نے کہا : تم نے اس بدکار عورت سے زنا کیا ہے اور اس نے تمہارے بچے کو جنم دیا ہے ۔ انہوں نے کہا : بچہ کہاں ہے؟ وہ اسے لے آئے ۔ انہوں نے کہا : مجھے نماز پڑھ لینے دو ، پھر انہوں نے نماز پڑھی ، جب نماز سے فارغ ہوئے تو بچے کے پاس آئے ، اس کے پیٹ میں انگلی چبھوئی اور کہا : بچے! تمہارا باپ کون ہے ۔ اس نے جواب دیا ۔ فلاں چرواہا ۔ آپ نے فرمایا : پھر وہ لوگ جریج کی طرف لپکے ، انہیں چومتے تھے اور برکت حاصل کرنے کے لیے ان کو ہاتھ لگاتے تھے اور انہوں نے کہا : ہم آپ کی عبادت گاہ سونے ( چاندی ) کی بنا دیتے ہیں ، انہوں نے کہا : نہیں ، اسے مٹی سے دوبارہ اسی طرح بنا دو جیسی وہ تھی تو انہوں نے ( ویسے ہی ) کیا ۔ اور ایک بچہ اپنی ماں کا دودھ پی رہا تھا ۔ وہاں سے ایک آدمی عمدہ سواری پر سوار خوبصورت لباس پہنے ہوئے گزرا تو اس بچے کی ماں نے کہا : اے اللہ! میرے بیٹے کو ایسا بنا دے ۔ بچے نے پستان ( دودھ ) چھوڑا ، اس آدمی کی طرف رخ کیا ، اسے دیکھا اور کہا؛ اے اللہ! مجھے اس جیسا نہ بنانا ، پھر اپنے پستان ( دودھ ) کا رخ کیا اور دودھ پینے میں لگ گیا ۔ \"\" ( ابوہریرہ رضی اللہ عنہ نے ) کہا : جیسے میں ( اب بھی ) رسول اللہ صلی اللہ علیہ وسلم کو دیکھ رہا ہوں کہ آپ صلی اللہ علیہ وسلم اپنی شہادت کی انگلی اپنے منہ میں ڈال کر اس کو چوستے ہوئے اس بچے کا دودھ پینا بیان کر رہے ہیں ۔ آپ نے فرمایا : \"\" پھر لوگ ایک لونڈی کو لے کر گزرے ۔ وہ اسے مار رہے تھے اور کہہ رہے تھے : تو نے زنا کیا ، تو نے چوری کی اور وہ کہہ رہی تھی : مجھے اللہ کافی ہے ، وہی بہترین کارساز ہے ۔ اس بچے کی ماں کہنے لگی : اے اللہ! میرے بیٹے کو اس کی طرح نہ بنانا ۔ بچے نے دودھ چھوڑا ، اس باندی کی طرف دیکھا اور کہا : اے اللہ! مجھے اسی جیسا بنانا ۔ یہاں آ کر ان دونوں ( ماں بیٹے ) نے ایک دوسرے سے سوال جواب کیا ۔ وہ کہنے لگی : میرا سر منڈے! بہت اچھی ہئیت کا ایک آدمی گزرا ، میں نے کہا : اے اللہ! میرے بیٹے کو اس جیسا بنانا تو تم نے کہا : اے اللہ! مجھے اس جیسا نہ بنانا ۔ پھر لوگ اس کنیز کو لے کر گزرے ، اسے مار رہے تھے اور کہہ رہے تھے : تو نے زنا کیا ہے ، تو نے چوری کی ہے ۔ میں نے کہا : اے اللہ! میرے بیٹے کو اس جیسا نہ بنانا تو تم نے یہ کہہ دیا : اے اللہ! مجھے اس جیسا بنانا ۔ اس ( بچے ) نے کہا : وہ شخص دوسروں پر ظلم ڈھانے والا جابر تھا ، اس لیے میں نے کہا : اے اللہ! مجھے اس کی طرح نہ بنانا ۔ اور یہ عورت جسے لوگ کہہ رہے تھے : تو نے زنا کیا ، حالانکہ اس نے زنا نہیں کیا تھا اور تو نے چوری کی حالانکہ اس نے چوری نہیں کی تھی ، اس لیے میں نے کہا : اے اللہ! مجھے اس کی طرح ( پاکباز ) بنانا ۔ \"\" فائدہ : حقیقی اور دائمی عزت والا وہی ہے جو اپنے پروردگار کی نافرمانی سے بچا ہوا ہے ، چاہے لوگ اسے حقیر اور گناہ گار سمجھتے ہوں اور حقیقت میں دائمی طور پر رذیل وہی ہے جو اللہ کا نافرمان ہے ، چاہے عارضی زندگی میں لوگ اسے معزز سمجھتے ہوں ۔","",{"u2":"محمد بن سیرین نے حضرت ابوہریرہ رضی اللہ عنہ سے، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی، آپ نے فرمایا: \"صرف تین بچوں کے سوا پنگھوڑے میں کسی نے بات نہیں کی: حضرت عیسیٰ بن مریم اور جریج (کی گواہی دینے) والے نے۔ جریج ایک عبادت گزار آدمی تھی۔ انہوں نے نوکیلی چھت والی ایک عبادت گاہ بنا لی۔ وہ اس کے اندر تھے کہ ان کی والدہ آئی اور وہ نماز پڑھ رہے تھے۔ تو اس نے پکار کر کہا: جریج! انہوں نے کہا: میرے رب! (ایک طرف) میری ماں ہے اور (دوسری طرف) میری نماز ہے، پھر وہ اپنی نماز کی طرف متوجہ ہو گئے اور وہ چلی گئی۔ جب دوسرا دن ہوا تو وہ آئی، وہ نماز پڑھ رہے تھے۔ اس نے بلایا: او جریج! تو جریج نے کہا: میرے پروردگار! میری ماں ہے اور میری نماز ہے۔ انہوں نے نماز کی طرف توجہ کر لی۔ وہ چلی گئی، پھر جب اگلا دن ہوا تو وہ آئی اور آواز دی: جریج! انہوں نے کہا: میرے پروردگار! میری ماں ہے اور میری نماز ہے، پھر وہ اپنی نماز میں لگ گئے، تو اس نے کہا: اے اللہ! بدکار عورتوں کا منہ دیکھنے سے پہلے اسے موت نہ دینا۔ بنی اسرائیل آپس میں جریج اور ان کی عبادت گزاری کا چرچا کرنے لگے۔ وہاں ایک بدکار عورت تھی جس کے حسن کی مثال دی جاتی تھی، وہ کہنے لگی: اگر تم چاہو تو میں تمہاری خاطر اسے فتنے میں ڈال سکتی ہوں، کہا: تو اس عورت نے اپنے آپ کو اس کے سامنے پیش کیا، لیکن وہ اس کی طرف متوجہ نہ ہوئے۔ وہ ایک چرواہے کے پاس گئی جو (دھوپ اور بارش مین) ان کی عبادت گاہ کی پناہ لیا کرتا تھا۔ اس عورت نے چرواہے کو اپنا آپ پیش کیا تو اس نے عورت کے ساتھ بدکاری کی اور اسے حمل ہو گیا۔ جب اس نے بچے کو جنم دیا تو کہا: یہ جریج سے ہے۔ لوگ ان کے پاس آئے، انہیں (عبادت گاہ سے) نیچے آنے کا کہا، ان کی عبادت گاہ ڈھا دی اور انہیں مارکا شروع کر دیا۔ انہوں نے کہا: تم لوگوں کو کیا ہوا ہے؟ لوگوں نے کہا: تم نے اس بدکار عورت سے زنا کیا ہے اور اس نے تمہارے بچے کو جنم دیا ہے۔ انہوں نے کہا: بچہ کہاں ہے؟ وہ اسے لے آئے۔ انہوں نے کہا: مجھے نماز پڑھ لینے دو، پھر انہوں نے نماز پڑھی، جب نماز سے فارغ ہوئے تو بچے کے پاس آئے، اس کے پیٹ میں انگلی چبھوئی اور کہا: بچے! تمہارا باپ کون ہے۔ اس نے جواب دیا۔ فلاں چرواہا۔ آپ نے فرمایا: پھر وہ لوگ جریج کی طرف لپکے، انہیں چومتے تھے اور برکت حاصل کرنے کے لیے ان کو ہاتھ لگاتے تھے اور انہوں نے کہا: ہم آپ کی عبادت گاہ سونے (چاندی) کی بنا دیتے ہیں، انہوں نے کہا: نہیں، اسے مٹی سے دوبارہ اسی طرح بنا دو جیسی وہ تھی تو انہوں نے (ویسے ہی) کیا۔\nاور ایک بچہ اپنی ماں کا دودھ پی رہا تھا۔ وہاں سے ایک آدمی عمدہ سواری پر سوار خوبصورت لباس پہنے ہوئے گزرا تو اس بچے کی ماں نے کہا: اے اللہ! میرے بیٹے کو ایسا بنا دے۔ بچے نے پستان (دودھ) چھوڑا، اس آدمی کی طرف رخ کیا، اسے دیکھا اور کہا؛ اے اللہ! مجھے اس جیسا نہ بنانا، پھر اپنے پستان (دودھ) کا رخ کیا اور دودھ پینے میں لگ گیا۔\"\n(ابوہریرہ رضی اللہ عنہ نے) کہا: جیسے میں (اب بھی) رسول اللہ صلی اللہ علیہ وسلم کو دیکھ رہا ہوں کہ آپ صلی اللہ علیہ وسلم اپنی شہادت کی انگلی اپنے منہ میں ڈال کر اس کو چوستے ہوئے اس بچے کا دودھ پینا بیان کر رہے ہیں۔\nآپ نے فرمایا: \"پھر لوگ ایک لونڈی کو لے کر گزرے۔ وہ اسے مار رہے تھے اور کہہ رہے تھے: تو نے زنا کیا، تو نے چوری کی اور وہ کہہ رہی تھی: مجھے اللہ کافی ہے، وہی بہترین کارساز ہے۔ اس بچے کی ماں کہنے لگی: اے اللہ! میرے بیٹے کو اس کی طرح نہ بنانا۔ بچے نے دودھ چھوڑا، اس باندی کی طرف دیکھا اور کہا: اے اللہ! مجھے اسی جیسا بنانا۔ یہاں آ کر ان دونوں (ماں بیٹے) نے ایک دوسرے سے سوال جواب کیا۔ وہ کہنے لگی: میرا سر منڈے! بہت اچھی ہئیت کا ایک آدمی گزرا، میں نے کہا: اے اللہ! میرے بیٹے کو اس جیسا بنانا تو تم نے کہا: اے اللہ! مجھے اس جیسا نہ بنانا۔ پھر لوگ اس کنیز کو لے کر گزرے، اسے مار رہے تھے اور کہہ رہے تھے: تو نے زنا کیا ہے، تو نے چوری کی ہے۔ میں نے کہا: اے اللہ! میرے بیٹے کو اس جیسا نہ بنانا تو تم نے یہ کہہ دیا: اے اللہ! مجھے اس جیسا بنانا۔\nاس (بچے) نے کہا: وہ شخص دوسروں پر ظلم ڈھانے والا جابر تھا، اس لیے میں نے کہا: اے اللہ! مجھے اس کی طرح نہ بنانا۔ اور یہ عورت جسے لوگ کہہ رہے تھے: تو نے زنا کیا، حالانکہ اس نے زنا نہیں کیا تھا اور تو نے چوری کی حالانکہ اس نے چوری نہیں کی تھی، اس لیے میں نے کہا: اے اللہ! مجھے اس کی طرح (پاکباز) بنانا۔\"\nفائدہ: حقیقی اور دائمی عزت والا وہی ہے جو اپنے پروردگار کی نافرمانی سے بچا ہوا ہے، چاہے لوگ اسے حقیر اور گناہ گار سمجھتے ہوں اور حقیقت میں دائمی طور پر رذیل وہی ہے جو اللہ کا نافرمان ہے، چاہے عارضی زندگی میں لوگ اسے معزز سمجھتے ہوں۔"}],[6553,"ابو عوانہ نے سہیل سے ، انہوں نے اپنے والد ( ابوصالح ) سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے ، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" ( اس شخص کی ) ناک خاک آلود ہو گئی ، پھر ( اس کی ) ناک خاک آلود ہو گئی ۔ \" پوچھا گیا : اللہ کے رسول! وہ کون شخص ہے؟ فرمایا : \" جس نے اپنے ماں باپ یا ان میں سے کسی ایک کو یا دونوں کو بڑھاپے میں پایا تو ( ان کی خدمت کر کے ) جنت میں داخل نہ ہوا ۔","",{"u2":"ابو عوانہ نے سہیل سے، انہوں نے اپنے والد (ابوصالح) سے، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا: \"(اس شخص کی) ناک خاک آلود ہو گئی، پھر (اس کی) ناک خاک آلود ہو گئی۔\" پوچھا گیا: اللہ کے رسول! وہ کون شخص ہے؟ فرمایا: \"جس نے اپنے ماں باپ یا ان میں سے کسی ایک کو یا دونوں کو بڑھاپے میں پایا تو (ان کی خدمت کر کے) جنت میں داخل نہ ہوا۔\""}],[6554,"جریر نے سہیل سے ، انہوں نے اپنے والد ( ابوصالح ) سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : نبی صلی اللہ علیہ وسلم نے فرمایا : \" اس شخص کی ناک خاک آلود ہو گئی ، پھر اس کی ناک خاک آلود ہو گئی ، پھر اس کی ناک خاک آلود ہو گئی ۔ \" پوچھا گیا : اللہ کے رسول! وہ کون شخص ہے؟ فرمایا : \" جس کے ہوتے ہوئے اس کے ماں باپ ، ان میں سے کسی ایک کو یا دونوں کو بڑھاپے نے پایا ، پھر وہ ( ان کی خدمت کر کے ) جنت میں داخل نہ ہوا ۔","",{"u2":"جریر نے سہیل سے، انہوں نے اپنے والد (ابوصالح) سے، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: نبی صلی اللہ علیہ وسلم نے فرمایا: \"اس شخص کی ناک خاک آلود ہو گئی، پھر اس کی ناک خاک آلود ہو گئی، پھر اس کی ناک خاک آلود ہو گئی۔\" پوچھا گیا: اللہ کے رسول! وہ کون شخص ہے؟ فرمایا: \"جس کے ہوتے ہوئے اس کے ماں باپ، ان میں سے کسی ایک کو یا دونوں کو بڑھاپے نے پایا، پھر وہ (ان کی خدمت کر کے) جنت میں داخل نہ ہوا۔\""}],[6555,"سلیمان بن بلال نے کہا : مجھے سہیل نے اپنے والد ( ابوصالح ) سے حدیث بیان کی ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے تین بار فرمایا : \" اس شخص کی ناک خاک آلود ہو گئی ۔ \" پھر ( آگے ) اُسی ( سابقہ حدیث ) کے مانند بیان کیا ۔","",{"u2":"سلیمان بن بلال نے کہا: مجھے سہیل نے اپنے والد (ابوصالح) سے حدیث بیان کی، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے تین بار فرمایا: \"اس شخص کی ناک خاک آلود ہو گئی۔\" پھر (آگے) اُسی (سابقہ حدیث) کے مانند بیان کیا۔"}],[6556,"ولید بن ولید نے عبداللہ بن دینار سے ، انہوں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت کی کہ ان کو مکہ مکرمہ کے راستے میں ایک بدوی شخص ملا ، سیدنا عبداللہ رضی اللہ عنہ نے ان کو سلام کیا اور جس گدھے پر خود سوار ہوتے تھے اس پر اسے بھی سوار کر لیا اور اپنے سر پر جو عمامہ تھا وہ اتار کر اس کے حوالے کر دیا ۔ ابن دینار نے کہا : ہم نے ان سے عرض کی : اللہ تعالی آپ کو ہر نیکی کی توفیق عطا فرمائے! یہ بدو لوگ تھوڑے دیے پر راضی ہو جاتے ہیں ۔ تو سیدنا عبداللہ ( بن عمر ) رضی اللہ عنہ نے فرمایا : اس شخص کا والد سیدنا عمر بن خطاب رضی اللہ عنہ کا محبوب دوست تھا اور میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ فرما رہے تھے : \" والدین کے ساتھ بہترین سلون ان لوگوں کے ساتھ حسن سلوک ہے جن کے ساتھ اس کے والد کو محبت تھی ۔","",{"u2":"ولید بن ولید نے عبداللہ بن دینار سے، انہوں نے حضرت عبداللہ بن عمر رضی اللہ عنہ سے روایت کی کہ ان کو مکہ مکرمہ کے راستے میں ایک بدوی شخص ملا، حضرت عبداللہ رضی اللہ عنہ نے ان کو سلام کیا اور جس گدھے پر خود سوار ہوتے تھے اس پر اسے بھی سوار کر لیا اور اپنے سر پر جو عمامہ تھا وہ اتار کر اس کے حوالے کر دیا۔ ابن دینار نے کہا: ہم نے ان سے عرض کی: اللہ تعالیٰ آپ کو ہر نیکی کی توفیق عطا فرمائے! یہ بدو لوگ تھوڑے دیے پر راضی ہو جاتے ہیں۔ تو حضرت عبداللہ (بن عمر) رضی اللہ عنہ نے فرمایا: اس شخص کا والد حضرت عمر بن خطاب رضی اللہ عنہ کا محبوب دوست تھا اور میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ فرما رہے تھے: \"والدین کے ساتھ بہترین سلون ان لوگوں کے ساتھ حسن سلوک ہے جن کے ساتھ اس کے والد کو محبت تھی۔\""}],[6557,"حیوہ بن شریح نے ابن ہاد سے ، انہوں نے عبداللہ بن دینار سے ، انہوں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے فرمایا : \" اپنے والد کے ساتھ سب سے بڑا نیک سلوک یہ ہے کہ انسان اس شخص سے بھی بہت اچھا سلوک کرے جس کے ساتھ اس کے والد کا محبت کا رشتہ تھا ۔","",{"u2":"حیوہ بن شریح نے ابن ہاد سے، انہوں نے عبداللہ بن دینار سے، انہوں نے حضرت عبداللہ بن عمر رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے فرمایا: \"اپنے والد کے ساتھ سب سے بڑا نیک سلوک یہ ہے کہ انسان اس شخص سے بھی بہت اچھا سلوک کرے جس کے ساتھ اس کے والد کا محبت کا رشتہ تھا۔\""}],[6558,"ابراہیم بن سعد اور لیث بن سعد دونوں نے یزید بن عبداللہ بن اسامہ بن ہاد سے حدیث بیان کی ، انہوں نے عبداللہ بن دینار سے ، انہوں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ کے حوالے سے روایت کی کہ وہ مکہ مکرمہ کے لیے نکلتے تو جب اونٹ کی سواری سے تھک جاتے تو ان کا گدھا ( ساتھ ہوتا ) تھا جس پر وہ سہولت کے لیے سواری کرتے ۔ اور ایک عمامہ ( ہوتا ) تھا جو اپنے سر پر باندھتے تھے ۔ تو ایسا ہوا کہ ایک دن وہ اس گدھے پر سوار تھے کہ ایک بادیہ نشیں ان کے قریب سے گزرا ، انہوں نے اس سے کہا؛ تم فلاں بن فلاں کے بیٹے نہیں ہو! اس نے کہا : کیوں نہیں ( اسی کا بیٹا ہوں ) تو انہوں نے گدھا اس کو دے دیا اور کہا : اس پر سوار ہو جاؤ اور عمامہ ( بھی ) اسے دے کر کہا : اسے سر پر باندھ لو ۔ تو ان کے کسی ساتھی نے ان سے کہا : اللہ آپ کی مغفرت کرے! آپ نے اس بدو کو وہ گدھا بھی دے دیا جس پر آپ سہولت ( تکان اتارنے ) کے لیے سواری کرتے تھے اور عمامہ بھی دے دیا جو اپنے سر پر باندھتے تھے ۔ انہوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ فرما رہے تھے : \" والدین کے ساتھ بہترین سلوک میں سے یہ ( بھی ) ہے کہ جب اس کا والد رخصت ہو جائے تو اس کے ساتھ محبت کا رشتہ رکھنے والے آدمی کے ساتھ اچھا سلوک کرے ۔ \" اور اس کا والد ( میرے والد ) سیدنا عمر رضی اللہ عنہ کا دوست تھا ۔","",{"u2":"ابراہیم بن سعد اور لیث بن سعد دونوں نے یزید بن عبداللہ بن اسامہ بن ہاد سے حدیث بیان کی، انہوں نے عبداللہ بن دینار سے، انہوں نے حضرت عبداللہ بن عمر رضی اللہ عنہ کے حوالے سے روایت کی کہ وہ مکہ مکرمہ کے لیے نکلتے تو جب اونٹ کی سواری سے تھک جاتے تو ان کا گدھا (ساتھ ہوتا) تھا جس پر وہ سہولت کے لیے سواری کرتے۔ اور ایک عمامہ (ہوتا) تھا جو اپنے سر پر باندھتے تھے۔ تو ایسا ہوا کہ ایک دن وہ اس گدھے پر سوار تھے کہ ایک بادیہ نشیں ان کے قریب سے گزرا، انہوں نے اس سے کہا؛ تم فلاں بن فلاں کے بیٹے نہیں ہو! اس نے کہا: کیوں نہیں (اسی کا بیٹا ہوں) تو انہوں نے گدھا اس کو دے دیا اور کہا: اس پر سوار ہو جاؤ اور عمامہ (بھی) اسے دے کر کہا: اسے سر پر باندھ لو۔ تو ان کے کسی ساتھی نے ان سے کہا: اللہ آپ کی مغفرت کرے! آپ نے اس بدو کو وہ گدھا بھی دے دیا جس پر آپ سہولت (تکان اتارنے) کے لیے سواری کرتے تھے اور عمامہ بھی دے دیا جو اپنے سر پر باندھتے تھے۔ انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ فرما رہے تھے: \"والدین کے ساتھ بہترین سلوک میں سے یہ (بھی) ہے کہ جب اس کا والد رخصت ہو جائے تو اس کے ساتھ محبت کا رشتہ رکھنے والے آدمی کے ساتھ اچھا سلوک کرے۔\" اور اس کا والد (میرے والد) حضرت عمر رضی اللہ عنہ کا دوست تھا۔"}],[6559,"ابن مہدی نے ہمیں معاویہ بن صالح سے حدیث بیان کی ، انہوں نے عبدالرحمٰن بن جبیر بن نفیر سے ، انہوں نے اپنے والد سے ، انہوں نے نواس بن سمعان انصاری رضی اللہ عنہ سے روایت کی ، کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم سے نیکی اور گناہ کے بارے میں سوال کیا تو آپ نے فرمایا : \" نیکی اچھا خلق ہے ، اور گناہ وہ ہے جو تمہارے دل میں کھٹکے اور تم ناپسند کرو کہ لوگوں کو اس کا پتہ چلے ۔","",{"u2":"ابن مہدی نے ہمیں معاویہ بن صالح سے حدیث بیان کی، انہوں نے عبدالرحمٰن بن جبیر بن نفیر سے، انہوں نے اپنے والد سے، انہوں نے نواس بن سمعان انصاری رضی اللہ عنہ سے روایت کی، کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے نیکی اور گناہ کے بارے میں سوال کیا تو آپ نے فرمایا: \"نیکی اچھا خلق ہے، اور گناہ وہ ہے جو تمہارے دل میں کھٹکے اور تم ناپسند کرو کہ لوگوں کو اس کا پتہ چلے۔\""}],[6560,"عبداللہ بن وہب نے کہا : مجھے معاویہ بن صالح نے ( باقی ماندہ سابقہ سند کے ساتھ ) سیدنا نواس بن سمعان رضی اللہ عنہ سے روایت کی ، کہا : میں ایک سال تک رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مدینہ میں مقیم رہا ۔ مجھے سوالات کرنے کے سوا اور کوئی بات ہجرت کرنے سے نہیں روکتی تھی کیونکہ ہم میں سے جب کوئی ہجرت کر لیتا تھا تو رسول اللہ صلی اللہ علیہ وسلم سے کسی چیز کے بارے میں سوال نہیں کرتا تھا ۔ کہا : ( تو اسی دوران مین ) میں نے آپ سے نیکی اور گناہ کے بارے میں دریافت کیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" نیکی حسن خلق ( اچھی عادات ) کا نام ہے اور گناہ وہ ہے جو تمہارے دل میں کھٹکے اور تم ناپسند کرو کہ لوگوں کو اس کا پتہ چلے ۔","",{"u2":"عبداللہ بن وہب نے کہا: مجھے معاویہ بن صالح نے (باقی ماندہ سابقہ سند کے ساتھ) حضرت نواس بن سمعان رضی اللہ عنہ سے روایت کی، کہا: میں ایک سال تک رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مدینہ میں مقیم رہا۔ مجھے سوالات کرنے کے سوا اور کوئی بات ہجرت کرنے سے نہیں روکتی تھی کیونکہ ہم میں سے جب کوئی ہجرت کر لیتا تھا تو رسول اللہ صلی اللہ علیہ وسلم سے کسی چیز کے بارے میں سوال نہیں کرتا تھا۔ کہا: (تو اسی دوران مین) میں نے آپ سے نیکی اور گناہ کے بارے میں دریافت کیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"نیکی حسن خلق (اچھی عادات) کا نام ہے اور گناہ وہ ہے جو تمہارے دل میں کھٹکے اور تم ناپسند کرو کہ لوگوں کو اس کا پتہ چلے۔\""}],[6561,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" اللہ تعالی نے مخلوق کو پیدا فرمایا حتی کہ جب وہ ان سے فارغ ہو گیا تو رَحم نے کھڑے ہو کر کہا : یہ ( میرا کھڑا ہونا ) اس کا کھڑا ہونا ہے جو قطع رحمی سے پناہ کا طلب گار ہے ۔ اللہ تعالی نے فرمایا : ہاں ، ( اس مقصد کے لیے تمہارا کھڑا ہونا مجھے قبول ہے ) کیا تم اس پر راضی نہیں ہو کہ میں اسی سے تعلق رکھوں جو تمہارا تعلق جوڑ کر رکھے اور اس سے تعلق توڑ دوں جو تمہارا تعلق توڑ دے؟ \"\" رَحم نے کہا : کیوں نہیں! ( میں راضی ہوں ۔ ) تو اللہ تعالی نے فرمایا : تمہیں یہ عطا کر دیا گیا ۔ \"\" پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" اگر تم چاہو تو ( قرآن مجید کا یہ مقام ) پڑھ لو : \"\" تو کیا تم اس ( بات ) کے قریب ( ہو گئے ) ہو کہ اگر تم پیچھے ہٹو گے تو زمین میں فساد برپا کرو گے اور خون کے رشتے توڑ ڈالو گے ، ایسے ہی لوگ ہیں جن پر اللہ نے لعنت کی اور انہیں ( ہدایت کی آواز سننے سے ) بہرا کر دیا اور ان کی آنکھوں کو ( اللہ کی نشانیاں دیکھنے سے ) اندھا کر دیا ۔ کیا یہ لوگ قرآن پر غوروخوض نہیں کرتے یا ( پھر ) ان کے دلوں پر قفل لگ چکے ہیں ۔","",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ نے مخلوق کو پیدا فرمایا حتی کہ جب وہ ان سے فارغ ہو گیا تو رَحم نے کھڑے ہو کر کہا: یہ (میرا کھڑا ہونا) اس کا کھڑا ہونا ہے جو قطع رحمی سے پناہ کا طلب گار ہے۔ اللہ تعالیٰ نے فرمایا: ہاں، (اس مقصد کے لیے تمہارا کھڑا ہونا مجھے قبول ہے) کیا تم اس پر راضی نہیں ہو کہ میں اسی سے تعلق رکھوں جو تمہارا تعلق جوڑ کر رکھے اور اس سے تعلق توڑ دوں جو تمہارا تعلق توڑ دے؟\" رَحم نے کہا: کیوں نہیں! (میں راضی ہوں۔) تو اللہ تعالیٰ نے فرمایا: تمہیں یہ عطا کر دیا گیا۔\"\nپھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اگر تم چاہو تو (قرآن مجید کا یہ مقام) پڑھ لو: \"تو کیا تم اس (بات) کے قریب (ہو گئے) ہو کہ اگر تم پیچھے ہٹو گے تو زمین میں فساد برپا کرو گے اور خون کے رشتے توڑ ڈالو گے، ایسے ہی لوگ ہیں جن پر اللہ نے لعنت کی اور انہیں (ہدایت کی آواز سننے سے) بہرا کر دیا اور ان کی آنکھوں کو (اللہ کی نشانیاں دیکھنے سے) اندھا کر دیا۔ کیا یہ لوگ قرآن پر غوروخوض نہیں کرتے یا (پھر) ان کے دلوں پر قفل لگ چکے ہیں۔\""}],[6562,"سیدہ عائشہ رضی اللہ عنہ سے روایت ہے ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" رَحم ( خونی رشتوں کا سارا سلسلہ ) عرش کے ساتھ چمٹا ہوا ہے اور یہ کہتا ہے : جس نے میرے تعلق کو جوڑ کر رکھا اللہ اس کے ساتھ تعلق جوڑے گا اور جس نے میرے تعلق کو توڑ دیا اللہ تعالی اس سے تعلق توڑ لے گا ۔","",{"u2":"حضرت عائشہ رضی اللہ عنہ سے روایت ہے، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"رَحم (خونی رشتوں کا سارا سلسلہ) عرش کے ساتھ چمٹا ہوا ہے اور یہ کہتا ہے: جس نے میرے تعلق کو جوٹ کر رکھا اللہ اس کے ساتھ تعلق جوڑے گا اور جس نے میرے تعلق کو توڑ دیا اللہ تعالیٰ اس سے تعلق توڑ لے گا۔\""}],[6563,"زہیر بن حرب اور ابن ابی عمر نے کہا : ہمیں سفیان نے زہری سے حدیث بیان کی ، انہوں نے محمد بن جبیر بن معطم سے ، انہوں نے اپنے والد سے ، انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" قطع کرنے والا جنت میں داخل نہیں ہو گا ۔ \"\" ابن ابی عمر نے بتایا کہ سفیان نے کہا : یعنی قطع رحمی کرنے والا ۔","",{"u2":"زہیر بن حرب اور ابن ابی عمر نے کہا: ہمیں سفیان نے زہری سے حدیث بیان کی، انہوں نے محمد بن جبیر بن معطم سے، انہوں نے اپنے والد سے، انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"قطع کرنے والا جنت میں داخل نہیں ہو گا۔\"\nابن ابی عمر نے بتایا کہ سفیان نے کہا: یعنی قطع رحمی کرنے والا۔"}],[6564,"امام مالک نے زہری سے روایت کی ، محمد بن جبیر بن معطم نے خبر دی کہ ان کے والد نے انہیں بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : قطع رحمی کرنے والا جنت میں داخل نہیں ہو گا ۔","",{"u2":"امام مالک نے زہری سے روایت کی، محمد بن جبیر بن معطم نے خبر دی کہ ان کے والد نے انہیں بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: قطع رحمی کرنے والا جنت میں داخل نہیں ہو گا۔\""}],[6565,"معمر نے زہری سے اسی سند کے ساتھ اسی کے مانند روایت کی اور ( اس میں ہے : سیدنا جبیر بن معطم رضی اللہ عنہ نے ) کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ۔","",{"u2":"معمر نے زہری سے اسی سند کے ساتھ اسی کے مانند روایت کی اور (اس میں ہے: حضرت جبیر بن معطم رضی اللہ عنہ نے) کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا۔"}],[6566,"یونس نے ابن شہاب سے ، انہوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جو شخص یہ چاہتا ہو کہ اس پر اس کا رزق کشادہ کیا جائے یا اس کے چھوڑے ہوئے کو مؤخر کیا جائے ( خود اس کی اور اس کی چھوڑی ہوئی اشیاء ، اعمال اور اولاد کی عمر لمبی ہو ) وہ صلہ رحمی کرے ۔","",{"u2":"یونس نے ابن شہاب سے، انہوں نے حضرت انس بن مالک رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص یہ چاہتا ہو کہ اس پر اس کا رزق کشادہ کیا جائے یا اس کے چھوڑے ہوئے کو مؤخر کیا جائے (خود اس کی اور اس کی چھوڑی ہوئی اشیاء، اعمال اور اولاد کی عمر لمبی ہو) وہ صلہ رحمی کرے۔\""}],[6567,"عقیل بن خالد نے کہا : ابن شہاب نے کہا : مجھے سیدنا انس بن مالک رضی اللہ عنہ نے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جو شخص یہ چاہتا کہ اس کے لیے اس کے رزق میں کشادگی کی جائے اور جو اس نے چھوڑ جانا ہے اس کی مہلت لمبی کی جائے تو وہ صلہ رحمی کرے ۔","",{"u2":"عقیل بن خالد نے کہا: ابن شہاب نے کہا: مجھے حضرت انس بن مالک رضی اللہ عنہ نے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص یہ چاہتا کہ اس کے لیے اس کے رزق میں کشادگی کی جائے اور جو اس نے چھوڑ جانا ہے اس کی مہلت لمبی کی جائے تو وہ صلہ رحمی کرے۔\""}],[6568,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ ایک شخص نے عرض کی : اللہ کے رسول! میرے ( بعض ) رشتہ دار ہیں ، میں ان سے تعلق جوڑتا ہوں اور وہ مجھ سے تعلق توڑتے ہیں ، میں ان کے ساتھ نیکی کرتا ہوں اور وہ میرے ساتھ برائی کرتے ہیں ، میں بردباری کے ساتھ ان سے درگزر کرتا ہوں اور وہ میرے ساتھ جہالت کا سلوک کرتے ہیں ، آپ نے فرمایا : \" اگر تم ایسے ہی ہو جیسے تم نے کہا ہے تو تم ان کو جلتی راکھ کھلا رہے ہو اور جب تک تم اس روش پر رہو گے ، ان کے مقابلے میں اللہ کی طرف سے ہمیشہ ایک مددگار تمہارے ساتھ رہے گا ۔","",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ ایک شخص نے عرض کی: اللہ کے رسول! میرے (بعض) رشتہ دار ہیں، میں ان سے تعلق جوڑتا ہوں اور وہ مجھ سے تعلق توڑتے ہیں، میں ان کے ساتھ نیکی کرتا ہوں اور وہ میرے ساتھ برائی کرتے ہیں، میں بردباری کے ساتھ ان سے درگزر کرتا ہوں اور وہ میرے ساتھ جہالت کا سلوک کرتے ہیں، آپ نے فرمایا: \"اگر تم ایسے ہی ہو جیسے تم نے کہا ہے تو تم ان کو جلتی راکھ کھلا رہے ہو اور جب تک تم اس روش پر رہو گے، ان کے مقابلے میں اللہ کی طرف سے ہمیشہ ایک مددگار تمہارے ساتھ رہے گا۔\""}],[6569,"امام مالک نے ابن شہاب سے ، انہوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ایک دوسرے سے بغض نہ رکھو ، ایک دوسرے سے حسد نہ کرو ، ایک دوسرے سے روگردانی نہ کرو اور اللہ کے بندے ( ایک دوسرے کے ) بھائی بن کر رہو ۔ کسی مسلمان کے لیے حلال نہیں کہ تین دن سے زیادہ اپنے بھائی سے تعلق ترک کیے رکھے ۔","",{"u2":"امام مالک نے ابن شہاب سے، انہوں نے حضرت انس بن مالک رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک دوسرے سے بغض نہ رکھو، ایک دوسرے سے حسد نہ کرو، ایک دوسرے سے روگردانی نہ کرو اور اللہ کے بندے (ایک دوسرے کے) بھائی بن کر رہو۔ کسی مسلمان کے لیے حلال نہیں کہ تین دن سے زیادہ اپنے بھائی سے تعلق ترک کیے رکھے۔\""}],[6570,"ابوداؤد نے کہا : ہمیں شعبہ نے قتادہ سے حدیث بیان کی ، انہوں نے سیدنا انس رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے فرمایا : \" ایک دوسرے سے حسد نہ کرو ، ایک دوسرے سے بغض نہ رکھو ، ایک دوسرے سے قطع تعلق نہ کرو اور اللہ کے بندے ( ایک دوسرے کے ) بھائی بن کر رہو ۔"],[6571,"ابوداؤد نے کہا : ہمیں شعبہ نے قتادہ سے حدیث بیان کی ، انہوں نے سیدنا انس رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے فرمایا : \" ایک دوسرے سے حسد نہ کرو ، ایک دوسرے سے بغض نہ رکھو ، ایک دوسرے سے قطع تعلق نہ کرو اور اللہ کے بندے ( ایک دوسرے کے ) بھائی بن کر رہو ۔","",{"u2":"محمد بن ولید زبیدی اور یونس نے ابن شہاب سے روایت کی، انہوں نے انس رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے مالک کی حدیث کے مانند روایت کی۔"}],[6572,"وہب بن جریر نے کہا : ہمیں شعبہ نے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی اور مزید یہ کہا : \" جس طرح اللہ نے تمہیں حکم دیا ہے ۔","",{"u2":"ابن عیینہ نے زہری سے اسی سند کے ساتھ روایت کی، نیز ابن عیینہ نے مزید یہ کہا: \"اور ایک دوسرے سے قطع رحمی نہ کرو۔\""}],[6576,"امام مالک نے ابن شہاب سے ، انہوں نے عطاء بن یزید لیثی سے ، انہوں نے سیدنا ابو ایوب انصاری رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کسی مسلمان کے لیے حلال نہیں کہ وہ تین دن سے زیادہ اپنے بھائی کو چھوڑ دے ( قطع تعلق کر کے رکھے کہ ) دونوں ایک دوسرے سے ملیں تو یہ بھی منہ موڑ لے اور وہ بھی منہ موڑ لے اور دونوں میں سے بہتر وہ ہے جو سلام میں پہل کرے ۔","",{"u2":"امام مالک نے ابن شہاب سے، انہوں نے عطاء بن یزید لیثی سے، انہوں نے حضرت ابو ایوب انصاری رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کسی مسلمان کے لیے حلال نہیں کہ وہ تین دن سے زیادہ اپنے بھائی کو چھوڑ دے (قطع تعلق کر کے رکھے کہ) دونوں ایک دوسرے سے ملیں تو یہ بھی منہ موڑ لے اور وہ بھی منہ موڑ لے اور دونوں میں سے بہتر وہ ہے جو سلام میں پہل کرے۔\""}],[6577,"سفیان ، یونس ، ( محمد بن ولید ) زبیدی اور معمر سب نے زہری سے مالک کی سند کے ساتھ ، اس قول کے سوا \" یہ بھی منہ موڑ لے اور وہ بھی منہ موڑ لے \" انہی کی حدیث کے مانند روایت کی ، مگر مالک بن انس کے سوا سب نے اپنی حدیث میں یہ الفاظ کہے : \" یہ بھی اُس کی طرف نہ دیکھے ، وہ بھی اس کی طرف نہ دیکھے ۔","",{"u2":"سفیان، یونس، (محمد بن ولید) زبیدی اور معمر سب نے زہری سے مالک کی سند کے ساتھ، اس قول کے سوا \"یہ بھی منہ موڑ لے اور وہ بھی منہ موڑ لے\" انہی کی حدیث کے مانند روایت کی، مگر مالک بن انس کے سوا سب نے اپنی حدیث میں یہ الفاظ کہے: \"یہ بھی اُس کی طرف نہ دیکھے، وہ بھی اس کی طرف نہ دیکھے۔\""}],[6578,"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" مومن کے لیے حلال نہیں کہ تین دن سے زیادہ اپنے ( مسلمان ) بھائی سے تعلق ترک کرے ۔","",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مومن کے لیے حلال نہیں کہ تین دن سے زیادہ اپنے (مسلمان) بھائی سے تعلق ترک کرے۔\""}],[6579,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تین دن کے بعد ( بھی ) روٹھے رہنا جائز نہیں ہے ۔","",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تین دن کے بعد (بھی) روٹھے رہنا جائز نہیں ہے۔\""}],[6580,"اعرج نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" بدگمانی سے دور رہو کیونکہ بدگمانی سب سے زیادہ جھوٹی بات ہے ، دوسروں کے ظاہری عیب تلاش کرو نہ دوسروں کے باطنی عیب ڈھونڈو ، مال و دولت میں ایک دوسرے کے ساتھ مسابقت نہ کرو ، ایک دوسرے سے حسد نہ کرو ، آپس میں بغض نہ رکھو ، ایک دوسرے سے روگردانی نہ کرو ، اور اللہ کے ایسے بندے بن کر رہو جو آپس میں بھائی بھائی ہیں ۔","",{"u2":"اعرج نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بدگمانی سے دور رہو کیونکہ بدگمانی سب سے زیادہ جھوٹی بات ہے، دوسروں کے ظاہری عیب تلاش کرو نہ دوسروں کے باطنی عیب ڈھونڈو، مال و دولت میں ایک دوسرے کے ساتھ مسابقت نہ کرو، ایک دوسرے سے حسد نہ کرو، آپس میں بغض نہ رکھو، ایک دوسرے سے روگردانی نہ کرو، اور اللہ کے ایسے بندے بن کر رہو جو آپس میں بھائی بھائی ہیں۔\""}],[6581,"علاء کے والد ( عبدالرحمٰن ) نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ایک دوسرے سے ترکِ تعلق مت کرو ، ایک دوسرے سے روگردانی نہ کرو ، دوسروں کے عیب تلاش نہ کرو ، تم میں سے کوئی کسی کی بیع پر بیع نہ کرے اور اللہ کے ایسے بندے بن جاؤ جو آپس میں بھائی بھائی ہیں ۔","",{"u2":"علاء کے والد (عبدالرحمٰن) نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک دوسرے سے ترکِ تعلق مت کرو، ایک دوسرے سے روگردانی نہ کرو، دوسروں کے عیب تلاش نہ کرو، تم میں سے کوئی کسی کی بیع پر بیع نہ کرے اور اللہ کے ایسے بندے بن جاؤ جو آپس میں بھائی بھائی ہیں۔\""}],[6582,"جریر نے اعمش سے ، انہوں نے ابوصالح سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ایک دوسرے سے حسد نہ کرو ، ایک دوسرے سے بغض نہ رکھو ، دوسروں کے ظاہری عیب تلاش نہ کرو ، دوسروں کے باطنی عیب مت ڈھونڈو ، ایک دوسرے کے لیے دھوکے سے قیمتیں نہ بڑھاؤ ، اور اللہ کے ایسے بندے بن جاؤ جو آپس میں بھائی بھائی ہیں ۔","",{"u2":"جریر نے اعمش سے، انہوں نے ابوصالح سے، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک دوسرے سے حسد نہ کرو، ایک دوسرے سے بغض نہ رکھو، دوسروں کے ظاہری عیب تلاش نہ کرو، دوسروں کے باطنی عیب مت ڈھونڈو، ایک دوسرے کے لیے دھوکے سے قیمتیں نہ بڑھاؤ، اور اللہ کے ایسے بندے بن جاؤ جو آپس میں بھائی بھائی ہیں۔\""}],[6583,"شعبہ نے ہمیں اعمش سے اسی سند کے ساتھ روایت کی : \" ایک دوسرے سے قطع رحمی نہ کرو ، ایک دوسرے سے روگردانی نہ کرو ، ایک دوسرے سے بغض نہ رکھو ، ایک دوسرے سے حسد نہ کرو اور جس طرح اللہ تعالی نے تمہیں حکم دیا ہے اللہ کے ایسے بندے بن جاؤ جو آپس میں بھائی بھائی ہیں ۔","",{"u2":"شعبہ نے ہمیں اعمش سے اسی سند کے ساتھ روایت کی: \"ایک دوسرے سے قطع رحمی نہ کرو، ایک دوسرے سے روگردانی نہ کرو، ایک دوسرے سے بغض نہ رکھو، ایک دوسرے سے حسد نہ کرو اور جس طرح اللہ تعالیٰ نے تمہیں حکم دیا ہے اللہ کے ایسے بندے بن جاؤ جو آپس میں بھائی بھائی ہیں۔\""}],[6584,"سہیل نے اپنے والد ( ابوصالح ) سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" ایک دوسرے سے بغض نہ رکھو ، ایک دوسرے سے روگردانی نہ کرو ، دولت کا حصول اور نمائش میں ایک دوسرے سے مقابلہ نہ کرو اور اللہ کے ایسے بندے بن جاؤ جو آپس میں بھائی بھائی ہیں ۔","",{"u2":") سہیل نے اپنے والد (ابوصالح) سے، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ایک دوسرے سے بغض نہ رکھو، ایک دوسرے سے روگردانی نہ کرو، دولت کا حصول اور نمائش میں ایک دوسرے سے مقابلہ نہ کرو اور اللہ کے ایسے بندے بن جاؤ جو آپس میں بھائی بھائی ہیں۔\""}],[6585,"داؤد بن قیس نے ہمیں عامر بن کریز کے آزاد کردہ غلام ابوسعید سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ایک دوسرے سے حسد نہ کرو ، ایک دوسرے کے لیے دھوکے سے قیمتیں نہ بڑھاؤ ، ایک دوسرے سے بغض نہ رکھو ، ایک دوسرے سے منہ نہ پھیرو ، تم میں سے کوئی دوسرے کے سودے پر سودا نہ کرے اور اللہ کے بندے بن جاؤ جو آپس میں بھائی بھائی ہیں ۔ مسلمان ( دوسرے ) مسلمان کا بھائی ہے ، نہ اس پر ظلم کرتا ہے ، نہ اسے بے یارو مددگار چھوڑتا ہے اور نہ اس کی تحقیر کرتا ہے ۔ تقوی یہاں ہے ۔ \" اور آپ صلی اللہ علیہ وسلم نے اپنے سینے کی طرف تین بار اشارہ کیا ، ( پھر فرمایا ) : \" کسی آدمی کے برے ہونے کے لیے یہی کافی ہے کہ وہ اپنے مسلمان بھائی کی تحقیر کرے ، ہر مسلمان پر ( دوسرے ) مسلمان کا خون ، مال اور عزت حرام ہیں ۔","",{"u2":"داؤد بن قیس نے ہمیں عامر بن کریز کے آزاد کردہ غلام ابوسعید سے، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک دوسرے سے حسد نہ کرو، ایک دوسرے کے لیے دھوکے سے قیمتیں نہ بڑھاؤ، ایک دوسرے سے بغض نہ رکھو، ایک دوسرے سے منہ نہ پھیرو، تم میں سے کوئی دوسرے کے سودے پر سودا نہ کرے اور اللہ کے بندے بن جاؤ جو آپس میں بھائی بھائی ہیں۔ مسلمان (دوسرے) مسلمان کا بھائی ہے، نہ اس پر ظلم کرتا ہے، نہ اسے بے یارو مددگار چھوڑتا ہے اور نہ اس کی تحقیر کرتا ہے۔ تقویٰ یہاں ہے۔\" اور آپ صلی اللہ علیہ وسلم نے اپنے سینے کی طرف تین بار اشارہ کیا، (پھر فرمایا): \"کسی آدمی کے برے ہونے کے لیے یہی کافی ہے کہ وہ اپنے مسلمان بھائی کی تحقیر کرے، ہر مسلمان پر (دوسرے) مسلمان کا خون، مال اور عزت حرام ہیں۔\""}],[6586,"اسامہ بن زید سے روایت ہے کہ انہوں نے عبداللہ بن عامر بن کریز کے آزاد کردہ غلام ابوسعید کو یہ کہتے ہوئے سنا کہ میں نے سیدنا ابوہریرہ رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے فرمایاَ اس کے بعد داؤد کی حدیث کی طرح بیان کیا ، کچھ چیزیں زیادہ بیان کیں اور کچھ کم ، زائد بیان کردہ باتوں میں سے ایک یہ ہے : \" اللہ تعالی تمہارے جسموں کو دیکھتا ہے نہ تمہاری صورتوں کو لیکن وہ تمہارے دلوں کی طرف دیکھتا ہے ۔ \" اور آپ نے اپنی انگلیوں سے اپنے سینے کی طرف اشارہ کیا ۔","",{"u2":"اسامہ بن زید سے روایت ہے کہ انہوں نے عبداللہ بن عامر بن کریز کے آزاد کردہ غلام ابوسعید کو یہ کہتے ہوئے سنا کہ میں نے حضرت ابوہریرہ رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: رسول اللہ صلی اللہ علیہ وسلم نے فرمایاَ اس کے بعد داؤد کی حدیث کی طرح بیان کیا، کچھ چیزیں زیادہ بیان کیں اور کچھ کم، زائد بیان کردہ باتوں میں سے ایک یہ ہے: \"اللہ تعالیٰ تمہارے جسموں کو دیکھتا ہے نہ تمہاری صورتوں کو لیکن وہ تمہارے دلوں کی طرف دیکھتا ہے۔\" اور آپ نے اپنی انگلیوں سے اپنے سینے کی طرف اشارہ کیا۔"}],[6587,"یزید بن اصم نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ تعالی تمہاری صورتوں اور تمہارے اموال کی طرف نہیں دیکھتا ، لیکن وہ تمہارے دلوں اور اعمال کی طرف دیکھتا ہے ۔","",{"u2":"یزید بن اصم نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ تمہاری صورتوں اور تمہارے اموال کی طرف نہیں دیکھتا، لیکن وہ تمہارے دلوں اور اعمال کی طرف دیکھتا ہے۔\""}],[6588,"امام مالک بن انس نے سہیل ( بن ابی صالح ) سے ، انہوں نے اپنے والد سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" پیر اور جمعرات کے دن جنت کے دروازے کھول دیے جاتے ہیں اور ہر اس بندے کی مغفرت کر دی جاتی ہے جو اللہ تعالی کے ساتھ کسی کو شریک نہیں بناتا ، اس بندے کےسوا جس کی اپنے بھائی کے ساتھ عداوت ہو ، چنانچہ کہا جاتا ہے : ان دونون کو مہلت دو حتی کہ یہ صلح کر لیں ، ان دونوں کو مہلت دو حتی کہ یہ صلح کر لیں ۔ ان دونوں کو مہلت دو حتی کہ یہ صلح کر لیں ۔ \" ( اور صلح کے بعد ان کی بھی بخشش کر دی جائے ۔)","",{"u2":") امام مالک بن انس نے سہیل (بن ابی صالح) سے، انہوں نے اپنے والد سے، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"پیر اور جمعرات کے دن جنت کے دروازے کھول دیے جاتے ہیں اور ہر اس بندے کی مغفرت کر دی جاتی ہے جو اللہ تعالیٰ کے ساتھ کسی کو شریک نہیں بناتا، اس بندے کےسوا جس کی اپنے بھائی کے ساتھ عداوت ہو، چنانچہ کہا جاتا ہے:ان دونون کو مہلت دو حتی کہ یہ صلح کر لیں، ان دونوں کو مہلت دو حتی کہ یہ صلح کر لیں۔ ان دونوں کو مہلت دو حتی کہ یہ صلح کر لیں۔\" (اور صلح کے بعد ان کی بھی بخشش کر دی جائے۔)"}],[6589,"امام مالک بن انس نے سہیل ( بن ابی صالح ) سے ، انہوں نے اپنے والد سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" پیر اور جمعرات کے دن جنت کے دروازے کھول دیے جاتے ہیں اور ہر اس بندے کی مغفرت کر دی جاتی ہے جو اللہ تعالی کے ساتھ کسی کو شریک نہیں بناتا ، اس بندے کےسوا جس کی اپنے بھائی کے ساتھ عداوت ہو ، چنانچہ کہا جاتا ہے : ان دونون کو مہلت دو حتی کہ یہ صلح کر لیں ، ان دونوں کو مہلت دو حتی کہ یہ صلح کر لیں ۔ ان دونوں کو مہلت دو حتی کہ یہ صلح کر لیں ۔ \" ( اور صلح کے بعد ان کی بھی بخشش کر دی جائے ۔)","",{"u2":"زہیر بن حرب نے کہا: ہمیں جریر نے حدیث بیان کی۔ قتیبہ بن سعید اور احمد بن عبدہ ضبی نے عبدالعزیز دراوردی سے حدیث بیان کی، ان دونوں (جریر اور عبدالعزیز) نے سہیل سے روایت کی، انہوں نے اپنے والد (ابو صالح) سے مالک کی سند کے ساتھ انہی کی حدیث کے مانند روایت کی، البتہ ابن عبدہ سے دراوردی کی بیان کردہ حدیث میں ہے: \"سوائے ان دو کے جنہوں نے ایک دوسرے کو چھوڑ رکھا ہو۔\" اور قتیبہ نے کہا: \"سوائے ان دو کے جنہوں نے دوری اختیار کر رکھی ہو۔\""}],[6590,"سفیان نے مسلم بن ابی مریم سے ، انہوں نے ابوصالح سے روایت کی ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے سنا ، انہوں نے ایک بار اس حدیث کو مرفوعا بیان کیا ، کہا : ہر پیر اور جمعرات کو اعمال پیش کیے جاتے ہیں ، اس دن اللہ تعالی ہر اس شخص کی مغفرت کر دیتا ہے جو اللہ تعالی کے ساتھ کسی کو شریک نہیں کرتا ، اس شخص کے سوا کہ اس کے اور اس کے بھائی کے درمیان عداوت اور کینہ ہو ، تو ( ان کے بارے میں ) کہا جاتا ہے : ان دونوں کو رینے دو یہاں تک کہ یہ آپس میں صلح کر لیں ، ان دونوں کو رہنے دو یہاں تک کہ یہ آپس میں صلح کر لیں ۔","",{"u2":"سفیان نے مسلم بن ابی مریم سے، انہوں نے ابوصالح سے روایت کی، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے سنا، انہوں نے ایک بار اس حدیث کو مرفوعا بیان کیا، کہا: ہر پیر اور جمعرات کو اعمال پیش کیے جاتے ہیں، اس دن اللہ تعالیٰ ہر اس شخص کی مغفرت کر دیتا ہے جو اللہ تعالیٰ کے ساتھ کسی کو شریک نہیں کرتا، اس شخص کے سوا کہ اس کے اور اس کے بھائی کے درمیان عداوت اور کینہ ہو، تو (ان کے بارے میں) کہا جاتا ہے: ان دونوں کو رینے دو یہاں تک کہ یہ آپس میں صلح کر لیں، ان دونوں کو رہنے دو یہاں تک کہ یہ آپس میں صلح کر لیں۔\""}],[6591,"امام مالک بن انس نے مسلم بن ابی مریم سے ، انہوں نے ابوصالح سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے ، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" لوگوں کے اعمال ہر ہفتے میں دو بار پیش کیے جاتے ہیں ، پیر کے دن اور جمعرات کے دن اور ہر ایمان رکھنے والے بندے کی مغفرت کر دی جاتی ہے ، اس بندے کے سوا کہ اس کے اور اس کے بھائی کے درمیان عداوت اور بغض ہوتا ہے ۔ تو ( ان کے بارے میں ) کہا جاتا ہے : ان دونوں کو چھوڑ دو ، یا مؤخر کر دو یہاں تک کہ دونوں ( عداوت چھوڑ کر ایک دوسرے کی طرف ) واپس آ جائیں ۔","",{"u2":"امام مالک بن انس نے مسلم بن ابی مریم سے، انہوں نے ابوصالح سے، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"لوگوں کے اعمال ہر ہفتے میں دو بار پیش کیے جاتے ہیں، پیر کے دن اور جمعرات کے دن اور ہر ایمان رکھنے والے بندے کی مغفرت کر دی جاتی ہے، اس بندے کے سوا کہ اس کے اور اس کے بھائی کے درمیان عداوت اور بغض ہوتا ہے۔ تو (ان کے بارے میں) کہا جاتا ہے: ان دونوں کو چھوڑ دو، یا مؤخر کر دو یہاں تک کہ دونوں (عداوت چھوڑ کر ایک دوسرے کی طرف) واپس آ جائیں۔\""}],[6592,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ تعالی قیامت کے دن فرمائے گا : میرے جلال کی بنا پر ایک دوسرے سے محبت کرنے والے کہاں ہیں؟ آج میں انہیں اپنے سائے میں رکھوں گا ، آج کے دن جب میرے سائے کے سوا اور کوئی سایہ نہیں ۔","",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ قیامت کے دن فرمائے گا: میرے جلال کی بنا پر ایک دوسرے سے محبت کرنے والے کہاں ہیں؟ آج میں انہیں اپنے سائے میں رکھوں گا، آج کے دن جب میرے سائے کے سوا اور کوئی سایہ نہیں۔\""}],[6593,"عبدالاعلی بن حماد نے کہا : ہمیں حماد بن سلمہ نے ثابت سے حدیث بیان کی ، انہوں نے ابورافع سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی : ا \" ایک شخص اپنے بھائی سے ملنے کے لیے گیا جو دوسری بستی میں تھا ، اللہ تعالی نے اس کے راستے پر ایک فرشتے کو اس کی نگرانی ( یا انتظار ) کے لیے مقرر فرما دیا ۔ جب وہ شخص اس ( فرشتے ) کے سامنے آیا تو اس نے کہا : کہاں جانا چاہتے ہو؟ اس نے کہا : میں اپنے ایک بھائی کے پاس جانا چاہتا ہوں جو اس بستی میں ہے ۔ اس نے پوچھا : کیا تمہارا اس پر کوئی احسان ہے جسے مکمل کرنا چاہتے ہو؟ اس نے کہا : نہیں ، بس مجھے اس کے ساتھ صرف اللہ عزوجل کی خاطر محبت ہے ۔ اس نے کہا : تو میں اللہ ہی کی طرف سے تمہارے پاس بھیجا جانے والا قاصد ہوں کہ اللہ کو بھی تمہارے ساتھ اسی طرح محبت ہے جس طرح اس کی خاطر تم نے اس ( بھائی ) سے محبت کی ہے ۔","",{"u2":"عبدالاعلیٰ بن حماد نے کہا: ہمیں حماد بن سلمہ نے ثابت سے حدیث بیان کی، انہوں نے ابورافع سے، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی: ا\"ایک شخص اپنے بھائی سے ملنے کے لیے گیا جو دوسری بستی میں تھا، اللہ تعالیٰ نے اس کے راستے پر ایک فرشتے کو اس کی نگرانی (یا انتظار) کے لیے مقرر فرما دیا۔ جب وہ شخص اس (فرشتے) کے سامنے آیا تو اس نے کہا: کہاں جانا چاہتے ہو؟ اس نے کہا: میں اپنے ایک بھائی کے پاس جانا چاہتا ہوں جو اس بستی میں ہے۔ اس نے پوچھا: کیا تمہارا اس پر کوئی احسان ہے جسے مکمل کرنا چاہتے ہو؟ اس نے کہا: نہیں، بس مجھے اس کے ساتھ صرف اللہ عزوجل کی خاطر محبت ہے۔ اس نے کہا: تو میں اللہ ہی کی طرف سے تمہارے پاس بھیجا جانے والا قاصد ہوں کہ اللہ کو بھی تمہارے ساتھ اسی طرح محبت ہے جس طرح اس کی خاطر تم نے اس (بھائی) سے محبت کی ہے۔\""}],[6594,"ابوبکر بن محمد بن زنجویہ قشیری نے کہا : ہمیں عبدالاعلی بن حماد نرسی نے حماد بن سلمہ سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی ۔"],[6595,"سعید بن منصور اور ابوربیع زہرانی سے کہا : ہمیں حماد بن زید نے ایوب سے حدیث بیان کی ، انہوں نے ابوقلابہ سے ، انہوں نے ابواسماء سے ، انہوں نے سیدنا ثوبان رضی اللہ عنہ سے روایت کی ۔ ۔ ابو ربیع نے کہا : انہوں نے اسے رسول اللہ صلی اللہ علیہ وسلم سے مرفوعا بیان کیا ۔ ۔ اور سعید کی حدیث میں ہے : ( ثوبان رضی اللہ عنہ نے ) کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" مریض کی عیادت کرنے والا واپس آنے تک جنت کے درمیان گزرنے والی روش پر ہوتا ہے ۔","",{"u2":"سعید بن منصور اور ابوربیع زہرانی سے کہا: ہمیں حماد بن زید نے ایوب سے حدیث بیان کی، انہوں نے ابوقلابہ سے، انہوں نے ابواسماء سے، انہوں نے حضرت ثوبان رضی اللہ عنہ سے روایت کی۔۔ ابو ربیع نے کہا: انہوں نے اسے رسول اللہ صلی اللہ علیہ وسلم سے مرفوعا بیان کیا۔۔ اور سعید کی حدیث میں ہے: (ثوبان رضی اللہ عنہ نے) کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مریض کی عیادت کرنے والا واپس آنے تک جنت کے درمیان گزرنے والی روش پر ہوتا ہے۔\""}],[6596,"ہشیم نے ہمیں خالد سے خبر دی ، انہوں نے ابوقلابہ سے ، انہوں نے ابواسماء سے ، انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے آزاد کردہ غلام سیدنا ثوبان رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جو شخص کسی مریض کی عیادت کرتا ہے وہ واپس آنے تک مسلسل جنت کی ایک روش پر رہتا ہے ۔","",{"u2":"ہشیم نے ہمیں خالد سے خبر دی، انہوں نے ابوقلابہ سے، انہوں نے ابواسماء سے، انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے آزاد کردہ غلام حضرت ثوبان رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص کسی مریض کی عیادت کرتا ہے وہ واپس آنے تک مسلسل جنت کی ایک روش پر رہتا ہے۔\""}],[6597,"یزید بن زُرَیع نے کہا : ہمیں خالد نے ابوقلابہ سے ، انہوں نے ابو اسماء رحبی سے ، انہوں نے سیدنا ثوبان رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" ایک مسلمان جب اپنے مسلمان بھائی کی عیادت کرتا ہے تو واپس آنے تک مسلسل جنت کی ایک روش میں موجود ہوتا ہے ۔","",{"u2":"یزید بن زُرَیع نے کہا: ہمیں خالد نے ابوقلابہ سے، انہوں نے ابو اسماء رحبی سے، انہوں نے حضرت ثوبان رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ایک مسلمان جب اپنے مسلمان بھائی کی عیادت کرتا ہے تو واپس آنے تک مسلسل جنت کی ایک روش میں موجود ہوتا ہے۔\""}],[6598,"یزید بن ہارون نے کہا : ہمیں عاصم احول نے ابوقلابہ عبداللہ بن زید سے خبر سنائی ، انہوں نے ابو اشعث سے ، انہوں نے ابو اسماء رحبی سے ، انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے آزاد کردہ غلام سیدنا ثوبان رضی اللہ عنہ سے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" جس شخص نے کسی مریض کی عیادت کی وہ مسلسل جنت کی روش میں رہا ۔ \" آپ سے پوچھا گیا : یا رسول اللہ! جنت کی روش کیا چیز ہے؟ آپ نے فرمایا : \" اس کے پھل جنہیں وہ چنتا ہے ۔","",{"u2":"مروان بن معاویہ نے عاصم احول سے اسی سند کے ساتھ حدیث بیان کی۔"}],[6599,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" قیامت کے دن اللہ عزوجل فرمائے گا : آدم کے بیٹے! میں بیمار ہوا تو نے میری عیادت نہ کی ۔ وہ کہے گا : میرے رب! میں کیسے تیری عیادت کرتا جبکہ تو رب العالمین ہے ۔ اللہ تعالی فرمائے گا : کیا تمہیں معلوم نہ تھا کہ میرا فلاں بندہ بیمار تھا ، تو نے اس کی عیادت نہ کی ۔ تمہیں معلوم نہیں کہ اگر تو اس کی عیادت کرتا تو مجھے اس کے پاس پاتا ، اے ابن آدم! میں نے تجھ سے کھانا مانگا ، تو نے مجھے کھانا نہ کھلایا ۔ وہ شخص کہے گا : اے میرے رب! میں تجھے کیسے کھانا کھلاتا جبکہ تو خود ہی سارے جہانوں کو پالنے والا ہے ۔ اللہ تعالی فرمائے گا : کیا تجھے معلوم نہیں کہ میرے فلاں بندے نے تجھ سے کھانا مانگا تھا : تو نے اسے کھانا نہ کھلایا اگر تو اس کو کھلا دیتا تو تمہیں وہ ( کھانا ) میرے پاس مل جاتا ۔ اے ابن آدم! میں نے تجھ سے پانی مانگا تھا ، تو نے مجھے پانی نہیں پلایا ۔ وہ شخص کہے گا : میرے رب! میں تجھے کیسے پانی پلاتا جبکہ تو خود ہی سارے جہانوں کو پالنے والا ہے ۔ اللہ تعالی فرمائے گا : میرے فلاں بندے نے تجھ سے پانی مانگا تھا تو نے اسے پانی نہ پلایا ، اگر تو اس کو پانی پلا دیتا تو ( آج ) اس کو میرے پاس پا لیتا ۔","",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"قیامت کے دن اللہ عزوجل فرمائے گا: آدم کے بیٹے! میں بیمار ہوا تو نے میری عیادت نہ کی۔ وہ کہے گا: میرے رب! میں کیسے تیری عیادت کرتا جبکہ تو رب العالمین ہے۔ اللہ تعالیٰ فرمائے گا: کیا تمہیں معلوم نہ تھا کہ میرا فلاں بندہ بیمار تھا، تو نے اس کی عیادت نہ کی۔ تمہیں معلوم نہیں کہ اگر تو اس کی عیادت کرتا تو مجھے اس کے پاس پاتا، اے ابن آدم! میں نے تجھ سے کھانا مانگا، تو نے مجھے کھانا نہ کھلایا۔ وہ شخص کہے گا: اے میرے رب! میں تجھے کیسے کھانا کھلاتا جبکہ تو خود ہی سارے جہانوں کو پالنے والا ہے۔ اللہ تعالیٰ فرمائے گا: کیا تجھے معلوم نہیں کہ میرے فلاں بندے نے تجھ سے کھانا مانگا تھا: تو نے اسے کھانا نہ کھلایا اگر تو اس کو کھلا دیتا تو تمہیں وہ (کھانا) میرے پاس مل جاتا۔ اے ابن آدم! میں نے تجھ سے پانی مانگا تھا، تو نے مجھے پانی نہیں پلایا۔ وہ شخص کہے گا: میرے رب! میں تجھے کیسے پانی پلاتا جبکہ تو خود ہی سارے جہانوں کو پالنے والا ہے۔ اللہ تعالیٰ فرمائے گا: میرے فلاں بندے نے تجھ سے پانی مانگا تھا تو نے اسے پانی نہ پلایا، اگر تو اس کو پانی پلا دیتا تو (آج) اس کو میرے پاس پا لیتا۔\""}],[6600,"عثمان بن ابی شیبہ اور اسحٰق بن ابراہیم نے کہا : ہمیں جریر نے اعمش سے حدیث بیان کی ، انہوں نے ابووائل سے ، انہوں نے مسروق سے روایت کی ، کہا : سیدہ عائشہ رضی اللہ عنہا نے کہا : میں نے کوئی شخص نہیں دیکھا جسے رسول اللہ صلی اللہ علیہ وسلم سے زیادہ سخت تکلیف کا سامنا کرنا پڑا ہو ۔ عثمان کی روایت میں \" سخت تکلیف کا سامنا \" کے بجائے \" جس کی تکلیف زیادہ سخت ہو \" ہے ۔","",{"u2":"عثمان بن ابی شیبہ اور اسحٰق بن ابراہیم نے کہا: ہمیں جریر نے اعمش سے حدیث بیان کی، انہوں نے ابووائل سے، انہوں نے مسروق سے روایت کی، کہا: حضرت عائشہ رضی اللہ عنہا نے کہا: میں نے کوئی شخص نہیں دیکھا جسے رسول اللہ صلی اللہ علیہ وسلم سے زیادہ سخت تکلیف کا سامنا کرنا پڑا ہو۔ عثمان کی روایت میں \"سخت تکلیف کا سامنا\" کے بجائے \"جس کی تکلیف زیادہ سخت ہو\" ہے۔"}],[6601,"شعبہ اور سفیان دونوں نے اعمش سے جریر کی سند کے ساتھ اسی کی حدیث کے مانند روایت کی ۔","",{"u2":"شعبہ اور سفیان دونوں نے اعمش سے جریر کی سند کے ساتھ اسی کی حدیث کے مانند روایت کی۔"}],[6602,"عثمان بن ابی شیبہ ، زہیر بن حرب اور اسحٰق بن ابراہیم نے کہا؛ ہمیں جریر نے اعمش سے حدیث بیان کی ، انہوں نے ابراہیم تیمی سے ، انہوں نے حارث بن سوید سے ، انہوں نے سیدنا عبداللہ ( بن مسعود ) رضی اللہ عنہ سے روایت کی ، کہا : میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا ، اس وقت آپ کو بخار چڑھ رہا تھا ، میں نے آپ کو ہاتھ سے چھوا اور عرض کی : اللہ کے رسول! آپ کو تو بہت سخت بخار چڑھا ہوا ہے ، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" ہاں ، مجھے اتنا بخار چڑھتا ہے جتنا تم میں سے دو آدمیوں کو بخار چڑھتا ہے ۔ \"\" میں نے عرض کی : یہ اس لیے کہ آپ کے لیے دہرا اجر ہے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" ہاں ، ( یہی بات ہے ۔ ) \"\" پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" کوئی مسلمان نہیں جسے کوئی تکلیف پہنچے ، مرض ہو یا اس کے علاوہ کوئی اور تکلیف مگر اللہ اس کے سبب سے اس کی برائیاں ( گناہ ) جھاڑ دیتا ہے جس طرح درخت اپنے پتے جھاڑتا ہے ۔ \"\" زہیر کی حدیث میں یہ الفاظ نہیں : \"\" تو میں نے آپ کو ہاتھ سے چھوا ۔","",{"u2":"عثمان بن ابی شیبہ، زہیر بن حرب اور اسحٰق بن ابراہیم نے کہا؛ ہمیں جریر نے اعمش سے حدیث بیان کی، انہوں نے ابراہیم تیمی سے، انہوں نے حارث بن سوید سے، انہوں نے حضرت عبداللہ (بن مسعود) رضی اللہ عنہ سے روایت کی، کہا: میں رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا، اس وقت آپ کو بخار چڑھ رہا تھا، میں نے آپ کو ہاتھ سے چھوا اور عرض کی: اللہ کے رسول! آپ کو تو بہت سخت بخار چڑھا ہوا ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہاں، مجھے اتنا بخار چڑھتا ہے جتنا تم میں سے دو آدمیوں کو بخار چڑھتا ہے۔\" میں نے عرض کی: یہ اس لیے کہ آپ کے لیے دہرا اجر ہے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہاں، (یہی بات ہے۔)\" پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کوئی مسلمان نہیں جسے کوئی تکلیف پہنچے، مرض ہو یا اس کے علاوہ کوئی اور تکلیف مگر اللہ اس کے سبب سے اس کی برائیاں (گناہ) جھاڑ دیتا ہے جس طرح درخت اپنے پتے جھاڑتا ہے۔\"\nزہیر کی حدیث میں یہ الفاظ نہیں: \"تو میں نے آپ کو ہاتھ سے چھوا۔\""}],[6603,"ابومعاویہ ، سفیان ، عیسی بن یونس اور یحیی بن عبدالملک بن ابی غنیہ سب نے اعمش سے جریر کی سند کے ساتھ ، اسی کی حدیث کے مانند روایت کی اور ابومعاویہ کی حدیث میں مزید ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" ہاں ، مجھے اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! روئے زمین پر کوئی مسلمان نہیں ۔ ۔ ۔","",{"u2":"ابومعاویہ، سفیان، عیسیٰ بن یونس اور یحییٰ بن عبدالملک بن ابی غنیہ سب نے اعمش سے جریر کی سند کے ساتھ، اسی کی حدیث کے مانند روایت کی اور ابومعاویہ کی حدیث میں مزید ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ہاں، مجھے اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! روئے زمین پر کوئی مسلمان نہیں۔۔۔\""}],[6604,"منصور نے ابراہیم سے ، انہوں نے اسود ( بن یزید نخعی ) سے روایت کی ، انہوں نے کہا : کچھ قریشی نوجوان سیدہ عائشہ رضی اللہ عنہا کی خدمت میں حاضر ہوئے جبکہ وہ منی میں تھیں ۔ وہ نوجوان ہنس رہے تھے ۔ سیدہ عائشہ رضی اللہ عنہا نے پوچھا : تم کس وجہ سے ہنس رہے ہو؟ انہوں نے کہا : فلاں شخص خیمے کی رسیوں پر گر پڑا ، قریب تھا کہ اس کی گردن یا آنکھ جاتی رہتی ۔ اس پر سیدہ عائشہ رضی اللہ عنہا نے فرمایا : ہنسو مت ، میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ نے فرمایا : \" کوئی مسلمان نہیں جسے کانٹا چبھ جائے یا اس سے بڑھ کر ( تکلیف ) ہو مگر اس کے لیے ایک درجہ لکھ دیا جاتا ہے اور اس کا ایک گناہ معاف کر دیا جاتا ہے ۔","",{"u2":"منصور نے ابراہیم سے، انہوں نے اسود (بن یزید نخعی) سے روایت کی، انہوں نے کہا: کچھ قریشی نوجوان حضرت عائشہ رضی اللہ عنہا کی خدمت میں حاضر ہوئے جبکہ وہ منیٰ میں تھیں۔ وہ نوجوان ہنس رہے تھے۔ حضرت عائشہ رضی اللہ عنہا نے پوچھا: تم کس وجہ سے ہنس رہے ہو؟ انہوں نے کہا: فلاں شخص خیمے کی رسیوں پر گر پڑا، قریب تھا کہ اس کی گردن یا آنکھ جاتی رہتی۔ اس پر حضرت عائشہ رضی اللہ عنہا نے فرمایا: ہنسو مت، میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ نے فرمایا: \"کوئی مسلمان نہیں جسے کانٹا چبھ جائے یا اس سے بڑھ کر (تکلیف) ہو مگر اس کے لیے ایک درجہ لکھ دیا جاتا ہے اور اس کا ایک گناہ معاف کر دیا جاتا ہے۔\""}],[6605,"اعمش نے ابراہیم سے ، انہوں نے اسود سے ، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ایک مومن کو کوئی کانٹا نہیں چبھتا یا اس سے زیادہ کوئی تکلیف نہیں ہوتی مگر اللہ تعالی اس سے اس کا ایک درجہ بلند کر دیتا ہے یا اس کی بنا پر اس کا ایک گناہ مٹا دیتا ہے ۔","",{"u2":"اعمش نے ابراہیم سے، انہوں نے اسود سے، انہوں نے حضرت عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک مومن کو کوئی کانٹا نہیں چبھتا یا اس سے زیادہ کوئی تکلیف نہیں ہوتی مگر اللہ تعالیٰ اس سے اس کا ایک درجہ بلند کر دیتا ہے یا اس کی بنا پر اس کا ایک گناہ مٹا دیتا ہے۔\""}],[6606,"محمد بن بشر نے کہا : ہمیں ہشام نے اپنے والد ( عروہ ) سے حدیث بیان کی ، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ایک مومن کو جب بھی کوئی کانٹا چبھتا ہے یا اس سے بڑھ کر کوئی تکلیف ہوتی ہے تو اللہ تعالی اس کی وجہ سے اس کا ایک گناہ مٹا دیتا ہے ۔","",{"u2":"محمد بن بشر نے کہا: ہمیں ہشام نے اپنے والد (عروہ) سے حدیث بیان کی، انہوں نے حضرت عائشہ رضی اللہ عنہا سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک مومن کو جب بھی کوئی کانٹا چبھتا ہے یا اس سے بڑھ کر کوئی تکلیف ہوتی ہے تو اللہ تعالیٰ اس کی وجہ سے اس کا ایک گناہ مٹا دیتا ہے۔\""}],[6607,"ابو معاویہ نے ہمیں ہشام سے اسی سند کے ساتھ حدیث بیان کی ۔","",{"u2":"ابو معاویہ نے ہمیں ہشام سے اسی سند کے ساتھ حدیث بیان کی۔"}],[6608,"ابن شہاب نے عروہ بن زبیر سے ، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کوئی بھی مصیبت نہیں جس میں کوئی مسلمان مبتلا ہو مگر اس کی بنا پر اس کا کوئی گناہ اس سے ہٹا دیا جاتا ہے حتی کہ وہ کانٹا بھی جو اسے چبھتا ہے ( اور کسی گناہ کا کفارہ بن جاتا ہے ۔)","",{"u2":"ابن شہاب نے عروہ بن زبیر سے، انہوں نے حضرت عائشہ رضی اللہ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کوئی بھی مصیبت نہیں جس میں کوئی مسلمان مبتلا ہو مگر اس کی بنا پر اس کا کوئی گناہ اس سے ہٹا دیا جاتا ہے حتی کہ وہ کانٹا بھی جو اسے چبھتا ہے (اور کسی گناہ کا کفارہ بن جاتا ہے۔)\""}],[6609,"امام مالک بن انس نے یزید بن خُصَیفہ سے ، انہوں نے عروہ بن زبیر سے ، انہوں نے نبی صلی اللہ علیہ وسلم کی اہلیہ سیدہ عائشہ رضی اللہ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : مسلمان پر کوئی بھی مصیبت نہیں آتی ، چاہے ایک کانٹا ہی ( چبھا ) ہو مگر اس کی وجہ سے اس کی غلطیاں معاف کر دی جاتی ہیں یا اس کو اس کی کچھ غلطیوں کا کفارہ بنا دیا جاتا ہے ۔ \"\" یزید کو پتہ نہیں کہ عروہ نے ان دونوں میں سے کون سا جملہ بولا تھا ۔","",{"u2":"امام مالک بن انس نے یزید بن خُصَیفہ سے، انہوں نے عروہ بن زبیر سے، انہوں نے نبی صلی اللہ علیہ وسلم کی اہلیہ حضرت عائشہ رضی اللہ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: مسلمان پر کوئی بھی مصیبت نہیں آتی، چاہے ایک کانٹا ہی (چبھا) ہو مگر اس کی وجہ سے اس کی غلطیاں معاف کر دی جاتی ہیں یا اس کو اس کی کچھ غلطیوں کا کفارہ بنا دیا جاتا ہے۔\"\nیزید کو پتہ نہیں کہ عروہ نے ان دونوں میں سے کون سا جملہ بولا تھا۔"}],[6610,"عمرہ نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کوئی بھی مصیبت نہیں جو مومن پر آتی ہے ، حتی کہ وہ کانٹا بھی جو اسے چبھتا ہے تو اللہ اس کے بدلے اس کے لیے ایک نیکی لکھ دیتا ہے یا اس کی وجہ سے اس کی کوئی غلطی معاف کر دی جاتی ہے ۔","",{"u2":"عمرہ نے حضرت عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کوئی بھی مصیبت نہیں جو مومن پر آتی ہے، حتی کہ وہ کانٹا بھی جو اسے چبھتا ہے تو اللہ اس کے بدلے اس کے لیے ایک نیکی لکھ دیتا ہے یا اس کی وجہ سے اس کی کوئی غلطی معاف کر دی جاتی ہے۔\""}],[6611,"عطاء بن یسار نے سیدنا ابوسعید اور سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، دونوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا : \" مومن کو کوئی تکلیف نہیں پہنچتی ، نہ تھکاوٹ ، نہ بیماری ، نہ غم حتی کہ کوئی فکر بھی جو اسے فکرمند کر دے مگر اس کے بدلے اس کے گناہوں کو مٹا دیا جاتا ہے ۔","",{"u2":"عطاء بن یسار نے حضرت ابوسعید اور حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، دونوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"مومن کو کوئی تکلیف نہیں پہنچتی، نہ تھکاوٹ، نہ بیماری، نہ غم حتی کہ کوئی فکر بھی جو اسے فکرمند کر دے مگر اس کے بدلے اس کے گناہوں کو مٹا دیا جاتا ہے۔\""}],[6612,"سفیان نے قریش کے ایک بزرگ ابن محیصن سے روایت کی ، انہوں نے محمد بن قیس بن مخرمہ کو سیدنا ابوہریرہ رضی اللہ عنہ سے حدیث بیان کرتے ہوئے سنا ، انہوں نے کہا : جب ( یہ آیت ) نازل ہوئی : \"\" جو شخص کوئی برائی کرے گا ، اس کے بدلے اسے سزا دی جائے گی ۔ \"\" یہ ( بات ) مسلمانوں کے لیے سخت خوف اور تشویش کا باعث بنی ، اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" ( مطلوبہ معیار کے ) قریب تر پہنچو اور اچھی طرح سیکھے ہو جاؤ ۔ ہر مصیبت میں ، جو کسی مسلمان کو پہنچتی ہے ، ایک کفارہ ہوتا ہے حتی کہ ٹھوکر جو اسے لگ جاتی ہے یا کانٹا اسے چبھ جاتا ہے ۔ \"\" امام مسلم نے کہا : وہ ( قریش کے شیخ ابن محیصن ) اہل مکہ میں سے عمر بن عبدالرحمان بن محیصن ہیں ۔","",{"u2":"سفیان نے قریش کے ایک بزرگ ابن محیصن سے روایت کی، انہوں نے محمد بن قیس بن مخرمہ کو حضرت ابوہریرہ رضی اللہ عنہ سے حدیث بیان کرتے ہوئے سنا، انہوں نے کہا: جب (یہ آیت) نازل ہوئی: \"جو شخص کوئی برائی کرے گا، اس کے بدلے اسے سزا دی جائے گی۔\" یہ (بات) مسلمانوں کے لیے سخت خوف اور تشویش کا باعث بنی، اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"(مطلوبہ معیار کے) قریب تر پہنچو اور اچھی طرح سیکھے ہو جاؤ۔ ہر مصیبت میں، جو کسی مسلمان کو پہنچتی ہے، ایک کفارہ ہوتا ہے حتی کہ ٹھوکر جو اسے لگ جاتی ہے یا کانٹا اسے چبھ جاتا ہے۔\"\nامام مسلم نے کہا: وہ (قریش کے شیخ ابن محیصن) اہل مکہ میں سے عمر بن عبدالرحمان بن محیصن ہیں۔"}],[6613,"ابوزبیر نے کہا : ہمیں سیدنا جابر بن عبداللہ رضی اللہ عنہ نے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم ( ایک انصاری خاتون ) سیدہ ام سائب یا سیدہ ام مسیب رضی اللہ عنہا کے ہاں تشریف لے گئے ، آپ نے فرمایا : \" ام سائب یا ( فرمایا : ) ام مسیب! تہیں کیا ہوا؟ کیا تم شدت سے کانپ رہی ہو؟ \" انہوں نے کہا : بخار ہے ، اللہ تعالی اس میں برکت نہ دے! آپ نے فرمایا : \" بخار کو برا نہ کہو ، کیونکہ یہ آدم کی اولاد کے گناہوں کو اس طرح دور کرتا ہے جس طرح بھٹی لوہے کے زنگ کو دور کرتی ہے ۔","",{"u2":"ابوزبیر نے کہا: ہمیں حضرت جابر بن عبداللہ رضی اللہ عنہ نے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم (ایک انصاری خاتون) حضرت ام سائب یا حضرت ام مسیب رضی اللہ عنہا کے ہاں تشریف لے گئے، آپ نے فرمایا: \"ام سائب یا (فرمایا:) ام مسیب! تہیں کیا ہوا؟ کیا تم شدت سے کانپ رہی ہو؟\" انہوں نے کہا: بخار ہے، اللہ تعالیٰ اس میں برکت نہ دے! آپ نے فرمایا: \"بخار کو برا نہ کہو، کیونکہ یہ آدم کی اولاد کے گناہوں کو اس طرح دور کرتا ہے جس طرح بھٹی لوہے کے زنگ کو دور کرتی ہے۔\""}],[6614,"عطاء بن ابی رباح نے حدیث بیان کی ، کہا : ایک دن سیدنا ابن عباس رضی اللہ عنہ نے مجھ سے کہا : کیا میں تمہیں اہل جنت میں سے ایک عورت نہ دکھاؤں؟ میں نے کہا : کیوں نہیں! انہوں نے کہا : یہ سیاہ فام عورت ہے ، یہ نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئی اور عرض کی : اللہ کے رسول! مجھ پر مرگی کا دورہ پڑتا ہے جس سے ( کبھی ) میرا لباس کھل جاتا ہے ۔ آپ میرے لیے اللہ سے دعا کیجئے ۔ آپ نے فرمایا : \" اگر تم چاہو تو اس پر صبر کرو اور تمہارے لیے جنت ہے اور اگر تم چاہو تو میں اللہ سے دعا کرتا ہوں کہ وہ تم کو صحت عطا فرمائے ۔ \" اس عورت نے کہا : میں صبر کروں گی ، اس نے کہا : میرا لباس کھل جاتا ہے ، آپ اللہ سے یہ دعا فرما دیں کہ میرا لباس نہ کھلے ، تو آپ نے اس کے لیے دعا فرمائی ۔","",{"u2":"عطاء بن ابی رباح نے حدیث بیان کی، کہا: ایک دن حضرت ابن عباس رضی اللہ عنہ نے مجھ سے کہا: کیا میں تمہیں اہل جنت میں سے ایک عورت نہ دکھاؤں؟ میں نے کہا: کیوں نہیں! انہوں نے کہا: یہ سیاہ فام عورت ہے، یہ نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئی اور عرض کی: اللہ کے رسول! مجھ پر مرگی کا دورہ پڑتا ہے جس سے (کبھی) میرا لباس کھل جاتا ہے۔ آپ میرے لیے اللہ سے دعا کیجئے۔ آپ نے فرمایا: \"اگر تم چاہو تو اس پر صبر کرو اور تمہارے لیے جنت ہے اور اگر تم چاہو تو میں اللہ سے دعا کرتا ہوں کہ وہ تم کو صحت عطا فرمائے۔\" اس عورت نے کہا: میں صبر کروں گی، اس نے کہا: میرا لباس کھل جاتا ہے، آپ اللہ سے یہ دعا فرما دیں کہ میرا لباس نہ کھلے، تو آپ نے اس کے لیے دعا فرمائی۔"}],[6615,"مروان بن محمد دمشقی نے کہا؛ ہمیں سعید بن عبدالعزیز نے ربیعہ بن یزید سے حدیث بیان کی ، انہوں نے ابو ادریس خولانی سے ، انہوں نے سیدنا ابوذر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے ایک ایسی روایت بیان کی جو آپ نے اللہ تبارک و تعالی سے بیان کی ، اللہ تعالی نے فرمایا : \"\" میرے بندو! میں نے ظلم کرنا اپنے اوپر حرام کیا ہے اور تمہارے درمیان بھی اسے حرام قرار دیا ہے ، اس لیے تم ایک دوسرے پر ظلم نہ کرو ۔ میرے بندو! تم سب کے سب گمراہ ہو ، سوائے اس کے جسے میں ہدایت دے دوں ، اس لیے مجھ سے ہدایت مانگو ، میں تمہیں ہدایت دوں گا ۔ میرے بندو! تم سب کے سب بھوکے ہو ، سوائے اس کے جسے میں کھلاؤں ، اس لیے مجھ سے کھانا مانگو ، میں تمہیں کھلاؤں گا ۔ میرے بندو! تم سب کے سب ننگے ہو ، سوائے اس کے جسے میں لباس پہناؤں ، لہٰذا مجھ سے لباس مانگو میں تمہیں لباس پہناؤں گا ۔ میرے بندو! تم دن رات گناہ کرتے ہو اور میں ہی سب کے سب گناہ معاف کرتا ہوں ، سو مجھ سے مغفرت مانگو میں تمہارے گناہ معاف کروں گا ۔ میرے بندو! تم کبھی مجھے نقصان پہنچانے کی طاقت نہیں رکھو گے کہ مجھے نقصان پہنچا سکو ، نہ کبھی مجھے فائدہ پہنچانے کے قابل ہو گے کہ مجھے فائدہ پہنچا سکو ۔ میرے بندو! اگر تمہارے پہلے والے اور تمہارے بعد والے اور تمہارے انسان اور تمہارے جن سب مل کر تم میں سے ایک انتہائی متقی انسان کے دل کے مطابق ہو جائیں تو اس سے میری بادشاہت میں کوئی اضافہ نہیں ہو سکتا ۔ میرے بندو! اگر تمہارے پہلے والے اور تمہارے بعد والے اور تمہارے انسان اور تمہارے جن سب مل کر تم میں سے سب سے فاجر آدمی کے دل کے مطابق ہو جائیں تو اس سے میری بادشاہت میں کوئی کمی نہیں ہو گی ۔ میرے بندو! اگر تمہارے پہلے اور تمہارے پچھلے اور تمہارے انسان اور تمہارے جن سب مل کر ایک کھلے میدان میں کھڑے ہو جائیں اور مجھ سے مانگیں اور میں ہر ایک کو اس کی مانگی ہوئی چیز عطا کر دوں تو اس سے جو میرے پاس ہے ، اس میں اتنا بھی کم نہیں ہو گا جو اس سوئی سے ( کم ہو گا ) جو سمندر میں ڈالی ( اور نکال لی ) جائے ۔ \"\" سعید نے کہا : ابوادریس خولانی جب یہ حدیث بیان کرتے تو اپنے گھٹنوں کے بل بیٹھ جاتے ۔","",{"u2":"مروان بن محمد دمشقی نے کہا؛ ہمیں سعید بن عبدالعزیز نے ربیعہ بن یزید سے حدیث بیان کی، انہوں نے ابو ادریس خولانی سے، انہوں نے حضرت ابوذر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے ایک ایسی روایت بیان کی جو آپ نے اللہ تبارک و تعالیٰ سے بیان کی، اللہ تعالیٰ نے فرمایا: \"میرے بندو! میں نے ظلم کرنا اپنے اوپر حرام کیا ہے اور تمہارے درمیان بھی اسے حرام قرار دیا ہے، اس لیے تم ایک دوسرے پر ظلم نہ کرو۔ میرے بندو! تم سب کے سب گمراہ ہو، سوائے اس کے جسے میں ہدایت دے دوں، اس لیے مجھ سے ہدایت مانگو، میں تمہیں ہدایت دوں گا۔ میرے بندو! تم سب کے سب بھوکے ہو، سوائے اس کے جسے میں کھلاؤں، اس لیے مجھ سے کھانا مانگو، میں تمہیں کھلاؤں گا۔ میرے بندو! تم سب کے سب ننگے ہو، سوائے اس کے جسے میں لباس پہناؤں، لہذا مجھ سے لباس مانگو میں تمہیں لباس پہناؤں گا۔ میرے بندو! تم دن رات گناہ کرتے ہو اور میں ہی سب کے سب گناہ معاف کرتا ہوں، سو مجھ سے مغفرت مانگو میں تمہارے گناہ معاف کروں گا۔ میرے بندو! تم کبھی مجھے نقصان پہنچانے کی طاقت نہیں رکھو گے کہ مجھے نقصان پہنچا سکو، نہ کبھی مجھے فائدہ پہنچانے کے قابل ہو گے کہ مجھے فائدہ پہنچا سکو۔ میرے بندو! اگر تمہارے پہلے والے اور تمہارے بعد والے اور تمہارے انسان اور تمہارے جن سب مل کر تم میں سے ایک انتہائی متقی انسان کے دل کے مطابق ہو جائیں تو اس سے میری بادشاہت میں کوئی اضافہ نہیں ہو سکتا۔ میرے بندو! اگر تمہارے پہلے والے اور تمہارے بعد والے اور تمہارے انسان اور تمہارے جن سب مل کر تم میں سے سب سے فاجر آدمی کے دل کے مطابق ہو جائیں تو اس سے میری بادشاہت میں کوئی کمی نہیں ہو گی۔ میرے بندو! اگر تمہارے پہلے اور تمہارے پچھلے اور تمہارے انسان اور تمہارے جن سب مل کر ایک کھلے میدان میں کھڑے ہو جائیں اور مجھ سے مانگیں اور میں ہر ایک کو اس کی مانگی ہوئی چیز عطا کر دوں تو اس سے جو میرے پاس ہے، اس میں اتنا بھی کم نہیں ہو گا جو اس سوئی سے (کم ہو گا) جو سمندر میں ڈالی (اور نکال لی) جائے۔\"\nسعید نے کہا: ابوادریس خولانی جب یہ حدیث بیان کرتے تو اپنے گھٹنوں کے بل بیٹھ جاتے۔"}],[6616,"ابوبکر بن اسحٰق نے کہا : ہمیں ابومسہر نے حدیث بیان کی ، انہوں نے کہا : ہمیں سعید بن عبدالعزیز نے اسی سند کے ساتھ حدیث بیان کی ، البتہ مروان کی حدیث زیادہ مکمل ہے ۔","",{"u2":"ابوبکر بن اسحٰق نے کہا: ہمیں ابومسہر نے حدیث بیان کی، انہوں نے کہا: ہمیں سعید بن عبدالعزیز نے اسی سند کے ساتھ حدیث بیان کی، البتہ مروان کی حدیث زیادہ مکمل ہے۔"}],[6617,"ابواسحٰق نے کہا : ہمیں یہ حدیث بشر کے دو بیٹوں حسن اور حسین نے اور محمد بن یحیی نے بیان کی ، انہوں نے کہا : ہمیں ابومسہر نے حدیث بیان کی ، پھر پوری طویل حدیث بیان کی ۔","",{"u2":"ابواسحٰق نے کہا: ہمیں یہ حدیث بشر کے دو بیٹوں حسن اور حسین نے اور محمد بن یحییٰ نے بیان کی، انہوں نے کہا: ہمیں ابومسہر نے حدیث بیان کی، پھر پوری طویل حدیث بیان کی۔"}],[6618,"ابواسماء نے سیدنا ابوذر رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ تعالی نے فرمایا : میں نے اپنے اوپر اور اپنے بندوں پر ظلم کو حرام کر دیا ہے ، لہٰذا ایک دوسرے پر ظلم نہ کرو ۔ \" اور ( اس کے بعد ) اسی ( سابقہ حدیث کی ) طرح حدیث بیان کی اور ابوادریس ( خولانی ) کی حدیث جو ہم نے ( پہلے ) بیان کی ہے اس سے زیادہ مکمل ہے ۔","",{"u2":"ابواسماء نے حضرت ابوذر رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ نے فرمایا: میں نے اپنے اوپر اور اپنے بندوں پر ظلم کو حرام کر دیا ہے، لہذا ایک دوسرے پر ظلم نہ کرو۔\" اور (اس کے بعد) اسی (سابقہ حدیث کی) طرح حدیث بیان کی اور ابوادریس (خولانی) کی حدیث جو ہم نے (پہلے) بیان کی ہے اس سے زیادہ مکمل ہے۔"}],[6619,"سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ظلم سے بچو ، کیونکہ ظلم قیامت کے دن ( دلوں پر چھانے والی ) ظلمتیں ہوں گی ۔ بخل اور ہوس سے بچو ، کیونکہ تم سے پہلے لوگوں کو بخل و ہوس نے ہلاک کر دیا ، اسی نے ان کو اکسایا تو انہوں نے اپنے ( ایک دوسرے کے ) خون بہائے اور اپنی حرمت والی چیزوں کو حلال کر لیا ۔","",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ظلم سے بچو، کیونکہ ظلم قیامت کے دن (دلوں پر چھانے والی) ظلمتیں ہوں گی۔ بخل اور ہوس سے بچو، کیونکہ تم سے پہلے لوگوں کو بخل و ہوس نے ہلاک کر دیا، اسی نے ان کو اکسایا تو انہوں نے اپنے (ایک دوسرے کے) خون بہائے اور اپنی حرمت والی چیزوں کو حلال کر لیا۔\""}],[6620,"عبداللہ بن دینار نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ظلم قیامت کے دن کئی ظلمتیں ( تاریکیاں ) ہوں گی ۔","",{"u2":"عبداللہ بن دینار نے حضرت ابن عمر رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ظلم قیامت کے دن کئی ظلمتیں (تاریکیاں) ہوں گی۔\""}],[6621,"سالم نے اپنے والد سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" مسلمان دوسرے مسلمان کا بھائی ہے ، نہ اس پر ظلم کرتا ہے ، نہ اسے ( ظالموں کے ) سپرد کرتا ہے ۔ جو شخص اپنے بھائی کی حاجت پوری کرنے میں لگا ہوتا ہے ، اللہ تعالی اس کی حاجت روائی فرماتا ہے ۔ جو کسی مسلمان سے اس کی ایک تکلیف دور کرتا ہے ، اللہ تعالی اس سے قیامت کی تکلیفوں میں سے ایک تکلیف دور کرتا ہے ۔ جو شخص کسی مسلمان کی پردہ پوشی کرتا ہے ، اللہ تعالی قیامت کے دن اس ( کے عیبوں ) کی پردہ پوشی فرمائے گا ۔","",{"u2":"سالم نے اپنے والد سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مسلمان دوسرے مسلمان کا بھائی ہے، نہ اس پر ظلم کرتا ہے، نہ اسے (ظالموں کے) سپرد کرتا ہے۔ جو شخص اپنے بھائی کی حاجت پوری کرنے میں لگا ہوتا ہے، اللہ تعالیٰ اس کی حاجت روائی فرماتا ہے۔ جو کسی مسلمان سے اس کی ایک تکلیف دور کرتا ہے، اللہ تعالیٰ اس سے قیامت کی تکلیفوں میں سے ایک تکلیف دور کرتا ہے۔ جو شخص کسی مسلمان کی پردہ پوشی کرتا ہے، اللہ تعالیٰ قیامت کے دن اس (کے عیبوں) کی پردہ پوشی فرمائے گا۔\""}],[6622,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کیا تم جانتے ہو کہ مفلس کون ہے؟ \" صحابہ نے کہا؛ ہمارے نزدیک مفلس وہ شخص ہے جس کے پاس نہ درہم ہو ، نہ کوئی سازوسامان ۔ آپ نے فرمایا : \" میری امت کا مفلس وہ شخص ہے جو قیامت کے دن نماز ، روزہ اور زکاۃ لے کر آئے گا اور اس طرح آئے گا کہ ( دنیا میں ) اس کو گالی دی ہو گی ، اس پر بہتان لگایا ہو گا ، اس کا مال کھایا ہو گا ، اس کا خون بہایا ہو گا اور اس کو مارا ہو گا ، تو اس کی نیکیوں میں سے اس کو بھی دیا جائے گا اور اس کو بھی دیا جائے گا اور اگر اس پر جو ذمہ ہے اس کی ادائیگی سے پہلے اس کی ساری نیکیاں ختم ہو جائیں گی تو ان کے گناہوں کو لے کر اس پر ڈالا جائے گا ، پھر اس کو جہنم میں پھینک دیا جائے گا ۔","",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم جانتے ہو کہ مفلس کون ہے؟\" صحابہ نے کہا؛ ہمارے نزدیک مفلس وہ شخص ہے جس کے پاس نہ درہم ہو، نہ کوئی سازوسامان۔ آپ نے فرمایا: \"میری امت کا مفلس وہ شخص ہے جو قیامت کے دن نماز، روزہ اور زکاۃ لے کر آئے گا اور اس طرح آئے گا کہ (دنیا میں) اس کو گالی دی ہو گی، اس پر بہتان لگایا ہو گا، اس کا مال کھایا ہو گا، اس کا خون بہایا ہو گا اور اس کو مارا ہو گا، تو اس کی نیکیوں میں سے اس کو بھی دیا جائے گا اور اس کو بھی دیا جائے گا اور اگر اس پر جو ذمہ ہے اس کی ادائیگی سے پہلے اس کی ساری نیکیاں ختم ہو جائیں گی تو ان کے گناہوں کو لے کر اس پر ڈالا جائے گا، پھر اس کو جہنم میں پھینک دیا جائے گا۔\""}],[6623,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" قیامت کے دن تم سب حقداروں کے حقوق ان کو ادا کرو گے ، حتی کہ اس بکری کا بدلہ بھی جس کے سینگ توڑ دیے گئے ہوں گے ، سینگوں والی بکری سے پورا پورا لیا جائے گا ۔","",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"قیامت کے دن تم سب حقداروں کے حقوق ان کو ادا کرو گے، حتی کہ اس بکری کا بدلہ بھی جس کے سینگ توڑ دیے گئے ہوں گے، سینگوں والی بکری سے پورا پورا لیا جائے گا۔\""}],[6624,"سیدنا ابوموسی رضی اللہ عنہ سے روایت ہے ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ تعالی ظالم کو مہلت دے دیتا ہے اور جب اس کو پکڑ لیتا ہے تو پھر جانے نہیں دیتا ۔ \" پھر آپ نے ( یہ آیت ) پڑھی : \" اور جب وہ ظلم کرنے والی بستیوں کو اپنی گرفت میں لیتا ہے تو آپ کے رب کی گرفت ایسی ہی ہوتی ہے ( کہ کوئی بچ نہیں سکتا ۔ ) بےشک اس کی گرفت سخت دردناک ہے ۔","",{"u2":"حضرت ابوموسیٰ رضی اللہ عنہ سے روایت ہے، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ ظالم کو مہلت دے دیتا ہے اور جب اس کو پکڑ لیتا ہے تو پھر جانے نہیں دیتا۔\" پھر آپ نے (یہ آیت) پڑھی: \"اور جب وہ ظلم کرنے والی بستیوں کو اپنی گرفت میں لیتا ہے تو آپ کے رب کی گرفت ایسی ہی ہوتی ہے (کہ کوئی بچ نہیں سکتا۔) بےشک اس کی گرفت سخت دردناک ہے۔\""}],[6625,"ابوزبیر نے سیدنا جابر رضی اللہ عنہ سے حدیث بیان کی ، کہا : دو لڑکے آپس میں لڑ پڑے ، ایک لڑکا مہاجرین میں سے تھا اور دوسرا لڑکا انصار میں سے ۔ مہاجر نے پکار کر آواز دی : اے مہاجرین! اور انصاری نے پکار کر آواز دی : اے انصار! تو ( اچانک ) رسول اللہ صلی اللہ علیہ وسلم باہر تشریف لے آئے اور فرمایا : \" یہ کیا زمانہ جاہلیت کی سی چیخ و پکار ہے؟ \" انہوں نے عرض کی : نہیں ، اللہ کے رسول! بس یہ دو لڑکے آپس میں لڑ پڑے ہیں اور ایک نے دوسرے کی سرین پر ضرب لگائی ہے ، آپ نے فرمایا : \" کوئی ( بڑی ) بات نہیں ، اور ہر انسان کو اپنے بھائی کی ، خواہ وہ ظالم ہو یا مظلوم ، مدد کرنی چاہئے ، اگر اس کا بھائی ظالم ہو تو اسے ( ظلم سے ) روکے ، یہی اس کی مدد ہے ، اور اگر مظلوم ہو تو اس کی مدد کرے ۔","",{"u2":"ابوزبیر نے حضرت جابر رضی اللہ عنہ سے حدیث بیان کی، کہا: دو لڑکے آپس میں لڑ پڑے، ایک لڑکا مہاجرین میں سے تھا اور دوسرا لڑکا انصار میں سے۔ مہاجر نے پکار کر آواز دی: اے مہاجرین! اور انصاری نے پکار کر آواز دی: اے انصار! تو (اچانک) رسول اللہ صلی اللہ علیہ وسلم باہر تشریف لے آئے اور فرمایا: \"یہ کیا زمانہ جاہلیت کی سی چیخ و پکار ہے؟\" انہوں نے عرض کی: نہیں، اللہ کے رسول! بس یہ دو لڑکے آپس میں لڑ پڑے ہیں اور ایک نے دوسرے کی سرین پر ضرب لگائی ہے، آپ نے فرمایا: \"کوئی (بڑی) بات نہیں، اور ہر انسان کو اپنے بھائی کی، خواہ وہ ظالم ہو یا مظلوم، مدد کرنی چاہئے، اگر اس کا بھائی ظالم ہو تو اسے (ظلم سے) روکے، یہی اس کی مدد ہے، اور اگر مظلوم ہو تو اس کی مدد کرے۔\""}],[6626,"سفیان بن عیینہ نے کہا : عمرو ( بن دینار ) نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : ہم ایک غزوے ( غزوہ مریسیع ) میں نبی صلی اللہ علیہ وسلم کے ساتھ تھے ، وہاں ایک مہاجر نے ایک انصاری کی سرین پر ضرب لگائی ، انصاری نے کہا : اے انصار! ( آؤ ، مدد کرو ) اور مہاجر نے کہا : اے مہاجرو! ( آؤ ، مدد کرو ۔ ) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" یہ کیا زمانہ جاہلیت کی طرح کی چیخ و پکار ہے؟ \"\" انہوں نے کہا : یا رسول اللہ! ایک مہاجر شخص نے ایک انصاری کی سرین پر مارا ہے ، آپ نے فرمایا : \"\" ( جب یہ اتنا چھوٹا سا معاملہ ہے تو جاہلی دور کی سی ) اس ( چیخ و پکار ) کو چھوڑو ۔ یہ ایک کریہہ اور بدبودار بات ہے ۔ \"\" عبداللہ بن اُبی نے یہ بات سنی تو کہنے لگا : ( اچھا! ) انہوں نے ( ایسا ) کیا ہے ، اللہ کی قسم! جب ہم مدینہ پہنچیں گے تو ہم میں سے عزت والا اسے ، جو ذلت والا ہے ، وہاں سے نکال باہر کرے گا ۔ سیدنا عمر رضی اللہ عنہ نے کہا : مجھے چھوڑئیے ، میں اس منافق کی گردن اڑاتا ہوں ، آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" اسے رہنے دو ، کہیں لوگ یہ نہ کہیں کہ محمد ( صلی اللہ علیہ وسلم ) اپنے ہی ساتھیوں کو قتل کر رہے ہیں ۔","",{"u2":"سفیان بن عیینہ نے کہا: عمرو (بن دینار) نے حضرت جابر بن عبداللہ رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: ہم ایک غزوے (غزوہ مریسیع) میں نبی صلی اللہ علیہ وسلم کے ساتھ تھے، وہاں ایک مہاجر نے ایک انصاری کی سرین پر ضرب لگائی، انصاری نے کہا: اے انصار! (آؤ، مدد کرو) اور مہاجر نے کہا: اے مہاجرو! (آؤ، مدد کرو۔) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہ کیا زمانہ جاہلیت کی طرح کی چیخ و پکار ہے؟\" انہوں نے کہا: یا رسول اللہ! ایک مہاجر شخص نے ایک انصاری کی سرین پر مارا ہے، آپ نے فرمایا: \"(جب یہ اتنا چھوٹا سا معاملہ ہے تو جاہلی دور کی سی) اس (چیخ و پکار) کو چھوڑو۔ یہ ایک کریہہ اور بدبودار بات ہے۔\" عبداللہ بن اُبی نے یہ بات سنی تو کہنے لگا: (اچھا!) انہوں نے (ایسا) کیا ہے، اللہ کی قسم! جب ہم مدینہ پہنچیں گے تو ہم میں سے عزت والا اسے، جو ذلت والا ہے، وہاں سے نکال باہر کرے گا۔\nحضرت عمر رضی اللہ عنہ نے کہا: مجھے چھوڑئیے، میں اس منافق کی گردن اڑاتا ہوں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اسے رہنے دو، کہیں لوگ یہ نہ کہیں کہ محمد (صلی اللہ علیہ وسلم) اپنے ہی ساتھیوں کو قتل کر رہے ہیں۔\""}],[6627,"اسحٰق بن ابراہیم ، اسحٰق بن منصور اور محمد بن رافع نے ہمیں حدیث بیان کی ۔ ۔ ابن رافع نے کہا : ہمیں حدیث بیان کی جبکہ دوسرے دونوں نے کہا : خبر دی ۔ ۔ عبدالرزاق نے کہا : ہمیں معمر نے ایوب سے خبر دی ، انہوں نے عمرو بن دینار سے اور انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی ، کہا : ایک مہاجر نے ایک انصاری کی سرین پر مارا ، وہ نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور آپ سے بدلہ دلوانے کی درخواست کی ، ( رسول اللہ صلی اللہ علیہ وسلم نے ضروری کاروائی کے بعد ) لوگوں سے کہا : \"\" اس ( چیخ و پکار اور فساد انگیزی ) کو چھوڑ دو ، یہ ایک کریہہ اور بدبودار ( ھرکت ) ہے ۔ \"\" ابن منصور نے اپنی روایت میں عمرو سے روایت کرتے ہوئے صراحت کی کہ عمرو نے کہا : میں نے جابر رضی اللہ عنہ سے سنا ۔","",{"u2":") اسحٰق بن ابراہیم، اسحٰق بن منصور اور محمد بن رافع نے ہمیں حدیث بیان کی۔۔ ابن رافع نے کہا: ہمیں حدیث بیان کی جبکہ دوسرے دونوں نے کہا: خبر دی۔۔ عبدالرزاق نے کہا: ہمیں معمر نے ایوب سے خبر دی، انہوں نے عمرو بن دینار سے اور انہوں نے حضرت جابر بن عبداللہ رضی اللہ عنہ سے روایت کی، کہا: ایک مہاجر نے ایک انصاری کی سرین پر مارا، وہ نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور آپ سے بدلہ دلوانے کی درخواست کی، (رسول اللہ صلی اللہ علیہ وسلم نے ضروری کاروائی کے بعد) لوگوں سے کہا: \"اس (چیخ و پکار اور فساد انگیزی) کو چھوڑ دو، یہ ایک کریہہ اور بدبودار (ھرکت) ہے۔\"\nابن منصور نے اپنی روایت میں عمرو سے روایت کرتے ہوئے صراحت کی کہ عمرو نے کہا: میں نے جابر رضی اللہ عنہ سے سنا۔"}],[6628,"سیدنا ابوموسی رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ایک مسلمان دوسرے مسلمان کے لیے ایک عمارت کے مانند ہے ، جس کی ایک ( اینٹ ) دوسری ( اینٹ ) کو مضبوط کرتی ہے ۔","",{"u2":"حضرت ابوموسیٰ رضی اللہ عنہ سے روایت ہے، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک مسلمان دوسرے مسلمان کے لیے ایک عمارت کے مانند ہے، جس کی ایک (اینٹ) دوسری (اینٹ) کو مضبوط کرتی ہے۔\""}],[6629,"زکریا نے ہمیں شعبی سے حدیث بیان کی ، انہوں نے سیدنا نعمان بن بشیر رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" مسلمانوں کی ایک دوسرے سے محبت ، ایک دوسرے کے ساتھ رحم دلی اور ایک دوسرے کی طرف التفات و تعاون کی مثال ایک جسم کی طرح ہے ، جب اس کے ایک عضو کو تکلیف ہوتی ہے تو باقی سارا جسم بیداری اور بخار کے ذریعے سے ( سب اعضاء کو ایک دوسرے کے ساتھ ملا کر ) اس کا ساتھ دیتا ہے ۔","",{"u2":"زکریا نے ہمیں شعبی سے حدیث بیان کی، انہوں نے حضرت نعمان بن بشیر رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مسلمانوں کی ایک دوسرے سے محبت، ایک دوسرے کے ساتھ رحم دلی اور ایک دوسرے کی طرف التفات و تعاون کی مثال ایک جسم کی طرح ہے، جب اس کے ایک عضو کو تکلیف ہوتی ہے تو باقی سارا جسم بیداری اور بخار کے ذریعے سے (سب اعضاء کو ایک دوسرے کے ساتھ ملا کر) اس کا ساتھ دیتا ہے۔\""}],[6630,"مطرف نے شعبی سے ، انہوں نے نعمان بن بشیر رضی اللہ عنہ سے ، انہوں نے نبی صلی اللہ علیہ وسلم سے اسی ( گزشتہ حدیث ) کی طرح روایت کی ۔","",{"u2":"مطرف نے شعبی سے، انہوں نے نعمان بن بشیر رضی اللہ عنہ سے، انہوں نے نبی صلی اللہ علیہ وسلم سے اسی (گزشتہ حدیث) کی طرح روایت کی۔"}],[6631,"وکیع نے اعمش سے ، انہوں نے شعبی سے ، انہوں نے سیدنا نعمان بن بشیر رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" مسلمان ( باہم ) ایک ہی انسان کی طرح ہیں ، اگر اس کے سر میں تکلیف ہو تو بخار اور بے خوابی کے ذریعے سے باقی سارا جسم اس کا ساتھ دیتا ہے ۔","",{"u2":"وکیع نے اعمش سے، انہوں نے شعبی سے، انہوں نے حضرت نعمان بن بشیر رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مسلمان (باہم) ایک ہی انسان کی طرح ہیں، اگر اس کے سر میں تکلیف ہو تو بخار اور بے خوابی کے ذریعے سے باقی سارا جسم اس کا ساتھ دیتا ہے۔\""}],[6632,"خیثمہ ( بن عبدالرحمٰن ) نے سیدنا نعمان بن بشیر رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" مسلمان ( باہم ) ایک انسان کی طرح ہیں ، اگر اس کی آنکھ میں تکلیف ہو تو سارے جسم کو تکلیف ہوتی ہے اور اگر سر میں تکلیف ہو تو اس کے سارے جسم کو تکلیف ہوتی ہے ۔","",{"u2":"خیثمہ (بن عبدالرحمٰن) نے حضرت نعمان بن بشیر رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مسلمان (باہم) ایک انسان کی طرح ہیں، اگر اس کی آنکھ میں تکلیف ہو تو سارے جسم کو تکلیف ہوتی ہے اور اگر سر میں تکلیف ہو تو اس کے سارے جسم کو تکلیف ہوتی ہے۔\""}],[6633,"شعبی نے سیدنا نعمان بن بشیر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی طرح روایت کی ۔","",{"u2":") شعبی نے حضرت نعمان بن بشیر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی طرح روایت کی۔"}],[6634,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ایک دوسرے کو برا بھلا کہنے والے جو کچھ بھی کہتے ہیں ، اس کا وبال پہل کرنے والے پر ہے جب تک مظلوم حد سے تجاوز نہ کرے ۔","",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک دوسرے کو برا بھلا کہنے والے جو کچھ بھی کہتے ہیں، اس کا وبال پہل کرنے والے پر ہے جب تک مظلوم حد سے تجاوز نہ کرے۔\""}],[6635,"سیدنا ابوہریرہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" صدقے نے مال میں کبھی کوئی کمی نہیں کی اور معاف کرنے سے اللہ تعالی بندے کو عزت ہی میں بڑھاتا ہے اور کوئی شخص ( صرف اور صرف ) اللہ کی خاطر تواضع ( انکسار ) اختیار نہیں کرتا مگر اللہ تعالی اس کا مقام بلند کر دیتا ہے ۔","",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"صدقے نے مال میں کبھی کوئی کمی نہیں کی اور معاف کرنے سے اللہ تعالیٰ بندے کو عزت ہی میں بڑھاتا ہے اور کوئی شخص (صرف اور صرف) اللہ کی خاطر تواضع (انکسار) اختیار نہیں کرتا مگر اللہ تعالیٰ اس کا مقام بلند کر دیتا ہے۔\""}],[6636,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کیا تم جانتے ہو کہ غیبت کیا ہے؟ \" انہوں ( صحابہ ) نے عرض کی : اللہ اور اس کا رسول خوب جاننے والے ہیں ۔ آپ نے فرمایا : \" اپنے بھائی کا اس طرح تذکرہ کرنا جو اسے ناپسند ہو ۔ \" عرض کی گئی : آپ یہ دیکھئے کہ اگر میرے بھائی میں وہ بات واقعی موجود ہو جو میں کہتا ہوں ( تو؟ ) آپ نے فرمایا : \" جو کچھ تم کہتے ہو ، اگر اس میں موجود ہے تو تم نے اس کی غیبت کی ، اگر اس میں وہ ( عیب ) موجود نہیں تو تم نے اس پر بہتان لگایا ہے ۔","",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم جانتے ہو کہ غیبت کیا ہے؟\" انہوں (صحابہ) نے عرض کی: اللہ اور اس کا رسول خوب جاننے والے ہیں۔ آپ نے فرمایا: \"اپنے بھائی کا اس طرح تذکرہ کرنا جو اسے ناپسند ہو۔\" عرض کی گئی: آپ یہ دیکھئے کہ اگر میرے بھائی میں وہ بات واقعی موجود ہو جو میں کہتا ہوں (تو؟) آپ نے فرمایا: \"جو کچھ تم کہتے ہو، اگر اس میں موجود ہے تو تم نے اس کی غیبت کی، اگر اس میں وہ (عیب) موجود نہیں تو تم نے اس پر بہتان لگایا ہے۔\""}],[6637,"رَوح ( بن قاسم ) نے سہیل سے ، انہوں نے اپنے والد ( ابوصالح ) سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے ، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" اللہ تعالی دنیا میں جس شخص کی پردہ پوشی کرتا ہے ، قیامت کے دن بھی اس کا پردہ رکھے گا ۔","",{"u2":") رَوح (بن قاسم) نے سہیل سے، انہوں نے اپنے والد (ابوصالح) سے، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا: \"اللہ تعالیٰ دنیا میں جس شخص کی پردہ پوشی کرتا ہے، قیامت کے دن بھی اس کا پردہ رکھے گا۔\""}],[6638,"وہیب نے کہا : ہمیں سہیل نے اپنے والد سے حدیث بیان کی ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" دنیا میں کوئی بندہ کسی ( دوسرے ) بندے کا عیب نہیں چھپاتا مگر قیامت کے روز اللہ تعالی اس کے عیب چھپا لے گا ۔","",{"u2":"وہیب نے کہا: ہمیں سہیل نے اپنے والد سے حدیث بیان کی، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا: \"دنیا میں کوئی بندہ کسی (دوسرے) بندے کا عیب نہیں چھپاتا مگر قیامت کے روز اللہ تعالیٰ اس کے عیب چھپا لے گا۔\""}],[6639,"سفیان بن عیینہ نے ابن منکدر سے روایت کی ، انہوں نے عروہ بن زبیر کو یہ کہتے ہوئے سنا کہ مجھے سیدہ عائشہ رضی اللہ عنہا نے حدیث بیان کی کہ ایک شخص نے نبی صلی اللہ علیہ وسلم سے ملاقات کی اجازت طلب کی ، آپ نے فرمایا : \" اس کو اجازت دے دو ، یہ یقینا اپنے قبیلے کا بُرا فرد ہے ، یا فرمایا : قبیلے کا برا مرد ہے ۔ \" جب وہ شخص اندر آیا تو آپ نے اس کے ساتھ نرمی سے گفتگو کی ۔ سیدہ عائشہ رضی اللہ عنہا نے کہا : میں نے عرض کی : اللہ کے رسول! آپ نے اس کے بارے میں وہ فرمایا جو فرمایا تھا ، پھر آپ نے اس کے ساتھ نرمی سے بات کی؟ آپ نے فرمایا : \" عائشہ! قیامت کے دن اللہ تعالی رتبے کے اعتبار سے سب سے برا شخص وہ ہو گا جس سے لوگ اس کی بدزبانی سے بچنے کے لیے دور رہیں یا اس کو چھوڑ دیں ۔","",{"u2":"سفیان بن عیینہ نے ابن منکدر سے روایت کی، انہوں نے عروہ بن زبیر کو یہ کہتے ہوئے سنا کہ مجھے حضرت عائشہ رضی اللہ عنہا نے حدیث بیان کی کہ ایک شخص نے نبی صلی اللہ علیہ وسلم سے ملاقات کی اجازت طلب کی، آپ نے فرمایا: \"اس کو اجازت دے دو، یہ یقینا اپنے قبیلے کا بُرا فرد ہے، یا فرمایا: قبیلے کا برا مرد ہے۔\" جب وہ شخص اندر آیا تو آپ نے اس کے ساتھ نرمی سے گفتگو کی۔ حضرت عائشہ رضی اللہ عنہا نے کہا: میں نے عرض کی: اللہ کے رسول! آپ نے اس کے بارے میں وہ فرمایا جو فرمایا تھا، پھر آپ نے اس کے ساتھ نرمی سے بات کی؟ آپ نے فرمایا: \"عائشہ! قیامت کے دن اللہ تعالیٰ رتبے کے اعتبار سے سب سے برا شخص وہ ہو گا جس سے لوگ اس کی بدزبانی سے بچنے کے لیے دور رہیں یا اس کو چھوڑ دیں۔\""}],[6640,"معمر نے ابن منکدر سے اسی سند کے ساتھ اسی کے ہم معنی روایت بیان کی ، مگر انہوں نے کہا : \" یہ قوم کا بدترین فرد ہے اور یہ گھرانے کا ( بدترین ) فرد ہے ۔","",{"u2":"معمر نے ابن منکدر سے اسی سند کے ساتھ اسی کے ہم معنی روایت بیان کی، مگر انہوں نے کہا: \"یہ قوم کا بدترین فرد ہے اور یہ گھرانے کا (بدترین) فرد ہے۔\""}],[6641,"منصور نے تمیم بن سلمہ سے ، انہوں نے عبدالرحمٰن بن ہلال سے ، انہوں نے سیدنا جریر رضی اللہ عنہ سے روایت کی ، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" جس شخص کو نرم خوئی سے محروم کر دیا جائے ، وہ بھلائی سے محروم کر دیا جاتا ہے ۔","",{"u2":"منصور نے تمیم بن سلمہ سے، انہوں نے عبدالرحمٰن بن ہلال سے، انہوں نے حضرت جریر رضی اللہ عنہ سے روایت کی، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا: \"جس شخص کو نرم خوئی سے محروم کر دیا جائے، وہ بھلائی سے محروم کر دیا جاتا ہے۔\""}],[6642,"اعمش نے تمیم بن سلمہ سے ، انہوں نے عبدالرحمٰن بن ہلال عبسی سے روایت کی ، انہوں نے کہا : میں نے سیدنا جریر رضی اللہ عنہ سے سنا ، وہ کہتے ہیں : میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ فرما رہے تھے : \" جو شخص نرم خوئی سے محروم کر دیا جائے وہ بھلائی سے محروم کر دیا جاتا ہے ۔","",{"u2":"اعمش نے تمیم بن سلمہ سے، انہوں نے عبدالرحمٰن بن ہلال عبسی سے روایت کی، انہوں نے کہا: میں نے حضرت جریر رضی اللہ عنہ سے سنا، وہ کہتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ فرما رہے تھے: \"جو شخص نرم خوئی سے محروم کر دیا جائے وہ بھلائی سے محروم کر دیا جاتا ہے۔\""}],[6643,"محمد بن اسماعیل نے عبدالرحمٰن بن ہلال سے روایت کی ، انہوں نے کہا : میں نے سیدنا جریر بن عبداللہ رضی اللہ عنہ کو یہ کہتے ہوئے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جو شخص نرم مزاجی سے محروم ہوا وہ بھلائی سے محروم ہوا ، یا جو شخص نرم مزاجی سے محروم کر دیا جاتا ہے وہ بھلائی سے محروم کر دیا جاتا ہے ۔","",{"u2":"محمد بن اسماعیل نے عبدالرحمٰن بن ہلال سے روایت کی، انہوں نے کہا: میں نے حضرت جریر بن عبداللہ رضی اللہ عنہ کو یہ کہتے ہوئے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص نرم مزاجی سے محروم ہوا وہ بھلائی سے محروم ہوا، یا جو شخص نرم مزاجی سے محروم کر دیا جاتا ہے وہ بھلائی سے محروم کر دیا جاتا ہے۔\""}],[6644,"نبی صلی اللہ علیہ وسلم کی اہلیہ سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" عائشہ! اللہ تعالی نرمی کرنے والا اور نرمی کو پسند فرماتا ہے اور نرمی کی بنا پر وہ کچھ عطا فرماتا ہے جو درشت مزاجی کی بنا پر عطا نہیں فرماتا ، وہ اس کے علاوہ کسی بھی اور بات پر اتنا عطا نہیں فرماتا ۔","",{"u2":") نبی صلی اللہ علیہ وسلم کی اہلیہ حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عائشہ! اللہ تعالیٰ نرمی کرنے والا اور نرمی کو پسند فرماتا ہے اور نرمی کی بنا پر وہ کچھ عطا فرماتا ہے جو درشت مزاجی کی بنا پر عطا نہیں فرماتا، وہ اس کے علاوہ کسی بھی اور بات پر اتنا عطا نہیں فرماتا۔\""}],[6645,"معاذ عنبری نے کہا : ہمیں شعبہ نے مقدام بن شریح بن بانی سے حدیث بیان کی ، انہوں نے اپنے والد سے ، انہوں نے نبی صلی اللہ علیہ وسلم کی اہلیہ سیدہ عائشہ صدیقہ رضی اللہ عنہا سے ، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" نرمی جس چیز میں بھی ہوتی ہے اس کو زینت بخش دیتی ہے اور جس چیز سے بھی نرمی نکال دی جاتی ہے اسے بدصورت کر دیتی ہے ۔","",{"u2":"معاذ عنبری نے کہا: ہمیں شعبہ نے مقدام بن شریح بن بانی سے حدیث بیان کی، انہوں نے اپنے والد سے، انہوں نے نبی صلی اللہ علیہ وسلم کی اہلیہ حضرت عائشہ صدیقہ رضی اللہ عنہا سے، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا: \"نرمی جس چیز میں بھی ہوتی ہے اس کو زینت بخش دیتی ہے اور جس چیز سے بھی نرمی نکال دی جاتی ہے اسے بدصورت کر دیتی ہے۔\""}],[6646,"محمد بن جعفر نے کہا : ہمیں شعبہ نے حدیث بیان کی ، انہوں نے کہا : میں نے مقدام بن شریح بن بانی کو اسی سند سے ( حدیث بیان کرتے ہوئے ) سنا اور انہوں نے حدیث میں مزید بیان کیا : سیدہ عائشہ رضی اللہ عنہا ایک ایسے اونٹ پر سوار ہوئیں جس میں ابھی سرکشی تھی تو سیدہ عائشہ رضی اللہ عنہا اسے گھمانے لگیں ، اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : عائشہ! \" نرمی سے کام لو ۔ \" اس کے بعد اسی ( سابقہ حدیث ) کے مانند بیان کیا ۔","",{"u2":"محمد بن جعفر نے کہا: ہمیں شعبہ نے حدیث بیان کی، انہوں نے کہا: میں نے مقدام بن شریح بن بانی کو اسی سند سے (حدیث بیان کرتے ہوئے) سنا اور انہوں نے حدیث میں مزید بیان کیا: حضرت عائشہ رضی اللہ عنہا ایک ایسے اونٹ پر سوار ہوئیں جس میں ابھی سرکشی تھی تو حضرت عائشہ رضی اللہ عنہا اسے گھمانے لگیں، اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: عائشہ! \"نرمی سے کام لو۔\" اس کے بعد اسی (سابقہ حدیث) کے مانند بیان کیا۔"}],[6647,"اسماعیل بن ابراہیم نے کہا : ہمیں ایوب نے ابوقلابہ سے حدیث بیان کی ، انہوں نے ابومہلب سے ، انہوں نے سیدنا عمران بن حصین رضی اللہ عنہ سے روایت کی ، کہا : ایک بار رسول اللہ صلی اللہ علیہ وسلم ایک سفر میں تھے اور ایک انصاری عورت اونٹنی پر سوار تھی کہ اچانک وہ اونٹنی مضطرب ہوئی ، اس عورت نے اس پر لعنت کی تو رسول اللہ صلی اللہ علیہ وسلم نے یہ بات سن لی ، آپ نے فرمایا : \"\" اس ( اونٹنی ) پر جو کچھ موجود ہے وہ ہٹا لو اور اس کو چھوڑو کیونکہ وہ ملعون اونٹنی ہے ۔ \"\" سیدنا عمران رضی اللہ عنہ کہتے ہیں کہ جیسے میں اب بھی دیکھ رہا ہوں کہ وہ اونٹنی لوگوں کے درمیان چل رہی ہے ، کوئی اس سے تعرض نہیں کرتا ۔","",{"u2":"اسماعیل بن ابراہیم نے کہا: ہمیں ایوب نے ابوقلابہ سے حدیث بیان کی، انہوں نے ابومہلب سے، انہوں نے حضرت عمران بن حصین رضی اللہ عنہ سے روایت کی، کہا: ایک بار رسول اللہ صلی اللہ علیہ وسلم ایک سفر میں تھے اور ایک انصاری عورت اونٹنی پر سوار تھی کہ اچانک وہ اونٹنی مضطرب ہوئی، اس عورت نے اس پر لعنت کی تو رسول اللہ صلی اللہ علیہ وسلم نے یہ بات سن لی، آپ نے فرمایا: \"اس (اونٹنی) پر جو کچھ موجود ہے وہ ہٹا لو اور اس کو چھوڑو کیونکہ وہ ملعون اونٹنی ہے۔\"\nحضرت عمران رضی اللہ عنہ کہتے ہیں کہ جیسے میں اب بھی دیکھ رہا ہوں کہ وہ اونٹنی لوگوں کے درمیان چل رہی ہے، کوئی اس سے تعرض نہیں کرتا۔"}],[6648,"حماد بن زید اور ( عبدالوہاب ) ثقفی نے ایوب سے اسماعیل کی سند کے ساتھ اسی کی حدیث کے مانند حدیث بیان کی ، مگر حماد کی حدیث میں ہے : سیدنا عمران رضی اللہ عنہ نے کہا : جیسے اب بھی میں اس کو دیکھ رہا ہوں ، وہ خاکستری رنگ کی ایک اونٹنی ہے ۔ اور ثقفی کی حدیث میں ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" اس پر جو کچھ ہے اتار لو ، اس کی پیٹھ ننگی کر دو کیونکہ وہ ایک ملعون اونٹنی ہے ۔","",{"u2":"حماد بن زید اور (عبدالوہاب) ثقفی نے ایوب سے اسماعیل کی سند کے ساتھ اسی کی حدیث کے مانند حدیث بیان کی، مگر حماد کی حدیث میں ہے: حضرت عمران رضی اللہ عنہ نے کہا: جیسے اب بھی میں اس کو دیکھ رہا ہوں، وہ خاکستری رنگ کی ایک اونٹنی ہے۔ اور ثقفی کی حدیث میں ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس پر جو کچھ ہے اتار لو، اس کی پیٹھ ننگی کر دو کیونکہ وہ ایک ملعون اونٹنی ہے۔\""}],[6649,"یزید بن زریع نے کہا : ہمیں تیمی نے ابوعثمان سے حدیث بیان کی ، انہوں نے سیدنا ابوبرزہ اسلمی رضی اللہ عنہ سے روایت کی کہ ایک باندی ایک اونٹنی پر سوار تھی جس پر لوگوں کا کچھ سامان بھی لدا ہوا تھا ، اچانک اس نے نبی صلی اللہ علیہ وسلم کو دیکھا ، اس وقت پہاڑ ( کے درے نے ) گزرنے والوں کا راستہ تنگ کر دیا تھا ۔ اس باندی نے ( اونٹنی کو تیز کرنے کے لیے زور سے ) کہا : چل ( تیز چلو تاکہ رسول اللہ صلی اللہ علیہ وسلم کے قریب پہنچ جائیں ، جب وہ اونٹنی تیز نہ ہوئی تو کہنے لگی : ) اے اللہ! اس پر لعنت بھیج ( سیدنا ابوبرزہ اسلمی رضی اللہ عنہ نے ) کہا : تو نبی صلی اللہ علیہ وسلم نے فرمایا : \" وہ اونٹنی جس پر لعنت ہو ہمارے ساتھ ( شریک سفر ) نہ ہو ۔","",{"u2":"یزید بن زریع نے کہا: ہمیں تیمی نے ابوعثمان سے حدیث بیان کی، انہوں نے حضرت ابوبرزہ اسلمی رضی اللہ عنہ سے روایت کی کہ ایک باندی ایک اونٹنی پر سوار تھی جس پر لوگوں کا کچھ سامان بھی لدا ہوا تھا، اچانک اس نے نبی صلی اللہ علیہ وسلم کو دیکھا، اس وقت پہاڑ (کے درے نے) گزرنے والوں کا راستہ تنگ کر دیا تھا۔ اس باندی نے (اونٹنی کو تیز کرنے کے لیے زور سے) کہا: چل (تیز چلو تاکہ رسول اللہ صلی اللہ علیہ وسلم کے قریب پہنچ جائیں، جب وہ اونٹنی تیز نہ ہوئی تو کہنے لگی:) اے اللہ! اس پر لعنت بھیج (حضرت ابوبرزہ اسلمی رضی اللہ عنہ نے) کہا: تو نبی صلی اللہ علیہ وسلم نے فرمایا: \"وہ اونٹنی جس پر لعنت ہو ہمارے ساتھ (شریک سفر) نہ ہو۔\""}],[6650,"معتمر بن سلیمان اور یحیی بن سعید نے سلیمان تیمی سے اسی سند کے ساتھ حدیث بیان کی ، معتمر کی حدیث میں مزید یہ ہے ( کہ آپ صلی اللہ علیہ وسلم نے فرمایا : ) \" نہیں ، اللہ کی قسم! ایسی اونٹنی ہمارے ساتھ نہ رہے جس پر اللہ کی لعنت ہو ۔ \" یا آپ نے جن الفاظ میں فرمایا ۔","",{"u2":"معتمر بن سلیمان اور یحییٰ بن سعید نے سلیمان تیمی سے اسی سند کے ساتھ حدیث بیان کی، معتمر کی حدیث میں مزید یہ ہے (کہ آپ صلی اللہ علیہ وسلم نے فرمایا:) \"نہیں، اللہ کی قسم! ایسی اونٹنی ہمارے ساتھ نہ رہے جس پر اللہ کی لعنت ہو۔\" یا آپ نے جن الفاظ میں فرمایا۔"}],[6651,"سلیمان بن بلال نے مجھے خبر دی ، کہا : علاء بن عبدالرحمٰن سے روایت ہے ، انہوں نے اپنے والد سے حدیث بیان کی ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ایک صدیق کے شایان شان نہیں کہ وہ زیادہ لعنت کرنے والا ہو ۔","",{"u2":"سلیمان بن بلال نے مجھے خبر دی، کہا: علاء بن عبدالرحمٰن سے روایت ہے، انہوں نے اپنے والد سے حدیث بیان کی، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک صدیق کے شایان شان نہیں کہ وہ زیادہ لعنت کرنے والا ہو۔\""}],[6652,"محمد بن جعفر نے علاء بن عبدالرحمٰن سے اسی سند کے ساتھ اسی کے مانند روایت کی ۔","",{"u2":"محمد بن جعفر نے علاء بن عبدالرحمٰن سے اسی سند کے ساتھ اسی کے مانند روایت کی۔"}],[6653,"حفص بن میسرہ نے زید بن اسلم سے روایت کی کہ عبدالملک بن مروان نے سیدہ ام درداء رضی اللہ عنہا کو اپنی طرف سے گھر کا کچھ عمدہ سامان بھیجا ، پھر ایسا ہوا کہ ایک رات کو عبدالملک اٹھا ، اس نے اپنے خادم کو آواز دی ، غالبا اس نے دیر لگا دی تو عبدالملک نے اس پر لعنت کی ، جب اس ( عبدالملک ) نے صبح کی تو سیدہ ام درداء رضی اللہ عنہا نے کہا : میں نے رات کو سنا کہ جس وقت تم نے اپنے خادم کو بلایا تھا تو تم نے اس پر لعنت کی تھی ، پھر وہ کہنے لگیں : میں نے سیدنا ابودرداء رضی اللہ عنہ کو یہ کہتے ہوئے سنا تھا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" زیادہ لعنت کرنے والے قیامت کے دن نہ شفاعت کرنے والے ہوں گے ، نہ گواہ بنیں گے ۔","",{"u2":"حفص بن میسرہ نے زید بن اسلم سے روایت کی کہ عبدالملک بن مروان نے حضرت ام درداء رضی اللہ عنہا کو اپنی طرف سے گھر کا کچھ عمدہ سامان بھیجا، پھر ایسا ہوا کہ ایک رات کو عبدالملک اٹھا، اس نے اپنے خادم کو آواز دی، غالبا اس نے دیر لگا دی تو عبدالملک نے اس پر لعنت کی، جب اس (عبدالملک) نے صبح کی تو حضرت ام درداء رضی اللہ عنہا نے کہا: میں نے رات کو سنا کہ جس وقت تم نے اپنے خادم کو بلایا تھا تو تم نے اس پر لعنت کی تھی، پھر وہ کہنے لگیں: میں نے حضرت ابودرداء رضی اللہ عنہ کو یہ کہتے ہوئے سنا تھا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"زیادہ لعنت کرنے والے قیامت کے دن نہ شفاعت کرنے والے ہوں گے، نہ گواہ بنیں گے۔\""}],[6654,"معمر نے زید بن اسلم سے اسی سند سے حفص بن میسرہ کی حدیث کے ہم معنی روایت کی ۔","",{"u2":"معمر نے زید بن اسلم سے اسی سند سے حفص بن میسرہ کی حدیث کے ہم معنی روایت کی۔"}],[6655,"ہشام بن سعد نے زید بن اسلم اور ابوحازم سے روایت کی ، انہوں نے ام درداء رضی اللہ عنہ سے اور انہوں نے سیدنا ابودرداء رضی اللہ عنہ سے روایت کی ، کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا : \" بلاشبہ زیادہ لعنت کرنے والے قیامت کے روز نہ شہادت دینے والے ہوں گے اور نہ شفاعت کرنے والے ۔","",{"u2":"ہشام بن سعد نے زید بن اسلم اور ابوحازم سے روایت کی، انہوں نے ام درداء رضی اللہ عنہ سے اور انہوں نے حضرت ابودرداء رضی اللہ عنہ سے روایت کی، کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا: \"بلاشبہ زیادہ لعنت کرنے والے قیامت کے روز نہ شہادت دینے والے ہوں گے اور نہ شفاعت کرنے والے۔\""}],[6656,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے ، کہا : رسول اللہ صلی اللہ علیہ وسلم سے عرض کی گئی : اللہ کے رسول! مشرکین کے خلاف دعا کیجئے ۔ آپ نے فرمایا : \" مجھے لعنت کرنے والا بنا کر نہیں بھیجا گیا ، مجھے تو رحمت بنا کر بھیجا گیا ہے ۔"],[6657,"جریر نے اعمش سے ، انہوں نے ابوضحی سے ، انہوں نے مسروق سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم کے پاس دو شخص آئے ، مجھے معلوم نہیں کس معاملے میں انہوں نے آپ سے گفتگو کی اور آپ کو ناراض کر دیا ، آپ نے ان پر لعنت کی اور ان دونوں کو برا کہا ، جب وہ نکل کر چلے گئے تو میں نے عرض کی : کوئی شخص بھی جسے کوئی خیر ملی ہو ( وہ ) ان دونوں کو نہیں ملی ۔ آپ نے فرمایا : \" وہ کیسے؟ \" کہا : میں نے عرض کی : آپ نے ان کو لعنت کی اور برا کہا ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \" تمہیں علم نہیں ہے میں نے اپنے رب سے کیا شرط کی ہوئی ہے؟ میں نے کہا ہے : اے اللہ! میں صرف بشر ہوں ، لہٰذا میں جس مسلمان کو لعنت کروں یا برا کہوں تو اس ( لعنت اور برا بھلا کہنے ) کو اس کے لیے گناہوں سے پاکیزگی اور حصولِ اجر کا ذریعہ بنا دے ۔","",{"u2":"جریر نے اعمش سے، انہوں نے ابوضحیٰ سے، انہوں نے مسروق سے اور انہوں نے حضرت عائشہ رضی اللہ عنہا سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم کے پاس دو شخص آئے، مجھے معلوم نہیں کس معاملے میں انہوں نے آپ سے گفتگو کی اور آپ کو ناراض کر دیا، آپ نے ان پر لعنت کی اور ان دونوں کو برا کہا، جب وہ نکل کر چلے گئے تو میں نے عرض کی: کوئی شخص بھی جسے کوئی خیر ملی ہو (وہ) ان دونوں کو نہیں ملی۔ آپ نے فرمایا: \"وہ کیسے؟\" کہا: میں نے عرض کی: آپ نے ان کو لعنت کی اور برا کہا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"تمہیں علم نہیں ہے میں نے اپنے رب سے کیا شرط کی ہوئی ہے؟ میں نے کہا ہے: اے اللہ! میں صرف بشر ہوں، لہذا میں جس مسلمان کو لعنت کروں یا برا کہوں تو اس (لعنت اور برا بھلا کہنے) کو اس کے لیے گناہوں سے پاکیزگی اور حصولِ اجر کا ذریعہ بنا دے۔\""}],[6658,"ابومعاویہ اور عیسی بن یونس نے اعمش سے اسی سند کے ساتھ جریر کی حدیث کے مانند حدیث بیان کی ، اور عیسی ( بن یونس ) کی حدیث میں کہا : وہ دونوں رسول اللہ صلی اللہ علیہ وسلم سے علیحدگی میں ملے تو آپ نے انہیں برا بھلا کہا ، ان دونوں پر لعنت بھیجی اور ان کو نکال دیا ۔","",{"u2":"ابومعاویہ اور عیسیٰ بن یونس نے اعمش سے اسی سند کے ساتھ جریر کی حدیث کے مانند حدیث بیان کی، اور عیسیٰ (بن یونس) کی حدیث میں کہا: وہ دونوں رسول اللہ صلی اللہ علیہ وسلم سے علیحدگی میں ملے تو آپ نے انہیں برا بھلا کہا، ان دونوں پر لعنت بھیجی اور ان کو نکال دیا۔"}],[6659,"عبداللہ بن نمیر نے کہا : ہمیں اعمش نے ابوصالح سے حدیث بیان کی ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اے اللہ! میں صرف ایک بشر ہوں ، اس لیے میں جس مسلمان کو برا بھلا کہوں یا اس پر لعنت کروں یا اس کو کوڑے ماروں تو اسے اُس کے لیے پاکیزگی ( کا ذریعہ ) اور رحمت بنا دے ۔","",{"u2":") عبداللہ بن نمیر نے کہا: ہمیں اعمش نے ابوصالح سے حدیث بیان کی، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اے اللہ! میں صرف ایک بشر ہوں، اس لیے میں جس مسلمان کو برا بھلا کہوں یا اس پر لعنت کروں یا اس کو کوڑے ماروں تو اسے اُس کے لیے پاکیزگی (کا ذریعہ) اور رحمت بنا دے۔\""}],[6660,"عبداللہ بن نمیر نے کہا : ہمیں اعمش نے ابوسفیان سے حدیث بیان کی ، انہوں نے سیدنا جابر رضی اللہ عنہ سے ، انہوں نے نبی صلی اللہ علیہ وسلم سے اسی حدیث کے مانند روایت کی مگر اس میں \" پاکیزگی اور اجر \" کے الفاظ ہیں ۔","",{"u2":"عبداللہ بن نمیر نے کہا: ہمیں اعمش نے ابوسفیان سے حدیث بیان کی، انہوں نے حضرت جابر رضی اللہ عنہ سے، انہوں نے نبی صلی اللہ علیہ وسلم سے اسی حدیث کے مانند روایت کی مگر اس میں \"پاکیزگی اور اجر\" کے الفاظ ہیں۔"}],[6661,"ابومعاویہ اور عیسی بن یونس نے اعمش سے عبداللہ بن نمیر کی سند کے ساتھ اسی کی حدیث کے مانند حدیث بیان کی ، مگر عیسی کی روایت میں ابوہریرہ رضی اللہ عنہ کی حدیث میں \" بنا دے \" اور \" اجر \" کے لفظ ہیں اور جابر رضی اللہ عنہ کی حدیث میں اور \" بنا دے \" اور \" رحمت \" کے لفظ ہیں ۔","",{"u2":"ابومعاویہ اور عیسیٰ بن یونس نے اعمش سے عبداللہ بن نمیر کی سند کے ساتھ اسی کی حدیث کے مانند حدیث بیان کی، مگر عیسیٰ کی روایت میں ابوہریرہ رضی اللہ عنہ کی حدیث میں \"بنا دے\" اور \"اجر\" کے لفظ ہیں اور جابر رضی اللہ عنہ کی حدیث میں اور \"بنا دے\" اور \"رحمت\" کے لفظ ہیں۔"}],[6662,"مغیرہ بن عبدالرحمٰن حزامی نے ہمیں ابوزناد سے حدیث بیان کی ، انہوں نے اعرج سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے ( دعا کرتے ہوئے ) فرمایا : \" اے اللہ! میں تجھ سے عہد لیتا ہوں جس میں تو میرے ساتھ ہرگز خلاف ورزی نہیں فرمائے گا کہ میں ایک بشر ہی ہوں ، میں جس کسی مومن کو تکلیف پہنچاؤں ، اسے برا بھلا کہوں ، اس پر لعنت کروں ، اسے کوڑے ماروں تو ان تمام باتوں کو قیامت کے دن اس کے لیے رحمت ، پاکیزگی اور ایسی قربت بنا دے جس کے ذریعے سے تو اسے اپنا قرب عطا فرمائے ۔","",{"u2":"مغیرہ بن عبدالرحمٰن حزامی نے ہمیں ابوزناد سے حدیث بیان کی، انہوں نے اعرج سے اور انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے (دعا کرتے ہوئے) فرمایا: \"اے اللہ! میں تجھ سے عہد لیتا ہوں جس میں تو میرے ساتھ ہرگز خلاف ورزی نہیں فرمائے گا کہ میں ایک بشر ہی ہوں، میں جس کسی مومن کو تکلیف پہنچاؤں، اسے برا بھلا کہوں، اس پر لعنت کروں، اسے کوڑے ماروں تو ان تمام باتوں کو قیامت کے دن اس کے لیے رحمت، پاکیزگی اور ایسی قربت بنا دے جس کے ذریعے سے تو اسے اپنا قرب عطا فرمائے۔\""}],[6663,"ابوزناد نے ہمیں اسی سند کے ساتھ یہ روایت بیان کی ، البتہ انہوں نے \"\" او جلدة \"\" کہا ۔ ابوزناد نے کہا : یہ ابوہریرہ رضی اللہ عنہ کی زبان ہے ۔ ( قریش کی زبان میں ) یہ لفظ \"\" جلدته \"\" ہی ہے ۔ ( معنی ایک ہی ہے ، یعنی جسے میں کوڑے ماروں ۔)","",{"u2":"ابوزناد نے ہمیں اسی سند کے ساتھ یہ روایت بیان کی، البتہ انہوں نے \"او جلدۃ\" کہا۔\nابوزناد نے کہا: یہ ابوہریرہ رضی اللہ عنہ کی زبان ہے۔ (قریش کی زبان میں) یہ لفظ \"جلدتہ\" ہی ہے۔ (معنی ایک ہی ہے، یعنی جسے میں کوڑے ماروں۔)"}],[6664,"ایوب نے عبدالرحمٰن اعرج سے ، انہوں نے ابوہریرہ رضی اللہ عنہ سے ، انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند حدیث بیان کی ۔","",{"u2":"ایوب نے عبدالرحمٰن اعرج سے، انہوں نے ابوہریرہ رضی اللہ عنہ سے، انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند حدیث بیان کی۔"}],[6665,"نصریوں کے آزاد کردہ غلام سالم نے کہا : میں نے سیدنا ابوہریرہ رضی اللہ عنہ کو کہتے ہوئے سنا ، کہہ رہے تھے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ ( دعا کرتے ہوئے ) فرما رہے تھے : \" اے اللہ! محمد ایک بشر ہی ہے ، جس طرح ایک بشر کو غصہ آتا ہے ، اسے بھی غصہ آتا ہے اور میں تیرے حضور ایک وعدہ لیتا ہوں جس میں تو میرے ساتھ ہرگز خلاف ورزی نہیں فرمائے گا کہ جس مومن کو بھی میں نے تکلیف پہنچائی ، اسے برا بھلا کہا یا کوڑے سے مارا تو اس سب کچھ کو اس کے لیے گناہوں کا کفارہ بنا دینا اور ایسی قربت میں بدل دینا جس کے ذریعے سے قیامت کے دن تو اسے اپنا قرب عطا فرمائے ۔","",{"u2":"نصریوں کے آزاد کردہ غلام سالم نے کہا: میں نے حضرت ابوہریرہ رضی اللہ عنہ کو کہتے ہوئے سنا، کہہ رہے تھے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ (دعا کرتے ہوئے) فرما رہے تھے: \"اے اللہ! محمد ایک بشر ہی ہے، جس طرح ایک بشر کو غصہ آتا ہے، اسے بھی غصہ آتا ہے اور میں تیرے حضور ایک وعدہ لیتا ہوں جس میں تو میرے ساتھ ہرگز خلاف ورزی نہیں فرمائے گا کہ جس مومن کو بھی میں نے تکلیف پہنچائی، اسے برا بھلا کہا یا کوڑے سے مارا تو اس سب کچھ کو اس کے لیے گناہوں کا کفارہ بنا دینا اور ایسی قربت میں بدل دینا جس کے ذریعے سے قیامت کے دن تو اسے اپنا قرب عطا فرمائے۔\""}],[6666,"یونس نے ابن شہاب سے روایت کی ، انہوں نے کہا : مجھے سعید بن مسیب نے سیدنا ابوہریرہ رضی اللہ عنہ سے خبر دی کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ ( دعا کرتے ہوئے ) فرما رہے تھے : \" اے اللہ! میں جس بندہ مومن کو برا بھلا کہوں تو اس کے لیے اسے قیامت کے دن اپنی قربت میں بدل دینا ۔","",{"u2":"یونس نے ابن شہاب سے روایت کی، انہوں نے کہا: مجھے سعید بن مسیب نے حضرت ابوہریرہ رضی اللہ عنہ سے خبر دی کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ (دعا کرتے ہوئے) فرما رہے تھے: \"اے اللہ! میں جس بندہ مومن کو برا بھلا کہوں تو اس کے لیے اسے قیامت کے دن اپنی قربت میں بدل دینا۔\""}],[6667,"ابن شہاب کے بھتیجے نے اپنے چچا سے روایت کی ، انہوں نے کہا : مجھے سعید بن مسیب نے سیدنا ابوہریرہ رضی اللہ عنہ سے حدیث بیان کی کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ ( دعا کرتے ہوئے ) فرما رہے تھے : \" اے اللہ! میں نے تیرے حضور پختہ عہد لیا ہے جس میں تو میرے ساتھ ہرگز خلاف ورزی نہیں فرمائے گا کہ کوئی بھی مومن جسے میں نے تکلیف پہنچائی ہو یا اسے برا بھلا کہا ہو یا اسے کوڑے سے مارا ہو ، اسے تو قیامت کے دن اس کے لیے ( گناہوں کا ) کفارہ بنا دینا ۔","",{"u2":"ابن شہاب کے بھتیجے نے اپنے چچا سے روایت کی، انہوں نے کہا: مجھے سعید بن مسیب نے حضرت ابوہریرہ رضی اللہ عنہ سے حدیث بیان کی کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ (دعا کرتے ہوئے) فرما رہے تھے: \"اے اللہ! میں نے تیرے حضور پختہ عہد لیا ہے جس میں تو میرے ساتھ ہرگز خلاف ورزی نہیں فرمائے گا کہ کوئی بھی مومن جسے میں نے تکلیف پہنچائی ہو یا اسے برا بھلا کہا ہو یا اسے کوڑے سے مارا ہو، اسے تو قیامت کے دن اس کے لیے (گناہوں کا) کفارہ بنا دینا۔\""}],[6668,"حجاج بن محمد نے کہا : ابن جریج نے کہا : مجھے ابوزبیر نے بتایا ، انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ کو یہ کہتے ہوئے سنا کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے یہ سنا ، آپ فرماتے تھے : \" میں ایک بشر ہی ہوں اور میں نے اپنے رب عزوجل سے یہ عہد لیا ہے کہ میں مسلمانوں میں سے جس بندے کو سب و شتم کروں تو یہ سب کچھ اس کے لیے پاکیزگی اور اجر ( کا سبب ) بن جائے ۔","",{"u2":"حجاج بن محمد نے کہا: ابن جریج نے کہا: مجھے ابوزبیر نے بتایا، انہوں نے حضرت جابر بن عبداللہ رضی اللہ عنہ کو یہ کہتے ہوئے سنا کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے یہ سنا، آپ فرماتے تھے: \"میں ایک بشر ہی ہوں اور میں نے اپنے رب عزوجل سے یہ عہد لیا ہے کہ میں مسلمانوں میں سے جس بندے کو سب و شتم کروں تو یہ سب کچھ اس کے لیے پاکیزگی اور اجر (کا سبب) بن جائے۔\""}],[6669,"حجاج بن محمد نے کہا : ابن جریج نے کہا : مجھے ابوزبیر نے بتایا ، انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ کو یہ کہتے ہوئے سنا کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے یہ سنا ، آپ فرماتے تھے : \" میں ایک بشر ہی ہوں اور میں نے اپنے رب عزوجل سے یہ عہد لیا ہے کہ میں مسلمانوں میں سے جس بندے کو سب و شتم کروں تو یہ سب کچھ اس کے لیے پاکیزگی اور اجر ( کا سبب ) بن جائے ۔","",{"u2":"روح اور ابوعاصم دونوں نے ہمیں ابن جریج سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی۔"}],[6670,"زہیر بن حرب اور ابومعن رقاشی نے ہمیں حدیث بیان کی ۔ ۔ اور الفاظ زہیر کے ہیں ۔ ۔ دونوں نے کہا : ہمیں عمر بن یونس نے حدیث بیان کی ، انہوں نے کہا : ہمیں عکرمہ بن عمار نے حدیث بیان کی ، کہا : ہمیں اسحق بن ابی طلحہ نے حدیث سنائی ، انہوں نے کہا : مجھے سیدنا انس بن مالک رضی اللہ عنہ نے بیان کیا کہ سیدہ ام سلیم رضی اللہ عنہا کے پاس ایک یتیم لڑکی تھی اور یہی ( ام سلیم رضی اللہ عنہا ) ام انس بھی کہلاتی تھیں ، رسول اللہ صلی اللہ علیہ وسلم نے اس کو دیکھا تو فرمایا : \"\" تو وہی لڑکی ہے ، تو بڑی ہو گئی ہے! تیری عمر ( اس تیزی سے ) بڑی نہ ہو \"\" وہ لڑکی روتی ہوئی واپس سیدہ ام سلیم رضی اللہ عنہا کے پاس گئی ، سیدہ ام سلیم رضی اللہ عنہا نے پوچھا : بیٹی! تجھے کیا ہوا؟ اس نے کہا : نبی صلی اللہ علیہ وسلم نے میرے خلاف دعا فرما دی ہے کہ میری عمر زیادہ نہ ہو ، اب میری عمر کسی صورت زیادہ نہ ہو گی ، یا کہا : اب میرا زمانہ ہرگز زیادہ نہیں ہو گا ، سیدہ ام سلیم رضی اللہ عنہا جلدی سے دوپٹہ لپیٹتے ہوئے نکلیں ، حتی کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوئیں ، رسول اللہ صلی اللہ علیہ وسلم نے ان سے پوچھا : \"\" ام سلیم! کیا بات ہے؟ \"\" سیدہ ام سلیم رضی اللہ عنہا نے کہا : اللہ کے نبی! کیا آپ نے میری ( پالی ہوئی ) یتیم لڑکی کے خلاف دعا کی ہے؟ آپ نے پوچھا : \"\" یہ کیا بات ہے؟ \"\" سیدہ ام سلیم رضی اللہ عنہا نے کہا : وہ کہتی ہے : آپ نے دعا فرمائی ہے کہ اس کی عمر زیادہ نہ ہو ، اور اس کا زمانہ لمبا نہ ہو ، ( سیدنا انس رضی اللہ عنہ نے ) کہا : تو رسول اللہ صلی اللہ علیہ وسلم ہنسے ، پھر فرمایا : \"\" ام سلیم! کیا تمہیں معلوم نہیں کہ میں نے اپنے رب سے پختہ عہد لیا ہے ، میں نے کہا : میں ایکبشر ہی ہوں ، جس طرح ایک بشر خوش ہوتا ہے ، میں بھی خوش ہوتا ہوں اور جس طرح بشر ناراض ہوتے ہیں میں بھی ناراض ہوتا ہوں ۔ تو میری امت میں سے کوئی بھی آدمی جس کے خلاف میں نے دعا کی اور وہ اس کا مستحق نہ تھا تو اس دعا کو قیامت کے دن اس کے لیے پاکیزگی ، گناہوں سے صفائی اور ایسی قربت بنا دے جس کے ذریعے سے تو اسے اپنے قریب فرما لے ۔ \"\" ابو معن نے کہا : حدیث میں تینوں جگہ ( یتیمہ کے بجائے ) تصغیر کے ساتھ يتيمة ( چھوٹی سی یتیم بچی کا لفظ ) ہے ۔","",{"u2":") زہیر بن حرب اور ابومعن رقاشی نے ہمیں حدیث بیان کی۔۔ اور الفاظ زہیر کے ہیں۔۔ دونوں نے کہا: ہمیں عمر بن یونس نے حدیث بیان کی، انہوں نے کہا: ہمیں عکرمہ بن عمار نے حدیث بیان کی، کہا: ہمیں اسحق بن ابی طلحہ نے حدیث سنائی، انہوں نے کہا: مجھے حضرت انس بن مالک رضی اللہ عنہ نے بیان کیا کہ حضرت ام سلیم رضی اللہ عنہا کے پاس ایک یتیم لڑکی تھی اور یہی (ام سلیم رضی اللہ عنہا) ام انس بھی کہلاتی تھیں، رسول اللہ صلی اللہ علیہ وسلم نے اس کو دیکھا تو فرمایا: \"تو وہی لڑکی ہے، تو بڑی ہو گئی ہے! تیری عمر (اس تیزی سے) بڑی نہ ہو\" وہ لڑکی روتی ہوئی واپس حضرت ام سلیم رضی اللہ عنہا کے پاس گئی، حضرت ام سلیم رضی اللہ عنہا نے پوچھا: بیٹی! تجھے کیا ہوا؟ اس نے کہا: نبی صلی اللہ علیہ وسلم نے میرے خلاف دعا فرما دی ہے کہ میری عمر زیادہ نہ ہو، اب میری عمر کسی صورت زیادہ نہ ہو گی، یا کہا: اب میرا زمانہ ہرگز زیادہ نہیں ہو گا، حضرت ام سلیم رضی اللہ عنہا جلدی سے دوپٹہ لپیٹتے ہوئے نکلیں، حتی کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوئیں، رسول اللہ صلی اللہ علیہ وسلم نے ان سے پوچھا: \"ام سلیم! کیا بات ہے؟\" حضرت ام سلیم رضی اللہ عنہا نے کہا: اللہ کے نبی! کیا آپ نے میری (پالی ہوئی) یتیم لڑکی کے خلاف دعا کی ہے؟ آپ نے پوچھا: \"یہ کیا بات ہے؟\" حضرت ام سلیم رضی اللہ عنہا نے کہا: وہ کہتی ہے: آپ نے دعا فرمائی ہے کہ اس کی عمر زیادہ نہ ہو، اور اس کا زمانہ لمبا نہ ہو، (حضرت انس رضی اللہ عنہ نے) کہا: تو رسول اللہ صلی اللہ علیہ وسلم ہنسے، پھر فرمایا: \"ام سلیم! کیا تمہیں معلوم نہیں کہ میں نے اپنے رب سے پختہ عہد لیا ہے، میں نے کہا: میں ایکبشر ہی ہوں، جس طرح ایک بشر خوش ہوتا ہے، میں بھی خوش ہوتا ہوں اور جس طرح بشر ناراض ہوتے ہیں میں بھی ناراض ہوتا ہوں۔ تو میری امت میں سے کوئی بھی آدمی جس کے خلاف میں نے دعا کی اور وہ اس کا مستحق نہ تھا تو اس دعا کو قیامت کے دن اس کے لیے پاکیزگی، گناہوں سے صفائی اور ایسی قربت بنا دے جس کے ذریعے سے تو اسے اپنے قریب فرما لے۔\"\nابو معن نے کہا: حدیث میں تینوں جگہ (یتیمہ کے بجائے) تصغیر کے ساتھ یتیمۃ (چھوٹی سی یتیم بچی کا لفظ) ہے۔"}],[6671,"محمد بن مثنی عنزی اور ابن بشار نے ہمیں حدیث بیان کی ۔ ۔ الفاظ ابن مثنی کے ہیں ۔ ۔ دونوں نے کہا : ہمیں امیہ بن خالد نے حدیث بیان کی ، انہوں نے کہا : ہمیں شعبہ نے ابوحمزہ قصاب سے حدیث بیان کی ، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی ، کہا : میں لڑکوں کے ساتھ کھیل رہا تھا کہ اچانک رسول اللہ صلی اللہ علیہ وسلم تشریف لے آئے ، میں دروازے کے پیچھے چھپ گیا ، کہا : آپ آئے اور میرے دونوں شانوں کے درمیان اپنے کھلے ہاتھ سے ہلکی سی ضرب لگائی ( مقصود پیار کا اظہار تھا ) اور فرمایا : \" جاؤ ، میرے لیے معاویہ کو بلا لاؤ ۔ \" میں نے آپ سے آ کر کہا : وہ کھانا کھا رہے ہیں ۔ آپ نے دوبارہ مجھ سے فرمایا : \" جاؤ ، معاویہ کو بلا لاؤ ۔ \" میں نے پھر آ کر کہا : وہ کھانا کھا رہے ہیں ، تو آپ نے فرمایا : \" اللہ اس کا پیٹ نہ بھرے ۔","",{"u2":"محمد بن مثنیٰ عنزی اور ابن بشار نے ہمیں حدیث بیان کی۔۔ الفاظ ابن مثنیٰ کے ہیں۔۔ دونوں نے کہا: ہمیں امیہ بن خالد نے حدیث بیان کی، انہوں نے کہا: ہمیں شعبہ نے ابوحمزہ قصاب سے حدیث بیان کی، انہوں نے حضرت ابن عباس رضی اللہ عنہ سے روایت کی، کہا: میں لڑکوں کے ساتھ کھیل رہا تھا کہ اچانک رسول اللہ صلی اللہ علیہ وسلم تشریف لے آئے، میں دروازے کے پیچھے چھپ گیا، کہا: آپ آئے اور میرے دونوں شانوں کے درمیان اپنے کھلے ہاتھ سے ہلکی سی ضرب لگائی (مقصود پیار کا اظہار تھا) اور فرمایا: \"جاؤ، میرے لیے معاویہ کو بلا لاؤ۔\" میں نے آپ سے آ کر کہا: وہ کھانا کھا رہے ہیں۔ آپ نے دوبارہ مجھ سے فرمایا: \"جاؤ، معاویہ کو بلا لاؤ۔\" میں نے پھر آ کر کہا: وہ کھانا کھا رہے ہیں، تو آپ نے فرمایا: \"اللہ اس کا پیٹ نہ بھرے۔\""}],[6672,"نضر بن شمیل نے کہا : ہمیں شعبہ نے حدیث بیان کی ، انہوں نے کہا : ہمیں ابوحمزہ نے خبر دی کہ میں نے سیدنا ابن عباس رضی اللہ عنہ سے سنا ، کہتے تھے : میں بچوں کے ساتھ کھیل رہا تھا ، رسول اللہ صلی اللہ علیہ وسلم تشریف لے آئے تو میں آپ سے چھپ گیا ۔ آگے اسی ( سابقہ حدیث ) کی طرح بیان کیا ۔","",{"u2":"نضر بن شمیل نے کہا: ہمیں شعبہ نے حدیث بیان کی، انہوں نے کہا: ہمیں ابوحمزہ نے خبر دی کہ میں نے حضرت ابن عباس رضی اللہ عنہ سے سنا، کہتے تھے: میں بچوں کے ساتھ کھیل رہا تھا، رسول اللہ صلی اللہ علیہ وسلم تشریف لے آئے تو میں آپ سے چھپ گیا۔ آگے اسی (سابقہ حدیث) کی طرح بیان کیا۔"}],[6673,"اعرج نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" بدترین انسانوں میں سے دو رخا شخص ( بھی ) ہوتا ہے ۔ وہ ان لوگوں سے ایک چہرے کے ساتھ ملتا ہے اور ان لوگوں سے دوسرے چہرے کے ساتھ ملتا ہے ۔","",{"u2":"اعرج نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بدترین انسانوں میں سے دو رخا شخص (بھی) ہوتا ہے۔ وہ ان لوگوں سے ایک چہرے کے ساتھ ملتا ہے اور ان لوگوں سے دوسرے چہرے کے ساتھ ملتا ہے۔\""}],[6674,"اعراک بن مالک نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا : \" لوگوں میں سے بدترین شخص دو چہروں والا ہوتا ہے ، جو ان لوگوں کے پاس ایک چہرے سے آتا ہے اور اُن لوگوں کے پاس دوسرے چہرے سے آتا ہے ۔","",{"u2":"اعراک بن مالک نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"لوگوں میں سے بدترین شخص دو چہروں والا ہوتا ہے، جو ان لوگوں کے پاس ایک چہرے سے آتا ہے اور اُن لوگوں کے پاس دوسرے چہرے سے آتا ہے۔\""}],[6675,"سعید بن مسیب اور ابوزرعہ نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تم لوگوں میں سے بدترین شخص اسے پاؤ گے جس کے دو چہرے ہیں ، ان کے پاس ایک چہرہ لے کر آتا ہے اور اُن کے پاس دوسرا چہرہ لے کر آتا ہے ۔"],[6676,"سعید بن مسیب اور ابوزرعہ نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تم لوگوں میں سے بدترین شخص اسے پاؤ گے جس کے دو چہرے ہیں ، ان کے پاس ایک چہرہ لے کر آتا ہے اور اُن کے پاس دوسرا چہرہ لے کر آتا ہے ۔","",{"u2":"سعید بن مسیب اور ابوزرعہ نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم لوگوں میں سے بدترین شخص اسے پاؤ گے جس کے دو چہرے ہیں، ان کے پاس ایک چہرہ لے کر آتا ہے اور اُن کے پاس دوسرا چہرہ لے کر آتا ہے۔\""}],[6677,"یونس نے ابن شہاب سے روایت کی ، انہوں نے کہا : مجھے حمید بن عبدالرحمان بن عوف نے خبر دی کہ ان کی والدہ سیدہ ام کلثوم بنت عقبہ بن ابی معیط رضی اللہ عنہ نبی صلی اللہ علیہ وسلم کے ساتھ بیعت کرنے والی ان خواتین میں سے تھیں جنہوں نے سب سے پہلے ہجرت کی ۔ انہوں نے اسے ( اپنے بیٹے کو ) خبر دی کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ فرما رہے تھے : \"\" وہ شخص جھوٹا نہیں جو لوگوں میں صلح کرائے اور اچھی بات کہے اور اچھی بات پہنچائے ۔ \"\" ابن شہاب نے کہا : لوگ جو جھوٹی باتیں کرتے ہیں ، میں نے ان میں سے تین کے سوا کسی بات کے بارے میں نہیں سنا کہ ان کی اجازت دی گئی ہے : جنگ اور جہاد میں ، لوگوں کے درمیان صلح کرانے کے لیے اور خاوند کا اپنی بیوی سے ( اسے راضی کرنے کی ) بات اور عورت کی اپنے خاوند سے ( اسے راضی کرنے کے لیے ) بات ۔","",{"u2":"یونس نے ابن شہاب سے روایت کی، انہوں نے کہا: مجھے حمید بن عبدالرحمان بن عوف نے خبر دی کہ ان کی والدہ حضرت ام کلثوم بنت عقبہ بن ابی معیط رضی اللہ عنہ نبی صلی اللہ علیہ وسلم کے ساتھ بیعت کرنے والی ان خواتین میں سے تھیں جنہوں نے سب سے پہلے ہجرت کی۔ انہوں نے اسے (اپنے بیٹے کو) خبر دی کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ فرما رہے تھے: \"وہ شخص جھوٹا نہیں جو لوگوں میں صلح کرائے اور اچھی بات کہے اور اچھی بات پہنچائے۔\"\nابن شہاب نے کہا: لوگ جو جھوٹی باتیں کرتے ہیں، میں نے ان میں سے تین کے سوا کسی بات کے بارے میں نہیں سنا کہ ان کی اجازت دی گئی ہے: جنگ اور جہاد میں، لوگوں کے درمیان صلح کرانے کے لیے اور خاوند کا اپنی بیوی سے (اسے راضی کرنے کی) بات اور عورت کی اپنے خاوند سے (اسے راضی کرنے کے لیے) بات۔\""}],[6678,"صالح نے کہا : ہمیں محمد بن مسلم بن عبیداللہ بن عبداللہ بن شہاب نے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی ، مگر صالح کی حدیث میں ہے : اور ( ام کلثوم بنت عقبہ رضی اللہ عنہا نے ) کہا : میں نے آپ سے نہیں سنا کہ لوگ جو باتیں کرتے ہیں آپ نے ان میں سے تین کے سوا کسی بات کی اجازت دی ہو ۔ ( آگے ) اسی کے مانند جس طرح یونس نے ابن شہاب کا قول بتایا ہے ۔","",{"u2":"صالح نے کہا: ہمیں محمد بن مسلم بن عبیداللہ بن عبداللہ بن شہاب نے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی، مگر صالح کی حدیث میں ہے: اور (ام کلثوم بنت عقبہ رضی اللہ عنہا نے) کہا: میں نے آپ سے نہیں سنا کہ لوگ جو باتیں کرتے ہیں آپ نے ان میں سے تین کے سوا کسی بات کی اجازت دی ہو۔ (آگے) اسی کے مانند جس طرح یونس نے ابن شہاب کا قول بتایا ہے۔"}],[6679,"معمر نے ہمیں زہری سے اسی سند کے ساتھ آپ کے اس فرمان تک خبر دی : \" اور اچھی بات پہنچائی \" اور اس کے بعد کا حصہ بیان نہیں کیا ۔","",{"u2":"معمر نے ہمیں زہری سے اسی سند کے ساتھ آپ کے اس فرمان تک خبر دی: \"اور اچھی بات پہنچائی\" اور اس کے بعد کا حصہ بیان نہیں کیا۔"}],[6680,"سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے ، کہا : محمد صلی اللہ علیہ وسلم نے فرمایا : \" کیا میں تم کو یہ نہ بتاؤں کہ بدترین حرام کیا ہے؟ یہ چغلی ہے جو لوگوں کی زبان پر رواں ہو جاتی ہے ۔ \" اور محمد صلی اللہ علیہ وسلم نے فرمایا : \" انسان سچ بولتا رہتا ہے یہاں تک کہ ( اللہ تعالی کے ہاں ) وہ صدیق لکھ دیا جاتا ہے اور جھوٹ بولتا رہتا ہے حتی کہ اس کو کذاب لکھ دیا جاتا ہے ۔","",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے، کہا: محمد صلی اللہ علیہ وسلم نے فرمایا: \"کیا میں تم کو یہ نہ بتاؤں کہ بدترین حرام کیا ہے؟ یہ چغلی ہے جو لوگوں کی زبان پر رواں ہو جاتی ہے۔\" اور محمد صلی اللہ علیہ وسلم نے فرمایا: \"انسان سچ بولتا رہتا ہے یہاں تک کہ (اللہ تعالیٰ کے ہاں) وہ صدیق لکھ دیا جاتا ہے اور جھوٹ بولتا رہتا ہے حتی کہ اس کو کذاب لکھ دیا جاتا ہے۔\""}],[6681,"جریر نے منصور سے ، انہوں نے ابووائل ( شقیق ) سے ، انہوں نے سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" سچ نیکی اور اچھائی کے راستے پر لے جاتا ہے اور نیکی جنت کی طرف لے جاتی ہے ، ایک آدمی سچ بولتا رہتا ہے حتی کہ وہ اللہ کے ہاں صدیق لکھ دیا جاتا ہے اور جھوٹ فسق و فجور کی طرف لے جاتا ہے اور فسق و فجور ( جہنم کی ) آگ کی طرف لے جاتا ہے اور ایک آدمی جھوٹ بولتا رہتا ہے ، یہاں تک کہ اللہ تعالی کے نزدیک اسے کذاب لکھ دیا جاتا ہے ۔","",{"u2":"جریر نے منصور سے، انہوں نے ابووائل (شقیق) سے، انہوں نے حضرت عبداللہ بن مسعود رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سچ نیکی اور اچھائی کے راستے پر لے جاتا ہے اور نیکی جنت کی طرف لے جاتی ہے، ایک آدمی سچ بولتا رہتا ہے حتی کہ وہ اللہ کے ہاں صدیق لکھ دیا جاتا ہے اور جھوٹ فسق و فجور کی طرف لے جاتا ہے اور فسق و فجور (جہنم کی) آگ کی طرف لے جاتا ہے اور ایک آدمی جھوٹ بولتا رہتا ہے، یہاں تک کہ اللہ تعالیٰ کے نزدیک اسے کذاب لکھ دیا جاتا ہے۔\""}],[6682,"ابوبکر بن ابی شیبہ اور ہناد بن سری نے کہا : ہمیں ابواحوص نے منصور سے حدیث بیان کی ، انہوں نے ابوائل سے اور انہوں نے سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" سچ نیکی ہے اور نیکی جنت کی طرف رہنمائی کرتی ہے اور بندہ پوری کوشش سے سچ ہی کا قصد کرتا رہتا ہے حتی کہ وہ اللہ تعالی کے نزدیک صدیق لکھ دیا جاتا ہے اور جھوٹ کج روی ہے اور کج روی جہنم کی طرف لے جاتی ہے اور بندہ جھوٹ بولنے کا قصد ہوتا رہتا ہے حتی کہ اسے جھوٹا لکھ دیا جاتا ہے ۔ \"\" ابن ابی شیبہ کی روایت میں ( \"\" رسول اللہ صلی اللہ علیہ وسلم نے فرمایا \"\" کے بجائے ) \"\" نبی صلی اللہ علیہ وسلم سے روایت ہے \"\" کے الفاظ ہیں ۔","",{"u2":"ابوبکر بن ابی شیبہ اور ہناد بن سری نے کہا: ہمیں ابواحوص نے منصور سے حدیث بیان کی، انہوں نے ابوائل سے اور انہوں نے حضرت عبداللہ بن مسعود رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سچ نیکی ہے اور نیکی جنت کی طرف رہنمائی کرتی ہے اور بندہ پوری کوشش سے سچ ہی کا قصد کرتا رہتا ہے حتی کہ وہ اللہ تعالیٰ کے نزدیک صدیق لکھ دیا جاتا ہے اور جھوٹ کج روی ہے اور کج روی جہنم کی طرف لے جاتی ہے اور بندہ جھوٹ بولنے کا قصد ہوتا رہتا ہے حتی کہ اسے جھوٹا لکھ دیا جاتا ہے۔\"\nابن ابی شیبہ کی روایت میں (\"رسول اللہ صلی اللہ علیہ وسلم نے فرمایا\" کے بجائے) \"نبی صلی اللہ علیہ وسلم سے روایت ہے\" کے الفاظ ہیں۔"}],[6683,"ابومعاویہ اور وکیع نے کہا : ہمیں اعمش نے شقیق ( ابووائل ) سے حدیث بیان کی ، انہوں نے سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تم صدق پر قائم رہو کیونکہ صدق نیکی کے راستے پر چلاتا ہے اور نیکی جنت کے راستے پر چلاتی ہے ۔ انسان مسلسل سچ بولتا رہتا ہے اور کوشش سے سچ پر قائم رہتا ہے ، حتی کہ وہ اللہ کے ہاں سچا لکھ لیا جاتا ہے اور جھوٹ سے دور رہو کیونکہ جھوٹ کج روی کے راستے پر چلاتا ہے اور کج روی آگ کی طرف لے جاتی ہے ، انسان مسلسل جھوٹ بولتا رہتا ہے اور جھوٹ کا قصد کرتا رہتا ہے یہاں تک کہ اللہ تعالی کے نزدیک اسے جھوٹا لکھ لیا جاتا ہے ۔","",{"u2":"ابومعاویہ اور وکیع نے کہا: ہمیں اعمش نے شقیق (ابووائل) سے حدیث بیان کی، انہوں نے حضرت عبداللہ بن مسعود رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم صدق پر قائم رہو کیونکہ صدق نیکی کے راستے پر چلاتا ہے اور نیکی جنت کے راستے پر چلاتی ہے۔ انسان مسلسل سچ بولتا رہتا ہے اور کوشش سے سچ پر قائم رہتا ہے، حتی کہ وہ اللہ کے ہاں سچا لکھ لیا جاتا ہے اور جھوٹ سے دور رہو کیونکہ جھوٹ کج روی کے راستے پر چلاتا ہے اور کج روی آگ کی طرف لے جاتی ہے، انسان مسلسل جھوٹ بولتا رہتا ہے اور جھوٹ کا قصد کرتا رہتا ہے یہاں تک کہ اللہ تعالیٰ کے نزدیک اسے جھوٹا لکھ لیا جاتا ہے۔\""}],[6684,"ابن مسہر اور عیسی بن یونس دونوں نے اعمش سے اسی سند کے ساتھ خبر دی ، انہوں نے عیسی کی روایت میں : \" صدق کا قصد کرتا رہتا ہے اور جھوٹ کا قصد کرتا رہتا ہے \" کے الفاظ ذکر نہیں کیے ۔ اور ابن مسہر کی روایت میں ( \" اللہ کے نزدیک \" کے بجائے ) \" حتی کہ اللہ اس کو لکھ لیتا ہے \" کے الفاظ ہیں ۔","",{"u2":"ابن مسہر اور عیسیٰ بن یونس دونوں نے اعمش سے اسی سند کے ساتھ خبر دی، انہوں نے عیسیٰ کی روایت میں: \"صدق کا قصد کرتا رہتا ہے اور جھوٹ کا قصد کرتا رہتا ہے\" کے الفاظ ذکر نہیں کیے۔ اور ابن مسہر کی روایت میں (\"اللہ کے نزدیک\" کے بجائے) \"حتی کہ اللہ اس کو لکھ لیتا ہے\" کے الفاظ ہیں۔"}],[6685,"جریر نے ہمیں اعمش سے حدیث بیان کی ، انہوں نے ابراہیم تیمی سے ، انہوں نے حارث بن سوید سے ، انہوں نے سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تم لوگ اپنے خیال میں رقوب کسے شمار کرتے ہو؟ ہم نے عرض کی : جس شخص کے بچے پیدا نہ ہوتے ہوں ۔ آپ نے فرمایا : \" یہ رقوب نہیں ہے ، بلکہ رقوب وہ شخص ہے جس نے ( آخرت میں ) کسی بچے کو آگے نہ بھیجا ہو ۔ \" آپ نے فرمایا : \" تم اپنے خیال میں پہلوان کسے سمجھتے ہو؟ \" ہم نے کہا : جس کو لوگ پچھاڑ نہ سکیں ۔ آپ نے فرمایا : \" پہلوان وہ نہیں ہے ، بلکہ پہلوان تو وہ شخص ہے جو غصے کے وقت خود پر قابو رکھتا ہے ۔","",{"u2":"جریر نے ہمیں اعمش سے حدیث بیان کی، انہوں نے ابراہیم تیمی سے، انہوں نے حارث بن سوید سے، انہوں نے حضرت عبداللہ بن مسعود رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم لوگ اپنے خیال میں رقوب کسے شمار کرتے ہو؟ ہم نے عرض کی: جس شخص کے بچے پیدا نہ ہوتے ہوں۔ آپ نے فرمایا: \"یہ رقوب نہیں ہے، بلکہ رقوب وہ شخص ہے جس نے (آخرت میں) کسی بچے کو آگے نہ بھیجا ہو۔\" آپ نے فرمایا: \"تم اپنے خیال میں پہلوان کسے سمجھتے ہو؟\" ہم نے کہا: جس کو لوگ پچھاڑ نہ سکیں۔ آپ نے فرمایا: \"پہلوان وہ نہیں ہے، بلکہ پہلوان تو وہ شخص ہے جو غصے کے وقت خود پر قابو رکھتا ہے۔\""}],[6686,"ابومعاویہ اور عیسی بن یونس نے اعمش سے اسی سند کے ساتھ اسی کے ہم معنی روایت کی ۔","",{"u2":"ابومعاویہ اور عیسیٰ بن یونس نے اعمش سے اسی سند کے ساتھ اسی کے ہم معنی روایت کی۔"}],[6687,"سعید بن مسیب نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ( کوئی شخص ) پچھاڑ دینے سے طاقت نہیں ہوتا ۔ طاقتور ( مضبوط ) وہ ہے جو غصے کے وقت خود کو قابو میں رکھتا ہے ۔","",{"u2":"سعید بن مسیب نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"(کوئی شخص) پچھاڑ دینے سے طاقت نہیں ہوتا۔ طاقتور (مضبوط) وہ ہے جو غصے کے وقت خود کو قابو میں رکھتا ہے۔\""}],[6688,"زبیدی نے زہری سے روایت کی ، انہوں نے کہا : مجھے حمید بن عبدالرحمٰن نے بتایا کہ سیدنا ابوہریرہ رضی اللہ عنہ نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ فرماتے تھے : \" پچھاڑ دینے سے کوئی شخص طاقتور نہیں ہوتا ۔ \" صحابہ نے پوچھا : اللہ کے رسول! پھر طاقت ور کون ہے؟ آپ نے فرمایا : \" جو غصے کے وقت خود کو قابو میں رکھتا ہے ۔","",{"u2":"زبیدی نے زہری سے روایت کی، انہوں نے کہا: مجھے حمید بن عبدالرحمٰن نے بتایا کہ حضرت ابوہریرہ رضی اللہ عنہ نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ فرماتے تھے: \"پچھاڑ دینے سے کوئی شخص طاقتور نہیں ہوتا۔\" صحابہ نے پوچھا: اللہ کے رسول! پھر طاقت ور کون ہے؟ آپ نے فرمایا: \"جو غصے کے وقت خود کو قابو میں رکھتا ہے۔\""}],[6689,"معمر اور شعیب دونوں نے زہری سے خبر دی ، انہوں نے حمید بن عبدالرحمٰن بن عوف سے ، انہوں نے ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی ۔","",{"u2":"معمر اور شعیب دونوں نے زہری سے خبر دی، انہوں نے حمید بن عبدالرحمٰن بن عوف سے، انہوں نے ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی۔"}],[6690,"یحیی بن یحیی اور محمد بن علاء نے کہا : ہمیں ابومعاویہ نے اعمش سے حدیث بیان کی ، انہوں نے عدی بن ثابت سے اور انہوں نے سیدنا سلیمان بن صرد رضی اللہ عنہ سے روایت کی ، کہا : دو آدمیوں نے رسول اللہ صلی اللہ علیہ وسلم کے سامنے آپس میں گالم گلوچ کیا ، ان دو میں سے ایک کی آنکھیں سرخ ہو گئیں اور گردن کی رگیں پھول گئیں تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" مجھے ایک ایسا کلمہ معلوم ہے کہ اگر یہ شخص اسے کہہ دے تو وہ ( غصے کی ) جس کیفیت میں خود کو پا رہا ہے وہ جاتی رہے گی ، ( وہ کلمہ ہے ) : \"\" اعوذبالله من الشيطان الرجيم \"\" اس آدمی نے کہا : کیا آپ مجھ پر جنون طاری دیکھتے ہیں؟ ابن علاء کی روایت میں ( صرف ) \"\" اور کیا آپ دیکھتے ہیں \"\" کے الفاظ ہیں اور انہوں نے \"\" آدمی \"\" کا تذکرہ نہیں کیا ۔","",{"u2":"یحییٰ بن یحییٰ اور محمد بن علاء نے کہا: ہمیں ابومعاویہ نے اعمش سے حدیث بیان کی، انہوں نے عدی بن ثابت سے اور انہوں نے حضرت سلیمان بن صرد رضی اللہ عنہ سے روایت کی، کہا: دو آدمیوں نے رسول اللہ صلی اللہ علیہ وسلم کے سامنے آپس میں گالم گلوچ کیا، ان دو میں سے ایک کی آنکھیں سرخ ہو گئیں اور گردن کی رگیں پھول گئیں تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مجھے ایک ایسا کلمہ معلوم ہے کہ اگر یہ شخص اسے کہہ دے تو وہ (غصے کی) جس کیفیت میں خود کو پا رہا ہے وہ جاتی رہے گی، (وہ کلمہ ہے): \"اعوذباللہ من الشیطان الرجیم\" اس آدمی نے کہا: کیا آپ مجھ پر جنون طاری دیکھتے ہیں؟\nابن علاء کی روایت میں (صرف) \"اور کیا آپ دیکھتے ہیں\" کے الفاظ ہیں اور انہوں نے \"آدمی\" کا تذکرہ نہیں کیا۔"}],[6691,"ابواسامہ نے کہا : میں نے اعمش سے سنا ، وہ کہہ رہے تھے : میں نے عدی بن ثابت سے سنا ، وہ کہہ رہے تھے کہ ہمیں سلیمان بن صرد رضی اللہ عنہ نے حدیث بیان کی ، کہا : نبی صلی اللہ علیہ وسلم کے سامنے دو آدمیوں نے آپس میں گالم گلوچ کیا ۔ ان میں سے ایک کو غصہ چڑھنا شروع ہو گیا اور اس کا چہرہ سرخ ہونے لگا ۔ نبی صلی اللہ علیہ وسلم نے اس کی طرف نظر کی اور فرمایا : \" مجھے ایک کلمے : \" اعوذبالله من الشيطان الرجيم \" کا پتہ ہے ۔ اگر یہ شخص وہ ( کلمہ ) کہہ دے تو اس سے یہ ( غصہ ) جاتا رہے گا ۔ \" نبی صلی اللہ علیہ وسلم سے ( یہ بات ) سننے والوں میں سے ایک آدمی اٹھ کر اس شخص کی طرف گیا اور کہا : تمہیں پتہ ہے کہ ابھی ابھی رسول اللہ صلی اللہ علیہ وسلم نے کیا فرمایا ہے؟ آپ نے فرمایا ہے : \" مجھے ایک ایسے کلمے : \" اعوذبالله من الشيطان الرجيم \" کا پتہ ہے ۔ اگر یہ ( شخص ) وہ ( کلمہ ) کہہ دے تو اس سے یہ کیفیت جاتی رہے گی ۔ \" اس شخص نے کہا : کیا تم یہ سمجھ رہے ہو کہ میں جنون کا شکار ہو گیا ہوں؟","",{"u2":"ابواسامہ نے کہا: میں نے اعمش سے سنا، وہ کہہ رہے تھے: میں نے عدی بن ثابت سے سنا، وہ کہہ رہے تھے کہ ہمیں سلیمان بن صرد رضی اللہ عنہ نے حدیث بیان کی، کہا: نبی صلی اللہ علیہ وسلم کے سامنے دو آدمیوں نے آپس میں گالم گلوچ کیا۔ ان میں سے ایک کو غصہ چڑھنا شروع ہو گیا اور اس کا چہرہ سرخ ہونے لگا۔ نبی صلی اللہ علیہ وسلم نے اس کی طرف نظر کی اور فرمایا: \"مجھے ایک کلمے: \"اعوذباللہ من الشیطان الرجیم\" کا پتہ ہے۔ اگر یہ شخص وہ (کلمہ) کہہ دے تو اس سے یہ (غصہ) جاتا رہے گا۔\" نبی صلی اللہ علیہ وسلم سے (یہ بات) سننے والوں میں سے ایک آدمی اٹھ کر اس شخص کی طرف گیا اور کہا: تمہیں پتہ ہے کہ ابھی ابھی رسول اللہ صلی اللہ علیہ وسلم نے کیا فرمایا ہے؟ آپ نے فرمایا ہے: \"مجھے ایک ایسے کلمے: \"اعوذباللہ من الشیطان الرجیم\" کا پتہ ہے۔ اگر یہ (شخص) وہ (کلمہ) کہہ دے تو اس سے یہ کیفیت جاتی رہے گی۔\" اس شخص نے کہا: کیا تم یہ سمجھ رہے ہو کہ میں جنون کا شکار ہو گیا ہوں؟"}],[6692,"حفص بن غیاث نے اعمش سے اسی سند کے ساتھ روایت کی ۔","",{"u2":"حفص بن غیاث نے اعمش سے اسی سند کے ساتھ روایت کی۔"}],[6693,"یونس بن محمد نے حماد بن سلمہ سے ، انہوں نے ثابت سے ، انہوں نے سیدنا انس رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جب اللہ تعالی نے جنت میں حضرت آدم علیہ السلام کی صورت بنا لی تو جب تک چاہا ان ( کے جسد ) کو وہاں رکھا ۔ ابلیس اس کے اردگرد گھوم کر دیکھنے لگا کہ وہ کیسا ہے ۔ جب اس نے دیکھا کہ وہ ( جسم ) اندر سے کھوکھلا ہے تو اس نے جان لیا کہ اسے اس طرح پیدا کیا گیا کہ یہ خود پر قابو نہیں رکھ سکتا ۔","",{"u2":"یونس بن محمد نے حماد بن سلمہ سے، انہوں نے ثابت سے، انہوں نے حضرت انس رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب اللہ تعالیٰ نے جنت میں حضرت آدم علیہ السلام کی صورت بنا لی تو جب تک چاہا ان (کے جسد) کو وہاں رکھا۔ ابلیس اس کے اردگرد گھوم کر دیکھنے لگا کہ وہ کیسا ہے۔ جب اس نے دیکھا کہ وہ (جسم) اندر سے کھوکھلا ہے تو اس نے جان لیا کہ اسے اس طرح پیدا کیا گیا کہ یہ خود پر قابو نہیں رکھ سکتا۔\""}],[6694,"بہز نے کہا : ہمیں حماد نے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی ۔","",{"u2":"بہز نے کہا: ہمیں حماد نے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی۔"}],[6695,"مغیرہ حزامی نے ہمیں ابوزناد سے حدیث بیان کی ، انہوں نے اعرج سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جب تم میں سے کوئی شخص اپنے ( مسلمان ) بھائی سے لڑے تو چہرے ( پر مارنے ) سے اجتناب کرے ۔","",{"u2":"مغیرہ حزامی نے ہمیں ابوزناد سے حدیث بیان کی، انہوں نے اعرج سے اور انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی شخص اپنے (مسلمان) بھائی سے لڑے تو چہرے (پر مارنے) سے اجتناب کرے۔\""}],[6696,"ہمیں سفیان بن عیینہ نے ابوزناد سے اسی سند کے ساتھ روایت کی اور کہا : \" جب تم میں سے کوئی ( دوسرے کو ) مارے ۔","",{"u2":"ہمیں سفیان بن عیینہ نے ابوزناد سے اسی سند کے ساتھ روایت کی اور کہا: \"جب تم میں سے کوئی (دوسرے کو) مارے۔\""}],[6697,"سہیل کے والد ( ابوصالح ) نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" جب تم میں سے کوئی شخص اپنے بھائی سے لڑے تو چہرے ( پر مارنے ) سے بچے ۔","",{"u2":"سہیل کے والد (ابوصالح) نے حضرت ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی شخص اپنے بھائی سے لڑے تو چہرے (پر مارنے) سے بچے۔\""}],[6698,"شعبہ نے ہمیں قتادہ سے حدیث بیان کی ، انہوں نے ابوایوب سے سنا ، سیدنا ابوہریرہ رضی اللہ عنہ سے حدیث بیان کر رہے تھے ۔ انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جب تم میں سے کوئی شخص اپنے بھائی سے لڑے تو اس کے چہرے پر طمانچہ نہ مارے ۔","",{"u2":"شعبہ نے ہمیں قتادہ سے حدیث بیان کی، انہوں نے ابوایوب سے سنا، حضرت ابوہریرہ رضی اللہ عنہ سے حدیث بیان کر رہے تھے۔ انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی شخص اپنے بھائی سے لڑے تو اس کے چہرے پر طمانچہ نہ مارے۔\""}],[6699,"نصر بن علی جبضمی نے کہا : ہمیں میرے والد نے حدیث بیان کی ، انہوں نے کہا : ہمیں مثنی ( بن سعید ) نے حدیث بیان کی ، نیز مجھے محمد بن حاتم نے حدیث بیان کی ، کہا : ہمیں عبدالرحمٰن بن مہدی نے مثنی بن سعید سے حدیث بیان کی ، انہوں نے قتادہ سے ، انہوں نے ابوایوب سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا اور ابن ابی حاتم کی حدیث میں ہے : نبی صلی اللہ علیہ وسلم سے روایت ہے ، آپ نے فرمایا : \" جب تم میں سے کوئی اپنے بھائی سے لڑے تو چہرے سے اجتناب کرے کیونکہ اللہ نے آدم کو اس کی صورت پر بنایا ہے ۔","",{"u2":"نصر بن علی جبضمی نے کہا: ہمیں میرے والد نے حدیث بیان کی، انہوں نے کہا: ہمیں مثنیٰ (بن سعید) نے حدیث بیان کی، نیز مجھے محمد بن حاتم نے حدیث بیان کی، کہا: ہمیں عبدالرحمٰن بن مہدی نے مثنیٰ بن سعید سے حدیث بیان کی، انہوں نے قتادہ سے، انہوں نے ابوایوب سے اور انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا اور ابن ابی حاتم کی حدیث میں ہے: نبی صلی اللہ علیہ وسلم سے روایت ہے، آپ نے فرمایا: \"جب تم میں سے کوئی اپنے بھائی سے لڑے تو چہرے سے اجتناب کرے کیونکہ اللہ نے آدم کو اس کی صورت پر بنایا ہے۔\""}],[6700,"ہمام نے کہا : ہمیں قتادہ نے ابوایوب یحیی بن مالک مراغی سے حدیث بیان کی ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جب تم میں سے کوئی شخص اپنے بھائی سے لڑے تو چہرے ( پر مارنے ) سے اجتناب کرے ۔","",{"u2":"ہمام نے کہا: ہمیں قتادہ نے ابوایوب یحییٰ بن مالک مراغی سے حدیث بیان کی، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی شخص اپنے بھائی سے لڑے تو چہرے (پر مارنے) سے اجتناب کرے۔\""}],[6701,"حفص بن غیاث نے ہشام بن عروہ سے ، انہوں نے اپنے والد سے ، انہوں نے سیدنا ہشام بن حکیم بن حزام رضی اللہ عنہ سے روایت کی ، کہا : شام میں ان کا کچھ لوگوں کے قریب سے گزرا ہوا جن کو دھوپ میں کھڑا کیا گیا تھا اور ان کے سروں پر زیتون کا تیل ڈالا کیا تھا ، انہوں نے پوچھا : یہ کیا ہو رہا ہے؟ بتایا گیا : ان کو خراج ( نہ دینے ) کی وجہ سے سزا دی جا رہی ہے تو ( سیدنا ہشام بن حکیم بن حزام رضی اللہ عنہ نے ) کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ نے فرمایا : \" اللہ تعالی ان لوگوں کو عذاب میں مبتلا کرنے کا جو دنیا میں لوگوں کو عذاب دیتے ہیں ۔","",{"u2":"حفص بن غیاث نے ہشام بن عروہ سے، انہوں نے اپنے والد سے، انہوں نے حضرت ہشام بن حکیم بن حزام رضی اللہ عنہ سے روایت کی، کہا: شام میں ان کا کچھ لوگوں کے قریب سے گزرا ہوا جن کو دھوپ میں کھڑا کیا گیا تھا اور ان کے سروں پر زیتون کا تیل ڈالا کیا تھا، انہوں نے پوچھا: یہ کیا ہو رہا ہے؟ بتایا گیا: ان کو خراج (نہ دینے) کی وجہ سے سزا دی جا رہی ہے تو (حضرت ہشام بن حکیم بن حزام رضی اللہ عنہ نے) کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ نے فرمایا: \"اللہ تعالیٰ ان لوگوں کو عذاب میں مبتلا کرنے کا جو دنیا میں لوگوں کو عذاب دیتے ہیں۔\""}],[6702,"ابواسامہ نے ہشام سے ، انہوں نے اپنے والد سے روایت کی ، انہوں نے کہا : سیدنا ہشام بن حکیم بن حزام رضی اللہ عنہ شام کے چند نبطیوں ( سامی قوم زمیندار لوگوں ) کے قریب سے گزرے ، انہوں دھوپ میں کھڑا کیا گیا تھا ، انہوں نے پوچھا : ان کا معاملہ کیا ہے؟ لوگوں نے بتایا : انہیں جزیے ( کی ادائیگی کے معاملے ) میں محبوس کیا گیا ہے ، تو سیدنا ہشام رضی اللہ عنہ نے کہا : میں گواہی دیتا ہوں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا : \" اللہ تعالی ان لوگوں کو عذاب دے گا جو دنیا میں لوگوں کو عذاب دیتے ہیں ۔","",{"u2":"ابواسامہ نے ہشام سے، انہوں نے اپنے والد سے روایت کی، انہوں نے کہا: حضرت ہشام بن حکیم بن حزام رضی اللہ عنہ شام کے چند نبطیوں (سامی قوم زمیندار لوگوں) کے قریب سے گزرے، انہوں دھوپ میں کھڑا کیا گیا تھا، انہوں نے پوچھا: ان کا معاملہ کیا ہے؟ لوگوں نے بتایا: انہیں جزیے (کی ادائیگی کے معاملے) میں محبوس کیا گیا ہے، تو حضرت ہشام رضی اللہ عنہ نے کہا: میں گواہی دیتا ہوں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا: \"اللہ تعالیٰ ان لوگوں کو عذاب دے گا جو دنیا میں لوگوں کو عذاب دیتے ہیں۔\""}],[6703,"وکیع ، ابومعاویہ اور جریر سب نے ہشام سے اسی سند کے ساتھ حدیث بیان کی ، اور جریر کی حدیث میں مزید یہ ہے ، کہا : اور فلسطین پر ان دنوں ان لوگوں کا امیر عمیر بن سعد ( انصاری ) تھا تو وہ ( ہشام رضی اللہ عنہ ) ان کے پاس گئے ، ان کو حدیث سنائی تو انہوں نے ان کے بارے میں حکم دیا ، چنانچہ ان کو چھوڑ دیا گیا ۔","",{"u2":"وکیع، ابومعاویہ اور جریر سب نے ہشام سے اسی سند کے ساتھ حدیث بیان کی، اور جریر کی حدیث میں مزید یہ ہے، کہا: اور فلسطین پر ان دنوں ان لوگوں کا امیر عمیر بن سعد (انصاری) تھا تو وہ (ہشام رضی اللہ عنہ) ان کے پاس گئے، ان کو حدیث سنائی تو انہوں نے ان کے بارے میں حکم دیا، چنانچہ ان کو چھوڑ دیا گیا۔"}],[6704,"ابن شہاب نے عروہ بن زبیر سے روایت کی کہ سیدنا ہشام بن حکیم رضی اللہ عنہ نے ایک شخص کو دیکھا ، وہ حمص کا عامل تھا ۔ اس نے نبطیوں میں سے کچھ لوگوں کو جزیے کی ادائیگی کے سلسلے میں دھوپ میں کھڑا کیا ہوا تھا تو انہوں نے پوچھا : یہ کیا ہے؟ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا : \" بلاشبہ اللہ تعالی ان لوگوں کو مبتلائے عذاب کرے گا جو دنیا میں لوگوں کو عذاب میں مبتلا کرتے ہیں ۔","",{"u2":"ابن شہاب نے عروہ بن زبیر سے روایت کی کہ حضرت ہشام بن حکیم رضی اللہ عنہ نے ایک شخص کو دیکھا، وہ حمص کا عامل تھا۔ اس نے نبطیوں میں سے کچھ لوگوں کو جزیے کی ادائیگی کے سلسلے میں دھوپ میں کھڑا کیا ہوا تھا تو انہوں نے پوچھا: یہ کیا ہے؟ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا: \"بلاشبہ اللہ تعالیٰ ان لوگوں کو مبتلائے عذاب کرے گا جو دنیا میں لوگوں کو عذاب میں مبتلا کرتے ہیں۔\""}],[6705,"سفیان بن عیینہ نے عمرو ( بن دینار ) سے روایت کی ، انہوں نے سیدنا جابر رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : ایک شخص چند تیر لے کر مسجد میں سے گزرا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ان تیروں کو ان کی نوکوں ( کی طرف سے ) پکڑو ۔","",{"u2":"سفیان بن عیینہ نے عمرو (بن دینار) سے روایت کی، انہوں نے حضرت جابر رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: ایک شخص چند تیر لے کر مسجد میں سے گزرا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ان تیروں کو ان کی نوکوں (کی طرف سے) پکڑو۔\""}],[6706,"حماد بن زید نے عمرو بن دینار سے ، انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے روایت کی کہ ایک شخص چند تیر لے کر مسجد میں سے گزرا ، اس نے ان کے پیکان کھول رکھے تھے ، آپ نے حکم دیا کہ وہ انہیں پیکانوں ( آگے والے لوہے کے نوکدار حصوں ) کی طرف سے پکڑے تاکہ وہ کسی مسلمان کو خراچ نہ لگا دیں ۔","",{"u2":"حماد بن زید نے عمرو بن دینار سے، انہوں نے حضرت جابر بن عبداللہ رضی اللہ عنہ سے روایت کی کہ ایک شخص چند تیر لے کر مسجد میں سے گزرا، اس نے ان کے پیکان کھول رکھے تھے، آپ نے حکم دیا کہ وہ انہیں پیکانوں (آگے والے لوہے کے نوکدار حصوں) کی طرف سے پکڑے تاکہ وہ کسی مسلمان کو خراچ نہ لگا دیں۔"}],[6707,"قتیبہ بن سعید اور محمد بن رمح نے کہا : ہمیں لیث اور ابوزبیر سے حدیث بیان کی ، انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی ، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے ایک شخص کو جو مسجد میں کچھ تیر بطور صدقہ لوگوں میں تقسیم کر رہا تھا ، حکم دیا کہ وہ کو نوکوں سے پکڑے بغیر انہیں لے کر ( لوگوں کے درمیان میں سے ) نہ گزرے ۔ ابن رمح نے ( اپنی روایت میں ) کہا : وہ تیروں کو بطور صدقہ دے رہا تھا ۔","",{"u2":"قتیبہ بن سعید اور محمد بن رمح نے کہا: ہمیں لیث اور ابوزبیر سے حدیث بیان کی، انہوں نے حضرت جابر رضی اللہ عنہ سے روایت کی، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے ایک شخص کو جو مسجد میں کچھ تیر بطور صدقہ لوگوں میں تقسیم کر رہا تھا، حکم دیا کہ وہ کو نوکوں سے پکڑے بغیر انہیں لے کر (لوگوں کے درمیان میں سے) نہ گزرے۔ ابن رمح نے (اپنی روایت میں) کہا: وہ تیروں کو بطور صدقہ دے رہا تھا۔"}],[6708,"ثابت نے ابوبردہ سے ، انہوں نے سیدنا ابوموسی رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" جب تم میں سے کوئی شخص مجلس یا بازار میں سے گزرے اور اس کے ہاتھ میں تیر ہوں تو وہ انہیں ان کے پیکانوں ( نوکدار حصوں ) سے پکڑے ، پھر ( تنبیہ ہے ) ان کے نوکیلے حصے کی طرف سے پکڑے ، پھر ( تاکید ہے ) ان کے نوکیلے حصوں کی طرف سے پکڑے ۔ \"\" کہا : تو سیدنا ابوموسی رضی اللہ عنہ نے کہا : اللہ کی قسم! ( ہمارا یہ حال ہے کہ ) ہم نے مرنے سے پہلے ( اپنی اسی زندگی میں ) ان تیروں کو ایک دوسرے کے چہروں کی طرف سیدھا کر لیا ہے ۔","",{"u2":"ثابت نے ابوبردہ سے، انہوں نے حضرت ابوموسیٰ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی شخص مجلس یا بازار میں سے گزرے اور اس کے ہاتھ میں تیر ہوں تو وہ انہیں ان کے پیکانوں (نوکدار حصوں) سے پکڑے، پھر (تنبیہ ہے) ان کے نوکیلے حصے کی طرف سے پکڑے، پھر (تاکید ہے) ان کے نوکیلے حصوں کی طرف سے پکڑے۔\"\nکہا: تو حضرت ابوموسیٰ رضی اللہ عنہ نے کہا: اللہ کی قسم! (ہمارا یہ حال ہے کہ) ہم نے مرنے سے پہلے (اپنی اسی زندگی میں) ان تیروں کو ایک دوسرے کے چہروں کی طرف سیدھا کر لیا ہے۔"}],[6709,"بُرید نے ابوبردہ سے ، انہوں نے سیدنا ابوموسی رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" جب تم میں سے کوئی شخص ہماری مسجد یا ہمارے بازار میں سے گزرے اور اس کے پاس تیر ہوں تو وہ انہیں اپنی ہتھیلی سے ان کے تیز نوکدار حصوں کی طرف سے پکڑے ، کہیں ایسا نہ ہو کہ اس کا کوئی حصہ مسلمانوں میں سے کسی شخص کو لگ جائے ۔ \"\" یا فرمایا : \"\" وہ ان کے پیکانوں کو اپنی مٹھی میں پکڑے ۔","",{"u2":"بُرید نے ابوبردہ سے، انہوں نے حضرت ابوموسیٰ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی، آپ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی شخص ہماری مسجد یا ہمارے بازار میں سے گزرے اور اس کے پاس تیر ہوں تو وہ انہیں اپنی ہتھیلی سے ان کے تیز نوکدار حصوں کی طرف سے پکڑے، کہیں ایسا نہ ہو کہ اس کا کوئی حصہ مسلمانوں میں سے کسی شخص کو لگ جائے۔\"\nیا فرمایا: \"وہ ان کے پیکانوں کو اپنی مٹھی میں پکڑے۔\""}],[6710,"ایوب نے ( محمد ) ابن سیرین سے روایت کی ، کہا : میں نے سیدنا ابوہریرہ رضی اللہ عنہ کو یہ کہتے ہوئے سنا کہ ابوالقاسم صلی اللہ علیہ وسلم نے فرمایا : \" جس نے اپنے بھائی کی طرف لوہے کے کسی ہتھیار سے اشارہ کیا تو اس پر فرشتے لعنت کرتے رہتے ہیں یہاں تک کہ وہ اس کام کو ترک کر دے ، چاہے وہ اس کا ماں باپ جایا بھائی ہی کیوں نہ ہو ۔","",{"u2":") ایوب نے (محمد) ابن سیرین سے روایت کی، کہا: میں نے حضرت ابوہریرہ رضی اللہ عنہ کو یہ کہتے ہوئے سنا کہ ابوالقاسم صلی اللہ علیہ وسلم نے فرمایا: \"جس نے اپنے بھائی کی طرف لوہے کے کسی ہتھیار سے اشارہ کیا تو اس پر فرشتے لعنت کرتے رہتے ہیں یہاں تک کہ وہ اس کام کو ترک کر دے، چاہے وہ اس کا ماں باپ جایا بھائی ہی کیوں نہ ہو۔\""}],[6711,"ابن عون نے محمد ( بن سیرین ) سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی ۔","",{"u2":"ابن عون نے محمد (بن سیرین) سے، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی۔"}],[6712,"ہمام بن منبہ سے روایت ہے ، کہا : یہ احادیث ہیں جو سیدنا ابوہریرہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کیں ، پھر انہوں نے کئی احادیث ذکر کیں ، ان میں سے ایک یہ ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تم میں سے کوئی شخص اپنے بھائی کی طرف ہتھیار سے اشارہ نہ کرے ، کیونکہ تم میں سے کوئی شخص نہیں جانتا کہ شاید شیطان اچانک اس کے ہاتھ میں اسے حرکت دے ( اور وہ دوسرے مسلمان کو لگ جائے ) اور وہ ( جس کے ہاتھ سے ہتھیار چلے ) جہنم کے گڑھے میں گر جائے ۔","",{"u2":"ہمام بن منبہ سے روایت ہے، کہا: یہ احادیث ہیں جو حضرت ابوہریرہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کیں، پھر انہوں نے کئی احادیث ذکر کیں، ان میں سے ایک یہ ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کوئی شخص اپنے بھائی کی طرف ہتھیار سے اشارہ نہ کرے، کیونکہ تم میں سے کوئی شخص نہیں جانتا کہ شاید شیطان اچانک اس کے ہاتھ میں اسے حرکت دے (اور وہ دوسرے مسلمان کو لگ جائے) اور وہ (جس کے ہاتھ سے ہتھیار چلے) جہنم کے گڑھے میں گر جائے۔\""}],[6713,"ابو بکر کے آزاد کردہ غلام سُمی نے ابوصالح سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ایک شخص راستے پر چلا جا رہا تھا ، اس نے راستے پر ایک کانٹے دار ٹہنی دیکھی تو اسے ( ایک طرف ) ہٹا دیا ۔ اللہ تعالی کے اسے اس کا انعام دیا تو اس کی بخشش فرما دی ۔","",{"u2":"ابو بکر کے آزاد کردہ غلام سُمی نے ابوصالح سے، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک شخص راستے پر چلا جا رہا تھا، اس نے راستے پر ایک کانٹے دار ٹہنی دیکھی تو اسے (ایک طرف) ہٹا دیا۔ اللہ تعالیٰ کے اسے اس کا انعام دیا تو اس کی بخشش فرما دی۔\""}],[6714,"سہیل نے اپنے والد سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ایک شخص راستے سے اوپر پڑی ہوئی درخت کی ایک شاخ کے پاس سے گزرا تو اس نے کہا : اللہ کی قسم! میں اس شاخ و مسلمانوں کے راستے سے ہٹا دوں کا تاکہ یہ ان کو ایذا نہ دے تو اس شخص کو جنت میں داخل کر دیا گیا ۔","",{"u2":"سہیل نے اپنے والد سے، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک شخص راستے سے اوپر پڑی ہوئی درخت کی ایک شاخ کے پاس سے گزرا تو اس نے کہا: اللہ کی قسم! میں اس شاخ و مسلمانوں کے راستے سے ہٹا دوں کا تاکہ یہ ان کو ایذا نہ دے تو اس شخص کو جنت میں داخل کر دیا گیا۔\""}],[6715,"اعمش نے ابوصالح سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ، آپ نے فرمایا : \" میں نے ایک شخص کو دیکھا کہ وہ ( اس عمل کے بدلے ) جنت میں ہر طرف ( نعمتوں کے مزے ) لوٹ رہا تھا ( کیونکہ ) اس نے راستے کے درمیان سے ایک ایسے درخت کو کاٹ دیا تھا جو لوگوں کو اذیت دیتا تھا ۔","",{"u2":"اعمش نے ابوصالح سے، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی، آپ نے فرمایا: \"میں نے ایک شخص کو دیکھا کہ وہ (اس عمل کے بدلے) جنت میں ہر طرف (نعمتوں کے مزے) لوٹ رہا تھا (کیونکہ) اس نے راستے کے درمیان سے ایک ایسے درخت کو کاٹ دیا تھا جو لوگوں کو اذیت دیتا تھا۔\""}],[6716,"ابورافع نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ایک درخت مسلمانوں کو اذیت دیتا تھا ، چنانچہ ایک شخص آیا اور اسے کاٹ دیا تو وہ جنت میں داخل ہو گیا ۔","",{"u2":"ابورافع نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک درخت مسلمانوں کو اذیت دیتا تھا، چنانچہ ایک شخص آیا اور اسے کاٹ دیا تو وہ جنت میں داخل ہو گیا۔\""}],[6717,"ابان نے صمعہ نے کہا : مجھے ابووازع نے حدیث بیان کی ، کہا : مجھے سیدنا ابوبرزہ رضی اللہ عنہ نے حدیث بیان کی ، کہا : میں نے عرض کی : اللہ کے نبی! آپ مجھے کوئی ایسی بات سکھا دیں جس سے میں نفع حاصل کروں ۔ آپ نے فرمایا : \" مسلمانوں کے راستے سے تکلیف دینے والی چیز کو ہٹا دیا کرو ۔","",{"u2":"ابان نے صمعہ نے کہا: مجھے ابووازع نے حدیث بیان کی، کہا: مجھے حضرت ابوبرزہ رضی اللہ عنہ نے حدیث بیان کی، کہا: میں نے عرض کی: اللہ کے نبی! آپ مجھے کوئی ایسی بات سکھا دیں جس سے میں نفع حاصل کروں۔ آپ نے فرمایا: \"مسلمانوں کے راستے سے تکلیف دینے والی چیز کو ہٹا دیا کرو۔\""}],[6718,"ابوبکر بن شعیب بن حبحاب نے ابووازع راسبی سے ، انہوں نے سیدنا ابوبرزہ رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کی : اللہ کے رسول! میں نہیں جانتا ، ہو سکتا ہے کہ آپ ( دنیا سے ) تشریف لے جائیں اور میں آپ کے بعد زندہ رہ جاؤں ، اس لیے آپ مجھے ( آخرت کے سفر کے لیے ) کوئی زاد راہ عطا کر دیجئے جس سے اللہ تعالی مجھے نفع عطا فرمائے ، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اس طرح کرو ، اس طرح کرو ۔ ۔ ابوبکر بن شعیب ان باتوں کو بھول گئے ۔ ۔ اور ( فرمایا : ) راستے سے تکلیف دہ چیزوں کو دُور کر دیا کرو ۔","",{"u2":"ابوبکر بن شعیب بن حبحاب نے ابووازع راسبی سے، انہوں نے حضرت ابوبرزہ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کی: اللہ کے رسول! میں نہیں جانتا، ہو سکتا ہے کہ آپ (دنیا سے) تشریف لے جائیں اور میں آپ کے بعد زندہ رہ جاؤں، اس لیے آپ مجھے (آخرت کے سفر کے لیے) کوئی زاد راہ عطا کر دیجئے جس سے اللہ تعالیٰ مجھے نفع عطا فرمائے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اس طرح کرو، اس طرح کرو۔۔ ابوبکر بن شعیب ان باتوں کو بھول گئے۔۔ اور (فرمایا:) راستے سے تکلیف دہ چیزوں کو دُور کر دیا کرو۔\""}],[6719,"جویریہ بن اسماء نے نافع سے ، انہوں نے سیدنا عبداللہ ( بن عمر رضی اللہ عنہ ) سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ایک عورت کو بلی کی وجہ سے عذاب دیا گیا ، اس نے بلی کو باندھے رکھا حتی کہ وہ مر گئی تو وہ اسی وجہ سے جہنم میں داخل ہو گئی ، کیونکہ جب اس نے بلی کو باندھا تو نہ اس کو کھلایا ، نہ پلایا اور نہ اس کو چھوڑا کہ وہ ( خود ہی ) زمین کے کیڑے مکوڑے کھا لیتی ۔","",{"u2":"جویریہ بن اسماء نے نافع سے، انہوں نے حضرت عبداللہ (بن عمر رضی اللہ عنہ) سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک عورت کو بلی کی وجہ سے عذاب دیا گیا، اس نے بلی کو باندھے رکھا حتی کہ وہ مر گئی تو وہ اسی وجہ سے جہنم میں داخل ہو گئی، کیونکہ جب اس نے بلی کو باندھا تو نہ اس کو کھلایا، نہ پلایا اور نہ اس کو چھوڑا کہ وہ (خود ہی) زمین کے کیڑے مکوڑے کھا لیتی۔\""}],[6720,"امام مالک بن انس نے نافع سے ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے ، انہوں نے نبی صلی اللہ علیہ وسلم سے ، جویریہ کی حدیث کے ہم معنی روایت کی ۔","",{"u2":"امام مالک بن انس نے نافع سے، انہوں نے حضرت ابن عمر رضی اللہ عنہ سے، انہوں نے نبی صلی اللہ علیہ وسلم سے، جویریہ کی حدیث کے ہم معنی روایت کی۔"}],[6721,"عبیداللہ بن عمر نے نافع سے ، انہوں نے سیدنا ابن عمر رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ایک عورت کو بلی کے سبب عذاب دیا کیا جسے اس نے باندھا رکھا تھا ، اس نے اسے کھانے کو دیا نہ پینے کو دیا ، نہ اسے چھوڑا کہ وہ زمین کے کیڑے مکوڑے شکار سے کھا لیتی ۔","",{"u2":"عبیداللہ بن عمر نے نافع سے، انہوں نے حضرت ابن عمر رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک عورت کو بلی کے سبب عذاب دیا کیا جسے اس نے باندھا رکھا تھا، اس نے اسے کھانے کو دیا نہ پینے کو دیا، نہ اسے چھوڑا کہ وہ زمین کے کیڑے مکوڑے شکار سے کھا لیتی۔\""}],[6722,"سعید مقبری نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی ۔","",{"u2":"سعید مقبری نے حضرت ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی۔"}],[6723,"معمر نے ہمیں ہمام بن منبہ سے روایت کی ، کہا : یہ احادیث ہمیں سیدنا ابوہریرہ رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے بیان کیں ، انہوں نے کئی احادیث بیان کیں ، ان میں سے ایک یہ تھی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ایک عورت اپنی بلی یا بلے کی وجہ سے دوزخ میں چلی گئی جس کو اس نے باندھ کر رکھا تھا ، نہ خود اس کو کھلایا اور نہ اسے چھوڑا کہ زمین کے چھوٹے موٹے جانور چنا کھا لیتی ، یہاں تک کہ وہ کمزور ہو کر مر گئی ۔","",{"u2":"معمر نے ہمیں ہمام بن منبہ سے روایت کی، کہا: یہ احادیث ہمیں حضرت ابوہریرہ رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے بیان کیں، انہوں نے کئی احادیث بیان کیں، ان میں سے ایک یہ تھی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک عورت اپنی بلی یا بلے کی وجہ سے دوزخ میں چلی گئی جس کو اس نے باندھ کر رکھا تھا، نہ خود اس کو کھلایا اور نہ اسے چھوڑا کہ زمین کے چھوٹے موٹے جانور چنا کھا لیتی، یہاں تک کہ وہ کمزور ہو کر مر گئی۔\""}],[6724,"سیدنا ابوسعید خدری اور سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے ، دونون نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" عزت اللہ عزوجل کا تہبند ہے اور کبریائی اس ( کے کندھوں ) کی چادر ہے ۔ جو شخص ان ( صفات ) کے معاملے میں میرے مدمقابل میں آئے گا ، میں اسے عذاب دوں گا ۔","",{"u2":"حضرت ابوسعید خدری اور حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، دونون نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عزت اللہ عزوجل کا تہبند ہے اور کبریائی اس (کے کندھوں) کی چادر ہے۔ جو شخص ان (صفات) کے معاملے میں میرے مدمقابل میں آئے گا، میں اسے عذاب دوں گا۔\""}],[6725,"ابو عمران جونی نے سیدنا جندب رضی اللہ عنہ سے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ایک آدمی نے کہا : اللہ کی قسم! اللہ تعالی فلاں شخص کو نہیں بخشے گا ، تو اللہ تعالی نے فرمایا : کون ہے جو مجھ پر قسم کھا رہا ہے کہ میں فلاں کو نہیں بخشوں گا؟ میں نے ( اس ) فلاں کو تو بخش دیا اور ( ایسا کہنے والے! ) تیرے سارے عمل ضائع کر دیے ۔ \" یا جن الفاظ میں آپ صلی اللہ علیہ وسلم نے ارشاد فرمایا ۔","",{"u2":"ابو عمران جونی نے حضرت جندب رضی اللہ عنہ سے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک آدمی نے کہا: اللہ کی قسم! اللہ تعالیٰ فلاں شخص کو نہیں بخشے گا، تو اللہ تعالیٰ نے فرمایا: کون ہے جو مجھ پر قسم کھا رہا ہے کہ میں فلاں کو نہیں بخشوں گا؟ میں نے (اس) فلاں کو تو بخش دیا اور (ایسا کہنے والے!) تیرے سارے عمل ضائع کر دیے۔\" یا جن الفاظ میں آپ صلی اللہ علیہ وسلم نے ارشاد فرمایا۔"}],[6726,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" بہت سے غبار میں اٹے ہوئے ( غریب الوطن ، مسافر ) بکھرے ہوئے بالوں والے ، دروازوں سے دھتکار دیے جانے والے لوگ ایسے ہیں کہ اگر ان میں سے کوئی اللہ تعالی پر ( اعتماد کر کے ) قسم کھا لے تو اللہ تعالی اس کی قسم پوری کر دیتا ہے ۔","",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بہت سے غبار میں اٹے ہوئے (غریب الوطن، مسافر) بکھرے ہوئے بالوں والے، دروازوں سے دھتکار دیے جانے والے لوگ ایسے ہیں کہ اگر ان میں سے کوئی اللہ تعالیٰ پر (اعتماد کر کے) قسم کھا لے تو اللہ تعالیٰ اس کی قسم پوری کر دیتا ہے۔\""}],[6727,"حماد بن ابی سلمہ اور امام مالک نے سہیل بن ابی صالح ، انہوں نے اپنے والد سے ، انہوں نے سیدنا ابوہریرہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" جب ایک شخص ( یہ ) کہتا ہے : لوگ ہلاک ہو گئے تو وہ انہیں ہلاک کر دیتا ہے ۔ \"\" ( امام مسلم کے ایک شاگرد ) ابواسحاق نے کہا : مجھے ( یعنی طور پر ) معلوم نہیں کہ ( کاف کے ) زبر کے ساتھ اهلكهم ( اس نے انہیں ہلاک کر دیا ہے ) یا پیش کے ساتھ اهلكهم ( ان سب سے بڑھ کر ہلاک کرنے والا ہے ) ۔"],[6728,"حماد بن ابی سلمہ اور امام مالک نے سہیل بن ابی صالح ، انہوں نے اپنے والد سے ، انہوں نے سیدنا ابوہریرہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" جب ایک شخص ( یہ ) کہتا ہے : لوگ ہلاک ہو گئے تو وہ انہیں ہلاک کر دیتا ہے ۔ \"\" ( امام مسلم کے ایک شاگرد ) ابواسحاق نے کہا : مجھے ( یعنی طور پر ) معلوم نہیں کہ ( کاف کے ) زبر کے ساتھ اهلكهم ( اس نے انہیں ہلاک کر دیا ہے ) یا پیش کے ساتھ اهلكهم ( ان سب سے بڑھ کر ہلاک کرنے والا ہے ) ۔","",{"u2":"حماد بن ابی سلمہ اور امام مالک نے سہیل بن ابی صالح، انہوں نے اپنے والد سے، انہوں نے حضرت ابوہریرہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب ایک شخص (یہ) کہتا ہے: لوگ ہلاک ہو گئے تو وہ انہیں ہلاک کر دیتا ہے۔\"\n(امام مسلم کے ایک شاگرد) ابواسحاق نے کہا: مجھے (یعنی طور پر) معلوم نہیں کہ (کاف کے) زبر کے ساتھ اہلکہم (اس نے انہیں ہلاک کر دیا ہے) یا پیش کے ساتھ اہلکہم (ان سب سے بڑھ کر ہلاک کرنے والا ہے)۔\""}],[6729,"روح بن قاسم اور سلیمان بن بلال نے سہیل سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی ۔","",{"u2":"روح بن قاسم اور سلیمان بن بلال نے سہیل سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی۔"}],[6730,"مالک بن انس ، لیث بن سعد اور یزید بن ہارون سب نے یحیی بن سعید سے روایت کی ، ( اسی طرح ) محمد بن مثنی نے ہمیں حدیث بیان کی ۔ ۔ الفاظ انہی کے ہیں ۔ ۔ کہا : ہمیں عبدالوہاب ثقفی نے حدیث بیان کی ، کہا : میں نے یحیی بن سعید سے سنا ، کہا : مجھے ابوبکر بن محمد بن عمرو بن حزم نے خبر دی کہ عمرہ نے ان کو حدیث بیان کی ، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے سنا ، وہ کہتی تھیں : میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا : \" مجھے جبریل مسلسل ہمسائے کے ساتھ حسن سلوک کے لیے کہتے رہے ، حتی کہ مجھے یقین ہونے لگا کہ وہ ضرور انہی وراثت میں شریک کر دیں گے ۔","",{"u2":"مالک بن انس، لیث بن سعد اور یزید بن ہارون سب نے یحییٰ بن سعید سے روایت کی، (اسی طرح) محمد بن مثنیٰ نے ہمیں حدیث بیان کی۔۔ الفاظ انہی کے ہیں۔۔ کہا: ہمیں عبدالوہاب ثقفی نے حدیث بیان کی، کہا: میں نے یحییٰ بن سعید سے سنا، کہا: مجھے ابوبکر بن محمد بن عمرو بن حزم نے خبر دی کہ عمرہ نے ان کو حدیث بیان کی، انہوں نے حضرت عائشہ رضی اللہ عنہا سے سنا، وہ کہتی تھیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا: \"مجھے جبریل مسلسل ہمسائے کے ساتھ حسن سلوک کے لیے کہتے رہے، حتی کہ مجھے یقین ہونے لگا کہ وہ ضرور انہی وراثت میں شریک کر دیں گے۔\""}],[6731,"ہشام بن عروہ نے اپنے والد سے ، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند حدیث بیان کی ۔","",{"u2":"ہشام بن عروہ نے اپنے والد سے، انہوں نے حضرت عائشہ رضی اللہ عنہا سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند حدیث بیان کی۔"}],[6732,"عمر بن محمد کے والد نے کہا : میں نے سیدنا ابن عمر رضی اللہ عنہ کو یہ کہتے ہوئے سنا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جبریل مجھے لگاتار ہمسائے کے ساتھ حسن سلوک کی تلقین کرتے رہے حتی کہ مجھے یقین ہونے لگا کہ وہ اسے وارث ( بھی ) بنا دیں گے ۔","",{"u2":"عمر بن محمد کے والد نے کہا: میں نے حضرت ابن عمر رضی اللہ عنہ کو یہ کہتے ہوئے سنا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جبریل مجھے لگاتار ہمسائے کے ساتھ حسن سلوک کی تلقین کرتے رہے حتی کہ مجھے یقین ہونے لگا کہ وہ اسے وارث (بھی) بنا دیں گے۔\""}],[6733,"عبدالعزیز بن عبدالصمد عمی نے کہا : ہمیں ابوعمران جونی نے عبداللہ بن صامت سے حدیث بیان کی ، انہوں نے سیدنا ابوذر رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ابوذر! جب تم شوربا پکاؤ تو اس میں پانی زیادہ رکھو اور اپنے پڑوسیوں کو یاد رکھو ۔","",{"u2":"عبدالعزیز بن عبدالصمد عمی نے کہا: ہمیں ابوعمران جونی نے عبداللہ بن صامت سے حدیث بیان کی، انہوں نے حضرت ابوذر رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ابوذر! جب تم شوربا پکاؤ تو اس میں پانی زیادہ رکھو اور اپنے پڑوسیوں کو یاد رکھو۔\""}],[6734,"شعبہ نے ابو عمران جونی سے ، انہوں نے عبداللہ بن صامت سے اور انہوں نے سیدنا ابوذر رضی اللہ عنہ سے روایت کی ، کہا : میرے خلیل صلی اللہ علیہ وسلم نے مجھے وصیت کی : \" جب تم شوربے والا سالن پکاؤ تو اس میں پانی زیادہ رکھو ، پھر اپنے ہمسایوں میں سے کسی ( ضرورت مند ) گھرانے کو دیکھو اور اس میں سے کچھ اچھے طریقے سے ان کو بھجوا دو ۔","",{"u2":"شعبہ نے ابو عمران جونی سے، انہوں نے عبداللہ بن صامت سے اور انہوں نے حضرت ابوذر رضی اللہ عنہ سے روایت کی، کہا: میرے خلیل صلی اللہ علیہ وسلم نے مجھے وصیت کی: \" جب تم شوربے والا سالن پکاؤ تو اس میں پانی زیادہ رکھو، پھر اپنے ہمسایوں میں سے کسی (ضرورت مند) گھرانے کو دیکھو اور اس میں سے کچھ اچھے طریقے سے ان کو بھجوا دو۔\""}],[6735,"سیدنا ابوذر رضی اللہ عنہ سے روایت ہے ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا : \" نیکی میں کسی چیز کو حقیر نہ سمجھو ، چاہے یہی ہو کہ تم اپنے ( مسلمان ) بھائی کو کھلتے ہوئے چہرے سے ملو ۔","",{"u2":"حضرت ابوذر رضی اللہ عنہ سے روایت ہے، کہا: رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا: \"نیکی میں کسی چیز کو حقیر نہ سمجھو، چاہے یہی ہو کہ تم اپنے (مسلمان) بھائی کو کھلتے ہوئے چہرے سے ملو۔\""}],[6736,"سیدنا ابوموسی رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم کے پاس جب کوئی ضرورت مند آتا تو آپ اپنے ساتھ بیٹھے ہوئے لوگوں کی طرف متوجہ ہوتے اور فرماتے : \" تم ( ابھی اس کی ) شفاعت کرو ، تمہیں بھی اجر دیا جائے گا اور اللہ تعالی اپنے نبی کی زبان سے وہی فیصلہ جاری کرائے گا جو اس کو پسند ہو گا ۔","",{"u2":"حضرت ابوموسیٰ رضی اللہ عنہ سے روایت ہے، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم کے پاس جب کوئی ضرورت مند آتا تو آپ اپنے ساتھ بیٹھے ہوئے لوگوں کی طرف متوجہ ہوتے اور فرماتے: \"تم (ابھی اس کی) شفاعت کرو، تمہیں بھی اجر دیا جائے گا اور اللہ تعالیٰ اپنے نبی کی زبان سے وہی فیصلہ جاری کرائے گا جو اس کو پسند ہو گا۔\""}],[6737,"سیدنا ابوموسی رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" نیک ہم نشیں اور بُرے ہم نشیں کی مثال مُشک بردار اور بھٹی دھونکنے والے کی طرح ہے ، مُشک بردار یا تم کو ہدیے میں مشک دے دے گا یا تم اس سے خرید لو گے ، ورنہ کم از کم تمہیں اس سے اچھی خوشبو آئے گی اور بھٹی دھونکنے والا یا تو ( چنگاریوں سے ) تمہارے کپڑے جلائے گا یا تمہیں ( اس سے ) بدبُو آئے گی ۔"],[6738,"سیدنا ابوموسی رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" نیک ہم نشیں اور بُرے ہم نشیں کی مثال مُشک بردار اور بھٹی دھونکنے والے کی طرح ہے ، مُشک بردار یا تم کو ہدیے میں مشک دے دے گا یا تم اس سے خرید لو گے ، ورنہ کم از کم تمہیں اس سے اچھی خوشبو آئے گی اور بھٹی دھونکنے والا یا تو ( چنگاریوں سے ) تمہارے کپڑے جلائے گا یا تمہیں ( اس سے ) بدبُو آئے گی ۔","",{"u2":"حضرت ابوموسیٰ رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا: \"نیک ہم نشیں اور بُرے ہم نشیں کی مثال مُشک بردار اور بھٹی دھونکنے والے کی طرح ہے، مُشک بردار یا تم کو ہدیے میں مشک دے دے گا یا تم اس سے خرید لو گے، ورنہ کم از کم تمہیں اس سے اچھی خوشبو آئے گی اور بھٹی دھونکنے والا یا تو (چنگاریوں سے) تمہارے کپڑے جلائے گا یا تمہیں (اس سے) بدبُو آئے گی۔\""}],[6739,"معمر اور شعیب نے ابن شہاب زہری سے روایت کی ، انہوں نے کہا : مجھے عبداللہ بن ابی بکر بن حزم نے حدیث بیان کی ، انہیں عروہ بن زبیر نے بتایا کہ ام المومنین عائشہ صدیقہ رضی اللہ عنہا نے کہا : میرے پاس ایک عورت آئی ، اس کے ساتھ اس کی دو بیٹیاں بھی تھیں ، اس نے مجھ سے ( کھانا ) مانگا تو اسے میرے پاس ایک کھجور کے سوا اور کچھ نہ ملا ۔ میں نے وہی اس کو دے دی ، اس نے وہ کھجور لے کر اپنی دو بیٹیوں میں تقسیم کر دی اور خود اس میں سے کچھ نہ کھانا ، پھر وہ کھڑی ہوئی ، اور وہ اس کی دونوں بیٹیاں چلی گئیں ، پھر نبی صلی اللہ علیہ وسلم میرے پاس تشریف لائے تو میں نے آپ کو اس عورت کی بات بتائی تو نبی صلی اللہ علیہ وسلم نے فرمایا : \" جس کسی پر بیٹیوں کی پرورش کا بار پڑ جائے اور وہ ان کے ساتھ حسن سلوک کرے تو وہ اس کے لیے جہنم سے ( بچانے والا ) پردہ ہوں گی ۔"],[6740,"معمر اور شعیب نے ابن شہاب زہری سے روایت کی ، انہوں نے کہا : مجھے عبداللہ بن ابی بکر بن حزم نے حدیث بیان کی ، انہیں عروہ بن زبیر نے بتایا کہ ام المومنین عائشہ صدیقہ رضی اللہ عنہا نے کہا : میرے پاس ایک عورت آئی ، اس کے ساتھ اس کی دو بیٹیاں بھی تھیں ، اس نے مجھ سے ( کھانا ) مانگا تو اسے میرے پاس ایک کھجور کے سوا اور کچھ نہ ملا ۔ میں نے وہی اس کو دے دی ، اس نے وہ کھجور لے کر اپنی دو بیٹیوں میں تقسیم کر دی اور خود اس میں سے کچھ نہ کھانا ، پھر وہ کھڑی ہوئی ، اور وہ اس کی دونوں بیٹیاں چلی گئیں ، پھر نبی صلی اللہ علیہ وسلم میرے پاس تشریف لائے تو میں نے آپ کو اس عورت کی بات بتائی تو نبی صلی اللہ علیہ وسلم نے فرمایا : \" جس کسی پر بیٹیوں کی پرورش کا بار پڑ جائے اور وہ ان کے ساتھ حسن سلوک کرے تو وہ اس کے لیے جہنم سے ( بچانے والا ) پردہ ہوں گی ۔","",{"u2":"معمر اور شعیب نے ابن شہاب زہری سے روایت کی، انہوں نے کہا: مجھے عبداللہ بن ابی بکر بن حزم نے حدیث بیان کی،انہیں عروہ بن زبیر نے بتایا کہ ام المومنین عائشہ صدیقہ رضی اللہ عنہا نے کہا: میرے پاس ایک عورت آئی، اس کے ساتھ اس کی دو بیٹیاں بھی تھیں، اس نے مجھ سے (کھانا) مانگا تو اسے میرے پاس ایک کھجور کے سوا اور کچھ نہ ملا۔ میں نے وہی اس کو دے دی، اس نے وہ کھجور لے کر اپنی دو بیٹیوں میں تقسیم کر دی اور خود اس میں سے کچھ نہ کھانا، پھر وہ کھڑی ہوئی، اور وہ اس کی دونوں بیٹیاں چلی گئیں، پھر نبی صلی اللہ علیہ وسلم میرے پاس تشریف لائے تو میں نے آپ کو اس عورت کی بات بتائی تو نبی صلی اللہ علیہ وسلم نے فرمایا: \"جس کسی پر بیٹیوں کی پرورش کا بار پڑ جائے اور وہ ان کے ساتھ حسن سلوک کرے تو وہ اس کے لیے جہنم سے (بچانے والا) پردہ ہوں گی۔\""}],[6741,"عراک بن مالک نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : میرے پاس ایک مسکین عورت آئی جس نے اپنی دو بیٹیاں اٹھائی ہوئی تھیں ، میں نے اس کو تین کھجوریں دیں ، اس نے کہا ان میں سے ہر ایک کو ایک ایک کھجور دی ، ( بچی ہوئی ) ایک کھجور کھانے کے لیے اپنے منہ کی طرف لے گئی ، تو وہ بھی اس کی دو بیٹیوں نے کھانے کے لیے مانگ لی ، اس نے وہ کھجور بھی جو وہ کھانا چاہتی تھی ، دو حصے کر کے دونوں بیٹیوں کو دے دی ۔ مجھے اس کا یہ کام بہت اچھا لگا ۔ میں نے رسول اللہ صلی اللہ علیہ وسلم کو بتایا تو آپ نے فرمایا : \" اللہ نے اس ( عمل ) کی وجہ سے اس کے لیے جنت پکی کر دی ہے یا ( فرمایا : ) اس وجہ سے اسے آگ سے آزاد کر دیا ہے ۔","",{"u2":"عراک بن مالک نے حضرت عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: میرے پاس ایک مسکین عورت آئی جس نے اپنی دو بیٹیاں اٹھائی ہوئی تھیں، میں نے اس کو تین کھجوریں دیں، اس نے کہا ان میں سے ہر ایک کو ایک ایک کھجور دی، (بچی ہوئی) ایک کھجور کھانے کے لیے اپنے منہ کی طرف لے گئی، تو وہ بھی اس کی دو بیٹیوں نے کھانے کے لیے مانگ لی، اس نے وہ کھجور بھی جو وہ کھانا چاہتی تھی، دو حصے کر کے دونوں بیٹیوں کو دے دی۔ مجھے اس کا یہ کام بہت اچھا لگا۔ میں نے رسول اللہ صلی اللہ علیہ وسلم کو بتایا تو آپ نے فرمایا: \"اللہ نے اس (عمل) کی وجہ سے اس کے لیے جنت پکی کر دی ہے یا (فرمایا:) اس وجہ سے اسے آگ سے آزاد کر دیا ہے۔\""}],[6742,"سیدنا انس رضی اللہ عنہ سے روایت ہے ، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس شخص نے دو لڑکیوں کی ان کے بالغ ہونے تک پرورش کی ، قیامت کے دن وہ اور میں اس طرح آئیں گے ۔ \" اور آپ صلی اللہ علیہ وسلم نے اپنی انگلیوں کو ملایا ۔","",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس شخص نے دو لڑکیوں کی ان کے بالغ ہونے تک پرورش کی، قیامت کے دن وہ اور میں اس طرح آئیں گے۔\" اور آپ صلی اللہ علیہ وسلم نے اپنی انگلیوں کو ملایا۔"}],[6743,"امام مالک نے ابن شہاب سے ، انہوں نے سعید بن مسیب سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" جس کسی مسلمان کے تین بچے فوت ہو جائیں تو اسے آگ صرف قسم پورا کرنے کے لیے چھوئے گی ۔","",{"u2":"امام مالک نے ابن شہاب سے، انہوں نے سعید بن مسیب سے، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا: \"جس کسی مسلمان کے تین بچے فوت ہو جائیں تو اسے آگ صرف قسم پورا کرنے کے لیے چھوئے گی۔\""}],[6744,"سفیان اور معمر دونوں نے زہری سے مالک کی سند کے ساتھ انہی کے مفہوم میں حدیث بیان کی ، مگر سفیان کی حدیث میں ہے : \" تو وہ صرف قسم پوری کرنے کے لیے آگ میں داخل ہو گا ۔","",{"u2":"سفیان اور معمر دونوں نے زہری سے مالک کی سند کے ساتھ انہی کے مفہوم میں حدیث بیان کی، مگر سفیان کی حدیث میں ہے: \"تو وہ صرف قسم پوری کرنے کے لیے آگ میں داخل ہو گا۔\""}],[6745,"سہیل کے والد ( ابوصالح ) نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے انصار کی عورتوں سے فرمایا : \" تم میں سے جس عورت کے بھی تین بچے فوت ہو جائیں اور وہ ان ( پر صبر کرتے ہوئے ان ) کا ثواب اللہ سے طلب کرے تو وہ ضرور جنت میں داخل ہو گی ۔ \" ان میں سے ایک عورت نے کہا : یا دو ( بچے فوت ہو جائیں؟ ) اللہ کے رسول! تو آپ نے فرمایا : \" یا دو بچے ( فوت ہو جائیں ۔)","",{"u2":"سہیل کے والد (ابوصالح) نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے انصار کی عورتوں سے فرمایا: \"تم میں سے جس عورت کے بھی تین بچے فوت ہو جائیں اور وہ ان (پر صبر کرتے ہوئے ان) کا ثواب اللہ سے طلب کرے تو وہ ضرور جنت میں داخل ہو گی۔\" ان میں سے ایک عورت نے کہا: یا دو (بچے فوت ہو جائیں؟) اللہ کے رسول! تو آپ نے فرمایا: \"یا دو بچے (فوت ہو جائیں۔)\""}],[6746,"ابوعوانہ نے عبدالرحمٰن بن اصبہانی سے ، انہوں نے ابوصالح ذکوان سے اور انہوں نے سیدنا ابوسعید خدری رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک عورت آئی اور عرض کی : آپ کی گفتگو ( کا بڑا حصہ ) مرد لے گئے ، لہٰذا آپ ہمارے لیے بھی اپنی طرف سے ایک دن مقرر فرما دیں کہ ہم آپ کے پاس آیا کریں اور اللہ نے آپ کو جو سکھایا ہے اس میں سے آپ ہمیں بھی سکھا دیں ۔ آپ نے فرمایا : \" تم عورتیں فلاں فلاں دن اکٹھی ہو جانا ۔ \" خواتین اکٹھی ہو گئیں تو رسول اللہ صلی اللہ علیہ وسلم ان کے پاس تشریف لائے اور اللہ نے جو علم آپ کو عطا فرمایا تھا اس میں سے ان کو بھی سکھایا ، پھر آپ نے فرمایا : \" تم میں سے کوئی عورت نہیں جو اپنے بچوں میں سے تین بچوں کو اپنے آگے ( اللہ کے پاس ) روانہ کر دے ، مگر وہ اس کے لیے آگ سے بچانے والا پردہ بن جائیں گے ۔ \" ایک عورت نے کہا : اور دو بچے بھی اور دو بچے بھی اور دو بچے بھی؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اور دو بچے بھی اور دو بچے بھی اور دو بچے بھی ۔","",{"u2":"ابوعوانہ نے عبدالرحمٰن بن اصبہانی سے، انہوں نے ابوصالح ذکوان سے اور انہوں نے حضرت ابوسعید خدری رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک عورت آئی اور عرض کی: آپ کی گفتگو (کا بڑا حصہ) مرد لے گئے، لہذا آپ ہمارے لیے بھی اپنی طرف سے ایک دن مقرر فرما دیں کہ ہم آپ کے پاس آیا کریں اور اللہ نے آپ کو جو سکھایا ہے اس میں سے آپ ہمیں بھی سکھا دیں۔ آپ نے فرمایا: \"تم عورتیں فلاں فلاں دن اکٹھی ہو جانا۔\" خواتین اکٹھی ہو گئیں تو رسول اللہ صلی اللہ علیہ وسلم ان کے پاس تشریف لائے اور اللہ نے جو علم آپ کو عطا فرمایا تھا اس میں سے ان کو بھی سکھایا، پھر آپ نے فرمایا: \"تم میں سے کوئی عورت نہیں جو اپنے بچوں میں سے تین بچوں کو اپنے آگے (اللہ کے پاس) روانہ کر دے، مگر وہ اس کے لیے آگ سے بچانے والا پردہ بن جائیں گے۔\" ایک عورت نے کہا: اور دو بچے بھی اور دو بچے بھی اور دو بچے بھی؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اور دو بچے بھی اور دو بچے بھی اور دو بچے بھی۔\""}],[6747,"محمد بن جعفر اور معاذ نے کہا : ہمیں شعبہ نے عبدالرحمان بن اصبہانی سے اسی سند کے ساتھ اس کے ہم معنی روایت کی اور دونوں نے شعبہ سے ( روایت کرتے ہوئے ) مزید یہ کہا : عبدالرحمن بن اصبہانی سے روایت ہے ، انہوں نے کہا : میں نے ابوحازم سے سنا ، وہ سیدنا ابوہریرہ رضی اللہ عنہ سے حدیث بیان کر رہے تھے ، کہا : آپ صلی اللہ علیہ وسلم نے فرمایا : \" تین بچے جو بلوغت کی عمر کو نہیں پہنچے ۔","",{"u2":"محمد بن جعفر اور معاذ نے کہا: ہمیں شعبہ نے عبدالرحمان بن اصبہانی سے اسی سند کے ساتھ اس کے ہم معنی روایت کی اور دونوں نے شعبہ سے (روایت کرتے ہوئے) مزید یہ کہا: عبدالرحمن بن اصبہانی سے روایت ہے، انہوں نے کہا: میں نے ابوحازم سے سنا، وہ حضرت ابوہریرہ رضی اللہ عنہ سے حدیث بیان کر رہے تھے، کہا: آپ صلی اللہ علیہ وسلم نے فرمایا: \"تین بچے جو بلوغت کی عمر کو نہیں پہنچے۔\""}],[6748,"ہمیں سوید بن سعید اور محمد بن عبدالاعلی نے حدیث بیان کی ۔ ۔ دونوں کے الفاظ ملتے جلتے ہیں ۔ ۔ دونوں نے کہا : ہمیں معتمر ( بن سلیمان تیمی ) نے اپنے والد سے روایت کی ، انہوں نے ابوسلیل سے اور انہوں نے ابوحسان سے روایت کی ، انہوں نے کہا : میں نے سیدنا ابوہریرہ رضی اللہ عنہ سے کہا : میرے وہ بچے فوت ہو گئے ہیں ، آپ ہمیں رسول اللہ صلی اللہ علیہ وسلم کی کون سی حدیث سنا سکتے ہیں جس سے آپ ہمیں ہمارے فوت ہونے والوں کے متعلق ہمارے دلوں کی تسلی دلا سکیں؟ ( ابوحسان نے ) کہا : ( سیدنا ابوہریرہ رضی اللہ عنہ نے ) کہا : ہاں ۔ ( آپ صلی اللہ علیہ وسلم نے فرمایا : ) \" چھوٹے بچے جنت کے پانی کے کیڑے ہیں ( وہ جنت کے اندر ہی رہتے ہیں ) ان میں سے کوئی اپنے باپ ۔ ۔ یا فرمایا : اپنے ماں باپ ۔ ۔ کو ملے گا تو وہ اسے اس کے کپڑے سے پکڑ لے گا ۔ ۔ یا کہا : اس کے ہاتھ سے ۔ ۔ جس طرح میں نے تمہارے اس کپڑے کے کنارے سے پکڑا ہوا ہے ، پھر اس وقت تک نہیں ہٹے گا ۔ ۔ یا کہا : نہیں رکے گا ۔ ۔ یہاں تک کہ اللہ اسے اور اس کے والد کو جنت میں داخل کر دے گا ۔ \" اور سوید کی روایت میں ( ابوسلیل سے روایت ہے کے بجائے یوں ) ہے : ہمیں ابوسلیل نے حدیث سنائی ۔","",{"u2":"ہمیں سوید بن سعید اور محمد بن عبدالاعلیٰ نے حدیث بیان کی۔۔ دونوں کے الفاظ ملتے جلتے ہیں۔۔ دونوں نے کہا: ہمیں معتمر (بن سلیمان تیمی) نے اپنے والد سے روایت کی، انہوں نے ابوسلیل سے اور انہوں نے ابوحسان سے روایت کی، انہوں نے کہا: میں نے حضرت ابوہریرہ رضی اللہ عنہ سے کہا: میرے وہ بچے فوت ہو گئے ہیں، آپ ہمیں رسول اللہ صلی اللہ علیہ وسلم کی کون سی حدیث سنا سکتے ہیں جس سے آپ ہمیں ہمارے فوت ہونے والوں کے متعلق ہمارے دلوں کی تسلی دلا سکیں؟ (ابوحسان نے) کہا: (حضرت ابوہریرہ رضی اللہ عنہ نے) کہا: ہاں۔ (آپ صلی اللہ علیہ وسلم نے فرمایا:) \"چھوٹے بچے جنت کے پانی کے کیڑے ہیں (وہ جنت کے اندر ہی رہتے ہیں) ان میں سے کوئی اپنے باپ۔۔ یا فرمایا: اپنے ماں باپ۔۔ کو ملے گا تو وہ اسے اس کے کپڑے سے پکڑ لے گا۔۔ یا کہا: اس کے ہاتھ سے۔۔ جس طرح میں نے تمہارے اس کپڑے کے کنارے سے پکڑا ہوا ہے، پھر اس وقت تک نہیں ہٹے گا۔۔ یا کہا: نہیں رکے گا۔۔ یہاں تک کہ اللہ اسے اور اس کے والد کو جنت میں داخل کر دے گا۔\" اور سوید کی روایت میں (ابوسلیل سے روایت ہے کے بجائے یوں) ہے: ہمیں ابوسلیل نے حدیث سنائی۔"}],[6749,"یحیی بن سعید نے تیمی سے اسی سند کے ساتھ روایت کی اور کہا : آپ نے رسول اللہ صلی اللہ علیہ وسلم سے کوئی ایسی بات سنی ہے جس سے آپ ہمارے فوت ہو جانے والوں کے حوالے سے ہمارے دلوں کو تسلی دلا سکیں؟ ( سیدنا ابوہریرہ رضی اللہ عنہ نے ) کہا : ہاں ۔","",{"u2":"یحییٰ بن سعید نے تیمی سے اسی سند کے ساتھ روایت کی اور کہا: آپ نے رسول اللہ صلی اللہ علیہ وسلم سے کوئی ایسی بات سنی ہے جس سے آپ ہمارے فوت ہو جانے والوں کے حوالے سے ہمارے دلوں کو تسلی دلا سکیں؟ (حضرت ابوہریرہ رضی اللہ عنہ نے) کہا: ہاں۔"}],[6750,"ابوبکر بن ابی شیبہ ، محمد بن عبداللہ بن نمیر اور ابوسعید اشج نے ہمیں حدیث بیان کی ۔ ۔ الفاظ ابوبکر کے ہیں ۔ ۔ انہوں نے کہا : ہمیں حفص بن غیاث نے حدیث بیان کی ، نیز ہمیں عمر بن حفص بن غیاث نے حدیث بیان کی ۔ انہوں نے کہا؛ ہمیں میرے والد نے اپنے دادا طلق بن معاویہ سے حدیث بیان کی ، انہوں نے ابوزرعہ بن عمرو بن جریر سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : ایک عورت نبی صلی اللہ علیہ وسلم کے پاس اپنے بچے کو لے کر آئی اور کہا : اللہ کے نبی! اللہ تعالی سے اس کے حق میں دعا فرمائیے ، میں تین بچے دفن کر چکی ہوں ۔ آپ نے فرمایا : \"\" تم نے تین ( بچوں ) کو دفن کیا ہے؟ \"\" اس نے کہا : جی ہاں ، آپ نے فرمایا : \"\" تم نے دوزخ سے بچنے کے لیے ایک مضبوط باڑ لگا دی ہے ۔ \"\" عمر ( بن حفص ) نے کہا : انہوں نے اپنے دادا ( طلق ) سے روایت کی اور باقیوں نے کہا : طلق سے روایت ہے اور دادا کا ذکر نہیں کیا ۔","",{"u2":"ابوبکر بن ابی شیبہ، محمد بن عبداللہ بن نمیر اور ابوسعید اشج نے ہمیں حدیث بیان کی۔۔ الفاظ ابوبکر کے ہیں۔۔ انہوں نے کہا: ہمیں حفص بن غیاث نے حدیث بیان کی، نیز ہمیں عمر بن حفص بن غیاث نے حدیث بیان کی۔ انہوں نے کہا؛ ہمیں میرے والد نے اپنے دادا طلق بن معاویہ سے حدیث بیان کی، انہوں نے ابوزرعہ بن عمرو بن جریر سے، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: ایک عورت نبی صلی اللہ علیہ وسلم کے پاس اپنے بچے کو لے کر آئی اور کہا: اللہ کے نبی! اللہ تعالیٰ سے اس کے حق میں دعا فرمائیے، میں تین بچے دفن کر چکی ہوں۔ آپ نے فرمایا: \"تم نے تین (بچوں) کو دفن کیا ہے؟\" اس نے کہا: جی ہاں، آپ نے فرمایا: \"تم نے دوزخ سے بچنے کے لیے ایک مضبوط باڑ لگا دی ہے۔\"\nعمر (بن حفص) نے کہا: انہوں نے اپنے دادا (طلق) سے روایت کی اور باقیوں نے کہا: طلق سے روایت ہے اور دادا کا ذکر نہیں کیا۔"}],[6751,"قتیبہ بن سعید اور زہیر بن حرب نے کہا : ہمیں جریر نے طلق بن معاویہ نخعی ابوغیاث سے حدیث بیان کی ، انہوں نے ابوزرعہ بن عمرو بن جریر سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : نبی صلی اللہ علیہ وسلم کے پاس ایک عورت اپنے بیٹے کو لے کر آئی تو اس نے کہا : اللہ کے رسول! یہ بیمار ہے اور میں اس کے بارے میں ( سخت ) خوف کا شکار ہوں ، میں ( اپنے ) تین بچے دفن کر چکی ہوں ، آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" تم نے دوزخ سے بچنے کے لیے مضبوط باڑ بنا لی ہے ۔ \"\" زہیر نے کہا : طلق سے روایت ہے اور کنیت ( ابوغیاث ) کا ذکر نہیں کیا ۔","",{"u2":"قتیبہ بن سعید اور زہیر بن حرب نے کہا: ہمیں جریر نے طلق بن معاویہ نخعی ابوغیاث سے حدیث بیان کی، انہوں نے ابوزرعہ بن عمرو بن جریر سے اور انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: نبی صلی اللہ علیہ وسلم کے پاس ایک عورت اپنے بیٹے کو لے کر آئی تو اس نے کہا: اللہ کے رسول! یہ بیمار ہے اور میں اس کے بارے میں (سخت) خوف کا شکار ہوں، میں (اپنے) تین بچے دفن کر چکی ہوں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم نے دوزخ سے بچنے کے لیے مضبوط باڑ بنا لی ہے۔\"\nزہیر نے کہا: طلق سے روایت ہے اور کنیت (ابوغیاث) کا ذکر نہیں کیا۔"}],[6752,"جریر نے سہیل سے ، انہوں نے اپنے والد ( ابوصالح ) سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جب اللہ تعالی کسی بندے سے محبت کرتا ہے تو جبریل علیہ السلام کو بلاتا ہے اور فرماتا ہے : میں فلاں سے محبت کرتا ہوں تم بھی اس سے محبت کرو ، کہا : تو جبرئیل اس سے محبت کرتے ہیں ، پھر وہ آسمان میں آواز دیتے ہیں ، کہتے ہیں : اللہ تعالی فلاں شخص سے محبت کرتاہے ، تم بھی اس سے محبت کرو ، چنانچہ آسمان والے اس سے محبت کرتے ہیں ، کہا : پھر اس کے لیے زمین میں مقبولیت رکھ دی جاتی ہے ، اور جب اللہ تعالی کسی بندے سے بغض رکھتا ہے تو جبرئیل کو بُلا کر فرماتا ہے : میں فلاں شخص سے بغج رکھتا ہوں ، تم بھی اس سے بغض رکھو ، تو جبرئیل اس سے بغض رکھتے ہیں ، پھر وہ آسمان والوں میں اعلان کرتے ہیں کہ اللہ تعالی فلاں سے بغض رکھتا ے ، تم بھی اس سے بغض رکھو ، کہا : تو وہ ( سب ) اس سے بغض رکھتے ہیں ، پھر اس کے لیے زمین میں بھی بغض رکھ دیا جاتا ہے ۔","",{"u2":"جریر نے سہیل سے، انہوں نے اپنے والد (ابوصالح) سے، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب اللہ تعالیٰ کسی بندے سے محبت کرتا ہے تو جبریل علیہ السلام کو بلاتا ہے اور فرماتا ہے: میں فلاں سے محبت کرتا ہوں تم بھی اس سے محبت کرو، کہا: تو جبرئیل اس سے محبت کرتے ہیں، پھر وہ آسمان میں آواز دیتے ہیں، کہتے ہیں: اللہ تعالیٰ فلاں شخص سے محبت کرتاہے، تم بھی اس سے محبت کرو، چنانچہ آسمان والے اس سے محبت کرتے ہیں، کہا: پھر اس کے لیے زمین میں مقبولیت رکھ دی جاتی ہے، اور جب اللہ تعالیٰ کسی بندے سے بغض رکھتا ہے تو جبرئیل کو بُلا کر فرماتا ہے: میں فلاں شخص سے بغج رکھتا ہوں، تم بھی اس سے بغض رکھو، تو جبرئیل اس سے بغض رکھتے ہیں، پھر وہ آسمان والوں میں اعلان کرتے ہیں کہ اللہ تعالیٰ فلاں سے بغض رکھتا ے، تم بھی اس سے بغض رکھو، کہا: تو وہ (سب) اس سے بغض رکھتے ہیں، پھر اس کے لیے زمین میں بھی بغض رکھ دیا جاتا ہے۔\""}],[6753,"عبدالعزیز دراوردی ، علاء بن مسیب اور امام مالک بن انس سب نے سہیل سے اسی سند کے ساتھ روایت کی ، البتہ علاء بن مسیب کی حدیث میں بغض کا ذکر نہیں ہے ( صرف محبت کرنے کی بات ہے ۔)","",{"u2":") عبدالعزیز دراوردی، علاء بن مسیب اور امام مالک بن انس سب نے سہیل سے اسی سند کے ساتھ روایت کی، البتہ علاء بن مسیب کی حدیث میں بغض کا ذکر نہیں ہے (صرف محبت کرنے کی بات ہے۔)"}],[6754,"عبدالعزیز بن عبداللہ بن ابی سلمی ماجثون نے سہیل سے ، انہوں نے ابوصالح سے روایت کی ، کہا : ہم عرفہ میں تھے کہ سیدنا عمر بن عبدالعزیز کا وہاں سے گذر ہوا اور وہ حج کے امیر تھے ، لوگ کھڑے ہو کر انہیں دیکھنے لگے ، میں نے اپنے والد سے کہا : ابا جان! میں یہ دیکھ رہا ہوں کہ اللہ تعالی عمر بن عبدالعزیز سے محبت کرتا ہے ، انہوں نے پوچھا : اس کا کیا سبب ہے؟ میں نے کہا : اس لیے کہ لوگوں کے دلوں میں ان کی محبت پائی جاتی ہے ، انہوں ( ابوصالح ) نے کہا : تیرا باپ قربان ہو! تم نے سیدنا ابوہریرہ رضی اللہ عنہ سے رسول اللہ صلی اللہ علیہ وسلم کی حدیث سنی ہے ۔ اس کے بعد انہوں نے سہیل سے جریر کی روایت کردہ حدیث بیان کی ۔","",{"u2":"عبدالعزیز بن عبداللہ بن ابی سلمی ماجثون نے سہیل سے، انہوں نے ابوصالح سے روایت کی، کہا: ہم عرفہ میں تھے کہ حضرت عمر بن عبدالعزیز کا وہاں سے گذر ہوا اور وہ حج کے امیر تھے، لوگ کھڑے ہو کر انہیں دیکھنے لگے، میں نے اپنے والد سے کہا: ابا جان! میں یہ دیکھ رہا ہوں کہ اللہ تعالیٰ عمر بن عبدالعزیز سے محبت کرتا ہے، انہوں نے پوچھا: اس کا کیا سبب ہے؟ میں نے کہا: اس لیے کہ لوگوں کے دلوں میں ان کی محبت پائی جاتی ہے، انہوں (ابوصالح) نے کہا: تیرا باپ قربان ہو! تم نے حضرت ابوہریرہ رضی اللہ عنہ سے رسول اللہ صلی اللہ علیہ وسلم کی حدیث سنی ہے۔ اس کے بعد انہوں نے سہیل سے جریر کی روایت کردہ حدیث بیان کی۔"}],[6755,"ابوصالح نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" روحیں ایک دوسرے کے ساتھ رہنے والی جماعتیں ہیں ۔ ان میں سے جو ایک دوسرے ( کی ایک جیسی صفات ) سے آگاہ ہو گئیں ان میں یکجائی ( الفت ) ہو گئی اور ( صفات کے اختلاف کی بنا پر ) جو ایک دوسرے سے گریزاں رہیں وہ باہم مختلف ہو گئیں ۔","",{"u2":"ابوصالح نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"روحیں ایک دوسرے کے ساتھ رہنے والی جماعتیں ہیں۔ ان میں سے جو ایک دوسرے (کی ایک جیسی صفات) سے آگاہ ہو گئیں ان میں یکجائی (الفت) ہو گئی اور (صفات کے اختلاف کی بنا پر) جو ایک دوسرے سے گریزاں رہیں وہ باہم مختلف ہو گئیں۔\""}],[6756,"یزید بن اصم نے سیدنا ابوہریرہ رضی اللہ عنہ سے مرفوعا ایک حدیث بیان کی ، کہا : \" لوگ سونے چاندی کی کانوں کی طرح معدنیات کی کانیں ہیں ، جو زمانہ جاہلیت میں اچھے تھے وہ اگر دین کو سمجھ لیں تو زمانہ اسلام میں بھی اچھے ہیں ۔ اور روحیں ایک ساتھ رہنے والی جماعتیں ہیں جو آپس میں ( ایک جیسی صفات کی بنا پر ) ایک دوسرے کو پہنچاننے لگیں ان میں یکجائی پیدا ہو گئی اور جو ( صفات کے اختلاف کی بنا پر ) ایک دوسرے سے گریزاں رہیں ، وہ باہم مختلف ہو گئیں ۔","",{"u2":"یزید بن اصم نے حضرت ابوہریرہ رضی اللہ عنہ سے مرفوعا ایک حدیث بیان کی، کہا: \"لوگ سونے چاندی کی کانوں کی طرح معدنیات کی کانیں ہیں، جو زمانہ جاہلیت میں اچھے تھے وہ اگر دین کو سمجھ لیں تو زمانہ اسلام میں بھی اچھے ہیں۔ اور روحیں ایک ساتھ رہنے والی جماعتیں ہیں جو آپس میں (ایک جیسی صفات کی بنا پر) ایک دوسرے کو پہنچاننے لگیں ان میں یکجائی پیدا ہو گئی اور جو (صفات کے اختلاف کی بنا پر) ایک دوسرے سے گریزاں رہیں، وہ باہم مختلف ہو گئیں۔\""}],[6757,"اسحاق بن عبداللہ بن ابی طلحہ نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی کہ ایک اعرابی نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا : قیامت کب آئے گی؟ رسول اللہ صلی اللہ علیہ وسلم نے اس سے فرمایا : \" تم نے اس کے لیے کیا تیار کر رکھا ہے؟ \" اس نے کہا : اللہ اور اس کے رسول کی محبت ۔ آپ نے فرمایا : \" تم اسی کے ساتھ ہو گے جس سے تم کو محبت ہے ۔","",{"u2":"اسحاق بن عبداللہ بن ابی طلحہ نے حضرت انس بن مالک رضی اللہ عنہ سے روایت کی کہ ایک اعرابی نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: قیامت کب آئے گی؟ رسول اللہ صلی اللہ علیہ وسلم نے اس سے فرمایا: \"تم نے اس کے لیے کیا تیار کر رکھا ہے؟\" اس نے کہا: اللہ اور اس کے رسول کی محبت۔ آپ نے فرمایا: \"تم اسی کے ساتھ ہو گے جس سے تم کو محبت ہے۔\""}],[6758,"سفیان نے زہری سے ، انہوں نے سیدنا انس رضی اللہ عنہ سے روایت کی ، کہا : ایک شخص نے پوچھا : اللہ کے رسول! قیامت کب ہو گی؟ آپ نے فرمایا : تم نے اس کے لیے کیا تیار کی ہے؟ \" اس نے زیادہ چیزوں کا ذکر نہیں کیا ، ( چند ایک کاموں کا ذکر کر سکا ) اس نے کہا : اور لیکن میں اللہ اور اس کے رسول صلی اللہ علیہ وسلم سے محبت کرتا ہوں ، آپ نے فرمایا : \" تم اس کے ساتھ ہو گے جس سے تمہیں محبت ہے ۔","",{"u2":"سفیان نے زہری سے، انہوں نے حضرت انس رضی اللہ عنہ سے روایت کی، کہا: ایک شخص نے پوچھا: اللہ کے رسول! قیامت کب ہو گی؟ آپ نے فرمایا: تم نے اس کے لیے کیا تیار کی ہے؟\" اس نے زیادہ چیزوں کا ذکر نہیں کیا، (چند ایک کاموں کا ذکر کر سکا) اس نے کہا: اور لیکن میں اللہ اور اس کے رسول صلی اللہ علیہ وسلم سے محبت کرتا ہوں، آپ نے فرمایا: \"تم اس کے ساتھ ہو گے جس سے تمہیں محبت ہے۔\""}],[6759,"سفیان نے زہری سے ، انہوں نے سیدنا انس رضی اللہ عنہ سے روایت کی ، کہا : ایک شخص نے پوچھا : اللہ کے رسول! قیامت کب ہو گی؟ آپ نے فرمایا : تم نے اس کے لیے کیا تیار کی ہے؟ \" اس نے زیادہ چیزوں کا ذکر نہیں کیا ، ( چند ایک کاموں کا ذکر کر سکا ) اس نے کہا : اور لیکن میں اللہ اور اس کے رسول صلی اللہ علیہ وسلم سے محبت کرتا ہوں ، آپ نے فرمایا : \" تم اس کے ساتھ ہو گے جس سے تمہیں محبت ہے ۔","",{"u2":"معمر نے زہری سے روایت کی، انہوں نے کہا: مجھے حضرت انس بن مالک رضی اللہ عنہ نے حدیث سنائی کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک اعرابی آیا، اسی (سابقہ حدیث) کے مانند مگر (اس میں ہے کہ) اس نے کہا: میں نے اس کے لیے کچھ زیادہ تیار نہیں کی جس پر میں اپنی تعریف کر سکوں (لیکن میں اللہ اور اس کے رسول صلی اللہ علیہ وسلم سے محبت کرتا ہوں۔)"}],[6760,"حماد بن زید نے کہا : ہمیں ثابت بنانی نے سیدنا انس بن مالک رضی اللہ عنہ سے حدیث بیان کی ، انہوں نے کہا : ایک شخص رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور عرض کی : اللہ کے رسول! قیامت کب ہو گی؟ آپ نے فرمایا : \"\" تم نے اس کے لیے کیا تیار کیا ہے؟ \"\" اس نے کہا : اللہ اور اس کے رسول صلی اللہ علیہ وسلم کی محبت ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" تم اسی کے ساتھ ہو گے جس سے تم کو محبت ہو گی ۔ \"\" سیدنا انس رضی اللہ عنہ نے کہا : اسلام قبول کرنے کے بعد ہمیں نبی صلی اللہ علیہ وسلم کے اس ارشاد سے بڑھ کر اور کسی بات سے اتنی خوشی نہیں ہوئی : \"\" تم اس کے ساتھ ہو گے جس سے تم کو محبت ہو گی ۔ \"\" سیدنا انس رضی اللہ عنہ نے کہا : میں اللہ اور اس کے رسول صلی اللہ علیہ وسلم اور ابوبکر اور عمر رضی اللہ عنہما سے محبت کرتا ہوں اور مجھے امید ہے کہ میں ان کے ساتھ ہوں گا ، ہر چند کہ میں نے ان کی طرح عمل نہیں کیے ۔","",{"u2":"حماد بن زید نے کہا: ہمیں ثابت بنانی نے حضرت انس بن مالک رضی اللہ عنہ سے حدیث بیان کی، انہوں نے کہا: ایک شخص رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور عرض کی: اللہ کے رسول! قیامت کب ہو گی؟ آپ نے فرمایا: \"تم نے اس کے لیے کیا تیار کیا ہے؟\" اس نے کہا: اللہ اور اس کے رسول صلی اللہ علیہ وسلم کی محبت۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم اسی کے ساتھ ہو گے جس سے تم کو محبت ہو گی۔\"\nحضرت انس رضی اللہ عنہ نے کہا: اسلام قبول کرنے کے بعد ہمیں نبی صلی اللہ علیہ وسلم کے اس ارشاد سے بڑھ کر اور کسی بات سے اتنی خوشی نہیں ہوئی: \"تم اس کے ساتھ ہو گے جس سے تم کو محبت ہو گی۔\"\nحضرت انس رضی اللہ عنہ نے کہا: میں اللہ اور اس کے رسول صلی اللہ علیہ وسلم اور ابوبکر اور عمر رضی اللہ عنہما سے محبت کرتا ہوں اور مجھے امید ہے کہ میں ان کے ساتھ ہوں گا، ہر چند کہ میں نے ان کی طرح عمل نہیں کیے۔"}],[6761,"جعفر بن سلیمان نے ہمیں حدیث سنائی ، کہا : ہمیں ثابت بنانی نے سیدنا انس بن مالک رضی اللہ عنہ سے حدیث سنائی ، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی اور انہوں نے سیدنا انس رضی اللہ عنہ کا یہ قول کہ میں ( اللہ اور اس کے رسول صلی اللہ علیہ وسلم ) سے محبت کرتا ہوں ، اور اس کے بعد والی بات بیان نہیں کی ۔","",{"u2":"جعفر بن سلیمان نے ہمیں حدیث سنائی، کہا: ہمیں ثابت بنانی نے حضرت انس بن مالک رضی اللہ عنہ سے حدیث سنائی، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی اور انہوں نے حضرت انس رضی اللہ عنہ کا یہ قول کہ میں (اللہ اور اس کے رسول صلی اللہ علیہ وسلم) سے محبت کرتا ہوں، اور اس کے بعد والی بات بیان نہیں کی۔"}],[6762,"منصور نے سالم بن ابی جعد سے روایت کی ، انہوں نے کہا : ہمیں سیدنا انس بن مالک رضی اللہ عنہ نے حدیث بیان کی ، کہا : ایک بار جب میں اور رسول اللہ صلی اللہ علیہ وسلم مسجد سے نکل رہے تھے تو مسجد کی چوکھٹ کے پاس ہماری ایک شخص سے ملاقات ہوئی ، اس نے کہا : اللہ کے رسول! قیامت کب ہے؟ آپ نے فرمایا : \" تم نے اس کے لیے کیا تیار کیا ہے؟ تو جیسے وہ ٹھٹھک گیا ، پھر اس نے کہا : اللہ کے رسول! میں نے اس کے لیے بہت زیادہ نمازیں ، بہت زیادہ روزے اور بہت زیادہ صدقات تو تیار نہیں کیے ، لیکن میں اللہ اور اس کے رسول صلی اللہ علیہ وسلم سے محبت رکھتا ہوں ، آپ نے فرمایا : \" تم اسی کے ساتھ ہو گے جس سے تمہیں محبت ہو گی ۔","",{"u2":"منصور نے سالم بن ابی جعد سے روایت کی، انہوں نے کہا: ہمیں حضرت انس بن مالک رضی اللہ عنہ نے حدیث بیان کی، کہا: ایک بار جب میں اور رسول اللہ صلی اللہ علیہ وسلم مسجد سے نکل رہے تھے تو مسجد کی چوکھٹ کے پاس ہماری ایک شخص سے ملاقات ہوئی، اس نے کہا: اللہ کے رسول! قیامت کب ہے؟ آپ نے فرمایا: \"تم نے اس کے لیے کیا تیار کیا ہے؟ تو جیسے وہ ٹھٹھک گیا، پھر اس نے کہا: اللہ کے رسول! میں نے اس کے لیے بہت زیادہ نمازیں، بہت زیادہ روزے اور بہت زیادہ صدقات تو تیار نہیں کیے، لیکن میں اللہ اور اس کے رسول صلی اللہ علیہ وسلم سے محبت رکھتا ہوں، آپ نے فرمایا: \"تم اسی کے ساتھ ہو گے جس سے تمہیں محبت ہو گی۔\""}],[6763,"عمرو بن مرہ نے سالم بن ابی جعد سے ، انہوں نے سیدنا انس رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی ۔","",{"u2":"عمرو بن مرہ نے سالم بن ابی جعد سے، انہوں نے حضرت انس رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی۔"}],[6764,"ابوعوانہ ، شعبہ اور ہشام نے قتادہ سے ، انہوں نے سیدنا انس رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے یہی حدیث روایت کی ۔"],[6765,"ابوعوانہ ، شعبہ اور ہشام نے قتادہ سے ، انہوں نے سیدنا انس رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے یہی حدیث روایت کی ۔"],[6766,"ابوعوانہ ، شعبہ اور ہشام نے قتادہ سے ، انہوں نے سیدنا انس رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے یہی حدیث روایت کی ۔","",{"u2":"ابوعوانہ، شعبہ اور ہشام نے قتادہ سے، انہوں نے حضرت انس رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے یہی حدیث روایت کی۔"}],[6767,"جریر نے ( سلیمان ) اعمش سے ، انہوں نے ابووائل سے ، انہوں نے سیدنا عبداللہ ( بن مسعود رضی اللہ عنہ ) سے روایت کی ، کہا : ایک شخص رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا ، اس نے کہا : اللہ کے رسول! آپ اس شخص کو کیسے دیکھتے ہیں جو کسی قوم سے محبت کرتا ہے مگر ابھی تک اس کے ساتھ نہیں ملا؟ ( اعمال میں ان سے بہت پیچھے ہے ) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" آدمی اسی کے ساتھ ہو گا جس سے وہ محبت کرتا ہے ۔","",{"u2":"جریر نے (سلیمان) اعمش سے، انہوں نے ابووائل سے، انہوں نے حضرت عبداللہ (بن مسعود رضی اللہ عنہ) سے روایت کی، کہا: ایک شخص رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، اس نے کہا: اللہ کے رسول! آپ اس شخص کو کیسے دیکھتے ہیں جو کسی قوم سے محبت کرتا ہے مگر ابھی تک اس کے ساتھ نہیں ملا؟ (اعمال میں ان سے بہت پیچھے ہے) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"آدمی اسی کے ساتھ ہو گا جس سے وہ محبت کرتا ہے۔\""}],[6768,"شعبہ اور سلیمان بن قرم نے سلیمان ( اعمش ) سے ، انہوں نے ابووائل سے ، انہوں نے عبداللہ ( بن مسعود رضی اللہ عنہ ) سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی ۔","",{"u2":"شعبہ اور سلیمان بن قرم نے سلیمان (اعمش) سے، انہوں نے ابووائل سے، انہوں نے عبداللہ (بن مسعود رضی اللہ عنہ) سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی۔"}],[6769,"ابومعاویہ اور محمد بن عبید نے اعمش سے ، انہوں نے ( ابووائل ) شقیق سے اور انہوں نے ابوموسی رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : نبی صلی اللہ علیہ وسلم کے پاس ایک شخص آیا ، پھر اعمش سے جریر کی روایت کے مانند حدیث بیان کی ۔","",{"u2":"ابومعاویہ اور محمد بن عبید نے اعمش سے، انہوں نے (ابووائل) شقیق سے اور انہوں نے ابوموسیٰ رضی اللہ عنہ سے روایت کی، انہوں نے کہا: نبی صلی اللہ علیہ وسلم کے پاس ایک شخص آیا، پھر اعمش سے جریر کی روایت کے مانند حدیث بیان کی۔"}],[6770,"حماد بن زید نے ابوعمران جونی سے ، انہوں نے عبداللہ بن صامت سے ، انہوں نے سیدنا ابوذر رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم سے عرض کی گئی : آپ کا کیا خیال ہے کہ ایک شخص اچھے کام کرتا ہے اور لوگ اس کی تعریف کرتے ہیں؟ آپ نے فرمایا : \" یہ مومن کے لیے فوری بشارت ہے ۔","",{"u2":"حماد بن زید نے ابوعمران جونی سے، انہوں نے عبداللہ بن صامت سے، انہوں نے حضرت ابوذر رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم سے عرض کی گئی: آپ کا کیا خیال ہے کہ ایک شخص اچھے کام کرتا ہے اور لوگ اس کی تعریف کرتے ہیں؟ آپ نے فرمایا: \"یہ مومن کے لیے فوری بشارت ہے۔\""}],[6771,"وکیع ، محمد بن جعفر ، عبدالصمد اور نضر سب نے شعبہ سے ، انہوں نے ابوعمران جونی سے حماد بن زید کی سند کے ساتھ ، اسی کی حدیث کے مانند روایت کی ، مگر شعبہ سے عبدالصمد کے سوا ( باقی ) سب کی حدیث میں ہے : \" اور لوگ اس کی وجہ سے اس کے ساتھ محبت کرتے ہیں ۔ \" اور عبدالصمد کی حدیث میں ہے : \" اور لوگ اس کی تعریف کرتے ہیں \" جس طرح حماد نے کہا ہے ۔","",{"u2":"وکیع، محمد بن جعفر، عبدالصمد اور نضر سب نے شعبہ سے، انہوں نے ابوعمران جونی سے حماد بن زید کی سند کے ساتھ، اسی کی حدیث کے مانند روایت کی، مگر شعبہ سے عبدالصمد کے سوا (باقی) سب کی حدیث میں ہے: \"اور لوگ اس کی وجہ سے اس کے ساتھ محبت کرتے ہیں۔\" اور عبدالصمد کی حدیث میں ہے: \"اور لوگ اس کی تعریف کرتے ہیں\" جس طرح حماد نے کہا ہے۔"}],[6772,"عبداللہ بن نمیر ہمدانی ، ابومعاویہ اور وکیع نے ہمیں حدیث بیان کی ، انہوں نے کہا : ہمیں اعمش نے زید بن وہب سے حدیث بیان کی ، انہوں نے سیدنا عبداللہ ( بن مسعود ) رضی اللہ عنہ سے روایت کی کہ اللہ کے رسول صلی اللہ علیہ وسلم اور وہ سچ بتاتے ہیں اور انہیں ( وحی کے ذریعے سے ) سچ بتایا جاتا ہے نے فرمایا : \" تم میں سے ہر ایک شخص کا مادہ تخلیق چالیس دن تک اس کی ماں کے پیٹ میں اکٹھا کیا جاتا ہے ، پھر وہ اتنی مدت ( چالیس دن ) کے لیے علقہ ( جونک کی طرح رحم کی دیوار کے ساتھ چپکا ہوا ) رہتا ہے ، پھر اتنی ہی مدت کے لیے مُضغہ کی شکل میں رہتا ہے ( جس میں ریڑھ کی ہڈی کے نشانات دانت سے چبائے جانے کے نشانات سے مشابہ ہوتے ہیں ۔ ) پھر اللہ تعالی فرشتے کو بھیجتا ہے جو ( پانچویں مہینے نیوروسیل ، یعنی دماغ کی تخلیق ہو جانے کے بعد ) اس میں روح پھونکتا ہے ۔ اور اسے چار باتوں کا حکم دیا جاتا ہے کہ اس کا رزق ، اس کی عمر ، اس کا عمل اور یہ کہ وہ خوش نصیب ہو گا یا بدنصیب ، لکھ لیا جائے ۔ مجھے اس ذات کی قسم جس کے سوا کوئی عبادت کے لائق نہیں! تم میں سے کوئی ایک شخص اہل جنت کے سے عمل کرتا رہتا ہے ، یہاں تک کہ جب اس کے اور جنت کے درمیان ایک بالشت کا فاصلہ رہ جاتا ہے تو ( اللہ کے علم کے مطابق ) لکھا ہوا اس پر غالب آ جاتا ہے تو وہ اہل جہنم کا عمل کر لیتا ہے اور اس ( جہنم ) میں داخل ہو جاتا ہے ۔ اور تم میں سے ایک شخص اہل جہنم کے سے عمل کرتا رہتا ہے حتی کہ اس کے اور جہنم کے درمیان ایک بالشت کا فاصلہ رہ جاتا ہے تو ( اللہ کے علم کے مطابق ) لکھا ہوا اس پر غالب آ جاتا ہے اور وہ اہل جنت کا عمل کر لیتا ہے اور اس ( جنت ) میں داخل ہو جاتا ہے ۔","",{"u2":"عبداللہ بن نمیر ہمدانی، ابومعاویہ اور وکیع نے ہمیں حدیث بیان کی، انہوں نے کہا: ہمیں اعمش نے زید بن وہب سے حدیث بیان کی، انہوں نے حضرت عبداللہ (بن مسعود) رضی اللہ عنہ سے روایت کی کہ اللہ کے رسول صلی اللہ علیہ وسلم اور وہ سچ بتاتے ہیں اور انہیں (وحی کے ذریعے سے) سچ بتایا جاتا ہے نے فرمایا: \"تم میں سے ہر ایک شخص کا مادہ تخلیق چالیس دن تک اس کی ماں کے پیٹ میں اکٹھا کیا جاتا ہے، پھر وہ اتنی مدت (چالیس دن) کے لیے علقہ (جونک کی طرح رحم کی دیوار کے ساتھ چپکا ہوا) رہتا ہے، پھر اتنی ہی مدت کے لیے مُضغہ کی شکل میں رہتا ہے (جس میں ریڑھ کی ہڈی کے نشانات دانت سے چبائے جانے کے نشانات سے مشابہ ہوتے ہیں۔) پھر اللہ تعالیٰ فرشتے کو بھیجتا ہے جو (پانچویں مہینے نیوروسیل، یعنی دماغ کی تخلیق ہو جانے کے بعد) اس میں روح پھونکتا ہے۔ اور اسے چار باتوں کا حکم دیا جاتا ہے کہ اس کا رزق، اس کی عمر، اس کا عمل اور یہ کہ وہ خوش نصیب ہو گا یا بدنصیب، لکھ لیا جائے۔ مجھے اس ذات کی قسم جس کے سوا کوئی عبادت کے لائق نہیں! تم میں سے کوئی ایک شخص اہل جنت کے سے عمل کرتا رہتا ہے، یہاں تک کہ جب اس کے اور جنت کے درمیان ایک بالشت کا فاصلہ رہ جاتا ہے تو (اللہ کے علم کے مطابق) لکھا ہوا اس پر غالب آ جاتا ہے تو وہ اہل جہنم کا عمل کر لیتا ہے اور اس (جہنم) میں داخل ہو جاتا ہے۔ اور تم میں سے ایک شخص اہل جہنم کے سے عمل کرتا رہتا ہے حتی کہ اس کے اور جہنم کے درمیان ایک بالشت کا فاصلہ رہ جاتا ہے تو (اللہ کے علم کے مطابق) لکھا ہوا اس پر غالب آ جاتا ہے اور وہ اہل جنت کا عمل کر لیتا ہے اور اس (جنت) میں داخل ہو جاتا ہے۔\""}],[6773,"عثمان بن ابی شیبہ اور اسحٰق بن ابراہیم نے ہمیں حدیث بیان کی ، دونوں نے جریر بن عبدالحمید سے روایت کی ، نیز ہمیں اسحق بن ابراہیم نے عیسی بن یونس سے خبر دی ۔ اور ابوسعید اشج نے مجھے بیان کیا ، کہا : ہمیں وکیع نے حدیث بیان کی کہ عبیداللہ بن معاذ نے کہا : ہمیں میرے والد نے حدیث بیان کی ، انہوں نے کہا : ہمیں شعبہ بن حجاج نے حدیث بیان کی ، ان سب ( جریر ، عیسی ، وکیع اور شعبہ ) نے اعمش سے ، اسی سند کے ساتھ روایت کی ۔ وکیع کی حدیث میں کہا : \" تم میں سے ایک انسان کا مادہ تخلیق چالیس راتوں تک اپنی ماں کے پیٹ میں اکٹھا ( ہونے کے مرحلے میں ) ہوتا ہے ۔ \" اور شعبہ سے معاذ کی حدیث میں \" چالیس راتیں یا چالیس دن \" اور جریر اور عیسی کی حدیث میں \" چالیس دن \" ہے ۔","",{"u2":"عثمان بن ابی شیبہ اور اسحٰق بن ابراہیم نے ہمیں حدیث بیان کی، دونوں نے جریر بن عبدالحمید سے روایت کی، نیز ہمیں اسحق بن ابراہیم نے عیسیٰ بن یونس سے خبر دی۔ اور ابوسعید اشج نے مجھے بیان کیا، کہا: ہمیں وکیع نے حدیث بیان کی کہ عبیداللہ بن معاذ نے کہا: ہمیں میرے والد نے حدیث بیان کی، انہوں نے کہا: ہمیں شعبہ بن حجاج نے حدیث بیان کی، ان سب (جریر، عیسیٰ، وکیع اور شعبہ) نے اعمش سے، اسی سند کے ساتھ روایت کی۔ وکیع کی حدیث میں کہا: \"تم میں سے ایک انسان کا مادہ تخلیق چالیس راتوں تک اپنی ماں کے پیٹ میں اکٹھا (ہونے کے مرحلے میں) ہوتا ہے۔\" اور شعبہ سے معاذ کی حدیث میں \"چالیس راتیں یا چالیس دن\" اور جریر اور عیسیٰ کی حدیث میں \"چالیس دن\" ہے۔"}],[6774,"عمرو بن دینار نے ابوطفیل ( عامر بن واثلہ رضی اللہ عنہ ) سے ، انہوں نے حذیفہ بن اسید رضی اللہ عنہ سے روایت کی جو انہوں نے نبی صلی اللہ علیہ وسلم تک پہنچائی ( مرفوع بیان کی ) ، آپ صلی اللہ علیہ وسلم نے فرمایا : \" جب نطفہ ( چالیس چالیس دنوں کے دو مرحلوں کے بعد تیسرے مرحلے میں ) چالیس یا پینتالیس راتیں رحم میں ٹھہرا رہتا ہے تو ( اللہ کا مقرر کیا ہوا ) فرشتہ اس کے پاس جاتا ہے اور کہتا ہے : اے رب! یہ خوش نصیب ہو گا یا بدنصیب ہو گا؟ تو دونوں ( باتوں میں سے اللہ کو بتائے اس ) کو لکھ لیا جاتا ہے ، پھر کہتا ہے : اے رب! یہ مرد ہے یا عورت؟ پھر دونوں ( میں سے جو اللہ بتائے اس ) کو لکھ لیا جاتا ہے ، پھر اس کا عمل ، اس کے قدموں کے نشانات ، اس کی مدت عمر اور اس کا رزق لکھ لیا جاتا ہے ، پھر ( اندراج کے ) صحیفے لپیٹ دیے جاتے ہیں ، پھر ان میں کوئی چیز بڑھائی جاتی ہے ، نہ کم کی جاتی ہے ۔","",{"u2":"عمرو بن دینار نے ابوطفیل (عامر بن واثلہ رضی اللہ عنہ) سے، انہوں نے حذیفہ بن اسید رضی اللہ عنہ سے روایت کی جو انہوں نے نبی صلی اللہ علیہ وسلم تک پہنچائی (مرفوع بیان کی)، آپ صلی اللہ علیہ وسلم نے فرمایا: \"جب نطفہ (چالیس چالیس دنوں کے دو مرحلوں کے بعد تیسرے مرحلے میں) چالیس یا پینتالیس راتیں رحم میں ٹھہرا رہتا ہے تو (اللہ کا مقرر کیا ہوا) فرشتہ اس کے پاس جاتا ہے اور کہتا ہے: اے رب! یہ خوش نصیب ہو گا یا بدنصیب ہو گا؟ تو دونوں (باتوں میں سے اللہ کو بتائے اس) کو لکھ لیا جاتا ہے، پھر کہتا ہے: اے رب! یہ مرد ہے یا عورت؟ پھر دونوں (میں سے جو اللہ بتائے اس) کو لکھ لیا جاتا ہے، پھر اس کا عمل، اس کے قدموں کے نشانات، اس کی مدت عمر اور اس کا رزق لکھ لیا جاتا ہے، پھر (اندراج کے) صحیفے لپیٹ دیے جاتے ہیں، پھر ان میں کوئی چیز بڑھائی جاتی ہے، نہ کم کی جاتی ہے۔\""}],[6775,"عمرو بن حارث نے ابوزبیر علی سے روایت کی کہ سیدنا عامر بن واثلہ رضی اللہ عنہ نے انہیں حدیث بیان کی ، انہوں نے سیدنا عبداللہ بن مسعود رضی اللہ عنہ کو یہ کہتے ہوئے سنا : بدبخت وہ ہے جو اپنی ماں کے پیٹ میں ( تھا تو اللہ کے علم کے مطابق ) بدبخت تھا اور سعادت مند وہ ہے جو اپنے علاوہ دوسرے سے نصیحت حاصل کرے ، پھر رسول اللہ صلی اللہ علیہ وسلم کے صحابہ میں سے ایک شخص آئے جنہیں سیدنا حذیفہ بن اسید غفاری رضی اللہ عنہ کہا جاتا تھا ، انہوں ( عامر بن واثلہ رضی اللہ عنہ ) نے ان کو سیدنا ابن مسعود رضی اللہ عنہ کے الفاظ میں یہ حدیث سنائی اور ( ان سے پوچھنے کے لیے ) کہا : وہ شخص کوئی عمل کیے بغیر بدبخت کیسے ہو جاتا ہے؟ تو اس ( عامر ) کو آدمی ( حذیفہ رضی اللہ عنہ ) نے کہا : کیا آپ اس پر تعجب کرتے ہیں؟ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا ہے : \" جب نطفے پر ( تیسرے مرحلے کی ) بیالیس راتیں گذر جاتی ہیں تو اللہ تعالی اس کے پاس ایک فرشتہ بھیجتا ہے ، وہ اس کی صورت بناتا ہے ، اس کے کان ، آنکھیں ، کھال ، گوشت اور اس کی ہڈیاں بناتا ہے ، پھر کہتا ہے : اے میرے رب! یہ مرد ہو گا کہ عورت؟ پھر تمہارا رب جو چاہتا ہوتا ہے وہ فیصلہ بتاتا ہے اور فرشتہ لکھ لیتا ہے ، پھر وہ کہتا ہے : اے میرے رب! اس کی مدت حیات ( کتنی ہو گی؟ ) پھر تمہارا رب جو اس کی مچیت ہوتی ہے ، بتاتا ہے اور فرشتہ لکھ لیتا ہے ، پھر وہ ( فرشتہ ) کہتا ہے : اے میرے رب! اس کا رزق ( کتنا ہو گا؟ ) تو تمہارا رب جو چاہتا ہوتا ہے وہ فیصلہ بتاتا ہے اور فرشتہ لکھ لیتا ہے ، پھر فرشتہ اپنے ہاتھ میں صحیفہ لے کر نکل جاتا ہے ، چنانچہ وہ شخص کسی معاملے میں نہ اس سے بڑھتا ہے ، نہ کم ہوتا ہے ۔","",{"u2":"عمرو بن حارث نے ابوزبیر علی سے روایت کی کہ حضرت عامر بن واثلہ رضی اللہ عنہ نے انہیں حدیث بیان کی، انہوں نے حضرت عبداللہ بن مسعود رضی اللہ عنہ کو یہ کہتے ہوئے سنا: بدبخت وہ ہے جو اپنی ماں کے پیٹ میں (تھا تو اللہ کے علم کے مطابق) بدبخت تھا اور سعادت مند وہ ہے جو اپنے علاوہ دوسرے سے نصیحت حاصل کرے، پھر رسول اللہ صلی اللہ علیہ وسلم کے صحابہ میں سے ایک شخص آئے جنہیں حضرت حذیفہ بن اسید غفاری رضی اللہ عنہ کہا جاتا تھا، انہوں (عامر بن واثلہ رضی اللہ عنہ) نے ان کو حضرت ابن مسعود رضی اللہ عنہ کے الفاظ میں یہ حدیث سنائی اور (ان سے پوچھنے کے لیے) کہا: وہ شخص کوئی عمل کیے بغیر بدبخت کیسے ہو جاتا ہے؟ تو اس (عامر) کو آدمی (حذیفہ رضی اللہ عنہ) نے کہا: کیا آپ اس پر تعجب کرتے ہیں؟ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا ہے: \"جب نطفے پر (تیسرے مرحلے کی) بیالیس راتیں گذر جاتی ہیں تو اللہ تعالیٰ اس کے پاس ایک فرشتہ بھیجتا ہے، وہ اس کی صورت بناتا ہے، اس کے کان، آنکھیں، کھال، گوشت اور اس کی ہڈیاں بناتا ہے، پھر کہتا ہے: اے میرے رب! یہ مرد ہو گا کہ عورت؟ پھر تمہارا رب جو چاہتا ہوتا ہے وہ فیصلہ بتاتا ہے اور فرشتہ لکھ لیتا ہے، پھر وہ کہتا ہے: اے میرے رب! اس کی مدت حیات (کتنی ہو گی؟) پھر تمہارا رب جو اس کی مچیت ہوتی ہے، بتاتا ہے اور فرشتہ لکھ لیتا ہے، پھر وہ (فرشتہ) کہتا ہے: اے میرے رب! اس کا رزق (کتنا ہو گا؟) تو تمہارا رب جو چاہتا ہوتا ہے وہ فیصلہ بتاتا ہے اور فرشتہ لکھ لیتا ہے، پھر فرشتہ اپنے ہاتھ میں صحیفہ لے کر نکل جاتا ہے، چنانچہ وہ شخص کسی معاملے میں نہ اس سے بڑھتا ہے، نہ کم ہوتا ہے۔\""}],[6776,"ابن جریج نے کہا : مجھے ابوزبیر نے خبر دی کہ ابوطفیل رضی اللہ عنہ نے انہیں بتایا کہ انہوں نے سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے اور عمرو بن حارث کی حدیث کی طرح حدیث بیان کی ۔","",{"u2":"ابن جریج نے کہا: مجھے ابوزبیر نے خبر دی کہ ابوطفیل رضی اللہ عنہ نے انہیں بتایا کہ انہوں نے حضرت عبداللہ بن مسعود رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے اور عمرو بن حارث کی حدیث کی طرح حدیث بیان کی۔"}],[6777,"یحیی بن ابوبکیر نے کہا : ہمیں ابوخیثمہ زہیر نے حدیث بیان کی ، انہوں نے کہا : مجھے عبداللہ بن عطاء نے حدیث بیان کی ، انہیں عکرمہ بن خالد نے حدیث بیان کی ، انہیں ابوطفیل رضی اللہ عنہ نے حدیث بیان کی ، کہا : میں ابو سریحہ حذیفہ بن اسید غفاری رضی اللہ عنہ کے پاس حاضر ہوا تو انہوں نے کہا : میں نے اپنے ان دونوں کانوں سے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا ہے : \" نطفہ ( اصل میں تین مرحلوں میں چالیس ) چالیس راتیں رحم مادر میں رہتا ہے ، پھر فرشتہ اس کی صورت بناتا ہے ۔ \" زہیر نے کہا : میرا گمان ہے کہ انہوں نے کہا : ( فرشتہ ) اسے بتایا ہے : \" تو وہ کہتا ہے : اے میرے رب! عورت ہو گی یا مرد ہو گا؟ پھر اللہ تعالی اس کے مذکر یا مؤنث ہونے کا فیصلہ بتا دیتا ہے ، وہ ( فرشتہ ) پھر کہتا ہے : اے میرے رب! مکمل ( پورے اعضاء والا ہے ) یا غیر مکمل؟ پھر اللہ تعالی مکمل یا غیر مکمل ہونے کے بارے میں اپنا فیصلہ بتا دیتا ہے ، پھر وہ کہتا ہے : اے میرے پروردگار! اس کا رزق کتنا ہو گا؟ اس کی مدت حیات کتنی ہو گی؟ اس کا اخلاق کیسا ہو گا؟ پھر اللہ تعالی اس کے بدبخت یا خوش بخت ہونے کے بارے میں بھی ( جو طے ہو چکا ) بتا دیتا ہے ۔","",{"u2":"یحییٰ بن ابوبکیر نے کہا: ہمیں ابوخیثمہ زہیر نے حدیث بیان کی، انہوں نے کہا: مجھے عبداللہ بن عطاء نے حدیث بیان کی، انہیں عکرمہ بن خالد نے حدیث بیان کی، انہیں ابوطفیل رضی اللہ عنہ نے حدیث بیان کی، کہا: میں ابو سریحہ حذیفہ بن اسید غفاری رضی اللہ عنہ کے پاس حاضر ہوا تو انہوں نے کہا: میں نے اپنے ان دونوں کانوں سے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا ہے: \"نطفہ (اصل میں تین مرحلوں میں چالیس) چالیس راتیں رحم مادر میں رہتا ہے، پھر فرشتہ اس کی صورت بناتا ہے۔\" زہیر نے کہا: میرا گمان ہے کہ انہوں نے کہا: (فرشتہ) اسے بتایا ہے: \"تو وہ کہتا ہے: اے میرے رب! عورت ہو گی یا مرد ہو گا؟ پھر اللہ تعالیٰ اس کے مذکر یا مؤنث ہونے کا فیصلہ بتا دیتا ہے، وہ (فرشتہ) پھر کہتا ہے: اے میرے رب! مکمل (پورے اعضاء والا ہے) یا غیر مکمل؟ پھر اللہ تعالیٰ مکمل یا غیر مکمل ہونے کے بارے میں اپنا فیصلہ بتا دیتا ہے، پھر وہ کہتا ہے: اے میرے پروردگار! اس کا رزق کتنا ہو گا؟ اس کی مدت حیات کتنی ہو گی؟ اس کا اخلاق کیسا ہو گا؟ پھر اللہ تعالیٰ اس کے بدبخت یا خوش بخت ہونے کے بارے میں بھی (جو طے ہو چکا) بتا دیتا ہے۔\""}],[6778,"کلثوم نے ابوطفیل رضی اللہ عنہ سے ، انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے صحابی سیدنا حذیفہ بن اسید غفاری رضی اللہ عنہ سے روایت کی ، انہوں نے یہ حدیث رسول اللہ صلی اللہ علیہ وسلم سے مرفوعا روایت کی : \" تخلیق کے دوران میں رحم پر ایک فرشتہ مقرر ہوتا ہے ، جب اللہ تعالی اپنے اذن سے کوئی چیز پیدا کرنا چاہتا ہے تو چالیس اور کچھ اوپر راتیں گزارنے کے بعد \" پھر ان سب کی روایت کردہ حدیث کے مطابق بیان کیا ۔","",{"u2":"کلثوم نے ابوطفیل رضی اللہ عنہ سے، انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے صحابی حضرت حذیفہ بن اسید غفاری رضی اللہ عنہ سے روایت کی، انہوں نے یہ حدیث رسول اللہ صلی اللہ علیہ وسلم سے مرفوعا روایت کی: \"تخلیق کے دوران میں رحم پر ایک فرشتہ مقرر ہوتا ہے، جب اللہ تعالیٰ اپنے اذن سے کوئی چیز پیدا کرنا چاہتا ہے تو چالیس اور کچھ اوپر راتیں گزارنے کے بعد\" پھر ان سب کی روایت کردہ حدیث کے مطابق بیان کیا۔"}],[6779,"عبیداللہ بن ابی بکر نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی ، انہوں نے یہ حدیث مرفوعا بیان کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ عزوجل رحم پر ایک فرشتہ مقرر کر دیتا ہے ، وہ کہتا ہے : اے میرے رب! ( اب ) یہ نطفہ ہے ، اے میرے رب! ( اب ) یہ عقلہ ہے ، اے میرے رب! ( اب یہ مضغہ ہے ، پھر جب اللہ تعالی اس کی ( انسان کی صورت میں ) تخلیق کا فیصلہ کرتا ہے تو انہوں نے کہا : فرشتہ کہتا ہے : اے میرے رب! مرد ہو یا عورت؟ بدبخت ہو یا خوش نصیب؟ رزق کتنا ہو گا؟ مدت عمر کتنی ہو گی؟ وہ ماں کے پیٹ میں ہوتا ہے اور اسی طرح ( سب کچھ ) لکھ لیا جاتا ہے ۔","",{"u2":"عبیداللہ بن ابی بکر نے حضرت انس بن مالک رضی اللہ عنہ سے روایت کی، انہوں نے یہ حدیث مرفوعا بیان کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ عزوجل رحم پر ایک فرشتہ مقرر کر دیتا ہے، وہ کہتا ہے: اے میرے رب! (اب) یہ نطفہ ہے، اے میرے رب! (اب) یہ عقلہ ہے، اے میرے رب! (اب یہ مضغہ ہے،پھر جب اللہ تعالیٰ اس کی (انسان کی صورت میں) تخلیق کا فیصلہ کرتا ہے تو انہوں نے کہا: فرشتہ کہتا ہے: اے میرے رب! مرد ہو یا عورت؟ بدبخت ہو یا خوش نصیب؟ رزق کتنا ہو گا؟ مدت عمر کتنی ہو گی؟ وہ ماں کے پیٹ میں ہوتا ہے اور اسی طرح (سب کچھ) لکھ لیا جاتا ہے۔\""}],[6780,"جریر نے ہمیں منصور سے حدیث بیان کی ۔ انہون نے سعید بن عبیدہ سے ، انہوں نے ابوعبدالرحمٰن سے اور انہوں نے سیدنا علی رضی اللہ عنہ سے روایت کی ، کہا : ہم ایک جنازے کے ساتھ بقیع غرقد میں تھے کہ رسول اللہ صلی اللہ علیہ وسلم تشریف لائے اور بیٹھ گئے ، ہم آپ صلی اللہ علیہ وسلم کے اردگرد بیٹھ گئے ۔ آپ نے اپنا سر مبارک جھکا لیا اور اپنی چھڑی سے زمین کریدنے لگے ( جس طرح کہ فکر مندی کے عالم میں ہوں ۔ ) پھر فرمایا : \" تم میں سے کوئی ایک بھی نہیں ، کوئی سانس لینے والا جاندار شخص نہیں ، مگر اللہ تعالی نے ( اپنے ازلی ابدی حتمی علم کے مطابق ) جنت یا جہنم میں اس کا ٹھکانا لکھ دیا ہے اور ( کوئی نہیں ) مگر ( یہ بھی ) لکھ دیا گیا ہے کہ وہ بدبخت ہے یا خوش بخت ۔ \" کہا : تو کسی آدمی نے کہا : اللہ کے رسول! کیا ہم اپنے لکھے پر ہی نہ رہ جائیں اور عمل چھوڑ دیں؟ تو آپ نے فرمایا : \" جو خوش بختوں میں سے ہو گا تو وہ خوش بختوں کے عمل کی طرف چل پڑے گا ۔ \" پھر آپ صلی اللہ علیہ وسلم نے ارشاد فرمایا : \" عمل کرو ، ہر ایک کا راستہ آسان کر دیا گیا ہے ۔ جو خوش بخت ہیں ان کے لیے خوش بختوں کے اعمال کا راستہ آسان کر دیا جاتا ہے اور جو بدبخت ہیں ان کے لیے بدبختوں کے عملوں کا راستہ آسان کر دیا جاتا ہے ۔ \" پھر آپ صلی اللہ علیہ وسلم نے تلاوت کیا : \" پس وہ شخص جس نے ( اللہ کی راہ میں ) دیا اور تقوی اختیار کیا اور اچھی بات کی تصدیق کر دی تو ہم اسے آسانی کی زندگی ( تک پہنچنے ) کے لیے سہولت عطا کریں گے اور وہ جس نے بخل کیا اور بے پروائی اختیار کی اور اچھی بات کی تکذیب کی تو ہم اسے مشکل زندگی ( تک جانے ) کے لیے سہولت دیں گے ۔","",{"u2":") جریر نے ہمیں منصور سے حدیث بیان کی۔ انہون نے سعید بن عبیدہ سے، انہوں نے ابوعبدالرحمٰن سے اور انہوں نے حضرت علی رضی اللہ عنہ سے روایت کی، کہا: ہم ایک جنازے کے ساتھ بقیع غرقد میں تھے کہ رسول اللہ صلی اللہ علیہ وسلم تشریف لائے اور بیٹھ گئے، ہم آپ صلی اللہ علیہ وسلم کے اردگرد بیٹھ گئے۔ آپ نے اپنا سر مبارک جھکا لیا اور اپنی چھڑی سے زمین کریدنے لگے (جس طرح کہ فکر مندی کے عالم میں ہوں۔) پھر فرمایا: \"تم میں سے کوئی ایک بھی نہیں، کوئی سانس لینے والا جاندار شخص نہیں، مگر اللہ تعالیٰ نے (اپنے ازلی ابدی حتمی علم کے مطابق) جنت یا جہنم میں اس کا ٹھکانا لکھ دیا ہے اور (کوئی نہیں) مگر (یہ بھی) لکھ دیا گیا ہے کہ وہ بدبخت ہے یا خوش بخت۔\" کہا: تو کسی آدمی نے کہا: اللہ کے رسول! کیا ہم اپنے لکھے پر ہی نہ رہ جائیں اور عمل چھوڑ دیں؟ تو آپ نے فرمایا: \"جو خوش بختوں میں سے ہو گا تو وہ خوش بختوں کے عمل کی طرف چل پڑے گا۔\" پھر آپ صلی اللہ علیہ وسلم نے ارشاد فرمایا: \"عمل کرو، ہر ایک کا راستہ آسان کر دیا گیا ہے۔ جو خوش بخت ہیں ان کے لیے خوش بختوں کے اعمال کا راستہ آسان کر دیا جاتا ہے اور جو بدبخت ہیں ان کے لیے بدبختوں کے عملوں کا راستہ آسان کر دیا جاتا ہے۔\" پھر آپ صلی اللہ علیہ وسلم نے تلاوت کیا: \"پس وہ شخص جس نے (اللہ کی راہ میں) دیا اور تقویٰ اختیار کیا اور اچھی بات کی تصدیق کر دی تو ہم اسے آسانی کی زندگی (تک پہنچنے) کے لیے سہولت عطا کریں گے اور وہ جس نے بخل کیا اور بے پروائی اختیار کی اور اچھی بات کی تکذیب کی تو ہم اسے مشکل زندگی (تک جانے) کے لیے سہولت دیں گے۔\""}],[6781,"ابوبکر بن ابی شیبہ اور ہناد بن سری نے ہمیں حدیث بیان کی ، انہوں نے کہا : ہمیں ابو احوص نے منصور سے اسی سند کے ساتھ اسی کے ہم معنی حدیث بیان کی اور کہا : آپ صلی اللہ علیہ وسلم نے ایک لکڑی پکڑی اور چھڑی نہیں کہا ۔ اور ابن ابی شیبہ نے ابو احوص سے بیان کردہ اپنی حدیث میں ( \" آپ صلی اللہ علیہ وسلم نے \" کی جگہ ) کہا : پھر رسول اللہ صلی اللہ علیہ وسلم نے تلاوت کیا ۔","",{"u2":"ابوبکر بن ابی شیبہ اور ہناد بن سری نے ہمیں حدیث بیان کی، انہوں نے کہا: ہمیں ابو احوص نے منصور سے اسی سند کے ساتھ اسی کے ہم معنی حدیث بیان کی اور کہا: آپ صلی اللہ علیہ وسلم نے ایک لکڑی پکڑی اور چھڑی نہیں کہا۔ اور ابن ابی شیبہ نے ابو احوص سے بیان کردہ اپنی حدیث میں (\"آپ صلی اللہ علیہ وسلم نے\" کی جگہ) کہا: پھر رسول اللہ صلی اللہ علیہ وسلم نے تلاوت کیا۔"}],[6782,"وکیع ، عبداللہ بن نمیر اور ابومعاویہ نے کہا : ہمیں اعمش نے سعد بن عبیدہ سے حدیث بیان کی ، انہوں نے ابوعبدالرحمٰن سلمی سے اور انہوں نے سیدنا علی رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم ایک دن بیٹھے ہوئے تھے ، اور آپ کے ہاتھ میں ایک چھڑی تھی جس سے آپ زمین کرید رہے تھے ، پھر آپ نے اپنا سر اقدس اٹھا کر فرمایا : \" تم میں سے کوئی ذی روح نہیں مگر جنت اور دوزخ میں اس کا مقام ( پہلے سے ) معلوم ہے ۔ \" انہوں ( صحابہ ) نے عرض کی : اللہ کے رسول! پھر ہم کس لیے عمل کریں؟ ہم اسی ( لکھے ہوئے ) پر تکیہ نہ کریں؟ آپ نے فرمایا : \" نہیں ، تم عمل کرو ، ہر شخص کے لیے اسی کی سہولت میسر ہے جس ( کو خود اپنے عمل کے ذریعے حاصل کرنے ) کے لیے اس کو پیدا کیا گیا ۔ \" پھر آپ صلی اللہ علیہ وسلم نے : \" تو وہ شخص جس نے ( اللہ کی راہ میں ) دیا اور اچھی بات کی تصدیق کی \" سے لے کر \" تو ہم اسے مشکل زندگی ( تک جانے ) کے لیے سہولت دیں گے \" تک پڑھا ۔","",{"u2":"وکیع، عبداللہ بن نمیر اور ابومعاویہ نے کہا: ہمیں اعمش نے سعد بن عبیدہ سے حدیث بیان کی، انہوں نے ابوعبدالرحمٰن سلمی سے اور انہوں نے حضرت علی رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم ایک دن بیٹھے ہوئے تھے، اور آپ کے ہاتھ میں ایک چھڑی تھی جس سے آپ زمین کرید رہے تھے، پھر آپ نے اپنا سر اقدس اٹھا کر فرمایا: \"تم میں سے کوئی ذی روح نہیں مگر جنت اور دوزخ میں اس کا مقام (پہلے سے) معلوم ہے۔\" انہوں (صحابہ) نے عرض کی: اللہ کے رسول! پھر ہم کس لیے عمل کریں؟ ہم اسی (لکھے ہوئے) پر تکیہ نہ کریں؟ آپ نے فرمایا: \"نہیں، تم عمل کرو، ہر شخص کے لیے اسی کی سہولت میسر ہے جس (کو خود اپنے عمل کے ذریعے حاصل کرنے) کے لیے اس کو پیدا کیا گیا۔\" پھر آپ صلی اللہ علیہ وسلم نے: \"تو وہ شخص جس نے (اللہ کی راہ میں) دیا اور اچھی بات کی تصدیق کی\" سے لے کر \"تو ہم اسے مشکل زندگی (تک جانے) کے لیے سہولت دیں گے\" تک پڑھا۔"}],[6783,"ہمیں شعبہ نے منصور اور اعمش سے حدیث بیان کی ، ان دونوں نے سعد بن عبیدہ سے سنا ، وہ ابوعبدالرحمٰن سلمی سے ، وہ سیدنا علی رضی اللہ عنہ سے اور وہ نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کر رہے تھے ۔","",{"u2":"ہمیں شعبہ نے منصور اور اعمش سے حدیث بیان کی، ان دونوں نے سعد بن عبیدہ سے سنا، وہ ابوعبدالرحمٰن سلمی سے، وہ حضرت علی رضی اللہ عنہ سے اور وہ نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کر رہے تھے۔"}],[6784,"ابوخیثمہ زہیر ( بن حرب ) نے ابوزبیر سے ، انہوں نے سیدنا جابر رضی اللہ عنہ سے روایت کی ، کہا : سیدنا سراقہ بن مالک بن جعشم رضی اللہ عنہ آئے اور عرض کی : اللہ کے رسول! آپ ہمارے لیے دین کو اس طرح بیان کیجئے ، گویا ہم ابھی پیدا کیے گئے ہیں ، آج کا عمل ( جو ہم کر رہے ہیں ) کس نوع میں آتا ہے؟ کیا اس میں جسے ( لکھنے والی ) قلمیں ( لکھ کر ) خشک ہو چکیں اور جو پیمارنے مقرر کیے گئے ہیں ان کا سلسلہ جاری ہو چکا ہے ( ہم بس انہی کے مطابق عمل کیے جا رہے ہیں؟ ) یا اس میں جو ہم از سر نو کر رہے ہیں ( پہلے سے ان کے بارے میں کچھ طے نہیں؟ ) آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" نہیں ، بلکہ جسے لکھنے والی قلمیں ( لکھ کر ) خشک ہو چکیں اور جن کے مقرر شدہ پیمانوں کے مطابق عمل شروع ہو چکا ۔ \"\" انہوں نے کہا : تو پھر عمل کس لیے ( کیا جائے؟ ) زہیر نے کہا : پھر اس کے بعد ابوزبیر نے کوئی بات کی جو میں نہیں سمجھ سکا ، تو میں نے پوچھا : آپ صلی اللہ علیہ وسلم نے کیا فرمایا؟ انہوں نے کہا : ( آپ نے فرمایا : ) \"\" تم عمل کرو ، ہر ایک کو سہولت میسر کی گئی ہے ۔","",{"u2":"ابوخیثمہ زہیر (بن حرب) نے ابوزبیر سے، انہوں نے حضرت جابر رضی اللہ عنہ سے روایت کی، کہا: حضرت سراقہ بن مالک بن جعشم رضی اللہ عنہ آئے اور عرض کی: اللہ کے رسول! آپ ہمارے لیے دین کو اس طرح بیان کیجئے، گویا ہم ابھی پیدا کیے گئے ہیں، آج کا عمل (جو ہم کر رہے ہیں) کس نوع میں آتا ہے؟ کیا اس میں جسے (لکھنے والی) قلمیں (لکھ کر) خشک ہو چکیں اور جو پیمارنے مقرر کیے گئے ہیں ان کا سلسلہ جاری ہو چکا ہے (ہم بس انہی کے مطابق عمل کیے جا رہے ہیں؟) یا اس میں جو ہم از سر نو کر رہے ہیں (پہلے سے ان کے بارے میں کچھ طے نہیں؟) آپ صلی اللہ علیہ وسلم نے فرمایا: \"نہیں، بلکہ جسے لکھنے والی قلمیں (لکھ کر) خشک ہو چکیں اور جن کے مقرر شدہ پیمانوں کے مطابق عمل شروع ہو چکا۔\" انہوں نے کہا: تو پھر عمل کس لیے (کیا جائے؟)\nزہیر نے کہا: پھر اس کے بعد ابوزبیر نے کوئی بات کی جو میں نہیں سمجھ سکا، تو میں نے پوچھا: آپ صلی اللہ علیہ وسلم نے کیا فرمایا؟ انہوں نے کہا: (آپ نے فرمایا:) \"تم عمل کرو، ہر ایک کو سہولت میسر کی گئی ہے۔\""}],[6785,"عمرو بن حارث نے ابوزبیر سے ، انہوں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی معنی میں روایت کی اور اس میں یہ الفاظ ہیں : تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ہر عمل کرنے والا اپنے عمل کے لیے آسانی پاتا ہے ۔","",{"u2":"عمرو بن حارث نے ابوزبیر سے، انہوں نے حضرت جابر بن عبداللہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی معنی میں روایت کی اور اس میں یہ الفاظ ہیں: تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہر عمل کرنے والا اپنے عمل کے لیے آسانی پاتا ہے۔\""}],[6786,"حماد بن زید نے یزید ضبعی سے روایت کی ، کہا : ہمیں مطرف نے سیدنا عمران بن حصین رضی اللہ عنہ سے حدیث بیان کی ، کہا : آپ صلی اللہ علیہ وسلم سے عرض کی گئی : اللہ کے رسول! کیا یہ معلوم ہے کہ جہنم والوں سے ( الگ ) جنت والے کون ہیں؟ کہا : آپ صلی اللہ علیہ وسلم نے فرمایا : \" ہاں ۔ \" کہا : عرض کی گئی : تو پھر عمل کرنے والے کس لیے عمل کریں؟ آپ نے فرمایا : \" ہر ایک کو اسی ( منزل کی طرف جانے ) کی سہولت میسر کر دی جاتی ہے جس ( تک اپنے اعمال کے ذریعے پہنچنے ) کے لیے اسے پیدا کیا گیا تھا ۔","",{"u2":"حماد بن زید نے یزید ضبعی سے روایت کی، کہا: ہمیں مطرف نے حضرت عمران بن حصین رضی اللہ عنہ سے حدیث بیان کی، کہا: آپ صلی اللہ علیہ وسلم سے عرض کی گئی: اللہ کے رسول! کیا یہ معلوم ہے کہ جہنم والوں سے (الگ) جنت والے کون ہیں؟ کہا: آپ صلی اللہ علیہ وسلم نے فرمایا: \"ہاں۔\" کہا: عرض کی گئی: تو پھر عمل کرنے والے کس لیے عمل کریں؟ آپ نے فرمایا: \"ہر ایک کو اسی (منزل کی طرف جانے) کی سہولت میسر کر دی جاتی ہے جس (تک اپنے اعمال کے ذریعے پہنچنے) کے لیے اسے پیدا کیا گیا تھا۔\""}],[6787,"عبدالوارث ، ابن علیہ ، جعفر بن سلیمان اور شعبہ سب نے یزید رشک سے اسی سند کے ساتھ حماد کی حدیث کے ہم معنی روایت کی اور عبدالوارث کی حدیث میں ( عرض کی گئی کے بجائے ) اس طرح ہے : ( عمران بن حصین رضی اللہ عنہ نے ) کہا : میں نے عرض کی : اللہ کے رسول","",{"u2":"عبدالوارث، ابن علیہ، جعفر بن سلیمان اور شعبہ سب نے یزید رشک سے اسی سند کے ساتھ حماد کی حدیث کے ہم معنی روایت کی اور عبدالوارث کی حدیث میں (عرض کی گئی کے بجائے) اس طرح ہے: (عمران بن حصین رضی اللہ عنہ نے) کہا: میں نے عرض کی: اللہ کے رسول!"}],[6788,"یحیی بن یعمر نے ابو اسود دیلی سے روایت کی ، کہا : سیدنا عمران بن حصین رضی اللہ عنہ نے مجھ سے کہا : تمہارا کیا خیال ہے کہ جو عمل لوگ آج کر رہے ہیں اور اس میں مشقت اٹھا رہے ہیں ، کیا یہ ایسی چیز ہے جس کا ان کے بارے میں فیصلہ ہو چکا اور پہلے ہی سے مقدر ہے جو ان میں جاری ہو چکا ہے یا وہ نئے سرے سے ان کے سامنے پیش کی جا رہی ہے ، جس طرح اسے ان کے نبی صلی اللہ علیہ وسلم ان کے پاس لائے ہیں اور ان پر حجت قائم ہوئی ہے؟ میں نے جواب دیا : بلکہ جس طرح ان کے بارے میں فیصلہ ہو چکا ہے اور اس کا سلسلہ ان میں جاری ہے ۔ ( دیلی نے ) کہا : تو ( عمران بن حصین رضی اللہ عنہ نے ) کہا : تو کیا یہ ظلم نہیں؟ ( دیلی نے ) کہا : تو اس بات پر میں سخت خوفزدہ اور پریشان ہو کیا اور میں نے کہا : ہر چیز اللہ کی پیدا کی ہوئی ہے اور اس کی ملکیت ہے ۔ جو بھی وہ کرے اس سے پوچھا نہیں جا سکتا اور وہ ( اس کے مملوک بندے ) جو کریں ان سے پوچھا جا سکتا ہے ۔ تو انہوں نے مجھ سے کہا : اللہ تم پر رحم کرے! میں نے جو تم سے پوچھا صرف اسی لیے پوچھا تھا تاکہ تمہاری عقل کا امتحان لوں ۔ مزینہ کے دو آدمی رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور عرض کی : اللہ کے رسول! آپ کس طرح دیکھتے ہیں ، لوگ جو عمل آج کر رہے اور اس میں مشقت اٹھا رہے ہیں کوئی ایسی چیز ہے جا کا ان کے بارے میں فیصلہ ہو چکا اور پہلے سے مقدر ہے جو ان میں جاری ہو چکی ہے یا وہ اب ان کے سامنے پیش کی جا رہی ہے ، جس طرح اسے ان کے رسول ان کے پاس لائے ہیں اور ان پر حجت تمام ہوئی ہے؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا : \" نہیں ، بلکہ بلکہ ایسی چیز ہے جو ان کے بارے میں طے ہو گئی ہے اور ان میں جاری ہو چکی ، اور اس کی تصدیق اللہ عزوجل کی کتاب میں ہے : \" اور نفس انسانی اور اس ذات کی قسم جس نے اس کو ٹھیک بنایا! پھر اس کو اس کی بدی بھی الہام کر دی اور نیکی بھی ۔","",{"u2":"یحییٰ بن یعمر نے ابو اسود دیلی سے روایت کی، کہا: حضرت عمران بن حصین رضی اللہ عنہ نے مجھ سے کہا: تمہارا کیا خیال ہے کہ جو عمل لوگ آج کر رہے ہیں اور اس میں مشقت اٹھا رہے ہیں، کیا یہ ایسی چیز ہے جس کا ان کے بارے میں فیصلہ ہو چکا اور پہلے ہی سے مقدر ہے جو ان میں جاری ہو چکا ہے یا وہ نئے سرے سے ان کے سامنے پیش کی جا رہی ہے، جس طرح اسے ان کے نبی صلی اللہ علیہ وسلم ان کے پاس لائے ہیں اور ان پر حجت قائم ہوئی ہے؟ میں نے جواب دیا: بلکہ جس طرح ان کے بارے میں فیصلہ ہو چکا ہے اور اس کا سلسلہ ان میں جاری ہے۔ (دیلی نے) کہا: تو (عمران بن حصین رضی اللہ عنہ نے) کہا: تو کیا یہ ظلم نہیں؟ (دیلی نے) کہا: تو اس بات پر میں سخت خوفزدہ اور پریشان ہو کیا اور میں نے کہا: ہر چیز اللہ کی پیدا کی ہوئی ہے اور اس کی ملکیت ہے۔ جو بھی وہ کرے اس سے پوچھا نہیں جا سکتا اور وہ (اس کے مملوک بندے) جو کریں ان سے پوچھا جا سکتا ہے۔ تو انہوں نے مجھ سے کہا: اللہ تم پر رحم کرے! میں نے جو تم سے پوچھا صرف اسی لیے پوچھا تھا تاکہ تمہاری عقل کا امتحان لوں۔ مزینہ کے دو آدمی رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور عرض کی: اللہ کے رسول! آپ کس طرح دیکھتے ہیں، لوگ جو عمل آج کر رہے اور اس میں مشقت اٹھا رہے ہیں کوئی ایسی چیز ہے جا کا ان کے بارے میں فیصلہ ہو چکا اور پہلے سے مقدر ہے جو ان میں جاری ہو چکی ہے یا وہ اب ان کے سامنے پیش کی جا رہی ہے، جس طرح اسے ان کے رسول ان کے پاس لائے ہیں اور ان پر حجت تمام ہوئی ہے؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"نہیں، بلکہ بلکہ ایسی چیز ہے جو ان کے بارے میں طے ہو گئی ہے اور ان میں جاری ہو چکی، اور اس کی تصدیق اللہ عزوجل کی کتاب میں ہے: \"اور نفس انسانی اور اس ذات کی قسم جس نے اس کو ٹھیک بنایا! پھر اس کو اس کی بدی بھی الہام کر دی اور نیکی بھی۔\""}],[6789,"علاء کے والد ( عبدالرحمٰن ) نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" بلاشبہ انسان ایک لمبی مدت تک اہل جنت کے سے عمل کرتا رہتا ہے ، پھر اس کے لیے اس کے عمل کا خاتمہ اہل جہنم کے سے عمل پر ہوتا ہے اور بلاشبہ ایک آدمی لمبا زمانہ اہل جہنم کے سے عمل کرتا رہتا ہے ، پھر اس کے لیے اس کے عمل کا خاتمہ اہل جنت کے سے عمل پر ہوتا ہے ۔","",{"u2":"علاء کے والد (عبدالرحمٰن) نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بلاشبہ انسان ایک لمبی مدت تک اہل جنت کے سے عمل کرتا رہتا ہے، پھر اس کے لیے اس کے عمل کا خاتمہ اہل جہنم کے سے عمل پر ہوتا ہے اور بلاشبہ ایک آدمی لمبا زمانہ اہل جہنم کے سے عمل کرتا رہتا ہے، پھر اس کے لیے اس کے عمل کا خاتمہ اہل جنت کے سے عمل پر ہوتا ہے۔\""}],[6790,"سیدنا سہل بن سعد ساعدی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ایک شخص ، جس طرح وہ لوگوں کو نظر آ رہا ہوتا ہے ، اہل جنت کے سے عمل کر رہا ہوتا ہے ، لیکن ( آخر کار ) وہ اہل جہنم میں سے ہوتا ہے اور ایک آدمی ، جس طرح سے وہ لوگوں کو نظر آ رہا ہوتا ہے اہل جہنم کے سے عمل کر رہا ہوتا ہے لیکن ( انجام کار ) وہ اہل جنت میں سے ہوتا ہے ۔","",{"u2":"حضرت سہل بن سعد ساعدی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک شخص، جس طرح وہ لوگوں کو نظر آ رہا ہوتا ہے، اہل جنت کے سے عمل کر رہا ہوتا ہے، لیکن (آخر کار) وہ اہل جہنم میں سے ہوتا ہے اور ایک آدمی، جس طرح سے وہ لوگوں کو نظر آ رہا ہوتا ہے اہل جہنم کے سے عمل کر رہا ہوتا ہے لیکن (انجام کار) وہ اہل جنت میں سے ہوتا ہے۔\""}],[6791,"محمد بن حاتم ، ابراہیم بن دینار ، ابن ابی عمر مکی اور احمد بن عبدہ ضبی نے ہمیں ابن عیینہ سے حدیث بیان کی ، الفاظ ابن حاتم اور ابن دینار کے ہیں ۔ ۔ ان دونوں نے کہا : ہمیں سفیان بن عمرو ( بن دینار ) سے حدیث بیان کی ، انہوں نے طاوس سے روایت کی ، انہوں نے کہا : میں نے سیدنا ابوہریرہ رضی اللہ عنہ کو کہتے ہوئے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" حضرت آدم اور حضرت موسی علیہم السلام نے ( ایک دوسرے کو ) اپنی اپنی دلیلیں دیں ۔ حضرت موسی علیہ السلام نے کہا : آدم! آپ ہمارے والد ہیں ، آپ نے ہمیں ناکام کر دیا اور ہمیں جنت سے باہر نکال لائے ۔ حضرت آدم علیہ السلام نے فرمایا : تم موسی ہو ، تمہیں اللہ تعالی نے اپنی ہم کلامی کے لیے منتخب فرمایا اور اپنے ہاتھ سے تمہارے لیے ( اپنے احکام کو ) لکھا ، کیا تم مجھے اس بات پر ملامت کر رہے ہو جسے اللہ تعالی نے میرے بارے میں مجھے پیدا کرنے سے بھی چالیس سال پہلے مقدر کر دیا تھا؟ \"\" نبی صلی اللہ علیہ وسلم نے فرمایا : تو حضرت آدم علیہ السلام ( دلیل میں ) حضرت موسی علیہ السلام پر غالب آ گئے ، حضرت آدم علیہ السلام حضرت موسی علیہ السلام پر غالب آ گئے ۔ \"\" ابن ابی عمر اور ابن عبدہ کی حدیث میں ہے کہ ایک نے کہا : \"\" لکھا \"\" اور دوسرے نے کہا : \"\" تمہارے لیے اپنے ہاتھ سے تورات لکھی ۔","",{"u2":"محمد بن حاتم، ابراہیم بن دینار، ابن ابی عمر مکی اور احمد بن عبدہ ضبی نے ہمیں ابن عیینہ سے حدیث بیان کی، الفاظ ابن حاتم اور ابن دینار کے ہیں۔۔ ان دونوں نے کہا: ہمیں سفیان بن عمرو (بن دینار) سے حدیث بیان کی، انہوں نے طاوس سے روایت کی، انہوں نے کہا: میں نے حضرت ابوہریرہ رضی اللہ عنہ کو کہتے ہوئے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"حضرت آدم اور حضرت موسیٰ علیہم السلام نے (ایک دوسرے کو) اپنی اپنی دلیلیں دیں۔ حضرت موسیٰ علیہ السلام نے کہا: آدم! آپ ہمارے والد ہیں، آپ نے ہمیں ناکام کر دیا اور ہمیں جنت سے باہر نکال لائے۔ حضرت آدم علیہ السلام نے فرمایا: تم موسیٰ ہو، تمہیں اللہ تعالیٰ نے اپنی ہم کلامی کے لیے منتخب فرمایا اور اپنے ہاتھ سے تمہارے لیے (اپنے احکام کو) لکھا، کیا تم مجھے اس بات پر ملامت کر رہے ہو جسے اللہ تعالیٰ نے میرے بارے میں مجھے پیدا کرنے سے بھی چالیس سال پہلے مقدر کر دیا تھا؟\" نبی صلی اللہ علیہ وسلم نے فرمایا: تو حضرت آدم علیہ السلام (دلیل میں) حضرت موسیٰ علیہ السلام پر غالب آ گئے، حضرت آدم علیہ السلام حضرت موسیٰ علیہ السلام پر غالب آ گئے۔\"\nابن ابی عمر اور ابن عبدہ کی حدیث میں ہے کہ ایک نے کہا: \"لکھا\" اور دوسرے نے کہا: \"تمہارے لیے اپنے ہاتھ سے تورات لکھی۔\""}],[6792,"ابوزناد نے اعرج سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" حضرت آدم اور حضرت موسی علیہم السلام نے ایک دوسرے کو دلائل دیے اور آدم علیہ السلام نے موسی علیہ السلام کو دلیل دے ہرا دیا ۔ موسی علیہ السلام نے ان سے کہا : آپ وہی آدم ہیں جنہوں نے ( خود غلطی کر کے اپنی اولاد کے ) لوگوں کو غلطیاں کرنے کا راستہ دکھایا اور انہیں جنت سے نکلوا دیا؟ تو آدم علیہ السلام نے فرمایا : تمہی ہو جسے اللہ نے ہر چیز کا علم دیا اور جسے لوگوں میں سے اپنی رسالت کے لیے منتخب فرمایا؟ انہوں نے کہا : ہاں ، ( تو آدم علیہ السلام نے ) فرمایا : تم مجھے اس بات پر ملامت کر رہے ہو جو مجھے پیدا کیے جانے سے بھی پہلے میرے مقدر کر دی گئی تھی؟","",{"u2":"ابوزناد نے اعرج سے، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"حضرت آدم اور حضرت موسیٰ علیہم السلام نے ایک دوسرے کو دلائل دیے اور آدم علیہ السلام نے موسیٰ علیہ السلام کو دلیل دے ہرا دیا۔ موسیٰ علیہ السلام نے ان سے کہا: آپ وہی آدم ہیں جنہوں نے (خود غلطی کر کے اپنی اولاد کے) لوگوں کو غلطیاں کرنے کا راستہ دکھایا اور انہیں جنت سے نکلوا دیا؟ تو آدم علیہ السلام نے فرمایا: تمہی ہو جسے اللہ نے ہر چیز کا علم دیا اور جسے لوگوں میں سے اپنی رسالت کے لیے منتخب فرمایا؟ انہوں نے کہا: ہاں، (تو آدم علیہ السلام نے) فرمایا: تم مجھے اس بات پر ملامت کر رہے ہو جو مجھے پیدا کیے جانے سے بھی پہلے میرے مقدر کر دی گئی تھی؟\""}],[6793,"حارث بن ابی ذباب نے یزید بن ہرمز اور عبدالرحمٰن اعرج سے روایت کی ، ان دونوں نے کہا : ہم نے سیدنا ابوہریرہ رضی اللہ عنہ سے سنا ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" حضرت آدم اور حضرت موسی علیہم السلام نے اپنے رب کے سامنے ایک دوسرے کو دلیلیں دیں اور حضرت آدم علیہ السلام دلیل میں حضرت موسی علیہ السلام پر غالب آ گئے ، حضرت موسی نے کہا : آپ وہ آدم ہیں جن کو اللہ تعالی نے اپنے ہاتھ سے پیدا کیا ، اور آپ میں اپنی روح کو پھونکا اور آپ کو فرشتوں سے سجدہ کرایا اور آپ کو اپنی جنت میں رکھا ، پھر آپ نے اپنی غلطی سے لوگوں کو جنت سے نکلوا کر زمین میں اتروا دیا؟ حضرت آدم علیہ السلام نے فرمایا : تم وہ موسی ہو جسے اللہ تعالی نے اپنی رسالت اور اپنی ہم کلامی کے ذریعے سے فضیلت بخشی اور تمہیں ( تورات کی ) وہ تختیاں عطا کیں جن میں ہر چیز کی وضاحت ہے اور تمہیں سرگوشی کے لیے جانے والا بنا کر اپنا قرب عطا فرمایا ۔ ( تم یہ بتاؤ ) تمہارے علم کے مطابق اللہ نے میری پیدائش سے کتنی مدت پہلے تورات کو ( اس صورت میں ) لکھا ( جس طرح وہ تم پر نازل ہوئی؟ ) موسی علیہ السلام نے کہا : چالیس سال سے ( قبل ۔ ) حضرت آدم علیہ السلام نے کہا : کیا تم نے اس میں یہ ( لکھا ہوا ) پایا : \" آدم نے اپنے پروردگار ( کے حکم ) سے سرتابی کی اور راہ سے ہٹ گیا \" ؟ ( حضرت موسی علیہ السلام نے ) کہا : ہاں ، تو انہوں نے کہا : کیا تم مجھے اس بات پر ملامت کر رہے ہو کہ میں نے وہ کام کیا جو اللہ نے میری پیدائش سے چالیس سال پہلے مجھ پر لکھ دیا تھا کہ میں وہ کام کروں گا؟ \" رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اس طرح آدم علیہ السلام نے دلیل سے موسی علیہ السلام کو لاجواب کر دیا ۔","",{"u2":"حارث بن ابی ذباب نے یزید بن ہرمز اور عبدالرحمٰن اعرج سے روایت کی، ان دونوں نے کہا: ہم نے حضرت ابوہریرہ رضی اللہ عنہ سے سنا، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"حضرت آدم اور حضرت موسیٰ علیہم السلام نے اپنے رب کے سامنے ایک دوسرے کو دلیلیں دیں اور حضرت آدم علیہ السلام دلیل میں حضرت موسیٰ علیہ السلام پر غالب آ گئے، حضرت موسیٰ نے کہا: آپ وہ آدم ہیں جن کو اللہ تعالیٰ نے اپنے ہاتھ سے پیدا کیا، اور آپ میں اپنی روح کو پھونکا اور آپ کو فرشتوں سے سجدہ کرایا اور آپ کو اپنی جنت میں رکھا، پھر آپ نے اپنی غلطی سے لوگوں کو جنت سے نکلوا کر زمین میں اتروا دیا؟ حضرت آدم علیہ السلام نے فرمایا: تم وہ موسیٰ ہو جسے اللہ تعالیٰ نے اپنی رسالت اور اپنی ہم کلامی کے ذریعے سے فضیلت بخشی اور تمہیں (تورات کی) وہ تختیاں عطا کیں جن میں ہر چیز کی وضاحت ہے اور تمہیں سرگوشی کے لیے جانے والا بنا کر اپنا قرب عطا فرمایا۔ (تم یہ بتاؤ) تمہارے علم کے مطابق اللہ نے میری پیدائش سے کتنی مدت پہلے تورات کو (اس صورت میں) لکھا (جس طرح وہ تم پر نازل ہوئی؟) موسیٰ علیہ السلام نے کہا: چالیس سال سے (قبل۔) حضرت آدم علیہ السلام نے کہا: کیا تم نے اس میں یہ (لکھا ہوا) پایا: \"آدم نے اپنے پروردگار (کے حکم) سے سرتابی کی اور راہ سے ہٹ گیا\"؟ (حضرت موسیٰ علیہ السلام نے) کہا: ہاں، تو انہوں نے کہا: کیا تم مجھے اس بات پر ملامت کر رہے ہو کہ میں نے وہ کام کیا جو اللہ نے میری پیدائش سے چالیس سال پہلے مجھ پر لکھ دیا تھا کہ میں وہ کام کروں گا؟\" رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اس طرح آدم علیہ السلام نے دلیل سے موسیٰ علیہ السلام کو لاجواب کر دیا۔\""}],[6794,"حمید بن عبدالرحمٰن نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" حضرت آدم اور حضرت موسی علیہم السلام نے دلائل کا تبادلہ کیا ۔ موسی علیہ السلام نے کہا : آپ آدم ہیں جن کی خطا نے انہیں جنت سے باہر نکالا؟ تو حضرت آدم علیہ السلام نے ان سے کہا : کیا تم موسی ہو جسے اللہ نے اپنی رسالت اور ہم کلامی سے دوسروں پر فضیلت دی ، پھر تم مجھے اس معاملے میں ملامت کر رہے ہو جو میری پیدائش سے پہلے میرے لیے مقدر کر دیا گیا تھا؟ اس طرح آدم علیہ السلام نے موسی علیہ السلام کو دلیل سے خاموش کر دیا ۔","",{"u2":"حمید بن عبدالرحمٰن نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"حضرت آدم اور حضرت موسیٰ علیہم السلام نے دلائل کا تبادلہ کیا۔ موسیٰ علیہ السلام نے کہا: آپ آدم ہیں جن کی خطا نے انہیں جنت سے باہر نکالا؟ تو حضرت آدم علیہ السلام نے ان سے کہا: کیا تم موسیٰ ہو جسے اللہ نے اپنی رسالت اور ہم کلامی سے دوسروں پر فضیلت دی، پھر تم مجھے اس معاملے میں ملامت کر رہے ہو جو میری پیدائش سے پہلے میرے لیے مقدر کر دیا گیا تھا؟ اس طرح آدم علیہ السلام نے موسیٰ علیہ السلام کو دلیل سے خاموش کر دیا۔\""}],[6795,"ابوسلمہ اور ہمام بن منبہ نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے ان ( گزشتہ راویوں ) کی حدیث کے ہم معنی حدیث بیان کی ۔"],[6796,"محمد بن سیرین نے ابوہریرہ رضی اللہ عنہ سے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے ان سب کی حدیث کے مانند حدیث بیان کی ۔","",{"u2":"ابوسلمہ اور ہمام بن منبہ نے حضرت ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے ان (گزشتہ راویوں) کی حدیث کے ہم معنی حدیث بیان کی۔"}],[6797,"ابن وہب نے ہمیں حدیث بیان کی ، کہا : مجھے ابوہانی خولانی نے ابو عبدالرحمٰن حبلی سے خبر دی ، انہوں نے سیدنا عبداللہ بن عمرو بن عاص رضی اللہ عنہ سے روایت کی ، کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا : \" اللہ تعالی نے آسمانوں اور زمین کو پیدا کرنے سے پچاس ہزار سال پہلے مخلوقات کی تقدیریں تحریر فرما دیں تھی ۔ فرمایا : اور اس کا عرش پانی پر تھا ۔","",{"u2":"محمد بن سیرین نے ابوہریرہ رضی اللہ عنہ سے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے ان سب کی حدیث کے مانند حدیث بیان کی۔"}],[6798,"حیوہ اور نافع بن یزید نے ابوہانی سے اسی سند کے ساتھ اسی حدیث کے مانند حدیث بیان کی مگر ان دونوں نے یہ نہیں کہا : \" اور اس کا عرش پانی پر تھا ۔","",{"u2":"ابن وہب نے ہمیں حدیث بیان کی، کہا: مجھے ابوہانی خولانی نے ابو عبدالرحمٰن حبلی سے خبر دی، انہوں نے حضرت عبداللہ بن عمرو بن عاص رضی اللہ عنہ سے روایت کی، کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"اللہ تعالیٰ نے آسمانوں اور زمین کو پیدا کرنے سے پچاس ہزار سال پہلے مخلوقات کی تقدیریں تحریر فرما دیں تھی۔ فرمایا: اور اس کا عرش پانی پر تھا۔\""}],[6799,"حیوہ نے ہمیں حدیث بیان کی ، انہوں نے کہا : مجھے ابوہانی نے بتایا ، انہوں نے ابوعبدالرحمٰن حبلی سے سنا ، انہوں نے سیدنا عبداللہ بن عمرو بن عاص رضی اللہ عنہ کو بیان کرتے ہوئے سنا ، کہا : انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا : \" بنی آدم کے سارے دل ایک دل کی صورت میں اللہ تعالی کی انگلیوں میں سے دو انگلیوں کے درمیان ہیں ، وہ جس طرح چاہتا ہے اسے ( ان سب کو ) گھماتا ہے ۔ \" اس کے بعد رسول اللہ صلی اللہ علیہ وسلم نے ( دعا کرتے ہوئے ) فرمایا : \" اے اللہ! اے دلوں کو پھیرنے والے! ہمارے دلوں کو اپنی اطاعت پر پھیر دے ۔","",{"u2":"حیوہ اور نافع بن یزید نے ابوہانی سے اسی سند کے ساتھ اسی حدیث کے مانند حدیث بیان کی مگر ان دونوں نے یہ نہیں کہا: \"اور اس کا عرش پانی پر تھا۔\""}],[6800,"عمرو بن مسلم نے طاوس سے روایت کی ، انہوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کے متعدد صحابہ کو پایا وہ سب کے سب یہ کہتے تھے کہ ہر چیز ( اللہ کی مقرر کردہ ) مقدار سے ہے اور میں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے سنا ، کہہ رہے تھے : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ہر چیز ( اللہ کی مقرر کردہ ) مقدار سے ہے یہاں تک کہ ( کسی کام کو ) نہ کر سکنا اور کر سکنا بھی ، یا کہا : ( کسی کام کو ) کر سکنا اور نہ کر سکنا ( بھی اسی مقدار سے ہے ۔)","",{"u2":"حیوہ نے ہمیں حدیث بیان کی، انہوں نے کہا: مجھے ابوہانی نے بتایا، انہوں نے ابوعبدالرحمٰن حبلی سے سنا، انہوں نے حضرت عبداللہ بن عمرو بن عاص رضی اللہ عنہ کو بیان کرتے ہوئے سنا، کہا: انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"بنی آدم کے سارے دل ایک دل کی صورت میں اللہ تعالیٰ کی انگلیوں میں سے دو انگلیوں کے درمیان ہیں، وہ جس طرح چاہتا ہے اسے (ان سب کو) گھماتا ہے۔\" اس کے بعد رسول اللہ صلی اللہ علیہ وسلم نے (دعا کرتے ہوئے) فرمایا: \"اے اللہ! اے دلوں کو پھیرنے والے! ہمارے دلوں کو اپنی اطاعت پر پھیر دے۔\""}],[6801,"محمد بن عباد بن جعفر مخزومی نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : مشرکین قریش تقدیر کے بارے میں رسول اللہ صلی اللہ علیہ وسلم سے بحث کرنے کے لیے آئے ، اس وقت ( یہ آیت ) نازل ہوئی : \" جس دن وہ جہنم میں اوندھے منہ گھسیٹے جائیں گے ، ( کہا جائے گا : ) دوزخ کا عذاب چکھو ، بےشک ہم نے ہر چیز کو ( طے شدہ ) مقدار کے مطابق بنایا ہے ۔","",{"u2":"عمرو بن مسلم نے طاوس سے روایت کی، انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کے متعدد صحابہ کو پایا وہ سب کے سب یہ کہتے تھے کہ ہر چیز (اللہ کی مقرر کردہ) مقدار سے ہے اور میں نے حضرت عبداللہ بن عمر رضی اللہ عنہ سے سنا، کہہ رہے تھے: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہر چیز (اللہ کی مقرر کردہ) مقدار سے ہے یہاں تک کہ (کسی کام کو) نہ کر سکنا اور کر سکنا بھی، یا کہا: (کسی کام کو) کر سکنا اور نہ کر سکنا (بھی اسی مقدار سے ہے۔)\""}],[6802,"اسحٰق بن ابراہیم اور عبد بن حمید نے ہمیں حدیث بیان کی ۔ ۔ الفاظ اسحٰق کے ہیں ۔ ۔ دونوں نے کہا : ہمیں عبدالرزاق نے خبر دی ، انہوں نے کہا؛ ہمیں معمر نے ابن طاوس سے حدیث بیان کی ، انہوں نے اپنے والد سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی ، کہا : جو ابوہریرہ رضی اللہ عنہ نے کہا ، میں نے اس سے بڑھ کر ( قرآن کے لفظ ) \"\" اللمم \"\" سے مشابہ کوئی اور چیز نہیں دیکھی ، نبی صلی اللہ علیہ وسلم نے فرمایا : \"\" اللہ تعالی نے ابن آدم پر اس کے حصے کا زنا لکھ دیا ہے ، وہ لامحالہ اپنا حصہ لے گا ۔ آنکھ کا زنا ( جس کا دیکھنا حرام ہے اس کو ) دیکھنا ہے ۔ زبان کا زنا ( حرام بات ) کہنا ہے ، دل تمنا رکھتا ہے ، خواہش کرتا ہے ، پھر شرم گاہ اس کی تصدیق کرتی ہے ( اور وہ زنا کا ارتکاب کر لیتاہے ) یا تکذیب کرنی ہے ( اور وہ اس کا ارتکاب نہیں کرتا ۔ ) \"\" عبد نے اپنی روایت میں کہا : ابن طاوس نے اپنے والد سے روایت کی ( کہا : ) میں نے سیدنا ابن عباس رضی اللہ عنہ سے سنا ، ( اس سند میں سماع کی صراحت ہے ۔)","",{"u2":"محمد بن عباد بن جعفر مخزومی نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: مشرکین قریش تقدیر کے بارے میں رسول اللہ صلی اللہ علیہ وسلم سے بحث کرنے کے لیے آئے، اس وقت (یہ آیت) نازل ہوئی: \"جس دن وہ جہنم میں اوندھے منہ گھسیٹے جائیں گے، (کہا جائے گا:) دوزخ کا عذاب چکھو، بےشک ہم نے ہر چیز کو (طے شدہ) مقدار کے مطابق بنایا ہے۔\""}],[6803,"ابوصالح نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" ابن آدم کے متعلق زنا میں سے اس کا حصہ لکھ دیا گیا ہے ۔ وہ لا محالہ اس کو حاصل کرنے والا ہے ، پس دونوں آنکھیں ، ان کا زنا دیکھنا ہے اور دونوں کان ، ان کا زنا سننا ہے اور زبان ، اس کا زنا بات کرنا ہے اور ہاتھ ، اس کا زنا پکڑنا ہے اور پاؤں ، اس کا زنا چل کر جانا ہے اور دل تمنا رکھتا ہے اور خواہش کرتا ہے اور شرم گاہ ان تمام باتوں کی تصدیق کرتی ہے ( اسے عملا سچ کر دکھاتی ہے اور حرام کا ارتکاب ہو جاتا ہے ) یا اس کی تکذیب کرتی ہے ( حقیقی زنا سے بچاؤ ہو جاتا ہے ۔)","",{"u2":"اسحٰق بن ابراہیم اور عبد بن حمید نے ہمیں حدیث بیان کی۔۔ الفاظ اسحٰق کے ہیں۔۔ دونوں نے کہا: ہمیں عبدالرزاق نے خبر دی، انہوں نے کہا؛ ہمیں معمر نے ابن طاوس سے حدیث بیان کی، انہوں نے اپنے والد سے اور انہوں نے حضرت ابن عباس رضی اللہ عنہ سے روایت کی، کہا: جو ابوہریرہ رضی اللہ عنہ نے کہا، میں نے اس سے بڑھ کر (قرآن کے لفظ) \" اللمم\" سے مشابہ کوئی اور چیز نہیں دیکھی، نبی صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ نے ابن آدم پر اس کے حصے کا زنا لکھ دیا ہے، وہ لامحالہ اپنا حصہ لے گا۔ آنکھ کا زنا (جس کا دیکھنا حرام ہے اس کو) دیکھنا ہے۔ زبان کا زنا (حرام بات) کہنا ہے، دل تمنا رکھتا ہے، خواہش کرتا ہے، پھر شرم گاہ اس کی تصدیق کرتی ہے (اور وہ زنا کا ارتکاب کر لیتاہے) یا تکذیب کرنی ہے (اور وہ اس کا ارتکاب نہیں کرتا۔)\"\nعبد نے اپنی روایت میں کہا: ابن طاوس نے اپنے والد سے روایت کی (کہا:) میں نے حضرت ابن عباس رضی اللہ عنہ سے سنا، (اس سند میں سماع کی صراحت ہے۔)"}],[6804,"زُبیدی نے زہری سے روایت کی ، انہوں نے کہا : مجھے سعید بن مسیب نے سیدنا ابوہریرہ رضی اللہ عنہ سے خبر دی کہ وہ کہا کرتے تھے : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ہر پیدا ہونے والا بچہ فطرت ( اللہ پر ایمان اور اچھائی کی محبت ) پر پیدا ہوتا ہے ، پھر اس کے ماں باپ اس کو یہودی ، نصرانی اور مجوسی بنا دیتے ہیں ، جیسے ایک جانور ( ماں ) کامل الاعضاء جانور ( بچے ) کو جنم دیتی ہے ، کیا تمہیں ان میں کوئی عضو کٹا ہوا جانور نظر آتا ہے؟ \" پھر سیدنا ابوہریرہ رضی اللہ عنہ کہتے تھے : تم چاہو تو یہ آیت پڑھ لو : \" یہی اللہ کی ( عطا کردہ ) فطرت ہے جس پر اس نے لوگوں کی تخلیق فرمائی ، اللہ کی تخلیق میں ردوبدل نہیں ہوتا ۔","",{"u2":"ابوصالح نے حضرت ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا: \"ابن آدم کے متعلق زنا میں سے اس کا حصہ لکھ دیا گیا ہے۔ وہ لا محالہ اس کو حاصل کرنے والا ہے، پس دونوں آنکھیں، ان کا زنا دیکھنا ہے اور دونوں کان، ان کا زنا سننا ہے اور زبان، اس کا زنا بات کرنا ہے اور ہاتھ، اس کا زنا پکڑنا ہے اور پاؤں، اس کا زنا چل کر جانا ہے اور دل تمنا رکھتا ہے اور خواہش کرتا ہے اور شرم گاہ ان تمام باتوں کی تصدیق کرتی ہے (اسے عملا سچ کر دکھاتی ہے اور حرام کا ارتکاب ہو جاتا ہے) یا اس کی تکذیب کرتی ہے (حقیقی زنا سے بچاؤ ہو جاتا ہے۔)\""}],[6805,"معمر نے زہری سے اسی سند کے ساتھ روایت کی اور کہا : \" جس طرح ایک ( مادہ ) جانور بچے کو جنم دیتی ہے ۔ \" انہوں نے \" کامل الاعضاء \" ذکر نہیں کیا ۔","",{"u2":"زُبیدی نے زہری سے روایت کی، انہوں نے کہا: مجھے سعید بن مسیب نے حضرت ابوہریرہ رضی اللہ عنہ سے خبر دی کہ وہ کہا کرتے تھے: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہر پیدا ہونے والا بچہ فطرت (اللہ پر ایمان اور اچھائی کی محبت) پر پیدا ہوتا ہے، پھر اس کے ماں باپ اس کو یہودی، نصرانی اور مجوسی بنا دیتے ہیں، جیسے ایک جانور (ماں) کامل الاعضاء جانور (بچے) کو جنم دیتی ہے، کیا تمہیں ان میں کوئی عضو کٹا ہوا جانور نظر آتا ہے؟\" پھر حضرت ابوہریرہ رضی اللہ عنہ کہتے تھے: تم چاہو تو یہ آیت پڑھ لو: \"یہی اللہ کی (عطا کردہ) فطرت ہے جس پر اس نے لوگوں کی تخلیق فرمائی، اللہ کی تخلیق میں ردوبدل نہیں ہوتا۔\""}],[6806,"یونس بن یزید نے ابن شہاب سے روایت کی ، انہیں ابوسلمہ بن عبدالرحمٰن نے بتایا کہ سیدنا ابوہریرہ رضی اللہ عنہ نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کوئی پیدا ہونے والا بچہ نہیں مگر اس کی ولادت فطرت پر ہوتی ہے ۔ \" پھر ( ابوہریرہ رضی اللہ عنہ ) کہتے : یہ آیت پڑھ لو : \" یہی اللہ کی ( عطا کردہ ) فطرت ہے جس پر اس نے لوگوں کی تخلیق کی ، اللہ کی تخلیق میں تبدیلی نہیں ہو گی ، یہی سیدھا مستحکم دین ہے ( جس کی انسانی فطرت امانت دار ہے ۔)","",{"u2":"معمر نے زہری سے اسی سند کے ساتھ روایت کی اور کہا: \"جس طرح ایک (مادہ) جانور بچے کو جنم دیتی ہے۔\" انہوں نے \"کامل الاعضاء\" ذکر نہیں کیا۔"}],[6807,"جریر نے اعمش سے ، انہوں نے ابوصالح سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کوئی ولادت پانے والا نہیں مگر وہ فطرت ہی پر پیدا ہوا ہے ، پھر اس کے والدین اسے یہودی ، نصرانی اور مشرک بنا دیتے ہیں ۔ \" ایک آدمی نے کہا : اللہ کے رسول! اگر وہ اس سے پہلے مر جائے؟ آپ نے فرمایا : \" اللہ ہی زیادہ جاننے والا ہے کہ ( بڑے ہو کر ) وہ بچے کیا عمل کرنے والے تھے ۔","",{"u2":"یونس بن یزید نے ابن شہاب سے روایت کی، انہیں ابوسلمہ بن عبدالرحمٰن نے بتایا کہ حضرت ابوہریرہ رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کوئی پیدا ہونے والا بچہ نہیں مگر اس کی ولادت فطرت پر ہوتی ہے۔\" پھر (ابوہریرہ رضی اللہ عنہ) کہتے: یہ آیت پڑھ لو: \"یہی اللہ کی (عطا کردہ) فطرت ہے جس پر اس نے لوگوں کی تخلیق کی، اللہ کی تخلیق میں تبدیلی نہیں ہو گی، یہی سیدھا مستحکم دین ہے (جس کی انسانی فطرت امانت دار ہے۔)\""}],[6808,"ابوبکر بن ابی شیبہ اور ابوکریب نے ہمیں حدیث بیان کی ، دونوں نے کہا : ہمیں ابومعاویہ نے حدیث بیان کی ، نیز ہمیں ابن نمیر نے بھی ( یہی ) حدیث بیان کی ، انہوں نے کہا : ہمیں میرے والد نے حدیث بیان کی ، ( ابومعاویہ اور ابن نمیر کے والد ) دونوں نے اعمش سے اسی سند کے ساتھ حدیث بیان کی ۔ ابن نمیر کی حدیث میں ہے : \"\" کوئی بچہ پیدا ہونے والا بچہ نہیں مگر وہ ملت پر ہوتا ہے ۔ \"\" اور ابومعاویہ سے ابوبکر نے جو روایت کی اس میں ہے : \"\" مگر وہ اس ملت ( ملت اسلامی ) پر ہوتا ہے یہاں تک کہ اس کی زبان اس ( کے کفر یا ایمان ) کو بیان کر دیتی ہے ۔ \"\" اور ابومعاویہ سے ابوکریب کی روایت میں ہے : \"\" کوئی ولادت پانے والا نومولود نہیں مگر وہ اسی فطرت پر ہوتا ہے یہاں تک کہ اس کی زبان اس کے ( ماحول سے اخذ کردہ ) خیالات کی ترجمانی کرتی ہے ۔","",{"u2":"جریر نے اعمش سے، انہوں نے ابوصالح سے اور انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کوئی ولادت پانے والا نہیں مگر وہ فطرت ہی پر پیدا ہوا ہے، پھر اس کے والدین اسے یہودی، نصرانی اور مشرک بنا دیتے ہیں۔\" ایک آدمی نے کہا: اللہ کے رسول! اگر وہ اس سے پہلے مر جائے؟ آپ نے فرمایا: \"اللہ ہی زیادہ جاننے والا ہے کہ (بڑے ہو کر) وہ بچے کیا عمل کرنے والے تھے۔\""}],[6809,"معمر نے ہمیں ہمام بن منبہ سے حدیث بیان کی ، کہا : یہ احادیث ہیں جو سیدنا ابوہریرہ رضی اللہ عنہ نے ہمیں رسول اللہ صلی اللہ علیہ وسلم سے سنائیں ، پھر انہوں نے کئی احادیث بیان کیں ، ان میں سے ایک حدیث یہ ہے : اور رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جو ( بچہ ) پیدا ہوتا ہے ، وہ اسی فطرت پر پیدا ہوتا ہے ، پھر اس کے والدین اس کو یہودی اور نصرانی بنا دیتے ہیں جس طرح تم اونٹوں کے بچوں کو جنم دلواتے ہو ۔ کیا تم ان میں سے کسی کو کان کٹا ہوا پاتے ہو؟ یہاں تک کہ تم خود اس کا کان کاٹ دو \" لوگوں نے کہا : اللہ کے رسول! کیا آپ نے دیکھا کہ اگر وہ چھوٹا ہی فوت ہو جائے؟ فرمایا : \" اللہ ہی زیادہ جاننے والا ہے وہ ( چھوٹی عمر میں فوت ہونے والے بچے ) کیا عمل کرنے والے تھے ۔","",{"u2":"ابوبکر بن ابی شیبہ اور ابوکریب نے ہمیں حدیث بیان کی، دونوں نے کہا: ہمیں ابومعاویہ نے حدیث بیان کی، نیز ہمیں ابن نمیر نے بھی (یہی) حدیث بیان کی، انہوں نے کہا: ہمیں میرے والد نے حدیث بیان کی، (ابومعاویہ اور ابن نمیر کے والد) دونوں نے اعمش سے اسی سند کے ساتھ حدیث بیان کی۔\nابن نمیر کی حدیث میں ہے: \"کوئی بچہ پیدا ہونے والا بچہ نہیں مگر وہ ملت پر ہوتا ہے۔\"\nاور ابومعاویہ سے ابوبکر نے جو روایت کی اس میں ہے: \"مگر وہ اس ملت (ملت اسلامی) پر ہوتا ہے یہاں تک کہ اس کی زبان اس (کے کفر یا ایمان) کو بیان کر دیتی ہے۔\"\nاور ابومعاویہ سے ابوکریب کی روایت میں ہے: \"کوئی ولادت پانے والا نومولود نہیں مگر وہ اسی فطرت پر ہوتا ہے یہاں تک کہ اس کی زبان اس کے (ماحول سے اخذ کردہ) خیالات کی ترجمانی کرتی ہے۔\""}],[6810,"علاء کے والد عبدالرحمٰن نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ہر انسان کو اس کی ماں فطرت پر جنم دیتی ہے اور اس کے ماں باپ بعد میں اس کو یہودی یا نصرانی یا مجوسی بنا دیتے ہیں ۔ اگر وہ دونوں ( صحیح ) مسلمان ہوں تو وہ مسلمان رہتا ہے اور ہر انسان کو جب اس کی ماں جنم دیتی ہے تو شیطان اس کے دونوں پہلوؤں میں ہاتھ سے مارتا ہے سوائے حضرت مریم علیہ السلام اور ان کے بیٹے کے ( انہیں اللہ نے اس سے محفوظ رکھا ۔)","",{"u2":"معمر نے ہمیں ہمام بن منبہ سے حدیث بیان کی، کہا: یہ احادیث ہیں جو حضرت ابوہریرہ رضی اللہ عنہ نے ہمیں رسول اللہ صلی اللہ علیہ وسلم سے سنائیں، پھر انہوں نے کئی احادیث بیان کیں، ان میں سے ایک حدیث یہ ہے: اور رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو (بچہ) پیدا ہوتا ہے، وہ اسی فطرت پر پیدا ہوتا ہے، پھر اس کے والدین اس کو یہودی اور نصرانی بنا دیتے ہیں جس طرح تم اونٹوں کے بچوں کو جنم دلواتے ہو۔ کیا تم ان میں سے کسی کو کان کٹا ہوا پاتے ہو؟ یہاں تک کہ تم خود اس کا کان کاٹ دو\" لوگوں نے کہا: اللہ کے رسول! کیا آپ نے دیکھا کہ اگر وہ چھوٹا ہی فوت ہو جائے؟ فرمایا: \"اللہ ہی زیادہ جاننے والا ہے وہ (چھوٹی عمر میں فوت ہونے والے بچے) کیا عمل کرنے والے تھے۔\""}],[6811,"ابن ابی ذئب اور یونس نے ابن شہاب سے روایت کی ، انہوں نے عطاء بن یزید سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم سے مشرکین کی اولاد کے بارے میں سوال کیا گیا تو آپ نے فرمایا : \" اللہ ہی زیادہ جانتا ہے کہ ( بڑے ہو کر ) وہ کیا عمل کرنے والے تھے ۔","",{"u2":"علاء کے والد عبدالرحمٰن نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہر انسان کو اس کی ماں فطرت پر جنم دیتی ہے اور اس کے ماں باپ بعد میں اس کو یہودی یا نصرانی یا مجوسی بنا دیتے ہیں۔ اگر وہ دونوں (صحیح) مسلمان ہوں تو وہ مسلمان رہتا ہے اور ہر انسان کو جب اس کی ماں جنم دیتی ہے تو شیطان اس کے دونوں پہلوؤں میں ہاتھ سے مارتا ہے سوائے حضرت مریم علیہ السلام اور ان کے بیٹے کے (انہیں اللہ نے اس سے محفوظ رکھا۔)\""}],[6812,"معمر ، شعیب اور معقل بن عبیداللہ نے زہری سے یونس اور ابن ابی ذئب کی سند کے ساتھ ان دونوں کی حدیث کے مانند حدیث بیان کی ، مگر شعیب اور معقل کی حدیث میں ( مشرکین کی اولاد کی بجائے ) \" مشرکین کے چھوٹے بچوں \" کے الفاظ ہیں ۔","",{"u2":"ابن ابی ذئب اور یونس نے ابن شہاب سے روایت کی، انہوں نے عطاء بن یزید سے اور انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم سے مشرکین کی اولاد کے بارے میں سوال کیا گیا تو آپ نے فرمایا: \"اللہ ہی زیادہ جانتا ہے کہ(بڑے ہو کر) وہ کیا عمل کرنے والے تھے۔\""}],[6813,"اعرج نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم سے مشرکین کے بچوں کے بارے میں سوال کیا گیا ، ان میں سے جو چھوٹی عمر میں فوت ہو جائیں ( تو ان کا انجام کیا ہو گا؟ ) آپ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ تعالی زیادہ جانتا ہے کہ وہ کیا عمل کرنے والے تھے ۔","",{"u2":"معمر، شعیب اور معقل بن عبیداللہ نے زہری سے یونس اور ابن ابی ذئب کی سند کے ساتھ ان دونوں کی حدیث کے مانند حدیث بیان کی، مگر شعیب اور معقل کی حدیث میں (مشرکین کی اولاد کی بجائے) \"مشرکین کے چھوٹے بچوں\" کے الفاظ ہیں۔"}],[6814,"سعید بن جبیر نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم سے مشرکین کے بچوں کے متعلق سوال کیا گیا تو آپ نے فرمایا : \" اللہ تعالی نے جب ان کو پیدا کیا تو وہ زیادہ جاننے والا ہے کہ وہ کیا عمل کرنے والے تھے ۔","",{"u2":"اعرج نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم سے مشرکین کے بچوں کے بارے میں سوال کیا گیا، ان میں سے جو چھوٹی عمر میں فوت ہو جائیں (تو ان کا انجام کیا ہو گا؟) آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ زیادہ جانتا ہے کہ وہ کیا عمل کرنے والے تھے۔\""}],[6815,"سعید بن جبیر نے سیدنا ابن عباس رضی اللہ عنہ سے اور انہوں نے سیدنا ابی بن کعب رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس لڑکے کو حضرت خضر علیہ السلام نے قتل کیا تھا وہ طبعا کافر بنایا گیا تھا ، اگر وہ زندہ رہتا تو زبردستی اپنے ماں باپ کو سرکشی اور کفر کی طرف لے جاتا ۔","",{"u2":"سعید بن جبیر نے حضرت ابن عباس رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم سے مشرکین کے بچوں کے متعلق سوال کیا گیا تو آپ نے فرمایا: \"اللہ تعالیٰ نے جب ان کو پیدا کیا تو وہ زیادہ جاننے والا ہے کہ وہ کیا عمل کرنے والے تھے۔\""}],[6816,"فضیل بن عمرو نے عائشہ بنت طلحہ سے اور انہوں نے ام المومنین سیدہ عائشہ صدیقہ رضی اللہ عنہا سے روایت کی کہ ایک بچہ فوت ہوا تو میں نے کہا : اس کے لیے خوش خبری ہو ، وہ تو جنت کی چڑیوں میں سے ایک چڑیا ہے ۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کیا تم نہیں جانتی کہ اللہ تعالی نے جنت کو پیدا کیا اور دوزخ کو پیدا کیا اور اس کے لیے بھی اس میں جانے والے بنائے اور اُس کے لیے بھی اس میں رہنے والے بنائے؟","",{"u2":"سعید بن جبیر نے حضرت ابن عباس رضی اللہ عنہ سے اور انہوں نے حضرت ابی بن کعب رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس لڑکے کو حضرت خضر علیہ السلام نے قتل کیا تھا وہ طبعا کافر بنایا گیا تھا، اگر وہ زندہ رہتا تو زبردستی اپنے ماں باپ کو سرکشی اور کفر کی طرف لے جاتا۔\""}],[6817,"وکیع نے طلحہ بن یحیی سے ، انہوں نے اپنی پھوپھی عائشہ بنت طلحہ سے اور انہوں نے ام المومنین سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم کو انصار کے ایک بچے کے جنازے کے لیے بلایا گیا ، میں نے کہا : اللہ کے رسول! اس کے لیے خوش خبری ہو یہ جنت کی چڑیوں میں سے ایک چڑیا ہے ، اس نے کوئی گناہ کیا ، نہ گناہ کرنے کی عمر پائی ، آپ صلی اللہ علیہ وسلم نے فرمایا : \" یا اس کے علاوہ کچھ اور؟ عائشہ! اللہ تعالی نے جنت میں رہنے والے لوگ پیدا فرمائے ، انہیں اس وقت جنت کے لیے تخلیق کیا جب وہ اپنے باپوں کی پشتوں میں تھے اور دوزخ کے لیے بھی رہنے والے بنائے ، انہیں اس وقت دوزخ کے لیے تخلیق کیا جب وہ اپنے باپوں کی پشتوں میں تھے ۔","",{"u2":"فضیل بن عمرو نے عائشہ بنت طلحہ سے اور انہوں نے ام المومنین حضرت عائشہ صدیقہ رضی اللہ عنہا سے روایت کی کہ ایک بچہ فوت ہوا تو میں نے کہا: اس کے لیے خوش خبری ہو، وہ تو جنت کی چڑیوں میں سے ایک چڑیا ہے۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم نہیں جانتی کہ اللہ تعالیٰ نے جنت کو پیدا کیا اور دوزخ کو پیدا کیا اور اس کے لیے بھی اس میں جانے والے بنائے اور اُس کے لیے بھی اس میں رہنے والے بنائے؟\""}],[6818,"اسماعیل بن زکریا اور سفیان ثوری نے طلحہ بن یحیی سے وکیع کی حدیث کے مانند اسی کی سند کے ساتھ روایت کی ۔","",{"u2":"وکیع نے طلحہ بن یحییٰ سے، انہوں نے اپنی پھوپھی عائشہ بنت طلحہ سے اور انہوں نے ام المومنین حضرت عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم کو انصار کے ایک بچے کے جنازے کے لیے بلایا گیا، میں نے کہا: اللہ کے رسول! اس کے لیے خوش خبری ہو یہ جنت کی چڑیوں میں سے ایک چڑیا ہے، اس نے کوئی گناہ کیا، نہ گناہ کرنے کی عمر پائی، آپ صلی اللہ علیہ وسلم نے فرمایا: \"یا اس کے علاوہ کچھ اور؟ عائشہ! اللہ تعالیٰ نے جنت میں رہنے والے لوگ پیدا فرمائے، انہیں اس وقت جنت کے لیے تخلیق کیا جب وہ اپنے باپوں کی پشتوں میں تھے اور دوزخ کے لیے بھی رہنے والے بنائے، انہیں اس وقت دوزخ کے لیے تخلیق کیا جب وہ اپنے باپوں کی پشتوں میں تھے۔\""}],[6819,"وکیع نے ہمیں معمر سے حدیث بیان کی ، انہوں نے علقمہ بن مرثد سے ، انہوں نے مغیرہ بن عبداللہ یشکری سے ، انہوں نے معرور بن سوید سے اور انہوں نے سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : نبی صلی اللہ علیہ وسلم کی اہلیہ سیدہ ام حبیبہ رضی اللہ عنہا نے یہ دعا کی : اے اللہ! مجھے اپنے خاوند رسول اللہ صلی اللہ علیہ وسلم اپنے والد سیدنا ابوسفیان رضی اللہ عنہ اور اپنے بھائی سیدنا معاویہ رضی اللہ عنہ ( کی زندگیوں ) سے مستفید فرما! ( سیدنا عبداللہ رضی اللہ عنہ نے ) کہا : تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" تم نے عمروں کی ایسی مدتوں کا ، جو مقرر کر دی گئی ہیں اور ان دنوں کا جو گنے جا چکے ہیں اور ایسے رزقوں کا جو بانٹے جا چکے ہیں ، سوال کیا ہے ۔ اگر تم اللہ سے یہ مانگتی کہ تمہیں آگ میں دیے جانے والے یا قبر میں دیے جانے والے عذاب سے پناہ عطا فرما دے تو یہ زیادہ اچھا اور زیادہ افضل ہوتا ۔ \"\" ( عبداللہ بن مسعود رضی اللہ عنہ نے ) کہا : آپ کے سامنے بندروں کے بارے میں بات چیت ہوئی ، مسعر نے کہا : میرا خیال ہے کہ انہوں ( سیدنا عبداللہ رضی اللہ عنہ ) نے کہا : خنزیروں کا بھی ( ذکر کیا گیا کہ وہ ) مسخ ہو کر بنے ہیں تو آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" اللہ تعالی نے مسخ ہونے والوں کی نہ نسل بنائی ہے نہ اولاد ، بندر اور خنزیر اس ( مسخ ہونے کے واقعے ) سے پہلے بھی ہوتے تھے ( جو موجودہ ہیں وہ انہی کی نسلیں ہیں ۔)","",{"u2":"اسماعیل بن زکریا اور سفیان ثوری نے طلحہ بن یحییٰ سے وکیع کی حدیث کے مانند اسی کی سند کے ساتھ روایت کی۔"}],[6820,"ابن بشر نے مسعر سے اسی سند کے ساتھ خبر دی ، مگر ابن بشر اور وکیع دونوں سے ان کی ( روایت کردہ ) حدیث میں یہ الفاظ منقول ہیں : \" آگ میں دیے جانے والے اور قبر میں دیے جانے والے عذاب سے ( پناہ مانگتی تو بہتر تھا ۔ ) \" ( \" یا \" کی بجائے \" اور \" ہے ۔)","",{"u2":"وکیع نے ہمیں معمر سے حدیث بیان کی، انہوں نے علقمہ بن مرثد سے، انہوں نے مغیرہ بن عبداللہ یشکری سے، انہوں نے معرور بن سوید سے اور انہوں نے حضرت عبداللہ بن مسعود رضی اللہ عنہ سے روایت کی، انہوں نے کہا: نبی صلی اللہ علیہ وسلم کی اہلیہ حضرت ام حبیبہ رضی اللہ عنہا نے یہ دعا کی: اے اللہ! مجھے اپنے خاوند رسول اللہ صلی اللہ علیہ وسلم اپنے والد حضرت ابوسفیان رضی اللہ عنہ اور اپنے بھائی حضرت معاویہ رضی اللہ عنہ (کی زندگیوں) سے مستفید فرما! (حضرت عبداللہ رضی اللہ عنہ نے) کہا: تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم نے عمروں کی ایسی مدتوں کا، جو مقرر کر دی گئی ہیں اور ان دنوں کا جو گنے جا چکے ہیں اور ایسے رزقوں کا جو بانٹے جا چکے ہیں، سوال کیا ہے۔ اگر تم اللہ سے یہ مانگتی کہ تمہیں آگ میں دیے جانے والے یا قبر میں دیے جانے والے عذاب سے پناہ عطا فرما دے تو یہ زیادہ اچھا اور زیادہ افضل ہوتا۔\"\n(عبداللہ بن مسعود رضی اللہ عنہ نے) کہا: آپ کے سامنے بندروں کے بارے میں بات چیت ہوئی، مسعر نے کہا: میرا خیال ہے کہ انہوں (حضرت عبداللہ رضی اللہ عنہ) نے کہا: خنزیروں کا بھی (ذکر کیا گیا کہ وہ) مسخ ہو کر بنے ہیں تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ نے مسخ ہونے والوں کی نہ نسل بنائی ہے نہ اولاد، بندر اور خنزیر اس (مسخ ہونے کے واقعے) سے پہلے بھی ہوتے تھے (جو موجودہ ہیں وہ انہی کی نسلیں ہیں۔)"}],[6821,"عبدالرزاق نے کہا : ہمیں ثوری نے علقمہ بن مرثد سے خبر دی ، انہوں نے مغیرہ بن عبداللہ یشکری سے ، انہوں نے معرور بن سوید سے اور انہوں نے سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت کی ، کہا : سیدہ ام حبیبہ رضی اللہ عنہا نے ( دعا کرتے ہوئے ) کہا : اے اللہ! مجھے میرے خاوند رسول اللہ صلی اللہ علیہ وسلم ، میرے والد ابوسفیان اور میرے بھائی ( کی درازی عمر ) سے مستفید فرما! تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا : \"\" تم نے اللہ تعالی سے ان مدتوں کا سوال کیا ہے جو مقرر کی جا چکیں اور قدموں کے ان نشانوں کا جن پر قدم رکھے جا چکے اور ایسے رزقوں کو جو تقسیم کیے جا چکے ۔ نہ ان میں سے کوئی چیز اپنا وقت آنے سے پہلے آ سکتی ہے اور نہ آنے کے بعد مؤخر ہو سکتی ہے ۔ اگر تم اللہ تعالی سے یہ مانگتی کہ وہ تمہیں جہنم میں دیے جانے والے عذاب اور قبر میں دیے جانے والے عذاب سے بچا لے تو تمہارے لیے بہتر ہوتا ۔ \"\" ( عبداللہ بن مسعود رضی اللہ عنہ نے ) کہا : ایک آدمی نے پوچھا : اللہ کے رسول! یہ بندر اور خنزیر کیا انہی میں سے ہیں جو مسخ ہو کر بنے تھے؟ تو نبی صلی اللہ علیہ وسلم نے فرمایا : \"\" اللہ تعالی نے کسی قوم کو ہلاک نہیں کیا یا ( فرمایا : ) کسی قوم کو عذاب نہیں دیا کہ پھر ان ( لوگوں ) کی نسل بنائے ( ان کے بچے پیدا کر کے انہیں آگے چلائے ۔ ) اور بلاشبہ بندر اور خنزیر پہلے بھی موجود تھے ۔ \"\" ( آگے انہی کی نسلیں چلی ہیں ۔)","",{"u2":"ابن بشر نے مسعر سے اسی سند کے ساتھ خبر دی، مگر ابن بشر اور وکیع دونوں سے ان کی (روایت کردہ) حدیث میں یہ الفاظ منقول ہیں: \"آگ میں دیے جانے والے اور قبر میں دیے جانے والے عذاب سے (پناہ مانگتی تو بہتر تھا۔)\" (\"یا\" کی بجائے \"اور\" ہے۔)"}],[6822,"ابوداود سلیمان بن معبد نے کہا : ہمیں حسین بن حفص نے حدیث بیان کی ، انہوں نے کہا : ہمیں سفیان نے اسی سند کے ساتھ حدیث بیان کی ، مگر انہوں نے کہا : \"\" اور قدموں کے ایسے نشان جن تک قدم پہنچ چکے ہیں ۔ \"\" ابن معبد نے کہا : ان ( اساتذہ ) میں سے بعض نے ( آپ صلی اللہ علیہ وسلم کے فرمان ) : \"\" اس کے حل ہونے سے پہلے ۔ \"\" یعنی اس کے اترنے سے پہلے ( وضاحتی الفاظ کے ساتھ ) روایت کی ۔","",{"u2":"عبدالرزاق نے کہا: ہمیں ثوری نے علقمہ بن مرثد سے خبر دی، انہوں نے مغیرہ بن عبداللہ یشکری سے، انہوں نے معرور بن سوید سے اور انہوں نے حضرت عبداللہ بن مسعود رضی اللہ عنہ سے روایت کی، کہا: حضرت ام حبیبہ رضی اللہ عنہا نے (دعا کرتے ہوئے) کہا: اے اللہ! مجھے میرے خاوند رسول اللہ صلی اللہ علیہ وسلم، میرے والد ابوسفیان اور میرے بھائی (کی درازی عمر) سے مستفید فرما! تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"تم نے اللہ تعالیٰ سے ان مدتوں کا سوال کیا ہے جو مقرر کی جا چکیں اور قدموں کے ان نشانوں کا جن پر قدم رکھے جا چکے اور ایسے رزقوں کو جو تقسیم کیے جا چکے۔ نہ ان میں سے کوئی چیز اپنا وقت آنے سے پہلے آ سکتی ہے اور نہ آنے کے بعد مؤخر ہو سکتی ہے۔ اگر تم اللہ تعالیٰ سے یہ مانگتی کہ وہ تمہیں جہنم میں دیے جانے والے عذاب اور قبر میں دیے جانے والے عذاب سے بچا لے تو تمہارے لیے بہتر ہوتا۔\"\n(عبداللہ بن مسعود رضی اللہ عنہ نے) کہا: ایک آدمی نے پوچھا: اللہ کے رسول! یہ بندر اور خنزیر کیا انہی میں سے ہیں جو مسخ ہو کر بنے تھے؟ تو نبی صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ نے کسی قوم کو ہلاک نہیں کیا یا (فرمایا:) کسی قوم کو عذاب نہیں دیا کہ پھر ان (لوگوں) کی نسل بنائے (ان کے بچے پیدا کر کے انہیں آگے چلائے۔) اور بلاشبہ بندر اور خنزیر پہلے بھی موجود تھے۔\" (آگے انہی کی نسلیں چلی ہیں۔)"}],[6823,"ابوداود سلیمان بن معبد نے کہا : ہمیں حسین بن حفص نے حدیث بیان کی ، انہوں نے کہا : ہمیں سفیان نے اسی سند کے ساتھ حدیث بیان کی ، مگر انہوں نے کہا : \"\" اور قدموں کے ایسے نشان جن تک قدم پہنچ چکے ہیں ۔ \"\" ابن معبد نے کہا : ان ( اساتذہ ) میں سے بعض نے ( آپ صلی اللہ علیہ وسلم کے فرمان ) : \"\" اس کے حل ہونے سے پہلے ۔ \"\" یعنی اس کے اترنے سے پہلے ( وضاحتی الفاظ کے ساتھ ) روایت کی ۔","",{"u2":"ابوداود سلیمان بن معبد نے کہا: ہمیں حسین بن حفص نے حدیث بیان کی، انہوں نے کہا: ہمیں سفیان نے اسی سند کے ساتھ حدیث بیان کی، مگر انہوں نے کہا: \"اور قدموں کے ایسے نشان جن تک قدم پہنچ چکے ہیں۔\"\nابن معبد نے کہا: ان (اساتذہ) میں سے بعض نے (آپ صلی اللہ علیہ وسلم کے فرمان): \"اس کے حل ہونے سے پہلے۔\" یعنی اس کے اترنے سے پہلے (وضاحتی الفاظ کے ساتھ) روایت کی۔"}],[6824,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" طاقت ور مومن اللہ کے نزدیک کمزور مومن کی نسبت بہتر اور زیادہ محبوب ہے ، جبکہ خیر دونوں میں ( موجود ) ہے ۔ جس چیز سے تمہیں ( حقیقی ) نفع پہنچے اس میں حرص کرو اور اللہ سے مدد مانگو اور کمزور نہ پڑو ( مایوس ہو کر نہ بیٹھ ) جاؤ ، اگر تمہیں کوئی ( نقصان ) پہنچے تو یہ نہ کہو : کاش! میں ( اس طرح ) کرتا تو ایسا ایسا ہوتا ، بلکہ یہ کہو : ( یہ ) اللہ کی تقدیر ہے ، وہ جو چاہتا ہے کرتا ہے ، اس لیے کہ ( حشرت کرتے ہوئے ) کاش ( کہنا ) شیطان کے عمل ( کے دروازے ) کو کھول دیتا ہے ۔","",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"طاقت ور مومن اللہ کے نزدیک کمزور مومن کی نسبت بہتر اور زیادہ محبوب ہے، جبکہ خیر دونوں میں (موجود) ہے۔ جس چیز سے تمہیں (حقیقی) نفع پہنچے اس میں حرص کرو اور اللہ سے مدد مانگو اور کمزور نہ پڑو (مایوس ہو کر نہ بیٹھ) جاؤ، اگر تمہیں کوئی (نقصان) پہنچے تو یہ نہ کہو: کاش! میں (اس طرح) کرتا تو ایسا ایسا ہوتا، بلکہ یہ کہو: (یہ) اللہ کی تقدیر ہے، وہ جو چاہتا ہے کرتا ہے،اس لیے کہ (حشرت کرتے ہوئے) کاش (کہنا) شیطان کے عمل (کے دروازے) کو کھول دیتا ہے۔\""}],[6825,"قاسم بن محمد نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے ( یہ آیات ) تلاوت فرمائیں : \" وہی ہے جس نے آپ پر کتاب نازل فرمائی ، اس میں سے محکم ( معنی میں واضح ) آیتیں ہیں ، وہی اصل کتاب ہیں اور دوسری متشابہ آیات ہیں ، پھر وہ لوگ جن کے دلوں میں کجی ہے ، وہ فتنے کی تلاش میں ان آیتوں کے پیچھے پڑے رہتے ہیں جو ان ( آیات قرآنی ) میں سے متشابہ ہیں ۔ ان ( متشابہ آیات ) کا حقیقی معنی اللہ اور ان لوگوں کے علاوہ اور کوئی نہیں جانتا جو علم میں راسخ ہیں ۔ وہ ( یہی ) کہتے ہیں : ہم ان ( آیات ) پر ایمان لائے ، سب ( آیتیں ) ہمارے رب کی طرف سے ہیں اور دانائی رکھنے والوں کے سوا کوئی ( ان سے ) نصیحت حاصل نہیں کرتا ۔ \" ( سیدہ عائشہ رضی اللہ عنہا نے ) کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جب تم ایسے لوگوں کو دیکھو جو قرآن میں سے متشابہ ( آیات ) کے پیچھے پڑتے ہیں ، تو یہی لوگ ہیں جن کا اللہ نے ( سابقہ آیات میں ) ذکر کیا ہے ، لہٰذا ان سے بچ کر رہو ۔","",{"u2":"قاسم بن محمد نے حضرت عائشہ رضی اللہ عنہا سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے (یہ آیات) تلاوت فرمائیں: \"وہی ہے جس نے آپ پر کتاب نازل فرمائی، اس میں سے محکم (معنی میں واضح) آیتیں ہیں، وہی اصل کتاب ہیں اور دوسری متشابہ آیات ہیں، پھر وہ لوگ جن کے دلوں میں کجی ہے، وہ فتنے کی تلاش میں ان آیتوں کے پیچھے پڑے رہتے ہیں جو ان (آیات قرآنی) میں سے متشابہ ہیں۔ ان (متشابہ آیات) کا حقیقی معنی اللہ اور ان لوگوں کے علاوہ اور کوئی نہیں جانتا جو علم میں راسخ ہیں۔ وہ (یہی) کہتے ہیں: ہم ان (آیات) پر ایمان لائے، سب (آیتیں) ہمارے رب کی طرف سے ہیں اور دانائی رکھنے والوں کے سوا کوئی (ان سے) نصیحت حاصل نہیں کرتا۔\" (حضرت عائشہ رضی اللہ عنہا نے) کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم ایسے لوگوں کو دیکھو جو قرآن میں سے متشابہ (آیات) کے پیچھے پڑتے ہیں، تو یہی لوگ ہیں جن کا اللہ نے (سابقہ آیات میں) ذکر کیا ہے، لہذا ان سے بچ کر رہو۔\""}],[6826,"حماد بن زید نے کہا : ہمیں ابوعمران جونی نے حدیث بیان کی ، انہوں نے کہا : عبداللہ بن رباح انصاری نے میری طرف لکھ بھیجا کہ سیدنا عبداللہ بن عمرو رضی اللہ عنہ نے کہا : میں ایک روز دن چڑھے ( مسجد میں ) رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا تو اتنے میں آپ صلی اللہ علیہ وسلم نے دو آدمیوں کی آوازیں سنیں جو ایک آیت کے بارے میں ( ایک دوسرے سے ) اختلاف کر رہے تھے ۔ آپ صلی اللہ علیہ وسلم نکل کر ہمارے سامنے تشریف لائے ۔ آپ کے چہرہ مبارک پر غصہ ( صاف ) پہچانا جا رہا تھا تو آپ نے فرمایا : \" جو لوگ تم سے پہلے تھے وہ کتاب اللہ کے بارے میں اختلاف کرنے سے ہلاک ہو گئے ۔","",{"u2":") حماد بن زید نے کہا: ہمیں ابوعمران جونی نے حدیث بیان کی، انہوں نے کہا: عبداللہ بن رباح انصاری نے میری طرف لکھ بھیجا کہ حضرت عبداللہ بن عمرو رضی اللہ عنہ نے کہا: میں ایک روز دن چڑھے (مسجد میں) رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا تو اتنے میں آپ صلی اللہ علیہ وسلم نے دو آدمیوں کی آوازیں سنیں جو ایک آیت کے بارے میں (ایک دوسرے سے) اختلاف کر رہے تھے۔ آپ صلی اللہ علیہ وسلم نکل کر ہمارے سامنے تشریف لائے۔ آپ کے چہرہ مبارک پر غصہ (صاف) پہچانا جا رہا تھا تو آپ نے فرمایا: \"جو لوگ تم سے پہلے تھے وہ کتاب اللہ کے بارے میں اختلاف کرنے سے ہلاک ہو گئے۔\""}],[6827,"ابو قُدامہ حارث بن عبید نے ابوعمران سے ، انہوں نے سیدنا جندب بن عبداللہ بجلی رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تم اس وقت تک قرآن پڑھتے رہو جب تک تمہارے دل اس پر ایک دوسرے کے ساتھ موافقت کرتے رہیں ( قرآن کے معانی تمہارے دل پر واضح ہوتے جا رہے ہوں ) جب تم اس میں اختلاف کرنے لگو تو اٹھ جاؤ ۔","",{"u2":"ابو قُدامہ حارث بن عبید نے ابوعمران سے، انہوں نے حضرت جندب بن عبداللہ بجلی رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم اس وقت تک قرآن پڑھتے رہو جب تک تمہارے دل اس پر ایک دوسرے کے ساتھ موافقت کرتے رہیں (قرآن کے معانی تمہارے دل پر واضح ہوتے جا رہے ہوں) جب تم اس میں اختلاف کرنے لگو تو اٹھ جاؤ۔\""}],[6828,"ہمام نے کہا : ہمیں ابوعمران نے سیدنا جندب بن عبداللہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تم اس پر ایک دوسرے کے ساتھ موافقت اور مطابقت کرتے رہیں ، چنانچہ جب تمہارا اختلاف شروع ہو جائے تو اٹھ جاؤ ۔","",{"u2":"ہمام نے کہا: ہمیں ابوعمران نے حضرت جندب بن عبداللہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم اس پر ایک دوسرے کے ساتھ موافقت اور مطابقت کرتے رہیں، چنانچہ جب تمہارا اختلاف شروع ہو جائے تو اٹھ جاؤ۔\""}],[6829,"ابان نے کہا : ہمیں ابوعمران نے حدیث سنائی ، کہا : ہم کوفہ میں ( رہنے والے ) نوجوان لڑکے تھے جب سیدنا جندب رضی اللہ عنہ نے ہمیں ( نصیحت کرتے ہوئے ) کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ( اس وقت تک ) قرآن پڑھو ۔ \" جیسے ان دونوں ( ابوقدامہ حارث بن عبید اور ہمام ) کی حدیث ہے ۔","",{"u2":"ابان نے کہا: ہمیں ابوعمران نے حدیث سنائی، کہا: ہم کوفہ میں (رہنے والے) نوجوان لڑکے تھے جب حضرت جندب رضی اللہ عنہ نے ہمیں (نصیحت کرتے ہوئے) کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"(اس وقت تک) قرآن پڑھو۔\" جیسے ان دونوں (ابوقدامہ حارث بن عبید اور ہمام) کی حدیث ہے۔"}],[6830,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ تعالی کے نزدیک سب سے بڑھ کر بغض کے قابل وہ شخص ہے جو سخت جھگڑالو ہو ۔","",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ کے نزدیک سب سے بڑھ کر بغض کے قابل وہ شخص ہے جو سخت جھگڑالو ہو۔\""}],[6831,"حفص بن میسرہ نے کہا : مجھے زید بن اسلم نے عطاء بن یسار سے حدیث بیان کی ، انہوں نے سیدنا ابوسعید خدری رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تم ضرور ان لوگوں کے طریقوں پر بالشت بر بالشت اور ہاتھ بر ہاتھ چلتے جاؤ گے جو تم سے پہلے تھے ( بعینہ ان کے طریقے اختیار کرو گے ، ان سے ذرہ برابر آگے پیچھے نہ ہو گے ) حتی کہ اگر وہ سانڈے کے بل میں گھسے تو تم بھی ان کے پیچھے گھسو گے ۔ \" ہم نے عرض کی : اللہ کے رسول! کیا یہود اور نصاری ( کے پیچھے چلیں گے؟ ) آپ نے فرمایا : \" تو ( اور ) کن کے؟","",{"u2":"حفص بن میسرہ نے کہا: مجھے زید بن اسلم نے عطاء بن یسار سے حدیث بیان کی، انہوں نے حضرت ابوسعید خدری رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم ضرور ان لوگوں کے طریقوں پر بالشت بر بالشت اور ہاتھ بر ہاتھ چلتے جاؤ گے جو تم سے پہلے تھے (بعینہ ان کے طریقے اختیار کرو گے، ان سے ذرہ برابر آگے پیچھے نہ ہو گے) حتی کہ اگر وہ سانڈے کے بل میں گھسے تو تم بھی ان کے پیچھے گھسو گے۔\" ہم نے عرض کی: اللہ کے رسول! کیا یہود اور نصاریٰ (کے پیچھے چلیں گے؟) آپ نے فرمایا: \"تو (اور) کن کے؟\""}],[6832,"مجھے میرے بہت سے ساتھیوں نے سعید بن ابی مریم سے حدیث بیان کی ، انہوں نے کہا : ہمیں ابوغسان محمد بن مطرف نے زید بن اسلم سے اسی سند کے ساتھ اسی کے مانند خبر دی ۔","",{"u2":"مجھے میرے بہت سے ساتھیوں نے سعید بن ابی مریم سے حدیث بیان کی، انہوں نے کہا: ہمیں ابوغسان محمد بن مطرف نے زید بن اسلم سے اسی سند کے ساتھ اسی کے مانند خبر دی۔"}],[6833,"محمد بن یحیی نے کہا : ہمیں ابن ابی مریم نے حدیث بیان کی ، کہا : ہمیں ابوغسان نے حدیث بیان کی ، کہا : مجھے زید بن اسلم نے عطاء بن یسار سے حدیث بیان کی ، پھر اسی طرح حدیث سنائی ( جس طرح حفص بن میسرہ کی روایت ہے ۔)","",{"u2":"محمد بن یحییٰ نے کہا: ہمیں ابن ابی مریم نے حدیث بیان کی، کہا: ہمیں ابوغسان نے حدیث بیان کی، کہا: مجھے زید بن اسلم نے عطاء بن یسار سے حدیث بیان کی، پھر اسی طرح حدیث سنائی (جس طرح حفص بن میسرہ کی روایت ہے۔)"}],[6834,"احنف بن قیس نے سیدنا عبداللہ ( بن مسعود رضی اللہ عنہ ) سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" غلو میں گہرے اترنے والے ہلاک ہو گئے ۔ \" آپ نے تین بار یہ بات ارشاد فرمائی ۔","",{"u2":"احنف بن قیس نے حضرت عبداللہ (بن مسعود رضی اللہ عنہ) سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"غلو میں گہرے اترنے والے ہلاک ہو گئے۔\" آپ نے تین بار یہ بات ارشاد فرمائی۔"}],[6835,"ابوتیاح نے ہمیں حدیث بیان کی ، کہا : ہمیں سیدنا انس بن مالک رضی اللہ عنہ نے حدیث بیان کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" قیامت کی علامات میں سے یہ ( بھی ) ہیں کہ علم اٹھ جائے گا ، جہالت جاگزیں ہو جائے گی ، شراب پی جانے لگے گی اور زنا کھل کر ہونے لگے گا ۔","",{"u2":") ابوتیاح نے ہمیں حدیث بیان کی، کہا: ہمیں حضرت انس بن مالک رضی اللہ عنہ نے حدیث بیان کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \" قیامت کی علامات میں سے یہ (بھی) ہیں کہ علم اٹھ جائے گا، جہالت جاگزیں ہو جائے گی، شراب پی جانے لگے گی اور زنا کھل کر ہونے لگے گا۔\""}],[6836,"شعبہ نے کہا : میں نے قتادہ کو سیدنا انس بن مالک رضی اللہ عنہ سے حدیث بیان کرتے ہوئے سنا ، انہوں نے کہا : کیا میں تمہیں رسول اللہ صلی اللہ علیہ وسلم سے سنی ہوئی ایک حدیث بیان نہ کروں؟ یہ حدیث میرے بعد تم کو کوئی ایسا شخص نہیں بیان کرے گا جس نے وہ آپ صلی اللہ علیہ وسلم سے ( براہ راست ) سنی ہو : \" قیامت کی نشانیوں میں سے ہے کہ علم اٹھ جائے گا ، جہالت نمایاں ہو جائے گی ، زنا پھیل جائے گا ، شراب پی جانے لگی گی ، مرد رخصت ہو جائیں گے اور عورتیں باقی رہ جائیں گی یہاں تک کہ پچاس عورتوں کے معاملات کا نگران ایک رہ جائے گا ۔","",{"u2":"شعبہ نے کہا: میں نے قتادہ کو حضرت انس بن مالک رضی اللہ عنہ سے حدیث بیان کرتے ہوئے سنا، انہوں نے کہا: کیا میں تمہیں رسول اللہ صلی اللہ علیہ وسلم سے سنی ہوئی ایک حدیث بیان نہ کروں؟ یہ حدیث میرے بعد تم کو کوئی ایسا شخص نہیں بیان کرے گا جس نے وہ آپ صلی اللہ علیہ وسلم سے (براہ راست) سنی ہو: \"قیامت کی نشانیوں میں سے ہے کہ علم اٹھ جائے گا، جہالت نمایاں ہو جائے گی، زنا پھیل جائے گا، شراب پی جانے لگی گی، مرد رخصت ہو جائیں گے اور عورتیں باقی رہ جائیں گی یہاں تک کہ پچاس عورتوں کے معاملات کا نگران ایک رہ جائے گا۔\""}],[6837,"محمد بن بشر ، عبدہ اور ابواسامہ ، ان سب نے سعید بن ابی عروبہ سے روایت کی ، انہوں نے قتادہ سے ، انہوں نے سیدنا انس بن مالک رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی ۔ ابن بشر اور عبدہ کی حدیث میں ہے : میرے بعد یہ حدیث تمہیں کوئی نہیں سنائے گا ۔ میں نے ( خود ) رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا ، پھر اسی ( شعبہ کی حدیث ) کے مانند بیان کیا ۔","",{"u2":"محمد بن بشر، عبدہ اور ابواسامہ، ان سب نے سعید بن ابی عروبہ سے روایت کی، انہوں نے قتادہ سے، انہوں نے حضرت انس بن مالک رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی۔ ابن بشر اور عبدہ کی حدیث میں ہے: میرے بعد یہ حدیث تمہیں کوئی نہیں سنائے گا۔ میں نے (خود) رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا، پھر اسی (شعبہ کی حدیث) کے مانند بیان کیا۔"}],[6838,"وکیع اور عبداللہ بن نمیر نے کہا : ہمیں اعمش نے ابووائل سے حدیث بیان کی ، کہا : میں سیدنا عبداللہ بن مسعود اور سیدنا ابوموسی رضی اللہ عنہ کے پاس بیٹھا ہوا تھا ، ان دونوں نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" قیامت سے کچھ عرصہ پہلے وہ ایام ہوں گے جن میں علم اٹھ جائے گا ، جہل طاری ہو جائے گا اور ان دنوں ہرج کی کثرت ہو جائے گی اور ہرج ( سے مراد ) لوگوں کا قتل ہے ۔","",{"u2":"وکیع اور عبداللہ بن نمیر نے کہا: ہمیں اعمش نے ابووائل سے حدیث بیان کی، کہا: میں حضرت عبداللہ بن مسعود اور حضرت ابوموسی رضی اللہ عنہ کے پاس بیٹھا ہوا تھا، ان دونوں نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"قیامت سے کچھ عرصہ پہلے وہ ایام ہوں گے جن میں علم اٹھ جائے گا، جہل طاری ہو جائے گا اور ان دنوں ہرج کی کثرت ہو جائے گی اور ہرج (سے مراد) لوگوں کا قتل ہے۔\""}],[6839,"سفیان اور زائدہ نے ( سلیمان ) اعمش سے اور انہوں نے ( ابووائل ) شقیق سے روایت کی ، انہوں نے کہا : میں عبداللہ ( بن مسعود ) اور ابوموسی رضی اللہ عنہ کے پاس بیٹھا ہوا تھا ، وہ دونوں احادیث بیان کر رہے تھے تو دونوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ، وکیع اور ابن نمیر کی حدیث کے مانند ۔"],[6840,"سفیان اور زائدہ نے ( سلیمان ) اعمش سے اور انہوں نے ( ابووائل ) شقیق سے روایت کی ، انہوں نے کہا : میں عبداللہ ( بن مسعود ) اور ابوموسی رضی اللہ عنہ کے پاس بیٹھا ہوا تھا ، وہ دونوں احادیث بیان کر رہے تھے تو دونوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ، وکیع اور ابن نمیر کی حدیث کے مانند ۔","",{"u2":"سفیان اور زائدہ نے (سلیمان) اعمش سے اور انہوں نے (ابووائل) شقیق سے روایت کی، انہوں نے کہا: میں عبداللہ (بن مسعود) اور ابوموسیٰ رضی اللہ عنہ کے پاس بیٹھا ہوا تھا، وہ دونوں احادیث بیان کر رہے تھے تو دونوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا، وکیع اور ابن نمیر کی حدیث کے مانند۔"}],[6841,"ابومعاویہ نے اعمش سے ، انہوں نے شقیق سے ، انہوں نے ابوموسی رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی ۔","",{"u2":"ابومعاویہ نے اعمش سے، انہوں نے شقیق سے، انہوں نے ابوموسیٰ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی۔"}],[6842,"جریر نے اعمش سے ، انہوں نے ابووائل سے روایت کی ، کہا : میں سیدنا عبداللہ بن مسعود اور سیدنا ابوموسی رضی اللہ عنہ کے ساتھ بیٹھا ہوا تھا ، وہ دونوں احادیث بیان کر رہے تھے تو سیدنا ابوموسی رضی اللہ عنہ نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ، اسی ( سابقہ حدیث ) کے مانند ۔","",{"u2":"جریر نے اعمش سے، انہوں نے ابووائل سے روایت کی، کہا: میں حضرت عبداللہ بن مسعود اور حضرت ابوموسیٰ رضی اللہ عنہ کے ساتھ بیٹھا ہوا تھا، وہ دونوں احادیث بیان کر رہے تھے تو حضرت ابوموسیٰ رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا، اسی (سابقہ حدیث) کے مانند۔"}],[6843,"شعیب نے زہری سے روایت کی ، انہوں نے کہا : مجھے حمید بن عبدالرحمٰن زہری نے حدیث بیان کی کہ سیدنا ابوہریرہ رضی اللہ عنہ نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" زمانہ باہم قریب ہو جائے گا اور علم کم ہو جائے گا ۔ \" پھر اسی کے مانند بیان کیا ۔","",{"u2":"یونس نے ابن شہاب سے روایت کی، انہوں نے کہا: مجھے حمید بن عبدالرحمٰن بن عوف نے حدیث بیان کی کہ حضرت ابوہریرہ رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"زمانہ باہم قریب ہو جائے گا (وقت بہت تیزی سے گزرتا ہوا محسوس ہو گا)، علم اٹھا لیا جائے گا، فتنے نمودار ہوں گے، (دلوں میں) بخل اور حرص ڈال دیا جائے گا اور ہرج کثرت سے ہو گا۔\" صحابہ نے پوچھا: ہرج کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"قتل و غارت گری۔\""}],[6844,"معمر نے زہری سے ، انہوں نے سعید ( بن مسیب ) سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" زمانہ باہم قریب ہو جائے گا اور علم اٹھا لیا جائے گا ۔ \" پھر ان دونوں ( یونس اور شعیب ) کی حدیث کے مانند بیان کیا ۔","",{"u2":"شعیب نے زہری سے روایت کی، انہوں نے کہا: مجھے حمید بن عبدالرحمٰن زہری نے حدیث بیان کی کہ حضرت ابوہریرہ رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"زمانہ باہم قریب ہو جائے گا اور علم کم ہو جائے گا۔\" پھر اسی کے مانند بیان کیا۔"}],[6846,"علاء کے والد عبدالرحمٰن ، سالم ، ہمام بن منبہ اور ابویونس سب نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : نبی صلی اللہ علیہ وسلم سے روایت ہے ، جس طرح زہری نے حمید سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی مگر انہوں نے یہ بیان نہیں کیا : \" اور ( دلوں میں ) بخل اور حرص ڈال دیا جائے گا ۔"],[6847,"علاء کے والد عبدالرحمٰن ، سالم ، ہمام بن منبہ اور ابویونس سب نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : نبی صلی اللہ علیہ وسلم سے روایت ہے ، جس طرح زہری نے حمید سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی مگر انہوں نے یہ بیان نہیں کیا : \" اور ( دلوں میں ) بخل اور حرص ڈال دیا جائے گا ۔"],[6849,"علاء کے والد عبدالرحمٰن ، سالم ، ہمام بن منبہ اور ابویونس سب نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : نبی صلی اللہ علیہ وسلم سے روایت ہے ، جس طرح زہری نے حمید سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی مگر انہوں نے یہ بیان نہیں کیا : \" اور ( دلوں میں ) بخل اور حرص ڈال دیا جائے گا ۔","",{"u2":"علاء کے والد عبدالرحمٰن، سالم، ہمام بن منبہ اور ابویونس سب نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: نبی صلی اللہ علیہ وسلم سے روایت ہے، جس طرح زہری نے حمید سے اور انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی مگر انہوں نے یہ بیان نہیں کیا: \"اور (دلوں میں) بخل اور حرص ڈال دیا جائے گا۔\""}],[6850,"جریر نے ہشام بن عروہ سے اور انہوں نے اپنے والد سے روایت کی ، انہوں نے کہا : میں نے سیدنا عبداللہ بن عمرو بن عاص رضی اللہ عنہ کو کہتے ہوئے سنا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ فرماتے تھے : \" اللہ تعالی علم کو لوگوں سے چھینتے ہوئے نہیں اٹھائے گا بلکہ وہ علماء کو اٹھا کر علم کو اٹھا لے گا حتی کہ جب وہ ( لوگوں میں ) کسی عالم کو ( باقی ) نہیں چھوڑے گا تو لوگ ( دین کے معاملات میں بھی ) جاہلوں کو اپنے سربراہ بنا لیں گے ۔ ان سے ( دین کے بارے میں ) سوال کیے جائیں گے تو وہ علم کے بغیر فتوے دیں گے ، اس طرح خود بھی گمراہ ہوں گے اور دوسروں کو بھی گمراہ کریں گے ۔","",{"u2":"جریر نے ہشام بن عروہ سے اور انہوں نے اپنے والد سے روایت کی، انہوں نے کہا: میں نے حضرت عبداللہ بن عمرو بن عاص رضی اللہ عنہ کو کہتے ہوئے سنا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ فرماتے تھے: \"اللہ تعالیٰ علم کو لوگوں سے چھینتے ہوئے نہیں اٹھائے گا بلکہ وہ علماء کو اٹھا کر علم کو اٹھا لے گا حتی کہ جب وہ (لوگوں میں) کسی عالم کو (باقی) نہیں چھوڑے گا تو لوگ (دین کے معاملات میں بھی) جاہلوں کو اپنے سربراہ بنا لیں گے۔ ان سے (دین کے بارے میں) سوال کیے جائیں گے تو وہ علم کے بغیر فتوے دیں گے، اس طرح خود بھی گمراہ ہوں گے اور دوسروں کو بھی گمراہ کریں گے۔\""}],[6851,"حماد بن زید ، عباد بن عباد ، ابومعاویہ ، وکیع ، ابن ادریس ، ابواسامہ ، ابن نمیر ، عبدہ ، سفیان ( بن عیینہ ) ، یحیی بن سعید ، عمر بن علی اور شعبہ بن حجاج ، سب نے ہشام بن عروہ سے ، انہوں نے اپنے والد سے ، انہوں نے عبداللہ بن عمرو رضی اللہ عنہ سے اور انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے جریر کی روایت کردہ حدیث کے مطابق روایت کی اور عمر بن علی کی حدیث میں مزید یہ ہے : پھر میں ایک سال بعد سیدنا عبداللہ بن عمرو رضی اللہ عنہ سے ملا اور ان سے سوال کیا تو انہوں نے وہ حدیث مجھے دوبارہ اسی طرح سنائی جیسے ( پہلے ) بیان کی تھی ۔ کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ فرما رہے تھے ۔","",{"u2":"حماد بن زید، عباد بن عباد، ابومعاویہ، وکیع، ابن ادریس، ابواسامہ، ابن نمیر، عبدہ، سفیان (بن عیینہ)، یحییٰ بن سعید، عمر بن علی اور شعبہ بن حجاج، سب نے ہشام بن عروہ سے، انہوں نے اپنے والد سے، انہوں نے عبداللہ بن عمرو رضی اللہ عنہ سے اور انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے جریر کی روایت کردہ حدیث کے مطابق روایت کی اور عمر بن علی کی حدیث میں مزید یہ ہے: پھر میں ایک سال بعد حضرت عبداللہ بن عمرو رضی اللہ عنہ سے ملا اور ان سے سوال کیا تو انہوں نے وہ حدیث مجھے دوبارہ اسی طرح سنائی جیسے (پہلے) بیان کی تھی۔ کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ فرما رہے تھے۔"}],[6852,"جعفر نے عمر بن حکم سے ، انہوں نے عبداللہ بن عمرو بن عاص رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے ہشام بن عروہ کی حدیث کی طرح بیان کیا ۔","",{"u2":"جعفر نے عمر بن حکم سے، انہوں نے عبداللہ بن عمرو بن عاص رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے ہشام بن عروہ کی حدیث کی طرح بیان کیا۔"}],[6853,"عبداللہ بن وہب نے کہا : مجھے ابوشُریح نے حدیث بیان کی کہ انہیں ابواسود نے عروہ بن زبیر سے حدیث بیان کی ، انہوں نے کہا : سیدہ عائشہ رضی اللہ عنہا نے مجھ سے فرمایا : بھانجے! مجھے خبر ملی ہے کہ عبداللہ بن عمر رضی اللہ عنہ ہمارے ہاں ( مدینہ ) سے گزر کر حج پر جانے والے ہیں ۔ تم ان سے ملو اور ان سے سوال کرو ۔ انہوں نے نبی صلی اللہ علیہ وسلم سے بڑا علم حاصل کر کے محفوظ کر رکھا ہے ۔ ( عروہ نے ) کہا : میں ان سے ملا اور بہت سی چیزوں کے بارے میں ، جو وہ رسول اللہ صلی اللہ علیہ وسلم سے بیان کرتے تھے ، ان سے پوچھا ۔ عروہ نے کہا : انہوں نے جو کچھ بیان کیا اس میں یہ بھی تھا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" اللہ تعالی علم کو لوگوں سے یک لخت چھین نہیں لے گا بلکہ وہ علماء کو اٹھا لے گا اور ان کے ساتھ علم کو بھی اٹھا لے گا ۔ اور لوگوں میں جاہل سربراہوں کو باقی چھوڑ دے گا جو علم کے بغیر لوگوں کو فتوے دیں گے ، اس طرح خود بھی گمراہ ہوں گے اور ( لوگوں کو بھی ) گمراہ کریں گے ۔ \"\" عروہ نے کہا : جب میں نے سیدہ عائشہ رضی اللہ عنہا کو یہ حدیث سنائی تو انہوں نے اسے ایک بہت بڑی بات سمجھا اور اس کو غیر معروف ( ناقابل قبول ) قرار دیا ۔ اور فرمایا : کیا انہوں نے تمہیں بتایا تھا کہ انہوں نے ( خود ) رسول اللہ صلی اللہ علیہ وسلم سے سنا تھا ، آپ نے یہ بات کہی تھی؟ عروہ نے کہا : یہاں تک کہ جب اگلا سال ہوا تو انہوں ( سیدہ عائشہ رضی اللہ عنہا ) نے ان سے کہا : ( عبداللہ ) بن عمرو رضی اللہ عنہ آ گئے ہیں ، ان سے ملو ، ان کے ساتھ بات چیت کا آغاز کرو ، یہاں تک کہ ان سے اسی حدیث کے بارے میں پوچھو جو انہوں نے علم کے حوالے سے تمہیں بیان کی تھی ۔ ( عروہ نے ) کہا : میں ان سے ملا اور ان سے سوال کیا تو انہوں نے وہ حدیث میرے سامنے ( بالکل ) اسی طرح بیان کر دی جس طرح پہلی بار بیان کی تھی ۔ عروہ نے کہا : جب میں نے سیدہ عائشہ رضی اللہ عنہا کو یہ بات بتائی تو انہوں نے فرمایا : میں سمجھتی ہوں کہ انہوں نے سچ کہا ، میں دیکھ رہی ہوں کہ انہوں نے اس میں نہ کوئی چیز بڑھائی ہے نہ کم کی ہے ۔","",{"u2":"عبداللہ بن وہب نے کہا: مجھے ابوشُریح نے حدیث بیان کی کہ انہیں ابواسود نے عروہ بن زبیر سے حدیث بیان کی، انہوں نے کہا: حضرت عائشہ رضی اللہ عنہا نے مجھ سے فرمایا: بھانجے! مجھے خبر ملی ہے کہ عبداللہ بن عمر رضی اللہ عنہ ہمارے ہاں (مدینہ) سے گزر کر حج پر جانے والے ہیں۔ تم ان سے ملو اور ان سے سوال کرو۔ انہوں نے نبی صلی اللہ علیہ وسلم سے بڑا علم حاصل کر کے محفوظ کر رکھا ہے۔ (عروہ نے) کہا: میں ان سے ملا اور بہت سی چیزوں کے بارے میں، جو وہ رسول اللہ صلی اللہ علیہ وسلم سے بیان کرتے تھے، ان سے پوچھا۔\nعروہ نے کہا: انہوں نے جو کچھ بیان کیا اس میں یہ بھی تھا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ علم کو لوگوں سے یک لخت چھین نہیں لے گا بلکہ وہ علماء کو اٹھا لے گا اور ان کے ساتھ علم کو بھی اٹھا لے گا۔ اور لوگوں میں جاہل سربراہوں کو باقی چھوڑ دے گا جو علم کے بغیر لوگوں کو فتوے دیں گے، اس طرح خود بھی گمراہ ہوں گے اور (لوگوں کو بھی) گمراہ کریں گے۔\"\nعروہ نے کہا: جب میں نے حضرت عائشہ رضی اللہ عنہا کو یہ حدیث سنائی تو انہوں نے اسے ایک بہت بڑی بات سمجھا اور اس کو غیر معروف (ناقابل قبول) قرار دیا۔ اور فرمایا: کیا انہوں نے تمہیں بتایا تھا کہ انہوں نے (خود) رسول اللہ صلی اللہ علیہ وسلم سے سنا تھا، آپ نے یہ بات کہی تھی؟\nعروہ نے کہا: یہاں تک کہ جب اگلا سال ہوا تو انہوں (حضرت عائشہ رضی اللہ عنہا) نے ان سے کہا: (عبداللہ) بن عمرو رضی اللہ عنہ آ گئے ہیں، ان سے ملو، ان کے ساتھ بات چیت کا آغاز کرو، یہاں تک کہ ان سے اسی حدیث کے بارے میں پوچھو جو انہوں نے علم کے حوالے سے تمہیں بیان کی تھی۔ (عروہ نے) کہا: میں ان سے ملا اور ان سے سوال کیا تو انہوں نے وہ حدیث میرے سامنے (بالکل) اسی طرح بیان کر دی جس طرح پہلی بار بیان کی تھی۔\nعروہ نے کہا: جب میں نے حضرت عائشہ رضی اللہ عنہا کو یہ بات بتائی تو انہوں نے فرمایا: میں سمجھتی ہوں کہ انہوں نے سچ کہا، میں دیکھ رہی ہوں کہ انہوں نے اس میں نہ کوئی چیز بڑھائی ہے نہ کم کی ہے۔"}],[6854,"سیدنا جریر بن عبداللہ سے روایت ہے کہ کچھ دیہاتی لوگ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے وہ کمبل پہنے ہوئے تھے۔ آپ صلی اللہ علیہ وسلم نے ان کا برا حال دیکھا اور ان کی محتاجی دریافت کی تو لوگوں کو رغبت دلائی صدقہ دینے کی۔ لوگوں نے صدقہ دینے میں دیر کی یہاں تک کہ اس بات کا رنج آپ صلی اللہ علیہ وسلم کے چہرے پر معلوم ہوا، پھر ایک انصاری شخص ایک تھیلی روپیوں کی لے کر آیا، پھر دوسرا آیا یہاں تک کہ تار بندھ گیا (صدقے اور خیرات کا)، آپ صلی اللہ علیہ وسلم کے چہرے پر خوشی معلوم ہونے لگی، پھر آپ صلی اللہ علیہ وسلم نے فرمایا: ”جو شخص اسلام میں اچھی بات نکالے (یعنی عمدہ بات کو جاری کرے جو شریعت کی رو سے ثواب ہے) پھر لوگ اس کے بعد اس پر عمل کریں تو اس کو اتنا ثواب ہو گا جتنا سب عمل کرنے والوں کو ہو گا اور عمل کرنے والوں کے ثواب میں کچھ کمی نہ ہو گی اور جو اسلام میں بری بات نکالے (مثلاً بدعت یا گناہ کی بات) اور لوگ اس کے بعد اس پر عمل کریں تو تمام عمل کرنے والوں کے برابر گناہ اس پر لکھا جائے گا اور عمل کرنے والوں کا گناہ کچھ کم نہ ہو گا۔“","",{"u2":"جریر بن عبدالحمید نے اعمش سے، انہوں نے موسیٰ بن عبداللہ بن یزید اور (مسلم) ابوضحیٰ سے، انہوں نے عبدالرحمٰن بن ہلال عبسی سے اور انہوں نے حضرت جریر بن عبداللہ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں کچھ دیہاتی حاضر ہوئے، انہوں نے اون کے کپڑے پہن رکھے تھے۔ آپ نے ان کی بدحالی دیکھی کہ وہ ضرورت مند اور محتاج ہو گئے تھے تو آپ نے لوگوں کو (ان کے لیے) صدقہ کرنے کی ترغیب دی لیکن لوگوں نے اس میں سستی سے کام لیا، حتی کہ یہ بات آپ صلی اللہ علیہ وسلم کے چہرہ انور سے ظاہر ہونے لگی۔\nکہا: پھر انصار میں سے ایک شخص چاندی (کے سکوں، درہموں) کی ایک تھیلی لے کر آ گیا، پھر دوسرا آیا، پھر لوگ ایک دوسرے کے پیچھے (صدقات لے کر) آنے لگے۔ یہاں تک کہ آپ کے چہرہ انور پر مسرت جھلکنے لگی، پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے اسلام میں کسی اچھے کام کی ابتدا کی اور اس کے بعد اس پر عمل ہوتا رہا، اس کے لیے (ہر) عمل کرنے والے (کے اجر) جتنا اجر لکھا جاتا رہے گا۔ اور ان کے گناہوں میں کسی چیز کی کمی نہ ہو گی۔\""}],[6855,"جریر رضی اللہ عنہ سے روایت ہے نبی اكرم صلی اللہ علیہ وسلم نے خطبہ پڑھا اور لوگوں كو ترغیب دی صدقہ دینے كی پھر بیان كیا اسی طرح جیسے اوپر گزرا","",{"u2":"حَدَّثَنَا یَحْیَی بْنُ یَحْیَی وَأَبُو بَکْرِ بْنُ أَبِی شَیْبَۃَ وَأَبُو کُرَیْبٍ جَمِیعًا عَنْ أَبِی مُعَاوِیَۃَ عَنْ الْأَعْمَشِ عَنْ مُسْلِمٍ عَنْ عَبْدِ الرَّحْمَنِ بْنِ ہِلَالٍ عَنْ جَرِیرٍ قَالَ خَطَبَ رَسُولُ اللَّہِ صَلَّی اللَّہُ عَلَیْہِ وَسَلَّمَ فَحَثَّ عَلَی الصَّدَقَۃِ بِمَعْنَی حَدِیثِ جَرِیرٍ حَدَّثَنَا مُحَمَّدُ بْنُ بَشَّارٍ حَدَّثَنَا یَحْیَی یَعْنِی ابْنَ سَعِیدٍ حَدَّثَنَا مُحَمَّدُ بْنُ أَبِی إِسْمَعِیلَ حَدَّثَنَا عَبْدُ الرَّحْمَنِ بْنُ ہِلَالٍ الْعَبْسِیُّ قَالَ قَالَ جَرِیرُ بْنُ عَبْدِ اللَّہِ قَالَ رَسُولُ اللَّہِ صَلَّی اللَّہُ عَلَیْہِ وَسَلَّمَ لَا یَسُنُّ عَبْدٌ سُنَّۃً صَالِحَۃً یُعْمَلُ بِہَا بَعْدَہُ ثُمَّ ذَکَرَ تَمَامَ الْحَدِیثِ حَدَّثَنِی عُبَیْدُ اللَّہِ بْنُ عُمَرَ الْقَوَارِیرِیُّ وَأَبُو کَامِلٍ وَمُحَمَّدُ بْنُ عَبْدِ الْمَلِکِ الْأُمَوِیُّ قَالُوا حَدَّثَنَا أَبُو عَوَانَۃَ عَنْ عَبْدِ الْمَلِکِ بْنِ عُمَیْرٍ عَنْ الْمُنْذِرِ بْنِ جَرِیرٍ عَنْ أَبِیہِ عَنْ النَّبِیِّ صَلَّی اللَّہُ عَلَیْہِ وَسَلَّمَ ح و حَدَّثَنَا مُحَمَّدُ بْنُ الْمُثَنَّی حَدَّثَنَا مُحَمَّدُ بْنُ جَعْفَرٍ ح و حَدَّثَنَا أَبُو بَکْرِ بْنُ أَبِی شَیْبَۃَ حَدَّثَنَا أَبُو أُسَامَۃَ ح و حَدَّثَنَا عُبَیْدُ اللَّہِ بْنُ مُعَاذٍ حَدَّثَنَا أَبِی قَالُوا حَدَّثَنَا شُعْبَۃُ عَنْ عَوْنِ بْنِ أَبِی جُحَیْفَۃَ عَنْ الْمُنْذِرِ بْنِ جَرِیرٍ عَنْ أَبِیہِ عَنْ النَّبِیِّ صَلَّی اللَّہُ عَلَیْہِ وَسَلَّمَ بِہَذَا الْحَدِیثِ"}],[6856,"محمد بن ابی اسماعیل نے کہا : ہمیں عبدالرحمٰن بن ہلال عبسی نے حدیث بیان کی ، انہوں نے کہا : سیدنا جریر بن عبداللہ رضی اللہ عنہ نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جو بندہ بھی کسی نیک کام کا آغاز کرے جس پر اس کے بعد عمل کیا جائے ۔ \" پھر پوری حدیث بیان کی ۔","",{"u2":"محمد بن ابی اسماعیل نے کہا: ہمیں عبدالرحمٰن بن ہلال عبسی نے حدیث بیان کی، انہوں نے کہا: حضرت جریر بن عبداللہ رضی اللہ عنہ نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو بندہ بھی کسی نیک کام کا آغاز کرے جس پر اس کے بعد عمل کیا جائے۔\" پھر پوری حدیث بیان کی۔"}],[6857,"عبدالملک بن عمیر اور عون بن ابی الجحیفہ نے مُنذِر بن جریر سے ، انہوں نے اپنے والد ( جریر بن عبداللہ رضی اللہ عنہ ) سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے یہی حدیث روایت کی ۔"],[6858,"عبدالملک بن عمیر اور عون بن ابی الجحیفہ نے مُنذِر بن جریر سے ، انہوں نے اپنے والد ( جریر بن عبداللہ رضی اللہ عنہ ) سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے یہی حدیث روایت کی ۔","",{"u2":"عبدالملک بن عمیر اور عون بن ابی الجحیفہ نے مُنذِر بن جریر سے،انہوں نے اپنے والد (جریر بن عبداللہ رضی اللہ عنہ) سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے یہی حدیث روایت کی۔"}],[6859,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس شخص نے ہدایت کی دعوت دی اسے اس ہدایت کی پیروی کرنے والوں کے اجر کے برابر اجر ملے گا اور ان کے اجر میں کوئی کمی نہیں ہو گی اور جس شخص نے کسی گمراہی کی دعوت دی ، اس پر اس کی پیروی کرنے والوں کے برابر گناہ ( کا بوجھ ) ہو گا اور ان کے گناہوں میں کوئی کمی نہیں ہو گی ۔","",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس شخص نے ہدایت کی دعوت دی اسے اس ہدایت کی پیروی کرنے والوں کے اجر کے برابر اجر ملے گا اور ان کے اجر میں کوئی کمی نہیں ہو گی اور جس شخص نے کسی گمراہی کی دعوت دی، اس پر اس کی پیروی کرنے والوں کے برابر گناہ (کا بوجھ) ہو گا اور ان کے گناہوں میں کوئی کمی نہیں ہو گی۔\""}],[6860,"جریر نے اعمش سے ، انہوں نے ابوصالح سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ عزوجل فرماتا ہے : میرے بارے میں میرا بندہ جو گمان کرتا ہے میں ( اس کو پورا کرنے کے لیے ) اس کے پاس ہوتا ہوں ۔ جب وہ مجھے یاد کرتا ہے تو میں اس کے ساتھ ہوتا ہوں ۔ اگر وہ مجھے اپنے دل میں یاد کرتا ہے تو میں اسے دل میں یاد کرتا ہوں اور اگر وہ مجھے ( بھری ) مجلس میں یاد کرتا ہے تو میں ان کی مجلس سے اچھی مجلس میں اسے یاد کرتا ہوں ، اگر وہ ایک بالشت میرے قریب آتا ہے تو میں ایک ہاتھ اس کے قریب جاتا ہوں اور اگر وہ ایک ہاتھ میر قریب آتا ہے تو میں دونوں ہاتھوں کی پوری لمبارئی کے برابر اس کے قریب آتا ہوں ، اگر وہ میرے پاس چلتا ہوا آتا ہے تو میں دوڑتا ہوا اس کے پاس جاتا ہوں ۔","",{"u2":"جریر نے اعمش سے، انہوں نے ابوصالح سے اور انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ عزوجل فرماتا ہے: میرے بارے میں میرا بندہ جو گمان کرتا ہے میں (اس کو پورا کرنے کے لیے) اس کے پاس ہوتا ہوں۔ جب وہ مجھے یاد کرتا ہے تو میں اس کے ساتھ ہوتا ہوں۔ اگر وہ مجھے اپنے دل میں یاد کرتا ہے تو میں اسے دل میں یاد کرتا ہوں اور اگر وہ مجھے (بھری) مجلس میں یاد کرتا ہے تو میں ان کی مجلس سے اچھی مجلس میں اسے یاد کرتا ہوں، اگر وہ ایک بالشت میرے قریب آتا ہے تو میں ایک ہاتھ اس کے قریب جاتا ہوں اور اگر وہ ایک ہاتھ میر قریب آتا ہے تو میں دونوں ہاتھوں کی پوری لمبارئی کے برابر اس کے قریب آتا ہوں، اگر وہ میرے پاس چلتا ہوا آتا ہے تو میں دوڑتا ہوا اس کے پاس جاتا ہوں۔\""}],[6861,"ابومعاویہ نے اعمش سے اسی سند کے ساتھ حدیث بیان کی ، اور انہوں نے یہ بیان نہیں کیا کہ \" اگر وہ ایک ہاتھ میرے قریب آتا ہے تو میں دونوں ہاتھوں کی پوری لمبائی کے برابر اس کے قریب آتا ہوں ۔","",{"u2":"ابومعاویہ نے اعمش سے اسی سند کے ساتھ حدیث بیان کی، اور انہوں نے یہ بیان نہیں کیا کہ \"اگر وہ ایک ہاتھ میرے قریب آتا ہے تو میں دونوں ہاتھوں کی پوری لمبائی کے برابر اس کے قریب آتا ہوں۔\""}],[6862,"ہمیں معمر نے ہمام بن منبہ سے حدیث بیان کی ، کہا : یہ احادیث ابوہریرہ رضی اللہ عنہ نے ہمیں رسول اللہ صلی اللہ علیہ وسلم سے بیان کیں ، پھر انہوں نے متعدد احادیث بیان کیں ، ان میں سے ایک یہ تھی کہ رسول اللہ صلی اللہ علیہ وسلم نے کہا : \" اللہ تعالی نے فرمایا : \" جب بندہ ایک بالشت ( بڑھ کر ) میرے پاس آتا ہے تو میں ایک ہاتھ ( بڑھ کر ) اس کے پاس جاتا ہوں اور جب وہ ایک ہاتھ ( بڑھ کر ) میرے پاس آتا ہے تو میں دونوں ہاتھوں کی لمبائی کے برابر ( بڑھ کر ) اس کے پاس جاتا ہوں اور اگر وہ دونوں ہاتھوں کی لمبائی کے برابر بڑھ کر میرے پاس آتا ہے تو میں اس کے پاس پہنچ جاتا ہوں ، اس سے زیادہ تیزی سے آتا ہوں ۔","",{"u2":") ہمیں معمر نے ہمام بن منبہ سے حدیث بیان کی، کہا: یہ احادیث ابوہریرہ رضی اللہ عنہ نے ہمیں رسول اللہ صلی اللہ علیہ وسلم سے بیان کیں، پھر انہوں نے متعدد احادیث بیان کیں، ان میں سے ایک یہ تھی کہ رسول اللہ صلی اللہ علیہ وسلم نے کہا: \"اللہ تعالیٰ نے فرمایا: \"جب بندہ ایک بالشت (بڑھ کر) میرے پاس آتا ہے تو میں ایک ہاتھ (بڑھ کر) اس کے پاس جاتا ہوں اور جب وہ ایک ہاتھ (بڑھ کر) میرے پاس آتا ہے تو میں دونوں ہاتھوں کی لمبائی کے برابر (بڑھ کر) اس کے پاس جاتا ہوں اور اگر وہ دونوں ہاتھوں کی لمبائی کے برابر بڑھ کر میرے پاس آتا ہے تو میں اس کے پاس پہنچ جاتا ہوں، اس سے زیادہ تیزی سے آتا ہوں۔\""}],[6863,"(سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے ، کہا : رسول اللہ صلی اللہ علیہ وسلم مکہ کے ایک راستے پر چلے جا رہے تھے کہ آپ کا ایک پہاڑ کے قریب سے گزر ہوا جس کو جمدان کہا جاتا ہے ، آپ نے فرمایا : \" چلتے رہو ، یہ جُمدان ہے ۔ مفردون 0لوگوں سے الگ ہو کر تنہا ہو جانے والے ) بازی لے گئے ۔ \" لوگوں نے پوچھا : اللہ کے رسول! مفردون سے کیا مراد ہے؟ فرمایا : \" کثرت سے اللہ کو یاد کرنے والے ( مرد ) اور اللہ کو یاد کرنے والی ( عورتیں ۔)","",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، کہا: رسول اللہ صلی اللہ علیہ وسلم مکہ کے ایک راستے پر چلے جا رہے تھے کہ آپ کا ایک پہاڑ کے قریب سے گزر ہوا جس کو جمدان کہا جاتا ہے، آپ نے فرمایا: \"چلتے رہو، یہ جُمدان ہے۔ مفردون 0لوگوں سے الگ ہو کر تنہا ہو جانے والے) بازی لے گئے۔\" لوگوں نے پوچھا: اللہ کے رسول! مفردون سے کیا مراد ہے؟ فرمایا: \"کثرت سے اللہ کو یاد کرنے والے (مرد) اور اللہ کو یاد کرنے والی (عورتیں۔)\""}],[6864,"عمرو ناقد ، زُہیر بن حرب اور ابن ابی عمر نے ہمیں سفیان سے حدیث بیان کی ۔ ۔ الفاظ عمرو کے ہیں ۔ ۔ انہوں نے کہا : ہمیں سفیان بن عیینہ نے ابوزناد سے حدیث بیان کی ، انہوں نے اعرج سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ تعالی کے ننانوے نام ہیں ، جس نے ان کی حفاظت کی وہ جنت میں داخل ہو جائے گا اور اللہ وتر ( طاق ) ہے ، وتر کو پسند کرتا ہے ۔ \" اور ابن ابی عمر کی روایت میں ہے : \" جس نے ان کو شمار کیا ۔","",{"u2":"عمرو ناقد، زُہیر بن حرب اور ابن ابی عمر نے ہمیں سفیان سے حدیث بیان کی۔۔ الفاظ عمرو کے ہیں۔۔ انہوں نے کہا: ہمیں سفیان بن عیینہ نے ابوزناد سے حدیث بیان کی، انہوں نے اعرج سے، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ کے ننانوے نام ہیں، جس نے ان کی حفاظت کی وہ جنت میں داخل ہو جائے گا اور اللہ وتر (طاق) ہے، وتر کو پسند کرتا ہے۔\" اور ابن ابی عمر کی روایت میں ہے: \" جس نے ان کو شمار کیا۔\""}],[6865,"معمر نے ہمیں ایوب سے خبر دی ، انہوں نے ابن سیرین سے ، انہوں نے ابوہریرہ رضی اللہ عنہ سے ، نیز ( ایوب نے ) ہمام بن منبہ سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" اللہ تعالی کے ننانوے ، ایک کم سو نام ہیں ، جس نے ان ( سب ) کو شمار کیا وہ جنت میں داخل ہو گا ۔ \"\" اور ہمام نے ابوہریرہ رضی اللہ عنہ سے مزید یہ بیان کیا \"\" بےشک وہ ( اللہ ) طاق ہے ، طاق ہی کو پسند کرتا ہے ۔","",{"u2":"معمر نے ہمیں ایوب سے خبر دی، انہوں نے ابن سیرین سے، انہوں نے ابوہریرہ رضی اللہ عنہ سے، نیز (ایوب نے) ہمام بن منبہ سے، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ کے ننانوے، ایک کم سو نام ہیں، جس نے ان (سب) کو شمار کیا وہ جنت میں داخل ہو گا۔\"\nاور ہمام نے ابوہریرہ رضی اللہ عنہ سے مزید یہ بیان کیا \"بےشک وہ (اللہ) طاق ہے، طاق ہی کو پسند کرتا ہے۔\""}],[6866,"عبدالعزیز بن صُہیب نے سیدنا انس رضی اللہ عنہ سے روایت کی ، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جب تک تم میں سے کوئی شخص دعا کرے تو قطعیت کے ساتھ ( اصرار کرتے ہوئے ) دعا کرے اور یہ نہ کہے : اے اللہ! اگر تو چاہے تو مجھے دے دے ، کیونکہ اللہ کو مجبور کرنے والا کوئی نہیں ہے ۔","",{"u2":") عبدالعزیز بن صُہیب نے حضرت انس رضی اللہ عنہ سے روایت کی، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تک تم میں سے کوئی شخص دعا کرے تو قطعیت کے ساتھ (اصرار کرتے ہوئے) دعا کرے اور یہ نہ کہے: اے اللہ! اگر تو چاہے تو مجھے دے دے، کیونکہ اللہ کو مجبور کرنے والا کوئی نہیں ہے۔\""}],[6867,"علاء کے والد ( عبدالرحمٰن ) نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جب تم میں سے کوئی شخص دعا کرے تو یہ نہ کہے : اے اللہ! اگر تو چاہے تو مجھے بخش دے ، بلکہ وہ پختگی اور اصرار سے سوال کرے اور بڑی رغبت کا اظہار کرے ، کیونکہ دینے کے لیے اللہ تعالی کے لیے کوئی چیز بڑی نہیں ہے ۔","",{"u2":"علاء کے والد (عبدالرحمٰن) نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی شخص دعا کرے تو یہ نہ کہے: اے اللہ! اگر تو چاہے تو مجھے بخش دے، بلکہ وہ پختگی اور اصرار سے سوال کرے اور بڑی رغبت کا اظہار کرے، کیونکہ دینے کے لیے اللہ تعالیٰ کے لیے کوئی چیز بڑی نہیں ہے۔\""}],[6868,"عطاء بن میناء نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تم میں سے کوئی شخص اس طرح نہ کہے : اے اللہ! اگر تو چاہے تو مجھے بخش دے ، اے اللہ! اگر تو چاہے تو مجھ پر رحم فرما ۔ وہ دعا میں پختگی اور قطعیت سے کام لے کیونکہ اللہ جو چاہے وہی کرتا ہے ، کوئی نہیں جو اسے مجبور کر سکے ۔","",{"u2":"عطاء بن میناء نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کوئی شخص اس طرح نہ کہے: اے اللہ! اگر تو چاہے تو مجھے بخش دے، اے اللہ! اگر تو چاہے تو مجھ پر رحم فرما۔ وہ دعا میں پختگی اور قطعیت سے کام لے کیونکہ اللہ جو چاہے وہی کرتا ہے، کوئی نہیں جو اسے مجبور کر سکے۔\""}],[6869,"عبدالعزیز نے سیدنا انس رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تم میں سے کوئی شخص کسی نقصان ( مصیبت ) کی وجہ سے ، جو اس پر نازل ہو ، موت کی تمنا نہ کرے ۔ اگر اسنے لامحالہ موت مانگنی بھی ہو تو یوں کہے : اے اللہ! مجھے اس وقت تک زندہ رکھ جب تک زندگی میرے لیے بہتر ہو اور مجھے وفات دے جب موت میرے لیے بہتر ہو ۔","",{"u2":"عبدالعزیز نے حضرت انس رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کوئی شخص کسی نقصان (مصیبت) کی وجہ سے، جو اس پر نازل ہو، موت کی تمنا نہ کرے۔ اگر اسنے لامحالہ موت مانگنی بھی ہو تو یوں کہے: اے اللہ! مجھے اس وقت تک زندہ رکھ جب تک زندگی میرے لیے بہتر ہو اور مجھے وفات دے جب موت میرے لیے بہتر ہو۔\""}],[6870,"ثابت نے سیدنا انس رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی ، مگر انہوں نے کہا : \" کسی نقصان کی وجہ سے جو اسے پہنچے ۔ \" ( نازل ہو نہیں کہا ۔)","",{"u2":"ثابت نے حضرت انس رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی، مگر انہوں نے کہا: \"کسی نقصان کی وجہ سے جو اسے پہنچے۔\" (نازل ہو نہیں کہا۔)"}],[6871,"عاصم نے ہمیں نضر بن انس سے حدیث بیان کی کہ سیدنا انس رضی اللہ عنہ ان دنوں زندہ تھے ۔ ( نضر نے ) کہا : انس رضی اللہ عنہ نے کہا : اگر نبی صلی اللہ علیہ وسلم نے فرمایا نہ ہوتا : \" تم میں سے کوئی شخص موت کی تمنا نہ کرے \" تو میں موت کی تمنا کرتا ۔","",{"u2":"عاصم نے ہمیں نضر بن انس سے حدیث بیان کی کہ حضرت انس رضی اللہ عنہ ان دنوں زندہ تھے۔ (نضر نے) کہا: انس رضی اللہ عنہ نے کہا: اگر نبی صلی اللہ علیہ وسلم نے فرمایا نہ ہوتا: \"تم میں سے کوئی شخص موت کی تمنا نہ کرے\" تو میں موت کی تمنا کرتا۔"}],[6872,"عبداللہ بن ادریس نے اسماعیل بن ابی خالد سے ، انہوں نے قیس بن ابی حازم سے روایت کی کہ انہوں نے کہا : ہم سیدنا خباب رضی اللہ عنہ کے پاس گئے ، اس وقت ان کے پیٹ پر ( علاج کے لئے ) سات جگہ ( تپتی ہوئی دھات سے ) داغ لگائے گئے تھے ۔ انہوں نے کہا : اگر یہ نہ ہوتا کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں موت کی دعا سے منع فرمایا تھا ، تو میں اس ( موت ) کی دعا کرتا ۔","",{"u2":"عبداللہ بن ادریس نے اسماعیل بن ابی خالد سے، انہوں نے قیس بن ابی حازم سے روایت کی کہ انہوں نے کہا: ہم حضرت خباب رضی اللہ عنہ کے پاس گئے، اس وقت ان کے پیٹ پر (علاج کے لئے) سات جگہ (تپتی ہوئی دھات سے) داغ لگائے گئے تھے۔ انہوں نے کہا: اگر یہ نہ ہوتا کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں موت کی دعا سے منع فرمایا تھا، تو میں اس (موت) کی دعا کرتا۔"}],[6873,"سفیان بن عیینہ ، جریر بن عبدالحمید ، وکیع ، عبداللہ بن نمیر ، معتمر بن سلیمان اور ابواسامہ سب نے اسماعیل سے اسی سند کے ساتھ ( یہی ) روایت کی ۔","",{"u2":"سفیان بن عیینہ، جریر بن عبدالحمید، وکیع، عبداللہ بن نمیر، معتمر بن سلیمان اور ابواسامہ سب نے اسماعیل سے اسی سند کے ساتھ (یہی) روایت کی۔"}],[6874,"معمر نے ہمیں ہمام بن منبہ سے حدیث بیان کی ، کہا : یہ احادیث ہمیں ابوہریرہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے بیان کیں ، انہوں نے کئی احادیث بیان کیں ، ان میں سے یہ ( بھی ) تھی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تم میں سے کوئی شخص ہرگز موت کی تمنا نہ کرے ، نہ موت آنے سے پہلے اس کے لیے دعا کرے کیونکہ جب تم میں سے کوئی شخص مر گیا تو اس کا عمل منقطع ہو گیا ( مزید عمل کی مہلت ختم ہو گئی ) اور مومن کی عمر اس کی بھلائی ہی میں اضافہ کرتی ہے ۔","",{"u2":"معمر نے ہمیں ہمام بن منبہ سے حدیث بیان کی، کہا: یہ احادیث ہمیں ابوہریرہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے بیان کیں، انہوں نے کئی احادیث بیان کیں، ان میں سے یہ (بھی) تھی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کوئی شخص ہرگز موت کی تمنا نہ کرے، نہ موت آنے سے پہلے اس کے لیے دعا کرے کیونکہ جب تم میں سے کوئی شخص مر گیا تو اس کا عمل منقطع ہو گیا (مزید عمل کی مہلت ختم ہو گئی) اور مومن کی عمر اس کی بھلائی ہی میں اضافہ کرتی ہے۔\""}],[6875,"ہمام نے کہا : ہمیں قتادہ نے انس بن مالک رضی اللہ عنہ سے حدیث بیان کی ، انہوں نے سیدنا عبادہ بن صامت رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے فرمایا : \" جو شخص اللہ سے ملنے کو محبوب رکھے ، اللہ اس سے ملنے کو محبوب رکھتا ہے اور جو اللہ سے ملنے کو ناپسند کرے ، اللہ بھی اس سے ملنے کو ناپسند کرتا ہے ۔","",{"u2":"ہمام نے کہا: ہمیں قتادہ نے انس بن مالک رضی اللہ عنہ سے حدیث بیان کی، انہوں نے حضرت عبادہ بن صامت رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص اللہ سے ملنے کو محبوب رکھے، اللہ اس سے ملنے کو محبوب رکھتا ہے اور جو اللہ سے ملنے کو ناپسند کرے، اللہ بھی اس سے ملنے کو ناپسند کرتا ہے۔\""}],[6876,"شعبہ نے قتادہ سے روایت کی ، انہوں نے کہا : میں نے سیدنا انس بن مالک رضی اللہ عنہ کو سیدنا عبادہ بن صامت رضی اللہ عنہ سے حدیث بیان کرتے ہوئے سنا ، انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی ۔","",{"u2":"شعبہ نے قتادہ سے روایت کی، انہوں نے کہا: میں نے حضرت انس بن مالک رضی اللہ عنہ کو حضرت عبادہ بن صامت رضی اللہ عنہ سے حدیث بیان کرتے ہوئے سنا، انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی۔"}],[6877,"خالد بن حارث بجیمی نے کہا : ہمیں سعید نے قتادہ سے حدیث بیان کی ، انہوں نے زُرارہ سے ، انہوں نے سعد بن ہشام سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جو شخص اللہ سے ملاقات کو پسند کرے ، اللہ اس سے ملاقات کو پسند فرماتا ہے اور جو شخص اللہ سے ملاقات کو ناپسند کرے ، اللہ اس سے ملاقات کو ناپسند کرتا ہے ۔ \" میں نے کہا : اللہ کے نبی! کیا اس سے موت کی ناپسندیدگی مراد ہے؟ ہم میں سے ہر شخص ( طبعا ) موت کو ناپسند کرتا ہے ، تو آپ صلی اللہ علیہ وسلم نے فرمایا : \" یہ بات نہیں ہے ، لیکن جب مومن کو اللہ کی رحمت ، اس کی رضامندی اور جنت کی بشارت دی جاتی ہے تو وہ اللہ سے ملاقات کو پسند کرتا ہے اور کافر کو جب اللہ کے عذاب اور اس کی ناراضی کی خبر دی جاتی ہے تو وہ اللہ سے ملاقات کو ناپسند کرتا ہے اور اللہ بھی اس ( ناشکرے اور متکبر ) سے ملاقات کو ناپسند کرتا ہے ۔","",{"u2":"خالد بن حارث بجیمی نے کہا: ہمیں سعید نے قتادہ سے حدیث بیان کی، انہوں نے زُرارہ سے، انہوں نے سعد بن ہشام سے اور انہوں نے حضرت عائشہ رضی اللہ عنہا سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص اللہ سے ملاقات کو پسند کرے، اللہ اس سے ملاقات کو پسند فرماتا ہے اور جو شخص اللہ سے ملاقات کو ناپسند کرے، اللہ اس سے ملاقات کو ناپسند کرتا ہے۔\" میں نے کہا: اللہ کے نبی! کیا اس سے موت کی ناپسندیدگی مراد ہے؟ ہم میں سے ہر شخص (طبعا) موت کو ناپسند کرتا ہے، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ بات نہیں ہے، لیکن جب مومن کو اللہ کی رحمت، اس کی رضامندی اور جنت کی بشارت دی جاتی ہے تو وہ اللہ سے ملاقات کو پسند کرتا ہے اور کافر کو جب اللہ کے عذاب اور اس کی ناراضی کی خبر دی جاتی ہے تو وہ اللہ سے ملاقات کو ناپسند کرتا ہے اور اللہ بھی اس (ناشکرے اور متکبر) سے ملاقات کو ناپسند کرتا ہے۔\""}],[6878,"محمد بن بکر نے کہا : ہمیں سعید نے قتادہ سے اسی سند کے ساتھ حدیث بیان کی ۔","",{"u2":"محمد بن بکر نے کہا: ہمیں سعید نے قتادہ سے اسی سند کے ساتھ حدیث بیان کی۔"}],[6879,"علی بن مسہر نے زکریا سے ، انہوں نے شعبی سے ، انہوں نے شریح بن بانی سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جو شخص اللہ سے ملاقات کو پسند کرتا ہے ، اللہ اس سے ملاقات کو پسند کرتا ہے اور جو شخص اللہ سے ملاقات کو ناپسند کرتا ہے ، اللہ بھی اس سے ملاقات کو ناپسند کرتا ہے اور موت اللہ کی ملاقات سے پہلے ہے ۔ \" ( ملاقات کا معاملہ اس کے بعد آئے گا ۔)","",{"u2":"علی بن مسہر نے زکریا سے، انہوں نے شعبی سے، انہوں نے شریح بن بانی سے اور انہوں نے حضرت عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص اللہ سے ملاقات کو پسند کرتا ہے، اللہ اس سے ملاقات کو پسند کرتا ہے اور جو شخص اللہ سے ملاقات کو ناپسند کرتا ہے، اللہ بھی اس سے ملاقات کو ناپسند کرتا ہے اور موت اللہ کی ملاقات سے پہلے ہے۔\" (ملاقات کا معاملہ اس کے بعد آئے گا۔)"}],[6880,"عیسی بن یونس نے کہا : ہمیں زکریا نے عامر ( شعبی ) سے حدیث بیان کی ، انہوں نے کہا : مجھے شُریح بن بانی نے حدیث بیان کی کہ سیدہ عائشہ رضی اللہ عنہا نے انہیں بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ، اسی ( گزشتہ روایت ) کے مانند ۔","",{"u2":"عیسیٰ بن یونس نے کہا: ہمیں زکریا نے عامر (شعبی) سے حدیث بیان کی، انہوں نے کہا: مجھے شُریح بن بانی نے حدیث بیان کی کہ حضرت عائشہ رضی اللہ عنہا نے انہیں بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا، اسی (گزشتہ روایت) کے مانند۔"}],[6881,"عبثر نے مطرف سے ، انہوں نے عامر سے ، انہوں نے شریح بن ہانی سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جو شخص اللہ سے ملاقات کو پسند کرے ، اللہ اس سے ملاقات کو پسند کرتا ہے اور جو اللہ سے ملاقات کو ناپسند کرے ، اللہ اس سے ملاقات کو ناپسند کرتا ہے ۔ ( شریح بن ہانی نے ) کہا : میں سیدہ عائشہ رضی اللہ عنہا کے پاس حاضر ہوا اور عرض کی : ام المومنین! میں نے سیدنا ابوہریرہ رضی اللہ عنہ کو رسول اللہ صلی اللہ علیہ وسلم سے ایک حدیث بیان کرتے ہوئے سنا ، اگر وہ اسی طرح ہے ( جس طرح وہ بیان کرتے ہیں ) تو ہم ہلاک ہو گئے ۔ تو انہوں ( عائشہ رضی اللہ عنہا ) نے فرمایا : ہلاک ہونے والا واقعی وہی ہے جو رسول اللہ صلی اللہ علیہ وسلم کے قول سے ہلاک ہوا ، ( بتاؤ ) وہ کیا حدیث ہے؟ ( میں نے عرض کی : ) انہوں نے کہا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جو شخص اللہ سے ملاقات کو پسند کرتا ہے اللہ بھی اس سے ملاقات کو پسند کرتا ہے اور جو شخص اللہ سے ملاقات کو ناپسند کرتا ہے ، اللہ بھی اس سے ملاقات کو ناپسند کرتا ہے \" اور ہم میں ایسا کوئی نہیں جو موت کو ناپسند نہ کرتا ہو ، تو سیدہ عائشہ رضی اللہ عنہا نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے یہی فرمایا تھا ، لیکن ( مفہوم کے اعتبار سے ) جس طرف تم گئے ہو وہ بات اس طرح نہیں بلکہ ( وہ اس طرح ہے کہ ) جب نگاہ اوپر کی طرف اٹھ جاتی ہے اور سینے میں سانس اکھڑ رہی ہوتی ہے اور جلد پر رونگٹے کھڑے ہو جاتے ہیں اور انگلیاں ٹیڑھی ہو کر اکڑ جاتی ہیں تو اس وقت جو اللہ سے ملنے کو پسند کرتا ہے ، اللہ بھی اس سے ملنا پسند کرتا ہے اور جو ( اس وقت ) اللہ سے ملاقات کو ناپسند کرتا ہے ، اللہ بھی اس سے ملنا ناپسند کرتا ہے ۔","",{"u2":"عبثر نے مطرف سے، انہوں نے عامر سے، انہوں نے شریح بن ہانی سے اور انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \" جو شخص اللہ سے ملاقات کو پسند کرے، اللہ اس سے ملاقات کو پسند کرتا ہے اور جو اللہ سے ملاقات کو ناپسند کرے، اللہ اس سے ملاقات کو ناپسند کرتا ہے۔ (شریح بن ہانی نے) کہا: میں حضرت عائشہ رضی اللہ عنہا کے پاس حاضر ہوا اور عرض کی: ام المومنین! میں نے حضرت ابوہریرہ رضی اللہ عنہ کو رسول اللہ صلی اللہ علیہ وسلم سے ایک حدیث بیان کرتے ہوئے سنا، اگر وہ اسی طرح ہے(جس طرح وہ بیان کرتے ہیں) تو ہم ہلاک ہو گئے۔ تو انہوں (عائشہ رضی اللہ عنہا) نے فرمایا: ہلاک ہونے والا واقعی وہی ہے جو رسول اللہ صلی اللہ علیہ وسلم کے قول سے ہلاک ہوا، (بتاؤ) وہ کیا حدیث ہے؟ (میں نے عرض کی:) انہوں نے کہا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص اللہ سے ملاقات کو پسند کرتا ہے اللہ بھی اس سے ملاقات کو پسند کرتا ہے اور جو شخص اللہ سے ملاقات کو ناپسند کرتا ہے، اللہ بھی اس سے ملاقات کو ناپسند کرتا ہے\" اور ہم میں ایسا کوئی نہیں جو موت کو ناپسند نہ کرتا ہو، تو حضرت عائشہ رضی اللہ عنہا نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے یہی فرمایا تھا، لیکن (مفہوم کے اعتبار سے) جس طرف تم گئے ہو وہ بات اس طرح نہیں بلکہ (وہ اس طرح ہے کہ) جب نگاہ اوپر کی طرف اٹھ جاتی ہے اور سینے میں سانس اکھڑ رہی ہوتی ہے اور جلد پر رونگٹے کھڑے ہو جاتے ہیں اور انگلیاں ٹیڑھی ہو کر اکڑ جاتی ہیں تو اس وقت جو اللہ سے ملنے کو پسند کرتا ہے، اللہ بھی اس سے ملنا پسند کرتا ہے اور جو (اس وقت) اللہ سے ملاقات کو ناپسند کرتا ہے، اللہ بھی اس سے ملنا ناپسند کرتا ہے۔"}],[6882,"جریر نے مطرف سے اسی سند کے ساتھ عبثر کی حدیث کے مانند خبر دی ۔","",{"u2":"جریر نے مطرف سے اسی سند کے ساتھ عبثر کی حدیث کے مانند خبر دی۔"}],[6883,"سیدنا ابوموسی اشعری رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" جو شخص اللہ سے ملاقات کو پسند کرے ، اللہ بھی اس سے ملاقات کو پسند کرتا ہے اور جو شخص اللہ سے ملاقات کو ناپسند کرے ، اللہ بھی اس سے ملنے کو ناپسند کرتا ہے ۔","",{"u2":"حضرت ابوموسیٰ اشعری رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا: \"جو شخص اللہ سے ملاقات کو پسند کرے، اللہ بھی اس سے ملاقات کو پسند کرتا ہے اور جو شخص اللہ سے ملاقات کو ناپسند کرے، اللہ بھی اس سے ملنے کو ناپسند کرتا ہے۔\""}],[6884,"یزید بن اصم نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ تعالی فرماتا ہے : میرا بندہ میرے بارے میں جو گمان کرتا ہے ، میں ( اس کو پورا کرنے کے لیے ) اس کے پاس ہوتا ہوں اور جب وہ مجھے پکارتا ہے تو میں اس کے ساتھ ہوتا ہوں ۔","",{"u2":"یزید بن اصم نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ فرماتا ہے: میرا بندہ میرے بارے میں جو گمان کرتا ہے، میں (اس کو پورا کرنے کے لیے) اس کے پاس ہوتا ہوں اور جب وہ مجھے پکارتا ہے تو میں اس کے ساتھ ہوتا ہوں۔\""}],[6885,"یحیی بن سعید اور ابن ابی عدی نے سلیمان تیمی سے ، انہوں نے سیدنا انس بن مالک رضی اللہ عنہ سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" اللہ عزوجل فرماتا ہے : جب میرا بندہ ایک بالشت میرے قریب آتا ہے تو میں ایک ہاتھ اس کے قریب آتا ہوں اور جب وہ ایک ہاتھ میرے قریب آتا ہے تو میں دونوں ہاتھوں کی لمبائی کے برابر اس کے قریب آتا ہوں اور جب وہ چل کر میرے پاس آتا ہے تو میں دوڑ کر اس کے پاس جاتا ہوں ۔","",{"u2":"یحییٰ بن سعید اور ابن ابی عدی نے سلیمان تیمی سے، انہوں نے حضرت انس بن مالک رضی اللہ عنہ سے، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا: \"اللہ عزوجل فرماتا ہے: جب میرا بندہ ایک بالشت میرے قریب آتا ہے تو میں ایک ہاتھ اس کے قریب آتا ہوں اور جب وہ ایک ہاتھ میرے قریب آتا ہے تو میں دونوں ہاتھوں کی لمبائی کے برابر اس کے قریب آتا ہوں اور جب وہ چل کر میرے پاس آتا ہے تو میں دوڑ کر اس کے پاس جاتا ہوں۔\""}],[6886,"معتمر نے اپنے والد ( سلیمان تیمی ) سے اسی سند کے ساتھ حدیث بیان کی اور \" جب وہ چل کر میرے پاس آتا ہے تو میں دوڑ کر اس کے پاس جاتا ہوں \" ذکر نہیں کیا ۔","",{"u2":"معتمر نے اپنے والد (سلیمان تیمی) سے اسی سند کے ساتھ حدیث بیان کی اور \"جب وہ چل کر میرے پاس آتا ہے تو میں دوڑ کر اس کے پاس جاتا ہوں\" ذکر نہیں کیا۔"}],[6887,"ابوصالح نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ عزوجل فرماتا ہے : میرا بندہ میرے بارے میں جو گمان کرتا ہے تو میں ( اس کو پورا کرنے کے لیے ) اس کے پاس ہوتا ہوں اور جب وہ مجھے یاد کرتا ہے تو میں اس کے ساتھ ہوتا ہوں ، اگر وہ مجھے اپنے دل میں یاد کرتا ہے تو میں اسے اپنے دل میں یاد کرتا ہوں ۔ اگر وہ مجھے کسی مجلس میں یاد کرتا ہے تو میں ان لوگوں کی مجلس سے بہتر مجلس میں اس کو یاد کرتا ہوں اور اگر وہ ایک بالشت میرے قریب ہوتا ہے تو میں ایک ہاتھ اس کے قریب ہو جاتا ہوں ، اگر وہ ایک ہاتھ میرے قریب ہوتا ہے تو میں پھیلے ہوئے دونوں ہاتھوں کی لمبائی جتنا ( فاصلہ ) اس کے قریب ہو جاتا ہوں اور اگر وہ چل کر میری طرف آتا ہے تو میں دوڑ کر اس کے پاس آتا ہوں ۔","",{"u2":"ابوصالح نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ عزوجل فرماتا ہے: میرا بندہ میرے بارے میں جو گمان کرتا ہے تو میں (اس کو پورا کرنے کے لیے) اس کے پاس ہوتا ہوں اور جب وہ مجھے یاد کرتا ہے تو میں اس کے ساتھ ہوتا ہوں، اگر وہ مجھے اپنے دل میں یاد کرتا ہے تو میں اسے اپنے دل میں یاد کرتا ہوں۔ اگر وہ مجھے کسی مجلس میں یاد کرتا ہے تو میں ان لوگوں کی مجلس سے بہتر مجلس میں اس کو یاد کرتا ہوں اور اگر وہ ایک بالشت میرے قریب ہوتا ہے تو میں ایک ہاتھ اس کے قریب ہو جاتا ہوں، اگر وہ ایک ہاتھ میرے قریب ہوتا ہے تو میں پھیلے ہوئے دونوں ہاتھوں کی لمبائی جتنا (فاصلہ) اس کے قریب ہو جاتا ہوں اور اگر وہ چل کر میری طرف آتا ہے تو میں دوڑ کر اس کے پاس آتا ہوں۔\""}],[6888,"وکیع نے کہا : ہمیں اعمش نے معرور بن سوید سے حدیث بیان کی ، انہوں نے سیدنا ابوزر رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" اللہ عزوجل فرماتا ہے : جو شخص ایک نیکی لے کر آتا ہے ، اسے اس جیسی دس ملتی ہیں اور میں بڑھا ( بھی ) دیتا ہوں اور جو شخص برائی لے کر آتا ہے تو اس کا بدلہ اس جیسی ایک برائی ہے یا ( چاہوں تو ) معاف کر دیتا ہوں ، جو ایک بالشت میرے قریب ہوتا ہے تو میں ایک ہاتھ اس کے قریب ہو جاتا ہوں اور جو ایک ہاتھ میرے قریب ہوتا ہے تو میں دو ہاتھوں کےپھیلاؤ جتنا اس کے قریب ہو جاتا ہوں اور جو میرے پاس چلتا ہوا آتا ہے ، میں اس کے پاس دوڑتا ہوا جاتا ہوں اور جو مجھ سے پوری زمین کی وسعت بھر گناہوں کے ساتھ ملاقات کرتا ہے ( اور ) میرے ساتھ کسی چیز کو شریک نہیں ٹھہراتا ، میں اتنی ہی مغفرت کے ساتھ اس سے ملاقات کرتا ہوں ۔ \"\" ( امام مسلم کے شاگرد ) ابراہیم نے کہا : ہم سے حسب بن بشر نے ، ان کو وکیع نے یہی حدیث بیان کی ۔"],[6889,"وکیع نے کہا : ہمیں اعمش نے معرور بن سوید سے حدیث بیان کی ، انہوں نے سیدنا ابوزر رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" اللہ عزوجل فرماتا ہے : جو شخص ایک نیکی لے کر آتا ہے ، اسے اس جیسی دس ملتی ہیں اور میں بڑھا ( بھی ) دیتا ہوں اور جو شخص برائی لے کر آتا ہے تو اس کا بدلہ اس جیسی ایک برائی ہے یا ( چاہوں تو ) معاف کر دیتا ہوں ، جو ایک بالشت میرے قریب ہوتا ہے تو میں ایک ہاتھ اس کے قریب ہو جاتا ہوں اور جو ایک ہاتھ میرے قریب ہوتا ہے تو میں دو ہاتھوں کےپھیلاؤ جتنا اس کے قریب ہو جاتا ہوں اور جو میرے پاس چلتا ہوا آتا ہے ، میں اس کے پاس دوڑتا ہوا جاتا ہوں اور جو مجھ سے پوری زمین کی وسعت بھر گناہوں کے ساتھ ملاقات کرتا ہے ( اور ) میرے ساتھ کسی چیز کو شریک نہیں ٹھہراتا ، میں اتنی ہی مغفرت کے ساتھ اس سے ملاقات کرتا ہوں ۔ \"\" ( امام مسلم کے شاگرد ) ابراہیم نے کہا : ہم سے حسب بن بشر نے ، ان کو وکیع نے یہی حدیث بیان کی ۔"],[6890,"ابومعاویہ نے اعمش سے اسی سند کے ساتھ اسی کے مانند روایت بیان کی ، مگر انہوں نے کہا : \" اس کے لیے اس جیسی دس نیکیاں ملتی ہیں ، یا میں ( اس سے بھی ) زیادہ دیتا ہوں ۔","",{"u2":"ابومعاویہ نے اعمش سے اسی سند کے ساتھ اسی کے مانند روایت بیان کی، مگر انہوں نے کہا: \"اس کے لیے اس جیسی دس نیکیاں ملتی ہیں، یا میں (اس سے بھی) زیادہ دیتا ہوں۔\""}],[6891,"محمد بن ابوعدی نے حمید سے ، انہوں نے ثابت سے اور انہوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے مسلمانوں میں سے ایک ایسے شخص کی عیادت کی جو لاغر ہو کر چوزے کی طرح ہو گیا تھا ، رسول اللہ صلی اللہ علیہ وسلم نے اس سے فرمایا : \" کیا تم اللہ تعالی سے کسی چیز کی دعا کرتے تھے یا اس سے کچھ مانگتے تھے؟ \" اس نے کہا : جی ہاں ، میں کہتا تھا : اے اللہ! تو مجھے آخرت میں جو سزا دینے والا ہے ابھی دنیا ہی میں دے دے ۔ اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ پاک ہے! تم میں اس کی طاقت نہیں ہے ۔ ۔ یا ( فرمایا : ) تم اس کی استطاعت نہیں رکھتے ۔ تم نے یہ کیوں نہ کہا : اے اللہ! ہمیں دنیا میں بھی اچھائی عطا فرما اور آخرت میں بھی اچھائی عطا فرما اور ہمیں آگ کے عذاب سے بچا لے ۔ \" پھر آپ صلی اللہ علیہ وسلم کے لیے اللہ سے دعا فرمائی تو اس نے اس شخص کو شفا عطا فرما دی ۔","",{"u2":"محمد بن ابوعدی نے حمید سے، انہوں نے ثابت سے اور انہوں نے حضرت انس بن مالک رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے مسلمانوں میں سے ایک ایسے شخص کی عیادت کی جو لاغر ہو کر چوزے کی طرح ہو گیا تھا، رسول اللہ صلی اللہ علیہ وسلم نے اس سے فرمایا: \"کیا تم اللہ تعالیٰ سے کسی چیز کی دعا کرتے تھے یا اس سے کچھ مانگتے تھے؟\" اس نے کہا: جی ہاں، میں کہتا تھا: اے اللہ! تو مجھے آخرت میں جو سزا دینے والا ہے ابھی دنیا ہی میں دے دے۔ اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ پاک ہے! تم میں اس کی طاقت نہیں ہے۔۔ یا (فرمایا:) تم اس کی استطاعت نہیں رکھتے۔ تم نے یہ کیوں نہ کہا: اے اللہ! ہمیں دنیا میں بھی اچھائی عطا فرما اور آخرت میں بھی اچھائی عطا فرما اور ہمیں آگ کے عذاب سے بچا لے۔\" پھر آپ صلی اللہ علیہ وسلم کے لیے اللہ سے دعا فرمائی تو اس نے اس شخص کو شفا عطا فرما دی۔"}],[6892,"خالد بن حارث نے کہا : ہمیں حمید نے اسی سند کے ساتھ دعا کے ان الفاظ تک حدیث بیان کی : \" ہمیں دوزخ کے عذاب سے بچا \" اور اس سے اضافی بات بیان نہیں کی ۔","",{"u2":"خالد بن حارث نے کہا: ہمیں حمید نے اسی سند کے ساتھ دعا کے ان الفاظ تک حدیث بیان کی: \"ہمیں دوزخ کے عذاب سے بچا\" اور اس سے اضافی بات بیان نہیں کی۔"}],[6893,"حماد نے کہا : ثابت نے ہمیں سیدنا انس رضی اللہ عنہ سے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم اپنے صحابہ میں سے ایک شخص کی عیادت کے لیے تشریف لےگئے ، وہ چوزے کی طرح ( لاغر ) ہو گیا تھا ، اس کے بعد حمید کی حدیث کے ہم معنی ہے ، مگر انہوں نے اس طرح کہا : \" تم میں اللہ کا عذاب برداشت کرنے کی طاقت نہیں \" انہوں نے یہ بیان نہیں کیا کہ آپ صلی اللہ علیہ وسلم نے اس کے لیے اللہ سے دعا کی تو اس نے اس شخص کو شفا عطا فرما دی ۔","",{"u2":"حماد نے کہا: ثابت نے ہمیں حضرت انس رضی اللہ عنہ سے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم اپنے صحابہ میں سے ایک شخص کی عیادت کے لیے تشریف لےگئے، وہ چوزے کی طرح (لاغر) ہو گیا تھا، اس کے بعد حمید کی حدیث کے ہم معنی ہے، مگر انہوں نے اس طرح کہا: \"تم میں اللہ کا عذاب برداشت کرنے کی طاقت نہیں\" انہوں نے یہ بیان نہیں کیا کہ آپ صلی اللہ علیہ وسلم نے اس کے لیے اللہ سے دعا کی تو اس نے اس شخص کو شفا عطا فرما دی۔"}],[6894,"قتادہ نے انس رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے یہی حدیث بیان کی ۔","",{"u2":") قتادہ نے انس رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے یہی حدیث بیان کی۔"}],[6895,"سیدنا ابوہریرہ رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" اللہ تبارک و تعالی کے کچھ فرشتے ہیں جو ( اللہ کی زمین میں ) چکر لگاتے رہتے ہیں ، وہ اللہ کے ذکر کی مجلسیں تلاش کرتے ہیں ، جب وہ کوئی ایسی مجلس پاتے ہیں جس میں ( اللہ کا ) ذکر ہوتا ہے تو ان کے ساتھ بیٹھ جاتے ہیں ، وہ ایک دوسرے کو اپنے پروں سے اس طرح ڈھانپ لیتے ہیں کہ اپنے اور دنیا کے آسمان کے درمیان ( کی وسعت کو ) بھر دیتے ہیں ۔ جب ( مجلس میں شریک ہونے والے ) لوگ منتشر ہو جاتے ہیں تو یہ ( فرشتے ) بھی اوپر کی طرف جاتے ہیں اور آسمان پر چلے جاتے ہیں ، کہا : تو اللہ عزوجل ان سے پوچھتا ہے ، حالانکہ وہ ان کے بارے میں سب سے زیادہ جاننے والا ہے : تم کہاں سے آئے ہو؟ وہ کہتے ہیں : ہم زمین میں ( رہنے والے ) تیرے بندوں کی طرف سے ( ہو کر ) آئے ہیں جو تیری پاکیزگی بیان کر رہے تھے ، تیزی بڑائی کہہ رہے تھے اور صرف اور صرف تیرے ہی معبود ہونے کا اقرار کر رہے تھے اور تیری حمد و ثنا کر رہے تھے اور تجھی سے مانگ رہے تھے ، فرمایا : وہ مجھ سے کیا مانگ رہے تھے؟ انہوں نے کہا : وہ آپ سے آپ کی جنت مانگ رہے تھے ۔ فرمایا : کیا انہوں نے میری جنت دیکھی ہے؟ انہوں نے کہا : پروردگار! ( انہوں نے ) نہیں ( دیکھی ) ، فرمایا : اگر انہوں نے میری جنت دیکھی ہوتی کیا ہوتا! ( کس الحاح و زاری سے مانگتے! ) وہ کہتے ہیں : اور وہ تیری پناہ مانگ رہے تھے ، فرمایا : وہ کس چیز سے میری پناہ مانگ رہے تھے؟ انہوں نے کہا : تیری آگ ( جہنم ) سے ، اے رب! فرمایا : کیا انہوں نے میری آگ ( جہنم ) دیکھی ہے؟ انہوں نے کہا : اے رب! نہیں ( دیکھی ) ، فرمایا : اگر وہ میری جہنم دیکھ لیتے تو ( ان کا کیا حال ہوتا! ) وہ کہتے ہیں : وہ تجھ سے گناہوں کی بخشش مانگ رہے تھے ، تو وہ فرماتا ہے : میں نے ان کے گناہ بخش دیے اور انہوں نے جو مانگا میں نے انہیں عطا کر دیا اور انہوں نے جس سے پناہ مانگی میں نے انہیں پناہ دے دی ۔ ( رسول اللہ صلی اللہ علیہ وسلم نے ) فرمایا : وہ ( فرشتے ) کہتے ہیں : پروردگار! ان میں فلاں شخص بھی موجود تھا ، سخت گناہ گار بندہ ، وہاں سے گزرتے ہوئے ان کے ساتھ بیٹھ گیا تھا ۔ ( آپ صلی اللہ علیہ وسلم نے ) فرمایا : تو اللہ ارشاد فرماتا ہے : میں نے اس کو بھی بخش دیا ۔ یہ ایسے لوگ ہیں کہ ان کی وجہ سے ان کے ساتھ بیٹھ جانے والا بھی محروم نہیں رہتا ۔","",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا: \"اللہ تبارک و تعالیٰ کے کچھ فرشتے ہیں جو (اللہ کی زمین میں) چکر لگاتے رہتے ہیں، وہ اللہ کے ذکر کی مجلسیں تلاش کرتے ہیں، جب وہ کوئی ایسی مجلس پاتے ہیں جس میں (اللہ کا) ذکر ہوتا ہے تو ان کے ساتھ بیٹھ جاتے ہیں، وہ ایک دوسرے کو اپنے پروں سے اس طرح ڈھانپ لیتے ہیں کہ اپنے اور دنیا کے آسمان کے درمیان (کی وسعت کو) بھر دیتے ہیں۔ جب (مجلس میں شریک ہونے والے) لوگ منتشر ہو جاتے ہیں تو یہ (فرشتے) بھی اوپر کی طرف جاتے ہیں اور آسمان پر چلے جاتے ہیں، کہا: تو اللہ عزوجل ان سے پوچھتا ہے، حالانکہ وہ ان کے بارے میں سب سے زیادہ جاننے والا ہے: تم کہاں سے آئے ہو؟ وہ کہتے ہیں: ہم زمین میں (رہنے والے) تیرے بندوں کی طرف سے (ہو کر) آئے ہیں جو تیری پاکیزگی بیان کر رہے تھے، تیزی بڑائی کہہ رہے تھے اور صرف اور صرف تیرے ہی معبود ہونے کا اقرار کر رہے تھے اور تیری حمد و ثنا کر رہے تھے اور تجھی سے مانگ رہے تھے، فرمایا: وہ مجھ سے کیا مانگ رہے تھے؟ انہوں نے کہا: وہ آپ سے آپ کی جنت مانگ رہے تھے۔ فرمایا: کیا انہوں نے میری جنت دیکھی ہے؟ انہوں نے کہا: پروردگار! (انہوں نے) نہیں (دیکھی)، فرمایا: اگر انہوں نے میری جنت دیکھی ہوتی کیا ہوتا! (کس الحاح و زاری سے مانگتے!) وہ کہتے ہیں: اور وہ تیری پناہ مانگ رہے تھے، فرمایا: وہ کس چیز سے میری پناہ مانگ رہے تھے؟ انہوں نے کہا: تیری آگ (جہنم) سے، اے رب! فرمایا: کیا انہوں نے میری آگ (جہنم) دیکھی ہے؟ انہوں نے کہا: اے رب! نہیں (دیکھی)، فرمایا: اگر وہ میری جہنم دیکھ لیتے تو (ان کا کیا حال ہوتا!) وہ کہتے ہیں: وہ تجھ سے گناہوں کی بخشش مانگ رہے تھے، تو وہ فرماتا ہے: میں نے ان کے گناہ بخش دیے اور انہوں نے جو مانگا میں نے انہیں عطا کر دیا اور انہوں نے جس سے پناہ مانگی میں نے انہیں پناہ دے دی۔ (رسول اللہ صلی اللہ علیہ وسلم نے) فرمایا: وہ (فرشتے) کہتے ہیں: پروردگار! ان میں فلاں شخص بھی موجود تھا، سخت گناہ گار بندہ، وہاں سے گزرتے ہوئے ان کے ساتھ بیٹھ گیا تھا۔ (آپ صلی اللہ علیہ وسلم نے) فرمایا: تو اللہ ارشاد فرماتا ہے: میں نے اس کو بھی بخش دیا۔ یہ ایسے لوگ ہیں کہ ان کی وجہ سے ان کے ساتھ بیٹھ جانے والا بھی محروم نہیں رہتا۔\""}],[6896,"عبدالعزیز بن صہیب نے کہا : قتادہ نے سیدنا انس رضی اللہ عنہ سے پوچھا کہ رسول اللہ صلی اللہ علیہ وسلم کون سی دعا کثرت سے مانگا کرتے تھے؟ سیدنا انس رضی اللہ عنہ نے کہا : آپ صلی اللہ علیہ وسلم کثرت سے جو دعا مانگا کرتے تھے وہ یہ تھی کہ آپ کہے : \"\" اے اللہ! ہمیں دنیا میں بھی اچھائی عطا فرما ، آخرت میں بھی اچھائی عطا فرما اور ہمیں آگ کے عذاب سے محفوظ رکھ ۔ \"\" کہا : سیدنا انس رضی اللہ عنہ جب کوئی ایک دعا مانگنا چاہتے تو یہی دعا مانگتے اور جب بڑی دعا مانگنا چاہتے تو اس میں یہ دعا بھی مانگتے ۔","",{"u2":") عبدالعزیز بن صہیب نے کہا: قتادہ نے حضرت انس رضی اللہ عنہ سے پوچھا کہ رسول اللہ صلی اللہ علیہ وسلم کون سی دعا کثرت سے مانگا کرتے تھے؟ حضرت انس رضی اللہ عنہ نے کہا: آپ صلی اللہ علیہ وسلم کثرت سے جو دعا مانگا کرتے تھے وہ یہ تھی کہ آپ کہے: \"اے اللہ! ہمیں دنیا میں بھی اچھائی عطا فرما، آخرت میں بھی اچھائی عطا فرما اور ہمیں آگ کے عذاب سے محفوظ رکھ۔\"\nکہا: حضرت انس رضی اللہ عنہ جب کوئی ایک دعا مانگنا چاہتے تو یہی دعا مانگتے اور جب بڑی دعا مانگنا چاہتے تو اس میں یہ دعا بھی مانگتے۔"}],[6897,"ثابت نے سیدنا انس رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم ( دعا فرماتے ہوئے یہ ) کہا کرتے تھے : \" اے ہمارے رب! ہمیں دنیا میں بھی اچھائی عطا فرما اور آخرت میں بھی اچھائی عطا فرما اور ہمیں دوزخ کے عذاب سے بچا ۔","",{"u2":"ثابت نے حضرت انس رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم (دعا فرماتے ہوئے یہ) کہا کرتے تھے: \"اے ہمارے رب! ہمیں دنیا میں بھی اچھائی عطا فرما اور آخرت میں بھی اچھائی عطا فرما اور ہمیں دوزخ کے عذاب سے بچا۔\""}],[6898,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جو شخص دن میں سو مرتبہ : \" لا اله الا لله وحده لا شريك له له الملك وله لحمد وهو على كل شيء قدير \" اللہ کے سوا کوئی عبادت کے لائق نہیں ، وہ اکیلا ہے ، اس کا کوئی شریک نہیں ، ساری بادشاہت اسی کی ہے ، حمد صرف اسی کو سزاوار ہے اور وہی ہر چیز پر قادر ہے \" کہے اس شخص کو دس غلام آزاد کرنے کے برابر اجر ملتا ہے ، اس کے لیے سو نیکیاں لکھی جاتی ہیں ، اس کے سو گناہ مٹا دیے جاتے ہیں اور یہ کلمات شام تک پورا دن شیطان سے اس کی حفاظت کا ذریعہ بن جاتے ہیں اور کوئی شخص اس سے زیادہ افضل عمل نہیں کر سکتا ، سوائے اس شخص کے جو اس سے بھی زیادہ مرتبہ یہی عمل کرے اور جس شخص نے ایک دن میں سو مرتبہ \" سبحان اللہ وبحمده \" کہا تو اس کے تمام گناہ معاف کر دیے جاتے ہیں ، چاہے وہ سمندر کے جھاگ کے برابر ہوں ۔","",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص دن میں سو مرتبہ: \" لا الہ الا للہ وحدہ لا شریک لہ لہ الملک ولہ لحمد وہو علی کل شیء قدیر\" اللہ کے سوا کوئی عبادت کے لائق نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں، ساری بادشاہت اسی کی ہے، حمد صرف اسی کو سزاوار ہے اور وہی ہر چیز پر قادر ہے\" کہے اس شخص کو دس غلام آزاد کرنے کے برابر اجر ملتا ہے، اس کے لیے سو نیکیاں لکھی جاتی ہیں، اس کے سو گناہ مٹا دیے جاتے ہیں اور یہ کلمات شام تک پورا دن شیطان سے اس کی حفاظت کا ذریعہ بن جاتے ہیں اور کوئی شخص اس سے زیادہ افضل عمل نہیں کر سکتا، سوائے اس شخص کے جو اس سے بھی زیادہ مرتبہ یہی عمل کرے اور جس شخص نے ایک دن میں سو مرتبہ \" سبحان اللہ وبحمدہ\" کہا تو اس کے تمام گناہ معاف کر دیے جاتے ہیں، چاہے وہ سمندر کے جھاگ کے برابر ہوں۔\""}],[6899,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ے ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : کوئی شخص جب صبح کرے اور جب شام کرے تو سو بار \" سبحان اللہ وبحمده \" کہے تو قیامت کے روز کوئی شخص اس سے بہتر عمل لے کر نہیں آئے گا ، سوائے اس کے جو اتنی بار ( یہ کلمات ) کہے یا اس سے زیادہ بار کہے ۔","",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ے، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: کوئی شخص جب صبح کرے اور جب شام کرے تو سو بار \" سبحان اللہ وبحمدہ\" کہے تو قیامت کے روز کوئی شخص اس سے بہتر عمل لے کر نہیں آئے گا، سوائے اس کے جو اتنی بار (یہ کلمات) کہے یا اس سے زیادہ بار کہے۔\""}],[6900,"ابواسحٰق نے عمرو بن میمون سے روایت کی ، کہا : جس شخص نے دس بار : \" لا اله الا لله وحده لا شريك له له الملك وله لحمد وهو على كل شيء قدير \" پڑھا وہ اس شخص کی طرح ہو گا جس نے حضرت اسماعیل علیہ السلام کی نسل سے چار غلام آزاد کیے ہوں ۔","",{"u2":"ابواسحٰق نے عمرو بن میمون سے روایت کی، کہا: جس شخص نے دس بار: \" لا الہ الا للہ وحدہ لا شریک لہ لہ الملک ولہ لحمد وہو علی کل شیء قدیر\" پڑھا وہ اس شخص کی طرح ہو گا جس نے حضرت اسماعیل علیہ السلام کی نسل سے چار غلام آزاد کیے ہوں۔"}],[6901,"شعبی نے ربیع بن خُثیم سے اسی کے مانند روایت کی ، انہوں نے کہا : میں نے ربیع سے پوچھا : آپ نے یہ ( حدیث ) کس سے سنی؟ انہوں نے کہا : عمرو بن میمون سے ، پھر میں عمرو بن میمون کے پاس آیا ، ان سے پوچھا : آپ نے یہ ( حدیث ) کس سے سنی؟ انہوں نے کہا : ابن ابی لیلی سے ، کہا : تو میں ابن ابی لیلی کے پاس آیا اور ان سے پوچھا : آپ نے یہ ( حدیث ) کس سے سنی؟ انہوں نے کہا : میں نے سیدنا ابوایوب انصاری رضی اللہ عنہ سے سنی ، وہ اسے رسول اللہ صلی اللہ علیہ وسلم سے بیان کرتے تھے ۔","",{"u2":"شعبی نے ربیع بن خُثیم سے اسی کے مانند روایت کی، انہوں نے کہا: میں نے ربیع سے پوچھا: آپ نے یہ (حدیث) کس سے سنی؟ انہوں نے کہا: عمرو بن میمون سے، پھر میں عمرو بن میمون کے پاس آیا، ان سے پوچھا: آپ نے یہ (حدیث) کس سے سنی؟ انہوں نے کہا: ابن ابی لیلیٰ سے، کہا: تو میں ابن ابی لیلیٰ کے پاس آیا اور ان سے پوچھا: آپ نے یہ (حدیث) کس سے سنی؟ انہوں نے کہا: میں نے حضرت ابوایوب انصاری رضی اللہ عنہ سے سنی، وہ اسے رسول اللہ صلی اللہ علیہ وسلم سے بیان کرتے تھے۔"}],[6902,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" دو کلمے ہیں جو زبان پر ہلکے ہیں اور میزان میں بھاری ہیں اور اللہ کو بہت محبوب ہیں : \" سبحان اللہ وبحمده سبحان العظيم \" اللہ ہر اس چیز سے پاک ہے جو اس کے شایان شان نہیں اور سب حمد اسی کو سزاوار ہے ، اللہ ہر اس چیز سے پاک ہے جو اس کے شایان شان نہیں اور عظمت کی ہر صفت سے متصف ہے ۔","",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"دو کلمے ہیں جو زبان پر ہلکے ہیں اور میزان میں بھاری ہیں اور اللہ کو بہت محبوب ہیں: \" سبحان اللہ وبحمدہ سبحان العظیم\" اللہ ہر اس چیز سے پاک ہے جو اس کے شایان شان نہیں اور سب حمد اسی کو سزاوار ہے، اللہ ہر اس چیز سے پاک ہے جو اس کے شایان شان نہیں اور عظمت کی ہر صفت سے متصف ہے۔\""}],[6903,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" یہ بات کہ میں \" سبحان اللہ والحمدلله ولا اله الا لله والله اكبر \" کہوں ، مجھے ان تمام چیزوں سے زیادہ محبوب ہے جن پر سورج طلوع ہوتا ہے ۔","",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہ بات کہ میں \" سبحان اللہ والحمدللہ ولا الہ الا للہ واللہ اکبر\" کہوں، مجھے ان تمام چیزوں سے زیادہ محبوب ہے جن پر سورج طلوع ہوتا ہے۔\""}],[6904,"ابوبکر بن ابی شیبہ نے ہمیں حدیث بیان کی ، کہا : ہمیں علی بن مسہر اور ابن نمیر نے موسی جہنی سے حدیث بیان کی ، اور ہمیں محمد بن عبداللہ بن نمیر نے بھی یہی حدیث بیان کی ۔ ۔ الفاظ انہی کے ہیں ۔ ۔ انہوں نے کہا : ہمیں میرے والد نے حدیث بیان کی ، انہوں نے کہا : ہمیں موسی جہنی نے معصب بن سعد سے حدیث بیان کی ، انہوں نے اپنے والد سے روایت کی ، انہوں نے کہا : ایک اعرابی رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور عرض کی : مجھے کچھ کلمات سکھائیے جنہیں میں ( بطور ذکر ) کہا کروں ۔ آپ نے فرمایا : \"\" یہ کہا کرو : \"\" لا اله الا لله وحده لا شريك له الله اكبر كبيرا والحمدلله كثيرا وسبحان اللہ رب العالمين لا حول ولا قوة الا بالله العزيز الحكيم \"\" \"\" اللہ کے سوا کوئی عبادت کے لائق نہیں ، وہ اکیلا ہے ، اس کا کوئی شریک نہیں ، اللہ بڑائی میں سب سے بڑا ہے اور بے حد و حساب تعریف اللہ کی ہے ، اللہ ہر اس چیز سے پاک ہے جو اس کے شایان شان نہیں ، وہ سارے جہانوں کا پالنے والا ہے ، کسی میں برائی سے بچنے کی طاقت اور نیکی کرنے کی قوت نہیں مگر صرف اور صرف اللہ کی دی ہوئی جو سب پر غالب ہے ، بڑی حکمت والا ہے ۔ \"\" اس شخص نے کہا : یہ کلمات تو میرے رب کے لیے ہیں ، میرے لیے کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" یہ کہو : \"\" اللهم اغفرلى وارحمنى واهدنى وارزقنى \"\" اے اللہ! مجھے بخش دے ، مجھ پر رحم فرما ، مجھے ہدایت دے اور مجھے رزق عطا فرما ۔ \"\" موسی نے کہا : جہاں تک \"\" عافنى \"\" مجھے عافیت عطا کر \"\" کا تعلق ہے تو اس کے بارے میں مجھے تھوڑا سا وہم ہے اور مجھے یقین نہیں ہے ، اور ابن ابی شیبہ نے اپنی حدیث میں موسی کا یہ قول نقل نہیں کیا ۔","",{"u2":"ابوبکر بن ابی شیبہ نے ہمیں حدیث بیان کی، کہا: ہمیں علی بن مسہر اور ابن نمیر نے موسیٰ جہنی سے حدیث بیان کی، اور ہمیں محمد بن عبداللہ بن نمیر نے بھی یہی حدیث بیان کی۔۔ الفاظ انہی کے ہیں۔۔ انہوں نے کہا: ہمیں میرے والد نے حدیث بیان کی، انہوں نے کہا: ہمیں موسی جہنی نے معصب بن سعد سے حدیث بیان کی، انہوں نے اپنے والد سے روایت کی، انہوں نے کہا: ایک اعرابی رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور عرض کی: مجھے کچھ کلمات سکھائیے جنہیں میں (بطور ذکر) کہا کروں۔ آپ نے فرمایا: \"یہ کہا کرو: \" لا الہ الا للہ وحدہ لا شریک لہ اللہ اکبر کبیرا والحمدللہ کثیرا وسبحان اللہ رب العالمین لا حول ولا قوۃ الا باللہ العزیز الحکیم\" \"اللہ کے سوا کوئی عبادت کے لائق نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں، اللہ بڑائی میں سب سے بڑا ہے اور بے حد و حساب تعریف اللہ کی ہے، اللہ ہر اس چیز سے پاک ہے جو اس کے شایان شان نہیں، وہ سارے جہانوں کا پالنے والا ہے، کسی میں برائی سے بچنے کی طاقت اور نیکی کرنے کی قوت نہیں مگر صرف اور صرف اللہ کی دی ہوئی جو سب پر غالب ہے، بڑی حکمت والا ہے۔\"\nاس شخص نے کہا: یہ کلمات تو میرے رب کے لیے ہیں، میرے لیے کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ کہو: \" اللہم اغفرلی وارحمنی واہدنی وارزقنی\" اے اللہ! مجھے بخش دے، مجھ پر رحم فرما، مجھے ہدایت دے اور مجھے رزق عطا فرما۔\"\nموسیٰ نے کہا: جہاں تک \" عافنی\" مجھے عافیت عطا کر\" کا تعلق ہے تو اس کے بارے میں مجھے تھوڑا سا وہم ہے اور مجھے یقین نہیں ہے، اور ابن ابی شیبہ نے اپنی حدیث میں موسیٰ کا یہ قول نقل نہیں کیا۔"}],[6905,"عبدالواحد بن زیاد نے کہا : ہمیں ابو مالک اشجعی نے اپنے والد ( طارق بن اشیم اشجعی رضی اللہ عنہ ) سے حدیث بیان کی ، کہا : جو شخص اسلام قبول کرتا ، رسول اللہ صلی اللہ علیہ وسلم اس کو ان کلمات کی تعلیم دیتے تھے : \" اللهم اغفرلى وارحمنى واهدنى وارزقنى \" \" اللہ! مجھے بخش دے ، مجھ پر رحم فرما ، مجھے ہدایت دے اور مجھے رزق عطا فرما ۔","",{"u2":"عبدالواحد بن زیاد نے کہا: ہمیں ابو مالک اشجعی نے اپنے والد (طارق بن اشیم اشجعی رضی اللہ عنہ) سے حدیث بیان کی، کہا: جو شخص اسلام قبول کرتا، رسول اللہ صلی اللہ علیہ وسلم اس کو ان کلمات کی تعلیم دیتے تھے: \" اللہم اغفرلی وارحمنی واہدنی وارزقنی\" \"اللہ! مجھے بخش دے، مجھ پر رحم فرما، مجھے ہدایت دے اور مجھے رزق عطا فرما۔\""}],[6906,"ابومعاویہ نے کہا؛ ہمیں ابومالک اشجعی نے اپنے والد سے حدیث بیان کی ، کہا : جب کوئی شخص مسلمان ہوتا تو نبی صلی اللہ علیہ وسلم اس کو نماز سکھاتے ، پھر اس کو حکم دیتے کہ ان کلمات کے ساتھ دعا کیا کرے : اللهم اغفرلى وارحمنى واهدنى وعافنى وارزقنى","",{"u2":"ابومعاویہ نے کہا؛ ہمیں ابومالک اشجعی نے اپنے والد سے حدیث بیان کی، کہا: جب کوئی شخص مسلمان ہوتا تو نبی صلی اللہ علیہ وسلم اس کو نماز سکھاتے، پھر اس کو حکم دیتے کہ ان کلمات کے ساتھ دعا کیا کرے: اللہم اغفرلی وارحمنی واہدنی وعافنی وارزقنی"}],[6907,"یزید بن ہارون نے کہا : ابومالک نے ہمیں اپنے والد سے خبر دی کہ انہوں نے نبی صلی اللہ علیہ وسلم سے سنا ، ( اس وقت ) ان کے پاس ایک شخص نے حاضر ہو کر عرض کی : اللہ کے رسول! جب میں اپنے رب سے مانگوں تو کیا کہا کروں؟ آپ نے فرمایا : \" تم کہو : \" اللهم اغفرلى وارحمنى وعافنى وارزقنى \" ساتھ ہی اپنے انگوٹھے کے سوا ( ایک ایک کر کے ) ساری انگلیاں بند کرتے گئے ( اور فرمایا : ) \" یہ کلمات تمہارے لیے تمہاری دنیا اور آخرت دونوں جمع کر دیں گے ۔","",{"u2":"یزید بن ہارون نے کہا: ابومالک نے ہمیں اپنے والد سے خبر دی کہ انہوں نے نبی صلی اللہ علیہ وسلم سے سنا، (اس وقت) ان کے پاس ایک شخص نے حاضر ہو کر عرض کی: اللہ کے رسول! جب میں اپنے رب سے مانگوں تو کیا کہا کروں؟ آپ نے فرمایا: \"تم کہو: \" اللہم اغفرلی وارحمنی وعافنی وارزقنی\" ساتھ ہی اپنے انگوٹھے کے سوا (ایک ایک کر کے) ساری انگلیاں بند کرتے گئے (اور فرمایا:) \"یہ کلمات تمہارے لیے تمہاری دنیا اور آخرت دونوں جمع کر دیں گے۔\""}],[6908,"معصب بن سعد سے روایت ہے ، انہوں نے کہا : مجھے میرے والد ( سعد بن ابی وقاص رضی اللہ عنہ ) نے حدیث سنائی ، انہوں نے کہا : ہم رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر تھے کہ آپ نے فرمایا : \" کیا تم میں سے کوئی شخص اس بات سے عاجز ہے کہ ہر روز ایک ہزار نیکیاں کمائے؟ \" آپ کے ساتھ بیٹھے ہوئے لوگوں میں سے ایک نے پوچھا ہم میں سے کوئی شخص ایک ہزار نیکیاں کس طرح کما سکتا ہے؟ آپ نے فرمایا : \" وہ سو بار سبحان اللہ کہے ۔ اس کے لیے ہزار نیکیاں لکھ دی جائیں گی اور اس کے سو گناہ مٹا دئیے جائیں گے ۔","",{"u2":") معصب بن سعد سے روایت ہے، انہوں نے کہا: مجھے میرے والد (سعد بن ابی وقاص رضی اللہ عنہ) نے حدیث سنائی، انہوں نے کہا: ہم رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر تھے کہ آپ نے فرمایا: \"کیا تم میں سے کوئی شخص اس بات سے عاجز ہے کہ ہر روز ایک ہزار نیکیاں کمائے؟\" آپ کے ساتھ بیٹھے ہوئے لوگوں میں سے ایک نے پوچھا ہم میں سے کوئی شخص ایک ہزار نیکیاں کس طرح کما سکتا ہے؟ آپ نے فرمایا: \"وہ سو بار سبحان اللہ کہے۔ اس کے لیے ہزار نیکیاں لکھ دی جائیں گی اور اس کے سو گناہ مٹا دئیے جائیں گے۔\""}],[6909,"ابومعاویہ نے اعمش سے ، انہوں نے ابوصالح سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس شخص نے کسی مسلمان کی دنیاوی تکلیفوں میں سے کوئی تکلیف دور کی ، اللہ تعالی اس کی قیامت کی تکلیفوں میں سے کوئی تکلیف دور کرے گا اور جس شخص نے کسی تنگ دست کے لیے آسانی کی ، اللہ تعالی اس کے لیے دنیا اور آخرت میں آسانی کرے گا اور جس نے کسی مسلمان کی پردہ پوشی کی ، اللہ تعالی دنیا اور آخرت میں اس کی پردہ پشی کرے گا اور اللہ تعالی اس وقت تک بندے کی مدد میں لگا رہتا ہے جب تک بندہ اپنے بھائی کی مدد میں لگا رہتا ہے اور جو شخص اس راستے پر چلتا ہے جس میں وہ علم حاصل کرنا چاہتا ہے تو اللہ تعالی اس کے ذریعے سے اس کے لیے جنت کا راستہ آسان کر دیتا ہے ، اللہ کے گھروں میں سے کسی گھر میں لوگوں کا کوئی گروہ اکٹھا نہیں ہوتا ، وہ قرآن کی تلاوت کرتے ہیں اور اس کا درس و تدریس کرتے ہیں مگر ان پر سکینت ( اطمینان و سکون قلب ) کا نزول ہوتا ہے اور ( اللہ کی ) رحمت ان کو ڈھانپ لیتی ہے اور فرشتے ان کو اپنے گھیرے میں لے لیتے ہیں اور اللہ تعالی اپنے مقربین میں جو اس کے پاس ہوتے ہیں ان کا ذکر کرتا ہے اور جس کے عمل نے اسے ( خیر کے حصول میں ) پیچھے رکھا ، اس کا نسب اسے تیز نہیں کر سکتا ۔","",{"u2":"ابومعاویہ نے اعمش سے، انہوں نے ابوصالح سے اور انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس شخص نے کسی مسلمان کی دنیاوی تکلیفوں میں سے کوئی تکلیف دور کی، اللہ تعالیٰ اس کی قیامت کی تکلیفوں میں سے کوئی تکلیف دور کرے گا اور جس شخص نے کسی تنگ دست کے لیے آسانی کی، اللہ تعالیٰ اس کے لیے دنیا اور آخرت میں آسانی کرے گا اور جس نے کسی مسلمان کی پردہ پوشی کی، اللہ تعالیٰ دنیا اور آخرت میں اس کی پردہ پشی کرے گا اور اللہ تعالیٰ اس وقت تک بندے کی مدد میں لگا رہتا ہے جب تک بندہ اپنے بھائی کی مدد میں لگا رہتا ہے اور جو شخص اس راستے پر چلتا ہے جس میں وہ علم حاصل کرنا چاہتا ہے تو اللہ تعالیٰ اس کے ذریعے سے اس کے لیے جنت کا راستہ آسان کر دیتا ہے، اللہ کے گھروں میں سے کسی گھر میں لوگوں کا کوئی گروہ اکٹھا نہیں ہوتا، وہ قرآن کی تلاوت کرتے ہیں اور اس کا درس و تدریس کرتے ہیں مگر ان پر سکینت (اطمینان و سکون قلب) کا نزول ہوتا ہے اور (اللہ کی) رحمت ان کو ڈھانپ لیتی ہے اور فرشتے ان کو اپنے گھیرے میں لے لیتے ہیں اور اللہ تعالیٰ اپنے مقربین میں جو اس کے پاس ہوتے ہیں ان کا ذکر کرتا ہے اور جس کے عمل نے اسے (خیر کے حصول میں) پیچھے رکھا، اس کا نسب اسے تیز نہیں کر سکتا۔\""}],[6910,"عبداللہ بن نمیر اور ابواسامہ نے کہا : ہمیں اعمش نے حدیث بیان کی ، انہوں نے ابوصالح سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ، جس طرح ابومعاویہ کی حدیث ہے ، مگر ابواسامہ کی حدیث میں تنگدست کے لیے آسانی کرنے کا ذکر نہیں ۔","",{"u2":"عبداللہ بن نمیر اور ابواسامہ نے کہا: ہمیں اعمش نے حدیث بیان کی، انہوں نے ابوصالح سے اور انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا، جس طرح ابومعاویہ کی حدیث ہے، مگر ابواسامہ کی حدیث میں تنگدست کے لیے آسانی کرنے کا ذکر نہیں۔"}],[6911,"محمد بن جعفر نے کہا : ہمیں شعبہ نے حدیث بیان کی ، کہا : میں نے ابواسحاق کو ابومسلم اغر سے حدیث بیان کرتے ہوئے سنا ، انہوں نے کہا : میں سیدنا ابوہریرہ اور سیدنا ابوسعید خدری رضی اللہ عنہ کے بارے میں گواہی دیتا ہوں ، ان دونوں نے نبی صلی اللہ علیہ وسلم کے بارے میں گواہی دی کہ آپ نے فرمایا : \" جو قوم بھی اللہ عزوجل کو یاد کرنے کے لیے بیٹھتی ہے ، ان کو فرشتے گھیر لیتے ہیں ، رحمت ڈھانپ لیتی ہے اور ان پر اطمینان قلب نازل ہوتا ہے اور اللہ ان کا ذکر ان میں کرتا ہے جو اس کے پاس ہوتے ہیں ۔","",{"u2":") محمد بن جعفر نے کہا: ہمیں شعبہ نے حدیث بیان کی، کہا: میں نے ابواسحاق کو ابومسلم اغر سے حدیث بیان کرتے ہوئے سنا، انہوں نے کہا: میں حضرت ابوہریرہ اور حضرت ابوسعید خدری رضی اللہ عنہ کے بارے میں گواہی دیتا ہوں، ان دونوں نے نبی صلی اللہ علیہ وسلم کے بارے میں گواہی دی کہ آپ نے فرمایا: \"جو قوم بھی اللہ عزوجل کو یاد کرنے کے لیے بیٹھتی ہے، ان کو فرشتے گھیر لیتے ہیں، رحمت ڈھانپ لیتی ہے اور ان پر اطمینان قلب نازل ہوتا ہے اور اللہ ان کا ذکر ان میں کرتا ہے جو اس کے پاس ہوتے ہیں۔\""}],[6912,"محمد بن جعفر نے کہا : ہمیں شعبہ نے حدیث بیان کی ، کہا : میں نے ابواسحاق کو ابومسلم اغر سے حدیث بیان کرتے ہوئے سنا ، انہوں نے کہا : میں سیدنا ابوہریرہ اور سیدنا ابوسعید خدری رضی اللہ عنہ کے بارے میں گواہی دیتا ہوں ، ان دونوں نے نبی صلی اللہ علیہ وسلم کے بارے میں گواہی دی کہ آپ نے فرمایا : \" جو قوم بھی اللہ عزوجل کو یاد کرنے کے لیے بیٹھتی ہے ، ان کو فرشتے گھیر لیتے ہیں ، رحمت ڈھانپ لیتی ہے اور ان پر اطمینان قلب نازل ہوتا ہے اور اللہ ان کا ذکر ان میں کرتا ہے جو اس کے پاس ہوتے ہیں ۔","",{"u2":"عبدالرحمٰن نے ہمیں حدیث بیان کی، کہا: ہمیں شعبہ نے اسی سند سے اسی کے مانند حدیث بیان کی۔"}],[6913,"سیدنا ابوسعید خدری رضی اللہ عنہ سے روایت ہے ، کہا : سیدنا معاویہ رضی اللہ عنہ نکل کر مسجد میں ایک حلقے ( والوں ) کے پاس سے گزرے ، انہوں نے کہا : تمہیں کس چیز نے یہاں بٹھا رکھا ہے؟ انہوں نے کہا : ہم اللہ کا ذکر کرنے کے لیے بیٹھے ہیں ۔ انہوں نے کہا : کیا اللہ کو گواہ بنا کر کہتے ہو کہ تمہیں اس کے علاوہ اور کسی غرض نے نہیں بٹھایا؟ انہوں نے کہا : اللہ کی قسم! ہم اس کے علاوہ اور کسی وجہ سے نہیں بیٹھے ، انہوں نے کہا؛ دیکھو ، میں نے تم پر کسی تہمت کی وجہ سے قسم نہیں دی ۔ رسول اللہ صلی اللہ علیہ وسلم کے سامنے میری حیثیت کا کوئی شخص ایسا نہیں جو حدیث بیان کرنے میں مجھ سے کم ہو ، ( اس کے باوجود اپنے یقینی علم کی بنا پر میں تمہارے سامنے یہ حدیث بیان کر رہا ہوں کہ ) رسول اللہ صلی اللہ علیہ وسلم نکل کر اپنے ساتھیوں کے ایک حلقے کے قریب تشریف لائے اور فرمایا : \" تم کس غرض سے بیٹھے ہو؟ \" انہوں نے کہا : ہم بیٹھے اللہ کا ذکر کر رہے ہیں اور اس بات پر اس کی حمد کر رہے ہیں کہ اس نے اسلام کی طرف ہماری رہنمائی کی ، اس کے ذریعے سے ہم پر احسان کیا ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \" کیا تم اللہ کو گواہ بنا کر کہتے ہو کہ تم صرف اسی غرض سے بیٹھے ہو؟ \" انہوں نے کہا : اللہ کی قسم! ہم اس کے سوا اور کسی غرض سے نہیں بیٹھے ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \" میں نے تم پر کسی تہمت کی وجہ سے تمہیں قسم نہیں دی ، بلکہ میرے پاس جبریل آئے اور مجھے بتایا کہ اللہ تعالی تمہارے ذریعے سے فرشتوں کے سامنے فخر کا اظہار فرما رہا ہے ۔","",{"u2":"حضرت ابوسعید خدری رضی اللہ عنہ سے روایت ہے، کہا: حضرت معاویہ رضی اللہ عنہ نکل کر مسجد میں ایک حلقے (والوں) کے پاس سے گزرے، انہوں نے کہا: تمہیں کس چیز نے یہاں بٹھا رکھا ہے؟ انہوں نے کہا: ہم اللہ کا ذکر کرنے کے لیے بیٹھے ہیں۔ انہوں نے کہا: کیا اللہ کو گواہ بنا کر کہتے ہو کہ تمہیں اس کے علاوہ اور کسی غرض نے نہیں بٹھایا؟ انہوں نے کہا: اللہ کی قسم! ہم اس کے علاوہ اور کسی وجہ سے نہیں بیٹھے، انہوں نے کہا؛ دیکھو، میں نے تم پر کسی تہمت کی وجہ سے قسم نہیں دی۔ رسول اللہ صلی اللہ علیہ وسلم کے سامنے میری حیثیت کا کوئی شخص ایسا نہیں جو حدیث بیان کرنے میں مجھ سے کم ہو، (اس کے باوجود اپنے یقینی علم کی بنا پر میں تمہارے سامنے یہ حدیث بیان کر رہا ہوں کہ) رسول اللہ صلی اللہ علیہ وسلم نکل کر اپنے ساتھیوں کے ایک حلقے کے قریب تشریف لائے اور فرمایا: \"تم کس غرض سے بیٹھے ہو؟\" انہوں نے کہا: ہم بیٹھے اللہ کا ذکر کر رہے ہیں اور اس بات پر اس کی حمد کر رہے ہیں کہ اس نے اسلام کی طرف ہماری رہنمائی کی، اس کے ذریعے سے ہم پر احسان کیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم اللہ کو گواہ بنا کر کہتے ہو کہ تم صرف اسی غرض سے بیٹھے ہو؟\" انہوں نے کہا: اللہ کی قسم! ہم اس کے سوا اور کسی غرض سے نہیں بیٹھے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں نے تم پر کسی تہمت کی وجہ سے تمہیں قسم نہیں دی، بلکہ میرے پاس جبریل آئے اور مجھے بتایا کہ اللہ تعالیٰ تمہارے ذریعے سے فرشتوں کے سامنے فخر کا اظہار فرما رہا ہے۔\""}],[6914,"ثابت نے ابو بُردہ سے اور انہوں نے سیدنا اغرمزنی رضی اللہ عنہ سے ، جنہیں شرفِ صحبت حاصل تھا ، روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : میرے دل پر غبار سا چھا جاتا ہے تو میں ( اس کیفیت کے ازالے کے لیے ) ایک دن میں سو بار اللہ سے استغفار کرتا ہوں ۔","",{"u2":"ثابت نے ابو بُردہ سے اور انہوں نے حضرت اغرمزنی رضی اللہ عنہ سے، جنہیں شرفِ صحبت حاصل تھا، روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: میرے دل پر غبار سا چھا جاتا ہے تو میں (اس کیفیت کے ازالے کے لیے) ایک دن میں سو بار اللہ سے استغفار کرتا ہوں۔\""}],[6915,"غندر نے شعبہ سے ، انہوں نے عمرہ بن مُرہ سے اور انہوں نے ابوبُردہ سے روایت کی ، انہوں نے کہا : میں نے سیدنا اغر رضی اللہ عنہ سے سنا ۔ ۔ اور وہ رسول اللہ صلی اللہ علیہ وسلم کے صحابہ میں سے تھے ۔ ۔ وہ سیدنا ابن عمر رضی اللہ عنہ سے روایت کرتے تھے ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" لوگو! اللہ کی طرف توبہ کیا کرو کیونکہ میں اللہ سے ۔ ۔ ایک دن میں ۔ ۔ سو بار توبہ کرتا ہوں ۔","",{"u2":"غندر نے شعبہ سے، انہوں نے عمرہ بن مُرہ سے اور انہوں نے ابوبُردہ سے روایت کی، انہوں نے کہا: میں نے حضرت اغر رضی اللہ عنہ سے سنا۔۔ اور وہ رسول اللہ صلی اللہ علیہ وسلم کے صحابہ میں سے تھے۔۔ وہ حضرت ابن عمر رضی اللہ عنہ سے روایت کرتے تھے، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"لوگو! اللہ کی طرف توبہ کیا کرو کیونکہ میں اللہ سے۔۔ ایک دن میں۔۔ سو بار توبہ کرتا ہوں۔\""}],[6916,"عبیداللہ کے والد معاذ ، ابوداؤد اور عبدالرحمٰن بن مہدی نے شعبہ سے اسی سند سے ( یہی ) روایت کی ۔","",{"u2":"عبیداللہ کے والد معاذ، ابوداؤد اور عبدالرحمٰن بن مہدی نے شعبہ سے اسی سند سے (یہی) روایت کی۔"}],[6917,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جس شخص نے سورج کے مغرب سے طلوع ہونے سے پہلے توبہ کر لی ، اللہ تعالی اس کی توبہ کو قبول فرما لے گا ۔","",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس شخص نے سورج کے مغرب سے طلوع ہونے سے پہلے توبہ کر لی، اللہ تعالیٰ اس کی توبہ کو قبول فرما لے گا۔\""}],[6918,"محمد بن فضیل اور ابومعاویہ نے عاصم سے ، انہوں نے ابوعثمان سے اور انہوں نے سیدنا ابوموسی رضی اللہ عنہ سے روایت کی ، کہا : ایک سفر میں ہم نبی صلی اللہ علیہ وسلم کے ساتھ تھے کہ لوگ بلند آواز کے ساتھ اللہ اکبر کہنے لگے ، نبی صلی اللہ علیہ وسلم نے فرمایا : \" اے لوگو! اپنی جانوں پر نرمی کرو ، تم نہ کسی بہرے کو پکار رہے ہو ، نہ غائب کو ، تم اس کو پکار رہے ہو جو ہر وقت خوب سننے والا ہے ، قریب ہے اور تمہارے ساتھ ہے ۔ \" اس وقت میں آپ کے پیچھے تھا اور یہ کہہ رہا تھا : \" لا حول ولا قوة الا باللہ \" \" گناہوں سے بچنے اور نیکی کی قوت صرف اور صرف اللہ سے ملتی ہے ۔ \" تو آپ صلی اللہ علیہ وسلم نے فرمایا : \" عبدالہ بن قیس! کیا میں تمہیں جنت کے خزانوں میں سے ایک خزانے کا پتہ نہ بتاؤں؟ \" میں نے کہا : کیوں نہیں ، اللہ کے رسول! آپ نے فرمایا : \" لا حول ولا قوة الا باللہ \" کہا کرو ۔","",{"u2":"محمد بن فضیل اور ابومعاویہ نے عاصم سے، انہوں نے ابوعثمان سے اور انہوں نے حضرت ابوموسیٰ رضی اللہ عنہ سے روایت کی، کہا: ایک سفر میں ہم نبی صلی اللہ علیہ وسلم کے ساتھ تھے کہ لوگ بلند آواز کے ساتھ اللہ اکبر کہنے لگے، نبی صلی اللہ علیہ وسلم نے فرمایا: \"اے لوگو! اپنی جانوں پر نرمی کرو، تم نہ کسی بہرے کو پکار رہے ہو، نہ غائب کو، تم اس کو پکار رہے ہو جو ہر وقت خوب سننے والا ہے، قریب ہے اور تمہارے ساتھ ہے۔\" اس وقت میں آپ کے پیچھے تھا اور یہ کہہ رہا تھا: \" لا حول ولا قوۃ الا باللہ \" \"گناہوں سے بچنے اور نیکی کی قوت صرف اور صرف اللہ سے ملتی ہے۔\" تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"عبدالہ بن قیس! کیا میں تمہیں جنت کے خزانوں میں سے ایک خزانے کا پتہ نہ بتاؤں؟\" میں نے کہا: کیوں نہیں، اللہ کے رسول! آپ نے فرمایا: \" لا حول ولا قوۃ الا باللہ \" کہا کرو۔\""}],[6919,"حفص بن غیاث نے عاصم سے اسی سند کے ساتھ اسی کے مانند روایت کی ۔","",{"u2":") حفص بن غیاث نے عاصم سے اسی سند کے ساتھ اسی کے مانند روایت کی۔"}],[6920,"یزید بن زُریع نے کہا : ہمیں ( سلیمان ) تیمی نے ابوعثمان سے حدیث بیان کی ، انہوں نے سیدنا ابوموسی رضی اللہ عنہ سے روایت کی کہ وہ لوگ ( صحابہ کرام رضی اللہ عنہم ) رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے اور وہ ایک گھاٹی پر چڑھ رہے تھے ، کہا : ایک آدمی جب بھی اونچائی پر چڑھتا زور سے پکارنا شروع کر دیتا : \" لا اله الا لله والله اكبر \" ( ابوموسی رضی اللہ عنہ نے ) کہا : نبی صلی اللہ علیہ وسلم نے فرمایا : \" تم لوگ کسی بہرے کو یا اسے جو غائب ہو ، نہیں پکار رہے ۔ \" کہا : پھر آپ صلی اللہ علیہ وسلم نے فرمایا : \" ابوموسی! یا ( فرمایا : ) عبداللہ بن قیس! کیا تمہیں ایسا کلمہ نہ بتاؤں جو جنت کے خزانے میں سے ہے؟ \" میں نے عرض کی ، اللہ کے رسول! وہ کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا : \" لا حول ولا قوة الا باللہ \" ( گناہوں سے بچنے کی ) کوئی کوشش اور ( نیکی کرنے کی ) کوئی قوت اللہ کے سوا کسی سے حاصل نہیں ہوتی ۔","",{"u2":"یزید بن زُریع نے کہا: ہمیں (سلیمان) تیمی نے ابوعثمان سے حدیث بیان کی، انہوں نے حضرت ابوموسیٰ رضی اللہ عنہ سے روایت کی کہ وہ لوگ (صحابہ کرام رضی اللہ عنہم) رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے اور وہ ایک گھاٹی پر چڑھ رہے تھے، کہا: ایک آدمی جب بھی اونچائی پر چڑھتا زور سے پکارنا شروع کر دیتا: \" لا الہ الا للہ واللہ اکبر \" (ابوموسیٰ رضی اللہ عنہ نے) کہا: نبی صلی اللہ علیہ وسلم نے فرمایا: \"تم لوگ کسی بہرے کو یا اسے جو غائب ہو، نہیں پکار رہے۔\" کہا: پھر آپ صلی اللہ علیہ وسلم نے فرمایا: \"ابوموسیٰ! یا (فرمایا:) عبداللہ بن قیس! کیا تمہیں ایسا کلمہ نہ بتاؤں جو جنت کے خزانے میں سے ہے؟\" میں نے عرض کی، اللہ کے رسول! وہ کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \" لا حول ولا قوۃ الا باللہ \" (گناہوں سے بچنے کی) کوئی کوشش اور (نیکی کرنے کی) کوئی قوت اللہ کے سوا کسی سے حاصل نہیں ہوتی۔\""}],[6921,"معتمر نے اپنے والد ( سلیمان تیمی ) سے روایت کی ، انہوں نے کہا : ہمیں ابوعثمان نے سیدنا ابوموسی رضی اللہ عنہ سے روایت کی ، کہا : ایک بار رسول اللہ صلی اللہ علیہ وسلم پھر اسی ( سابقہ حدیث ) کی طرح بیان کیا ۔","",{"u2":"معتمر نے اپنے والد (سلیمان تیمی) سے روایت کی، انہوں نے کہا: ہمیں ابوعثمان نے حضرت ابوموسیٰ رضی اللہ عنہ سے روایت کی، کہا: ایک بار رسول اللہ صلی اللہ علیہ وسلم پھر اسی (سابقہ حدیث) کی طرح بیان کیا۔"}],[6922,"ایوب نے ابوعثمان سے اور انہوں نے سیدنا ابوموسی رضی اللہ عنہ سے روایت کی ، کہا : ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک سفر میں تھے ، پھر عاصم کی حدیث کی طرح بیان کیا ۔","",{"u2":"ایوب نے ابوعثمان سے اور انہوں نے حضرت ابوموسیٰ رضی اللہ عنہ سے روایت کی، کہا: ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک سفر میں تھے، پھر عاصم کی حدیث کی طرح بیان کیا۔"}],[6923,"خالد حذاء نے ابوعثمان سے اور انہوں نے سیدنا ابوموسی رضی اللہ عنہ سے روایت کی ، کہا : ہم ایک غزوے میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے ، پھر اس حدیث کو بیان کیا اور اس میں کہا : ( آپ صلی اللہ علیہ وسلم نے فرمایا : ) \" تم جس کو پکار رہے ہو وہ تم میں سے کسی کی اونٹنی کی گردن کی نسبت بھی اس کے زیادہ قریب ہے ۔ \" اور ان ( خالد حذاء ) کی حدیث میں \" لا حول ولا قوة الا باللہ \" کا ذکر نہیں ہے ۔","",{"u2":"خالد حذاء نے ابوعثمان سے اور انہوں نے حضرت ابوموسیٰ رضی اللہ عنہ سے روایت کی، کہا: ہم ایک غزوے میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے، پھر اس حدیث کو بیان کیا اور اس میں کہا: (آپ صلی اللہ علیہ وسلم نے فرمایا:) \"تم جس کو پکار رہے ہو وہ تم میں سے کسی کی اونٹنی کی گردن کی نسبت بھی اس کے زیادہ قریب ہے۔\" اور ان (خالد حذاء) کی حدیث میں \" لا حول ولا قوۃ الا باللہ \" کا ذکر نہیں ہے۔"}],[6924,"عثمان بن غیاث نے کہا : ہمیں ابوعثمان نے سیدنا ابوموسی اشعری رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ نے مجھ سے فرمایا : \" کیا میں تمہیں جنت کے خزانوں میں سے ایک کلمہ نہ بتاؤں؟ \" ۔ ۔ یا فرمایا : ۔ ۔ \" جنت کے خزانوں میں سے ایک خزانے کا پتہ نہ بتاؤں؟ \" میں نے عرض کی : کیوں نہیں ( ضرور بتائیں ) ، آپ صلی اللہ علیہ وسلم نے فرمایا : \" لا حول ولا قوة الا باللہ","",{"u2":"عثمان بن غیاث نے کہا: ہمیں ابوعثمان نے حضرت ابوموسی اشعری رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ نے مجھ سے فرمایا: \"کیا میں تمہیں جنت کے خزانوں میں سے ایک کلمہ نہ بتاؤں؟\"۔۔ یا فرمایا:۔۔ \"جنت کے خزانوں میں سے ایک خزانے کا پتہ نہ بتاؤں؟\" میں نے عرض کی: کیوں نہیں (ضرور بتائیں)، آپ صلی اللہ علیہ وسلم نے فرمایا: \" لا حول ولا قوۃ الا باللہ \""}],[6925,"ابو بکر رضی االله عنہ سے روایت ہے انہوں نے رسول االله صلی اللہ علیہ وسلم سے عرض کیا یارسول االله صلی اللہ علیہ وسلم مجھے ایک دعا سکھلائیے جس کو میں پڑھا کروں اپنی نماز میں آپ نے فرمایا یہ کہا کر یا االله میں نے اپنے نفس پر بڑا ظلم کیا ہے یا بہت ظلم کیا ہے اور گناہوں کو کوئی نہیں بخشتا سوا تیرے تو بخش دے مجھے اپنے پاس کی بخشش سے اور رحم کر مجھ پر تو بخشنے والا مہربان ہے ۔"],[6926,"عبداللہ بن وہب نے ہمیں خبر دی ، کہا : ہمیں ایک آدمی نے جس کا انہوں نے نام لیا اور عمرو بن حارث نے یزید بن ابی حبیب سے خبر دی اور انہوں نے ابوالخیر سے روایت کی ، انہوں نے سیدنا عبداللہ بن عمرو بن عاص رضی اللہ عنہ سے سنا ، وہ کہتے تھے : سیدنا ابوبکر صدیق رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کی : اللہ کے رسول! آپ مجھے ایک ایسی دعا سکھائیے جس کو میں اپنی نماز میں بھی مانگا کروں اور اپنے گھر میں بھی مانگا کروں ۔ ۔ پھر لیث کی حدیث کے مانند بیان کیا ۔ مگر انہوں نے ( بغیر شک کے ) \" ظلما كثيرا \" ( بہت ظلم کیا ) کہا ۔","",{"u2":"عبداللہ بن وہب نے ہمیں خبر دی، کہا: ہمیں ایک آدمی نے جس کا انہوں نے نام لیا اور عمرو بن حارث نے یزید بن ابی حبیب سے خبر دی اور انہوں نے ابوالخیر سے روایت کی، انہوں نے حضرت عبداللہ بن عمرو بن عاص رضی اللہ عنہ سے سنا، وہ کہتے تھے: حضرت ابوبکر صدیق رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کی: اللہ کے رسول! آپ مجھے ایک ایسی دعا سکھائیے جس کو میں اپنی نماز میں بھی مانگا کروں اور اپنے گھر میں بھی مانگا کروں۔۔ پھر لیث کی حدیث کے مانند بیان کیا۔ مگر انہوں نے (بغیر شک کے) \" ظلما کثیرا \" (بہت ظلم کیا) کہا۔"}],[6927,"ابن نمیر نے کہا : ہمیں ہشام نے اپنے والد ( عروہ ) سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم ( اللہ تعالی سے ) یہ دعائیں مانگا کرتے تھے : \" اے اللہ! میں تیری پناہ میں آتا ہوں آگ کے فتنے سے اور آگ کے عذاب سے اور غنا کی آزمائش کے شر سے اور فقر کی آزمائش کے شر سے اور میں تیری پناہ میں آتا ہوں جھوٹے مسیح کے فتنے کی برائی سے ۔ اے اللہ! میری خطائیں برف اور اولوں ( کے پانی ) سے دھودے ، اور میرے دل کو خطاؤں سے اس طرح صاف ستھرا کر دے جس طرح تو سفید کپڑے کو میل سے صاف کرتا ہے اور میرے اور میری خطاؤں کے درمیان اتنا فاصلہ ڈال دے جتنا فاصلہ تو نے مشرق اور مغرب کے درمیان ڈالا ہے ۔ اے اللہ! میں سستی ، عاجز کر دینے والے بڑھاپے ، گناہ اور قرج ( کے غلبے ) سے تیری پناہ میں آتا ہوں ۔","",{"u2":"ابن نمیر نے کہا: ہمیں ہشام نے اپنے والد (عروہ) سے اور انہوں نے حضرت عائشہ رضی اللہ عنہا سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم (اللہ تعالیٰ سے) یہ دعائیں مانگا کرتے تھے: \"اے اللہ! میں تیری پناہ میں آتا ہوں آگ کے فتنے سے اور آگ کے عذاب سے اور غنا کی آزمائش کے شر سے اور فقر کی آزمائش کے شر سے اور میں تیری پناہ میں آتا ہوں جھوٹے مسیح کے فتنے کی برائی سے۔ اے اللہ! میری خطائیں برف اور اولوں (کے پانی) سے دھودے، اور میرے دل کو خطاؤں سے اس طرح صاف ستھرا کر دے جس طرح تو سفید کپڑے کو میل سے صاف کرتا ہے اور میرے اور میری خطاؤں کے درمیان اتنا فاصلہ ڈال دے جتنا فاصلہ تو نے مشرق اور مغرب کے درمیان ڈالا ہے۔ اے اللہ! میں سستی، عاجز کر دینے والے بڑھاپے، گناہ اور قرج (کے غلبے) سے تیری پناہ میں آتا ہوں۔\""}],[6928,"ابومعاویہ اور وکیع نے ہمیں ہشام سے اسی سند کے ساتھ حدیث بیان کی ۔","",{"u2":"ابومعاویہ اور وکیع نے ہمیں ہشام سے اسی سند کے ساتھ حدیث بیان کی۔"}],[6929,"ابن علیہ نے کہا : ہمیں سلیمان تیمی نے خبر دی ، انہوں نے کہا : ہمیں سیدنا انس بن مالک رضی اللہ عنہ نے حدیث بیان کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم یہ دعا فرمایا کرتے تھے : \" اے اللہ! میں عاجز ہونے ، سستی ، بزدلی ، بڑھاپے اور بخل سے تیری پناہ میں آتا ہوں اور میں قبر کے عذاب اور زندگی اور موت کی آزمائشوں سے تیری پناہ میں آتا ہوں ۔","",{"u2":"ابن علیہ نے کہا: ہمیں سلیمان تیمی نے خبر دی، انہوں نے کہا: ہمیں حضرت انس بن مالک رضی اللہ عنہ نے حدیث بیان کی، کہا: رسول اللہ صلی اللہ علیہ وسلم یہ دعا فرمایا کرتے تھے: \"اے اللہ! میں عاجز ہونے، سستی، بزدلی، بڑھاپے اور بخل سے تیری پناہ میں آتا ہوں اور میں قبر کے عذاب اور زندگی اور موت کی آزمائشوں سے تیری پناہ میں آتا ہوں۔\""}],[6930,"یزید بن زریع اور معتمر دونوں نے تیمی سے ، انہوں نے سیدنا انس رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی ، البتہ یزید کی حدیث میں آپ صلی اللہ علیہ وسلم کا قول : \" اور زندگی اور موت کی آزمائشوں سے ( میں تیزی پناہ میں آتا ہوں ) \" مذکور نہیں ۔","",{"u2":"یزید بن زریع اور معتمر دونوں نے تیمی سے، انہوں نے حضرت انس رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی، البتہ یزید کی حدیث میں آپ صلی اللہ علیہ وسلم کا قول: \"اور زندگی اور موت کی آزمائشوں سے (میں تیزی پناہ میں آتا ہوں)\" مذکور نہیں۔"}],[6931,"ابن مبارک نے سلیمان تیمی سے ، انہوں نے سیدنا انس بن مالک رضی اللہ عنہ سے ، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے کئی اشیاء سے ، جن کا انہوں نے ذکر کیا اور بخل سے اللہ کی پناہ طلب کی ۔","",{"u2":"ابن مبارک نے سلیمان تیمی سے، انہوں نے حضرت انس بن مالک رضی اللہ عنہ سے، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے کئی اشیاء سے، جن کا انہوں نے ذکر کیا اور بخل سے اللہ کی پناہ طلب کی۔"}],[6932,"شعیب بن حبحاب نے سیدنا انس رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم یہ دعائیں مانگا کرتے تھے : \" اے اللہ! میں بخل ، سستی ، ذلیل ترین عمر ، قبر کے عذاب اور زندگی اور موت کی آزمائشوں سے تیری پناہ میں آتا ہوں ۔","",{"u2":"شعیب بن حبحاب نے حضرت انس رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم یہ دعائیں مانگا کرتے تھے: \"اے اللہ! میں بخل، سستی، ذلیل ترین عمر، قبر کے عذاب اور زندگی اور موت کی آزمائشوں سے تیری پناہ میں آتا ہوں۔\""}],[6933,"عمرو ناقد اور زُہیر بن حرب نے مجھے حدیث بیان کی ، انہوں نے کہا : ہمیں سفیان بن عیینہ نے حدیث بیان کی ، انہوں نے کہا : مجھے سُمی نے ابوصالح سے حدیث بیان کی ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم انسان کے حق میں برا ثابت ہونے والے فیصلے ، بدبختی کے آ لینے ، اپنی تکلیف پر دشمنوں کے خوش ہونے اور عاجز کر دینے والی آزمائش سے پناہ مانگا کرتے تھے ۔ عمرو نے اپنی حدیث ( کی سند ) میں کہا : سفیان نے کہا : مجھے شک ہے کہ ( شاید ) میں نے ان باتوں میں سے کوئی ایک بات بڑھا دی ہے ۔","",{"u2":") عمرو ناقد اور زُہیر بن حرب نے مجھے حدیث بیان کی، انہوں نے کہا: ہمیں سفیان بن عیینہ نے حدیث بیان کی، انہوں نے کہا: مجھے سُمی نے ابوصالح سے حدیث بیان کی، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم انسان کے حق میں برا ثابت ہونے والے فیصلے، بدبختی کے آ لینے، اپنی تکلیف پر دشمنوں کے خوش ہونے اور عاجز کر دینے والی آزمائش سے پناہ مانگا کرتے تھے۔\nعمرو نے اپنی حدیث (کی سند) میں کہا: سفیان نے کہا: مجھے شک ہے کہ (شاید) میں نے ان باتوں میں سے کوئی ایک بات بڑھا دی ہے۔"}],[6934,"لیث نے یزید بن ابی حبیب سے اور انہون نے حارث بن یعقوب سے روایت کی کہ یعقوب بن عبداللہ نے انہیں حدیث سنائی ، انہوں نے بسر بن سعید کو یہ کہتے ہوئے سنا ، میں نے سعد بن ابی وقاص رضی اللہ عنہ کو کہتے ہوئے سنا ، کہا : میں نے سیدہ خولہ بنت حکیم سلمیہ سے سنا ، وہ کہتی تھیں : میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا : \" جو شخص کسی ( بھی ) منزل پر اترا اور اس نے یہ کلمات کہے : میں اللہ ( سے اس ) کے مکمل ترین کلمات کی پناہ طلب کرتا ہوں ہر اس چیز کے شر سے جو اس نے پیدا کی ، تو اس شخص کو اس منزل سے چلے جانے تک کوئی چیز نقصان نہیں پہنچائے گی ۔","",{"u2":"لیث نے یزید بن ابی حبیب سے اور انہون نے حارث بن یعقوب سے روایت کی کہ یعقوب بن عبداللہ نے انہیں حدیث سنائی، انہوں نے بسر بن سعید کو یہ کہتے ہوئے سنا، میں نے سعد بن ابی وقاص رضی اللہ عنہ کو کہتے ہوئے سنا، کہا: میں نے حضرت خولہ بنت حکیم سلمیہ سے سنا، وہ کہتی تھیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا: \"جو شخص کسی (بھی) منزل پر اترا اور اس نے یہ کلمات کہے: میں اللہ (سے اس) کے مکمل ترین کلمات کی پناہ طلب کرتا ہوں ہر اس چیز کے شر سے جو اس نے پیدا کی، تو اس شخص کو اس منزل سے چلے جانے تک کوئی چیز نقصان نہیں پہنچائے گی۔\""}],[6935,"عبداللہ بن وہب نے کہا : ہمیں عمرو بن حارث نے خبر دی کہ یزید بن ابی حبیب اور حارث بن یعقوب نے انہیں یعقوب بن عبداللہ بن اشج سے حدیث بیان کی ، انہوں نے بسر بن سعید سے ، انہوں نے سعد بن ابی وقاص رضی اللہ عنہ سے اور انہوں نے سیدہ خولہ بنت حکیم سلمیہ سے روایت کی ، انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا : \" تم میں سے کوئی شخص جب کسی منزل پر پہنچے تو یہ کلمات کہے : \" میں ہر اس چیز کے شر سے جو اللہ نے پیدا کی ، اس نے مکمل ترین کلمات کی پناہ میں آتا ہوں ، اس طرح وہاں سے کوچ کر جانے تک کوئی بھی چیز اسے نقصان نہیں پہنچائے گی ۔","",{"u2":"عبداللہ بن وہب نے کہا: ہمیں عمرو بن حارث نے خبر دی کہ یزید بن ابی حبیب اور حارث بن یعقوب نے انہیں یعقوب بن عبداللہ بن اشج سے حدیث بیان کی، انہوں نے بسر بن سعید سے، انہوں نے سعد بن ابی وقاص رضی اللہ عنہ سے اور انہوں نے حضرت خولہ بنت حکیم سلمیہ سے روایت کی، انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا: \"تم میں سے کوئی شخص جب کسی منزل پر پہنچے تو یہ کلمات کہے: \"میں ہر اس چیز کے شر سے جو اللہ نے پیدا کی، اس نے مکمل ترین کلمات کی پناہ میں آتا ہوں، اس طرح وہاں سے کوچ کر جانے تک کوئی بھی چیز اسے نقصان نہیں پہنچائے گی۔\""}],[6936,"عبداللہ بن وہب نے کہا : ہمیں عمرو بن حارث نے خبر دی کہ یزید بن ابی حبیب اور حارث بن یعقوب نے انہیں یعقوب بن عبداللہ بن اشج سے حدیث بیان کی ، انہوں نے بسر بن سعید سے ، انہوں نے سعد بن ابی وقاص رضی اللہ عنہ سے اور انہوں نے سیدہ خولہ بنت حکیم سلمیہ سے روایت کی ، انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا : \" تم میں سے کوئی شخص جب کسی منزل پر پہنچے تو یہ کلمات کہے : \" میں ہر اس چیز کے شر سے جو اللہ نے پیدا کی ، اس نے مکمل ترین کلمات کی پناہ میں آتا ہوں ، اس طرح وہاں سے کوچ کر جانے تک کوئی بھی چیز اسے نقصان نہیں پہنچائے گی ۔","",{"u2":"یعقوب نے کہا: قعقاع بن حکیم نے ذوان سے، انہوں نے ابوصالح سے اور انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ انہوں نے کہا: ایک شخص نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور عرض کی: اللہ کے رسول! مجھے اس بچھو سے کتنی شدید تکلیف پہنچی جس نے کل رات مجھے کاٹ لیا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر تم نے جب رات کی تھی، یہ (کلمات) کہہ دیتے: میں ہر اس چیز کے شر سے جسے اللہ نے پیدا کیا، اس کے کامل ترین کلمات کی پناہ میں آتا ہوں تو وہ (بچھو) تمہیں کوئی نقصان نہ پہنچاتا۔\""}],[6937,"لیث نے یزید بن ابی حبیب سے ، انہوں نے جعفر سے ، انہوں نے یعقوب سے روایت کی ، انہوں نے ان کو بتایا کہ غطفان کے آزاد کردہ غلام ابوصالح نے انہیں بتایا ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے سنا ، کہتے تھے ایک شخص نے کہا : اللہ کے رسول! مجھے بچھو نے کاٹ لیا ۔ ( آگے ) ابن وہب کی حدیث کے مانند ہے ۔","",{"u2":"لیث نے یزید بن ابی حبیب سے، انہوں نے جعفر سے، انہوں نے یعقوب سے روایت کی، انہوں نے ان کو بتایا کہ غطفان کے آزاد کردہ غلام ابوصالح نے انہیں بتایا، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے سنا، کہتے تھے ایک شخص نے کہا: اللہ کے رسول! مجھے بچھو نے کاٹ لیا۔ (آگے) ابن وہب کی حدیث کے مانند ہے۔"}],[6938,"منصور نے سعد بن عبیدہ سے روایت کی ، انہوں نے کہا : مجھے سیدنا براء بن عازب رضی اللہ عنہ نے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" جب تم اپنے بستر پر جانے لگو تو اپنی نماز کے وضو کی طرح وضو کرو ، پھر اپنی دائیں کروٹ لیٹو ، پھر یہ کہو : \"\" اے اللہ! میں نے اپنا چہرہ تیرے سپرد کر دیا اور اپنا معاملہ تیرے حوالے کر دیا اور اپنی کمر تیرے سہارے پر ٹکا دی ، یہ سب سے امید اور تیرے خوف کے ساتھ کیا ۔ تیرے سوا تجھ سے نہ کہیں پناہ مل سکتی ہے ، نہ نجات حاصل ہو سکتی ہے ۔ میں تیری کتاب پر ایمان لایا جو تو نے نازل کی اور تیرے نبی پر ایمان لایا جسے تو نے مبعوث کیا ۔ ان کلمات کو تم ( اپنی زبان سے ادا ہونے والے ) آخری کلمات بنا لو ( ان کے بعد اور کچھ نہ بولو ) تو اس رات اگر تمہیں موت آ گئی تو فطرت پر موت آئے گی ۔ \"\" ( سیدنا براء بن عازب رضی اللہ عنہ نے ) کہا : میں نے ان کلمات کو یاد کرنے کے لیے انہیں دہرایا تو کہا : \"\" میں تیرے رسول پر ایمان لایا جسے تو نے بھیجا \"\" تو آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" ( یوں ) کہو : میں تیرے نبی پر ایمان لایا جسے تو نے بھیجا ۔","",{"u2":"منصور نے سعد بن عبیدہ سے روایت کی، انہوں نے کہا: مجھے حضرت براء بن عازب رضی اللہ عنہ نے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \" جب تم اپنے بستر پر جانے لگو تو اپنی نماز کے وضو کی طرح وضو کرو، پھر اپنی دائیں کروٹ لیٹو، پھر یہ کہو: \"اے اللہ! میں نے اپنا چہرہ تیرے سپرد کر دیا اور اپنا معاملہ تیرے حوالے کر دیا اور اپنی کمر تیرے سہارے پر ٹکا دی، یہ سب سے امید اور تیرے خوف کے ساتھ کیا۔ تیرے سوا تجھ سے نہ کہیں پناہ مل سکتی ہے، نہ نجات حاصل ہو سکتی ہے۔ میں تیری کتاب پر ایمان لایا جو تو نے نازل کی اور تیرے نبی پر ایمان لایا جسے تو نے مبعوث کیا۔ ان کلمات کو تم (اپنی زبان سے ادا ہونے والے) آخری کلمات بنا لو (ان کے بعد اور کچھ نہ بولو) تو اس رات اگر تمہیں موت آ گئی تو فطرت پر موت آئے گی۔\"\n(حضرت براء بن عازب رضی اللہ عنہ نے) کہا: میں نے ان کلمات کو یاد کرنے کے لیے انہیں دہرایا تو کہا: \"میں تیرے رسول پر ایمان لایا جسے تو نے بھیجا\" تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"(یوں) کہو: میں تیرے نبی پر ایمان لایا جسے تو نے بھیجا۔\""}],[6939,"حُصین بن سعد بن عبیدہ سے ، انہوں نے سیدنا براء بن عازب رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے یہ حدیث روایت کی ، مگر منصور نے زیادہ مکمل حدیث بیان کی اور حصین کی حدیث میں یہ اضافہ کیا : \" اگر یہ ( کہنے والا ) صبح کرے گا تو خیر حاصل کرے گا ۔","",{"u2":"حُصین بن سعد بن عبیدہ سے، انہوں نے حضرت براء بن عازب رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے یہ حدیث روایت کی، مگر منصور نے زیادہ مکمل حدیث بیان کی اور حصین کی حدیث میں یہ اضافہ کیا: \"اگر یہ (کہنے والا) صبح کرے گا تو خیر حاصل کرے گا۔\""}],[6940,"محمد بن مثنی نے ابوداود سے اور ابن بشار نے عبدالرحمٰن اور ابوداود دونوں سے روایت کی ، دونوں نے کہا : ہمیں شعبہ نے عمروہ بن مرہ سے حدیث سنائی ، انہوں نے کہا : میں نے سعد بن عبیدہ سے سنا ، وہ سیدنا براء بن عازب رضی اللہ عنہ سے روایت کر رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص کو حکم دیا کہ جب وہ رات کو اپنی خواب گاہ میں جانے لگے تو ( دعا کرتے ہوئے ) یہ کہے : \" اے اللہ! میں نے اپنی جان تیرے سپرد کر دی اور اپنا چہرہ تیری طرف متوجہ کر لیا اور اپنی کمر تیرے سہارے پر ٹکا دی اور اپنا معاملہ تیرے حوالے کر دیا ، یہ سب تجھی سے امید کرتے ہوئے اور تجھی سے ڈرتے ہوئے کیا ۔ تجھ سے خوف تیرے سوا نہ پناہ کی کوئی جگہ ہے نہ نجات کی ۔ میں تیری کتاب پر ایمان لایا جو تو نے نازل کی اور تیرے رسول پر ایمان لایا جسے تو نے بھیجا ، پھر اگر ( اس رات ) اسے موت آ گئی تو فطرت پر موت آئے گی ۔ \" ابن بشار نے اپنی حدیث میں : \" رات کے وقت \" ( بستر پر جانے لگے ) کے الفاظ نہیں کہے ۔","",{"u2":"محمد بن مثنیٰ نے ابوداود سے اور ابن بشار نے عبدالرحمٰن اور ابوداود دونوں سے روایت کی، دونوں نے کہا: ہمیں شعبہ نے عمروہ بن مرہ سے حدیث سنائی، انہوں نے کہا: میں نے سعد بن عبیدہ سے سنا، وہ حضرت براء بن عازب رضی اللہ عنہ سے روایت کر رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص کو حکم دیا کہ جب وہ رات کو اپنی خواب گاہ میں جانے لگے تو (دعا کرتے ہوئے) یہ کہے: \"اے اللہ! میں نے اپنی جان تیرے سپرد کر دی اور اپنا چہرہ تیری طرف متوجہ کر لیا اور اپنی کمر تیرے سہارے پر ٹکا دی اور اپنا معاملہ تیرے حوالے کر دیا، یہ سب تجھی سے امید کرتے ہوئے اور تجھی سے ڈرتے ہوئے کیا۔ تجھ سے خوف تیرے سوا نہ پناہ کی کوئی جگہ ہے نہ نجات کی۔ میں تیری کتاب پر ایمان لایا جو تو نے نازل کی اور تیرے رسول پر ایمان لایا جسے تو نے بھیجا، پھر اگر (اس رات) اسے موت آ گئی تو فطرت پر موت آئے گی۔\" ابن بشار نے اپنی حدیث میں: \"رات کے وقت\" (بستر پر جانے لگے) کے الفاظ نہیں کہے۔"}],[6941,"ابو احوص نے ابواسحٰق سے اور انہوں نے سیدنا براء بن عازب رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص سے فرمایا : \" اے فلاں! جب تم اپنے بستر پر لیٹنے لگو ۔ ۔ ۔ \" اس کے بعد عمرو بن مرہ کی حدیث کے مانند ہے ۔ ( مگر ابو احوص نے منصور کی روایت کی طرح ) یہ الفاظ کہے : \" ( اور میں ایمان لایا ) تیرے نبی پر جسے تو نے بھیجا ، پھر اگر تم اس رات مر گئے تو ( عین ) فطرت پر مرو گے اور اگر تم نے ( زندہ حالت میں ) صبح کر لی تو خیر ( و بھلائی ) حاصل کرو گے ۔","",{"u2":"ابو احوص نے ابواسحٰق سے اور انہوں نے حضرت براء بن عازب رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص سے فرمایا: \"اے فلاں! جب تم اپنے بستر پر لیٹنے لگو۔۔۔\" اس کے بعد عمرو بن مرہ کی حدیث کے مانند ہے۔ (مگر ابو احوص نے منصور کی روایت کی طرح) یہ الفاظ کہے: \"(اور میں ایمان لایا) تیرے نبی پر جسے تو نے بھیجا، پھر اگر تم اس رات مر گئے تو (عین) فطرت پر مرو گے اور اگر تم نے (زندہ حالت میں) صبح کر لی تو خیر (و بھلائی) حاصل کرو گے۔\""}],[6942,"شعبہ نے ابواسحٰق سے روایت کی کہ انہوں نے سیدنا براء بن عازب رضی اللہ عنہ کو کہتے ہوئے سنا : رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص کو حکم دیا ، اسی کے مانند ، اور انہوں نے \" اگر تم نے ( زندہ حالت میں ) صبح کی تو خیر حاصل کرو گے \" کے الفاظ بیان نہیں کیے ۔","",{"u2":"شعبہ نے ابواسحٰق سے روایت کی کہ انہوں نے حضرت براء بن عازب رضی اللہ عنہ کو کہتے ہوئے سنا: رسول اللہ صلی اللہ علیہ وسلم نے ایک شخص کو حکم دیا، اسی کے مانند، اور انہوں نے \"اگر تم نے (زندہ حالت میں) صبح کی تو خیر حاصل کرو گے\" کے الفاظ بیان نہیں کیے۔"}],[6943,"سیدنا براء بن عازب رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم جب بستر پر تشریف لے جاتے تو یہ دعا کرتے : \" اے اللہ! میں تیرے نام سے جیتا ہوں اور تیرے نام سے وفات پاؤں گا \" اور جب بیدار ہوتے تو فرماتے : \" اللہ کی حمد ہے جس نے ہمیں وفات دینے کے بعد زندہ کر دیا اور اسی کی طرف ( قیامت کے روز ) زندہ ہو کر جاتا ہے ۔","",{"u2":"حضرت براء بن عازب رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم جب بستر پر تشریف لے جاتے تو یہ دعا کرتے: \"اے اللہ! میں تیرے نام سے جیتا ہوں اور تیرے نام سے وفات پاؤں گا\" اور جب بیدار ہوتے تو فرماتے: \"اللہ کی حمد ہے جس نے ہمیں وفات دینے کے بعد زندہ کر دیا اور اسی کی طرف (قیامت کے روز) زندہ ہو کر جاتا ہے۔\""}],[6944,"عقبہ بن مُکرم اور ابوبکر بن نافع نے کہا : ہمیں غندر نے حدیث بیان کی ، انہوں نے کہا : ہمیں شعبہ نے خالد سے حدیث سنائی ، انہوں نے کہا : میں نے عبداللہ بن حارث کو سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت کرتے ہوئے سنا ، انہوں نے ایک شخص سے کہا کہ جب وہ اپنے بستر پر جائے تو یہ دعا کرے : \"\" اے اللہ! میری جان کو تو نے پیدا کیا اور تو ہی اس کو موت دے گا ، اس جان کی موت بھی اور زندگی بھی تیرے ہی لیے ہے ، اگر تو اس کو زندہ رکھے تو اس کی حفاظت فرمانا اور اگر تو اس کو موت دے تو اس کی مغفرت کرنا ، اے اللہ! میں تجھ سے عافیت مانگتا ہوں ۔ \"\" ایک شخص نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے پوچھا : کیا آپ نے یہ حدیث سیدنا عمر رضی اللہ عنہ سے سنی ہے؟ انہوں نے کہا : ان سے جو سیدنا عمر سے زیادہ افضل ہیں ( میں نے یہ حدیث ) رسول اللہ صلی اللہ علیہ وسلم سے ( سنی ہے ۔ ) ابن نافع نے اپنی روایت میں کہا : عبداللہ بن حارث سے روایت ہے ، یہ نہیں کہا : میں نے سنا ۔","",{"u2":"عقبہ بن مُکرم اور ابوبکر بن نافع نے کہا: ہمیں غندر نے حدیث بیان کی، انہوں نے کہا: ہمیں شعبہ نے خالد سے حدیث سنائی، انہوں نے کہا: میں نے عبداللہ بن حارث کو حضرت عبداللہ بن عمر رضی اللہ عنہ سے روایت کرتے ہوئے سنا، انہوں نے ایک شخص سے کہا کہ جب وہ اپنے بستر پر جائے تو یہ دعا کرے: \"اے اللہ! میری جان کو تو نے پیدا کیا اور تو ہی اس کو موت دے گا، اس جان کی موت بھی اور زندگی بھی تیرے ہی لیے ہے، اگر تو اس کو زندہ رکھے تو اس کی حفاظت فرمانا اور اگر تو اس کو موت دے تو اس کی مغفرت کرنا، اے اللہ! میں تجھ سے عافیت مانگتا ہوں۔\" ایک شخص نے حضرت عبداللہ بن عمر رضی اللہ عنہ سے پوچھا: کیا آپ نے یہ حدیث حضرت عمر رضی اللہ عنہ سے سنی ہے؟ انہوں نے کہا: ان سے جو حضرت عمر سے زیادہ افضل ہیں (میں نے یہ حدیث) رسول اللہ صلی اللہ علیہ وسلم سے (سنی ہے۔)\nابن نافع نے اپنی روایت میں کہا: عبداللہ بن حارث سے روایت ہے، یہ نہیں کہا: میں نے سنا۔"}],[6945,"جریر نے سہیل سے روایت کی ، انہوں نے کہا : ( میرے والد ) ابوصالح ہمیں حکم دیا کرتے تھے کہ جب ہم میں سے کوئی شخص سونے کا ارادہ کرے تو بستر پر دائیں کروٹ لیٹے ، پھر دعا کرے : اے اللہ! اے آسمانوں کے رب اور زمین کے رب اور عرش عظیم کے رب ، اے ہمارے رب اور ہر چیز کے رب ، دانے اور گٹھلیوں کو چیر ( کر پودے اور درخت اگا ) دینے والے! تورات ، انجیل اور فرقان کو نازل کرنے والے! میں ہر اس چیز کے شر سے تیری پناہ میں آتا ہوں جس کی پیشانی تیرے قبضے میں ہے ، اے اللہ! تو ہی اول ہے ، تجھ سے پہلے کوئی شے نہیں ، اے اللہ! تو ہی آخر ہے ، تیرے بعد کوئی شے نہیں ہے ، تو ہی ظاہر ہے ، تیرے اوپر کوئی شے نہیں ہے ، تو ہی باطن ہے ، تجھ سے پیچھے کوئی شے نہیں ہے ، ہماری طرف سے ( ہمارا ) قرض ادا کر اور ہمیں فقر سے غنا عطا فرما ۔ وہ اس حدیث کو ابوہریرہ رضی اللہ عنہ سے اور وہ ( آگے ) اسے رسول اللہ صلی اللہ علیہ وسلم سے روایت کرتے تھے ۔","",{"u2":"جریر نے سہیل سے روایت کی، انہوں نے کہا: (میرے والد) ابوصالح ہمیں حکم دیا کرتے تھے کہ جب ہم میں سے کوئی شخص سونے کا ارادہ کرے تو بستر پر دائیں کروٹ لیٹے، پھر دعا کرے: \"اے اللہ! اے آسمانوں کے رب اور زمین کے رب اور عرش عظیم کے رب، اے ہمارے رب اور ہر چیز کے دب، دانے اور کٹھلیوں کو چیز (کر پودے اور درخت اگا) دینے والے! تورات، انجیل اور فرقان کو نازل کرنے والے! میں ہر اس چیز کے شر سے تیری پناہ میں آتا ہوں جس کی پیشانی تیرے قبضے میں ہے، اے اللہ! تو ہی اول ہے، تجھ سے پہلے کوئی شے نہیں، اے اللہ! تو ہی آخر ہے، تیرے بعد کوئی شے نہیں ہے، تو ہی ظاہر ہے، تیرے اوپر کوئی شے نہیں ہے، تو ہی باطل ہے، تجھ سے پیچھے کوئی شے نہیں ہے، ہماری طرف سے (ہمارا) قرض ادا کر اور ہمیں فقر سے غنا عطا فرما۔\" وہ اس حدیث کو ابوہریرہ رضی اللہ عنہ سے اور وہ (آگے) اسے رسول اللہ صلی اللہ علیہ وسلم سے روایت کرتے تھے۔"}],[6946,"خالد طحان نے سہیل سے ، انہوں نے اپنے والد سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم ہمیں یہ حکم دیا کرتے تھے کہ جب ہم اپنے بستروں پر لیٹیں تو یہ دعا کریں ، جریر کی حدیث کے مانند ( اور خالد طحان نے \" ہر اس چیز کے شر سے \" کے بجائے ) کہا : \" ہر اس جاندار کے شر سے ( تیری پناہ چاہتا ہوں ) جسے تو نے اس کی پیشانی سے پکڑا ہوا ہے ۔","",{"u2":"خالد طحان نے سہیل سے، انہوں نے اپنے والد سے اور انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم ہمیں یہ حکم دیا کرتے تھے کہ جب ہم اپنے بستروں پر لیٹیں تو یہ دعا کریں، جریر کی حدیث کے مانند (اور خالد طحان نے \"ہر اس چیز کے شر سے\" کے بجائے) کہا: \"ہر اس جاندار کے شر سے (تیری پناہ چاہتا ہوں) جسے تو نے اس کی پیشانی سے پکڑا ہوا ہے۔\""}],[6947,"اعمش نے ابوصالح سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : سیدہ فاطمہ رضی اللہ عنہا نبی صلی اللہ علیہ وسلم کے پاس ایک خادم مانگنے کے لیے آئیں تو آپ صلی اللہ علیہ وسلم نے ( جواب میں ) ان سے کہا : \" ( بیٹی! ) تم کہا کرو : اے اللہ! ساتوں آسمانوں کے رب! \" جس طرح سہیل نے اپنے والد ( ابوصالح ) سے روایت کی ۔","",{"u2":"اعمش نے ابوصالح سے اور انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: حضرت فاطمہ رضی اللہ عنہا نبی صلی اللہ علیہ وسلم کے پاس ایک خادم مانگنے کے لیے آئیں تو آپ صلی اللہ علیہ وسلم نے (جواب میں) ان سے کہا: \"(بیٹی!) تم کہا کرو: اے اللہ! ساتوں آسمانوں کے رب!\" جس طرح سہیل نے اپنے والد (ابوصالح) سے روایت کی۔"}],[6948,"انس بن عیاض نے کہا : ہمیں عبیداللہ نے حدیث بیان کی ، انہوں نے کہا : مجھے سعید بن ابی سعید مقبری نے اپنے والد سے حدیث بیان کی ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جب تم میں سے کوئی شخص اپنے بستر پر لیٹنا چاہے تو اپنے تہبند کا اندرونی حصہ لے کر اس سے اپنے بستر کو جھاڑے ، پھر بسم اللہ کہے کیونکہ وہ نہیں جانتا کہ اس ( کے اٹھ جانے ) کے بعد اس کے بستر پر ( مخلوقات میں سے ) کون آیا؟ پھر جب لیٹنا چاہے تو اپنی دائیں کروٹ لیٹے اور کہے : \" میرے پروردگار! تو ( ہر نا شایان بات سے ) پاک ہے ، میں نے تیرے ( حکم ) سے اپنا پہلو ( بستر پر ) رکھا اور تیرے ہی حک سے اسے اٹھاؤں گا اگر تو نے میری روح کو ( اپنے پاس ) روک لیا تو اس کی مغفرت کر دینا اور اگر تو نے اسے ( واپس ) بھیج دیا تو اس کی اسی طرح حفاظت فرمانا جس طرح تو اپنے نیک بندوں کی حفاظت فرماتا ہے ۔","",{"u2":"انس بن عیاض نے کہا: ہمیں عبیداللہ نے حدیث بیان کی، انہوں نے کہا: مجھے سعید بن ابی سعید مقبری نے اپنے والد سے حدیث بیان کی، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی شخص اپنے بستر پر لیٹنا چاہے تو اپنے تہبند کا اندرونی حصہ لے کر اس سے اپنے بستر کو جھاڑے، پھر بسم اللہ کہے کیونکہ وہ نہیں جانتا کہ اس (کے اٹھ جانے) کے بعد اس کے بستر پر (مخلوقات میں سے) کون آیا؟ پھر جب لیٹنا چاہے تو اپنی دائیں کروٹ لیٹے اور کہے: \"میرے پروردگار! تو (ہر نا شایان بات سے) پاک ہے، میں نے تیرے (حکم) سے اپنا پہلو (بستر پر) رکھا اور تیرے ہی حک سے اسے اٹھاؤں گا اگر تو نے میری روح کو (اپنے پاس) روک لیا تو اس کی مغفرت کر دینا اور اگر تو نے اسے (واپس) بھیج دیا تو اس کی اسی طرح حفاظت فرمانا جس طرح تو اپنے نیک بندوں کی حفاظت فرماتا ہے۔\""}],[6949,"عبدہ نے عبیداللہ بن عمر سے اسی سند کے ساتھ یہی حدیث روایت کی اور کہا : \" پھر وہ یہ ہے : تیرے نام سے اے پروردگار! میں نے اپنا پہلو ٹکایا ، اگر تو نے میری جان کو زندہ کیا تو اس پر رحمت فرمانا ۔","",{"u2":"عبدہ نے عبیداللہ بن عمر سے اسی سند کے ساتھ یہی حدیث روایت کی اور کہا: \"پھر وہ یہ ہے: تیرے نام سے اے پروردگار! میں نے اپنا پہلو ٹکایا، اگر تو نے میری جان کو زندہ کیا تو اس پر رحمت فرمانا۔\""}],[6950,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب بستر پر جاتے تو فرماتے : \" اللہ تعالی کی حمد ہے جس نے ہمیں کھلایا ، پلایا ، ( ہر طرح سے ) کافی ہوا اور ہمیں ٹھکانا دیا ۔ کتنے لوگ ہیں جن کا نہ کوئی کفایت کرنے والا ہے نہ ٹھکانہ دینے والا ۔","",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب بستر پر جاتے تو فرماتے: \"اللہ تعالیٰ کی حمد ہے جس نے ہمیں کھلایا، پلایا، (ہر طرح سے) کافی ہوا اور ہمیں ٹھکانا دیا۔ کتنے لوگ ہیں جن کا نہ کوئی کفایت کرنے والا ہے نہ ٹھکانہ دینے والا۔\""}],[6951,"منصور نے ہلال سے اور انہوں نے فروہ بن نوفل اشجعی سے روایت کی ، کہا : میں نے ام المومنین سیدہ عائشہ رضی اللہ عنہا سے سوال کیا کہ رسول اللہ صلی اللہ علیہ وسلم اللہ تعالی سے کیا دعائیں کیا کرتے تھے؟ سیدہ عائشہ رضی اللہ عنہا نے کہا : آپ صلی اللہ علیہ وسلم دعا کیا کرتے تھے : \" اے اللہ! جو میں نے کیا اس کے شر سے اور جو میں نے نہیں کیا ، اس کے شر سے تیری پناہ میں آتا ہوں ۔","",{"u2":"منصور نے ہلال سے اور انہوں نے فروہ بن نوفل اشجعی سے روایت کی، کہا: میں نے ام المومنین حضرت عائشہ رضی اللہ عنہا سے سوال کیا کہ رسول اللہ صلی اللہ علیہ وسلم اللہ تعالیٰ سے کیا دعائیں کیا کرتے تھے؟ حضرت عائشہ رضی اللہ عنہا نے کہا: آپ صلی اللہ علیہ وسلم دعا کیا کرتے تھے: \"اے اللہ! جو میں نے کیا اس کے شر سے اور جو میں نے نہیں کیا، اس کے شر سے تیری پناہ میں آتا ہوں۔\""}],[6952,"عبداللہ بن ادریس نے حصین سے ، انہوں نے ہلال سے اور انہوں نے فروہ بن نوفل سے روایت کی ، کہا : میں نے سیدہ عائشہ رضی اللہ عنہا سے سوال کیا کہ رسول اللہ صلی اللہ علیہ وسلم کیا دعا فرمایا کرتے تھے؟ سیدہ عائشہ رضی اللہ عنہا نے کہا : آپ یہ دعا فرمایا کرتے تھے : \" اے اللہ! میں نے جو کام کیے ہیں ، ان کے شر سے اور جو کام میں نے نہیں کیے ، ان کے شر سے تیری پناہ چاہتا ہوں ۔","",{"u2":"عبداللہ بن ادریس نے حصین سے، انہوں نے ہلال سے اور انہوں نے فروہ بن نوفل سے روایت کی، کہا: میں نے حضرت عائشہ رضی اللہ عنہا سے سوال کیا کہ رسول اللہ صلی اللہ علیہ وسلم کیا دعا فرمایا کرتے تھے؟ حضرت عائشہ رضی اللہ عنہا نے کہا: آپ یہ دعا فرمایا کرتے تھے: \"اے اللہ! میں نے جو کام کیے ہیں، ان کے شر سے اور جو کام میں نے نہیں کیے، ان کے شر سے تیری پناہ چاہتا ہوں۔\""}],[6953,"ابن ابی عدی اور محمد بن جعفر دونوں نے شعبہ سے اور انہوں نے حصین سے اسی سند کے ساتھ اسی کے مانند روایت کی ، مگر محمد بن جعفر کی حدیث میں ( وشر ما لم اعمل کے بجائے ) و من شر ما لم اعمل ہے ۔","",{"u2":"ابن ابی عدی اور محمد بن جعفر دونوں نے شعبہ سے اور انہوں نے حصین سے اسی سند کے ساتھ اسی کے مانند روایت کی، مگر محمد بن جعفر کی حدیث میں (وشر ما لم اعمل کے بجائے) و من شر ما لم اعمل ہے۔"}],[6954,"عبدہ بن ابولبابہ نے ہلال بن سیاف سے ، انہوں نے فروہ بن نوفل سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی کہ نبی صلی اللہ علیہ وسلم اپنی دعا میں فرماتے تھے : \" اے اللہ! میں ان کاموں کے شر سے جو میں نے کیے اور ان کے شر سے جو نہیں کیے ، تیری پناہ میں آتا ہوں ۔","",{"u2":"عبدہ بن ابولبابہ نے ہلال بن سیاف سے، انہوں نے فروہ بن نوفل سے اور انہوں نے حضرت عائشہ رضی اللہ عنہا سے روایت کی کہ نبی صلی اللہ علیہ وسلم اپنی دعا میں فرماتے تھے: \"اے اللہ! میں ان کاموں کے شر سے جو میں نے کیے اور ان کے شر سے جو نہیں کیے، تیری پناہ میں آتا ہوں۔\""}],[6955,"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم ( دعا کرتے ہوئے ) فرمایا کرتے تھے : \" اے اللہ! میں تیرے لیے فرمانبردار ہو گیا ، تیرے ساتھ ایمان لایا ، تجھ پر بھروسہ کیا ، تیری طرف رجوع کیا اور تیری مدد سے ( کفر کے ساتھ ) مخاصمت کی ۔ اے اللہ! میں اس بات سے تیری عزت کی پناہ لیتا ہوں ۔ ۔ تیرے سوا کوئی معبود نہیں ۔ ۔ کہ تو مجھے سیدھی راہ سے ہٹا دے ۔ ۔ تو ہی ہمیشہ زندہ رہنے والا ہے جس کو موت نہیں آ سکتی اور جن و انس سب مر جائیں گے ۔","",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم (دعا کرتے ہوئے) فرمایا کرتے تھے: \"اے اللہ! میں تیرے لیے فرمانبردار ہو گیا، تیرے ساتھ ایمان لایا، تجھ پر بھروسہ کیا، تیری طرف رجوع کیا اور تیری مدد سے (کفر کے ساتھ) مخاصمت کی۔ اے اللہ! میں اس بات سے تیری عزت کی پناہ لیتا ہوں۔۔ تیرے سوا کوئی معبود نہیں۔۔ کہ تو مجھے سیدھی راہ سے ہٹا دے۔۔ تو ہی ہمیشہ زندہ رہنے والا ہے جس کو موت نہیں آ سکتی اور جن و انس سب مر جائیں گے۔\""}],[6956,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم جب کسی سفر میں ہوتے اور سحر کے وقت اٹھتے تو فرماتے : \" ( ہماری طرف سے ) اللہ کی حمد اور اس کے انعام کی خوبصورتی ( کے اعتراف ) کا سننے والا یہ بات دوسروں کو بھی سنا دے ۔ اے ہمارے رب! ہمارے ساتھ رہ ، ہم پر احسان کر ، میں آگ سے اللہ کی پناہ مانگتے ہوئے یہ دعا کر رہا ہوں ۔","",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم جب کسی سفر میں ہوتے اور سحر کے وقت اٹھتے تو فرماتے: \"(ہماری طرف سے) اللہ کی حمد اور اس کے انعام کی خوبصورتی (کے اعتراف) کا سننے والا یہ بات دوسروں کو بھی سنا دے۔ اے ہمارے رب! ہمارے ساتھ رہ، ہم پر احسان کر، میں آگ سے اللہ کی پناہ مانگتے ہوئے یہ دعا کر رہا ہوں۔\""}],[6957,"معاذ عنبری نے کہا : ہمیں شعبہ نے ابواسحٰق سے حدیث بیان کی ، انہوں نے ابوبردہ بن ابوموسی اشعری سے ، انہوں نے اپنے والد سیدنا ابوموسی اشعری رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ یہ دعا فرمایا کرتے تھے : \" اے اللہ! میری خطاء میری لا علمی ، اپنے ( کسی ) معاملے میں میرا حد سے آگے یا پیچھے رہ جانا اور وہ سب کچھ جو میری نسبت تو زیادہ جانتا ہے سب معاف فرما دے ۔ اے اللہ! میرے وہ سب کام جو ( تجھے پسند نہ آئے ہوں ) میں نے سنجیدگی سے کیے ہوں یا مزاحا کیے ہوں ، بھول چوک کر کیے ہوں یا جان بوجھ کر کیے ہوں اور یہ سب مجھ سے ہوئے ہوں ، ان کو بخش دے ۔ اے اللہ! میری وہ باتیں ( جو تجھے پسند نہیں آئیں ) بخش دے جو میں نے پہلے کیں یا جو میں نے بعد میں کیں ، اکیلے میں کیں یا جو میں نے سب کے سامنے کیں اور جنہیں تو مجھ سے زیادہ جاننے والا ہے ، تو ہی ( جسے چاہے اپنی رحمت کی طرف ) آگے بڑھانے والا ہے اور تو ہی پیچھے کرنے والا ہے اور تو ہر چیز پر قادر ہے ۔","",{"u2":"معاذ عنبری نے کہا: ہمیں شعبہ نے ابواسحٰق سے حدیث بیان کی، انہوں نے ابوبردہ بن ابوموسیٰ اشعری سے، انہوں نے اپنے والد حضرت ابوموسیٰ اشعری رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ یہ دعا فرمایا کرتے تھے: \"اے اللہ! میری خطاء میری لا علمی، اپنے (کسی) معاملے میں میرا حد سے آگے یا پیچھے رہ جانا اور وہ سب کچھ جو میری نسبت تو زیادہ جانتا ہے سب معاف فرما دے۔ اے اللہ! میرے وہ سب کام جو (تجھے پسند نہ آئے ہوں) میں نے سنجیدگی سے کیے ہوں یا مزاحا کیے ہوں، بھول چوک کر کیے ہوں یا جان بوجھ کر کیے ہوں اور یہ سب مجھ سے ہوئے ہوں، ان کو بخش دے۔ اے اللہ! میری وہ باتیں (جو تجھے پسند نہیں آئیں) بخش دے جو میں نے پہلے کیں یا جو میں نے بعد میں کیں، اکیلے میں کیں یا جو میں نے سب کے سامنے کیں اور جنہیں تو مجھ سے زیادہ جاننے والا ہے، تو ہی (جسے چاہے اپنی رحمت کی طرف) آگے بڑھانے والا ہے اور تو ہی پیچھے کرنے والا ہے اور تو ہر چیز پر قادر ہے۔\""}],[6958,"عبدالملک بن صباح مسمعی نے کہا : ہمیں شعبہ نے اسی سند سے ( یہی ) حدیث بیان کی ۔","",{"u2":") عبدالملک بن صباح مسمعی نے کہا: ہمیں شعبہ نے اسی سند سے (یہی) حدیث بیان کی۔"}],[6959,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے ، کہا : رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتے تھے : \" اے اللہ! میرے دین کو درست کر دے ، جو میرے ( دین و دنیا کے ) ہر کام کے تحفظ کا ذریعہ ہے اور میری دنیا کو درست کر دے جس میں میری گزران ہے اور میری آخرت کو درست کر دے جس میں میرا ( اپنی منزل کی طرف ) لوٹنا ہے اور میری زندگی کو میرے لیے ہر بھلائی میں اضافے کا سبب بنا دے اور میری وفات کو میرے لیے ہر شر سے راحت بنا دے ۔","",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، کہا: رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتے تھے: \"اے اللہ! میرے دین کو درست کر دے، جو میرے (دین و دنیا کے) ہر کام کے تحفظ کا ذریعہ ہے اور میری دنیا کو درست کر دے جس میں میری گزران ہے اور میری آخرت کو درست کر دے جس میں میرا (اپنی منزل کی طرف) لوٹنا ہے اور میری زندگی کو میرے لیے ہر بھلائی میں اضافے کا سبب بنا دے اور میری وفات کو میرے لیے ہر شر سے راحت بنا دے۔\""}],[6960,"محمد بن مثنی اور محمد بن بشار نے کہا : ہمیں محمد بن جعفر نے حدیث بیان کی ، انہوں نے کہا : ہمیں شعبہ نے ابواسحٰق سے حدیث سنائی ، انہوں نے ابواحوص سے ، انہوں نے سیدنا عبداللہ ( بن مسعود رضی اللہ عنہ ) سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم فرمایا کرتے تھے : \" اے اللہ! میں تجھ سے ہدایت ، تقوی ، پاک دامنی ، اور ( دل کا ) غنا مانگتا ہوں ۔","",{"u2":"محمد بن مثنیٰ اور محمد بن بشار نے کہا: ہمیں محمد بن جعفر نے حدیث بیان کی، انہوں نے کہا: ہمیں شعبہ نے ابواسحٰق سے حدیث سنائی، انہوں نے ابواحوص سے، انہوں نے حضرت عبداللہ (بن مسعود رضی اللہ عنہ) سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم فرمایا کرتے تھے: \"اے اللہ! میں تجھ سے ہدایت، تقویٰ، پاک دامنی، اور (دل کا) غنا مانگتا ہوں۔\""}],[6961,"محمد بن مثنی اور ابن بشار نے کہا : ہمیں عبدالرحمٰن نے سفیان سے حدیث بیان کی ، انہوں نے ابواسحاق سے اسی سند کے ساتھ اسی کے مانند روایت کی ، البتہ ابن مثنی نے اپنی روایت میں ( عفاف کی بجائے ) \" عفت \" کا لفظ کہا ۔ ( مفہوم ایک ہی ہے ۔)","",{"u2":"محمد بن مثنیٰ اور ابن بشار نے کہا: ہمیں عبدالرحمٰن نے سفیان سے حدیث بیان کی، انہوں نے ابواسحاق سے اسی سند کے ساتھ اسی کے مانند روایت کی، البتہ ابن مثنیٰ نے اپنی روایت میں (عفاف کی بجائے) \"عفت\" کا لفظ کہا۔ (مفہوم ایک ہی ہے۔)"}],[6962,"عبداللہ بن حارث اور ابو عثمان نہدی نے سیدنا زید بن ارقم رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : میں تمہیں اسی طرح بتاتا ہوں جس طرح رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا ، آپ فرماتے تھے : \" اے اللہ! میں تجھ سے تیری پناہ میں آتا ہوں ، عاجز ہو جانے ، سستی ، بزدلی ، بخل ، سخت بڑھاپے اور قبر کے عذاب سے ۔ اے اللہ! میرے دل کو تقوی دے ، اس کو پاکیزہ کر دے ، تو ہی اس ( دل ) کو سب سے بہتر پاک کرنے والا ہے ، تو ہی اس کا رکھو الا اور اس کا مددگار ہے ۔ اے اللہ! میں تجھ سے ایسے علم سے تیری پناہ مانگتا ہوں جو کوئی فائدہ نہ دے اور ایسے دل سے جو ( تیرے آگے ) جھک کر مطمئن نہ ہوتا ہو اور ایسے من سے جو سیر نہ ہو اور ایسی دعا سے جسے شرف قبولیت نصیب نہ ہو ۔","",{"u2":"عبداللہ بن حارث اور ابو عثمان نہدی نے حضرت زید بن ارقم رضی اللہ عنہ سے روایت کی، انہوں نے کہا: میں تمہیں اسی طرح بتاتا ہوں جس طرح رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا، آپ فرماتے تھے: \"اے اللہ! میں تجھ سے تیری پناہ میں آتا ہوں، عاجز ہو جانے، سستی، بزدلی، بخل، سخت بڑھاپے اور قبر کے عذاب سے۔ اے اللہ! میرے دل کو تقویٰ دے، اس کو پاکیزہ کر دے، تو ہی اس (دل) کو سب سے بہتر پاک کرنے والا ہے، تو ہی اس کا رکھوالا اور اس کا مددگار ہے۔ اے اللہ! میں تجھ سے ایسے علم سے تیری پناہ مانگتا ہوں جو کوئی فائدہ نہ دے اور ایسے دل سے جو (تیرے آگے) جھک کر مطمئن نہ ہوتا ہو اور ایسے من سے جو سیر نہ ہو اور ایسی دعا سے جسے شرف قبولیت نصیب نہ ہو۔\""}],[6963,"عبدالواحد بن زیاد نے حسن بن عبداللہ سے روایت کی ، انہوں نے کہا : ہمیں ابراہیم بن سعد نخعی نے حدیث بیان کی ، انہوں نے کہا : ہمیں عبدالرحمٰن بن یزید نے سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے حدیث بیان کی ، انہوں نے کہا : جب شام ہوتی تو رسول اللہ صلی اللہ علیہ وسلم یہ دعا کرتے تھے : \"\" ہم نے شام کی اور سارا ملک ( شام کے وقت بھی ) اللہ کا ہوا ، سب شکر اور تعریف اللہ کے لیے ہے ، اللہ کے سوا کوئی عبادت کے لائق نہیں ، وہ اکیلا ( مالک ، معبود ) ہے ، اس کا کوئی شریک نہیں ۔ \"\" حسن ( بن عبیداللہ ) نے کہا : مجھے زید نے حدیث بیان کی ، انہوں نے اس ( دعا ) میں ( یہ حصہ ) ابراہیم ( نخعی ) سے ( سن کر ) حفظ کہا : \"\" اسی کی بادشاہی اور اسی کے لیے ہر طرح کی تعریف ہے اور وہ ہر چیز پر پوری طرح قادر ہے ۔ اے اللہ! میں تجھ سے اس رات کی بھلائی مانگتا ہوں اور تجھ سے اس رات کی اور اس کے بعد ( کے ہر لمحے ) کی برائی سے پناہ طلب کرتا ہوں ، اے اللہ! میں کسل مندی اور بڑھاپے کی خرابی سے تیری پناہ میں آتا ہوں ، اے اللہ! میں تیری پناہ مانگتا ہوں جہنم میں کسی بھی قسم کے عذاب سے اور قبر میں کسی بھی قسم کے عذاب سے ۔","",{"u2":"عبدالواحد بن زیاد نے حسن بن عبداللہ سے روایت کی، انہوں نے کہا: ہمیں ابراہیم بن سعد نخعی نے حدیث بیان کی، انہوں نے کہا: ہمیں عبدالرحمٰن بن یزید نے حضرت عبداللہ بن مسعود رضی اللہ عنہ سے حدیث بیان کی، انہوں نے کہا: جب شام ہوتی تو رسول اللہ صلی اللہ علیہ وسلم یہ دعا کرتے تھے: \"ہم نے شام کی اور سارا ملک (شام کے وقت بھی) اللہ کا ہوا، سب شکر اور تعریف اللہ کے لیے ہے، اللہ کے سوا کوئی عبادت کے لائق نہیں، وہ اکیلا (مالک، معبود) ہے، اس کا کوئی شریک نہیں۔\"\nحسن (بن عبیداللہ) نے کہا: مجھے زید نے حدیث بیان کی، انہوں نے اس (دعا) میں (یہ حصہ) ابراہیم (نخعی) سے (سن کر) حفظ کہا: \"اسی کی بادشاہی اور اسی کے لیے ہر طرح کی تعریف ہے اور وہ ہر چیز پر پوری طرح قادر ہے۔ اے اللہ! میں تجھ سے اس رات کی بھلائی مانگتا ہوں اور تجھ سے اس رات کی اور اس کے بعد (کے ہر لمحے) کی برائی سے پناہ طلب کرتا ہوں، اے اللہ! میں کسل مندی اور بڑھاپے کی خرابی سے تیری پناہ میں آتا ہوں، اے اللہ! میں تیری پناہ مانگتا ہوں جہنم میں کسی بھی قسم کے عذاب سے اور قبر میں کسی بھی قسم کے عذاب سے۔\""}],[6964,"جریر نے حسن بن عبیداللہ سے ، انہوں نے ابراہیم بن سوید سے ، انہوں نے عبدالرحمٰن بن یزید سے اور انہوں نے سیدنا عبداللہ ( بن مسعود رضی اللہ عنہ ) سے روایت کی ، انہوں نے کہا : اللہ کے نبی صلی اللہ علیہ وسلم جب شام کرتے تو ( دعا کرتے ہوئے ) فرماتے : \" ہم اور سارا ملک شام کے وقت بھی اللہ کا ہوا ، سب حمد اللہ کے لیے ہے ، اللہ کے سوا کوئی عبادت کے لائق نہیں ، وہ اکیلا ہے ، اس کا کوئی شریک نہیں ۔ \" ( حسن بن عبیداللہ نے ) کہا : میں دیکھتا ہوں کہ انہوں ( ابراہیم نخعی ) نے ان کلمات میں یہ بھی کہا : \" ساری بادشاہت اسی کی ہے ، ( ہر نعمت پر ) ساری تعریف بھی اسی کو سزاوار ہے ، وہی ہر چیز پر پوری قدرت رکھنے والا ہے ۔ اے میرے پروردگار! جو کچھ اس رات میں ہے اور جو اس کے بعد ہے ، میں تجھ سے اس کی بھلائی کا طلبگار ہوں اور جو کچھ اس رات میں ہے اور جو اس کے بعد ہے اس کی برائی سے میں تیری پناہ میں آتا ہوں ۔ اے میرے پروردگار! میں تیری پناہ چاہتا ہوں کسل مندی سے اور بڑھاپے کی خرابی سے ۔ اے میرے پروردگار! میں تجھ سے پناہ مانگتا ہوں جہنم میں کسی بھی قسم کے عذاب سے اور قبر میں کسی بھی قسم کے عذاب سے ۔ \" اور جب آپ صلی اللہ علیہ وسلم صبح کرتے تو ( بالکل اسی طرح ) فرماتے : ہم اور ساری بادشاہت اور اختیار صبح کو ( بھی ) اللہ کے ہوئے ۔","",{"u2":"جریر نے حسن بن عبیداللہ سے، انہوں نے ابراہیم بن سوید سے، انہوں نے عبدالرحمٰن بن یزید سے اور انہوں نے حضرت عبداللہ (بن مسعود رضی اللہ عنہ) سے روایت کی، انہوں نے کہا: اللہ کے نبی صلی اللہ علیہ وسلم جب شام کرتے تو (دعا کرتے ہوئے) فرماتے: \"ہم اور سارا ملک شام کے وقت بھی اللہ کا ہوا، سب حمد اللہ کے لیے ہے، اللہ کے سوا کوئی عبادت کے لائق نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں۔\" (حسن بن عبیداللہ نے) کہا: میں دیکھتا ہوں کہ انہوں (ابراہیم نخعی) نے ان کلمات میں یہ بھی کہا: \"ساری بادشاہت اسی کی ہے، (ہر نعمت پر) ساری تعریف بھی اسی کو سزاوار ہے، وہی ہر چیز پر پوری قدرت رکھنے والا ہے۔ اے میرے پروردگار! جو کچھ اس رات میں ہے اور جو اس کے بعد ہے، میں تجھ سے اس کی بھلائی کا طلبگار ہوں اور جو کچھ اس رات میں ہے اور جو اس کے بعد ہے اس کی برائی سے میں تیری پناہ میں آتا ہوں۔ اے میرے پروردگار! میں تیری پناہ چاہتا ہوں کسل مندی سے اور بڑھاپے کی خرابی سے۔ اے میرے پروردگار! میں تجھ سے پناہ مانگتا ہوں جہنم میں کسی بھی قسم کے عذاب سے اور قبر میں کسی بھی قسم کے عذاب سے۔\" اور جب آپ صلی اللہ علیہ وسلم صبح کرتے تو (بالکل اسی طرح) فرماتے: ہم اور ساری بادشاہت اور اختیار صبح کو (بھی) اللہ کے ہوئے۔\""}],[6965,"زائدہ نے حسن بن عبیداللہ سے ، انہوں نے ابراہیم بن سُوید سے ، انہوں نے عبدالرحمٰن بن یزید سے اور انہوں نے سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم شام کے وقت ( دعا کرتے ہوئے یہ ) فرمایا کرتے تھے : \"\" ہم نے اور سارے ملک نے اللہ کے ( حکم و فرمان کی پابندی کے ) لیے شام کی ۔ سب تعریف اللہ کے لیے ہے ، اللہ کے سوا کوئی عبادت کے لائق نہیں ، وہ اکیلا ہے ، اس کا کوئی شریک نہیں ۔ اے اللہ! میں تجھ سے اس رات کی اور اس میں موجود ہر بھلائی کا سوال کرتا ہوں اور میں تجھ سے اس رات کے اور اس میں موجود ہر شر سے پناہ کا طلبگار ہوں ۔ اے اللہ! میں تیری پناہ مانگتا ہوں ، سستی طاری ہو جانے سے اور عمر ( کے حد سے ) بڑھ جانے سے اور بڑھاپے کی خرابی سے اور دنیا کے ہر فتنے اور قبر کے عذاب سے ۔ \"\" حسن بن عبیداللہ نے کہا : زبید نے مجھے ابراہیم بن سوید ( نخعی ) سے ، انہوں نے عبدالرحمان بن یزید سے ، انہوں نے سیدنا عبداللہ ( بن مسعود رضی اللہ عنہ ) سے روایت کرتے ہوئے مزید یہ بتایا کہ آپ صلی اللہ علیہ وسلم ( جب شام کرتے تو ) یہ فرماتے : \"\" اللہ کے سوا کوئی عبادت کے لائق نہیں ، وہ اکیلا ہے ، اس کا کوئی شریک نہیں ، ساری بادشاہت اسی کی ہے ، سب تعریف اسی کو سزاوار ہے اور وہی ہر چیز پر قادر ہے ۔","",{"u2":") زائدہ نے حسن بن عبیداللہ سے، انہوں نے ابراہیم بن سُوید سے، انہوں نے عبدالرحمٰن بن یزید سے اور انہوں نے حضرت عبداللہ بن مسعود رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم شام کے وقت (دعا کرتے ہوئے یہ) فرمایا کرتے تھے: \"ہم نے اور سارے ملک نے اللہ کے (حکم و فرمان کی پابندی کے) لیے شام کی۔ سب تعریف اللہ کے لیے ہے، اللہ کے سوا کوئی عبادت کے لائق نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں۔ اے اللہ! میں تجھ سے اس رات کی اور اس میں موجود ہر بھلائی کا سوال کرتا ہوں اور میں تجھ سے اس رات کے اور اس میں موجود ہر شر سے پناہ کا طلبگار ہوں۔ اے اللہ! میں تیری پناہ مانگتا ہوں، سستی طاری ہو جانے سے اور عمر (کے حد سے) بڑھ جانے سے اور بڑھاپے کی خرابی سے اور دنیا کے ہر فتنے اور قبر کے عذاب سے۔\"\nحسن بن عبیداللہ نے کہا: زبید نے مجھے ابراہیم بن سوید (نخعی) سے، انہوں نے عبدالرحمان بن یزید سے، انہوں نے حضرت عبداللہ (بن مسعود رضی اللہ عنہ) سے روایت کرتے ہوئے مزید یہ بتایا کہ آپ صلی اللہ علیہ وسلم (جب شام کرتے تو) یہ فرماتے: \"اللہ کے سوا کوئی عبادت کے لائق نہیں، وہ اکیلا ہے، اس کا کوئی شریک نہیں، ساری بادشاہت اسی کی ہے، سب تعریف اسی کو سزاوار ہے اور وہی ہر چیز پر قادر ہے۔\""}],[6966,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم ( دعا کرتے ہوئے یہ ) فرمایا کرتے تھے : \" اکیلے اللہ کے سوا کوئی عبادت کے لائق نہیں ، اس نے اپنے لشکر کو عزت دی ، اپنے بندے کی نصرت کی ، اکیلا وہ تمام جماعتوں پر غالب آیا ، ( وہی آخر ہے ) اس کے بعد کچھ نہیں ۔","",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم (دعا کرتے ہوئے یہ) فرمایا کرتے تھے: \"اکیلے اللہ کے سوا کوئی عبادت کے لائق نہیں، اس نے اپنے لشکر کو عزت دی، اپنے بندے کی نصرت کی، اکیلا وہ تمام جماعتوں پر غالب آیا، (وہی آخر ہے) اس کے بعد کچھ نہیں۔\""}],[6967,"ابوکریب محمد بن علاء نے ہمیں حدیث بیان کی ، انہوں نے کہا : ہمیں ( عبداللہ ) بن ادریس نے حدیث بیان کی ، انہوں نے کہا : میں عاصم بن کلیب سے سنا ، انہوں نے ابوبردہ سے اور انہوں نے سیدنا علی رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا : \" ( دعا کرتے ہوئے یہ ) کہو : اے اللہ! مجھے ہدایت دے اور مجھے سیدھے راستے پر چلا ، اور ( اے علی! ) ہدایت ( کا نام لیتے ہوئے اس ) سے صحیح راستے پر چلنے کو ذہن میں رکھو اور سیدھا رہنے سے تیری جیسی سدھائی مراد کو ( مانگتے ہوئے ہدایت اور صواب کا کمال طلب کرو ۔)","",{"u2":"ابوکریب محمد بن علاء نے ہمیں حدیث بیان کی، انہوں نے کہا: ہمیں (عبداللہ) بن ادریس نے حدیث بیان کی، انہوں نے کہا: میں عاصم بن کلیب سے سنا، انہوں نے ابوبردہ سے اور انہوں نے حضرت علی رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا: \"(دعا کرتے ہوئے یہ) کہو: اے اللہ! مجھے ہدایت دے اور مجھے سیدھے راستے پر چلا، اور (اے علی!) ہدایت (کا نام لیتے ہوئے اس) سے صحیح راستے پر چلنے کو ذہن میں رکھو اور سیدھا رہنے سے تیری جیسی سدھائی مراد کو (مانگتے ہوئے ہدایت اور صواب کا کمال طلب کرو۔)\""}],[6968,"ابن نمیر نے کہا : ہمیں عبداللہ بن ادریس نے حدیث بیان کی ، انہوں نے کہا : ہمیں عاصم بن کلیب نے اسی سند کے ساتھ خبر دی ( کہ سیدنا علی رضی اللہ عنہ نے ) کہا : رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا : \" ( اے علی! یہ ) کہو : اے اللہ! میں تجھ سے ہدایت اور راستی کا سوال کرتا ہوں ۔ \" پھر اسی کے مانند بیان کیا ۔","",{"u2":"ابن نمیر نے کہا: ہمیں عبداللہ بن ادریس نے حدیث بیان کی، انہوں نے کہا: ہمیں عاصم بن کلیب نے اسی سند کے ساتھ خبر دی (کہ حضرت علی رضی اللہ عنہ نے) کہا: رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا: \"(اے علی! یہ) کہو: اے اللہ! میں تجھ سے ہدایت اور راستی کا سوال کرتا ہوں۔\" پھر اسی کے مانند بیان کیا۔"}],[6969,"کُریب نے سیدنا ابن عباس رضی اللہ عنہ سے اور انہوں نے سیدہ جویریہ رضی اللہ عنہا سے روایت کی کہ نبی صلی اللہ علیہ وسلم صبح کی نماز پڑھنے کے بعد صبح سویرے ان کے ہاں سے باہر تشریف لے گئے ، اس وقت وہ اپنی نماز پڑھنے والی جگہ میں تھیں ، پھر دن چڑھنے کے بعد آپ صلی اللہ علیہ وسلم ان کے پاس واپس تشریف لائے تو وہ ( اسی طرح ) بیٹھی ہوئی تھیں ۔ آپ نے فرمایا : \" تم اب تک اسی حالت میں بیٹھی ہوئی ہو جس پر میں تمہیں چھوڑ کر گیا تھا؟ \" انہوں نے عرض کی : جی ہاں ، نبی کریم صلی اللہ علیہ وسلم نے فرمایا : \" تمہارے ( ہاں سے جانے کے ) بعد میں نے چار کلمے تین بار کہے ہیں ، اگر ان کو ان کے ساتھ تولا جائے جو تم نے آج کے دن اب تک کہا ہے تو یہ ان سے وزن میں بڑھ جائیں : \" سبحان اللہ وبحمده عدد خلقه ورضا نفسه وزنة عرشه ومداد كلماته \" پاکیزگی ہے اللہ کی اور اس کی تعریف کے ساتھ ، جتنی اس کی مخلوق کی گنتی ہے اور جتنی اس کو پسند ہے اور جتنا اس کے عرش کا وزن اور جتنی اس کے کلمات کی سیاہی ہے ۔","",{"u2":") کُریب نے حضرت ابن عباس رضی اللہ عنہ سے اور انہوں نے حضرت جویریہ رضی اللہ عنہا سے روایت کی کہ نبی صلی اللہ علیہ وسلم صبح کی نماز پڑھنے کے بعد صبح سویرے ان کے ہاں سے باہر تشریف لے گئے، اس وقت وہ اپنی نماز پڑھنے والی جگہ میں تھیں، پھر دن چڑھنے کے بعد آپ صلی اللہ علیہ وسلم ان کے پاس واپس تشریف لائے تو وہ (اسی طرح) بیٹھی ہوئی تھیں۔ آپ نے فرمایا: \"تم اب تک اسی حالت میں بیٹھی ہوئی ہو جس پر میں تمہیں چھوڑ کر گیا تھا؟\" انہوں نے عرض کی: جی ہاں، نبی کریم صلی اللہ علیہ وسلم نے فرمایا: \"تمہارے (ہاں سے جانے کے) بعد میں نے چار کلمے تین بار کہے ہیں، اگر ان کو ان کے ساتھ تولا جائے جو تم نے آج کے دن اب تک کہا ہے تو یہ ان سے وزن میں بڑھ جائیں: \"سبحان اللہ وبحمدہ عدد خلقہ ورضا نفسہ وزنۃ عرشہ ومداد کلماتہ\"پاکیزگی ہے اللہ کی اور اس کی تعریف کے ساتھ، جتنی اس کی مخلوق کی گنتی ہے اور جتنی اس کو پسند ہے اور جتنا اس کے عرش کا وزن اور جتنی اس کے کلمات کی سیاہی ہے۔\""}],[6970,"ابورشدین نے سیدنا ابن عباس رضی اللہ عنہ سے اور انہوں نے سیدہ جویریہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : صبح کی نماز کے وقت یا صبح کی نماز کے بعد رسول اللہ صلی اللہ علیہ وسلم گزرتے ہوئے ان کے ہاں تشریف لائے ۔ ۔ پھر اس ( پچھلی حدیث ) کے مطابق بیان کیا ۔ ۔ مگر انہوں نے ( اپنے کلموں کو اس طرح ) بیان کیا : \" میں اللہ کی تسبیح بیان کرتا ہوں جتنی اس کی مخلوقات کی گنتی ہے ، میں اللہ کی تسبیح بیان کرتا ہوں جتنی اس کی رضا ہے ، میں اللہ کی تسبیح بیان کرتا ہوں جتنا اس کے عرش کا وزن ہے ، میں اللہ کی تسبیح کرتا ہوں جتنی اس کے کلمات کی سیاہی ہے ۔","",{"u2":"ابورشدین نے حضرت ابن عباس رضی اللہ عنہ سے اور انہوں نے حضرت جویریہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: صبح کی نماز کے وقت یا صبح کی نماز کے بعد رسول اللہ صلی اللہ علیہ وسلم گزرتے ہوئے ان کے ہاں تشریف لائے۔۔ پھر اس (پچھلی حدیث) کے مطابق بیان کیا۔۔ مگر انہوں نے (اپنے کلموں کو اس طرح) بیان کیا: \"میں اللہ کی تسبیح بیان کرتا ہوں جتنی اس کی مخلوقات کی گنتی ہے، میں اللہ کی تسبیح بیان کرتا ہوں جتنی اس کی رضا ہے، میں اللہ کی تسبیح بیان کرتا ہوں جتنا اس کے عرش کا وزن ہے، میں اللہ کی تسبیح کرتا ہوں جتنی اس کے کلمات کی سیاہی ہے۔\""}],[6971,"محمد بن جعفر نے کہا : ہمیں شعبہ نے حکم سے حدیث بیان کی ، انہوں نے کہا : میں نے ابن ابی لیلی سے سنا ، انہوں نے کہا : ہمیں سیدنا علی رضی اللہ عنہ نے حدیث بیان کی کہ سیدہ فاطمہ رضی اللہ عنہا کو چکی پیسنے سے جو زحمت برداشت کرنی پڑی اس کی وجہ سے ان کے ہاتھوں میں تکلیف ہوئی ۔ رسول اللہ صلی اللہ علیہ وسلم کے پاس کچھ قیدی آئے ۔ آپ کی طرف گئیں ، لیکن آپ صلی اللہ علیہ وسلم کو ( گھر میں ) نہ پایا ۔ سیدہ عائشہ رضی اللہ عنہا سے ملیں اور انہیں ( اپنی تکلیف کے بارے میں ) بتایا ۔ جب نبی صلی اللہ علیہ وسلم تشریف لائے تو سیدہ عائشہ رضی اللہ عنہا نے آپ کو ان ( سیدہ فاطمہ رضی اللہ عنہا ) کے اپنے پاس آنے کے بارے میں بتایا تو رسول اللہ صلی اللہ علیہ وسلم ہمارے ہان تشریف لائے ۔ ۔ اس وقت ہم اپنے اپنے بستروں میں جا چکے تھے ، ہم کھڑے ہونے لگے تو نبی صلی اللہ علیہ وسلم نے فرمایا : \" دونوں اپنی اپنی جگہ پر رہو ۔ \" آپ ہم دونوں کے درمیان ( والی جگہ پر ) بیٹھ گئے حتی کہ میں نے آپ کے قدم مبارک کی ٹھڈک اپنے سینے پر محسوس کی ، پھر آپ صلی اللہ علیہ وسلم نے فرمایا : \" کیا تم دونوں نے مجھ سے مانگا ہے میں تمہیں اس سے بہتر بات نہ سکھلاؤں؟ جب تم دونوں اپنے اپنے بستروں میں جاؤ تو چونتیس بار اللہ اکبر کہو ، تینتیس بار سبحان اللہ کہو اور تینتیس بار الحمدللہ کہو ، یہ ( عمل ) تم دونوں کے لیے ایک خادم ( مل جانے ) سے بہتر ہے ۔","",{"u2":"محمد بن جعفر نے کہا: ہمیں شعبہ نے حکم سے حدیث بیان کی، انہوں نے کہا: میں نے ابن ابی لیلی سے سنا، انہوں نے کہا: ہمیں حضرت علی رضی اللہ عنہ نے حدیث بیان کی کہ حضرت فاطمہ رضی اللہ عنہا کو چکی پیسنے سے جو زحمت برداشت کرنی پڑی اس کی وجہ سے ان کے ہاتھوں میں تکلیف ہوئی۔ رسول اللہ صلی اللہ علیہ وسلم کے پاس کچھ قیدی آئے۔ آپ کی طرف گئیں، لیکن آپ صلی اللہ علیہ وسلم کو (گھر میں) نہ پایا۔ حضرت عائشہ رضی اللہ عنہا سے ملیں اور انہیں (اپنی تکلیف کے بارے میں) بتایا۔ جب نبی صلی اللہ علیہ وسلم تشریف لائے تو حضرت عائشہ رضی اللہ عنہا نے آپ کو ان (حضرت فاطمہ رضی اللہ عنہا) کے اپنے پاس آنے کے بارے میں بتایا تو رسول اللہ صلی اللہ علیہ وسلم ہمارے ہان تشریف لائے۔۔ اس وقت ہم اپنے اپنے بستروں میں جا چکے تھے، ہم کھڑے ہونے لگے تو نبی صلی اللہ علیہ وسلم نے فرمایا: \"دونوں اپنی اپنی جگہ پر رہو۔\" آپ ہم دونوں کے درمیان (والی جگہ پر) بیٹھ گئے حتی کہ میں نے آپ کے قدم مبارک کی ٹھڈک اپنے سینے پر محسوس کی، پھر آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تم دونوں نے مجھ سے مانگا ہے میں تمہیں اس سے بہتر بات نہ سکھلاؤں؟ جب تم دونوں اپنے اپنے بستروں میں جاؤ تو چونتیس بار اللہ اکبر کہو، تینتیس بار سبحان اللہ کہو اور تینتیس بار الحمدللہ کہو، یہ (عمل) تم دونوں کے لیے ایک خادم (مل جانے) سے بہتر ہے۔\""}],[6972,"وکیع ، معاذ اور ابن ابی عدی سب نے شعبہ سے اسی سند کے ساتھ روایت کی اور معاذ کی حدیث میں ہے : \" جب تم دونوں رات کے وقت اپنے بستر میں چلے جاؤ ۔","",{"u2":"وکیع، معاذ اور ابن ابی عدی سب نے شعبہ سے اسی سند کے ساتھ روایت کی اور معاذ کی حدیث میں ہے: \"جب تم دونوں رات کے وقت اپنے بستر میں چلے جاؤ۔\""}],[6973,"عبیداللہ بن ابی یزید اور عطاء بن ابی رباح نے مجاہد سے ، انہوں نے ابن ابی لیلی سے ، انہوں نے سیدنا علی رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی طرح حدیث بیان کی جس طرح حکم نے ابن ابی لیلی سے روایت کی ۔ انہوں نے حدیث میں مزید یہ بیان کیا کہ سیدنا علی رضی اللہ عنہ نے کہا : میں نے جب سے رسول اللہ صلی اللہ علیہ وسلم سے یہ بات سنی میں نے کبھی اسے ترک نہیں کیا ۔ ان سے پوچھا کیا : جنگ صفین کی رات بھی نہیں چھوڑا؟ انہوں نے جواب دیا : جنگ صفین کی رات بھی ( اسے نہیں چھوڑا ۔ ) عطاء نے جو حدیث مجاہد سے اور انہوں نے ابن ابی لیلی سے روایت کی ، انہوں ( ابن ابی لیلی ) نے کہا : میں نے ان ( سیدنا علی رضی اللہ عنہ ) سے عرض کی : صفین کی رات بھی نہ چھوڑا؟"],[6974,"عبیداللہ بن ابی یزید اور عطاء بن ابی رباح نے مجاہد سے ، انہوں نے ابن ابی لیلی سے ، انہوں نے سیدنا علی رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی طرح حدیث بیان کی جس طرح حکم نے ابن ابی لیلی سے روایت کی ۔ انہوں نے حدیث میں مزید یہ بیان کیا کہ سیدنا علی رضی اللہ عنہ نے کہا : میں نے جب سے رسول اللہ صلی اللہ علیہ وسلم سے یہ بات سنی میں نے کبھی اسے ترک نہیں کیا ۔ ان سے پوچھا کیا : جنگ صفین کی رات بھی نہیں چھوڑا؟ انہوں نے جواب دیا : جنگ صفین کی رات بھی ( اسے نہیں چھوڑا ۔ ) عطاء نے جو حدیث مجاہد سے اور انہوں نے ابن ابی لیلی سے روایت کی ، انہوں ( ابن ابی لیلی ) نے کہا : میں نے ان ( سیدنا علی رضی اللہ عنہ ) سے عرض کی : صفین کی رات بھی نہ چھوڑا؟","",{"u2":"عبیداللہ بن ابی یزید اور عطاء بن ابی رباح نے مجاہد سے، انہوں نے ابن ابی لیلیٰ سے، انہوں نے حضرت علی رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی طرح حدیث بیان کی جس طرح حکم نے ابن ابی لیلیٰ سے روایت کی۔ انہوں نے حدیث میں مزید یہ بیان کیا کہ حضرت علی رضی اللہ عنہ نے کہا: میں نے جب سے رسول اللہ صلی اللہ علیہ وسلم سے یہ بات سنی میں نے کبھی اسے ترک نہیں کیا۔ ان سے پوچھا کیا: جنگ صفین کی رات بھی نہیں چھوڑا؟ انہوں نے جواب دیا: جنگ صفین کی رات بھی (اسے نہیں چھوڑا۔)\nعطاء نے جو حدیث مجاہد سے اور انہوں نے ابن ابی لیلیٰ سے روایت کی، انہوں (ابن ابی لیلیٰ) نے کہا: میں نے ان (حضرت علی رضی اللہ عنہ) سے عرض کی:صفین کی رات بھی نہ چھوڑا؟"}],[6975,"روح بن قاسم نے سہیل سے ، انہوں نے اپنے والد ( ابوصالح ) سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ سیدہ فاطمہ رضی اللہ عنہا ایک خدمت گزار ( کنیز ) مانگنے کے لیے نبی صلی اللہ علیہ وسلم کے پاس آئیں اور آپ سے کام کی شکایت کی تو آپ نے فرمایا : \" تمہیں کدمت گزار تو ہمارے ہاں نہیں ملا ۔ \" ( ہمارے گھر میں بھی موجود نہیں ) ، فرمایا : \" کیا میں تمہیں ایسی بات نہ بتاؤں جو تمہارے لیے خدمت گزار سے بہت بہتر ہے؟ جب تم بستر پر جاؤ تو تینتیس بار سبحان اللہ کہو ، تینتیس بار الحمدللہ کہو اور چونتیس بار اللہ اکبر کہو ۔","",{"u2":"روح بن قاسم نے سہیل سے، انہوں نے اپنے والد (ابوصالح) سے اور انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ حضرت فاطمہ رضی اللہ عنہا ایک خدمت گزار (کنیز) مانگنے کے لیے نبی صلی اللہ علیہ وسلم کے پاس آئیں اور آپ سے کام کی شکایت کی تو آپ نے فرمایا: \"تمہیں کدمت گزار تو ہمارے ہاں نہیں ملا۔\" (ہمارے گھر میں بھی موجود نہیں)، فرمایا: \"کیا میں تمہیں ایسی بات نہ بتاؤں جو تمہارے لیے خدمت گزار سے بہت بہتر ہے؟ جب تم بستر پر جاؤ تو تینتیس بار سبحان اللہ کہو، تینتیس بار الحمدللہ کہو اور چونتیس بار اللہ اکبر کہو۔\""}],[6976,"روح بن قاسم نے سہیل سے ، انہوں نے اپنے والد ( ابوصالح ) سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ سیدہ فاطمہ رضی اللہ عنہا ایک خدمت گزار ( کنیز ) مانگنے کے لیے نبی صلی اللہ علیہ وسلم کے پاس آئیں اور آپ سے کام کی شکایت کی تو آپ نے فرمایا : \" تمہیں کدمت گزار تو ہمارے ہاں نہیں ملا ۔ \" ( ہمارے گھر میں بھی موجود نہیں ) ، فرمایا : \" کیا میں تمہیں ایسی بات نہ بتاؤں جو تمہارے لیے خدمت گزار سے بہت بہتر ہے؟ جب تم بستر پر جاؤ تو تینتیس بار سبحان اللہ کہو ، تینتیس بار الحمدللہ کہو اور چونتیس بار اللہ اکبر کہو ۔","",{"u2":"وہیب نے کہا: ہمیں سہیل نے اسی سند کے ساتھ (یہی) حدیث بیان کی۔"}],[6977,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا : \" جب تم مرغ کی بانگ سنو تو اللہ تعالی سے اس کے فضل کا سوال کرو ، کیونکہ ( اس وقت ) اس نے ایک فرشتے کو دیکھا ہے اور جب تم گدھے کی آواز سنو تو شیطان سے اللہ کی پناہ مانگو کیونکہ اس نے شیطان کو دیکھا ہے ۔","",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: \"جب تم مرغ کی بانگ سنو تو اللہ تعالیٰ سے اس کے فضل کا سوال کرو، کیونکہ (اس وقت) اس نے ایک فرشتے کو دیکھا ہے اور جب تم گدھے کی آواز سنو تو شیطان سے اللہ کی پناہ مانگو کیونکہ اس نے شیطان کو دیکھا ہے۔\""}],[6978,"معاذ بن ہشام نے کہا : مجھے میرے والد نے قتادہ سے حدیث بیان کی ، انہوں نے ابوعالیہ سے اور انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم کرب کے وقت یہ دعا کیا کرتے تھے : \" اللہ کے سوا کوئی عبادت کے لائق نہیں جو سب سے عظیم ہے ، سب سے زیادہ حلم والا ہے ۔ اللہ کے سوا کوئی عبادت کے لائق نہیں جو عرش عظیم کا مالک ہے ۔ اللہ کے سوا کوئی عبادت کے لائق نہیں جو آسمانوں کا مالک ، زمینوں کا مالک اور عزت والے عرش کا مالک ہے ۔","",{"u2":"معاذ بن ہشام نے کہا: مجھے میرے والد نے قتادہ سے حدیث بیان کی، انہوں نے ابوعالیہ سے اور انہوں نے حضرت ابن عباس رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم کرب کے وقت یہ دعا کیا کرتے تھے: \"اللہ کے سوا کوئی عبادت کے لائق نہیں جو سب سے عظیم ہے، سب سے زیادہ حلم والا ہے۔ اللہ کے سوا کوئی عبادت کے لائق نہیں جو عرش عظیم کا مالک ہے۔ اللہ کے سوا کوئی عبادت کے لائق نہیں جو آسمانوں کا مالک، زمینوں کا مالک اور عزت والے عرش کا مالک ہے۔\""}],[6979,"وکیع نے ہشام سے اسی سند کے ساتھ حدیث بیان کی ، لیکن معاذ بن ہشام کی حدیث زیادہ مکمل ہے ۔","",{"u2":"وکیع نے ہشام سے اسی سند کے ساتھ حدیث بیان کی، لیکن معاذ بن ہشام کی حدیث زیادہ مکمل ہے۔"}],[6980,"ہمیں سعید بن ابی عروبہ نے قتادہ سے روایت کی ، ابوعالیہ ریاحی نے انہیں سیدنا ابن عباس رضی اللہ عنہ سے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم کرب کے وقت ان الفاظ سے دعا فرماتے تھے ، پھر وہی کلمات ذکر کیے جو معاذ بن ہشام نے اپنے والد سے اور انہوں نے قتادہ سے روایت کیے ، مگر انہوں نے ( \" رب السماوات و رب الارض \" کے بجائے ) \" رب السماوات والارض \" کہا ۔","",{"u2":"ہمیں سعید بن ابی عروبہ نے قتادہ سے روایت کی، ابوعالیہ ریاحی نے انہیں حضرت ابن عباس رضی اللہ عنہ سے حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم کرب کے وقت ان الفاظ سے دعا فرماتے تھے، پھر وہی کلمات ذکر کیے جو معاذ بن ہشام نے اپنے والد سے اور انہوں نے قتادہ سے روایت کیے، مگر انہوں نے (\"رب السماوات و رب الارض \" کے بجائے) \" رب السماوات والارض \" کہا۔"}],[6981,"(حماد بن سلمہ نے کہا : مجھے یوسف بن عبداللہ بن حارث نے ابوعالیہ سے خبر دی ، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم کو جب کوئی سخت مشکل اور تکلیف دہ معاملہ درپیش ہوتا تو آپ فرماتے ، پھر اسی طرح بیان کیا جس طرح معاذ نے اپنے والد سے حدیث بیان کی ہے اور ان کلمات کے ساتھ \" لا اله الا لله العظيم الحليم \" کے بعد ) \" لا اله الا لله رب العرش الكريم \" مزید بیان کیا ۔","",{"u2":"حماد بن سلمہ نے کہا: مجھے یوسف بن عبداللہ بن حارث نے ابوعالیہ سے خبر دی، انہوں نے حضرت ابن عباس رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم کو جب کوئی سخت مشکل اور تکلیف دہ معاملہ درپیش ہوتا تو آپ فرماتے، پھر اسی طرح بیان کیا جس طرح معاذ نے اپنے والد سے حدیث بیان کی ہے اور ان کلمات کے ساتھ \" لا الہ الا للہ العظیم الحلیم \" کے بعد) \" لا الہ الا للہ رب العرش الکریم \" مزید بیان کیا۔"}],[6982,"وہیب نے کہا : ہمیں سعید جریری نے ابو عبداللہ جسری سے حدیث بیان کی ، انہوں نے ابن صامت سے اور انہوں نے سیدنا ابوذر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم سے سوال کیا گیا : ( اللہ کے ذکر کے لیے ) کون سا کلمہ افضل ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا : \" جسے اللہ نے اپنے فرشتوں کے لیے یا ( ان سمیت ) اپنے تمام بندوں کے لیے منتخب فرمایا ہے : سبحان اللہ وبحمده \" میں ( ہر نعمت کے لیے ) اللہ کی حمد کے ساتھ ہر ناشایان چیز سے اس کی پاکیزگی بیان کرتا ہوں ۔","",{"u2":"وہیب نے کہا: ہمیں سعید جریری نے ابو عبداللہ جسری سے حدیث بیان کی، انہوں نے ابن صامت سے اور انہوں نے حضرت ابوذر رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم سے سوال کیا گیا: (اللہ کے ذکر کے لیے) کون سا کلمہ افضل ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"جسے اللہ نے اپنے فرشتوں کے لیے یا (ان سمیت) اپنے تمام بندوں کے لیے منتخب فرمایا ہے: سبحان اللہ وبحمدہ \"میں (ہر نعمت کے لیے) اللہ کی حمد کے ساتھ ہر ناشایان چیز سے اس کی پاکیزگی بیان کرتا ہوں۔\""}],[6983,"شعبہ نے جریر سے ، انہوں نے ابوعبداللہ جسری سے جو عنزہ قبیلے سے تھے ، انہوں نے عبداللہ بن صامت سے اور انہوں نے سیدنا ابوذر رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کیا میں تمہیں وہ کلمہ نہ بتاؤں جو اللہ تعالی کو سب سے زیادہ محبوب ہے؟ \" میں نے کہا : اللہ کے رسول! مجھے وہ کلمہ بتائیے جو اللہ تعالی کو سب سے زیادہ محبوب ہے ، تو آپ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ تعالی کو سب سےزیادہ محبوب کلمہ سبحان اللہ وبحمده ہے ۔","",{"u2":"شعبہ نے جریر سے، انہوں نے ابوعبداللہ جسری سے جو عنزہ قبیلے سے تھے، انہوں نے عبداللہ بن صامت سے اور انہوں نے حضرت ابوذر رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کیا میں تمہیں وہ کلمہ نہ بتاؤں جو اللہ تعالیٰ کو سب سے زیادہ محبوب ہے؟\" میں نے کہا: اللہ کے رسول! مجھے وہ کلمہ بتائیے جو اللہ تعالیٰ کو سب سے زیادہ محبوب ہے، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ کو سب سےزیادہ محبوب کلمہ سبحان اللہ وبحمدہ ہے۔"}],[6984,"فضیل نے طلحہ بن عبیداللہ بن کریز سے ، انہوں نے ام درداء سے اور انہوں نے سیدہ ام درداء رضی اللہ عنہا سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کوئی مسلمان بندہ نہیں جو اپنے بھائی کی پیٹھ پیچھے اس کے لیے دعا کرے ، مگر ایک فرشتہ ( ہے جو ) کہتا ہے : تمہیں بھی اس کے مانند ملے ۔","",{"u2":") فضیل نے طلحہ بن عبیداللہ بن کریز سے، انہوں نے ام درداء سے اور انہوں نے حضرت ام درداء رضی اللہ عنہا سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کوئی مسلمان بندہ نہیں جو اپنے بھائی کی پیٹھ پیچھے اس کے لیے دعا کرے، مگر ایک فرشتہ (ہے جو) کہتا ہے: تمہیں بھی اس کے مانند ملے۔\""}],[6985,"موسی بن سروان معلم نے ہمیں حدیث بیان کی ، کہا : مجھے طلحہ بن عبیداللہ بن کریز نے حدیث بیان کی ، کہا : مجھے سیدہ ام درداء رضی اللہ عنہا نے حدیث بیان کی ، کہا : میرے آقا ( خاوند ) نے مجھ سے بیان کیا کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا : \" جس شخص نے اپنے بھائی کے لیے اس کی پیٹھ پیچھے دعا کی تو جو فرشتہ اس کے ساتھ مقرر ہے وہ کہتا ہے : آمین اور تمہیں بھی اسی کے مانند عطا ہو ۔","",{"u2":") موسیٰ بن سروان معلم نے ہمیں حدیث بیان کی، کہا: مجھے طلحہ بن عبیداللہ بن کریز نے حدیث بیان کی، کہا: مجھے حضرت ام درداء رضی اللہ عنہا نے حدیث بیان کی، کہا: میرے آقا (خاوند) نے مجھ سے بیان کیا کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا: \"جس شخص نے اپنے بھائی کے لیے اس کی پیٹھ پیچھے دعا کی تو جو فرشتہ اس کے ساتھ مقرر ہے وہ کہتا ہے: آمین اور تمہیں بھی اسی کے مانند عطا ہو۔\""}],[6986,"عیسی بن یونس نے کہا : ہمیں عبدالملک بن ابی سلیمان نے ابوزبیر سے حدیث بیان کی ، انہوں نے عبداللہ بن صفوان کے بیٹے صفوان سے روایت کی ، ( سیدنا ابودرداء رضی اللہ عنہ کی بیٹی ) درداء ، ان ( صفوان ) کی زوجیت میں تھی ، وہ کہتے ہیں : اور میں شام آیا تو سیدنا ابودرداء رضی اللہ عنہ کے ہاں ان کے گھر گیا ، وہ نہیں ملے ، میں سیدہ ام درداء رضی اللہ عنہا سے ملا تو انہوں نے کہا : کیا تم اس سال حج کا ارادہ رکھتے ہو؟ میں نے کہا : جی ہاں ۔ انہوں نے کہا : ہمارے لیے خیر کی دعا کرنا کیونکہ نبی صلی اللہ علیہ وسلم فرمایا کرتے تھے : \" مسلمان کی اپنے بھائی کے لیے اس کی پیٹھ پیچھے کی گئی دعا مستجاب ہوتی ہے ، اس کے سر کے قریب ایک فرشتہ مقرر ہوتا ہے ، وہ جب بھی اپنے بھائی کے لیے دعائے خیر کرتا ہے تو مقرر کیا ہوا فرشتہ اس پر کہتا ہے : آمین ، اور تمہیں بھی اسی کے مانند عطا ہو ۔","",{"u2":"(صفوان نے) کہا: میں بازار کی طرف نکلا تو حضرت ابودرداء رضی اللہ عنہ سے بھی میری ملاقات ہوئی، انہوں نے بھی نبی صلی اللہ علیہ وسلم سے روایت کرتے ہوئے مجھ سے وہی کچھ کہا (جو ان کی بیوی حضرت ام درداء رضی اللہ عنہا نے کہا تھا۔)"}],[6987,"یزید بن ہارون نے عبدالملک بن ابی سلیمان سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی ، اور کہا : صفوان بن عبداللہ بن صفوان سے روایت ہے ۔","",{"u2":"یزید بن ہارون نے عبدالملک بن ابی سلیمان سے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی، اور کہا: صفوان بن عبداللہ بن صفوان سے روایت ہے۔"}],[6988,"ابواسامہ اور محمد بن بشر نے زکریا بن ابی زائدہ سے ، انہوں نے سعید بن ابی بُردہ سے اور انہوں نے سیدنا انس بن مالک رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : اللہ تعالی اس بات پر ( اپنے ) بندے سے راضی ہوتا ہے کہ وہ ایک کھانا کھائے اور اس پر اللہ کی حمد کرے یا پینے کی کوئی چیز ( پانی ، دودھ وغیرہ ) پیے اور اس پر اللہ کی حمد کرے ۔","",{"u2":"ابواسامہ اور محمد بن بشر نے زکریا بن ابی زائدہ سے، انہوں نے سعید بن ابی بُردہ سے اور انہوں نے حضرت انس بن مالک رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: اللہ تعالیٰ اس بات پر (اپنے) بندے سے راضی ہوتا ہے کہ وہ ایک کھانا کھائے اور اس پر اللہ کی حمد کرے یا پینے کی کوئی چیز (پانی، دودھ وغیرہ) پیے اور اس پر اللہ کی حمد کرے۔\""}],[6989,"اسحٰق بن یوسف ازرق نے کہا : ہمیں زکریا بن ابی زائدہ نے سعید بن ابی بُردہ سے حدیث بیان کی ، انہوں نے انس بن مالک رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ، ( آگے ) اسی کے مانند ( ہے ۔)","",{"u2":"اسحٰق بن یوسف ازرق نے کہا: ہمیں زکریا بن ابی زائدہ نے سعید بن ابی بُردہ سے حدیث بیان کی، انہوں نے انس بن مالک رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا، (آگے) اسی کے مانند (ہے۔)"}],[6990,"امام مالک نے ابن شہاب سے ، انہوں نے ابن ازہر کے آزاد کردہ غلام ابوعبید سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تم میں سے کسی شخص کی دعا اس وقت تک قبول ہوتی ہے جب تک وہ جلد بازی کرتے ہوئے یہ نہیں کہتا : میں نے دعا کی ، لیکن میرے حق میں قبول نہیں ہوتی ۔ ۔ یا نہیں ہوئی ۔","",{"u2":"امام مالک نے ابن شہاب سے، انہوں نے ابن ازہر کے آزاد کردہ غلام ابوعبید سے اور انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کسی شخص کی دعا اس وقت تک قبول ہوتی ہے جب تک وہ جلد بازی کرتے ہوئے یہ نہیں کہتا: میں نے دعا کی، لیکن میرے حق میں قبول نہیں ہوتی۔۔ یا نہیں ہوئی۔\""}],[6991,"عقیل بن خالد نے ابن شہاب سے روایت کی ، انہوں نے کہا : مجھے عبدالرحمٰن بن عوف رضی اللہ عنہ کے آزاد کردہ غلام ابوعبید نے حدیث بیان کی ۔ ۔ اور وہ قراء اور اہل فقہ میں سے ہیں ۔ ۔ انہوں نے کہا : میں نے سیدنا ابوہریرہ رضی اللہ عنہ سے سنا ، وہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تم میں سے کسی بھی شخص کی دعا قبول ہوتی ہے جب تک وہ جلد بازی نہ کرے اور یہ ( نہ ) کہے : میں نے اپنے رب سے دعا کی تو اس نے مجھے میری دعا کا جواب نہیں دیا ( میری دعا قبول نہیں کی ۔)","",{"u2":"عقیل بن خالد نے ابن شہاب سے روایت کی، انہوں نے کہا: مجھے عبدالرحمٰن بن عوف رضی اللہ عنہ کے آزاد کردہ غلام ابوعبید نے حدیث بیان کی۔۔ اور وہ قراء اور اہل فقہ میں سے ہیں۔۔ انہوں نے کہا: میں نے حضرت ابوہریرہ رضی اللہ عنہ سے سنا، وہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کسی بھی شخص کی دعا قبول ہوتی ہے جب تک وہ جلد بازی نہ کرے اور یہ (نہ) کہے: میں نے اپنے رب سے دعا کی تو اس نے مجھے میری دعا کا جواب نہیں دیا (میری دعا قبول نہیں کی۔)\""}],[6992,"ابوادریس خولانی نے سیدنا ابوہریرہ رضی اللہ عنہ سے ، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" جب تک کوئی بندہ گناہ یا قطع رحمی کی دعا نہ کرے اور قبولیت کے معاملے میں جلد بازی نہ کرے ، اس کی دعا قبول ہوتی رہتی ہے ۔ \" عرض کی گئی : اللہ کے رسول! جلد بازی کرنا کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا : \" وہ کہے : میں نے دعا کی اور میں نے دعا کی اور مجھے نظر نہیں آتا کہ وہ میرے حق میں قبول کرے گا ، پھر اس مرحلے میں ( مایوس ہو کر ) تھک جائے اور دعا کرنا چھوڑ دے ۔","",{"u2":"ابوادریس خولانی نے حضرت ابوہریرہ رضی اللہ عنہ سے، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا: \"جب تک کوئی بندہ گناہ یا قطع رحمی کی دعا نہ کرے اور قبولیت کے معاملے میں جلد بازی نہ کرے، اس کی دعا قبول ہوتی رہتی ہے۔\" عرض کی گئی: اللہ کے رسول! جلد بازی کرنا کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"وہ کہے: میں نے دعا کی اور میں نے دعا کی اور مجھے نظر نہیں آتا کہ وہ میرے حق میں قبول کرے گا، پھر اس مرحلے میں (مایوس ہو کر) تھک جائے اور دعا کرنا چھوڑ دے۔\""}],[6993,"حماد بن سلمہ ، معاذ بن معاذ ، عنبری ، معتمر ، جریر اور یزید بن زُریع نے کہا : ہمیں سلیمان تیمی نے ابوعثمان سے حدیث بیان کی ، انہوں نے سیدنا اسامہ بن زید رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" میں جنت کے دروازے پر کھڑا ہوا تو زیادہ تر لوگ جو اس میں داخل ہوئے ، مسکین تھے اور میں نے دیکھا کہ مال و متاع والے ( جنتی ) باہر روکے ہوئے تھے ، سوائے ( مالدار ) دوزخیوں کے ، انہیں جہنم میں ڈالنے کا حکم ( فورا ہی ) صادر کر دیا گیا تھا ۔ اور میں جہنم کے دروازے پر کھڑا ہوا تو دیکھا کہ اس میں داخل ہونے والی بیشتر عورتیں تھیں ۔","",{"u2":"حماد بن سلمہ، معاذ بن معاذ، عنبری، معتمر، جریر اور یزید بن زُریع نے کہا: ہمیں سلیمان تیمی نے ابوعثمان سے حدیث بیان کی، انہوں نے حضرت اسامہ بن زید رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میں جنت کے دروازے پر کھڑا ہوا تو زیادہ تر لوگ جو اس میں داخل ہوئے، مسکین تھے اور میں نے دیکھا کہ مال و متاع والے (جنتی) باہر روکے ہوئے تھے، سوائے (مالدار) دوزخیوں کے، انہیں جہنم میں ڈالنے کا حکم (فورا ہی) صادر کر دیا گیا تھا۔ اور میں جہنم کے دروازے پر کھڑا ہوا تو دیکھا کہ اس میں داخل ہونے والی بیشتر عورتیں تھیں۔\""}],[6994,"اسماعیل بن ابراہیم نے ایوب سے ، انہوں نے ابورجاء عطاروی سے روایت کی ، انہوں نے کہا : میں نے سیدنا ابن عباس رضی اللہ عنہ کو بیان کرتے ہوئے سنا کہ حضرت محمد صلی اللہ علیہ وسلم نے فرمایا : \" میں نے جنت کے اندر جھانک کر دیکھا تو میں نے اہل جنت میں اکثریت فقراء کی دیکھی اور میں نے دوزخ میں جھانک کر دیکھا تو میں نے دوزخ میں اکثریت عورتوں کی دیکھی ۔","",{"u2":"اسماعیل بن ابراہیم نے ایوب سے، انہوں نے ابورجاء عطاروی سے روایت کی، انہوں نے کہا: میں نے حضرت ابن عباس رضی اللہ عنہ کو بیان کرتے ہوئے سنا کہ حضرت محمد صلی اللہ علیہ وسلم نے فرمایا: \"میں نے جنت کے اندر جھانک کر دیکھا تو میں نے اہل جنت میں اکثریت فقراء کی دیکھی اور میں نے دوزخ میں جھانک کر دیکھا تو میں نے دوزخ میں اکثریت عورتوں کی دیکھی۔\""}],[6995,"(عبدالوہاب ) ثقفی نے بتایا : ایوب نے ہمیں اسی سند کے ساتھ ( یہی ) حدیث بیان کی ۔","",{"u2":"(عبدالوہاب) ثقفی نے بتایا: ایوب نے ہمیں اسی سند کے ساتھ (یہی) حدیث بیان کی۔"}],[6996,"ابو اشہب نے ہمیں حدیث بیان کی ، کہا : ہمیں ابو رجاء نے سیدنا ابن عباس رضی اللہ عنہ سے حدیث بیان کی کہ نبی صلی اللہ علیہ وسلم نے آگ ( جہنم ) میں جھانک کر دیکھا ۔ پھر ایوب کی حدیث کے مانند ذکر کیا ۔","",{"u2":"ابو اشہب نے ہمیں حدیث بیان کی، کہا: ہمیں ابو رجاء نے حضرت ابن عباس رضی اللہ عنہ سے حدیث بیان کی کہ نبی صلی اللہ علیہ وسلم نے آگ (جہنم) میں جھانک کر دیکھا۔ پھر ایوب کی حدیث کے مانند ذکر کیا۔"}],[6997,"سعید بن ابی عروبہ سے روایت ہے ، انہوں نے ابورجاء سے سنا ، انہوں نے سیدنا ابن عباس رضی اللہ عنہ سے روایت کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ، پھر اسی کے مانند ذکر کیا ۔","",{"u2":"سعید بن ابی عروبہ سے روایت ہے، انہوں نے ابورجاء سے سنا، انہوں نے حضرت ابن عباس رضی اللہ عنہ سے روایت کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا، پھر اسی کے مانند ذکر کیا۔"}],[6998,"معاذ نے کہا : ہمیں شعبہ نے ابوتیاح سے حدیث بیان کی ، انہوں نے کہا : مطرف بن عبداللہ کی دو بیویاں تھیں ، وہ ایک بیوی کے پاس سے آئے تو دوسری نے کہا : تم فلاں عورت ( دوسری بیوی کا نام لیا ) کے پاس سے آئے ہو؟ انہوں نے کہا : میں سیدنا عمران بن حصین رضی اللہ عنہ کے پاس سے ( بھی ہو کر ) آیا ہوں اور انہوں نے ہمیں یہ حدیث بیان کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جنت میں رہنے والوں میں سب سے کم تعداد عورتوں کی ہے ۔","",{"u2":"معاذ نے کہا: ہمیں شعبہ نے ابوتیاح سے حدیث بیان کی، انہوں نے کہا: مطرف بن عبداللہ کی دو بیویاں تھیں، وہ ایک بیوی کے پاس سے آئے تو دوسری نے کہا: تم فلاں عورت (دوسری بیوی کا نام لیا) کے پاس سے آئے ہو؟ انہوں نے کہا: میں حضرت عمران بن حصین رضی اللہ عنہ کے پاس سے (بھی ہو کر) آیا ہوں اور انہوں نے ہمیں یہ حدیث بیان کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جنت میں رہنے والوں میں سب سے کم تعداد عورتوں کی ہے۔\""}],[6999,"ہمیں محمد بن جعفر نے حدیث بیان کی ، کہا : ہمیں شعبہ نے ابوتیاح سے حدیث سنائی ، کہا : میں نے مطرف کو حدیث بیان کرتے ہوئے سنا کہ ان کی دو بیویاں تھیں ( آگے ) معاذ کی حدیث کے ہم معنی ( روایت کی ۔)","",{"u2":") ہمیں محمد بن جعفر نے حدیث بیان کی، کہا: ہمیں شعبہ نے ابوتیاح سے حدیث سنائی، کہا: میں نے مطرف کو حدیث بیان کرتے ہوئے سنا کہ ان کی دو بیویاں تھیں (آگے) معاذ کی حدیث کے ہم معنی (روایت کی۔)"}],[7000,"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے ، کہا : رسول اللہ صلی اللہ علیہ وسلم کی دعاؤں میں سے ایک یہ تھی : \" اے اللہ! میں تیری پناہ چاہتا ہوں تیری نعمت کے زوال سے ، تیری عافیت کے ہٹ جانے سے ، تیری ناگہانی سزا سے اور تیری ہر طرح کی ناراضی سے ۔","",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے، کہا: رسول اللہ صلی اللہ علیہ وسلم کی دعاؤں میں سے ایک یہ تھی: \"اے اللہ! میں تیری پناہ چاہتا ہوں تیری نعمت کے زوال سے، تیری عافیت کے ہٹ جانے سے، تیری ناگہانی سزا سے اور تیری ہر طرح کی ناراضی سے۔\""}],[7001,"سعید بن منصور نے کہا : ہمیں سفیان اور معتمر بن سلیمان نے سلیمان تیمی سے حدیث بیان کی ، انہوں نے ابوعثمان نہدی سے اور انہوں نے سیدنا اسامہ بن زید رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" میں نے اپنے بعد کوئی آزمائش نہیں چھوڑی جو مردوں کے لیے عورتوں ( کی آزمائش ) سے بڑھ کر نقصان پہنچانے والی ہو ۔","",{"u2":"سعید بن منصور نے کہا: ہمیں سفیان اور معتمر بن سلیمان نے سلیمان تیمی سے حدیث بیان کی، انہوں نے ابوعثمان نہدی سے اور انہوں نے حضرت اسامہ بن زید رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میں نے اپنے بعد کوئی آزمائش نہیں چھوڑی جو مردوں کے لیے عورتوں (کی آزمائش) سے بڑھ کر نقصان پہنچانے والی ہو۔\""}],[7002,"عبیداللہ بن معاذ عنبری ، سعید بن سعید اور محمد بن عبدالاعلی نے ہمیں معتمر سے حدیث بیان کی ۔ ابن معاذ نے کہا : ہمیں معتمر بن سلیمان نے حدیث بیان کی ، انہوں نے کہا : میرے والد نے کہا : ہمیں ابوعثمان نے سیدنا اسامہ بن زید اور سیدنا سعید بن زید رضی اللہ عنہ سے روایت کی ، ان دونوں نے رسول اللہ صلی اللہ علیہ وسلم سے حدیث بیان کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" میں اپنے بعد لوگوں میں کوئی ایسا فتنہ چھوڑ کر نہیں جا رہا جو مردوں کے لیے عورتوں سے بڑھ کر نقصان پہنچانے والا ہو ۔","",{"u2":"عبیداللہ بن معاذ عنبری، سعید بن سعید اور محمد بن عبدالاعلیٰ نے ہمیں معتمر سے حدیث بیان کی۔ ابن معاذ نے کہا: ہمیں معتمر بن سلیمان نے حدیث بیان کی، انہوں نے کہا: میرے والد نے کہا: ہمیں ابوعثمان نے حضرت اسامہ بن زید اور حضرت سعید بن زید رضی اللہ عنہ سے روایت کی، ان دونوں نے رسول اللہ صلی اللہ علیہ وسلم سے حدیث بیان کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں اپنے بعد لوگوں میں کوئی ایسا فتنہ چھوڑ کر نہیں جا رہا جو مردوں کے لیے عورتوں سے بڑھ کر نقصان پہنچانے والا ہو۔\""}],[7003,"ابوخالد احمر ، ہشیم اور جریر سب نے سلیمان تیمی سے ، اسی سند کے ساتھ ، اسی کے مانند حدیث بیان کی ۔","",{"u2":"ابوخالد احمر، ہشیم اور جریر سب نے سلیمان تیمی سے، اسی سند کے ساتھ، اسی کے مانند حدیث بیان کی۔"}],[7004,"محمد بن مثنی اور محمد بن بشار نے ہمیں حدیث بیان کی ، دونوں نے کہا : ہمیں محمد بن جعفر نے حدیث سنائی ، انہوں نے کہا : ہمیں شعبہ نے ابوسلمہ سے حدیث بیان کی ، انہوں نے کہا : میں نے ابونضرہ سے سنا ، وہ سیدنا ابوسعید خدری رضی اللہ عنہ سے روایت کر رہے تھے ، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" بلاشبہ دنیا بہت میٹھی اور ہری بھری ہے اور اللہ تعالی اس میں تمہیں ( تم سے پہلے والوں کا ) جانشیں بنانے والا ہے ، پھر وہ دیکھے گا کہ تم کیسے عمل کرتے ہو ، لہٰذا تم دنیا ( میں کھو جانے سے ) بچتے رہنا اور عورتوں ( کے فتنے میں مبتلا ہونے سے ) بچ کر رہنا ، اس لیے کہ بنی اسرائیل میں سب سے پہلا فتنہ عورتوں ( کے معاملے ) میں تھا ۔ \"\" اور بشار کی حدیث میں ہے : \"\" تاکہ وہ دیکھے کہ تم کس طرح عمل کرتے ہو ۔","",{"u2":"محمد بن مثنیٰ اور محمد بن بشار نے ہمیں حدیث بیان کی، دونوں نے کہا: ہمیں محمد بن جعفر نے حدیث سنائی، انہوں نے کہا: ہمیں شعبہ نے ابوسلمہ سے حدیث بیان کی، انہوں نے کہا: میں نے ابونضرہ سے سنا، وہ حضرت ابوسعید خدری رضی اللہ عنہ سے روایت کر رہے تھے، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"بلاشبہ دنیا بہت میٹھی اور ہری بھری ہے اور اللہ تعالیٰ اس میں تمہیں (تم سے پہلے والوں کا) جانشیں بنانے والا ہے، پھر وہ دیکھے گا کہ تم کیسے عمل کرتے ہو، لہذا تم دنیا (میں کھو جانے سے) بچتے رہنا اور عورتوں (کے فتنے میں مبتلا ہونے سے) بچ کر رہنا، اس لیے کہ بنی اسرائیل میں سب سے پہلا فتنہ عورتوں (کے معاملے) میں تھا۔\"\nاور بشار کی حدیث میں ہے: \"تاکہ وہ دیکھے کہ تم کس طرح عمل کرتے ہو۔\""}],[7005,"انس بن عیاض ابو ضمرہ نے موسی بن عقبہ سے ، انہوں نے نافع سے ، انہوں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی ۔ آپ نے فرمایا : \"\" تین آدمی پیدال چلے جا رہے تھے کہ انہیں بارش نے آ لیا ، انہوں نے پہاڑ میں ایک غار کی پناہ لی ، تو ( اچانک ) ان کے گار کے منہ پر پہاڑ سے ایک چٹان آ گری اور ان کے اوپر آ کر انہیں ڈھانک دیا ، انہوں نے ایک دوسرے سے کہا : تم اپنے ان نیک اعمال پر نظر ڈالو جو تم نے ( صرف اور صرف ) اللہ کے لیے کیے ہوں اور ان کے وسیلے سے اللہ تعالی سے دعا کرو ، شاید وہ اس بندش اور قید سے تمہیں آزاد کر دے ۔ اس پر ان میں سے ایک نے کہا ، اے اللہ! میرے انتہائی بوڑھے والدین ، بیوی اور چھوٹے چھوٹے بچے ہیں جن کی میں نگہداشت کرتا ہوں ۔ جب شام کو میں اپنے جانور ( چرانے کے بعد انہیں ) ان کے پاس واپس آتا ، ان کا دودھ دوہتا تو آغاز اپنے والدین سے کرتا اور اپنے بچوں سے پہلے انہیں پلاتا تھا ۔ ایک دن ( مویشیوں کے چرنے کے قابل ) درختوں کی تلاش مجھے بہت دور لے گئی ، میں رات سے پہلے گھر نہ پہنچ سکا ۔ میں نے انہیں پایا کہ وہ دونوں سو چکے ہیں ۔ میں جس طرح 0ہر روز ) دودھ نکالا کرتا تھا نکالا اور وہ ڈوبا ہوا دودھ لے کر ان کے سرہانے کھڑا ہو گیا ۔ مجھے یہ بھی ناپسند تھا کہ ان کو نیند سے جگاؤں اور یہ بھی گوارا نہ تھا کہ ان سے پہلے بچوں کو پلاؤں ، بچے بھوک کی شدت سے بلکتے ہوئے میرے قدموں میں لوٹ پوٹ ہو رہے تھے ، میں اسی حال میں ( کھڑا ) رہا اور وہ بھی اسی حالت میں رہے یہاں تک کہ صبح طلوع ہو گئی ۔ ( اے اللہ! ) اگر تو جانتا ہے کہ میں نے یہ صرف تیری رضا کے لیے کیا ہے تو اس ( غار کے بند منہ ) میں اتنا سوراخ کر دے کہ ہم آسمان کو دیکھ لیں ۔ اللہ نے اس میں ایک سوراخ کر دیا کہ وہ آسمان کو دیکھنے لگے ۔ اور دوسرا ( ساتھی ) کہنے لگا : اے اللہ! میری ایک چچا زاد تھی ، میں اس سے وہی شدید محبت کرتا تھا جو ایک مرد عورت سے کرتا ہے ۔ میں نے اس سے اپنے لیے ( خود ) اسی کو مانگا ۔ اس نے اس وقت تک ( میری بات ماننے سے ) انکار کر دیا ، یہاں تک کہ میں اسے ( سونے کے ) سو دینار لا کر دوں ۔ میں انہیں حاصل کرنے میں لگ گیا یہاں تک کہ سو دینار اکٹھے کر لیے ، پھر جب میں ان کے دونوں قدموں کے درمیان پہنچا تو وہ کہنے لگی : اللہ کے بندے! اللہ سے ڈر اور حق ( نکاح ) کے بغیر مہر ( بکارت ) نہ توڑ ۔ تو ( تیرا نام سن کر ) میں اس سے ( الگ ہو کر ) کھڑا ہو گیا ۔ اگر تو جانتا ہے کہ میں نے یہ تجھے راضی کرنے کے لیے کیا تھا تو اس میں ( اور زیادہ ) سوراخ کر دے ( اللہ نے ) ان کے لیے ( اور زیادہ ) سوراخ کر دیا ۔ اور تیسرے نے ( دعا کرتے ہوئے ) کہا : اے اللہ! میں نے ایک مزدور کو چاولوں کے ایک فرق ( تین صاع ، تقریبا ساڑھے سات کلو گرام ) کی اجرت کے عوض کام پر لگایا ۔ جب اس نے اپنا کام پورا کر لیا تو کہا : میرا حق ( اجرت ) ادا کرو ۔ میں نے اسے اس کا فرق ( تین صاع چاول ) پیش کیا ۔ وہ ( اسے کم قرار دیتے ہوئے ) اس کو چھوڑ کر چلا گیا ۔ میں مسلسل اس ( تین صاع چاولوں ) کو کاشت کرنے لگا ، یہاں تک کہ میں نے اس ( کی آمدنی ) سے گائے ( کے بہت سے ریوڑ ) اور ان کو چرانے والے ( غلام ) اکٹھے کر لیے ۔ پھر ( مدت بعد ) وہ میرے پاس ( واپس ) آیا اور کہا : اللہ سے ڈرو ، میرے حق میں مجھ پر ظلم نہ کرو ۔ میں نے کہا : ان گایوں ( کے ریوڑوں ) اور انہیں چرانے والے ( غلاموں ) کی طرف جاؤ اور انہیں لے لو ۔ اس نے کہا : اللہ سے ڈرو! میرے ساتھ مذاق تو نہ کرو ۔ میں نے کہا : میں مذاق نہیں کر رہا ، یہ سب گائیں اور ان کو چرانے والے ( غلام ) لے جاؤ ، وہ انہیں لے کر چلا گیا ۔ اگر تو جانتا ہے کہ میں نے یہ صرف تجھے راضی کرنے کے لیے کیا تھا تو جو حصہ باقی رہ گیا ہے ، اسے بھی کھول دے ۔ اللہ نے باقی حصہ بھی کھول دیا ( اور وہ آزاد ہو کر غار سے باہر نکل آئے ۔)","",{"u2":"انس بن عیاض ابو ضمرہ نے موسیٰ بن عقبہ سے، انہوں نے نافع سے، انہوں نے حضرت عبداللہ بن عمر رضی اللہ عنہ سے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی۔ آپ نے فرمایا: \"تین آدمی پیدال چلے جا رہے تھے کہ انہیں بارش نے آ لیا، انہوں نے پہاڑ میں ایک غار کی پناہ لی، تو (اچانک) ان کے گار کے منہ پر پہاڑ سے ایک چٹان آ گری اور ان کے اوپر آ کر انہیں ڈھانک دیا، انہوں نے ایک دوسرے سے کہا: تم اپنے ان نیک اعمال پر نظر ڈالو جو تم نے (صرف اور صرف) اللہ کے لیے کیے ہوں اور ان کے وسیلے سے اللہ تعالیٰ سے دعا کرو، شاید وہ اس بندش اور قید سے تمہیں آزاد کر دے۔ اس پر ان میں سے ایک نے کہا، اے اللہ! میرے انتہائی بوڑھے والدین، بیوی اور چھوٹے چھوٹے بچے ہیں جن کی میں نگہداشت کرتا ہوں۔ جب شام کو میں اپنے جانور (چرانے کے بعد انہیں) ان کے پاس واپس آتا، ان کا دودھ دوہتا تو آغاز اپنے والدین سے کرتا اور اپنے بچوں سے پہلے انہیں پلاتا تھا۔ ایک دن (مویشیوں کے چرنے کے قابل) درختوں کی تلاش مجھے بہت دور لے گئی، میں رات سے پہلے گھر نہ پہنچ سکا۔ میں نے انہیں پایا کہ وہ دونوں سو چکے ہیں۔ میں جس طرح 0ہر روز) دودھ نکالا کرتا تھا نکالا اور وہ ڈوبا ہوا دودھ لے کر ان کے سرہانے کھڑا ہو گیا۔ مجھے یہ بھی ناپسند تھا کہ ان کو نیند سے جگاؤں اور یہ بھی گوارا نہ تھا کہ ان سے پہلے بچوں کو پلاؤں، بچے بھوک کی شدت سے بلکتے ہوئے میرے قدموں میں لوٹ پوٹ ہو رہے تھے، میں اسی حال میں (کھڑا) رہا اور وہ بھی اسی حالت میں رہے یہاں تک کہ صبح طلوع ہو گئی۔ (اے اللہ!) اگر تو جانتا ہے کہ میں نے یہ صرف تیری رضا کے لیے کیا ہے تو اس (غار کے بند منہ) میں اتنا سوراخ کر دے کہ ہم آسمان کو دیکھ لیں۔ اللہ نے اس میں ایک سوراخ کر دیا کہ وہ آسمان کو دیکھنے لگے۔\nاور دوسرا (ساتھی) کہنے لگا: اے اللہ! میری ایک چچا زاد تھی، میں اس سے وہی شدید محبت کرتا تھا جو ایک مرد عورت سے کرتا ہے۔ میں نے اس سے اپنے لیے (خود) اسی کو مانگا۔ اس نے اس وقت تک (میری بات ماننے سے) انکار کر دیا، یہاں تک کہ میں اسے (سونے کے) سو دینار لا کر دوں۔ میں انہیں حاصل کرنے میں لگ گیا یہاں تک کہ سو دینار اکٹھے کر لیے، پھر جب میں ان کے دونوں قدموں کے درمیان پہنچا تو وہ کہنے لگی: اللہ کے بندے! اللہ سے ڈر اور حق (نکاح) کے بغیر مہر (بکارت) نہ توڑ۔ تو (تیرا نام سن کر) میں اس سے (الگ ہو کر) کھڑا ہو گیا۔ اگر تو جانتا ہے کہ میں نے یہ تجھے راضی کرنے کے لیے کیا تھا تو اس میں (اور زیادہ) سوراخ کر دے (اللہ نے) ان کے لیے (اور زیادہ) سوراخ کر دیا۔\nاور تیسرے نے (دعا کرتے ہوئے) کہا: اے اللہ! میں نے ایک مزدور کو چاولوں کے ایک فرق (تین صاع، تقریبا ساڑھے سات کلو گرام) کی اجرت کے عوض کام پر لگایا۔ جب اس نے اپنا کام پورا کر لیا تو کہا: میرا حق (اجرت) ادا کرو۔ میں نے اسے اس کا فرق (تین صاع چاول) پیش کیا۔ وہ (اسے کم قرار دیتے ہوئے) اس کو چھوڑ کر چلا گیا۔ میں مسلسل اس (تین صاع چاولوں) کو کاشت کرنے لگا، یہاں تک کہ میں نے اس (کی آمدنی) سے گائے (کے بہت سے ریوڑ) اور ان کو چرانے والے (غلام) اکٹھے کر لیے۔ پھر (مدت بعد) وہ میرے پاس (واپس) آیا اور کہا: اللہ سے ڈرو، میرے حق میں مجھ پر ظلم نہ کرو۔ میں نے کہا: ان گایوں (کے ریوڑوں) اور انہیں چرانے والے (غلاموں) کی طرف جاؤ اور انہیں لے لو۔ اس نے کہا: اللہ سے ڈرو! میرے ساتھ مذاق تو نہ کرو۔ میں نے کہا: میں مذاق نہیں کر رہا، یہ سب گائیں اور ان کو چرانے والے (غلام) لے جاؤ، وہ انہیں لے کر چلا گیا۔ اگر تو جانتا ہے کہ میں نے یہ صرف تجھے راضی کرنے کے لیے کیا تھا تو جو حصہ باقی رہ گیا ہے، اسے بھی کھول دے۔ اللہ نے باقی حصہ بھی کھول دیا (اور وہ آزاد ہو کر غار سے باہر نکل آئے۔)\""}],[7006,"موسی بن عقبہ ، عبیداللہ ، فُضیل ، رقبہ بن مسقلہ اور صالح بن کیسان سب نے نافع سے ، انہوں نے ابن عمر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے ابوضمرہ کی موسی بن عقبہ سے روایت کردہ حدیث کے ہم معنی روایت کی اور انہوں نے ان کی حدیث میں ( پیدل چلے جا رہے تھے کے ساتھ ) \" اور وہ پیدل چلتے ہوئے نکلے \" کے الفاظ بڑھائے اورعبیداللہ کی روایت کو چھوڑ کر صالح کی حدیث میں \" وہ مل کر پیدل چلے \" کے الفاظ ہیں جبکہ ان ( عبیداللہ ) کی حدیث میں \" اور وہ نکلے \" کا لفظ ہے اور انہوں نے اس کے بعد ( پیدل چلتے ہوئے وغیرہ ) کا کچھ ذکر نہیں کیا ۔","",{"u2":"موسیٰ بن عقبہ، عبیداللہ، فُضیل، رقبہ بن مسقلہ اور صالح بن کیسان سب نے نافع سے، انہوں نے ابن عمر رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے ابوضمرہ کی موسیٰ بن عقبہ سے روایت کردہ حدیث کے ہم معنی روایت کی اور انہوں نے ان کی حدیث میں (پیدل چلے جا رہے تھے کے ساتھ) \"اور وہ پیدل چلتے ہوئے نکلے\" کے الفاظ بڑھائے اورعبیداللہ کی روایت کو چھوڑ کر صالح کی حدیث میں \"وہ مل کر پیدل چلے\" کے الفاظ ہیں جبکہ ان (عبیداللہ) کی حدیث میں \"اور وہ نکلے\" کا لفظ ہے اور انہوں نے اس کے بعد (پیدل چلتے ہوئے وغیرہ) کا کچھ ذکر نہیں کیا۔"}],[7007,"سالم بن عبداللہ ( بن عمر ) نے مجھے خبر دی کہ سیدنا عبداللہ بن عمر رضی اللہ عنہ نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا : \" تم سے پہلے لوگوں میں سے تین شخص ( کسی غرض سے ) روانہ ہوئے ، حتی کہ رات گزارنے کی ضرورت انہیں ایک غار کی پناہ گاہ میں لے آئی \" پھر انہوں نے ابن عمر رضی اللہ عنہ سے نافع کی روایت کے مطابق واقعہ بیان کیا مگر کہا : \" اے اللہ! میرے انتہائی بوڑھے والدین تھے ، میں رات کے وقت ان دونوں سے پہلے نہ گھر والوں کو دودھ پلاتا تھا ، نہ مال کو ( اپنی ملکیت کے غلاموں یا مویشیوں کے ان بچوں کو جن کی اپنی مائیں نہ تھیں ) دودھ پلاتا تھا ۔ \" اور ( یہ بھی ) کہا : \" ( میری عم زاد ) مجھ سے دور رہی یہاں تک کہ ایک قحط سالی کا شکار ہو گئی ، وہ میرے پاس آئی تو میں نے اسے ( سو کے بجائے جو اس نے مانگے تھے ) ایک سو بیس دینار دیے ۔ \" اور ( تیسرے شخص کے واقعے میں ) اس نے کہا : \" میں نے اس کی اجرت کو ( کاشتکاری اور تجارت کے ذریعے ) خوب بار آور بنایا ، یہاں تک کہ ایسا کرنے سے مال مویشی بہت بڑھ گئے اور پھیل گئے ۔ \" اور آخر میں کہا : \" تو وہ چلتے ہوئے غار سے باہر آ گئے ۔","",{"u2":"سالم بن عبداللہ (بن عمر) نے مجھے خبر دی کہ حضرت عبداللہ بن عمر رضی اللہ عنہ نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"تم سے پہلے لوگوں میں سے تین شخص (کسی غرض سے) روانہ ہوئے، حتی کہ رات گزارنے کی ضرورت انہیں ایک غار کی پناہ گاہ میں لے آئی\" پھر انہوں نے ابن عمر رضی اللہ عنہ سے نافع کی روایت کے مطابق واقعہ بیان کیا مگر کہا: \"اے اللہ! میرے انتہائی بوڑھے والدین تھے، میں رات کے وقت ان دونوں سے پہلے نہ گھر والوں کو دودھ پلاتا تھا، نہ مال کو (اپنی ملکیت کے غلاموں یا مویشیوں کے ان بچوں کو جن کی اپنی مائیں نہ تھیں) دودھ پلاتا تھا۔\" اور (یہ بھی) کہا: \"(میری عم زاد) مجھ سے دور رہی یہاں تک کہ ایک قحط سالی کا شکار ہو گئی، وہ میرے پاس آئی تو میں نے اسے (سو کے بجائے جو اس نے مانگے تھے) ایک سو بیس دینار دیے۔\" اور (تیسرے شخص کے واقعے میں) اس نے کہا: \"میں نے اس کی اجرت کو (کاشتکاری اور تجارت کے ذریعے) خوب بار آور بنایا، یہاں تک کہ ایسا کرنے سے مال مویشی بہت بڑھ گئے اور پھیل گئے۔\" اور آخر میں کہا: \"تو وہ چلتے ہوئے غار سے باہر آ گئے۔\""}],[7008,"ابوصالح نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ عزوجل نے فرمایا : میرے بارے میں میرے بندے کا جو گمان ہو میں اس کے ساتھ ( مطابق ہوتا ) ہوں اور وہ مجھے جہاں ( بھی ) یاد کرے میں اس کے پاس ہوتا ہوں ۔ اللہ کی قسم! اللہ تعالی اپنے بندے کی توبہ پر تم میں سے ایسے آدمی کی نسبت بھی زیادہ خوش ہوتا ہے جسے چٹیل بیابان میں اپنی گم شدہ سواری ( سامان سمیت واپس ) مل جاتی ہے ۔ ( میرا ) جو بندہ ایک بالشت میرے قریب آتا ہے ، میں ایک ہاتھ اس کے قریب آ جاتا ہوں اور جو ایک ہاتھ میرے قریب ہوتا ہے ، میں دونوں ہاتھوں کی پوری لمبائی کے برابر اس کے قریب ہو جاتا ہوں اور جو چلتا ہوا میری طرف آتا ہے ، میں دوڑتا ہوا اس کے پاس آتا ہوں ۔","",{"u2":") ابوصالح نے حضرت ابوہریرہ رضی اللہ عنہ سے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ عزوجل نے فرمایا: میرے بارے میں میرے بندے کا جو گمان ہو میں اس کے ساتھ (مطابق ہوتا) ہوں اور وہ مجھے جہاں (بھی) یاد کرے میں اس کے پاس ہوتا ہوں۔ اللہ کی قسم! اللہ تعالیٰ اپنے بندے کی توبہ پر تم میں سے ایسے آدمی کی نسبت بھی زیادہ خوش ہوتا ہے جسے چٹیل بیابان میں اپنی گم شدہ سواری (سامان سمیت واپس) مل جاتی ہے۔ (میرا) جو بندہ ایک بالشت میرے قریب آتا ہے، میں ایک ہاتھ اس کے قریب آ جاتا ہوں اور جو ایک ہاتھ میرے قریب ہوتا ہے، میں دونوں ہاتھوں کی پوری لمبائی کے برابر اس کے قریب ہو جاتا ہوں اور جو چلتا ہوا میری طرف آتا ہے، میں دوڑتا ہوا اس کے پاس آتا ہوں۔\""}],[7009,"اعرج نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ تعالی یقینا تم میں سے کسی کے توبہ کرنے پر اس سے زیادہ خوش ہوتا ہے جتنا تم میں سے کوئی شخص اپنی گم شدہ سواری ( واپس ) پا کر خوش ہوتا ہے ۔","",{"u2":"اعرج نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ یقینا تم میں سے کسی کے توبہ کرنے پر اس سے زیادہ خوش ہوتا ہے جتنا تم میں سے کوئی شخص اپنی گم شدہ سواری (واپس) پا کر خوش ہوتا ہے۔\""}],[7010,"ہمام بن منبہ نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے ہم معنی روایت کی ۔","",{"u2":"ہمام بن منبہ نے حضرت ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے اسی کے ہم معنی روایت کی۔"}],[7011,"جریر نے اعمش سے ، انہوں نے عمارہ بن عمیر سے اور انہوں نے حارث بن سُوید سے روایت کی ، انہوں نے کہا : میں سیدنا عبداللہ ( بن مسعود رضی اللہ عنہ ) کے ہاں حاضر ہوا ، اس وقت وہ بیمار تھے ، انہوں نے ہمیں وہ حدیثیں بیان کیں ، ایک حدیث اپنی طرف سے اور ایک حدیث رسول اللہ صلی اللہ علیہ وسلم کی طرف سے ، انہوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آپ فرماتے تھے : \" اللہ تعالی اپنے مومن بندے کی توبہ پر اس سے زیادہ خوش ہوتا ہے جتنا وہ آدمی ( خوش ہوتا ہے ) جو ہلاکت خیز سنسان اور بے آب و گیاہ میدان میں ہو ، اس کے ساتھ اس کی سواری ہو ، اس ( سواری ) پر اس کا کھانا اور پانی لدا ہوا ہو ، وہ ( تھکا ہارا کچھ دیر کے لئے ) سو جائے اور جب جاگے تو سواری جا چکی ہو ۔ وہ ڈھونڈتا رہے یہاں تک کہ اسے شدید پیاس لگ جائے ، پھر وہ کہے : میں جہاں پر تھا ، اسی جگہ واپس جاتا ہوں اور سو جاتا ہوں ، یہاں تک کہ ( اس نیند کے عالم میں ) مجھے موت آ جائے ۔ وہ اپنی کلائی پر سر رکھ کر مرنے کے لیے لیٹ جائے اور ( اچانک ) اس کی آنکھ کھلے تو اس کی وہ سواری جس پر اس کا زادراہ کھانا اور پانی تھا اس کے پاس کھڑی ہو ۔ تو اللہ اپنے مومن بندے کی توبہ پر اس سے زیادہ خوش ہوتا ہے جتنا یہ آدمی اپنی سواری اور زادراہ سے خوش ہوتا ہے ۔","",{"u2":"جریر نے اعمش سے، انہوں نے عمارہ بن عمیر سے اور انہوں نے حارث بن سُوید سے روایت کی، انہوں نے کہا: میں حضرت عبداللہ (بن مسعود رضی اللہ عنہ) کے ہاں حاضر ہوا، اس وقت وہ بیمار تھے، انہوں نے ہمیں وہ حدیثیں بیان کیں، ایک حدیث اپنی طرف سے اور ایک حدیث رسول اللہ صلی اللہ علیہ وسلم کی طرف سے، انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، آپ فرماتے تھے: \"اللہ تعالیٰ اپنے مومن بندے کی توبہ پر اس سے زیادہ خوش ہوتا ہے جتنا وہ آدمی (خوش ہوتا ہے) جو ہلاکت خیز سنسان اور بے آب و گیاہ میدان میں ہو، اس کے ساتھ اس کی سواری ہو، اس (سواری) پر اس کا کھانا اور پانی لدا ہوا ہو، وہ (تھکا ہارا کچھ دیر کے لئے) سو جائے اور جب جاگے تو سواری جا چکی ہو۔ وہ ڈھونڈتا رہے یہاں تک کہ اسے شدید پیاس لگ جائے، پھر وہ کہے: میں جہاں پر تھا، اسی جگہ واپس جاتا ہوں اور سو جاتا ہوں، یہاں تک کہ (اس نیند کے عالم میں) مجھے موت آ جائے۔ وہ اپنی کلائی پر سر رکھ کر مرنے کے لیے لیٹ جائے اور (اچانک) اس کی آنکھ کھلے تو اس کی وہ سواری جس پر اس کا زادراہ کھانا اور پانی تھا اس کے پاس کھڑی ہو۔ تو اللہ اپنے مومن بندے کی توبہ پر اس سے زیادہ خوش ہوتا ہے جتنا یہ آدمی اپنی سواری اور زادراہ سے خوش ہوتا ہے۔\""}],[7012,"قطبہ بن عبدالعزیز نے اعمش سے اسی سند کے ساتھ روایت کی اور کہا : \" اس آدمی کی نسبت ( زیادہ خوش ہوتا ہے ) جو زمین کے سنسان بے آب و گیاہ صحرا میں ہو ۔ \" دوية کے بجائے داوية کا لفظ بولا ، معنی ایک ہی ہے ۔","",{"u2":"قطبہ بن عبدالعزیز نے اعمش سے اسی سند کے ساتھ روایت کی اور کہا: \"اس آدمی کی نسبت (زیادہ خوش ہوتا ہے) جو زمین کے سنسان بے آب و گیاہ صحرا میں ہو۔\" دویۃ کے بجائے داویۃ کا لفظ بولا، معنی ایک ہی ہے۔)"}],[7013,"ابواسامہ نے کہا : ہمیں اعمش نے حدیث بیان کی ، انہوں نے کہا : ہمیں عمارہ بن عمیر نے حدیث سنائی ، انہوں نے کہا : میں نے حارث بن سوید سے سنا ، کہا : مجھے سیدنا عبداللہ ( بن مسعود رضی اللہ عنہ ) نے وہ حدیثیں بیان کیں ، ایک رسول اللہ صلی اللہ علیہ وسلم سے ( نقل کرتے ہوئے ) اور دوسری اپنی طرف سے ، چنانچہ انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" بلاشبہ اللہ اپنے مومن بندے کی توبہ سے ( اس آدمی کی نسبت ) زیادہ خوش ہوتا ہے \" ( آگے ) جریر کی حدیث کے مانند ۔","",{"u2":"ابواسامہ نے کہا: ہمیں اعمش نے حدیث بیان کی، انہوں نے کہا: ہمیں عمارہ بن عمیر نے حدیث سنائی، انہوں نے کہا: میں نے حارث بن سوید سے سنا، کہا: مجھے حضرت عبداللہ (بن مسعود رضی اللہ عنہ) نے وہ حدیثیں بیان کیں، ایک رسول اللہ صلی اللہ علیہ وسلم سے (نقل کرتے ہوئے) اور دوسری اپنی طرف سے، چنانچہ انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بلاشبہ اللہ اپنے مومن بندے کی توبہ سے (اس آدمی کی نسبت) زیادہ خوش ہوتا ہے\" (آگے) جریر کی حدیث کے مانند۔"}],[7014,"ابو یونس نے سماک سے روایت کی ، کہا : سیدنا نعمان بن بشیر رضی اللہ عنہ نے خطبہ دیا اور ( آپ صلی اللہ علیہ وسلم کا فرمان ) بیان کیا : \"\" اللہ تعالی کو اپنے بندے کی توبہ پر اس شخص کی نسبت زیادہ خوشی ہوتی ہے جس نے اپنا زادراہ اور اپنی پانی کی بڑی مشک کو اونٹ پر لادا ، پھر ( سفر پر ) چل پڑا ، یہاں تک کہ جب وہ ایک چٹیل زمین پر تھا تو اسے دوپہر کی نیند نے بے بس کر دیا ، وہ اترا اور ایک درخت کے نیچے دوپہر کے آرام کے لیے لیٹ گیا ، اس کی آنکھ لگ گئی اور اس کا اونٹ کسی طرف کو نکل گیا ، پھر وہ جاگا تو کوشش کر کے ایک ٹیلے پر چڑھا ( ہر طرف دیکھا ) لیکن اسے کچھ نظر نہ آیا ، پھر وہ مشقت اٹھا کر دوسرے ٹیلے پر چڑھا ، اسے کچھ نظر نہ آیا ، پھر ( مزید ) مشقت سے تیسرے ٹیلے پر چڑھا تو اسے کچھ نظر نہ آیا ، پھر وہ آیا ، اسی جگہ پہنچا جہاں دوپہر کا آرام کیا تھا ، وہ ( اس جگہ ) بیٹھا ہوا تھا کہ اس کا اونٹ چلتا ہوا ( واپس ) آ گیا اور اپنی مہار ( نکیل سے بندھی ہوئی رسی ) اس آدمی کے ہاتھ پر گرا دی ۔ ( اسے اٹھ کر مہار پکڑنے کی زحمت بھی نہ کرنی پڑی ) تو اللہ اپنے بندے کی توبہ پر اس شخص کی نسبت زیادہ خوش ہوتا ہے جب یہ آدمی اپنی سواری کو اس کی اصل حالت میں ( زادراہ اور پانی سمیت صحیح سالم ) پا لیتا ہے ۔ \"\" سماک نے کہا : تو شعبی نے سمجھا کہ سیدنا نعمان ( بن بشیر رضی اللہ عنہ ) نے یہ بات مرفوع ( رسول اللہ صلی اللہ علیہ وسلم سے ) بیان کی ہے ، لیکن میں نے ان کو ( مرفوع بیان کرتے ) نہیں سنا ۔","",{"u2":") ابو یونس نے سماک سے روایت کی، کہا: حضرت نعمان بن بشیر رضی اللہ عنہ نے خطبہ دیا اور (آپ صلی اللہ علیہ وسلم کا فرمان) بیان کیا: \"اللہ تعالیٰ کو اپنے بندے کی توبہ پر اس شخص کی نسبت زیادہ خوشی ہوتی ہے جس نے اپنا زادراہ اور اپنی پانی کی بڑی مشک کو اونٹ پر لادا، پھر (سفر پر) چل پڑا، یہاں تک کہ جب وہ ایک چٹیل زمین پر تھا تو اسے دوپہر کی نیند نے بے بس کر دیا، وہ اترا اور ایک درخت کے نیچے دوپہر کے آرام کے لیے لیٹ گیا، اس کی آنکھ لگ گئی اور اس کا اونٹ کسی طرف کو نکل گیا، پھر وہ جاگا تو کوشش کر کے ایک ٹیلے پر چڑھا (ہر طرف دیکھا) لیکن اسے کچھ نظر نہ آیا، پھر وہ مشقت اٹھا کر دوسرے ٹیلے پر چڑھا، اسے کچھ نظر نہ آیا، پھر (مزید) مشقت سے تیسرے ٹیلے پر چڑھا تو اسے کچھ نظر نہ آیا، پھر وہ آیا، اسی جگہ پہنچا جہاں دوپہر کا آرام کیا تھا، وہ (اس جگہ) بیٹھا ہوا تھا کہ اس کا اونٹ چلتا ہوا (واپس) آ گیا اور اپنی مہار (نکیل سے بندھی ہوئی رسی) اس آدمی کے ہاتھ پر گرا دی۔ (اسے اٹھ کر مہار پکڑنے کی زحمت بھی نہ کرنی پڑی) تو اللہ اپنے بندے کی توبہ پر اس شخص کی نسبت زیادہ خوش ہوتا ہے جب یہ آدمی اپنی سواری کو اس کی اصل حالت میں (زادراہ اور پانی سمیت صحیح سالم) پا لیتا ہے۔\"\nسماک نے کہا: تو شعبی نے سمجھا کہ حضرت نعمان (بن بشیر رضی اللہ عنہ) نے یہ بات مرفوع (رسول اللہ صلی اللہ علیہ وسلم سے) بیان کی ہے، لیکن میں نے ان کو (مرفوع بیان کرتے) نہیں سنا۔"}],[7015,"یحیی بن یحیی اور جعفر بن حمید نے ہمیں عبیداللہ بن ایاد بن لقیط سے ، انہوں نے ایاد سے حدیث بیان کی ، انہوں نے سیدنا براء بن عازب رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" تم اس شخص کی خوشی کے متعلق کیا کہتے ہو جس کی اونٹنی ایسی بے آب و گیاہ زمین میں ، جہاں کھانے کی کوئی چیز ہو نہ پینے کی ، اپنی نکیل کی رسی کھینچتی ہوئی ( کسی طرف ) نکل گئی ۔ اس کا کھانا اور پانی بھی اسی پر تھا ۔ اس شخص نے اسے ( بہت ) ڈھونڈا حتی کہ تھک کر ہار گیا ، پھر وہ ( اونٹنی چلتے چلتے ) ایک درخت کے ٹنڈ منڈ تنے کے پاس سے گزری تو اس کی نکیل کی رسی اس کے ساتھ اٹک گئی اور اس شخص نے اس ( اونٹنی ) کو اس ( تنے ) کے ساتھ لگی کھڑی پا لیا؟ \"\" ہم نے عرض کی : اللہ کے رسول! ( اس شخص کی خوشی ) بے پناہ ہو گی ۔ اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" اللہ تعالی اپنے بندے کی توبہ پر اس سے کہیں زیادہ خوش ہوتا ہے جتنا یہ شخص اپنی سواری کو پا کر ہوتا ہے ۔ \"\" جعفر نے کہا : ہمیں عبیداللہ بن یاد نے اپنے والد سے حدیث بیان کی ۔","",{"u2":"یحییٰ بن یحییٰ اور جعفر بن حمید نے ہمیں عبیداللہ بن ایاد بن لقیط سے، انہوں نے ایاد سے حدیث بیان کی، انہوں نے حضرت براء بن عازب رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم اس شخص کی خوشی کے متعلق کیا کہتے ہو جس کی اونٹنی ایسی بے آب و گیاہ زمین میں، جہاں کھانے کی کوئی چیز ہو نہ پینے کی، اپنی نکیل کی رسی کھینچتی ہوئی (کسی طرف) نکل گئی۔ اس کا کھانا اور پانی بھی اسی پر تھا۔ اس شخص نے اسے (بہت) ڈھونڈا حتی کہ تھک کر ہار گیا، پھر وہ (اونٹنی چلتے چلتے) ایک درخت کے ٹنڈ منڈ تنے کے پاس سے گزری تو اس کی نکیل کی رسی اس کے ساتھ اٹک گئی اور اس شخص نے اس (اونٹنی) کو اس (تنے) کے ساتھ لگی کھڑی پا لیا؟\" ہم نے عرض کی: اللہ کے رسول! (اس شخص کی خوشی) بے پناہ ہو گی۔ اس پر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ اپنے بندے کی توبہ پر اس سے کہیں زیادہ خوش ہوتا ہے جتنا یہ شخص اپنی سواری کو پا کر ہوتا ہے۔\"\nجعفر نے کہا: ہمیں عبیداللہ بن یاد نے اپنے والد سے حدیث بیان کی۔"}],[7016,"اسحاق بن عبداللہ بن ابی طلحہ نے کہا : ہمیں سیدنا انس بن مالک رضی اللہ عنہ نے حدیث بیان کی اور وہ ( سیدنا انس رضی اللہ عنہ ) ان کے چچا ہیں ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ تعالی اپنے بندے کی توبہ پر ، جب وہ ( بندہ ) اس کی طرف توبہ کرتا ہے ، تم میں سے کسی ایسے شخص کی نسبت کہیں زیادہ خوش ہوتا ہے جو ایک بے آب و گیاہ صحرا میں اپنی سواری پر ( سفر کر رہا ) تھا تو وہ اس کے ہاتھ سے نکل ( کر گم ہو ) گئی ، اس کا کھانا اور پانی اسی ( سواری ) پر ہے ۔ وہ اس ( کے ملنے ) سے مایوس ہو گیا تو ایک درخت کے پاس آیا اور اس کے سائے میں لیٹ گیا ۔ وہ اپنی سواری ( ملنے ) سے ناامید ہو چکا تھا ۔ وہ اسی عالم میں ہے کہ اچانک وہ ( آدمی ) اس کے پاس ہے ، وہ ( اونٹنی ) اس کے پاس کھڑی ہے ، اس نے اس کو نکیل کی رسی سے پکڑ لیا ، پھر بے پناہ خوشی کی شدت میں کہہ بیٹھا ، اے اللہ! تو میرا بندہ ہے اور میں تیرا رب ہوں ۔ خوشی کی شدت کی وجہ سے غلطی کر گیا ۔","",{"u2":") اسحاق بن عبداللہ بن ابی طلحہ نے کہا: ہمیں حضرت انس بن مالک رضی اللہ عنہ نے حدیث بیان کی اور وہ (حضرت انس رضی اللہ عنہ) ان کے چچا ہیں، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ اپنے بندے کی توبہ پر، جب وہ (بندہ) اس کی طرف توبہ کرتا ہے، تم میں سے کسی ایسے شخص کی نسبت کہیں زیادہ خوش ہوتا ہے جو ایک بے آب و گیاہ صحرا میں اپنی سواری پر (سفر کر رہا) تھا تو وہ اس کے ہاتھ سے نکل (کر گم ہو) گئی، اس کا کھانا اور پانی اسی (سواری) پر ہے۔ وہ اس (کے ملنے) سے مایوس ہو گیا تو ایک درخت کے پاس آیا اور اس کے سائے میں لیٹ گیا۔ وہ اپنی سواری (ملنے) سے ناامید ہو چکا تھا۔ وہ اسی عالم میں ہے کہ اچانک وہ (آدمی) اس کے پاس ہے، وہ (اونٹنی) اس کے پاس کھڑی ہے، اس نے اس کو نکیل کی رسی سے پکڑ لیا، پھر بے پناہ خوشی کی شدت میں کہہ بیٹھا، اے اللہ! تو میرا بندہ ہے اور میں تیرا رب ہوں۔ خوشی کی شدت کی وجہ سے غلطی کر گیا۔\""}],[7017,"ہداب بن خالد نے کہا : ہمیں ہمام نے حدیث بیان کی ، انہوں نے کہا : ہمیں قتادہ نے سیدنا انس بن مالک رضی اللہ عنہ سے حدیث سنائی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ تعالی کو اپنے بندے کی توبہ سے ، تم میں سے کسی ایسے شخص کی نسبت ہمیں زیادہ خوشی ہوتی ہے جب کٹیل صحرا میں اس کے ( اس ) اونٹ ( کے آں ے ) پر اس کی آنکھ کھلتی ہے جسے وہ صحرا میں گم کر چکا ہوتا ہے ۔","",{"u2":"ہداب بن خالد نے کہا: ہمیں ہمام نے حدیث بیان کی، انہوں نے کہا: ہمیں قتادہ نے حضرت انس بن مالک رضی اللہ عنہ سے حدیث سنائی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ کو اپنے بندے کی توبہ سے، تم میں سے کسی ایسے شخص کی نسبت ہمیں زیادہ خوشی ہوتی ہے جب کٹیل صحرا میں اس کے (اس) اونٹ (کے آں ے) پر اس کی آنکھ کھلتی ہے جسے وہ صحرا میں گم کر چکا ہوتا ہے۔\""}],[7018,"ہداب بن خالد نے کہا : ہمیں ہمام نے حدیث بیان کی ، انہوں نے کہا : ہمیں قتادہ نے سیدنا انس بن مالک رضی اللہ عنہ سے حدیث سنائی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ تعالی کو اپنے بندے کی توبہ سے ، تم میں سے کسی ایسے شخص کی نسبت ہمیں زیادہ خوشی ہوتی ہے جب کٹیل صحرا میں اس کے ( اس ) اونٹ ( کے آں ے ) پر اس کی آنکھ کھلتی ہے جسے وہ صحرا میں گم کر چکا ہوتا ہے ۔","",{"u2":"حبان نے کہا: ہمیں ہمام نے حدیث بیان کی۔کہا: ہمیں قتادہ نے حدیث سنائی، کہا: ہمیں حضرت انس بن مالک رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند حدیث بیان کی۔"}],[7019,"عمر بن عبدالعزیز کے قصہ گو محمد بن قیس نے ابوصرمہ سے ، انہوں نے سیدنا ابو ایوب انصاری رضی اللہ عنہ سے روایت کی کہ جب ان کی وفات کا وقت آیا تو انہوں نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنی ہوئی ایک حدیث تم سے چھپا رکھی تھی ، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا تھا : \" اگر تم ( لوگ ) گناہ نہ کرو تو ( تمہاری جگہ ) اللہ تعالی ایسی مخلوق کو پیدا فرما دے جو گناہ کریں ( پھر اللہ سے توبہ کریں اور ) وہ ان کی مغفرت فرما دے ۔","",{"u2":") عمر بن عبدالعزیز کے قصہ گو محمد بن قیس نے ابوصرمہ سے، انہوں نے حضرت ابو ایوب انصاری رضی اللہ عنہ سے روایت کی کہ جب ان کی وفات کا وقت آیا تو انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنی ہوئی ایک حدیث تم سے چھپا رکھی تھی، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا تھا: \"اگر تم (لوگ) گناہ نہ کرو تو (تمہاری جگہ) اللہ تعالیٰ ایسی مخلوق کو پیدا فرما دے جو گناہ کریں (پھر اللہ سے توبہ کریں اور) وہ ان کی مغفرت فرما دے۔\""}],[7020,"محمد بن کعب قرظی نے ابوصرمہ سے ، انہوں نے سیدنا ابوایوب انصاری رضی اللہ عنہ سے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" اگر تم ایسے ہوتے کہ تمہارے ( نامہ اعمال میں کچھ بھی ) گناہ نہ ہوتے جن کی اللہ تعالی تمہارے لیے بخشش فرماتا تو وہ ایسی قوم کو ( اس دنیا میں ) لے آتا جن کے گناہ ہوتے اور وہ ان کے لیے ان ( گناہوں ) کی مغفرت فرماتا ۔","",{"u2":"محمد بن کعب قرظی نے ابوصرمہ سے، انہوں نے حضرت ابوایوب انصاری رضی اللہ عنہ سے اور انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر تم ایسے ہوتے کہ تمہارے (نامہ اعمال میں کچھ بھی) گناہ نہ ہوتے جن کی اللہ تعالیٰ تمہارے لیے بخشش فرماتا تو وہ ایسی قوم کو (اس دنیا میں) لے آتا جن کے گناہ ہوتے اور وہ ان کے لیے ان (گناہوں) کی مغفرت فرماتا۔\""}],[7021,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! اگر تم ( لوگ ) گناہ نہ کرو تو اللہ تعالی تم کو ( اس دنیا سے ) لے جائے اور ( تمہارے بدلے میں ) ایسی قوم کو لے آئے جو گناہ کریں اور اللہ تعالی سے مغفرت مانگیں تو وہ ان کی مغفرت فرمائے ۔"],[7022,"جعفر بن سلیمان نے سعید بن ایاس جریری سے ، انہوں نے ابوعثمان نہدی سے اور انہوں نے سیدنا حنظلہ ( بن ربیع ) اُسیدی رضی اللہ عنہ سے روایت کی ، انہوں نے کہا ۔ ۔ اور وہ رسول اللہ صلی اللہ علیہ وسلم کے کاتبوں میں سے تھے ۔ ۔ کہا : سیدنا ابوبکر رضی اللہ عنہ مجھ سے ملے اور دریافت کیا : حنظلہ! آپ کیسے ہیں؟ میں نے کہا : حنظلہ منافق ہو گیا ہے ، ( سیدنا ابوبکر رضی اللہ عنہ نے ) کہا : سبحان اللہ! تم کیا کہہ رہے ہو؟ میں نے کہا : ہم رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوتے ہیں ، آپ ہمیں جنت اور دوزخ کی یاد دلاتے ہیں حتی کہ ایسے لگتے ہیں گویا ہم ( انہیں ) آنکھوں سے دیکھ رہے ہیں ، پھر جب ہم رسول اللہ صلی اللہ علیہ وسلم کے ہاں سے نکلتے ہیں تو بیویوں ، بچوں اور کھیتی باڑی ( اور دوسرے کام کاج ) کو سنبھالنے میں لگ جاتے ہیں اور بہت سی چیزیں بھول بھلا جاتے ہیں ۔ سیدنا ابوبکر رضی اللہ عنہ نے کہا : اللہ کی قسم! یہی کچھ ہمیں بھی پیش آتا ہے ، پھر میں اور سیدنا ابوبکر رضی اللہ عنہ چل پڑے اور رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے ۔ میں نے عرض کی : اللہ کے رسول! حنظلہ منافق ہو گیا ہے ، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" وہ کیا معاملہ ہے؟ \" میں نے عرض کی : اللہ کے رسول! ہم آپ کے پاس حاضر ہوتے ہیں ، آپ ہمیں جنت اور دوزخ کی یاد دلاتے ہیں ، تو حالت یہ ہوتی ہے گویا ہم ( جنت اور دوزخ کو ) اپنی آنکھوں سے دیکھ رہے ہیں اور جب ہم آپ کے ہاں سے باہر نکلتے ہیں تو بیویوں ، بچوں اور کام کاج کی دیکھ بھال میں لگ جاتے ہیں ۔ ۔ ہم بہت کچھ بھول جاتے ہیں ۔ ۔ اس پر رسول اللہ صلی اللہ علیہ وسلم نے تین بار ارشاد فرمایا : \" اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! اگر تم ہمیشہ اسی کیفیت میں رہو جس طرح میرے پاس ہوتے اور ذکر میں لگے رہو تو تمہارے بچھونوں پر اور تمہارے راستوں میں فرشتے ( آ کر ) تمہارے ساتھ مصافحے کریں ، لیکن اے حنظلہ! کوئی گھڑی کسی طرح ہوتی ہے اور کوئی گھڑی کسی ( اور ) طرح ۔","",{"u2":"جعفر بن سلیمان نے سعید بن ایاس جریری سے، انہوں نے ابوعثمان نہدی سے اور انہوں نے حضرت حنظلہ (بن ربیع) اُسیدی رضی اللہ عنہ سے روایت کی، انہوں نے کہا۔۔ اور وہ رسول اللہ صلی اللہ علیہ وسلم کے کاتبوں میں سے تھے۔۔ کہا: حضرت ابوبکر رضی اللہ عنہ مجھ سے ملے اور دریافت کیا: حنظلہ! آپ کیسے ہیں؟ میں نے کہا: حنظلہ منافق ہو گیا ہے، (حضرت ابوبکر رضی اللہ عنہ نے) کہا: سبحان اللہ! تم کیا کہہ رہے ہو؟ میں نے کہا: ہم رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوتے ہیں، آپ ہمیں جنت اور دوزخ کی یاد دلاتے ہیں حتی کہ ایسے لگتے ہیں گویا ہم (انہیں) آنکھوں سے دیکھ رہے ہیں، پھر جب ہم رسول اللہ صلی اللہ علیہ وسلم کے ہاں سے نکلتے ہیں تو بیویوں، بچوں اور کھیتی باڑی (اور دوسرے کام کاج) کو سنبھالنے میں لگ جاتے ہیں اور بہت سی چیزیں بھول بھلا جاتے ہیں۔ حضرت ابوبکر رضی اللہ عنہ نے کہا: اللہ کی قسم! یہی کچھ ہمیں بھی پیش آتا ہے، پھر میں اور حضرت ابوبکر رضی اللہ عنہ چل پڑے اور رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے۔ میں نے عرض کی: اللہ کے رسول! حنظلہ منافق ہو گیا ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"وہ کیا معاملہ ہے؟\" میں نے عرض کی: اللہ کے رسول! ہم آپ کے پاس حاضر ہوتے ہیں، آپ ہمیں جنت اور دوزخ کی یاد دلاتے ہیں، تو حالت یہ ہوتی ہے گویا ہم (جنت اور دوزخ کو) اپنی آنکھوں سے دیکھ رہے ہیں اور جب ہم آپ کے ہاں سے باہر نکلتے ہیں تو بیویوں، بچوں اور کام کاج کی دیکھ بھال میں لگ جاتے ہیں۔۔ ہم بہت کچھ بھول جاتے ہیں۔۔ اس پر رسول اللہ صلی اللہ علیہ وسلم نے تین بار ارشاد فرمایا: \"اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! اگر تم ہمیشہ اسی کیفیت میں رہو جس طرح میرے پاس ہوتے اور ذکر میں لگے رہو تو تمہارے بچھونوں پر اور تمہارے راستوں میں فرشتے (آ کر) تمہارے ساتھ مصافحے کریں،لیکن اے حنظلہ! کوئی گھڑی کسی طرح ہوتی ہے اور کوئی گھڑی کسی (اور) طرح۔\""}],[7023,"عبدالصمد کے والد ( عبدالوارث بن سعید ) نے کہا : ہمیں سعید جریری نے ابوعثمان نہدی سے حدیث بیان کی ، انہوں نے سیدنا حنظلہ رضی اللہ عنہ سے روایت کی ، کہا : ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس تھے تو آپ نے ہمیں وعظ فرمایا اور دوزخ کی یاد دلائی ۔ کہا : پھر میں گھر آیا تو بچوں کے ساتھ ہنسی مذاق کیا اور بیوی سے خوش طبعی کی ، پھر میں باہر نکلا تو سیدنا ابوبکر رضی اللہ عنہ سے ملاقات ہوئی ، ، میں نے یہی بات ان کو بتائی ۔ انہوں نے کہا : میں نے بھی یہی کیا ہے جس طرح تم نے ذکر کیا ہے ، پھر ہم دونوں رسول اللہ صلی اللہ علیہ وسلم سے ملے ، میں نے عرض کی : اللہ کے رسول! حنظلہ منافق ہو گیا ہے ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \" یہ کیا بات ہے؟ \" تو میں نے پوری بات آپ سے عرض کر دی ، پھر سیدنا ابوبکر رضی اللہ عنہ نے کہا : جس طرح انہوں نے کیا ہے ، میں بھی بالکل یہی کیا ہے ( گھر جا کر بیوی بچوں کے ساتھ مشغول ہو گیا ۔ ) آپ صلی اللہ علیہ وسلم نے فرمایا : \" حنظلہ ( یہ ) گھڑی گھڑی کا معاملہ ہے ( ایک گھڑی کسی طرح ہوتی ہے اور دوسری کسی اور طرح ۔ ) اگر تمہارے دل ہر وقت اسی طرح رہیں جیسے تذکیر و تلقین کے وقت ہوتے ہیں تو تمہارے ساتھ فرشتے مصافحے کریں حتی کہ راستوں میں تم کو سلام کہیں ۔","",{"u2":"عبدالصمد کے والد (عبدالوارث بن سعید) نے کہا: ہمیں سعید جریری نے ابوعثمان نہدی سے حدیث بیان کی، انہوں نے حضرت حنظلہ رضی اللہ عنہ سے روایت کی، کہا: ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس تھے تو آپ نے ہمیں وعظ فرمایا اور دوزخ کی یاد دلائی۔ کہا: پھر میں گھر آیا تو بچوں کے ساتھ ہنسی مذاق کیا اور بیوی سے خوش طبعی کی، پھر میں باہر نکلا تو حضرت ابوبکر رضی اللہ عنہ سے ملاقات ہوئی،، میں نے یہی بات ان کو بتائی۔ انہوں نے کہا: میں نے بھی یہی کیا ہے جس طرح تم نے ذکر کیا ہے، پھر ہم دونوں رسول اللہ صلی اللہ علیہ وسلم سے ملے، میں نے عرض کی: اللہ کے رسول! حنظلہ منافق ہو گیا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ کیا بات ہے؟\" تو میں نے پوری بات آپ سے عرض کر دی، پھر حضرت ابوبکر رضی اللہ عنہ نے کہا: جس طرح انہوں نے کیا ہے، میں بھی بالکل یہی کیا ہے (گھر جا کر بیوی بچوں کے ساتھ مشغول ہو گیا۔) آپ صلی اللہ علیہ وسلم نے فرمایا: \"حنظلہ (یہ) گھڑی گھڑی کا معاملہ ہے (ایک گھڑی کسی طرح ہوتی ہے اور دوسری کسی اور طرح۔) اگر تمہارے دل ہر وقت اسی طرح رہیں جیسے تذکیر و تلقین کے وقت ہوتے ہیں تو تمہارے ساتھ فرشتے مصافحے کریں حتی کہ راستوں میں تم کو سلام کہیں۔\""}],[7024,"سفیان نے سعید جریری سے ، انہوں نے ابوعثمان نہدی سے اور انہوں نے سیدنا حنظلہ تمیمی اُسیدی کاتب ( رسول اللہ صلی اللہ علیہ وسلم ) سے روایت کی ، کہا : ہم رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوتے تھے اور آپ ہمیں جنت اور دوزخ کی یاد دلاتے ۔ ۔ ۔ پھر ان دونوں ( جعفر بن سلیمان اور عبدالوارث بن سعید ) کی حدیث کی طرح بیان کیا ۔","",{"u2":"سفیان نے سعید جریری سے، انہوں نے ابوعثمان نہدی سے اور انہوں نے حضرت حنظلہ تمیمی اُسیدی کاتب (رسول اللہ صلی اللہ علیہ وسلم) سے روایت کی، کہا: ہم رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوتے تھے اور آپ ہمیں جنت اور دوزخ کی یاد دلاتے۔۔۔ پھر ان دونوں (جعفر بن سلیمان اور عبدالوارث بن سعید) کی حدیث کی طرح بیان کیا۔"}],[7025,"مغیرہ حزامی نے ابوزناد سے ، انہوں نے اعرج سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے فرمایا : اللہ تعالی نے جب مخلوق کو پیدا فرمایا تو اپنی کتاب میں لکھ دیا اور وہ ( کتاب ) عرش کے اوپر اس کے پاس ہے : یقینا میری رحمت میرے غضب پر غالب ہو گی ۔","",{"u2":"مغیرہ حزامی نے ابوزناد سے، انہوں نے اعرج سے اور انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے فرمایا: اللہ تعالیٰ نے جب مخلوق کو پیدا فرمایا تو اپنی کتاب میں لکھ دیا اور وہ (کتاب) عرش کے اوپر اس کے پاس ہے: یقینا میری رحمت میرے غضب پر غالب ہو گی۔\""}],[7026,"سفیان بن عیینہ نے ابوزناد سے ، انہوں نے اعرج سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ عزوجل نے فرمایا : میری رحمت میرے غضب پر سبقت لے گئی ہے ۔","",{"u2":"سفیان بن عیینہ نے ابوزناد سے، انہوں نے اعرج سے، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ عزوجل نے فرمایا: میری رحمت میرے غضب پر سبقت لے گئی ہے۔\""}],[7027,"عطاء بن مینا نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ تعالی نے جب مخلوق کے بارے میں فیصلہ فرما لیا تو اس نے اپنی کتاب میں اپنے اوپر لازم کرتے ہوئے لکھ دیا ، وہ اس کے پاس رکھی ہوئی ہے : یقینا میری رحمت میرے غضب پر غالب رہے گی ۔","",{"u2":"عطاء بن مینا نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ نے جب مخلوق کے بارے میں فیصلہ فرما لیا تو اس نے اپنی کتاب میں اپنے اوپر لازم کرتے ہوئے لکھ دیا، وہ اس کے پاس رکھی ہوئی ہے: یقینا میری رحمت میرے غضب پر غالب رہے گی۔\""}],[7028,"سعید بن مسیب نے بتایا کہ سیدنا ابوہریرہ رضی اللہ عنہ نے کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا : \" اللہ تعالی نے رحمت کے ایک سو حصے کیے ، ننانوے حصے اپنے پاس روک کر رکھ لیے اور ایک حصہ زمین پر اتارا ، اسی ایک حصے میں سے مخلوق ایک دوسرے پر رحم کرتی ہے حتی کہ ایک چوپایہ اس ڈر سے اپنا سم اپنے بچے اوپر اٹھا لیتا ہے کہ کہیں اس کو لگ نہ جائے ۔","",{"u2":"سعید بن مسیب نے بتایا کہ حضرت ابوہریرہ رضی اللہ عنہ نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"اللہ تعالیٰ نے رحمت کے ایک سو حصے کیے، ننانوے حصے اپنے پاس روک کر رکھ لیے اور ایک حصہ زمین پر اتارا، اسی ایک حصے میں سے مخلوق ایک دوسرے پر رحم کرتی ہے حتی کہ ایک چوپایہ اس ڈر سے اپنا سم اپنے بچے اوپر اٹھا لیتا ہے کہ کہیں اس کو لگ نہ جائے۔\""}],[7029,"علاء کے والد ( عبدالرحمٰن ) نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے فرمایا : \" اللہ تعالی نے سو رحمتیں پیدا کیں ، اس نے ایک رحمت اپنی مخلوق میں رکھی اور ایک کم سو رحمتیں ( آئندہ کے لیے ) اپنے پاس چھپا کر رکھ لیں ۔","",{"u2":"علاء کے والد (عبدالرحمٰن) نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ نے سو رحمتیں پیدا کیں، اس نے ایک رحمت اپنی مخلوق میں رکھی اور ایک کم سو رحمتیں (آئندہ کے لیے) اپنے پاس چھپا کر رکھ لیں۔\""}],[7030,"عطاء نے سیدنا ابوہریرہ رضی اللہ عنہ سے ، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ تعالی کی سو رحمتیں ہیں ، ان میں سے ایک رحمت اس نے جن و انس ، حیوانات اور حشرات الارض کے درمیان نازل فرما دی ، اسی ( ایک حصے کے ذریعے ) سے وہ ایک دوسرے پر شفقت کرتے ہیں ، آپس میں رحمت کا برتاؤ کرتے ہیں ، اسی سے وحشی جانور اپنے بچوں پر شفقت کرتے ہیں اور اللہ تعالی نے ننانوے رحمتیں مؤخر کر کے رکھ لی ہیں ، ان سے قیامت کے دن اپنے بندوں پر رحم فرمائے گا ۔","",{"u2":"عطاء نے حضرت ابوہریرہ رضی اللہ عنہ سے، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ کی سو رحمتیں ہیں، ان میں سے ایک رحمت اس نے جن و انس، حیوانات اور حشرات الارض کے درمیان نازل فرما دی، اسی (ایک حصے کے ذریعے) سے وہ ایک دوسرے پر شفقت کرتے ہیں، آپس میں رحمت کا برتاؤ کرتے ہیں، اسی سے وحشی جانور اپنے بچوں پر شفقت کرتے ہیں اور اللہ تعالیٰ نے ننانوے رحمتیں مؤخر کر کے رکھ لی ہیں، ان سے قیامت کے دن اپنے بندوں پر رحم فرمائے گا۔\""}],[7031,"معاذ نے کہا : ہمیں سلیمان تیمی نے حدیث بیان کی ، انہوں نے کہا : ہمیں ابوعثمان نہدی نے سیدنا سلمان فارسی رضی اللہ عنہ سے حدیث سنائی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ تعالی کی سو رحمتیں ہیں ، ان میں سے ایک رحمت ہے جس کے ذریعے سے مخلوق آپس میں ایک دوسرے پر رحم کرتی ہے اور ننانوے ( رحمتیں ) قیامت کے دن کے لیے ( محفوظ ) ہیں ۔","",{"u2":"معاذ نے کہا: ہمیں سلیمان تیمی نے حدیث بیان کی، انہوں نے کہا: ہمیں ابوعثمان نہدی نے حضرت سلمان فارسی رضی اللہ عنہ سے حدیث سنائی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ کی سو رحمتیں ہیں، ان میں سے ایک رحمت ہے جس کے ذریعے سے مخلوق آپس میں ایک دوسرے پر رحم کرتی ہے اور ننانوے (رحمتیں) قیامت کے دن کے لیے (محفوظ) ہیں۔\""}],[7032,"معتمر نے اپنے والد ( سلیمان تیمی ) سے اسی سند کے ساتھ ( یہی ) حدیث بیان کی ۔","",{"u2":"معتمر نے اپنے والد (سلیمان تیمی) سے اسی سند کے ساتھ (یہی) حدیث بیان کی۔"}],[7033,"داود بن ابی ہند نے ابو عثمان سے اور انہوں نے سیدنا سلمان رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" بےشک اللہ تعالی نے جس دن آسمانوں اور زمین کو پیدا کیا اس دن اس نے سو رحمتیں پیدا کیں ، ہر رحمت آسمانوں اور زمین کےدرمیان کی وسعت کے برابر ہے ، اس نے ان میں سے ایک رحمت زمین میں رکھی ، اسی رحمت کی وجہ سے والدہ اپنی اولاد پر رحمت کرتی ہے اور وحشی جانور اور پرندے آپس میں ایک دوسرے کے ساتھ رحمت کا سلوک کرتے ہیں ، جب قیامت کا دن ہو گا تو اللہ تعالی اپنی رحمتوں کو اس رحمت کے ساتھ ملا کر پوری ( سو ) کرے گا ( اور بندوں کے ساتھ سو فیصد رحمت کا سلوک فرمائے گا ۔)","",{"u2":"داود بن ابی ہند نے ابو عثمان سے اور انہوں نے حضرت سلمان رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بےشک اللہ تعالیٰ نے جس دن آسمانوں اور زمین کو پیدا کیا اس دن اس نے سو رحمتیں پیدا کیں، ہر رحمت آسمانوں اور زمین کےدرمیان کی وسعت کے برابر ہے، اس نے ان میں سے ایک رحمت زمین میں رکھی، اسی رحمت کی وجہ سے والدہ اپنی اولاد پر رحمت کرتی ہے اور وحشی جانور اور پرندے آپس میں ایک دوسرے کے ساتھ رحمت کا سلوک کرتے ہیں، جب قیامت کا دن ہو گا تو اللہ تعالیٰ اپنی رحمتوں کو اس رحمت کے ساتھ ملا کر پوری (سو) کرے گا (اور بندوں کے ساتھ سو فیصد رحمت کا سلوک فرمائے گا۔)\""}],[7034,"سیدنا عمر بن خطاب رضی اللہ عنہ سے روایت ہے ، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس کچھ قیدی آئے ، ان قیدیوں میں سے ایک عورت کسی کو تلاش کر رہی تھی ، اچانک قیدیوں میں سے اس ایک کو بچہ مل گیا ، اس نے بچے کو اٹھا کر پیٹ سے چمتا لیا اور اس کو دودھ پلانے لگی ، تب رسول اللہ صلی اللہ علیہ وسلم نے ہم سے فرمایا : \" کیا تم سمجھتے ہو کہ یہ عورت اپنے بچے کو آگ میں ڈال دے گی؟ \" ہم نے کہا : اللہ کی قسم! اگر اس کے بس میں ہو کہ اسے نہ پھینکے ( تو ہرگز نہیں پھینکے گی ۔ ) تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ تعالی اپنے بندوں پر اس سے بھی زیادہ رحم کرنے والا ہے جتنا اس عورت کو اپنے بچے کے ساتھ ہے ۔","",{"u2":"حضرت عمر بن خطاب رضی اللہ عنہ سے روایت ہے، انہوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس کچھ قیدی آئے، ان قیدیوں میں سے ایک عورت کسی کو تلاش کر رہی تھی، اچانک قیدیوں میں سے اس ایک کو بچہ مل گیا، اس نے بچے کو اٹھا کر پیٹ سے چمتا لیا اور اس کو دودھ پلانے لگی، تب رسول اللہ صلی اللہ علیہ وسلم نے ہم سے فرمایا: \"کیا تم سمجھتے ہو کہ یہ عورت اپنے بچے کو آگ میں ڈال دے گی؟\" ہم نے کہا: اللہ کی قسم! اگر اس کے بس میں ہو کہ اسے نہ پھینکے (تو ہرگز نہیں پھینکے گی۔) تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ اپنے بندوں پر اس سے بھی زیادہ رحم کرنے والا ہے جتنا اس عورت کو اپنے بچے کے ساتھ ہے۔\""}],[7035,"سیدنا ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اگر مومن کو یہ علم ہو جائے کہ اللہ تعالی کے پاس سزا کیا ہے تو کوئی شخص اس کی جنت کی امید ہی نہ رکھے ، اور اگر کافر کو یہ پتہ چل جائے کہ اللہ کے پاس رحمت کس قدر ہے تو کوئی ایک بھی اس کی جنت سے مایوس نہ ہو ۔","",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اگر مومن کو یہ علم ہو جائے کہ اللہ تعالیٰ کے پاس سزا کیا ہے تو کوئی شخص اس کی جنت کی امید ہی نہ رکھے، اور اگر کافر کو یہ پتہ چل جائے کہ اللہ کے پاس رحمت کس قدر ہے تو کوئی ایک بھی اس کی جنت سے مایوس نہ ہو۔\""}],[7036,"اعرج نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ایک آڈمی جس نے کبھی کوئی نیکی نہیں کی تھی ، اپنے گھر والوں سے کہا : جب وہ مرے تو اسے جلا دیں ، پھر اس کا آدھا حصہ ( ۃواؤں میں اڑا کر ) خشکی پر بکھیر دیں اور آدھا حصہ سمندر میں بہا دیں ، کیونکہ اللہ کی قسم! اللہ تعالی نے اسے قابو کر لیا تو اس کو ضرور بالضرور ایسا عذاب دے گا جو تمام جہانوں میں سے کسی کو نہیں دے گا ، چنانچہ جب وہ آدمی مر گیا تو انہوں نے وہی کیا جس کا اس نے حکم دیا تھا ۔ اللہ تعالی نے خشکی کو حکم دیا ، اس شخص کا جو بھی حسہ اس ( خشکی ) میں تھا اس نے اس کو اکٹھا کر دیا اور سمندر کو حکم تو جو کچھ اس میں تھا اس نے اکٹھا کر دیا ، پھر ( اللہ نے ) اس سے پوچھا : تم نے ایسا کیوں کیا تھا؟ اس نے کہا : میرے رب! تیرے ڈر سے ( ایسا کیا تھا ) اور تو سب سے زیادہ جاننے والا ہے ( کہ میری بات سچ ہے ) تو اللہ نے ( اس سچی خشیت کی بنا پر ) اسے بخش دیا ۔","",{"u2":"اعرج نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ایک آڈمی جس نے کبھی کوئی نیکی نہیں کی تھی، اپنے گھر والوں سے کہا: جب وہ مرے تو اسے جلا دیں، پھر اس کا آدھا حصہ (ۃواؤں میں اڑا کر) خشکی پر بکھیر دیں اور آدھا حصہ سمندر میں بہا دیں، کیونکہ اللہ کی قسم! اللہ تعالیٰ نے اسے قابو کر لیا تو اس کو ضرور بالضرور ایسا عذاب دے گا جو تمام جہانوں میں سے کسی کو نہیں دے گا، چنانچہ جب وہ آدمی مر گیا تو انہوں نے وہی کیا جس کا اس نے حکم دیا تھا۔ اللہ تعالیٰ نے خشکی کو حکم دیا، اس شخص کا جو بھی حسہ اس (خشکی) میں تھا اس نے اس کو اکٹھا کر دیا اور سمندر کو حکم تو جو کچھ اس میں تھا اس نے اکٹھا کر دیا، پھر (اللہ نے) اس سے پوچھا: تم نے ایسا کیوں کیا تھا؟ اس نے کہا: میرے رب! تیرے ڈر سے (ایسا کیا تھا) اور تو سب سے زیادہ جاننے والا ہے (کہ میری بات سچ ہے) تو اللہ نے (اس سچی خشیت کی بنا پر) اسے بخش دیا۔\""}],[7037,"معمر نے کہا : زہری نے مجھ سے کہا : کیا میں تمہیں دو عجیب حدیثیں نہ سناؤں؟ ( پھر ) زہری نے کہا : مجھے حمید بن عبدالرحمان نے سیدنا ابوہریرہ رضی اللہ عنہ سے خبر دی ، انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" ایک شخص نے اپنے آپ پر ہر قسم کی زیادتی کی ( ہر گناہ کا ارتکاب کر کے خود کو مجرم بنایا ۔ ) تو جب اس کی موت کا وقت آیا تو اس نے اپنے بیٹوں کو وصیت کی اور کہا : جب میں مر جاؤں تو مجھے جلا دینا ، پھر مجھے ریزہ ریزہ کر دینا ، پھر مجھے ہوا میں ، سمندر میں اڑا دینا ۔ اللہ کی قسم! اگر میرے رب نے مجھے قابو کر لیا تو مجھے یقینا ایسا عذاب دے گا جو کسی اور کو نہ دیا ہو گا ۔ \" آپ صلی اللہ علیہ وسلم نے فرمایا : \" انہوں نے اس کے ساتھ یہی کیا ۔ تو اللہ نے زمین سے کہا : جو تو نے لیا پورا واپس کر ، تو وہ ( پورے کا پورا سامنے ) کھڑا تھا ۔ اللہ نے اس سے فرمایا : تو نے جو کیا اس پر تمہیں کس چیز نے اکسایا؟ اس نے کہا : میرے پروردگار! تیری خشیت نے ۔ ۔ یا کہا ۔ ۔ : تیرے خوف نے تو اسی ( بات ) کی بنا پر اس ( اللہ ) نے اسے بخش دیا ۔","",{"u2":"زہری نے کہا: اور حمید نے مجھے حضرت ابوہریرہ رضی اللہ عنہ سے حدیث سنائی، انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ایک عورت بلی کے معاملے میں جہنم میں ڈال دی گئی جسے اس نے باندھ رکھا تھا۔ اس نے نہ اس کو کھلایا، نہ اسے چھوڑا ہی کہ زمین کے چھوٹے چھوٹے جانور کھا لیتی، وہ لاغر ہو کر مر گئی۔\"\nزہری نے کہا؛ یہ اس لیے (فرمایا کیا:) ہے کہ کوئی شخص نہ صرف (رحمت پر) بھروسہ کر لے اور نہ صرف مایوسی ہی کو اپنا لے۔"}],[7038,"زبیدی نے مجھے حدیث سنائی کہ زہری نے کہا : مجھے حُمید بن عبدالرحمان بن عوف نے سیدنا ابوہریرہ رضی اللہ عنہ سے حدیث سنائی ، کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا : \"\" ایک بندے نے اپنے آپ پر ہر طرح کی زیادتی کی ۔ \"\" ( آگے ) معمر کی حدیث کی طرح ہے ، اس قول تک : \"\" پس اللہ نے اسے بخش دیا ۔ \"\" اور انہوں نے بلی کے واقعے ( کے بارے ) میں عورت والی حدیث کا ذکر نہیں کیا ۔ اور زُبیدی کی حدیث میں ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" اللہ عزوجل نے ہر شے سے ، جس نے اس ( جلائے جانے والے شخص ) کی کوئی بھی چیز لی تھی ، فرمایا : اس کا جو حصہ تیرے پاس ہے پورا واپس کر ۔","",{"u2":"زبیدی نے مجھے حدیث سنائی کہ زہری نے کہا: مجھے حُمید بن عبدالرحمان بن عوف نے حضرت ابوہریرہ رضی اللہ عنہ سے حدیث سنائی، کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا: \"ایک بندے نے اپنے آپ پر ہر طرح کی زیادتی کی۔\" (آگے) معمر کی حدیث کی طرح ہے، اس قول تک: \"پس اللہ نے اسے بخش دیا۔\"\nاور انہوں نے بلی کے واقعے (کے بارے) میں عورت والی حدیث کا ذکر نہیں کیا۔\nاور زُبیدی کی حدیث میں ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ عزوجل نے ہر شے سے، جس نے اس (جلائے جانے والے شخص) کی کوئی بھی چیز لی تھی، فرمایا: اس کا جو حصہ تیرے پاس ہے پورا واپس کر۔\""}],[7039,"شعبہ نے ہمیں قتادہ سے حدیث بیان کی ، انہوں نے عقبہ بن عبدالغافر کو کہتے ہوئے سنا کہ میں نے سیدنا ابوسعید خدری رضی اللہ عنہ سے سنا ، وہ نبی اکرم صلی اللہ علیہ وسلم سے حدیث بیان کر رہے تھے : \" تم سے پہلے کے لوگوں میں سے ایک شخص کو اللہ تعالی نے مال اور اولاد سے نوازا تھا ۔ اس نے اپنے بچوں سے کہا : ہر صورت وہی کچھ کرو گے جس کا میں تمہیں حکم دے رہا ہوں ، یا میں اپنا ورثہ دوسروں کے سپرد کر دوں گا ، جب میں مر جاؤں تو مجھے جلا دو ۔ ۔ اور مجھے زیادہ یہ لگتا ہے کہ قتادہ نے کہا ۔ ۔ پھر مجھے کوٹ کر ریزہ ریزہ کر دو ، پھر مجھے ہوا میں اڑا دو کیونکہ میں نے اللہ کے ہاں کوئی اچھائی ذخیرہ نہیں کی ۔ اللہ مجھ پر پوری قدرت رکھتا ہے کہ مجھے عذاب دے ۔ کہا : اس نے ان ( اپنی اولاد ) سے پختہ عہد و پیمان لیا ، تو میرے رب کی قسم! انہوں نے اس کے ساتھ وہی کیا ( جو اس نے کہا تھا ۔ ) اللہ تعالی نے پوچھا : تم نے جو کچھ کیا اس پر تمہیں کس نے اکسایا؟ اس نے کہا : تیرے خوف نے ۔ فرمایا : پھر اسے اس کے سوا ( جو وہ بھگت چکا تھا ، یعنی لاش کا جلنا اور اللہ کے سامنے پیشی وغیرہ ) اور کوئی عذاب نہ ہوا ۔","",{"u2":"شعبہ نے ہمیں قتادہ سے حدیث بیان کی، انہوں نے عقبہ بن عبدالغافر کو کہتے ہوئے سنا کہ میں نے حضرت ابوسعید خدری رضی اللہ عنہ سے سنا، وہ نبی اکرم صلی اللہ علیہ وسلم سے حدیث بیان کر رہے تھے: \"تم سے پہلے کے لوگوں میں سے ایک شخص کو اللہ تعالیٰ نے مال اور اولاد سے نوازا تھا۔ اس نے اپنے بچوں سے کہا: ہر صورت وہی کچھ کرو گے جس کا میں تمہیں حکم دے رہا ہوں، یا میں اپنا ورثہ دوسروں کے سپرد کر دوں گا، جب میں مر جاؤں تو مجھے جلا دو۔۔ اور مجھے زیادہ یہ لگتا ہے کہ قتادہ نے کہا۔۔ پھر مجھے کوٹ کر ریزہ ریزہ کر دو، پھر مجھے ہوا میں اڑا دو کیونکہ میں نے اللہ کے ہاں کوئی اچھائی ذخیرہ نہیں کی۔ اللہ مجھ پر پوری قدرت رکھتا ہے کہ مجھے عذاب دے۔ کہا: اس نے ان (اپنی اولاد) سے پختہ عہد و پیمان لیا، تو میرے رب کی قسم! انہوں نے اس کے ساتھ وہی کیا (جو اس نے کہا تھا۔) اللہ تعالیٰ نے پوچھا: تم نے جو کچھ کیا اس پر تمہیں کس نے اکسایا؟ اس نے کہا: تیرے خوف نے۔ فرمایا: پھر اسے اس کے سوا (جو وہ بھگت چکا تھا، یعنی لاش کا جلنا اور اللہ کے سامنے پیشی وغیرہ) اور کوئی عذاب نہ ہوا۔\""}],[7040,"سلیمان ، شیبان بن عبدالرحمٰن اور ابوعوانہ سب نے قتادہ سے شعبہ کی سند کے ساتھ اسی کی حدیث کے مانند بیان کیا ۔ شیبان اور ابوعوانہ کی حدیث میں یہ الفاظ ہیں : \"\" لوگوں میں سے ایک آدمی کو اللہ تعالی نے بہت مال اور اولاد سے نوازا ۔ \"\" اور تمیمی کی حدیث میں ہے : \"\" اس نے اللہ کے پاس کوئی اچھائی جمع نہ کرائی \"\" کہا کہ قتادہ نے اس کی یہ تشریح کی : اس نے اللہ کے پاس کوئی اچھائی ذخیرہ نہ کی ۔ اور شیبان کی حدیث میں ہے : \"\" بےشک اس نے ، اللہ کی قسم! اللہ کے ہاں کوئی نیکی محفوظ نہ کرائی ۔ \"\" اور ابوعوانہ کی حدیث میں ہے : \"\" اس نے کچھ جمع نہ کیا \"\" امتار میم کے ساتھ ( یہ سب بولنے میں بھی ملتے جلتے الفاظ ہیں اور معنی میں بھی ۔)","",{"u2":"سلیمان، شیبان بن عبدالرحمٰن اور ابوعوانہ سب نے قتادہ سے شعبہ کی سند کے ساتھ اسی کی حدیث کے مانند بیان کیا۔ شیبان اور ابوعوانہ کی حدیث میں یہ الفاظ ہیں: \"لوگوں میں سے ایک آدمی کو اللہ تعالیٰ نے بہت مال اور اولاد سے نوازا۔\"\nاور تمیمی کی حدیث میں ہے: \"اس نے اللہ کے پاس کوئی اچھائی جمع نہ کرائی\" کہا کہ قتادہ نے اس کی یہ تشریح کی: اس نے اللہ کے پاس کوئی اچھائی ذخیرہ نہ کی۔ اور شیبان کی حدیث میں ہے: \"بےشک اس نے، اللہ کی قسم! اللہ کے ہاں کوئی نیکی محفوظ نہ کرائی۔\" اور ابوعوانہ کی حدیث میں ہے: \"اس نے کچھ جمع نہ کیا\" امتار میم کے ساتھ (یہ سب بولنے میں بھی ملتے جلتے الفاظ ہیں اور معنی میں بھی۔)"}],[7041,"عبدالاعلی بن حماد نے مجھے حدیث بیان کی ، انہوں نے کہا : ہمیں حماد بن سلمہ نے اسحٰق بن عبداللہ بن ابی طلحہ سے حدیث سنائی ، انہوں نے عبدالرحمٰن بن ابی عمرہ سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے اپنے رب عزوجل سے نقل کرتے ہوئے فرمایا : \"\" ایک بندے نے گناہ کیا ، اس نے کہا : اے اللہ! میرا گناہ بخش دے ، تو ( اللہ ) تبارک و تعالی نے فرمایا : میرے بندے نے گناہ کیا ہے ، اس کو پتہ ہے کہ اس کا رب ہے جو گناہ معاف بھی کرتا ہے اور گناہ پر گرفت بھی کرتا ہے ، اس بندے نے پھر گناہ کیا تو کہا : میرے رب! میرا گناہ بخش دے ، تو ( اللہ ) تبارک و تعالی نے فرمایا : میرا بندہ ہے ، اس نے گناہ کیا ہے تو اسے معلوم ہے کہ اس کا رب ہے جو گناہ بخش دیتا ہے اور ( چاہے تو ) گناہ پر پکڑتا ہے ۔ اس بندے نے پھر سے وہی کیا ، گناہ کیا اور کہا : میرے رب! میرے لیے میرا گناہ بخش دے ، تو ( اللہ ) تبارک و تعالی نے فرمایا : میرے بندے نے گناہ کیا تو اسے معلوم ہے کہ اس کا رب ہے جو گناہ بخشتا ہے اور ( چاہے تو ) گناہ پر پکڑ لیتا ہے ، ( میرے بندے! اب تو ) جو چاہے کر ، میں نے تجھے بخش دیا ہے ۔ \"\" عبدالاعلی نے کہا : مجھے ( پوری طرح ) معلوم نہیں کہ آپ صلی اللہ علیہ وسلم نے تیسری بار فرمایا یا چوتھی بار : \"\" جو چاہے کر ۔","",{"u2":"عبدالاعلیٰ بن حماد نے مجھے حدیث بیان کی، انہوں نے کہا: ہمیں حماد بن سلمہ نے اسحٰق بن عبداللہ بن ابی طلحہ سے حدیث سنائی، انہوں نے عبدالرحمٰن بن ابی عمرہ سے، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے اپنے رب عزوجل سے نقل کرتے ہوئے فرمایا: \"ایک بندے نے گناہ کیا، اس نے کہا: اے اللہ! میرا گناہ بخش دے، تو (اللہ) تبارک و تعالیٰ نے فرمایا: میرے بندے نے گناہ کیا ہے، اس کو پتہ ہے کہ اس کا رب ہے جو گناہ معاف بھی کرتا ہے اور گناہ پر گرفت بھی کرتا ہے، اس بندے نے پھر گناہ کیا تو کہا: میرے رب! میرا گناہ بخش دے، تو (اللہ) تبارک و تعالیٰ نے فرمایا: میرا بندہ ہے، اس نے گناہ کیا ہے تو اسے معلوم ہے کہ اس کا رب ہے جو گناہ بخش دیتا ہے اور (چاہے تو) گناہ پر پکڑتا ہے۔ اس بندے نے پھر سے وہی کیا، گناہ کیا اور کہا: میرے رب! میرے لیے میرا گناہ بخش دے، تو (اللہ) تبارک و تعالیٰ نے فرمایا: میرے بندے نے گناہ کیا تو اسے معلوم ہے کہ اس کا رب ہے جو گناہ بخشتا ہے اور (چاہے تو) گناہ پر پکڑ لیتا ہے، (میرے بندے! اب تو) جو چاہے کر، میں نے تجھے بخش دیا ہے۔\"\nعبدالاعلیٰ نے کہا: مجھے (پوری طرح) معلوم نہیں کہ آپ صلی اللہ علیہ وسلم نے تیسری بار فرمایا یا چوتھی بار: \"جو چاہے کر۔\""}],[7042,"محمد بن زنجویہ قشیری نے کہا : ہمیں عبدالاعلی بن حماد نرسی نے اسی سند کے ساتھ ( یہی ) حدیث بیان کی ۔","",{"u2":"محمد بن زنجویہ قشیری نے کہا: ہمیں عبدالاعلیٰ بن حماد نرسی نے اسی سند کے ساتھ (یہی) حدیث بیان کی۔"}],[7043,"ہمام نے کہا : ہمیں اسحٰق بن عبداللہ بن ابی طلحہ نے حدیث بیان کی ، انہوں نے کہا : مدینہ میں ایک واعظ تھا جسے عبدالرحمٰن بن ابی عمرہ کہا جاتا تھا ، میں نے اسے کہتے ہوئے سنا کہ میں نے سیدنا ابوہریرہ رضی اللہ عنہ کو یہ کہتے ہوئے سنا ، میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا : \" یقینا ایک بندے نے گناہ کیا \" ( آگے ) حماد بن سلمہ کی حدیث کے مطابق بیان کیا اور اس نے \" گناہ کیا \" ( کے الفاظ ) تین بار کہے اور تیسری دفعہ کے بعد کہا : \" میں نے اپنے بندے کو بخش دیا ، لہٰذا جو چاہے کرے ۔","",{"u2":"ہمام نے کہا: ہمیں اسحٰق بن عبداللہ بن ابی طلحہ نے حدیث بیان کی، انہوں نے کہا: مدینہ میں ایک واعظ تھا جسے عبدالرحمٰن بن ابی عمرہ کہا جاتا تھا، میں نے اسے کہتے ہوئے سنا کہ میں نے حضرت ابوہریرہ رضی اللہ عنہ کو یہ کہتے ہوئے سنا، میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا: \"یقینا ایک بندے نے گناہ کیا\" (آگے) حماد بن سلمہ کی حدیث کے مطابق بیان کیا اور اس نے \"گناہ کیا\" (کے الفاظ) تین بار کہے اور تیسری دفعہ کے بعد کہا: \"میں نے اپنے بندے کو بخش دیا، لہذا جو چاہے کرے۔\""}],[7044,"محمد بن جعفر نے کہا : ہمیں شعبہ نے عمرہ بن مرہ سے حدیث بیان کی ، انہوں نے کہا : میں نے ابوعبید کو سیدنا ابوموسی رضی اللہ عنہ سے حدیث بیان کرتے ہوئے سنا ، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" اللہ عزوجل رات کو اپنا دست ( رحمت بندوں کی طرف ) پھیلا دیتا ہے تاکہ دن کو گناہ کرنے والا توبہ کرے اور دن کو اپنا دست ( رحمت ) پھیلا دیتا ہے تاکہ رات کو گناہ کرنے والا توبہ کرے ( اور وہ اس وقت تک یہی کرتا رہے گا ) یہاں تک کہ سورج مغرب سے طلوع ہو جائے ۔","",{"u2":"محمد بن جعفر نے کہا: ہمیں شعبہ نے عمرہ بن مرہ سے حدیث بیان کی، انہوں نے کہا: میں نے ابوعبید کو حضرت ابوموسیٰ رضی اللہ عنہ سے حدیث بیان کرتے ہوئے سنا، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا: \"اللہ عزوجل رات کو اپنا دست (رحمت بندوں کی طرف) پھیلا دیتا ہے تاکہ دن کو گناہ کرنے والا توبہ کرے اور دن کو اپنا دست (رحمت) پھیلا دیتا ہے تاکہ رات کو گناہ کرنے والا توبہ کرے (اور وہ اس وقت تک یہی کرتا رہے گا) یہاں تک کہ سورج مغرب سے طلوع ہو جائے۔\""}],[7045,"محمد بن جعفر نے کہا : ہمیں شعبہ نے عمرہ بن مرہ سے حدیث بیان کی ، انہوں نے کہا : میں نے ابوعبید کو سیدنا ابوموسی رضی اللہ عنہ سے حدیث بیان کرتے ہوئے سنا ، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" اللہ عزوجل رات کو اپنا دست ( رحمت بندوں کی طرف ) پھیلا دیتا ہے تاکہ دن کو گناہ کرنے والا توبہ کرے اور دن کو اپنا دست ( رحمت ) پھیلا دیتا ہے تاکہ رات کو گناہ کرنے والا توبہ کرے ( اور وہ اس وقت تک یہی کرتا رہے گا ) یہاں تک کہ سورج مغرب سے طلوع ہو جائے ۔","",{"u2":"ابوداود نے کہا: ہمیں شعبہ نے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی۔"}],[7046,"جریر نے اعمش سے ، انہوں نے ابووائل ( شقیق ) سے اور انہوں نے سیدنا عبداللہ ( بن مسعود رضی اللہ عنہ ) سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ تعالی سے بڑھ کر کوئی نہیں جسے مدح ( اس کی رحمت و عنایت کا اقرار اور اس پر اس کی تعریف ) پسند ہو ، اسی لیے اس نے خود اپنی مدح فرمائی ہے اور کوئی نہیں جو اللہ سے بڑھ کر غیرت مند ہو ، اسی لیے اس نے بے حیائی کے تمام کام ، ان میں سے جو ظاہر ہیں اور جو پوشیدہ ہیں ، حرام کر دیے ہیں ۔","",{"u2":"جریر نے اعمش سے، انہوں نے ابووائل (شقیق) سے اور انہوں نے حضرت عبداللہ (بن مسعود رضی اللہ عنہ) سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ سے بڑھ کر کوئی نہیں جسے مدح (اس کی رحمت و عنایت کا اقرار اور اس پر اس کی تعریف) پسند ہو، اسی لیے اس نے خود اپنی مدح فرمائی ہے اور کوئی نہیں جو اللہ سے بڑھ کر غیرت مند ہو، اسی لیے اس نے بے حیائی کے تمام کام، ان میں سے جو ظاہر ہیں اور جو پوشیدہ ہیں، حرام کر دیے ہیں۔\""}],[7047,"عبداللہ بن نمیر اور ابومعاویہ نے اعمش سے ، انہوں نے شقیق سے اور انہوں نے سیدنا عبداللہ ( بن مسعود رضی اللہ عنہ ) سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ سے بڑھ کر کوئی غیور نہیں ہے ، اسی لیے اس نے بے حیائی کے تمام کام ، ان میں سے جو ظاہر ہیں اور جو پوشیدہ ہیں حرام کر دیے ہیں ، اللہ تعالی سے بڑھ کر کوئی نہیں ہے جسے مدح زیادہ پسند ہو ۔","",{"u2":"عبداللہ بن نمیر اور ابومعاویہ نے اعمش سے، انہوں نے شقیق سے اور انہوں نے حضرت عبداللہ (بن مسعود رضی اللہ عنہ) سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ سے بڑھ کر کوئی غیور نہیں ہے، اسی لیے اس نے بے حیائی کے تمام کام، ان میں سے جو ظاہر ہیں اور جو پوشیدہ ہیں حرام کر دیے ہیں، اللہ تعالیٰ سے بڑھ کر کوئی نہیں ہے جسے مدح زیادہ پسند ہو۔\""}],[7048,"عمرو بن مرہ نے کہا : میں نے ابووائل کو کہتے ہوئے سنا کہ میں نے سیدنا عبداللہ بن مسعود رضی اللہ عنہ کو یہ کہتے ہوئے سنا ، وہ کہتے تھے ۔ ۔ ( عمرو بن مرہ نے ) کہا : میں نے ان ( ابووائل ) سے کہا : کیا آپ نے خود عبداللہ بن مسعود رضی اللہ عنہ سے سنا تھا؟ انہوں نے کہا : ہاں ۔ اور انہوں نے اسے مرفوعا بیان کیا : ۔ ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ سے بڑھ کر کوئی غیرت مند نہیں ، اسی لیے اس نے تمام کھلی اور پوشیدہ فواحش ( بے حیائی کی باتیں ) حرام کر دیں اور اللہ سے بڑھ کر کسی کو مدح پسند نہیں ( کیونکہ حقیقت میں وہی مدح کا حقدار ہے ) ، اسی لیے اس نے اپنی مدح فرمائی ہے ۔","",{"u2":"عمرو بن مرہ نے کہا: میں نے ابووائل کو کہتے ہوئے سنا کہ میں نے حضرت عبداللہ بن مسعود رضی اللہ عنہ کو یہ کہتے ہوئے سنا، وہ کہتے تھے۔۔ (عمرو بن مرہ نے) کہا: میں نے ان (ابووائل) سے کہا: کیا آپ نے خود عبداللہ بن مسعود رضی اللہ عنہ سے سنا تھا؟ انہوں نے کہا: ہاں۔ اور انہوں نے اسے مرفوعا بیان کیا:۔۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ سے بڑھ کر کوئی غیرت مند نہیں، اسی لیے اس نے تمام کھلی اور پوشیدہ فواحش (بے حیائی کی باتیں) حرام کر دیں اور اللہ سے بڑھ کر کسی کو مدح پسند نہیں (کیونکہ حقیقت میں وہی مدح کا حقدار ہے)، اسی لیے اس نے اپنی مدح فرمائی ہے۔\""}],[7049,"عبدالرحمٰن بن یزید نے سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کوئی نہیں جسے اللہ سے بڑھ کر مدح پسند ہو ، اسی بنا پر اس نے اپنی مدح فرمائی اور کوئی نہیں جو اللہ سے بڑھ کر غیرت مند ہو ، اسی بنا پر اس نے تمام فواحش حرام کر دیں اور کوئی نہیں جسے اللہ سے بڑھ کر ( بندوں کا اس سے ) معذرت کرنا پسند ہو ، اسی بنا پر اس نے کتاب نازل فرمائی اور پیغمبروں کو بھیجا ۔","",{"u2":") عبدالرحمٰن بن یزید نے حضرت عبداللہ بن مسعود رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"کوئی نہیں جسے اللہ سے بڑھ کر مدح پسند ہو، اسی بنا پر اس نے اپنی مدح فرمائی اور کوئی نہیں جو اللہ سے بڑھ کر غیرت مند ہو، اسی بنا پر اس نے تمام فواحش حرام کر دیں اور کوئی نہیں جسے اللہ سے بڑھ کر (بندوں کا اس سے) معذرت کرنا پسند ہو، اسی بنا پر اس نے کتاب نازل فرمائی اور پیغمبروں کو بھیجا۔\""}],[7050,"حجاج بن ابی عثمان نے کہا : یحیی ( بن ابی کثیر ) نے کہا : مجھے ابوسلمہ نے سیدنا ابوہریرہ رضی اللہ عنہ سے حدیث بیان کی ، انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ تعالی غیرت فرماتا ہے اور بےشک مومن بھی غیرت کرتا ہے ۔ اللہ کی غیرت اس بات پر ہوتی ہے کہ مومن ایسے کام کا ارتکاب کرے جو اس نے اس پر حرام کیا ہے ۔","",{"u2":"حجاج بن ابی عثمان نے کہا: یحییٰ (بن ابی کثیر) نے کہا: مجھے ابوسلمہ نے حضرت ابوہریرہ رضی اللہ عنہ سے حدیث بیان کی، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ غیرت فرماتا ہے اور بےشک مومن بھی غیرت کرتا ہے۔ اللہ کی غیرت اس بات پر ہوتی ہے کہ مومن ایسے کام کا ارتکاب کرے جو اس نے اس پر حرام کیا ہے۔\""}],[7051,"یحیی نے کہا : مجھے ابوسلمہ نے حدیث بیان کی ، انہٰن عروہ بن زبیر نے بیان کیا ، انہیں سیدہ اسماء بنت ابی بکر رضی اللہ عنہا نے حدیث سنائی کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ ارشاد فرماتے ہوئے سنا : \" کوئی نہیں جو اللہ عزوجل سے زیادہ غیرت مند ہو ۔","",{"u2":"یحییٰ نے کہا: مجھے ابوسلمہ نے حدیث بیان کی، انہٰن عروہ بن زبیر نے بیان کیا، انہیں حضرت اسماء بنت ابی بکر رضی اللہ عنہا نے حدیث سنائی کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ ارشاد فرماتے ہوئے سنا: \"کوئی نہیں جو اللہ عزوجل سے زیادہ غیرت مند ہو۔\""}],[7052,"ابان بن یزید اور حرب بن شداد نے یحیی بن ابی کثیر سے ، انہوں نے ابوسلمہ سے ، انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے حجاج کی روایت کے مانند صرف سیدنا ابوہریرہ رضی اللہ عنہ کی حدیث بیان کی اور انہوں نے سیدہ اسماء رضی اللہ عنہا کی حدیث کا ذکر نہیں کیا ۔","",{"u2":"ابان بن یزید اور حرب بن شداد نے یحییٰ بن ابی کثیر سے، انہوں نے ابوسلمہ سے، انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے حجاج کی روایت کے مانند صرف حضرت ابوہریرہ رضی اللہ عنہ کی حدیث بیان کی اور انہوں نے حضرت اسماء رضی اللہ عنہا کی حدیث کا ذکر نہیں کیا۔"}],[7053,"ہشام نے یحیی بن ابی کثیر سے ، انہوں نے ابوسلمہ سے ، انہوں نے عروہ سے ، انہوں نے سیدہ اسماء رضی اللہ عنہا سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ عزوجل سے بڑھ کر کوئی غیور نہیں ہے ۔","",{"u2":"ہشام نے یحییٰ بن ابی کثیر سے، انہوں نے ابوسلمہ سے، انہوں نے عروہ سے، انہوں نے حضرت اسماء رضی اللہ عنہا سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ عزوجل سے بڑھ کر کوئی غیور نہیں ہے۔\""}],[7054,"عبدالعزیز بن محمد نے علاء سے ، انہوں نے اپنے والد ( عبدالرحمٰن ) سے اور انہوں نے سیدنا ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" مومن ( دوسرے ) مومن کے لیے غیرت کرتا ہے ( کہ اس کی حرمت پامال نہ کی جائے ) اور اللہ تعالی تو غیرت میں اس سے بڑھ کر ہے ۔","",{"u2":"عبدالعزیز بن محمد نے علاء سے، انہوں نے اپنے والد (عبدالرحمٰن) سے اور انہوں نے حضرت ابوہریرہ رضی اللہ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مومن (دوسرے) مومن کے لیے غیرت کرتا ہے (کہ اس کی حرمت پامال نہ کی جائے) اور اللہ تعالیٰ تو غیرت میں اس سے بڑھ کر ہے۔\""}],[7055,"شعبہ نے کہا : میں نے علاء کو اسی سند کے ساتھ ( یہی حدیث بیان کرتے ہوئے ) سنا ۔","",{"u2":"شعبہ نے کہا: میں نے علاء کو اسی سند کے ساتھ (یہی حدیث بیان کرتے ہوئے) سنا۔"}],[7056,"یزید نے کہا؛ ہمیں تیمی نے ابوعثمان سے حدیث بیان کی ، انہوں نے سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت کی کہ ایک شخص نے ایک عورت کو بوسہ دیا ، ( پھر ) وہ نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور اس واقعے کا ذکر کیا ، تب ( یہ آیت ) نازل ہوئی : \" دن کے دونوں حصوں اور رات کے کچھ حصوں میں نماز قائم رکھو ، بےشک نیکیاں برائیوں کو دور کر دیتی ہیں ، یہ یاد دہانی ہے یاد رکھنے والوں کے لیے ۔ \" اس شخص نے کہا : اللہ کے رسول! کیا یہ ( بشارت ) صرف میرے لیے ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا : \" میری امت میں سے جو بھی ( گناہوں سے پاک ہونے کے لیے ) اس پر عمل کرے ۔","",{"u2":"یزید نے کہا؛ ہمیں تیمی نے ابوعثمان سے حدیث بیان کی، انہوں نے حضرت عبداللہ بن مسعود رضی اللہ عنہ سے روایت کی کہ ایک شخص نے ایک عورت کو بوسہ دیا، (پھر) وہ نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور اس واقعے کا ذکر کیا، تب (یہ آیت) نازل ہوئی: \"دن کے دونوں حصوں اور رات کے کچھ حصوں میں نماز قائم رکھو، بےشک نیکیاں برائیوں کو دور کر دیتی ہیں، یہ یاد دہانی ہے یاد رکھنے والوں کے لیے۔\" اس شخص نے کہا: اللہ کے رسول! کیا یہ (بشارت) صرف میرے لیے ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"میری امت میں سے جو بھی (گناہوں سے پاک ہونے کے لیے) اس پر عمل کرے۔\""}],[7057,"ابو احوص نے سماک سے ، انہوں نے ابراہیم سے ، انہوں نے علقمہ اور اسود سے اور انہوں نے سیدنا عبداللہ ( بن مسعود رضی اللہ عنہ ) سے روایت کی کہ ایک شخص نبی صلی اللہ علیہ وسلم کے پاس آیا تو اس نے کہا : اللہ کے رسول! میں نے مدینہ کے آخری حصے میں ایک عورت کو قابو کر لیا اور اس کے علاوہ کہ میں اس سے جماع کروں میں نے اس سے اور سب کچھ حاصل کر لیا ۔ تو ( اب ) میں آپ کے سامنے حاضر ہوں ، آپ میرے بارے میں جو چاہیں فیصلہ کر لیں ۔ سیدنا عمر رضی اللہ عنہ نے اس سے کہا : اللہ نے تمہارا پردہ رکھا ، کاش! تم خود بھی اپنا پردہ رکھتے ۔ ( سیدنا عبداللہ بن مسعود رضی اللہ عنہ نے ) کہا : رسول اللہ صلی اللہ علیہ وسلم نے اسے کوئی جواب نہ دیا ۔ تو ( کچھ دیر بعد ) وہ شخص اٹھا اور چل دیا ۔ نبی صلی اللہ علیہ وسلم نے اس کے پیچھے ایک آدمی بھیج کر اسے بلایا اور اس کے سامنے یہ آیت پڑھی : \" دن کے دونوں حصوں اور رات کے کچھ حصوں میں نماز قائم کرو ، بےشک نیکیاں برائیوں کو ختم کر دیتی ہیں ۔ یہ ان کے لیے یاددہانی ہے جو اچھی بات کو یاد رکھنے والے ہیں ۔ \" اس پر لوگوں میں سے ایک آدمی نے کہا : اللہ کے نبی! کیا یہ خاص اسی کے لیے ہے؟ آپ صلی اللہ علیہ وسلم نے ارشاد فرمایا : \" بلکہ تمام لوگوں کے لیے ہے ۔","",{"u2":"معتمر نے اپنے والد (سلیمان تیمی) سے روایت کی، انہوں نے کہا: ہمیں ابوعثمان نے حضرت ابن مسعود رضی اللہ عنہ سے حدیث بیان کی کہ ایک شخص نبی صلی اللہ علیہ وسلم کی خدمت میں آیا اور اس نے ذکر کیا کہ اس نے ایک عورت کو بوسہ دیا ہے یا اس کو ہاتھ سے مس کیا ہے (یا ایسا) کوئی اور کام کیا ہے، گویا کہ وہ اس کے کفار کے متعلق سوال کر رہا ہے، کہا: تب اللہ عزوجل نے یہ آیت نازل فرمائی، پھر یزید کی حدیث کے مانند بیان کیا۔"}],[7058,"شعبہ نے سماک بن حرب سے روایت کی ، انہوں نے کہا : میں نے ابراہیم کو اپنے ماموں اسود سے حدیث بیان کرتے ہوئے سنا ، انہوں نے سیدنا عبداللہ ( بن مسعود رضی اللہ عنہ ) سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے ابو احوص کی حدیث کے ہم معنی روایت کی ، انہوں نے اپنی حدیث میں کہا : تو سیدنا معاذ رضی اللہ عنہ نے عرض کی : اللہ کے رسول! کیا یہ خاص اسی کے لیے ہے یا عمومی طور پر ہم سب کے لیے ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا : \" بلکہ تم سب کے لیے عام ہے ۔","",{"u2":"جریر نے سلیمان تیمی سے اسی سند کے ساتھ روایت کی، کہا: ایک شخص نے ایک عورت کے ساتھ زنا سے کم درجے کا کوئی کام کیا۔ وہ حضرت عمر بن خطاب رضی اللہ عنہ کے پاس گیا، انہوں نے اس کے سامنے اس کو بہت بڑا گناہ قرار دیا، پھر وہ حضرت ابوبکر رضی اللہ عنہ کے پاس آیا، انہوں نے بھی اس کے لیے اس کو بہت بڑی بات قرار دیا، پھر وہ نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا، (آگے) یزید اور معتمر کی حدیث کے مانند بیان کیا۔"}],[7059,"معتمر نے اپنے والد ( سلیمان تیمی ) سے روایت کی ، انہوں نے کہا : ہمیں ابوعثمان نے سیدنا ابن مسعود رضی اللہ عنہ سے حدیث بیان کی کہ ایک شخص نبی صلی اللہ علیہ وسلم کی خدمت میں آیا اور اس نے ذکر کیا کہ اس نے ایک عورت کو بوسہ دیا ہے یا اس کو ہاتھ سے مس کیا ہے ( یا ایسا ) کوئی اور کام کیا ہے ، گویا کہ وہ اس کے کفار کے متعلق سوال کر رہا ہے ، کہا : تب اللہ عزوجل نے یہ آیت نازل فرمائی ، پھر یزید کی حدیث کے مانند بیان کیا ۔","",{"u2":"ابو احوص نے سماک سے، انہوں نے ابراہیم سے، انہوں نے علقمہ اور اسود سے اور انہوں نے حضرت عبداللہ (بن مسعود رضی اللہ عنہ) سے روایت کی کہ ایک شخص نبی صلی اللہ علیہ وسلم کے پاس آیا تو اس نے کہا: اللہ کے رسول! میں نے مدینہ کے آخری حصے میں ایک عورت کو قابو کر لیا اور اس کے علاوہ کہ میں اس سے جماع کروں میں نے اس سے اور سب کچھ حاصل کر لیا۔ تو (اب) میں آپ کے سامنے حاضر ہوں، آپ میرے بارے میں جو چاہیں فیصلہ کر لیں۔ حضرت عمر رضی اللہ عنہ نے اس سے کہا: اللہ نے تمہارا پردہ رکھا، کاش! تم خود بھی اپنا پردہ رکھتے۔ (حضرت عبداللہ بن مسعود رضی اللہ عنہ نے) کہا: رسول اللہ صلی اللہ علیہ وسلم نے اسے کوئی جواب نہ دیا۔ تو (کچھ دیر بعد) وہ شخص اٹھا اور چل دیا۔ نبی صلی اللہ علیہ وسلم نے اس کے پیچھے ایک آدمی بھیج کر اسے بلایا اور اس کے سامنے یہ آیت پڑھی: \"دن کے دونوں حصوں اور رات کے کچھ حصوں میں نماز قائم کرو، بےشک نیکیاں برائیوں کو ختم کر دیتی ہیں۔ یہ ان کے لیے یاددہانی ہے جو اچھی بات کو یاد رکھنے والے ہیں۔\" اس پر لوگوں میں سے ایک آدمی نے کہا: اللہ کے نبی! کیا یہ خاص اسی کے لیے ہے؟ آپ صلی اللہ علیہ وسلم نے ارشاد فرمایا: \"بلکہ تمام لوگوں کے لیے ہے۔\""}],[7060,"جریر نے سلیمان تیمی سے اسی سند کے ساتھ روایت کی ، کہا : ایک شخص نے ایک عورت کے ساتھ زنا سے کم درجے کا کوئی کام کیا ۔ وہ سیدنا عمر بن خطاب رضی اللہ عنہ کے پاس گیا ، انہوں نے اس کے سامنے اس کو بہت بڑا گناہ قرار دیا ، پھر وہ سیدنا ابوبکر رضی اللہ عنہ کے پاس آیا ، انہوں نے بھی اس کے لیے اس کو بہت بڑی بات قرار دیا ، پھر وہ نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا ، ( آگے ) یزید اور معتمر کی حدیث کے مانند بیان کیا ۔","",{"u2":"شعبہ نے سماک بن حرب سے روایت کی، انہوں نے کہا: میں نے ابراہیم کو اپنے ماموں اسود سے حدیث بیان کرتے ہوئے سنا، انہوں نے حضرت عبداللہ (بن مسعود رضی اللہ عنہ) سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے ابو احوص کی حدیث کے ہم معنی روایت کی، انہوں نے اپنی حدیث میں کہا: تو حضرت معاذ رضی اللہ عنہ نے عرض کی: اللہ کے رسول! کیا یہ خاص اسی کے لیے ہے یا عمومی طور پر ہم سب کے لیے ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"بلکہ تم سب کے لیے عام ہے۔\""}],[7061,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ ایک شخص نبی صلی اللہ علیہ وسلم کے پاس آیا اور عرض کی : اللہ کے رسول! میں نے حد ( لگنے والے کام ) کا ارتکاب کر لیا ہے ، مجھ پر حد قائم کیجئے ۔ ( سیدنا انس رضی اللہ عنہ نے ) کہا : ( تب ) نماز کا وقت آ گیا ، اس نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھی ۔ جب نماز پڑھ لی تو کہنے لگا : اللہ کے رسول! میں نے حد ( کے قابل گناہ ) کا ارتکاب کیا ہے ، میرے بارے میں اللہ کی کتاب کا ( جو ) فیصلہ ( ہے اسے ) نافذ فرمائیے ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : \" کیا تو ہمارے ساتھ نماز میں شامل ہوا؟ \" اس نے عرض کی : ہاں ، فرمایا : \" تیرا گناہ بخش دیا گیا ہے ۔","",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے کہ ایک شخص نبی صلی اللہ علیہ وسلم کے پاس آیا اور عرض کی: اللہ کے رسول! میں نے حد (لگنے والے کام) کا ارتکاب کر لیا ہے، مجھ پر حد قائم کیجئے۔ (حضرت انس رضی اللہ عنہ نے) کہا: (تب) نماز کا وقت آ گیا، اس نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھی۔جب نماز پڑھ لی تو کہنے لگا: اللہ کے رسول! میں نے حد (کے قابل گناہ) کا ارتکاب کیا ہے، میرے بارے میں اللہ کی کتاب کا (جو) فیصلہ (ہے اسے) نافذ فرمائیے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تو ہمارے ساتھ نماز میں شامل ہوا؟\" اس نے عرض کی: ہاں، فرمایا: \"تیرا گناہ بخش دیا گیا ہے۔\""}],[7062,"شداد نے ہمیں حدیث بیان کی ، کہا : ہمیں سیدنا ابو امامہ رضی اللہ عنہ نے حدیث بیان کی ، کہا : ایک بار رسول اللہ صلی اللہ علیہ وسلم مسجد میں تشریف فرما تھے اور ہم بھی آپ کے پاس بیٹھے ہوئے تھے کہ ایک شخص آیا تو کہنے لگا : اللہ کے رسول! میں نے حد ( کے قابل گناہ ) کا ارتکاب کر دیا ہے ، لہٰذا آپ مجھ پر حد قائم کیجئے ۔ رسول اللہ صلی اللہ علیہ وسلم خاموش رہے ، اس نے دوبارہ کہا : اللہ کے رسول! میں حد کا مستحق ہو گیا ہوں ، آپ مجھ پر حد قائم کیجئے ۔ نبی صلی اللہ علیہ وسلم خاموش رہے ، اس نے تیسری بار ( یہی ) کہا تو ( اس وقت ) نماز کی اقامت کہہ دی گئی ۔ سیدنا ابو امامہ رضی اللہ عنہ نے کہا : جب رسول اللہ صلی اللہ علیہ وسلم نماز سے ( فارغ ہو کر ) واپس ہوئے تو وہ شخص آپ کے پیچھے چل پڑا ، میں ( بھی ) رسول اللہ صلی اللہ علیہ وسلم کے پیچھے چل پڑا کہ دیکھوں آپ صلی اللہ علیہ وسلم اس کو کیا جواب دیتے ہیں ۔ وہ شخص رسول اللہ صلی اللہ علیہ وسلم سے جا ملا اور کہا : اللہ کے رسول! میں نے حد ( کے قابل گناہ ) کا ارتکاب کیا ہے ، آپ مجھ پر حد قائم فرمائیں ۔ سیدنا ابو امامہ رضی اللہ عنہ نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے اس سے کہا : \" ذرا دیکھو : جب تم اپنے گھر سے نکلے تھے تو تم نے وضو کیا تھا اور اچھی طرح وضو کیا تھا؟ \" اس نے عرض کی : ہاں ، اللہ کے رسول! ( اچھی طرح وضو کیا تھا ۔ ) فرمایا : \" اس کے بعد تم نے ہمارے ساتھ نماز پڑھی؟ \" اس نے عرض کی : جی ہاں ، اللہ کے رسول! ( سیدنا ابو امامہ رضی اللہ عنہ نے ) کہا : رسول اللہ صلی اللہ علیہ وسلم نے اُسے فرمایا : \" تو یقینا اللہ تعالی نے تمہاری حد ۔ ۔ یا فرمایا ۔ ۔ تمہارے گناہ کو معاف کر دیا ہے ۔","",{"u2":"شداد نے ہمیں حدیث بیان کی، کہا: ہمیں حضرت ابو امامہ رضی اللہ عنہ نے حدیث بیان کی، کہا: ایک بار رسول اللہ صلی اللہ علیہ وسلم مسجد میں تشریف فرما تھے اور ہم بھی آپ کے پاس بیٹھے ہوئے تھے کہ ایک شخص آیا تو کہنے لگا: اللہ کے رسول! میں نے حد (کے قابل گناہ) کا ارتکاب کر دیا ہے، لہذا آپ مجھ پر حد قائم کیجئے۔ رسول اللہ صلی اللہ علیہ وسلم خاموش رہے، اس نے دوبارہ کہا: اللہ کے رسول! میں حد کا مستحق ہو گیا ہوں، آپ مجھ پر حد قائم کیجئے۔ نبی صلی اللہ علیہ وسلم خاموش رہے، اس نے تیسری بار (یہی) کہا تو (اس وقت) نماز کی اقامت کہہ دی گئی۔ حضرت ابو امامہ رضی اللہ عنہ نے کہا: جب رسول اللہ صلی اللہ علیہ وسلم نماز سے (فارغ ہو کر) واپس ہوئے تو وہ شخص آپ کے پیچھے چل پڑا، میں (بھی) رسول اللہ صلی اللہ علیہ وسلم کے پیچھے چل پڑا کہ دیکھوں آپ صلی اللہ علیہ وسلم اس کو کیا جواب دیتے ہیں۔ وہ شخص رسول اللہ صلی اللہ علیہ وسلم سے جا ملا اور کہا: اللہ کے رسول! میں نے حد (کے قابل گناہ) کا ارتکاب کیا ہے، آپ مجھ پر حد قائم فرمائیں۔ حضرت ابو امامہ رضی اللہ عنہ نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے اس سے کہا: \"ذرا دیکھو: جب تم اپنے گھر سے نکلے تھے تو تم نے وضو کیا تھا اور اچھی طرح وضو کیا تھا؟\" اس نے عرض کی: ہاں، اللہ کے رسول! (اچھی طرح وضو کیا تھا۔) فرمایا: \"اس کے بعد تم نے ہمارے ساتھ نماز پڑھی؟\" اس نے عرض کی: جی ہاں، اللہ کے رسول! (حضرت ابو امامہ رضی اللہ عنہ نے) کہا: رسول اللہ صلی اللہ علیہ وسلم نے اُسے فرمایا: \"تو یقینا اللہ تعالیٰ نے تمہاری حد۔۔ یا فرمایا۔۔ تمہارے گناہ کو معاف کر دیا ہے۔\""}],[7063,"ہشام نے قتادہ سے ، انہوں نے ابوصدیق سے اور انہوں نے سیدنا ابوسعید خدری رضی اللہ عنہ سے روایت کی ، کہا کہ نبی صلی اللہ علیہ وسلم نے فرمایا : \"\" تم سے پہلے لوگوں میں سے ایک شخص تھا اس نے ننانوے قتل کیے ، پھر اس نے زمین پر بسنے والوں میں سے سب سے بڑے عالم کے بارے میں پوچھا ( کہ وہ کون ہے ۔ ) اسے ایک راہب کا پتہ بتایا گیا ۔ وہ اس کے پاس آیا اور پوچھا کہ اس نے ننانوے قتل کیے ہیں ، کیا اس کے لیے توبہ ( کی کوئی سبیل ) ہے؟ اس نے کہا : نہیں ۔ تو اس نے اسے بھی قتل کر دیا اور اس ( کے قتل ) سے سو قتل پورے کر لیے ۔ اس نے پھر اہل زمین میں سے سب سے بڑے عالم کے بارے میں دریافت کیا ۔ اسے ایک عالم کا پتہ بتایا گیا ۔ تو اس نے ( جا کر ) کہا : اس نے سو قتل کیے ہیں ، کیا اس کے لیے توبہ ( کا امکان ) ہے؟ اس ( عالم ) نے کہا : ہاں ، اس کے اور توبہ کے درمیان کون حائل ہو سکتا ہے؟ تم فلاں فلاں سرزمین پر چلے جاؤ ، وہاں ( ایسے ) لوگ ہیں جو اللہ تعالی کی عبادت کرتے ہیں ، تم بھی ان کے ساتھ اللہ کی عبادت میں مشغول ہو جاؤ اور اپنی سرزمین پر واپس نہ آو ، یہ بُری ( باتوں سے بھری ہوئی ) سرزمین ہے ۔ وہ چل پڑا ، یہاں تک کہ جب آدھا راستہ طے کر لیا تو اسے موت آ لیا ۔ اس کے بارے میں رحمت کے فرشتے اور عذاب کے فرشتے جھگڑنے لگے ۔ رحمت کے فرشتوں نے کہا : یہ شخص توبہ کرتا ہوا اپنے دل کو اللہ کی طرف متوجہ کر کے آیا تھا اور عذاب کے فرشتوں نے کہا : اس نے کبھی نیکی کا کوئی کام نہیں کیا ۔ تو ایک فرشتہ آدمی کے روپ میں ان کے پاس آیا ، انہوں نے اسے اپنے درمیان ( ثالث ) مقرر کر لیا ۔ اس نے کہا : دونوں زمینوں کے درمیان فاصلہ ماپ لو ، وہ دونوں میں سے جس زمین کے زیادہ قریب ہو تو وہ اسی ( زمین کے لوگوں ) میں سے ہو گا ۔ انہوں نے مسافت کو ماپا تو اسے اس زمین کے قریب تر پایا جس کی طرف وہ جا رہا تھا ، چنانچہ رحمت کے فرشتوں نے اسے اپنے ہاتھوں میں لے لیا ۔ \"\" قتادہ نے کہا : حسن ( بصری ) نے کہا : ( اس حدیث میں ) ہمیں بتایا گیا کہ جب اسے موت نے آ لیا تھا تو اس نے اپنے سینے سے ( گھسیٹ کر ) خود کو ( گناہوں بھری زمین سے ) دور کر لیا تھا ۔","",{"u2":"ہشام نے قتادہ سے، انہوں نے ابوصدیق سے اور انہوں نے حضرت ابوسعید خدری رضی اللہ عنہ سے روایت کی، کہا کہ نبی صلی اللہ علیہ وسلم نے فرمایا: \"تم سے پہلے لوگوں میں سے ایک شخص تھا اس نے ننانوے قتل کیے، پھر اس نے زمین پر بسنے والوں میں سے سب سے بڑے عالم کے بارے میں پوچھا (کہ وہ کون ہے۔) اسے ایک راہب کا پتہ بتایا گیا۔ وہ اس کے پاس آیا اور پوچھا کہ اس نے ننانوے قتل کیے ہیں، کیا اس کے لیے توبہ (کی کوئی سبیل) ہے؟ اس نے کہا: نہیں۔ تو اس نے اسے بھی قتل کر دیا اور اس (کے قتل) سے سو قتل پورے کر لیے۔ اس نے پھر اہل زمین میں سے سب سے بڑے عالم کے بارے میں دریافت کیا۔ اسے ایک عالم کا پتہ بتایا گیا۔ تو اس نے (جا کر) کہا: اس نے سو قتل کیے ہیں، کیا اس کے لیے توبہ (کا امکان) ہے؟ اس (عالم) نے کہا: ہاں، اس کے اور توبہ کے درمیان کون حائل ہو سکتا ہے؟ تم فلاں فلاں سرزمین پر چلے جاؤ، وہاں (ایسے) لوگ ہیں جو اللہ تعالیٰ کی عبادت کرتے ہیں، تم بھی ان کے ساتھ اللہ کی عبادت میں مشغول ہو جاؤ اور اپنی سرزمین پر واپس نہ آو،یہ بُری (باتوں سے بھری ہوئی) سرزمین ہے۔ وہ چل پڑا، یہاں تک کہ جب آدھا راستہ طے کر لیا تو اسے موت آ لیا۔ اس کے بارے میں رحمت کے فرشتے اور عذاب کے فرشتے جھگڑنے لگے۔ رحمت کے فرشتوں نے کہا: یہ شخص توبہ کرتا ہوا اپنے دل کو اللہ کی طرف متوجہ کر کے آیا تھا اور عذاب کے فرشتوں نے کہا: اس نے کبھی نیکی کا کوئی کام نہیں کیا۔ تو ایک فرشتہ آدمی کے روپ میں ان کے پاس آیا، انہوں نے اسے اپنے درمیان (ثالث) مقرر کر لیا۔ اس نے کہا: دونوں زمینوں کے درمیان فاصلہ ماپ لو، وہ دونوں میں سے جس زمین کے زیادہ قریب ہو تو وہ اسی (زمین کے لوگوں) میں سے ہو گا۔ انہوں نے مسافت کو ماپا تو اسے اس زمین کے قریب تر پایا جس کی طرف وہ جا رہا تھا، چنانچہ رحمت کے فرشتوں نے اسے اپنے ہاتھوں میں لے لیا۔\"\nقتادہ نے کہا: حسن (بصری) نے کہا: (اس حدیث میں) ہمیں بتایا گیا کہ جب اسے موت نے آ لیا تھا تو اس نے اپنے سینے سے (گھسیٹ کر) خود کو (گناہوں بھری زمین سے) دور کر لیا تھا۔"}],[7064,"معاذ بن عنبری نے کہا : ہمیں شعبہ نے قتادہ سے حدیث سنائی ، انہوں نے ابو صدیق ناجی سے سنا ، انہوں نے سیدنا ابوسعید خدری رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی : \" ایک شخص نے ننانوے انسان قتل کیے ، پھر اس نے یہ پوچھنا شروع کر دیا : کیا اس کی توبہ ( کی کوئی سبیل ) ہو سکتی ہے؟ وہ ایک راہب کے پاس آیا ، اس سے پوچھا تو اس نے جواب دیا : تیرے لیے کوئی توبہ نہیں ۔ اس نے اس راہب کو ( بھی ) قتل کر دیا ۔ اس کے بعد اس نے پھر سے ( توبہ کے متعلق ) پوچھنا شروع کر دیا ، پھر ایک بستی سے ( دوسری ) بستی کی طرف نکل پڑا جس میں نیک لوگ رہتے تھے ۔ وہ راستے کے کسی حصے میں تھا کہ اسے موت نے آن لیا ، وہ ( اس وقت ) اپنے سینے کے ذریعے سے ( پچھلی گناہوں بھری بستی سے ) دور ہوا ، پھر مر گیا ۔ تو اس کے بارے میں رحمت کے فرشتوں اور عذاب کے فرشتوں نے آپس میں جھگڑا کیا ۔ تو وہ شخص ایک بالشت برابر نیک بستی کی طرف قریب تھا ، اسے اس بستی کے لوگوں میں سے ( شمار ) کر لیا گیا ۔","",{"u2":"معاذ بن عنبری نے کہا: ہمیں شعبہ نے قتادہ سے حدیث سنائی، انہوں نے ابو صدیق ناجی سے سنا، انہوں نے حضرت ابوسعید خدری رضی اللہ عنہ سے اور انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی: \"ایک شخص نے ننانوے انسان قتل کیے، پھر اس نے یہ پوچھنا شروع کر دیا: کیا اس کی توبہ (کی کوئی سبیل) ہو سکتی ہے؟ وہ ایک راہب کے پاس آیا، اس سے پوچھا تو اس نے جواب دیا: تیرے لیے کوئی توبہ نہیں۔ اس نے اس راہب کو (بھی) قتل کر دیا۔ اس کے بعد اس نے پھر سے (توبہ کے متعلق) پوچھنا شروع کر دیا، پھر ایک بستی سے (دوسری) بستی کی طرف نکل پڑا جس میں نیک لوگ رہتے تھے۔ وہ راستے کے کسی حصے میں تھا کہ اسے موت نے آن لیا، وہ (اس وقت) اپنے سینے کے ذریعے سے (پچھلی گناہوں بھری بستی سے) دور ہوا، پھر مر گیا۔ تو اس کے بارے میں رحمت کے فرشتوں اور عذاب کے فرشتوں نے آپس میں جھگڑا کیا۔ تو وہ شخص ایک بالشت برابر نیک بستی کی طرف قریب تھا، اسے اس بستی کے لوگوں میں سے (شمار) کر لیا گیا۔\""}],[7065,"شعبہ نے ہمیں قتادہ سے اسی سند کے ساتھ اسی طرح حدیث بیان کی جس طرح معاذ بن معاذ کی حدیث ہے اور اس میں مزید یہ کہا : \" تو اللہ نے اس ( گناہگاروں کی بستی ) کو وحی کر دی کہ تو دور ہو جا اور اس ( نیک لوگوں کی بستی ) کو وحی کر دی کہ تو قریب ہو جا ۔","",{"u2":"شعبہ نے ہمیں قتادہ سے اسی سند کے ساتھ اسی طرح حدیث بیان کی جس طرح معاذ بن معاذ کی حدیث ہے اور اس میں مزید یہ کہا: \"تو اللہ نے اس (گناہگاروں کی بستی) کو وحی کر دی کہ تو دور ہو جا اور اس (نیک لوگوں کی بستی) کو وحی کر دی کہ تو قریب ہو جا۔\""}],[7066,"طلحہ بن یحیی نے ابوبردہ سے اور انہوں نے سیدنا ابوموسی رضی اللہ عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جب قیامت کا دن ہو گا تو اللہ تعالی ( ایک مرحلے پر ) ہر مسلمان کو ایک یہودی یا نصرانی عطا کر دے گا ، پھر فرمائے گا : یہ جہنم سے تمہارے لیے چھٹکارے کا ذریعہ بنے گا ۔","",{"u2":"طلحہ بن یحییٰ نے ابوبردہ سے اور انہوں نے حضرت ابوموسیٰ رضی اللہ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب قیامت کا دن ہو گا تو اللہ تعالیٰ (ایک مرحلے پر) ہر مسلمان کو ایک یہودی یا نصرانی عطا کر دے گا، پھر فرمائے گا: یہ جہنم سے تمہارے لیے چھٹکارے کا ذریعہ بنے گا۔\""}],[7067,"عفان بن مسلم نے ہمیں حدیث بیان کی ، کہا : ہمیں ہمام نے قتادہ سے حدیث بیان کی کہ عون ( بن عبداللہ ) اور سعید بن ابی بردہ نے انہیں حدیث بیان کی ، وہ دونوں ابو بردہ کے سامنے موجود تھے جب وہ سیدنا عمر بن عبدالعزیز کو اپنے والد سے حدیث بیان کر رہے تھے ، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" جو مسلمان بھی فوت ہوتا ہے اللہ تعالی اس کی جگہ پر ایک یہودی یا ایک نصرانی کو دوزخ میں داخل کر دیتا ہے ۔ \" کہا : عمر بن عبدالعزیز نے سیدنا ابوبُردہ کو تین بار اس اللہ کی قسم دی جس کے سوا کوئی عبادت کے لائق نہیں کہ واقعی ان کے والد نے انہیں رسول اللہ صلی اللہ علیہ وسلم سے یہ حدیث بیان کی تھی ۔ انہوں نے ان ( عمر بن عبدالعزیز ) کے سامنے قسم کھائی ۔ ( قتادہ نے ) کہا : سعید نے مجھ سے یہ بیان نہیں کیا کہ انہوں نے ان سے قسم لی اور نہ انہوں نے عون کی ( بتائی ہوئی ) بات پر کوئی اعتراض کیا ۔","",{"u2":"عفان بن مسلم نے ہمیں حدیث بیان کی، کہا: ہمیں ہمام نے قتادہ سے حدیث بیان کی کہ عون (بن عبداللہ) اور سعید بن ابی بردہ نے انہیں حدیث بیان کی، وہ دونوں ابو بردہ کے سامنے موجود تھے جب وہ حضرت عمر بن عبدالعزیز کو اپنے والد سے حدیث بیان کر رہے تھے، انہوں نے نبی صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا: \"جو مسلمان بھی فوت ہوتا ہے اللہ تعالیٰ اس کی جگہ پر ایک یہودی یا ایک نصرانی کو دوزخ میں داخل کر دیتا ہے۔\" کہا: عمر بن عبدالعزیز نے حضرت ابوبُردہ کو تین بار اس اللہ کی قسم دی جس کے سوا کوئی عبادت کے لائق نہیں کہواقعی ان کے والد نے انہیں رسول اللہ صلی اللہ علیہ وسلم سے یہ حدیث بیان کی تھی۔ انہوں نے ان (عمر بن عبدالعزیز) کے سامنے قسم کھائی۔ (قتادہ نے) کہا: سعید نے مجھ سے یہ بیان نہیں کیا کہ انہوں نے ان سے قسم لی اور نہ انہوں نے عون کی (بتائی ہوئی) بات پر کوئی اعتراض کیا۔"}],[7068,"عبدالصمد بن عبدالوارث سے روایت ہے ، کہا : ہمیں ہمام نے خبر دی ، انہوں نے کہا : ہمیں قتادہ نے اسی سند کے ساتھ عفان کی حدیث کے مانند حدیث بیان کی اور ( عون بن عبداللہ کی نسبت اس کے دادا کی طرف کرتے ہوئے ) کہا : عون بن عتبہ ۔","",{"u2":"عبدالصمد بن عبدالوارث سے روایت ہے، کہا: ہمیں ہمام نے خبر دی، انہوں نے کہا: ہمیں قتادہ نے اسی سند کے ساتھ عفان کی حدیث کے مانند حدیث بیان کی اور (عون بن عبداللہ کی نسبت اس کے دادا کی طرف کرتے ہوئے) کہا: عون بن عتبہ۔"}],[7069,"(ابوروح ) حرمی بن عمارہ نے کہا : ہمیں شداد ابو طلحہ راسبی نے غیلان بن جریر سے حدیث بیان کی ، انہوں نے ابو بردہ سے ، انہوں نے اپنے والد ( سیدنا ابو موسی رضی اللہ عنہ ) سے اور انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" قیامت کے دن مسلمانوں میں سے کچھ لوگ پہاڑوں جیسے ( بڑے بڑے ) گناہ لے کر آئیں گے ، اللہ تعالی ان کے لیے وہ گناہ بخش دے گا ، اور جہاں تک میں سمجھتا ہوں ، وہ ان ( گناہوں ) کو یہود اور نصاری پر ڈال دے گا ۔ \"\" ابو روح نے کہا : مجھے معلوم نہیں کہ یہ شک کس ( راوی ) کی طرف سے ہے ۔ سیدنا ابو بردہ نے کہا : میں نے یہ حدیث عمر بن عبدالعزیز کو بیان کی ، انہوں نے کہا : کیا تمہارے والد نے تمہیں یہ حدیث نبی صلی اللہ علیہ وسلم سے بیان کی تھی؟ میں نے کہا : ہاں ۔","",{"u2":"(ابوروح) حرمی بن عمارہ نے کہا: ہمیں شداد ابو طلحہ راسبی نے غیلان بن جریر سے حدیث بیان کی، انہوں نے ابو بردہ سے، انہوں نے اپنے والد (حضرت ابو موسی رضی اللہ عنہ) سے اور انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"قیامت کے دن مسلمانوں میں سے کچھ لوگ پہاڑوں جیسے (بڑے بڑے) گناہ لے کر آئیں گے، اللہ تعالیٰ ان کے لیے وہ گناہ بخش دے گا، اور جہاں تک میں سمجھتا ہوں، وہ ان (گناہوں) کو یہود اور نصاری پر ڈال دے گا۔\"\nابو روح نے کہا: مجھے معلوم نہیں کہ یہ شک کس (راوی) کی طرف سے ہے۔\nحضرت ابو بردہ نے کہا: میں نے یہ حدیث عمر بن عبدالعزیز کو بیان کی، انہوں نے کہا: کیا تمہارے والد نے تمہیں یہ حدیث نبی صلی اللہ علیہ وسلم سے بیان کی تھی؟ میں نے کہا: ہاں۔"}],[7070,"قتادہ نے صفوان بن محرز سے روایت کی کہ ایک شخص نے سیدنا ابن عمر رضی اللہ عنہ سے پوچھا : آپ نے نبی صلی اللہ علیہ وسلم سے نجوی ( مومن سے اللہ کی سرگوشی ) کے متعلق کس طرح سنا تھا؟ انہوں نے کہا : میں نے آپ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا : \" مومن کو قیامت کے دن اس کے رب عزوجل کے قریب کیا جائے گا ، حتی کہ اللہ تعالی اس پر اپنا پردہ ڈال دے گا ( تاکہ کوئی اور اس کے راز پر مطلع نہ ہو ) ، پھر اس سے اس کے گناہوں کا اقرار کرائے گا اور فرمائے گا : کیا تو ( ان سب گناہوں کو ) پہچانتا ہے؟ وہ کہے گا : میرے رب! میں ( ان سب گناہوں کو ) پہچانتا ہوں ۔ ( اللہ تعالی ) فرمائے گا : میں نے دنیا میں تم پر ( رحم کرتے ہوئے ) ان گناہوں کو چھپا لیا تھا اور آج ( تم پر رحم کرتے ہوئے ) تمہارے لیے ان سب کو معاف کرتا ہوں ، پھر اسے ( محض ) اس کی نیکیوں کا صحیفہ پکڑا دیا جائے گا اور رہے کفار اور منافقین تو ساری مخلوقات کے سامنے بلند آواز سے انہیں کہا جائے گا : یہی ہیں جنہوں نے اللہ پر جھوٹ باندھا ۔","",{"u2":"قتادہ نے صفوان بن محرز سے روایت کی کہ ایک شخص نے حضرت ابن عمر رضی اللہ عنہ سے پوچھا: آپ نے نبی صلی اللہ علیہ وسلم سے نجویٰ (مومن سے اللہ کی سرگوشی) کے متعلق کس طرح سنا تھا؟ انہوں نے کہا: میں نے آپ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا: \" مومن کو قیامت کے دن اس کے رب عزوجل کے قریب کیا جائے گا، حتی کہ اللہ تعالیٰ اس پر اپنا پردہ ڈال دے گا (تاکہ کوئی اور اس کے راز پر مطلع نہ ہو)، پھر اس سے اس کے گناہوں کا اقرار کرائے گا اور فرمائے گا: کیا تو (ان سب گناہوں کو) پہچانتا ہے؟ وہ کہے گا: میرے رب! میں (ان سب گناہوں کو) پہچانتا ہوں۔ (اللہ تعالیٰ) فرمائے گا: میں نے دنیا میں تم پر (رحم کرتے ہوئے) ان گناہوں کو چھپا لیا تھا اور آج (تم پر رحم کرتے ہوئے) تمہارے لیے ان سب کو معاف کرتا ہوں، پھر اسے (محض) اس کی نیکیوں کا صحیفہ پکڑا دیا جائے گا اور رہے کفار اور منافقین تو ساری مخلوقات کے سامنے بلند آواز سے انہیں کہا جائے گا: یہی ہیں جنہوں نے اللہ پر جھوٹ باندھا۔\""}],[7071,"عُقیل بن ابن شہاب سے یونس کی سند کے ساتھ زہری سے بالکل اسی طرح روایت کی ۔","",{"u2":"یونس نے مجھے ابن شہاب سے خبر دی، کہا: پھر رسول اللہ صلی اللہ علیہ وسلم غزوہ تبوک لڑنے گئے اور آپ کا ارادہ روم اور شام کے عرب نصرانیوں کا مقابلہ کرنے کا تھا۔\nابن شہاب نے کہا: مجھے عبدالرحمٰن بن عبداللہ بن کعب بن مالک نے خبر دی کہ عبداللہ بن کعب حضرت کعب رضی اللہ عنہ کے نابینا ہونے کے بعد حضرت کعب رضی اللہ عنہ کے بیٹوں میں سے وہی حضرت کعب رضی اللہ عنہ کا ہاتھ پکڑنے اور انہیں (ہر ضرورت کے لیے) لانے لے جانے والے تھے۔ کہا: میں نے حضرت کعب بن مالک رضی اللہ عنہ سے ان کی وہ حدیث سنی تھی جب وہ غزوہ تبوک میں رسول اللہ صلی اللہ علیہ وسلم سے پیچھے رہ گئے تھے۔ کعب بن مالک رضی اللہ عنہ نے کہا: میں غزوہ تبوک کے سوا کسی جنگ میں، جو آپ صلی اللہ علیہ وسلم نے کی، کبھی رسول اللہ صلی اللہ علیہ وسلم سے پیچھے نہیں رہا۔ (ہاں) مگر میں غزوہ بدر میں بھی پیچھے رہا تھا (کیونکہ آپ صلی اللہ علیہ وسلم سب کو ساتھ لے کر تشریف نہیں لے گئے تھے اس لیے) آپ صلی اللہ علیہ وسلم نے کسی شخص پر، جو اس جنگ میں شریک نہیں ہوا، عتاب نہیں فرمایا تھا۔ (بدر کے موقع پر) رسول اللہ صلی اللہ علیہ وسلم اور مسلمان قریش کے تجارتی قافلے (کا سامنا کرنے) کے ارادے سے نکلے تھے، یہاں تک کہ اللہ نے طے شدہ وقت کے بغیر ان کی اور ان کے دشمنوں کی مڈبھیڑ کروادی۔ میں بیعت عقبہ کی رات میں آپ صلی اللہ علیہ وسلم کے ساتھ شامل تھا جب ہم سب نے اسلام قبول کرنے پر (رسول اللہ صلی اللہ علیہ وسلم کے ساتھ) معاہدہ کیا تھا۔ مجھے اس (اعزاز) کے عوض بدر میں شمولیت (کا اعزاز بھی) زیادہ محبوب نہیں، اگرچہ لوگوں میں بدر کا تذکرہ اس (بیعت) کی نسبت زیادہ ہوتا ہے۔ میں جب غزوہ تبوک کے موقع پر رسول اللہ صلی اللہ علیہ وسلم سے پیچھے رہا تھا تو میرے احوال یہ تھے کہ میں اس وقت کی نسبت، جب میں اس جنگ سے پیچھے رہا تھا، کبھی (جسمانی طور پر) زیادہ قوی اور (مالی اعتبار سے) زیادہ خوش حال نہیں رہا تھا۔ اللہ کی قسم! میرے پاس اس سے پہلے کبھی دو سواریاں اکٹھی نہیں ہوئی تھیں، یہاں تک کہ اس غزوے کے موقع پر ہی میں نے دو سواریاں اکٹھی رکھی ہوئی تھیں۔ رسول اللہ صلی اللہ علیہ وسلم نے وہ غزوہ سخت گرمی میں کیا تھا، آپ کو بہت دور کے چٹیل صحرا کا سفر درپیش تھا اور آپ کو بہت زیادہ دشمنوں کا سامنا کرنا تھا۔ آپ صلی اللہ علیہ وسلم نے مسلمانوں کے سامنے اس معاملے کو (جو انہیں درپیس تھا) اچھی طرح واضح فرما دیا تھا تاکہ وہ اپنی جنگ کی (پوری) تیاری کر لیں۔ آپ صلی اللہ علیہ وسلم نے انہیں ان کی سمت سے بھی آگاہ فرما دیا تھا جدھر سے آپ جانا چاہتے تھے۔ رسول اللہ صلی اللہ علیہ وسلم کے ہمراہ کثیر تعداد میں مسلمان تھے۔ کسی محفوظ رکھنے والی کی کتاب میں ان کے نام جمع (اکٹھے لکھے ہوئے) نہیں تھے۔۔ ان کی مراد رجسٹر سے تھی۔۔\nحضرت کعب رضی اللہ عنہ نے کہا: ایسے لوگ کم تھے جو غائب رہنا چاہتے تھے، جو سمجھتے تھے کہ ان کی یہ بات اس وقت تک مخفی رہے گی جب تک ان کے بارے میں اللہ عزوجل کی وحی نازل نہیں ہوتی اور رسول اللہ صلی اللہ علیہ وسلم نے یہ غزوہ اس وقت کیا جب پھل اور (درختوں پر پتے زیادہ ہو جانے کی بنا پر) سائے اچھے ہو گئے تھے۔ (ہر آدمی کا دل چاہتا تھا کہ آرام سے گھر میں رہے، دن کو سائے کے نیچے آرام کرے او تازہ پھل کھائے۔) میرا بھی دل اسی طرف زیادہ مائل تھا۔ رسول اللہ صلی اللہ علیہ وسلم اور آپ کے ساتھ مسلمان (جہاد کی) تیار میں لگ گئے۔ میں صبح کو نکلتا کہ میں بھی ان کے ساتھ تیاری کروں اور واپس آتا تو میں نے کچھ بھی نہ کیا ہوتا۔ میں دل میں کہتا: میں چاہوں تو اس کی بھرپور تیاری کر سکتا ہوں، یہی کیفیت مجھے مسلسل آگے سے آگے گرتی گئی اور لوگ مسلسل سنجیدہ سے سنیدہ ہوتے گئے، یہاں تک کہ رسول اللہ صلی اللہ علیہ وسلم صبح سویرے روانہ ہو گئے، مسلمان آپ کے ہمراہ تھے اور میں اپنی کوئی بھی تیاری مکمل نہ کر پایا تھا۔ میں پھر صبح کے وقت نکلا اور واپس آیا تو بھی کچھ نہ کر پایا تھا اور میری یہی کیفیت تسلسل سے آگے چلتی رہی، یہاں تک کہ (تیاری میں پیچھے رہ جانے والے) مسلمان جلد از جلد جانے لگے اور جنہوں نے جنگ میں حصہ لینا تھا وہ بہت آگے نکل گئے، اس پر میں نے ارادہ کیا کہ نکل پڑوں اور لوگوں سے جا ملوں۔ اے کاش! میں ایسا کر لیتا لیکن یہ (بھی) میرے مقدر میں نہ ہوا اور میری یہ حالت ہو گئی کہ رسول اللہ صلی اللہ علیہ وسلم کی روانگی کے بعد جب میں لوگوں میں نکلتا تو میں اس بات پر سخت غمگین ہوتا کہ مجھے (اپنے لیے اپنے جیسے کسی شخص کی) کوئی مثال نہیں ملتی (جس کے نمونے پر میں نے عمل کیا ہو)، سوائے کسی ایسے انسان کے جس پر نفاق کی تہمت تھی یا ضعفاء، میں کوئی شخص جسے اللہ کی طرف سے معذور قرار دیا گیا تھا۔رسول اللہ صلی اللہ علیہ وسلم نے اس وقت تک میرا ذکر نہیں کیا، یہاں تک کہ آپ تبوک پہنچے تو آپ نے جب آپ لوگوں کےساتھ تبوک میں بیٹھے ہوئے تھے، فرمایا: \"کعب بن مالک نے کیا کیا؟\" تو بنو سلمہ کے ایک شخص نے کہا: اسے اس کی دو (خوبصورت) چادروں اور اپنے دونوں پہلوؤں کو دیکھنے (کے کام) نے روک لیا ہے۔ حضرت معاذ بن جبل رضی اللہ عنہ نے اس سے کہا: تم نے بری بات کہی، اللہ کے رسول! اللہ کی قسم! ہم ان کے بارے میں اچھائی کے سوا اور کچھ نہیں جانتے۔ رسول اللہ صلی اللہ علیہ وسلم نے سکوت اختیار فرما لیا۔ آپ اسی کیفیت میں تھے کہ آپ نے سفید لباس میں ملبوس ایک شخص کو دیکھا جس کے (چلنے کے) سبب سے (صحرا میں نظر آنے والا) سراب ٹوٹتا جا رہا تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تجھے ابوخیثمہ (انصاری) ہونا چاہئے۔\" تو وہ ابوخیثمہ انصاری رضی اللہ عنہ ہی تھے اور یہ وہی ہیں جنہوں نے ایک صاع کھجور کا صدقہ دیا تھا جب منافقوں نے انہیں طعنہ دیا تھا (اور کہا تھا: اللہ اس کے ایک صاع کا محتاج نہیں۔)\nکعب بن مالک رضی اللہ عنہ نے کہا: جب مجھے یہ خبر پہنچی کہ رسول اللہ صلی اللہ علیہ وسلم نے تبوک سے واپسی کا رخ فرما لیا ہے تو مجھے میرے غم اور افسوس نے (شدت سے) آ لیا، میں جھوٹے عذر سوچنے اور (دل میں) کہنے لگا: میں کل کو آپ کی ناراضی سے کیسے نکلوں گا؟ میں اپنے گھر والوں میں سے ہر رائے رکھنے والے فرد سے (بھی) مدد لینے لگا۔ جب مجھ سے کہا گیا: رسول اللہ صلی اللہ علیہ وسلم پہنچنے والے ہیں تو باطل (بہانے تراشنے) کا خیال میرے دل سے زائل ہو گیا، یہاں تک کہ میں نے جان لیا کہ میں کسی چیز کے ذریعے سے آپ (کی ناراضی) سے نہیں بچ سکتا تو میں نے آپ کے سامنے سچ کہنے کا تہیہ کر لیا۔ رسول اللہ صلی اللہ علیہ وسلم کی تشریف آوری صبح کے وقت ہوئی۔ آپ صلی اللہ علیہ وسلم جب سفر سے آتے تو مسجد سے آغاز فرماتے، اس میں دو رکعتیں پڑھتے، پھر لوگوں (سے ملاقات) کے لیے بیٹھ جاتے۔ جب آپ نے ایسا کر لیا تو پیچھے رہ جانے والے آپ کے پاس آنے لگے۔ انہوں نے (آ کر) عذر پیش کرنا اور آپ کے سامنے قسمیں کھانا شروع کر دیں، وہ اَسی سے کچھ زائد آدمی تھے، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے ان کے ظاہرا (کیے گئے عذروں) کو قبول فرمایا، ان سے آئندہ (اطاعت) کی بیعت لی، اللہ سے ان کی مغفرت کی دعا کی اور ان کے باطن کو اللہ کے حوالے کر دیا، یہاں تک کہ میں حاضر ہوا۔ جب میں نے سلام کیا تو آپ صلی اللہ علیہ سلم تو آپ صلی اللہ علیہ وسلم اس طرح مسکرائے جیسے آپ کو غصہ دلایا گیا ہو، پھر آپ نے فرمایا: \"آؤ۔\" میں چلتا ہوا آیا، یہاں تک کہ آپ کے سامنے (آکر) بیٹھ گیا تو آپ نے مجھ سے فرمایا: \"تمہیں کس بات نے پیچھے رکھا؟ کیا تم نے اپنی سواری حاصل کر نہیں لی تھی؟\" کہا: میں نے عرض کی: اللہ کے رسول! بے شک، اللہ کی قسم! اگر میں آپ کے سوا پوری دنیا میں سے کسی بھی اور کے سامنے بیٹھا ہوتا تو میں دیکھ لیتا (ایسا عذر تراش لیتا) کہ میں جلد ہی اس کی ناراضی سے نکل جاتا، مجھے (اپنے حق میں) دلیلیں دینے کا ملکہ ملا ہے، لیکن اللہ کی قسم! میں جانتا ہوں کہ آج اگر میں آپ سے کوئی جھوٹی بات کہہ دوں جس سے آپ مجھ پر راضی ہو جائیں تو جلد ہی اللہ تعالیٰ آپ کو مجھ پر ناراض کر دے گا اور اگر میں آپ سے سچی بات کہہ دوں جس سے آپ مجھ پر ناراض ہو جائیں تو کل مجھے اس میں اللہ کی طرف سے اچھے انجام کی پوری امید ہے۔ اللہ کی قسم! میرے پاس (پیچھے رہ جانے کا) کوئی عذر نہیں تھا۔ اللہ کی قسم! میں جب آپ کا ساتھ دینے سے پیچھے رہا ہوں تو اس سے پہلے کبھی (جسمانی طور پر) اس سے بڑھ کر قوی اور (مالی طور پر) اس سے زیادہ خوش حال نہ تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہ شخص جس نے سچ کہا ہے، (اب) تم اٹھ جاؤ (اور انتظار کرو) یہاں تک کہ اللہ تمہارے بارے میں فیصلہ فرما دے۔\" میں اٹھ گیا، بنوسلمہ کے کچھ لوگ بھی جوش میں کھڑے ہو کر میرے پیچھے آئے اور مجھ سے کہنے لگے: تمہارے بارے میں ہم نہیں جانتے کہ اس سے پہلے تم نے کوئی گناہ کیا ہے، کیا تم اس سے بھی عاجز رہ گئے کہ رسول اللہ صلی اللہ علیہ وسلم کے سامنے کوئی عذر پیش کر دیتے جس طرح دوسرے پیچھے رہنے والے لوگوں کے عذر پیش کیے ہیں۔ تمہارے گناہ کے معاملے میں تمہارے لیے رسول اللہ صلی اللہ علیہ وسلم کا استغفار فرمانا کافی ہو جاتا۔\n(حضرت کعب بن مالک رضی اللہ عنہ نے) کہا: اللہ کی قسم! وہ مسلسل مجھ سے سخت ناراضی کا اظہار اور ملامت کرتے رہے، یہاں تک کہ میں نے یہ ارادہ کیا کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس واپس ہو جاؤں اور خود کو جھٹلا دوں۔ کہا: پھر میں نے ان سے کہا: کیا میرے ساتھ کسی اور نے بھی اس صورت حال کا سامنا کیا ہے؟ انہوں نے کہا: ہاں، تمہارے ساتھ دو اور آدمیوں نے بھی اسی صورتِ حال کا سامنا کیا ہے، ان سے بھی وہی کہا گیا ہے جو تم سے کہا گیا ہے۔ کہا: میں نے پوچھا: وہ دونوں کون ہیں؟ انہوں نے کہا: وہ مرارہ بن ربیعہ عامری اور ہلال بن امیہ واقفی ہیں۔ انہوں نے میرے سامنے دو نیک انسانوں کا نام لیا جو بدر میں شریک ہوئے تھے۔ ان (دونوں کی صورت) میں ایک قابل عمل نمونہ موجود تھا۔ کہا: جب انہوں نے میرے سامنے ان دونوں کا ذکر کیا تو میں (رسول اللہ صلی اللہ علیہ وسلم کے پاس واپس جانے کے بجائے اسی پر ڈٹا رہا۔)\nکہا: اور رسول اللہ صلی اللہ علیہ وسلم نے پیچھے رہ جانے والوں میں سے صرف ہم تینوں کو مخاطب کرتے ہوئے سب مسلمانوں کو ہم سے بات کرنے سے منع فرما دیا۔\nکہا: لوگ ہم سے اجتناب برتنے لگے، یا کہا: وہ ہمارے لیے (بالکل ہی) بدل گئے، یہاں تک کہ میرے دل (کے خیال) میں یہ زمین میرے لیے اجنبی بن گئی، یہ اب وہ زمین نہ رہی تھی جسے میں پہچانتا تھا۔ ہم پچاس راتیں اسی حالت میں رہے۔ جہاں تک میرے دونوں ساتھیوں کا تعلق ہے تو وہ دونوں بے بس ہو کر روتے ہوئے گھروں میں بیٹھ گئے۔ میں ان دونوں کی نسبت زیادہ جوان اور دلیر تھا، اس لیے میں (گھر سے) نکلتا، نماز میں شامل ہوتا اور بازاروں میں گھومتا اور مجھ سے بات کوئی نہ کرتا۔ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس بھی، جب آپ نماز کے بعد مجلس میں ہوتے، آتا اور سلام کرتا۔ میں اپنے دل میں سوچتا: کیا آپ نے سلام کے جواب میں لب مبارک ہلائے تھے یا نہیں؟ پھر میں آپ کے قریب (کھڑے ہو کر) نماز پڑھتا اور چور نظروں سے آپ کی طرف دیکھتا، جب میں اپنی نماز کی طرف متوجہ ہوتا تو آپ میری طرف دیکھتے اور جب آپ کی طرف متوجہ ہوتا تو آپ مجھ سے رخ مبارک پھیر لیتے، یہاں تک کہ جب میرے ساتھ مسلمانوں کی بے اعتنائی (کی مدت) طویل ہو گئی تو (ایک دن) میں چل پڑا اور (جا کر) ابوقتادہ رضی اللہ عنہ کے باغ کی دیوار پھلانگی (اور باغ میں چلا گیا۔) اور وہ میرے چچا کا بیٹا اور لوگوں میں سے مجھے سب سے زیادہ پیارا تھا۔ میں نے اسے سلام کیا تو اللہ کی قسم! اس نے مجھے سلام کا جواب تک نہ دیا۔ میں نے اس سے کہا: ابوقتادہ! میں تمہیں اللہ کا واسطہ دیتا (ہوں اور پوچھتا) ہوں: تم جانتے ہو نا کہ میں اللہ اور اس کے رسول صلی اللہ علیہ وسلم سے محبت کرتا ہوں؟ کہا: وہ خاموش رہے۔ میں نے دوبارہ پوچھا اور اسے اللہ کا واسطہ دیا تو (پھر بھی) وہ خاموش رہے۔ میں نے (تیسری بار) پھر سے پوچھا اور اللہ کا واسطہ دیا تو انہوں نے کہا: اللہ اور اس کا رسول صلی اللہ علیہ وسلم زیادہ جاننے والے ہیں۔ اس پر میری آنکھوں میں آنسو آ گئے، میں واپس مڑا، یہاں تک کہ (پھر سے) دیوار پھلانگی (اور باغ سے نکل گیا۔)\nایک روز میں مدینہ کے بازار میں چلا جا رہا تھا تو میں نے اہل شام کے نبطیوں میں سے ایک نبطی (سامی، زمیندار) کو جو کھانے کی اجناس لے کر پیچنے کے لیے مدینہ آیا ہوا تھا، دیکھا، وہ کہتا پھر رہا تھا: کوئی ہے جو مجھے کعب بن مالک کا پتہ بتا دے۔ لوگوں نے اس کے سامنے میری طرف اشارے کرنے شروع کر دئیے۔ یہاں تک کہ وہ میرے پاس آیا اور شاہ غسان کا ایک خط میرے حوالتےے کر دیا۔ میں لکھنا (پڑھنا) جانتا تھا۔ میں نے وہ خط پڑھا تو اس میں لکھا تھا: سلام کے بعد، ہمیں یہ خبر پہنچی ہے کہ تمہارے صاحب (رسول اللہ صلی اللہ علیہ وسلم) نے تمہارے ساتھ بہت برا سلوک کیا ہے اور اللہ نے تمہیں ذلت اٹھانے اور ضائع ہو جانے والی جگہ میں (محبوس کر کے) نہیں رکھ دیا، لہذا تم ہمارے ساتھ آ ملو، ہم تمہارے ساتھ بہت اچھا سلوک کریں گے، کہا: جب میں نے وہ خط پڑھا تو (دل میں) کہا: یہ ایک اور آزمائش ہے۔ میں نے اسے لے کر ایک تندور کا رخ کیا اور اس خط کو اس میں جلا دیا، یہاں تک کہ پچاس میں سے چالیس راتیں گزر گئیں اور وحی موخر ہو گئی تو اچانک میرے پاس رسول اللہ صلی اللہ علیہ وسلم کا قاصد آیا اور کہا: رسول اللہ صلی اللہ علیہ وسلم تمہیں حکم دیتے ہیں کہ تم اپنی بیوی سے بھی الگ ہو جاؤ۔ کہا: میں نے پوچھا: کیا اسے طلاق دے دوں یا کیا کروں؟ اس نے کہا: نہیں، بس الگ رہو۔ اس کے قریب نہ جاؤ، کہا: آپ صلی اللہ علیہ وسلم نے میرے دونوں ساتھیوں کی طرف بھی یہی پیغام بھیجا۔ کہا: میں نے اپنی بیوی سے کہا: تم اپنے گھر والوں کے پاس چلی جاؤ اور اس وقت تک انہی کے ساتھ رہو۔ جب تک اللہ تعالیٰ اس معاملے کا فیصلہ نہ فرما دے۔ کہا: ہلال بن امیہ رضی اللہ عنہ کی بیوی رسول اللہ صلی اللہ علیہ وسلم کے پاس آئی اور عرض کی: اللہ کے رسول! ہلال بن امیہ اپنا خیال نہ رکھ سکنے والا بوڑھا انسان ہے، اس کے پاس کوئی خادم بھی نہیں، کیا آپ اس بات کو بھی ناپسند کرتے ہیں کہ میں ان کی خدمت کروں؟ فرمایا: \"نہیں، لیکن وہ تمہارے ساتھ قربت ہرگز اختیار نہ کرے۔\" انہوں نے کہا: اللہ جانتا ہے وہ تو کسی چیز کی طرف حرکت بھی نہیں کر سکتے۔ جب سے ان کا یہ معاملہ ہوا ہے اس روز سے آج تک مسلسل روتے ہی رہتے ہیں۔\nکہا: میرے گھر والوں میں سے بعض نے مجھ سے کہا: (اچھا ہوا) اگر تم بھی اپنی بیوی کے بارے میں رسول اللہ صلی اللہ علیہ وسلم سے اجازت لے لو، آپ صلی اللہ علیہ وسلم نے ہلال بن امیہ رضی اللہ عنہ کی بیوی کو اجازت دے دی ہے کہ وہ ان کی خدمت کرتی رہیں۔ کہا: میں نے جواب دیا: میں اس معاملے میں رسول اللہ صلی اللہ علیہ وسلم سے اجازت نہیں مانگوں گا، مجھے معلوم نہیں کہ جب میں اس کے بارے میں آپ سے اجازت کی درخواست کروں تو آپ کیا فرمائیں، میں ایک جواب آدمی ہوں، (اپنا خیال خود رکھ سکتا ہوں) کہا: میں دس راتیں اسی عالم میں رہا اور جب سے ہمارے ساتھ بات چیت کو ممنوع قرار دیا گیا اس وقت سے پچاس راتیں پوری ہو گئیں۔کہا: پھر میں نے پچاسویں رات کی صبح اپنے گھروں میں سے ایک گھر کی چھت پر فجر کی نماز ادا کی اور میں، اس کے بعد اللہ تعالیٰ نے ہماری جس حالت کا ذکر فرمایا، اسی حالت میں کہ مجھ پر زمین اپنی وسعتوں کے باوجود تنگ تھی اور میرا دل بھی مجھ پر تنگ پڑ چکا تھا، بیٹھا ہوا تھا کہ میں نے ایک پکارنے والے کی آواز سنی جو وہ سلع پر چڑھ کر اپنی بلند ترین آواز میں کہہ رہا تھا: کعب بن مالک! خوش ہو جاؤ۔ کہا: میں (اسی وقت) سجدے میں گر گیا اور مجھے پتہ چل گیا کہ (تنگی کے بعد) کشادگی (کی نوید) آ گئی ہے۔\nکہا: اور رسول اللہ صلی اللہ علیہ وسلم نے جب صبح کی نماز پڑھی تو آپ نے لوگوں میں ہم پر اللہ کی توجہ اور عنایت (توبہ قبول کرنے) کا اعلان فرما دیا۔ لوگ ہمیں خوش خبری سنانے کے لیے چل پڑے، میرے دونوں ساتھیوں کی طرف بھی خوش خبری سنانے والے رونہ ہو گئے اور میری طرف (آنے کے لیے) ایک شخص نے گھوڑا دوڑایا اور (میرے قبیلے) اسلم میں سے ایک شخص نے خود میری طرف دوڑ لگائی اور پہاڑ پر چڑھ گیا، تو آواز گھوڑے سے زیادہ تیز رفتار تھی (پہلے پہنچ گئی) جب وہ شخص میرے پاس پہنچا جس کی خوش خبری دینے کی آواز میں نے سنی تھی تو میں نے اپنے دونوں کپڑے اتار کر اس کی خوش خبری کے بدلے اسے پہنا دیے۔ اللہ کی قسم! اس دن دو کپڑوں کے سوا میری ملکیت میں (پہننے کی) اور کوئی چیز نہ تھی۔ میں نے دو کپڑے عاریتا لے کر انہیں پہن لیا اور رسول اللہ صلی اللہ علیہ وسلم (سے ملاقات) کا قصد لے کر چل پڑا، لوگ گروہ در گروہ مجھ سے ملتے تھے، توبہ (قبول ہونے) پر مجھے مبارک باد دیتے تھے اور کہتے تھے: تم پر اللہ کی نظر عنایت تمہیں مبارک ہو! یہاں تک کہ میں مسجد میں داخل ہوا تو (دیکھا کہ) رسول اللہ صلی اللہ علیہ وسلم مسجد میں تشریف فرما تھے اور لوگ آپ کے اردگرد بیٹھے ہوئے تھے، (ان میں سے) طلحہ بن عبیداللہ رضی اللہ عنہ اٹھ کر میری طرف لپکے، میرے ساتھ مصافحہ کیا اور مبارکباد دی۔ اللہ کی قسم! مہاجرین میں سے ان کے سوا کوئی اور (میرے استقبال کے لیے اس طرح) نہ اٹھا۔\n(عبداللہ بن کعب نے) کہا: کعب رضی اللہ عنہ کے بارے میں یہ بات کبھی نہ بھولتے تھے (انہوں نے اس کو ہمیشہ یاد رکھا۔)\nحضرت کعب رضی اللہ عنہ نے کہا: جب میں نے رسول اللہ صلی اللہ علیہ وسلم کو سلام کیا تو آپ نے فرمایا، جبکہ آپ کا چہرہ مبارک خوشی سے دمک رہا تھا اور آپ یہ فرما رہے تھے: \"ماں کے پیٹ سے جنم لینے کے وقت سے جو بہترین دن تم پر گزر رہا ہے، تمہیں اس کی خوش خبری ہو!\" کہا: میں نے عرض کی: اللہ کے رسول! (یہ بشارت) آپ کی طرف سے ہے یا اللہ کی طرف سے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"نہیں، بلکہ اللہ کی طرف سے ہے۔\" اور جب رسول اللہ صلی اللہ علیہ وسلم کو بہت خوشی حاصل ہوتی تو آپ کا چہرہ مبارک اس طرح چمک اٹھتا تھا جیسے آپ کا چہرہ مبارک چاند کا ایک ٹکڑا ہو۔ کہا: اور ہمیں یہ بات اچھی طرح معلوم تھی۔\nکہا: جب میں آپ کے روبرو بیٹھ گیا تو میں نے عرض کی: اللہ کے رسول! میری توبہ میں یہ بھی ہے کہ میں اللہ اور اس کے رسول صلی اللہ علیہ وسلم کے سامنے صدقہ پیش کرنے کے لیے اپنے پورے مال سے دستبردار ہو جاؤں۔ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اپنا کچھ مال اپنے پاس رکھو، یہ بات تمہارے حق میں بہتر ہے۔\" میں نے عرض کی: تو میں اپنا وہ حصہ جو مجھے خیبر سے ملا، اپنے پاس رکھ لیتا ہوں (حضرت کعب رضی اللہ عنہ نے) کہا: میں نے عرض کی: اللہ کے رسول! اللہ نے مجھے صرف اور صرف سچائی کی بنا پر نجات عطا فرمائی اور یہ بات بھی میری توبہ کا حصہ ہے کہ جب تک میری زندگی ہے، سچ کے بغیر کبھی کوئی بات نہیں کہوں گا۔ کہا: اللہ کی قسم! میں مسلمانوں میں سے کسی کو نہیں جانتا جسے اس وقت سے لے کر، جب میں نے رسول اللہ صلی اللہ علیہ وسلم کے سامنے سچ بولا تھا، آج تک اللہ تعالیٰ نے اس سے بہتر انداز میں نوازا ہو، جس طرح مجھے نوازا۔ اللہ کی قسم! جب میں نے رسول اللہ صلی اللہ علیہ وسلم سے یہ بات عرض کی، اس وقت سے لے کر آج تک کوئی ایک جھوٹ بولنے کا ارادہ تک نہیں کیا اور میں امید رکھتا ہوں کہ میری بقیہ زندگی میں بھی اللہ مجھے (جھوٹ سے) محفوظ رکھے گا۔\nکہا: اس پر اللہ تعالیٰ نے (یہ آیات) نازل فرمائیں: \"اللہ تعالیٰ نے نظر عنایت فرمائی نبی صلی اللہ علیہ وسلم اور مہاجرین اور انصار پر جنہوں نے تنگی کی گھڑی میں آپ کا اتباع کیا\" حتی کہ آپ یہاں پہنچ گئے: \"بےشک وہ انتہائی مہربان اور رحم فرمانے والا ہے۔ اور ان تین (افراد) پر بھی جو پیچھے کر دیے گئے تھے یہاں تک کہ زمین اپنی وسعت کے باوجود ان پر تنگ ہو گئی تھی اور خود ان کے اپنے دل ان پر تنگ پڑ گئے تھے اور انہیں یقین ہو گیا تھا کہ اللہ سے پناہ ملنے کی، اس کے اپنے سوا، کہیں اور جگہ نہ تھی، پھر اس نے ان کی طرف نظر عنایت کی کہ وہ اس کی طرف متوجہ ہوں، یقینا اللہ ہی ہے بہت نظر عنایت کرنے والا ہمیشہ رحم کرنے والا\" سے لے کر اس ٹکڑے تک: \"اے ایمان والو! اللہ کے سامنے تقویٰ اختیار کرو اور سچ بولنے والوں میں شامل ہو جاؤ۔\"\nحضرت کعب رضی اللہ عنہ نے کہا: اللہ کی قسم! اللہ تعالیٰ نے مجھے اسلام کا راستہ دکھانے کے بعد، مجھ پر کبھی کوئی ایسا انعام نہیں کیا جس کی میرے دل میں اس سچ سے زیادہ قدر ہو جو میں نے رسول اللہ صلی اللہ علیہ وسلم کے سامنے بولا تھا، (یعنی) اس بات کی کہ میرے ساتھ ایسا نہ ہوا کہ میں آپ کے سامنے جھوٹ بولتا اور ان لوگوں کی طرح ہلاک ہو جاتا جنہوں نے جھوٹ بولا تھا۔ جن لوگوں نے جھوٹ بولا تھا، اللہ تعالیٰ نے جب وحی نازل فرمائی تو جتنی (کبھی) کسی شخص کی مذمت کی، ان کی اس سے کہیں زیادہ مذمت فرمائی۔ اللہ تعالیٰ نے ارشاد فرمایا: \"یہ لوگ جب تم (مدینہ میں) ان کے پاس واپس پہنچو گے تو ضرور اللہ کی قسمیں کھائیں گے تاکہ تم ان سے صرف نظر کر لو، لہذا تم ان سے رخ پھیر لو، یہ (سرتاپا) گندگی ہیں اور جو کچھ یہ کرتے رہے اس کی جزا کے طور پر ان کا ٹھکانا جہنم ہے۔ یہ تمہارے سامنے قسمیں کھاتے ہیں تاکہ تم لوگ ان سے راضی ہو جاؤ، اگر تم ان سے راضی ہو بھی جاؤ تو اللہ تعالیٰ (ان) فاسق لوگوں سے کبھی راضی نہ ہو گا۔\"\nحضرت کعب رضی اللہ عنہ نے کہا: ہم تینوں کو مخاطب کر کے، ہمیں ان لوگوں کے معاملے سے پیچھے (مؤخر) کر دیا گیا تھا جنہوں نے قسمیں کھائی تھیں اور (بظاہر) وہ قسمیں قبول کر لی گئی تھیں اور رسول اللہ صلی اللہ علیہ وسلم نے ان سے (تجدید) بیعت فرمائی اور ان کے لیے مغفرت کی دعا بھی کی تھی۔ اور رسول اللہ صلی اللہ علیہ وسلم نے ہمارا معاملہ مؤخر فرما دیا تھا حتی کہ اللہ تعالیٰ نے اس کے بارے میں فیصلہ فرمایا، اسی کے متعلق اللہ عزوجل نے فرمایا: \"اور ان تینوں پر بھی نظر عنایت فرمائی جن کو پیچھے (مؤخر) کر دیا گیا تھا۔\" اللہ تعالیٰ نے ہمارے پیچھے کردیے جانے کے بارے میں جو فرمایا ہے اس سے مراد ہمارا جنگ سے پیچھے رہ جانا نہ تھا بلکہ اس شخص کی نسبت ہمیں (ہمارا معاملہ) مؤخر کر دینا اور ہمارے معاملے کے فیصلے کو بعد میں کرنا مراد تھا کہ جس نے آپ صلی اللہ علیہ وسلم کے سامنے قسمیں کھائی، معذرت کی تو آپ نے اس سے قبول کر لی۔"}],[7072,"عُقیل بن ابن شہاب سے یونس کی سند کے ساتھ زہری سے بالکل اسی طرح روایت کی ۔","",{"u2":"عُقیل بن ابن شہاب سے یونس کی سند کے ساتھ زہری سے بالکل اسی طرح روایت کی۔"}],[7074,"معقل بن عبیداللہ نے زہری سے روایت کی ، انہوں نے کہا : مجھے عبدالرحمٰن بن عبداللہ بن کعب بن مالک نے اپنے چچا عبیداللہ بن کعب سے روایت کی اور جب سیدنا کعب رضی اللہ عنہ کی آنکھیں جاتی رہیں تو وہی ان کا ہاتھ پکڑ کر ان کی رہنما کرتے تھے ۔ وہ اپنی قوم میں سب سے بڑے عالم اور رسول اللہ صلی اللہ علیہ وسلم کے صحابہ کی احادیث کے سب سے بڑے حافظ تھے ، انہوں نے کہا : میں نے اپنے والد سیدنا کعب بن مالک رضی اللہ عنہ سے سنا ، وہ ان تین لوگوں میں سے ایک تھے جن کی توبہ قبول کی گئی ، وہ حدیث بیان کرتے تھے کہ وہ دو غزووں کو چھوڑ کر کبھی کسی غزوے میں جو رسول اللہ صلی اللہ علیہ وسلم سے لڑا ، آپ سے پیچھے نہیں رہے ۔ انہوں نے ( سابقہ حدیث کی طرح ) حدیث بیان کی اور اس میں کہا : \" رسول اللہ صلی اللہ علیہ وسلم لوگوں کی بہت بڑی تعداد کے ساتھ ، جو دس ہزار سے زیادہ تھے اور کسی محفوظ رکھنے والے کے دیوان ( رجسٹر ) میں ان سب کے نام درج نہ تھے ، اس جنگ کے لیے نکلے ۔","",{"u2":"معقل بن عبیداللہ نے زہری سے روایت کی، انہوں نے کہا: مجھے عبدالرحمٰن بن عبداللہ بن کعب بن مالک نے اپنے چچا عبیداللہ بن کعب سے روایت کی اور جب حضرت کعب رضی اللہ عنہ کی آنکھیں جاتی رہیں تو وہی ان کا ہاتھ پکڑ کر ان کی رہنما کرتے تھے۔ وہ اپنی قوم میں سب سے بڑے عالم اور رسول اللہ صلی اللہ علیہ وسلم کے صحابہ کی احادیث کے سب سے بڑے حافظ تھے، انہوں نے کہا: میں نے اپنے والد حضرت کعب بن مالک رضی اللہ عنہ سے سنا، وہ ان تین لوگوں میں سے ایک تھے جن کی توبہ قبول کی گئی، وہ حدیث بیان کرتے تھے کہ وہ دو غزووں کو چھوڑ کر کبھی کسی غزوے میں جو رسول اللہ صلی اللہ علیہ وسلم سے لڑا، آپ سے پیچھے نہیں رہے۔ انہوں نے (سابقہ حدیث کی طرح) حدیث بیان کی اور اس میں کہا: \"رسول اللہ صلی اللہ علیہ وسلم لوگوں کی بہت بڑی تعداد کے ساتھ، جو دس ہزار سے زیادہ تھے اور کسی محفوظ رکھنے والے کے دیوان (رجسٹر) میں ان سب کے نام درج نہ تھے، اس جنگ کے لیے نکلے۔"}],[7075,"ابو ربیع عتکی نے مجھے حدیث بیان کی ، انہوں نے کہا : ہمیں فلیح بن سلیمان نے حدیث سنائی ، نیز ہمیں حسن بن علی حلوانی اور عبد بن حمید نے حدیث سنائی ، دونوں نے کہا : ہمیں یعقوب بن ابراہیم بن سعد نے حدیث سنائی ، انہوں نے کہا : ہمیں میرے والد نے صالح بن کیسان سے حدیث سنائی ، ان دونوں ( فلیح بن سلیمان اور صالح بن کیسان ) نے زہری سے یونس اور معمر کی روایت کے مطابق انہی کی سند کے ساتھ ( یہی ) حدیث بیان کی ۔ فلیح کی حدیث میں اسی طرح ہے جیسے معمر نے بیان کیا : انہیں ( قبائلی ) حمیت نے جاہلیت ( کے دور ) میں گھسیٹ لیا ۔ اور صالح کی حدیث میں یونس کے قول کی طرح ہے : انہیں ( قبائلی ) حمیت نے اکسا دیا ۔ اور صالح کی حدیث میں مزید یہ ہے : عروہ نے کہا : سیدہ عائشہ رضی اللہ عنہا اس بات کو ناپسند کرتی تھیں کہ حسان ( بن ثابت رضی اللہ عنہ ) کو ان کے سامنے برا بھلا کہا جائے ۔ وہ فرماتی تھیں : انہوں نے یہ ( عظیم شعر ) کہا ہے : \"\" بےشک میرا باپ اور اس کا باپ اور میری عزت ، تم لوگوں سے محمد صلی اللہ علیہ وسلم کی آبرو کی حفاظت کے لیے ڈھال ہیں ۔ \"\" اور انہوں نے مزید بھی کہا : عروہ نے کہا : سیدہ عائشہ رضی اللہ عنہا نے فرمایا : اللہ کی قسم! جس شخص کے بارے میں وہ ساری باتیں ، جو گھڑی گئی تھیں ، وہ کہتا تھا : سبحان اللہ! ( یہ کیسی باتیں ہیں ) اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! میں نے کبھی کسی عورت کے حجلہ عروسی 0تک کا ) پردہ بھی نہیں اٹھایا ۔ ( سیدہ عائشہ رضی اللہ عنہا نے ) کہا : پھر بعد میں وہ اللہ کی راہ میں قتل ہو کر شہید ہو گیا ۔ اور یعقوب بن ابراہیم کی حدیث میں موغرين في نحر الظهيرة ( لوگ دوپہر کے وقت بے سایہ بنجر راستے میں سفر سے بے حال ہو گئے تھے ۔ ) عبدالرزاق نے موغرين ( گرمی کی شدت سے بے حال ہوئے ) کہا ہے ۔ عبد بن حمید نے کہا : میں نے عبدالرزاق سے پوچھا : \"\" موغرين \"\" کا مطلب کیا ہے؟ کہا : الوغرة گرمی کی شدت ہوتی ہے ۔","",{"u2":"حبان بن موسیٰ نے ہمیں حدیث بیان کی، انہوں نے کہا: ہمیں عبداللہ بن مبارک نے خبر دی، انہوں نے کہا: ہمیں یونس بن یزید ایلی نے خبر دی، نیز ہمیں اسحٰق بن ابراہیم، محمد بن رافع اور عبد بن حمید نے بھی (یہی) حدیث بیان کی۔۔ ابن رافع نے کہا: ہمیں عبدالرزاق نے حدیث بیان کی اور دیگر نے کہا: ہمیں خبر دی۔۔ انہوں نے کہا: ہمیں معمر نے خبر دی، اور (حدیث کا) پچھلا حصہ معمر کی حدیث کا ہے جو عبد (بن حمید) اور (محمد) ابن رافع سے روایت کی گئی ہے، یونس اور معمر دونوں نے زہری سے روایت کرتے ہوئے کہا: مجھے سعید بن مسیب، عروہ بن زبیر، علقمہ بن وقاص اور عبیداللہ بن عبداللہ بن عتبہ بن مسعود نے رسول اللہ صلی اللہ علیہ وسلم کی اہلیہ حضرت عائشہ رضی اللہ عنہا کی حدیث کے بارے میں خبر دی جب بہتان تراشنے والوں نے اس حوالے سے جو کچھ کہا، وہ کہا اور اللہ تعالیٰ نے ان کی طرف سے کی گئی باتوں سے حضرت عائشہ رضی اللہ عنہا کی براءت فرما دی۔ ان سب نے مجھے حضرت عائشہ رضی اللہ عنہا کی حدیث کا کچھ حصہ بیان کیا، ان میں سے بعض کو دوسرے بعض لوگوں کی نسبت ان (سیدہ عائشہ رضی اللہ عنہا) کی حدیث زیادہ یاد تھی۔ میں نے ان میں سے ہر ایک سے اس کی بیان کی ہوئی حدیث اچھی طرح حفظ کر لی۔ ان کی حدیث کے اجزاء ایک دوسرے کی تائید اور تصدیق کرتے ہیں۔ ان سب نے یہ بیان کیا کہ نبی صلی اللہ علیہ وسلم کی اہلیہ حضرت عائشہ صدیقہ رضی اللہ عنہا نے کہا: رسول اللہ صلی اللہ علیہ وسلم جب کسی سفر کے لیے نکلنے کا ارادہ فرماتے تو اپنی بیویوں کے درمیان قرعہ ڈالتے، ان میں سے جس کا قرعہ نکلتا، رسول اللہ صلی اللہ علیہ وسلم اسے اپنے ساتھ لے کر (سفر پر) نکلتے۔\nحضرت عائشہ رضی اللہ عنہا نے فرمایا: آپ صلی اللہ علیہ وسلم نے ایک جنگ میں جو آپ نے لڑی، (غزوہ بنی مصطلق مراد ہے جس کا دوسرا نام غزوہ مُریسیع ہے۔ یہ 5ھ میں لڑی گئی) قرعہ ڈالا تو میرا نام نکلا، میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ روانہ ہوئی۔ یہ حجاب کا حکم نازل ہونے کے بعد کا واقعہ ہے۔ پورے سفر میں مجھے ہودج (کجاوے) میں ہی اٹھایا (اور اونٹ کی پیٹھ پر بٹھایا) جاتا تھا اور ہودج ہی میں (نیچے) اتارا جاتا تھا یہاں تک کہ جب رسول اللہ صلی اللہ علیہ وسلم اپنے غزوے سے فارغ ہو گئے اور واپس روانہ ہوئے اور ہم مدینہ سے قریب پہنچ گئے تو آپ نے (رات کا کچھ حصہ آرام کرنے کے بعد) رات ہی کو سفر کا اعلان فرما دیا۔ جب ان سب لوگوں نے سفر کا اعلان کر دیا تو میں اٹھی، (پہلے) چل کر لشکر سے باہر نکلی اور جب ضرورت سے فارغ ہو گئی تو کجاوے کی طرف آئی۔ اس وقت میں نے اپنی گردن کے نیچے ہاتھ لگایا تو (یمن کے شہر) ظفار کے (سفید و سیاہ) پتھروں کا میرا ہار ٹوٹ (کر گر) چکا تھا۔ میں واپس ہوئی اور اپنا ہار ڈھونڈنا شروع کر دیا۔ اس کی تلاش نے مجھے (کافی دیر کے لئے وہیں) روکے رکھا۔ (اتنے میں) وہ لوگ، جو اونٹ کی پشت پر میرا کجاوا باندھا کرتے تھے، آئے، کجاوا اٹھایا اور میرے اس اونٹ پر باندھ دیا جس پر میں سفر کیا کرتی تھی۔ وہ یہی سمجھ رہے تھے کہ میں اس (کجاوے) کے اندر موجود ہوں۔\nحضرت عائشہ رضی اللہ عنہا نے فرمایا: اس زمانے میں عورتیں ہلکی پھلکی ہوتی تھیں، موٹی نہیں ہوتی تھیں، نہ ان پر گوشت چڑھا ہوتا تھا، وہ سانس کی ڈوری بندھی رہنے کے بقدر کھانا کھاتی تھیں۔ ان لوگوں نے جب میرے کجاوے کو اٹھایا اور اونچا کیا تو اس کے وزن میں کوئی تبدیلی محسوس نہ کی۔ میں (اس وقت) کم عمر لڑکی ہی تھی۔ انہوں نے اونٹ کو کھڑا کیا اور چل پڑے۔ مجھے اپنا ہار لشکر روانہ ہونے کے بعد ہی ملا تھا۔ میں ان کی رات گزارنے کی جگہوں پر آئی تو وہاں نہ کوئی کسی کو بلانے والا تھا، نہ جواب دینے والا، میں نے اسی جگہ کا رخ کیا جہاں (رات کو اپنے خیمے میں) ٹھہری تھی۔ مجھے یقین تھا کہ جب وہ لوگ مجھے (کجاوے میں) نہ پائیں گے تو میری طرف واپس آئیں گے، میں اپنی اسی منزل پر بیٹھی ہوئی تھی کہ میری آنکھ لگ گئی اور میں سو گئی۔ بنوسلیم کے بطن بنو ذکوان سے تعلق رکھنے والے صفوان بن معطل نے رات کے وقت لشکر کے پیچھے قیام کیا تھا۔ وہ رات کے آخری حصے میں روانہ ہوئے اور صبح کے وقت میری منزل کے پاس آئے تو انہیں کسی سوئے ہوئے انسان کا سایہ سا نظر آیا، وہ میرے قریب آئے تو مجھے دیکھ کر پہچان لیا۔ انہوں نے مجھ پر حجاب فرض ہونے سے پہلے مجھے دیکھا ہوا تھا۔ انہوں نے مجھے پہچاننے کے بعد انا للہ وانا الیہ راجعون پڑھا تو میں جاگ گئی۔ میں نے اپنی پردے کی چادر سے اپنا چہرہ ڈھانک لیا، اللہ کی قسم! وہ مجھ سے ایک کلمہ تک نہیں کہہ رہے تھے اور نہ ہی انا للہ کے علاوہ میں نے ان کے منہ سے کوئی بات سنی یہاں تک کہ انہوں نے اپنی اونٹنی کو بٹھایا۔ وہ اونٹنی کے اگلے پاؤں پر چڑھ کر کھڑے ہو گئے (تاکہ وہ ہل نہ سکے) تو میں اس اونٹنی پر سوار ہو گئی اور وہ مجھے اونٹنی پر بٹھا کر اس کی نکیل کی رسی پکڑ کر چل پڑے، یہاں تک کہ جب لوگ دوپہر کی شدید گرمی کے سامنے بے حال ہو کر اتر گئے تو اس کے بعد ہم لشکر میں پہنچے۔ تو میری حالت کے بارے میں جس نے ہلاکت میں پڑنا تھا، وہ ہلاکت میں پڑا اور جو شخص اس بہتان تراشی کے سب سے بڑے حصے کا ذمہ دار تھا وہ (رئیس المنافقین) عبداللہ بن ابی بن سلول تھا۔ ہم مدینہ آ گئے۔ مدینہ آتے ہی میں ایک مہینہ بیمار رہی۔ لوگ بہتان باندھنے والوں کی باتوں میں باتیں ملاتے رہے جبکہ مجھے اپنی بیماری کی وجہ سے ان میں سے کسی بات کا شعور تک نہ تھا۔ میری بیماری کے دوران میں جو بات مجھے کھٹکتی تھی وہ یہ تھی کہ مجھے رسول اللہ صلی اللہ علیہ وسلم کی طرف سے وہ لطف و کرم میسر نہ تھا جو میں اپنی بیماری کے دوران میں ہمیشہ دیکھا کرتی تھی۔ رسول اللہ صلی اللہ علیہ وسلم اندر آتے، سلام کہتے اور کہتے: \"آپ لوگ کیسی ہو؟\" بس یہی بات مجھے کھٹکتی تھی لیکن اصل (شے) کا مجھے پتہ نہ چلتا تھا۔ یہاں تک کہ میں بہت نقاہت کے بعد باہر نکلی، میں مسطح کی ماں کے ہمراہ (مدینہ سے باہر) مناصع کی طرف نکلی، وہیں ہمارا ضرورت کے لیے باہر جانے کا علاقہ تھا اور ہم ایک رات کے بعد دوسری رات ہی تو باہر نکلتے تھے۔ یہ اس سے پہلے کی بات ہے جب ہم نے اپنے گھروں کے قریب (حوائج ضروریہ کے لیے) پردہ دار جگہیں بنا لی تھیں اور ضرورت سے فراغت کے معاملے میں ہمارا طریقہ ابتدائی عربوں کا سا تھا، ہمیں پردہ دار جگہیں اپنے گھروں (رہائشی حجروں) کے پاس بنانے سے اذیت ہوتی تھی۔ میں اور مسطح کی ماں چل پڑیں۔ وہ ابو رہم بن مطلب بن عبد مناف کی بیٹی تھیں۔ ان کی والدہ صخر بن عامر کی بیٹی اور حضرت ابوبکر صدیق رضی اللہ عنہ کی خالی تھیں۔ اور ان کا بیٹا مسطح بن اثاثہ بن عباد بن مطلب کا بیٹا تھا۔ میں اور ابورہم کی بیٹی (مسطح کی والدہ) اپنی ضرورت سے فارغ ہو کر میرے گھر کی طرف آئیں تو ام مسطح رضی اللہ عنہ اپنی موٹی اونی چادر میں ا(لجھیں اور) پھسل کر گر پڑیں۔ اور کہنے لگیں: (اللہ کرے) مسطح منہ کے بل گر کر ہلاک ہو! میں نے ان سے کہا: آپ نے بہت بری بات کہی ہے۔ آپ ایسے شخص کو بددعا دے رہی ہیں جو بدر میں شامل تھا۔ وہ کہنے لگیں: اے بھولی عورت! تم نے نہیں سنا، اس نے کیا کہا ہے؟ میں نے کہا: اس نے کیا کہا ہے؟ (حضرت عائشہ رضی اللہ عنہا نے کہا: تو انہوں نے مجھے بہتان تراشوں کی بات بتائی اور میری (پہلی) بیماری میں (دوسری سخت ترین) بیماری کا اضافہ ہو گیا۔ میں جب واپس اپنے گھر آئی تو رسول اللہ صلی اللہ علیہ وسلم اندر داخل ہوئے، سلام کہا، پھر پوچھا: \"تم لوگ کیسی ہو؟\" (تو) میں نے کہا: کیا آپ مجھے اجازت دیتے ہیں کہ میں اپنے والدین کے ہاں چلی جاؤں؟ (حضرت عائشہ رضی اللہ عنہا نے) کہا: میں اس وقت یہ چاہتی تھی کہ ان دونوں (والدین) کی طرف سے خبر کے بارے میں تیقن حاصل کر لوں۔ رسول اللہ صلی اللہ علیہ وسلم نے مجھے اجازت دے دی، میں اپنے والدین کے ہاں آ گئی اور اپنی والدہ سے کہا: امی! لوگ کیا باتیں کر رہے ہیں؟ تو انہوں نے کہا: بیٹی اس معاملے کو اپنے لیے مزید تکلیف کا ذریعہ نہ بناؤ۔۔ اللہ کی قسم! ایسا نہ ہونے کے برابر ہے کہ کسی مرد کے ہاں کوئی خوبصورت بیوی ہو، وہ اس سے محبت کرتا ہو اور اس کی سوکنیں بھی ہوں تو عورتیں اس پر بڑھا کر باتیں نہ کریں (حضرت عائشہ رضی اللہ عنہا نے) کہا: میں نے کہا: سبحان اللہ! تو کیا لوگ اس طرح کی باتیں (بھی) کر رہے ہیں؟ اس رات صبح ہونے تک میں مسلسل روتی رہی، نہ آنسو رکتے تھے، نہ آنکھوں میں سرمے جتنی (قلیل ترین مقدار میں) نیند محسوس کرتی تھی، پھر میں نے روتے ہوئے صبح کی۔ رسول اللہ صلی اللہ علیہ وسلم نے جب وحی کی آمد میں تاخیر محسوس کی تو علی بن ابی طالب اور اسامہ بن زید رضی اللہ عنہ کو اپنی بیوی سے جدائی کے بارے میں مشورے کے لیے بلایا۔ (حضرت عائشہ رضی اللہ عنہا نے) کہا: اسامہ بن زید رضی اللہ عنہ نے تو اسی طرف اشارہ کیا جو وہ آپ صلی اللہ علیہ وسلم کی اہلیہ کی براءت اور ان کی (آپس کی) محبت کے بارے میں جانتے تھے۔ انہوں نے کہا: اللہ کے رسول! وہ آپ کی گھر والی ہیں اور ہم اچھائی کے سوا اور کوئی بات جانتے تک نہیں۔ رہے حضرت علی بن ابی طالب رضی اللہ عنہ تو انہوں نے کہا: اللہ تعالیٰ نے آپ کو کسی تنگی میں نہیں رکھا ہوا، ان کے علاوہ بھی عورتیں بہت ہیں۔ اگر آپ خادمہ سے پوچھیں تو آپ کو وہ سچ بتائے گی۔ (حضرت عائشہ رضی اللہ عنہا نے) کہا: رسول اللہ صلی اللہ علیہ وسلم نے بریرہ (حضرت عائشہ رضی اللہ عنہا کی آزاد کردہ کنیز) کو بلایا اور فرمایا: \"بریرہ! تم نے (کبھی) کوئی ایسی چیز دیکھی جس سے تمہیں عائشہ کے بارے میں شک ہوا ہو؟\" بریرہ رضی اللہ عنہ نے کہا: اس ذات کی قسم جس نے آپ کو حق کے ساتھ مبعوث کیا ہے! ان کے خلاف میں نے اس سے زیادہ کبھی کوئی ایسی بات نہیں دیکھی جس کا میں ان پر عیب لگاؤں کہ وہ ایک نو عمر لڑکی ہے، اپنے گھر والوں کا آٹا گندھا چھوڑ کر سو جاتی ہے اور بکری آ کر اسے کھا لیتی ہے۔ (حضرت عائشہ رضی اللہ عنہا نے) کہا: رسول اللہ صلی اللہ علیہ وسلم منبر پر کھڑے ہوئے اور عبداللہ بن ابی بن سلول کے (خلاف کاروائی کے) بارے میں معذرت طلب فرمائی۔ (حضرت عائشہ رضی اللہ عنہا نے) کہا: رسول اللہ صلی اللہ علیہ وسلم نے منبر پر کھڑے ہو کر فرمایا: \"اے مسلمانوں کی جماعت! (تم میں سے کون) کون شخص مجھے اس آدمی کے خلاف (کاروائی کے) حوالے سے معذور سمجھتا ہے جس کی اذیت رسانی کا سلسلہ میرے گھر والوں تک پہنچ گیا ہے۔ اللہ کی قسم! میں اپنے گھر والوں کے بارے میں خیر کے سوا اور کچھ نہیں جانتا اور جس آدمی کا انہوں نے ذکر کیا ہے اس کے بارے میں بھی میں خیر اور بھلائی کے سوا اور کچھ نہیں جانتا۔ وہ جب بھی میرے گھر آیا ہے ہمیشہ میرے ہی ساتھ آیا ہے۔\" تو سعد بن معاذ انصاری رضی اللہ عنہ کھڑے ہوئے اور کہا: اللہ کے رسول! میں اس کے بارے میں آپ کا عذر مانتا ہوں۔ اگر وہ اوس میں سے ہوتا تو ہم اس کی گردن مار دیتے اور اگر وہ ہمارے برادر قبیلے خزرج میں سے ہے تو آپ ہمیں حکم دیں گے اور ہم آپ کے حکم پر عمل کریں گے۔ (حضرت عائشہ رضی اللہ عنہ نے) کہا: تو حضرت سعد بن عبادہ رضی اللہ عنہ کھڑے ہو گئے، وہ خزرج کے سردار تھے اور نیک انسان تھے، لیکن انہیں (قبائلی) حمیت نے جاہلیت کے دور میں گھسیٹ لیا۔ انہوں نے سعد بن معاذ رضی اللہ عنہ سے کہا: بقائے الہیٰ کی قسم! تم نے جھوٹ کہا۔ نہ تم اسے قتل کرو گے، نہ ہی تم میں اس کے قتل کی ہمت ہے۔ اس پر اُسید بن حضیر رضی اللہ عنہ کھڑے ہو گئے۔ وہ سعد بن معاذ رضی اللہ عنہ کے چچا زاد تھے۔ انہوں نے سعد بن عبادہ رضی اللہ عنہ سے کہا: تم نے جھوٹ کہا ہے، بقائے الہیٰ کی قسم! ہم اسے ضرور بالضرور قتل کریں گے۔ تم منافق ہو اور منافقوں کی طرف سے جھگڑا کرتے ہو۔ اوس اور خزرج کے دونوں قبیلے جوش میں آ گئے، یہاں تک کہ آپس میں لڑنے پر آمادہ ہو گئے۔ رسول اللہ صلی اللہ علیہ وسلم منبر ہی پر کھڑے تھے۔ آپ صلی اللہ علیہ وسلم مسلسل انہیں دھیما کرتے رہے یہاں تک کہ وہ خاموش ہو گئے اور آپ صلی اللہ علیہ وسلم بھی خاموش ہو گئے۔ (حضرت عائشہ رضی اللہ عنہا نے) کہا: میں وہ سارا دن روتی رہی، نہ آنسو تھمتے تھے، نہ آنکھوں میں نیند کا سرمہ ہی لگا سکتی تھی۔ پھر اگلی رات بھی میں روتی رہی، نہ آنسو تھمتے تھے، نہ میں آنکھوں میں نیند کا سرمہ ہی لگا سکتی تھی (سرمے کے برابر نیند محسوس کر سکتی تھی۔) میرے ماں باپ یہ سمجھتے تھے کہ یہ رونا میرا جگر پھاڑ دے گا۔ وہ دونوں میرے پاس بیٹھے تھے اور میں روئے جا رہی تھی کہ انصار کی ایک عورت نے میرے پاس آنے کی اجازت مانگی، میں نے اسے اجازت دی تو وہ بھی بیٹھ کر رونے لگی۔ (حضرت عائشہ رضی اللہ عنہا نے) کہا: ہم اسی حال میں تھے کہ رسول اللہ صلی اللہ علیہ وسلم ہمارے ہاں تشریف لے آئے، سلام کہا، پھر بیٹھ گئے۔ (حضرت عائشہ رضی اللہ عنہا نے) کہا: جب سے میرے بارے جو کہا گیا تھا، اس کے بعد آپ میرے پاس (آکر بھی) نہیں بیٹھے تھے۔ اور آپ ایک مہینہ (انتظار میں رہے)، آپ کی طرف میرے بارے میں کوئی وحی بھی نہیں آئی تھی، انہوں نے کہا: جب رسول اللہ صلی اللہ علیہ وسلم بیٹھ گئے تو آپ نے شہادتین پڑھیں، پھر فرمایا: \"اس کے بعد، عائشہ! مجھے تمہارے حوالے سے یہ یہ بات پہنچی ہے۔ اگر تم بَری ہو تو عنقریب اللہ تعالیٰ خود تمہاری براءت فرما دے گا اور اگر تم سی گناہ کے قریب (بھی) ہوئی ہو تو اللہ سے مغفرت طلب کرو اور اس کی طرف توبہ کرو، کیونکہ بندہ جب گناہ کا اعتراف کر لیتا ہے، پھر توبہ کرتا ہے تو اللہ اس کی توبہ قبول فرما لیتا ہے۔\" (حضرت عائشہ رضی اللہ عنہا نے) کہا: جب رسول اللہ صلی اللہ علیہ وسلم نے اپنی بات ختم کی تو میرے آنسو رک گئے، یہاں تک کہ مجھے اپنی آنکھ میں ایک قطرہ بھی محسوس نہ ہو رہا تھا۔ میں نے اپنے والد سے کہا: آپ میری طرف سے رسول اللہ صلی اللہ علیہ وسلم کو اس بات کا جواب دیں جو انہوں نے کہی ہے، انہوں نے کہا: اللہ کی قسم! مجھے معلوم نہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم سے کیا کہوں، پھر میں نے اپنی ماں سے کہا: آپ میری طرف سے رسول اللہ صلی اللہ علیہ وسلم کو جواب دیں۔ انہوں نے (بھی وہی) کہا: واللہ! میں نہیں جانتی کہ میں رسول اللہ صلی اللہ علیہ وسلم سے کیا کہوں۔ تو میں نے، جبکہ اس وقت میں ایک کم عمر لڑکی تھی، زیادہ قرآن مجید یاد نہیں تھا (خود جواب دیتے ہوئے) کہا: اللہ کی قسم! میں نے یہ بات جان لی ہے کہ آپ لوگوں نے اس بات کو (بار بار) سنا ہے اور یہ آپ کے دلوں میں بیٹھ گئے ہے اور آپ اس کو سچ سمجھنے لگے ہیں۔ اگر میں آپ لوگوں سے کہوں کہ میں (گناہ سے بالکل) بَری ہوں اور اللہ جانتا ہے کہ میں بَری ہوں تو آپ لوگ اس بات میں مجھے سچا نہیں مانو گے اور اگر میں آپ لوگوں کے سامنے اس معاملے کا اعتراف کر لوں اور اللہ جانتا ہے کہ میں بَری ہوں، تو آپ لوگ میری تصدیق کرو گے۔ مجھے اپنے اور آپ لوگوں کے لیے حضرت یوسف علیہ السلام کے والد (یعقوب علیہ السلام) کے قول کے علاوہ اور کوئی مثال نہیں ملتی\" صبر جمیل (سے کام لینا ہے) اور جو کچھ آپ لوگ کہتے ہیں، اس پر اللہ ہے جس سے مدد مانگنی ہے۔\"\n(حضرت عائشہ رضی اللہ عنہ نے) کہا: پھر میں اپنا رخ پھیر کر اپنے بستر پر لیٹ گئی، انہوں نے کہا: اور میں اللہ کی قسم! اس وقت جانتی تھی کہ میں بَری ہوں اور (یہ بھی جانتی تھی کہ) اللہ بَری ہونے کی وجہ سے (خود) مجھے بَری فرمائے گا لیکن اللہ گواہ ہے، مجھے یہ گمان نہ تھا کہ وہ میرے بارے میں وحی نازل فرمائے گا جس کی تلاوت ہوا کرے گی میری نظر میں میرا مقام اس سے بہت حقیر تھا کہ اللہ عزوجل میرے بارے میں خود کلام فرمائے گا جس کی تلاوت ہو گئی لیکن میں یہ امید ضرور رکھتی تھی کہ رسول اللہ صلی اللہ علیہ وسلم سوتے ہوئے کوئی خواب دیکھیں گے جس کے ذریعے سے اللہ مجھے بَری فرما دے گا۔ (حضرت عائشہ رضی اللہ عنہا نے) کہا: اللہ کی قسم! رسول اللہ صلی اللہ علیہ وسلم اپنی جگہ سے نہیں اٹھے تھے، نہ ابھی گھر والوں میں سے کوئی باہر نکلا تھا کہ اللہ عزوجل نے نے اپنے نبی پر وحی نازل فرما دی۔ وحی کے وقت آپ جس طرح پسینے سے شرابور ہو جاتے تھے آپ پر وہی کیفیت طاری ہو گئی، یہاں تک کہ سرد دن میں بھی نازل کی جانے والی وحی کے بوجھ سے پسینہ موتیوں کی طرح آپ کے جسم سے گرا کرتا تھا۔ انہوں نے کہا: جب رسول اللہ صلی اللہ علیہ وسلم سے یہ کیفیت زائل ہوئی تو آپ ہنس رہے تھے اور پہلا جملہ جو آپ نے کہا، یہ تھا: \"عائشہ! خوش ہو جاؤ، اللہ نے تمہیں بَری فرم دیا ہے۔\" میری ماں نے مجھ سے کہا: کھڑی ہو کر ان کے پاس جاؤ۔ تو میں نے کہا: نہ میں کھڑی ہو کر آپ کی طرف جاؤں گی، نہ اللہ کے سوا کسی کا شکر ادا کروں گی، وہی ہے جس نے میری براءت نازل فرمائی۔ (حضرت عائشہ رضی اللہ عنہا نے) کہا کہ اللہ عزوجل نے دس آیات نازل فرمائیں: \"جو لوگ بہتان لے کر آئے وہ تمہی میں سے ایک گروہ ہے، تم اسے اپنے لیے برا مت سمجھو، بلکہ یہ تمہارے لیے بہت بہتر ہے۔\" اللہ عزوجل نے یہ (دس) آیات میری براءت میں نازل فرمائیں۔ (حضرت عائشہ رضی اللہ عنہا نے) کہا: حضرت ابوبکر رضی اللہ عنہ نے کہا: اور وہ مسطح پر اپنے ساتھ اس کی قرابت اور اس کے فقر کی بنا پر خرچ کیا کرتے تھے، اللہ کی قسم! اس نے عائشہ کے بارے میں جو کہا ہے، اس کے بعد میں اس پر کچھ خرچ نہیں کروں گا۔ اس پر اللہ عزوجل نے یہ آیت اتاری: \"تم میں سے فضیلت اور استطاعت رکھنے والے یہ قسم نہ کھائیں کہ وہ قرابت داروں کو (خرچ) نہ دیا کریں گے\" اپنے فرمان: \"کیا تم لوگ یہ پسند نہیں کرتے کہ اللہ تمہیں بخش دے؟\" تک۔\nحبان بن موسیٰ نے کہا: عبداللہ بن مبارک کا قول ہے: یہ اللہ کی کتاب کی سب سے زیادہ امیدا افزا آیت ہے۔\nاس پر حضرت ابوبکر صدیق رضی اللہ عنہ نے فرمایا: اللہ کی قسم! میں یقینا یہ بات پسند کرتا ہوں کہ اللہ مجھے بخش دے، چنانچہ وہ مسطح رضی اللہ عنہ کو جو خرچ دیا کرتے تھے، دوبارہ دینے لگے اور کہا: میں یہ (خرچ) اس سے کبھی نہیں چھینوں گا (ہمیشہ دیتا رہوں گا۔)\nحضرت عائشہ رضی اللہ عنہا نے کہا: اور رسول اللہ صلی اللہ علیہ وسلم نے اپنی بیوی زینب بنت حجش رضی اللہ عنہا سے بھی میرے معاملے کے بارے میں دریافت کیا جو نبی صلی اللہ علیہ وسلم کی بیوی تھی: \"تم کیا جانتی ہو یا (فرمایا:) تم نے کیا دیکھا؟\" انہوں نے کہا: اللہ کے رسول! میں اپنے کانوں اور اپنی آنکھوں کی حفاظت کرتی ہوں (کہ میں اپنے کانوں کی طرف جھوٹی بات سننے کو اور اپنی آنکھوں کی طرف جھوٹ دیکھنے کو منسوب کروں) اللہ کی قسم! میں (ان کے کردار میں) بھلائی کے سوا اور کچھ نہیں جانتی۔\nحضرت عائشہ نے کہا: اور یہی تھیں جو نبی صلی اللہ علیہ وسلم کی بیویوں میں سے (مرتبے اور قرب کے معاملے میں) میرے مدمقابل آتی تھیں، لیکن خدا خوفی کی بنا پر اللہ نے ان کو (غلط بات کہنے سے) محفوظ رکھا، جبکہ ان کی بہن حمنہ بنت حجش رضی اللہ عنہا نے ان کے لیے لڑائی شروع کر دی اور ہلاک ہونے والوں کے ساتھ ہلاک ہوئیں۔ (قذف و بہتان کے گناہ کا ارتکاب کر بیٹھیں۔)\nزہری نے کہا: یہ (واقعہ) ہے جو ان سب (بیان کرنے والوں) کی طرف سے ہم تک پہنچا۔\nیونس کی حدیث میں (حضرت سعد بن عبادہ رضی اللہ عنہ کے حوالے سے) ہے: ان (سعد بن عبادہ رضی اللہ عنہ) کو (قبائلی) حمیت نے اکسا دیا۔"}],[7077,"ابو اسامہ نے ہشام بن عروہ سے روایت کی ، انہوں نے اپنے والد سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ، انہوں نے کہا : جب میرے معاملے میں وہ باتیں کہی گئیں جو کہی گئیں اور مجھے اس معاملے کا علم نہ تھا ، ( اس وقت ) رسول اللہ صلی اللہ علیہ وسلم خطبہ دینے کے لیے کھڑے ہوئے ۔ شہادتین پڑھیں ، اللہ کی حمد و ژنا کی جو اس کے شایان شان ہے ، پھر فرمایا : \"\" اس ( حمد و ثنا ) کے بعد! مجھے ان لوگوں کے بارے میں مشورہ دو جنہوں نے میری اہلیہ پر بہتان لگایا اور میں اللہ کی قسم کھاتا ہوں کہ میری اہلیہ کے خلاف کبھی کوئی برائی میرے علم میں نہیں آئی ۔ وہ ( صفوان بن معطل رضی اللہ عنہ ) جس کے بارے میں انہوں نے تہمت لگائی ہے ، اللہ کی قسم! مجھے اس کے بارے میں کسی برائی کا علم نہیں ، وہ کبھی میرے گھر نہیں آیا مگر اس وقت جب میں موجود تھا اور میں کبھی سفر کی وجہ سے ( مدینہ سے ) غیر حاضر نہیں رہا مگر وہ بھی ( اس سفر میں ) میرے ساتھ ( مدینہ س ) غیر حاضر تھا ۔ \"\" اور پورے واقعے سمیت حدیث بیان کی اور اس میں یہ ( بھی ) ہے : رسول اللہ صلی اللہ علیہ وسلم میرے گھر میں داخل ہوئے اور میری خادمہ سے پوچھا ۔ اس نے کہا : اللہ کی قسم! میں ان میں کوئی ایک عیب بھی نہیں جانتی ، اس کے سوا کہ وہ سو جایا کرتی تھیں اور بکری اندر آتی اور ان کا آٹا یا کہا : ان کا خمیر ( جو آٹے میں ملایا جاتا ہے ) کھا جاتی ۔ ہشام کو شک ہوا ہے ۔ ۔ تو آپ صلی اللہ علیہ وسلم کے ایک ساتھی نے جھڑکیاں دیں اور کہا : رسول اللہ صلی اللہ علیہ وسلم کو بالکل سچ بتاؤ ، حتی کہ اس معاملے میں ان لوگوں نے اسے تحقیر آمیز باتیں کہیں تو اس نے جواب میں کہا : سبحان اللہ! اللہ کی قسم! میں ان کے بارے میں بالکل اسی طرح جانتی ہوں جس طرح سنار خالص سونے کو جانتا ہے ۔ ( ان میں ذرہ برابر کھوٹ نہیں ، وہ خالص سونا ہیں ۔ ) اور یہ معاملہ اس شخص تک پہنچا جس کے بارے میں یہ بات کہی گئی تو اس نے کہا : سبحان اللہ! اللہ کی قسم! میں نے آج تک کسی عورت کی خلوت گاہ کا پردہ بھی نہیں اٹھایا ۔ سیدہ عائشہ رضی اللہ عنہا نے فرمایا : وہ اللہ عزوجل کی راہ میں قتل ہو کر شہید ہو گیا ۔ اور اس حدیث میں مزید یہ بات بھی ہے کہ جن لوگوں نے ( بہتان پر مبنی ) باتیں کی تھیں ان میں مسطح ، حمنہ اور حسان ( بن ثابت ) رضی اللہ عنہم تھے ۔ اور منافق عبداللہ بن ابی وہ شخص تھا جو ( سیدھے سادھے واقعے کے اندر سے ) جھوٹے الزام نکالتا تھا اور ( بہتان کی جھوٹی کہانی کی صورت میں ) انہیں یکجا کرتا تھا ۔ اسی نے اس بہتان تراشی میں سب سے بڑا کردار سنبھالا اور ( اس کے بعد ) حمنہ رضی اللہ عنہا تھی ۔","",{"u2":"ابو اسامہ نے ہشام بن عروہ سے روایت کی، انہوں نے اپنے والد سے اور انہوں نے حضرت عائشہ رضی اللہ عنہا سے روایت کی، انہوں نے کہا: جب میرے معاملے میں وہ باتیں کہی گئیں جو کہی گئیں اور مجھے اس معاملے کا علم نہ تھا، (اس وقت) رسول اللہ صلی اللہ علیہ وسلم خطبہ دینے کے لیے کھڑے ہوئے۔ شہادتین پڑھیں، اللہ کی حمد و ژنا کی جو اس کے شایان شان ہے، پھر فرمایا: \"اس (حمد و ثنا) کے بعد! مجھے ان لوگوں کے بارے میں مشورہ دو جنہوں نے میری اہلیہ پر بہتان لگایا اور میں اللہ کی قسم کھاتا ہوں کہ میری اہلیہ کے خلاف کبھی کوئی برائی میرے علم میں نہیں آئی۔ وہ (صفوان بن معطل رضی اللہ عنہ) جس کے بارے میں انہوں نے تہمت لگائی ہے، اللہ کی قسم! مجھے اس کے بارے میں کسی برائی کا علم نہیں، وہ کبھی میرے گھر نہیں آیا مگر اس وقت جب میں موجود تھا اور میں کبھی سفر کی وجہ سے (مدینہ سے) غیر حاضر نہیں رہا مگر وہ بھی (اس سفر میں) میرے ساتھ (مدینہ س) غیر حاضر تھا۔\" اور پورے واقعے سمیت حدیث بیان کی اور اس میں یہ (بھی) ہے: رسول اللہ صلی اللہ علیہ وسلم میرے گھر میں داخل ہوئے اور میری خادمہ سے پوچھا۔ اس نے کہا: اللہ کی قسم! میں ان میں کوئی ایک عیب بھی نہیں جانتی، اس کے سوا کہ وہ سو جایا کرتی تھیں اور بکری اندر آتی اور ان کا آٹا یا کہا: ان کا خمیر (جو آٹے میں ملایا جاتا ہے) کھا جاتی۔ ہشام کو شک ہوا ہے۔۔ تو آپ صلی اللہ علیہ وسلم کے ایک ساتھی نے جھڑکیاں دیں اور کہا: رسول اللہ صلی اللہ علیہ وسلم کو بالکل سچ بتاؤ، حتی کہ اس معاملے میں ان لوگوں نے اسے تحقیر آمیز باتیں کہیں تو اس نے جواب میں کہا: سبحان اللہ! اللہ کی قسم! میں ان کے بارے میں بالکل اسی طرح جانتی ہوں جس طرح سنار خالص سونے کو جانتا ہے۔ (ان میں ذرہ برابر کھوٹ نہیں، وہ خالص سونا ہیں۔)\nاور یہ معاملہ اس شخص تک پہنچا جس کے بارے میں یہ بات کہی گئی تو اس نے کہا: سبحان اللہ! اللہ کی قسم! میں نے آج تک کسی عورت کی خلوت گاہ کا پردہ بھی نہیں اٹھایا۔\nحضرت عائشہ رضی اللہ عنہا نے فرمایا: وہ اللہ عزوجل کی راہ میں قتل ہو کر شہید ہو گیا۔\nاور اس حدیث میں مزید یہ بات بھی ہے کہ جن لوگوں نے (بہتان پر مبنی) باتیں کی تھیں ان میں مسطح، حمنہ اور حسان (بن ثابت) رضی اللہ عنہم تھے۔ اور منافق عبداللہ بن ابی وہ شخص تھا جو (سیدھے سادھے واقعے کے اندر سے) جھوٹے الزام نکالتا تھا اور (بہتان کی جھوٹی کہانی کی صورت میں) انہیں یکجا کرتا تھا۔ اسی نے اس بہتان تراشی میں سب سے بڑا کردار سنبھالا اور (اس کے بعد) حمنہ رضی اللہ عنہا تھی۔"}],[7078,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ ایک شخص کو رسول اللہ صلی اللہ علیہ وسلم کی ام ولد ( آپ کے فرزند کی والدہ ) کے ساتھ مہتم کیا جاتا تھا تو رسول اللہ صلی اللہ علیہ وسلم نے سیدنا علی رضی اللہ عنہ سے کہا : جاؤ اور اس کی گردن اڑا دو ، سیدنا علی رضی اللہ عنہ اس کے پاس گئے تو وہ ایک اتھلے ( کم گہرے ) کنویں میں ٹھنڈک کے لیے غسل کر رہا تھا ، سیدنا علی رضی اللہ عنہ نے اس سے کہا : نکلو ، اور ( سہارا دینے کے لیے ) اسے اپنا ہاتھ پکڑایا اور اسے باہر نکالا تو دیکھا کہ وہ ہیجڑا ہے ، اس کا عضو مخصوص تھا ہی نہیں ۔ اس پر سیدنا علی رضی اللہ عنہ ( اس کو قتل کرنے سے ) رُک گئے اور نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور عرض کی : اللہ کے رسول! وہ تو ہیجڑا ہے ، اس کا عضو مخصوص ہے ہی نہیں ۔","",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے کہ ایک شخص کو رسول اللہ صلی اللہ علیہ وسلم کی ام ولد (آپ کے فرزند کی والدہ) کے ساتھ مہتم کیا جاتا تھا تو رسول اللہ صلی اللہ علیہ وسلم نے حضرت علی رضی اللہ عنہ سے کہا: جاؤ اور اس کی گردن اڑا دو، حضرت علی رضی اللہ عنہ اس کے پاس گئے تو وہ ایک اتھلے (کم گہرے) کنویں میں ٹھنڈک کے لیے غسل کر رہا تھا، حضرت علی رضی اللہ عنہ نے اس سے کہا: نکلو، اور (سہارا دینے کے لیے) اسے اپنا ہاتھ پکڑایا اور اسے باہر نکالا تو دیکھا کہ وہ ہیجڑا ہے، اس کا عضو مخصوص تھا ہی نہیں۔ اس پر حضرت علی رضی اللہ عنہ (اس کو قتل کرنے سے) رُک گئے اور نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور عرض کی: اللہ کے رسول! وہ تو ہیجڑا ہے، اس کا عضو مخصوص ہے ہی نہیں۔"}],[7079,"ہمیں زہیر بن معاویہ نے حدیث بیان کی ، انہوں نے کہا : ہمیں ابواسحٰق نے حدیث بیان کی ، انہوں نے سیدنا زید بن ارقم رضی اللہ عنہ سے سنا ، وہ کہہ رہے تھے : ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک سفر میں نکلے ، اس میں لوگوں کو بہت تکلیف پہنچی تو عبداللہ بن ابی نے اپنے ساتھیوں سے کہا : جو لوگ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ہیں ، جب تک آپ صلی اللہ علیہ وسلم سے الگ نہ ہو جائیں ، ان پر کچھ خرچ نہ کرو ( مہاجرین سے تعاون بند کر دو ۔ ) زہیر نے کہا : اور یہ اس کی قراءت ہے جس نے حوله کو زیر کے ساتھ من حوله پڑھا ۔ اور اس نے ( یہ بھی ) کہا : اگر ہم مدینہ کو لوٹ گئے تو جو عزت والے ہیں وہ وہاں سے ذلت والوں کو نکال دیں گے ۔ ( زید بن ارقم رضی اللہ عنہ نے ) کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوا اور آپ کو یہ بات بتا دی ، آپ نے عبداللہ بن اُبی کو بلوایا اور اس سے ( اس بات کے متعلق ) پوچھا ، اس نے بہت پکی قسم کھائی کہ اس نے ایسا نہیں کہا اور کہا : زید نے رسول اللہ صلی اللہ علیہ وسلم سے جھوٹ بولا ہے ۔ ( سیدنا زید رضی اللہ عنہ نے ) کہا : میرے دل کو ان لوگوں کی اس بات سے بہت تکلیف پہنچی ، حتی کہ اللہ تعالی نے میری تصدیق میں یہ آیت نازل کی : \"\" جب آپ کے پاس منافقین آتے ہیں \"\" پھر نبی صلی اللہ علیہ وسلم نے ان کے استغفار کے لیے ان کو بلوایا تو انہوں نے ( تمسخر سے ) اپنے سر ٹیڑھے کر لیے ۔ \"\" اور ( اس آیت میں ) اللہ تعالی کے قول : \"\" گویا وہ سہارے سے کھڑے ہوئے شہتیر ہیں \"\" ( سے مراد ) سیدنا زید رضی اللہ عنہ نے کہا : ( یہ ہے کہ ) یہ لوگ ( جسمانی اعتبار سے سیدھے ، لمبے اور دیکھنے میں ) بہت خوبصورت تھے ۔","",{"u2":") ہمیں زہیر بن معاویہ نے حدیث بیان کی، انہوں نے کہا: ہمیں ابواسحٰق نے حدیث بیان کی، انہوں نے حضرت زید بن ارقم رضی اللہ عنہ سے سنا، وہ کہہ رہے تھے: ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک سفر میں نکلے، اس میں لوگوں کو بہت تکلیف پہنچی تو عبداللہ بن ابی نے اپنے ساتھیوں سے کہا: جو لوگ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ہیں، جب تک آپ صلی اللہ علیہ وسلم سے الگ نہ ہو جائیں، ان پر کچھ خرچ نہ کرو (مہاجرین سے تعاون بند کر دو۔)\nزہیر نے کہا: اور یہ اس کی قراءت ہے جس نے حولہ کو زیر کے ساتھ من حولہ پڑھا۔\nاور اس نے (یہ بھی) کہا: اگر ہم مدینہ کو لوٹ گئے تو جو عزت والے ہیں وہ وہاں سے ذلت والوں کو نکال دیں گے۔ (زید بن ارقم رضی اللہ عنہ نے) کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوا اور آپ کو یہ بات بتا دی، آپ نے عبداللہ بن اُبی کو بلوایا اور اس سے (اس بات کے متعلق) پوچھا، اس نے بہت پکی قسم کھائی کہ اس نے ایسا نہیں کہا اور کہا: زید نے رسول اللہ صلی اللہ علیہ وسلم سے جھوٹ بولا ہے۔ (حضرت زید رضی اللہ عنہ نے) کہا: میرے دل کو ان لوگوں کی اس بات سے بہت تکلیف پہنچی، حتی کہ اللہ تعالیٰ نے میری تصدیق میں یہ آیت نازل کی: \"جب آپ کے پاس منافقین آتے ہیں\" پھر نبی صلی اللہ علیہ وسلم نے ان کے استغفار کے لیے ان کو بلوایا تو انہوں نے (تمسخر سے) اپنے سر ٹیڑھے کر لیے۔\" اور (اس آیت میں) اللہ تعالیٰ کے قول: \"گویا وہ سہارے سے کھڑے ہوئے شہتیر ہیں\" (سے مراد) حضرت زید رضی اللہ عنہ نے کہا: (یہ ہے کہ) یہ لوگ (جسمانی اعتبار سے سیدھے، لمبے اور دیکھنے میں) بہت خوبصورت تھے۔"}],[7080,"سفیان بن عیینہ نے عمرو ( بن دینار ) سے روایت کی ، انہوں نے سیدنا جابر رضی اللہ عنہ کو یہ بیان کرتے ہوئے سنا : نبی صلی اللہ علیہ وسلم عبداللہ بن ابی کی قبر پر تشریف لائے ، اس کو قبر سے نکال کر اپنے گھٹنوں پر رکھا ، اس پر اپنا لعاب مبارک چھڑکا اور اسے اپنی قمیص پہنچائی ، ( ایسا کیوں کیا؟ ) اللہ زیادہ جاننے والا ہے ۔","",{"u2":"سفیان بن عیینہ نے عمرو (بن دینار) سے روایت کی، انہوں نے حضرت جابر رضی اللہ عنہ کو یہ بیان کرتے ہوئے سنا: نبی صلی اللہ علیہ وسلم عبداللہ بن ابی کی قبر پر تشریف لائے، اس کو قبر سے نکال کر اپنے گھٹنوں پر رکھا، اس پر اپنا لعاب مبارک چھڑکا اور اسے اپنی قمیص پہنچائی، (ایسا کیوں کیا؟) اللہ زیادہ جاننے والا ہے۔"}],[7081,"ابن جریج نے کہا : مجھے عمرو بن دینار نے خبر دی ، کہا : میں نے سیدنا جابر بن عبداللہ رضی اللہ عنہ کو بیان کرتے ہوئے سنا : نبی صلی اللہ علیہ وسلم عبداللہ بن ابی کے پاس اس کو اس کے گڑھے میں داخل کر دیے جانے کے بعد آئے ، پھر سفیان کی حدیث کے مانند بیان کیا ۔","",{"u2":"ابن جریج نے کہا: مجھے عمرو بن دینار نے خبر دی، کہا: میں نے حضرت جابر بن عبداللہ رضی اللہ عنہ کو بیان کرتے ہوئے سنا: نبی صلی اللہ علیہ وسلم عبداللہ بن ابی کے پاس اس کو اس کے گڑھے میں داخل کر دیے جانے کے بعد آئے، پھر سفیان کی حدیث کے مانند بیان کیا۔"}],[7082,"ابواسامہ نے کہا : ہمیں عبیداللہ بن عمر نے نافع سے حدیث بیان کی ، انہوں نے سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت کی ، کہا : جب عبداللہ بن ابی ابن سلول مر گیا تو اس کے بیٹے عبداللہ بن عبداللہ رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے ، اور آپ سے سوال کیا کہ آپ اپنی قمیص اس کو عطا فرمائیں ، جس میں وہ اپنے باپ کو کفن دیں تو آپ نے ( وہ قمیص ) ان کو عطا کی ، پھر آپ صلی اللہ علیہ وسلم سے درخواست کی کہ آپ اس کی نماز جنازہ پڑھیں ، چنانچہ رسول اللہ صلی اللہ علیہ وسلم اس پر نماز جنازہ پڑھنے کے لیے کھڑے ہوئے تو سیدنا عمر رضی اللہ عنہ کھڑے ہو گئے اور ( التجا کرنے کے لیے ) رسول اللہ صلی اللہ علیہ وسلم کے کپڑے ( کے ایک کنارے ) کو پکڑ لیا اور کہا : اللہ کے رسول! کیا آپ اس کی نماز جنازہ پڑھائیں گے ، حالانکہ اللہ تعالی نے آپ کو اس کی نماز جنازہ پڑھنے سے منع فرمایا ہے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ تعالی نے مجھے اختیار دیا ہے ، اس نے فرمایا ہے : \" آپ ان کے لیے استغفار کریں یا استغفار نہ کریں ، خواہ آپ ان کے لیے ستر مرتبہ استغفار کریں \" اور میں ستر مرتبہ سے زیادہ استغفار کروں گا ۔ \" ( عمر رضی اللہ عنہ نے ) کہا : یقینا وہ منافق ہے ، ( مگر ) رسول اللہ صلی اللہ علیہ وسلم نے اس کی نماز جنازہ پڑھا دی ، اس پر اللہ عزوجل نے ( واضح حکم ) نازل فرمایا : \" اور ان ( منافقین ) میں سے جو شخص مر جائے آپ کبھی اس کی نماز جنازہ نہ پڑھیں اور نہ اس کی قبر پر کھڑے ہوں ۔","",{"u2":"ابواسامہ نے کہا: ہمیں عبیداللہ بن عمر نے نافع سے حدیث بیان کی، انہوں نے حضرت عبداللہ بن عمر رضی اللہ عنہ سے روایت کی، کہا: جب عبداللہ بن ابی ابن سلول مر گیا تو اس کے بیٹے عبداللہ بن عبداللہ رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، اور آپ سے سوال کیا کہ آپ اپنی قمیص اس کو عطا فرمائیں، جس میں وہ اپنے باپ کو کفن دیں تو آپ نے (وہ قمیص) ان کو عطا کی، پھر آپ صلی اللہ علیہ وسلم سے درخواست کی کہ آپ اس کی نماز جنازہ پڑھیں، چنانچہ رسول اللہ صلی اللہ علیہ وسلم اس پر نماز جنازہ پڑھنے کے لیے کھڑے ہوئے تو حضرت عمر رضی اللہ عنہ کھڑے ہو گئے اور (التجا کرنے کے لیے) رسول اللہ صلی اللہ علیہ وسلم کے کپڑے (کے ایک کنارے) کو پکڑ لیا اور کہا: اللہ کے رسول! کیا آپ اس کی نماز جنازہ پڑھائیں گے، حالانکہ اللہ تعالیٰ نے آپ کو اس کی نماز جنازہ پڑھنے سے منع فرمایا ہے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالیٰ نے مجھے اختیار دیا ہے، اس نے فرمایا ہے: \"آپ ان کے لیے استغفار کریں یا استغفار نہ کریں، خواہ آپ ان کے لیے ستر مرتبہ استغفار کریں\" اور میں ستر مرتبہ سے زیادہ استغفار کروں گا۔\" (عمر رضی اللہ عنہ نے) کہا: یقینا وہ منافق ہے، (مگر) رسول اللہ صلی اللہ علیہ وسلم نے اس کی نماز جنازہ پڑھا دی، اس پر اللہ عزوجل نے (واضح حکم) نازل فرمایا: \"اور ان (منافقین) میں سے جو شخص مر جائے آپ کبھی اس کی نماز جنازہ نہ پڑھیں اور نہ اس کی قبر پر کھڑے ہوں۔\""}],[7083,"یحیی قطان نے عبیداللہ ( بن عمر بن حفص ) سے اسی سند کے ساتھ اسی طرح حدیث بیان کی اور مزید یہ کہا : چنانچہ آپ صلی اللہ علیہ وسلم نے ان پر نماز جنازہ ترک کر دی ۔","",{"u2":") یحییٰ قطان نے عبیداللہ (بن عمر بن حفص) سے اسی سند کے ساتھ اسی طرح حدیث بیان کی اور مزید یہ کہا: چنانچہ آپ صلی اللہ علیہ وسلم نے ان پر نماز جنازہ ترک کر دی۔"}],[7084,"محمد بن ابی عمر مکی نے ہمیں حدیث بیان کی ، کہا : ہمیں سفیان نے منصور سے حدیث بیان کی ، انہوں نے مجاہد سے ، انہوں نے ابومعمر سے اور انہوں نے سیدنا ابن مسعود رضی اللہ عنہ سے روایت کی ، کہا : تین آدمی بیت اللہ کے پاس اکٹھے ہوئے ، ( ان میں سے ) دو قریشی تھے اور ایک ثقفی تھا ، یا دو ثقفی تھے اور ایک قریشی تھا ، ان کے دلوں کا فہم کم تھا ، ان کے پیٹوں کی چربی بہت تھی ۔ ان میں سے ایک نے کہا : کیا تم سمجھتے ہو کہ جو کچھ ہم کہتے ہیں ، اللہ سنتا ہے؟ دوسرے نے کہا : اگر ہم اونچی آواز سے بات کریں تو سنتا ہے اور آہستہ بات کریں تو نہیں سنتا ۔ تیسرے نے کہا : اگر ہم اونچا بولیں تو وہ سنتا ہے تو پھر ہم آہستہ بولیں تو بھی سنتا ہے ۔ اس پر اللہ عزوجل نے ( یہ آیتیں ) نازل فرمائیں : \" تم اس لیے ( اپنی باتیں ) نہیں چھپا رہے تھے کہ تمہارے خلاف تمہارے کان گواہی دیں گے اور نہ تمہاری آنکھیں اور نہ تمہاری کھالیں ۔","",{"u2":"محمد بن ابی عمر مکی نے ہمیں حدیث بیان کی، کہا: ہمیں سفیان نے منصور سے حدیث بیان کی، انہوں نے مجاہد سے، انہوں نے ابومعمر سے اور انہوں نے حضرت ابن مسعود رضی اللہ عنہ سے روایت کی، کہا: تین آدمی بیت اللہ کے پاس اکٹھے ہوئے، (ان میں سے) دو قریشی تھے اور ایک ثقفی تھا، یا دو ثقفی تھے اور ایک قریشی تھا، ان کے دلوں کا فہم کم تھا، ان کے پیٹوں کی چربی بہت تھی۔ ان میں سے ایک نے کہا: کیا تم سمجھتے ہو کہ جو کچھ ہم کہتے ہیں، اللہ سنتا ہے؟ دوسرے نے کہا: اگر ہم اونچی آواز سے بات کریں تو سنتا ہے اور آہستہ بات کریں تو نہیں سنتا۔ تیسرے نے کہا: اگر ہم اونچا بولیں تو وہ سنتا ہے تو پھر ہم آہستہ بولیں تو بھی سنتا ہے۔ اس پر اللہ عزوجل نے (یہ آیتیں) نازل فرمائیں: \"تم اس لیے (اپنی باتیں) نہیں چھپا رہے تھے کہ تمہارے خلاف تمہارے کان گواہی دیں گے اور نہ تمہاری آنکھیں اور نہ تمہاری کھالیں۔\""}],[7085,"ابوبکر بن خلاد باہلی نے مجھے حدیث بیان کی ، کہا : ہمیں یحیی بن سعید نے حدیث بیان کی ، کہا : ہمیں سفیان نے حدیث بیان کی ، کہا : مجھے سلیمان نے عمارہ بن عمیر سے حدیث بیان کی ، انہوں نے وہب بن ربیعہ سے اور انہوں نے عبداللہ رضی اللہ عنہ سے روایت کی ، نیز ہمیں یحیی نے حدیث بیان کی ، کہا : ہمیں سفیان نے حدیث سنائی ، کہا : مجھے منصور نے مجاہد سے حدیث بیان کی ، انہوں نے ابومعمر سے اور انہوں نے عبداللہ رضی اللہ عنہ سے اسی طرح روایت کی ۔"],[7086,"ابوبکر بن خلاد باہلی نے مجھے حدیث بیان کی ، کہا : ہمیں یحیی بن سعید نے حدیث بیان کی ، کہا : ہمیں سفیان نے حدیث بیان کی ، کہا : مجھے سلیمان نے عمارہ بن عمیر سے حدیث بیان کی ، انہوں نے وہب بن ربیعہ سے اور انہوں نے عبداللہ رضی اللہ عنہ سے روایت کی ، نیز ہمیں یحیی نے حدیث بیان کی ، کہا : ہمیں سفیان نے حدیث سنائی ، کہا : مجھے منصور نے مجاہد سے حدیث بیان کی ، انہوں نے ابومعمر سے اور انہوں نے عبداللہ رضی اللہ عنہ سے اسی طرح روایت کی ۔","",{"u2":") ابوبکر بن خلاد باہلی نے مجھے حدیث بیان کی، کہا: ہمیں یحییٰ بن سعید نے حدیث بیان کی، کہا: ہمیں سفیان نے حدیث بیان کی، کہا: مجھے سلیمان نے عمارہ بن عمیر سے حدیث بیان کی، انہوں نے وہب بن ربیعہ سے اور انہوں نے عبداللہ رضی اللہ عنہ سے روایت کی، نیز ہمیں یحییٰ نے حدیث بیان کی، کہا: ہمیں سفیان نے حدیث سنائی، کہا: مجھے منصور نے مجاہد سے حدیث بیان کی، انہوں نے ابومعمر سے اور انہوں نے عبداللہ رضی اللہ عنہ سے اسی طرح روایت کی۔"}],[7087,"معاذ عنبری نے کہا : ہمیں شعبہ نے عدی بن ثابت سے حدیث بیان کی ، انہوں نے کہا : میں نے عبداللہ بن یزید کو سیدنا زید بن ثابت رضی اللہ عنہ سے حدیث بیان کرتے ہوئے سنا کہ نبی صلی اللہ علیہ وسلم ( جنگ کے لئے ) اُحد کی جانب روانہ ہوئے ۔ جو لوگ آپ کے ساتھ تھے ان میں سے کچھ واپس آ گئے ۔ رسول اللہ صلی اللہ علیہ وسلم کے صحابہ ان کے بارے میں دو حصوں میں تقسیم ہو گئے ۔ بعض نے کہا : ہم انہیں قتل کر دیں اور بعض نے کہا : نہیں ۔ تو ( یہ آیت ) نازل ہوئی : \" تمہیں کیا ہو گیا ہے کہ منافقین کے بارے میں تم وہ دو گروہ بن گئے ہو ۔","",{"u2":"معاذ عنبری نے کہا: ہمیں شعبہ نے عدی بن ثابت سے حدیث بیان کی، انہوں نے کہا: میں نے عبداللہ بن یزید کو حضرت زید بن ثابت رضی اللہ عنہ سے حدیث بیان کرتے ہوئے سنا کہ نبی صلی اللہ علیہ وسلم (جنگ کے لئے) اُحد کی جانب روانہ ہوئے۔ جو لوگ آپ کے ساتھ تھے ان میں سے کچھ واپس آ گئے۔ رسول اللہ صلی اللہ علیہ وسلم کے صحابہ ان کے بارے میں دو حصوں میں تقسیم ہو گئے۔ بعض نے کہا: ہم انہیں قتل کر دیں اور بعض نے کہا: نہیں۔ تو (یہ آیت) نازل ہوئی: \"تمہیں کیا ہو گیا ہے کہ منافقین کے بارے میں تم وہ دو گروہ بن گئے ہو۔\""}],[7088,"یحیی بن سعید اور غندر دونوں نے شعبہ سے اسی سند کے ساتھ اسی کے مانند روایت کی ۔","",{"u2":"یحییٰ بن سعید اور غندر دونوں نے شعبہ سے اسی سند کے ساتھ اسی کے مانند روایت کی۔"}],[7089,"سیدنا ابوسعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے عہد میں کچھ منافقین ایسے تھے کہ جب نبی صلی اللہ علیہ وسلم کسی جنگ کے لئے تشریف لے جاتے تو وہ پیچھے رہ جاتے اور رسول اللہ صلی اللہ علیہ وسلم کی مخالفت میں اپنے پیچھے رہ جانے پر خوش ہوتے ، اور جب نبی صلی اللہ علیہ وسلم واپس آتے تو آپ کے سامنے عذر بیان کرتے اور قسمیں کھاتے اور چاہتے کہ لوگ ان کاموں پر ان کی تعریف کریں جو انہوں نے نہیں کیے تھے ، اس پر یہ ( آیت نازل ) ہوئی : \" ان لوگوں کے متعلق گمان نہ کرو جو اپنے کیے پر خوش ہوتے ہیں اور یہ پسند کرتے ہیں کہ اس کام پر ان کی تعریف کی جائے جو انہوں نے نہیں کیا ، ان کے متعلق یہ گمان بھی نہ کرو کہ وہ عذاب سے بچنے والے مقام پر ہوں گے ۔","",{"u2":") حضرت ابوسعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے عہد میں کچھ منافقین ایسے تھے کہ جب نبی صلی اللہ علیہ وسلم کسی جنگ کے لئے تشریف لے جاتے تو وہ پیچھے رہ جاتے اور رسول اللہ صلی اللہ علیہ وسلم کی مخالفت میں اپنے پیچھے رہ جانے پر خوش ہوتے، اور جب نبی صلی اللہ علیہ وسلم واپس آتے تو آپ کے سامنے عذر بیان کرتے اور قسمیں کھاتے اور چاہتے کہ لوگ ان کاموں پر ان کی تعریف کریں جو انہوں نے نہیں کیے تھے، اس پر یہ (آیت نازل) ہوئی: \"ان لوگوں کے متعلق گمان نہ کرو جو اپنے کیے پر خوش ہوتے ہیں اور یہ پسند کرتے ہیں کہ اس کام پر ان کی تعریف کی جائے جو انہوں نے نہیں کیا، ان کے متعلق یہ گمان بھی نہ کرو کہ وہ عذاب سے بچنے والے مقام پر ہوں گے۔\""}],[7090,"ابن جریج سے روایت ہے ، انہوں نے کہا : مجھے ابن ابی ملیکہ نے بتایا ، انہیں حمید بن عبدالرحمن بن عوف نے خبر دی کہ مروان نے اپنے دربان سے کہا : \" رافع! سیدنا ابن عباس رضی اللہ عنہ کے پاس جاؤ اور کہو کہ اگر یہ بات ہے کہ ہم میں سے ہر شخص جو اپنے کیے پر خوش ہوتا ہے اور ہر ایک جو یہ پسند کرتا ہے کہ جو اس نے نہیں کیا ، اس پر اس کی تعریف کی جائے ، اس کو عذاب ہو گا تو ہم سب ہی ضرور عذاب میں ڈالے جائیں گے ۔ تو سیدنا ابن عباس رضی اللہ عنہ نے فرمایا : تم لوگوں کا اس آیت سے کیا تعلق ( بنتا ) ہے؟ یہ آیت اہل کتاب کے بارے میں اتری تھی ، پھر سیدنا ابن عباس رضی اللہ عنہ نے ( اس سے پہلی ) یہ آیت پڑھی : \" اور جب اللہ نے ان لوگوں کا ، جنہیں کتاب دی گئی تھی ، عہد لیا کہ تم اسے لوگوں کے سامنے کھول کر بیان کرو گے اور اس کو چھپاؤ گے نہیں ۔ \" پھر ابن عباس رضی اللہ عنہ نے ( اس کے بعد والی ) آیت تلاوت فرمائی : \" ان لوگوں کے بارے میں گمان نہ کرو جو اپنے کیے پر خوش ہوتے ہیں اور پسند کرتے ہیں کہ اس کام پر ان کی تعریف کی جائے جو انہوں نے نہیں کیا ۔ \" اور سیدنا ابن عباس رضی اللہ عنہ نے فرمایا : نبی صلی اللہ علیہ وسلم نے ان سے ( ان کی کتاب میں لکھی ہوئی ) کسی چیز کے بارے میں پوچھا تو انہوں نے آپ سے وہ چیز چھپا لی اور ( اس کے بجائے ) ایک دوسری بات بتا دی اور وہ اس طرح نکلے کہ انہوں نے آپ صلی اللہ علیہ وسلم کے سامنے یہ ظاہر کیا کہ آپ صلی اللہ علیہ وسلم نے ان سے جو پوچھا تھا ، انہوں نے آپ صلی اللہ علیہ وسلم کو وہی بتا دیا ہے اور اس بات پر انہوں نے آپ صلی اللہ علیہ وسلم سے تعریف بھی بٹورنی چاہی اور جو بات آپ نے ان سے پوچھی وہ بات چھپا کر انہوں نے جو کچھ لیا تھا اس پر ( اپنے دلوں میں ) خوش بھی ہوئے ۔","",{"u2":"ابن جریج سے روایت ہے، انہوں نے کہا: مجھے ابن ابی ملیکہ نے بتایا، انہیں حمید بن عبدالرحمن بن عوف نے خبر دی کہ مروان نے اپنے دربان سے کہا: \"رافع! حضرت ابن عباس رضی اللہ عنہ کے پاس جاؤ اور کہو کہ اگر یہ بات ہے کہ ہم میں سے ہر شخص جو اپنے کیے پر خوش ہوتا ہے اور ہر ایک جو یہ پسند کرتا ہے کہ جو اس نے نہیں کیا، اس پر اس کی تعریف کی جائے، اس کو عذاب ہو گا تو ہم سب ہی ضرور عذاب میں ڈالے جائیں گے۔ تو حضرت ابن عباس رضی اللہ عنہ نے فرمایا: تم لوگوں کا اس آیت سے کیا تعلق (بنتا) ہے؟ یہ آیت اہل کتاب کے بارے میں اتری تھی، پھر حضرت ابن عباس رضی اللہ عنہ نے (اس سے پہلی) یہ آیت پڑھی: \"اور جب اللہ نے ان لوگوں کا، جنہیں کتاب دی گئی تھی، عہد لیا کہ تم اسے لوگوں کے سامنے کھول کر بیان کرو گے اور اس کو چھپاؤ گے نہیں۔\" پھر ابن عباس رضی اللہ عنہ نے (اس کے بعد والی) آیت تلاوت فرمائی: \"ان لوگوں کے بارے میں گمان نہ کرو جو اپنے کیے پر خوش ہوتے ہیں اور پسند کرتے ہیں کہ اس کام پر ان کی تعریف کی جائے جو انہوں نے نہیں کیا۔\" اور حضرت ابن عباس رضی اللہ عنہ نے فرمایا: نبی صلی اللہ علیہ وسلم نے ان سے (ان کی کتاب میں لکھی ہوئی) کسی چیز کے بارے میں پوچھا تو انہوں نے آپ سے وہ چیز چھپا لی اور (اس کے بجائے) ایک دوسری بات بتا دی اور وہ اس طرح نکلے کہ انہوں نے آپ صلی اللہ علیہ وسلم کے سامنے یہ ظاہر کیا کہ آپ صلی اللہ علیہ وسلم نے ان سے جو پوچھا تھا، انہوں نے آپ صلی اللہ علیہ وسلم کو وہی بتا دیا ہے اور اس بات پر انہوں نے آپ صلی اللہ علیہ وسلم سے تعریف بھی بٹورنی چاہی اور جو بات آپ نے ان سے پوچھی وہ بات چھپا کر انہوں نے جو کچھ لیا تھا اس پر (اپنے دلوں میں) خوش بھی ہوئے۔"}],[7091,"اسود بن عامر نے کہا : ہمیں شعبہ بن حجاج نے قتادہ سے حدیث بیان کی ، انہوں نے ابونضرہ سے اور انہوں نے قیس ( بن عباد ) سے روایت کی ، انہوں نے کہا : میں نے سیدنا عمار رضی اللہ عنہ سے کہا : آپ نے اپنے اس کام پر غور کیا جو آپ نے سیدنا علی رضی اللہ عنہ کے معاملے میں کیا ہے ( ان کا بھرپور ساتھ دیا ہے اور ان کے مخالفین سے جنگ تک کی ہے ) یہ آپ کے اپنے غوروفکر سے اختیار کی ہوئی آپ کی رائے تھی یا ایسی چیز تھی جس کی ذمہ داری رسول اللہ صلی اللہ علیہ وسلم نے آپ لوگوں کے سپرد کی تھی؟ انہوں نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے کوئی ایسی ذمہ داری ہمارے سپرد نہیں کی جو انہوں نے تمام لوگوں کے سپرد نہ کی ہو لیکن سیدنا حذیفہ رضی اللہ عنہ نے مجھے نبی صلی اللہ علیہ وسلم سے خبر دی ، کہا : نبی صلی اللہ علیہ وسلم نے فرمایا : \" میرے ساتھیوں میں سے بارہ افراد منافق ہیں ، ان میں سے آٹھ ایسے ہیں جو جنت میں داخل نہیں ہوں گے یہاں تک کہ اونٹ سوئی کے ناکے میں داخل ہو جائے ( کبھی داخل نہیں ہوں گے ) ، ان میں آٹھ ایسے ہیں ( کہ ان کے شر سے نجات کے لیے ان کے کندھوں کے درمیان ظاہر ہونے والا سرخ ) پھوڑا تمہاری نجات کے لیے تمہیں کفایت کرے گا ۔ اور چار ۔ \" ( آگے کا حصہ ) مجھے ( اسود بن عامر کو ) یاد نہیں کہ شعبہ نے ان ( چار ) کے بارے میں کیا کہا تھا ۔","",{"u2":"اسود بن عامر نے کہا: ہمیں شعبہ بن حجاج نے قتادہ سے حدیث بیان کی، انہوں نے ابونضرہ سے اور انہوں نے قیس (بن عباد) سے روایت کی، انہوں نے کہا: میں نے حضرت عمار رضی اللہ عنہ سے کہا: آپ نے اپنے اس کام پر غور کیا جو آپ نے حضرت علی رضی اللہ عنہ کے معاملے میں کیا ہے (ان کا بھرپور ساتھ دیا ہےاور ان کے مخالفین سے جنگ تک کی ہے) یہ آپ کے اپنے غوروفکر سے اختیار کی ہوئی آپ کی رائے تھی یا ایسی چیز تھی جس کی ذمہ داری رسول اللہ صلی اللہ علیہ وسلم نے آپ لوگوں کے سپرد کی تھی؟ انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے کوئی ایسی ذمہ داری ہمارے سپرد نہیں کی جو انہوں نے تمام لوگوں کے سپرد نہ کی ہو لیکن حضرت حذیفہ رضی اللہ عنہ نے مجھے نبی صلی اللہ علیہ وسلم سے خبر دی، کہا: نبی صلی اللہ علیہ وسلم نے فرمایا: \"میرے ساتھیوں میں سے بارہ افراد منافق ہیں، ان میں سے آٹھ ایسے ہیں جو جنت میں داخل نہیں ہوں گے یہاں تک کہ اونٹ سوئی کے ناکے میں داخل ہو جائے (کبھی داخل نہیں ہوں گے)، ان میں آٹھ ایسے ہیں (کہ ان کے شر سے نجات کے لیے ان کے کندھوں کے درمیان ظاہر ہونے والا سرخ) پھوڑا تمہاری نجات کے لیے تمہیں کفایت کرے گا۔ اور چار۔\" (آگے کا حصہ) مجھے (اسود بن عامر کو) یاد نہیں کہ شعبہ نے ان (چار) کے بارے میں کیا کہا تھا۔"}],[7092,"محمد بن جعفر ( غندر ) نے کہا؛ ہمیں شعبہ نے قتادہ سے حدیث بیان کی ، انہوں نے ابونضرہ سے اور انہوں نے قیس بن عباد سے روایت کی ، انہوں نے کہا : ہم لوگوں نے سیدنا عمار رضی اللہ عنہ سے کہا : آپ ( سیدنا علی رضی اللہ عنہ کی حمایت میں ) اپنی جنگ کو کیسے دیکھتے ہیں ، کیا یہ ایک رائے ہے جو آپ نے غوروفکر سے اختیار کی ہے؟ تو رائے غلط بھی ہو سکتی ہے اور صحیح بھی ، یا کوئی ذمہ داری ہے جو رسول اللہ صلی اللہ علیہ وسلم نے ہمیں کوئی ایسی ( خصوصی ) ذمہ داری نہیں دی تھی جو تمام لوگوں کے سپرد نہ کی ہو اور کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا : \"\" بےشک میری امت میں ۔ ۔ ۔ \"\" شعبہ نے کہا : اور میں سمجھتا ہوں کہ انہوں نے کہا تھا : مجھے حذیفہ رضی اللہ عنہ نے ( یہ ) حدیث سنائی ۔ اور غندر نے کہا : مجھے لگتا ہے کہ انہوں نے کہا : \"\" میری امت میں بارہ منافق ہیں ، وہ جنت میں داخل نہ ہوں گے اور نہ اس کی خوشبو پائیں گے ، جب تک کہ اونٹ سوئی کے ناکے میں داخل نہ ہو جائے ۔ ان میں سے آٹھ ایسے ہیں ( کہ ان کے شر سے بچاؤ کے لیے ) تمہاری کفایت ایک ایسا پھوڑا کرے گا جو آگ کے جلتے ہوئے دیے کی طرح ( اوپر سے سرک ) ہو گا ، ان کے کندھوں میں طاہر ہو گا یہاں تک کہ ان کے سینوں سے نکل آئے گا ۔","",{"u2":"محمد بن جعفر (غندر) نے کہا؛ ہمیں شعبہ نے قتادہ سے حدیث بیان کی، انہوں نے ابونضرہ سے اور انہوں نے قیس بن عباد سے روایت کی، انہوں نے کہا: ہم لوگوں نے حضرت عمار رضی اللہ عنہ سے کہا: آپ (حضرت علی رضی اللہ عنہ کی حمایت میں) اپنی جنگ کو کیسے دیکھتے ہیں، کیا یہ ایک رائے ہے جو آپ نے غوروفکر سے اختیار کی ہے؟ تو رائے غلط بھی ہو سکتی ہے اور صحیح بھی، یا کوئی ذمہ داری ہے جو رسول اللہ صلی اللہ علیہ وسلم نے ہمیں کوئی ایسی (خصوصی) ذمہ داری نہیں دی تھی جو تمام لوگوں کے سپرد نہ کی ہو اور کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا: \"بےشک میری امت میں۔۔۔\"\nشعبہ نے کہا: اور میں سمجھتا ہوں کہ انہوں نے کہا تھا: مجھے حذیفہ رضی اللہ عنہ نے (یہ) حدیث سنائی۔\nاور غندر نے کہا: مجھے لگتا ہے کہ انہوں نے کہا: \"میری امت میں بارہ منافق ہیں، وہ جنت میں داخل نہ ہوں گے اور نہ اس کی خوشبو پائیں گے، جب تک کہ اونٹ سوئی کے ناکے میں داخل نہ ہو جائے۔ ان میں سے آٹھ ایسے ہیں (کہ ان کے شر سے بچاؤ کے لیے) تمہاری کفایت ایک ایسا پھوڑا کرے گا جو آگ کے جلتے ہوئے دیے کی طرح (اوپر سے سرک) ہو گا، ان کے کندھوں میں طاہر ہو گا یہاں تک کہ ان کے سینوں سے نکل آئے گا۔\""}],[7093,"ولید بن جمیع نے کہا : ہمیں ابوطفیل رضی اللہ عنہ نے حدیث بیان کی ، انہوں نے کہا : عقبہ والوں میں سے ایک شخص اور سیدنا حذیفہ رضی اللہ عنہ کے درمیان ( اس طرح کا ) جھگڑا ہو گیا جس طرح لوگوں کے درمیان ہو جاتا ہے ۔ ( گفتگو کے دوران میں ) انہوں نے ( اس شخص سے ) کہا : میں تمہیں اللہ کی قسم دے کر پوچھتا ہوں کہ عقبہ والوں کی تعداد کتنی تھی؟ ( سیدنا ابوطفیل رضی اللہ عنہ نے ) کہا : لوگوں نے اس سے کہا : جب وہ آپ سے پوچھ رہے ہیں تو انہیں بتاؤ ۔ ( پھر سیدنا حذیفہ رضی اللہ عنہ نے خود ہی جواب دیتے ہوئے ) کہا : ہمیں بتایا جاتا تھا کہ وہ چودہ لوگ تھے اور اگر تم بھی ان میں شامل تھے تو وہ کل پندرہ لوگ تھے اور میں گواہی دیتا ہوں کہ ان میں سے بارہ دنیا کی زندگی میں بھی اللہ اور اس کے رسول صلی اللہ علیہ وسلم کے خلاف جنگ میں تھے اور ( آخرت میں بھی ) جب گواہ کھڑے ہوں گے ۔ اور آپ صلی اللہ علیہ وسلم نے ان تین لوگوں کا عذر قبول فرما لیا تھا جنہوں نے کہا تھا کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کے اعلان کرنے والے کا اعلان نہیں سنا تھا اور اس بات سے بھی بے خبر تھے کہ ان لوگوں کا ارادہ کیا ہے جبکہ آپ صلی اللہ علیہ وسلم اس وقت حرہ میں تھے ، آپ چل پڑے اور فرمایا : \" پانی کم ہے ، اس لیے مجھ سے پہلے وہاں کوئی نہ پہنچے ۔ \" چنانچہ آپ صلی اللہ علیہ وسلم نے ( وہاں پہنچ کر ) دیکھا کہ کچھ لوگ آپ سے پہلے وہاں پہنچ گئے ہیں تو آپ نے اس روز ان پر لعنت کی ۔","",{"u2":"ولید بن جمیع نے کہا: ہمیں ابوطفیل رضی اللہ عنہ نے حدیث بیان کی، انہوں نے کہا: عقبہ والوں میں سے ایک شخص اور حضرت حذیفہ رضی اللہ عنہ کے درمیان (اس طرح کا) جھگڑا ہو گیا جس طرح لوگوں کے درمیان ہو جاتا ہے۔ (گفتگو کے دوران میں) انہوں نے (اس شخص سے) کہا: میں تمہیں اللہ کی قسم دے کر پوچھتا ہوں کہ عقبہ والوں کی تعداد کتنی تھی؟ (حضرت ابوطفیل رضی اللہ عنہ نے) کہا: لوگوں نے اس سے کہا: جب وہ آپ سے پوچھ رہے ہیں تو انہیں بتاؤ۔ (پھر حضرت حذیفہ رضی اللہ عنہ نے خود ہی جواب دیتے ہوئے) کہا: ہمیں بتایا جاتا تھا کہ وہ چودہ لوگ تھے اور اگر تم بھی ان میں شامل تھے تو وہ کل پندرہ لوگ تھے اور میں گواہی دیتا ہوں کہ ان میں سے بارہ دنیا کی زندگی میں بھی اللہ اور اس کے رسول صلی اللہ علیہ وسلم کے خلاف جنگ میں تھے اور (آخرت میں بھی) جب گواہ کھڑے ہوں گے۔ اور آپ صلی اللہ علیہ وسلم نے ان تین لوگوں کا عذر قبول فرما لیا تھا جنہوں نے کہا تھا کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کے اعلان کرنے والے کا اعلان نہیں سنا تھا اور اس بات سے بھی بے خبر تھے کہ ان لوگوں کا ارادہ کیا ہے جبکہ آپ صلی اللہ علیہ وسلم اس وقت حرہ میں تھے، آپ چل پڑے اور فرمایا: \"پانی کم ہے، اس لیے مجھ سے پہلے وہاں کوئی نہ پہنچے۔\" چنانچہ آپ صلی اللہ علیہ وسلم نے (وہاں پہنچ کر) دیکھا کہ کچھ لوگ آپ سے پہلے وہاں پہنچ گئے ہیں تو آپ نے اس روز ان پر لعنت کی۔"}],[7094,"معاذ عنبری نے کہا : ہمیں قروہ بن خالد نے ابو زبیر سے حدیث بیان کی ، انھوں نے سیدنا جابر بن عبداللہ رضی اللہ تعالی عنہ سےروایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" کون ہے جو اس گھاٹی ( یعنی ) مرار کی گھاٹی پرچڑھے گا!بے شک اس کے گناہ بھی اسی طرح جھڑ جائیں گے جس طرح بنی اسرائیل کے گناہ جھڑ گئے تھے ۔ \"\" ( سیدنا جابر رضی اللہ تعالی عنہ نے ) کہا : تو سب سے پہلے جو اس گھاٹی پر چڑھے وہ ہمارے بنو خزرج کے گھوڑ ے تھے ، پھر لوگوں کا تانتابندھ گیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" تم سب وہ ہو جن کے گناہ بخش دیئے گئے ، سوائے سرخ اونٹ والے شخص کے ۔ \"\" ہم اس کے پاس آئے اور ( اس سے ) کہا : آؤ رسول اللہ صلی اللہ علیہ وسلم تمہارے لئے بھی استغفار فرمائیں ۔ اس نے کہا : اللہ کی قسم!اگر میں اپنی گم شدہ چیز پالوں تو یہ بات مجھے اس کی نسبت زیادہ پسند ہے کہ تمہارا صاحب میرے لئے مغفرت کی دعا کرے ۔ ( سیدنا جابر رضی اللہ تعالی عنہ نے ) کہا : وہ آدمی اس وقت اپنی سے کم شدہ چیز کو ڈھونڈنے کے لئے آوازیں لگا رہا تھا ۔","",{"u2":"معاذ عنبری نے کہا:ہمیں قروہ بن خالد نے ابو زبیر سے حدیث بیان کی،انھوں نے حضرت جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سےروایت کی،کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"کون ہے جو اس گھاٹی(یعنی)مرار کی گھاٹی پرچڑھے گا!بے شک اس کے گناہ بھی اسی طرح جھڑ جائیں گے جس طرح بنی اسرائیل کے گناہ جھڑ گئے تھے۔\"\n(حضرت جابر رضی اللہ تعالیٰ عنہ نے)کہا:تو سب سے پہلے جو اس گھاٹی پر چڑھے وہ ہمارے بنو خزرج کے گھوڑ ے تھے،پھر لوگوں کا تانتابندھ گیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"تم سب وہ ہو جن کے گناہ بخش دیئے گئے،سوائے سرخ اونٹ والے شخص کے۔\"ہم اس کے پاس آئے اور(اس سے) کہا:آؤ رسول اللہ صلی اللہ علیہ وسلم تمہارے لئے بھی استغفار فرمائیں۔اس نے کہا:اللہ کی قسم!اگر میں اپنی گم شدہ چیز پالوں تو یہ بات مجھے اس کی نسبت زیادہ پسند ہے کہ تمہارا صاحب میرے لئے مغفرت کی دعا کرے۔\n(حضرت جابر رضی اللہ تعالیٰ عنہ نے)کہا:وہ آدمی اس وقت اپنی سے کم شدہ چیز کو ڈھونڈنے کے لئے آوازیں لگارہا تھا۔"}],[7095,"یحیی بن حبیب حارثی نے ہمیں یہی حدیث بیان کی ، کہا : ہمیں خالد بن حارث نے حدیث بیان کی ، کہا : ہمیں قرہ نے حدیث بیان کی ، انھوں نے کہا : ہمیں ابو زبیر نے سیدنا جابر بن عبداللہ رضی اللہ تعالی عنہ سے روایت کی ، انھوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کون ہےجو مراد مرار یا مرار کی گھاٹی پر چڑھے گا ۔ \" ( آگے ) معاذ عنبری کی حدیث کے مانند ، البتہ ( اس حدیث میں ) انھوں نے کہا : اور وہ ایک اعرابی تھا جو اپنی گم شدہ چیز ڈھونڈنے کے لئے اعلان کرنے کے لئے آیا تھا ۔","",{"u2":"یحییٰ بن حبیب حارثی نے ہمیں یہی حدیث بیان کی،کہا:ہمیں خالد بن حارث نےحدیث بیان کی،کہا:ہمیں قرہ نے حدیث بیان کی،انھوں نے کہا:ہمیں ابو زبیر نے حضرت جابر بن عبداللہ رضی اللہ تعالیٰ عنہ سے روایت کی،انھوں نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"کون ہےجو مراد مرار یا مرار کی گھاٹی پر چڑھے گا۔\"(آگے)معاذ عنبری کی حدیث کے مانند،البتہ(اس حدیث میں) انھوں نے کہا:اور وہ ایک اعرابی تھا جو اپنی گم شدہ چیز ڈھونڈنے کے لئے اعلان کرنے کے لئے آیا تھا۔"}],[7096,"سیدنا انس بن مالک رضی اللہ تعالی عنہ سے روایت ہے ، کہا : ہم بنو نجار میں سے ایک شخص تھا ، اس نے سورہ بقرہ اور سورہ آل عمران پڑھی ( یاد کی ) ہوئی تھی اور وہ رسول اللہ صلی اللہ علیہ وسلم کے لئے کتابت کیا کرتا تھا ، وہ بھاگ کر چلا گیا اور اہل کتاب کے ساتھ شامل ہوگیا ، انھوں نے اس کو بہت اونچا اٹھایا اور کہا : یہ ہے جو محمد ( صلی اللہ علیہ وسلم ) کے لئے کتابت کرتا تھا وہ اس کے آنے سے بہت خوش ہوئے ، تھوڑے ہی دن گزرے کہ اللہ تعالی نے ان کے بیچ میں ( ہوتے ہوئے ) اس کی گردن توڑ دی ۔ انھوں نے اس کے لیے قبر کھودی اور اسے دفن کردیا ۔ صبح ہوئی تو زمین نے اسے اپنی سطح کے ا وپر پھینک دیا تھا ۔ انھوں نے دوبارہ وہی کیا ، اس کی قبر کھودی اور اسے دفن کردیا ۔ پھر صبح ہوئی تو زمین نے اسے باہر پھینک دیا تھا ، انھوں نے پھر ( تیسری بار ) اسی طرح کیا ، اس کے لئے قبر کھودی اور اسے دفن کردیا ، صبح کو زمین نے اسے باہر پھینک دیا ہواتھا تو انھوں نے اسے اسی طرح پھینکا ہوا چھوڑ دیا ۔","",{"u2":"حضرت انس بن مالک رضی اللہ تعالیٰ عنہ سے روایت ہے،کہا:ہم بنو نجار میں سے ایک شخص تھا،اس نے سورہ بقرہ اور سورہ آل عمران پڑھی(یاد کی) ہوئی تھی اور وہ رسول اللہ صلی اللہ علیہ وسلم کے لئے کتابت کیا کرتا تھا،وہ بھاگ کر چلا گیا اور اہل کتاب کے ساتھ شامل ہوگیا،انھوں نے اس کو بہت اونچا اٹھایا اور کہا:یہ ہے جو محمد(صلی اللہ علیہ وسلم) کے لئے کتابت کرتا تھا وہ اس کے آنے سے بہت خوش ہوئے،تھوڑے ہی دن گزرے کہ اللہ تعالیٰ نے ان کے بیچ میں(ہوتے ہوئے) اس کی گردن توڑ دی۔انھوں نے اس کے لیے قبر کھودی اور اسے دفن کردیا۔صبح ہوئی تو زمین نے اسے اپنی سطح کے ا وپر پھینک دیا تھا۔ انھوں نے دوبارہ وہی کیا،اس کی قبر کھودی اور اسے دفن کردیا۔پھر صبح ہوئی تو زمین نے اسے باہر پھینک دیا تھا،انھوں نے پھر(تیسری بار) اسی طرح کیا،اس کے لئے قبر کھودی اور اسے دفن کردیا،صبح کو زمین نے اسے باہر پھینک دیا ہواتھا تو انھوں نے اسے اسی طرح پھینکا ہوا چھوڑ دیا۔"}],[7097,"سیدنا جابر رضی اللہ تعالی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم ایک سفر سے و اپس آئے ، جب آپ صلی اللہ علیہ وسلم مدینہ منورہ کے قریب تھے تو اتنے زور کی آندھی چلی کہ قریب تھا وہ سوار کو بھی ( ریت میں ) دفن کردے گی ۔ تو وہ ( جابر رضی اللہ تعالی عنہ ) یقین سے کہتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا : \" یہ آندھی کسی منافق کی موت کے لئے بھیجی گئی ہے \" جب آ پ مدینہ منورہ تشریف لے آئے تو منافقوں میں سے ایک بہت بڑا منافق مرچکا تھا ۔","",{"u2":"حضرت جابر رضی اللہ تعالیٰ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم ایک سفر سے و اپس آئے،جب آپ صلی اللہ علیہ وسلم مدینہ منورہ کے قریب تھے تو اتنے زور کی آندھی چلی کہ قریب تھا وہ سوار کو بھی(ریت میں) دفن کردے گی۔تو وہ(جابر رضی اللہ تعالیٰ عنہ) یقین سے کہتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا:\"یہ آندھی کسی منافق کی موت کے لئے بھیجی گئی ہے\"جب آ پ مدینہ منورہ تشریف لے آئے تو منافقوں میں سے ایک بہت بڑا منافق مرچکا تھا۔"}],[7098,"ایاس ( بن سلمہ بن اکوع ) نے ہمیں حدیث بیان کی ، کہا : مجھے میرے والد نے حدیث بیان کی ، انھوں نے کہا : ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک شخص کی ، جسے بخار چڑھا ہوا تھا ، عیادت کی ، کہا : میں نے اس ( کےجسم ) پر اپنا ہاتھ رکھا تو میں نے کہا : اللہ کی قسم! میں نے آج کی طرح کسی شخص کو نہیں دیکھا جو اس سے زیادہ تپ رہا ہو ، تو اللہ کے نبی صلی اللہ علیہ وسلم نے فرمایا : \" کیا میں تمھیں قیامت کے دن اس سے بھی زیادہ تپتے ہوؤں کے بارے میں نہ بتاؤں؟یہ دونوں شخص جو ( اونٹوں پر ) سوار ہیں ، اپنے منہ دوسری طرف کیے ہوئے ہیں ۔ \" ( آپ نے یہ بات ) دو آدمیوں کے بارے میں ( فرمائی ) جو اس وقت ( ظاہر طور ) آپ کے ساتھیوں میں ( شمار ہوتے ) تھے ۔","",{"u2":"ایاس(بن سلمہ بن اکوع) نے ہمیں حدیث بیان کی،کہا:مجھے میرے والد نے حدیث بیان کی،انھوں نے کہا:ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک شخص کی،جسے بخار چڑھا ہوا تھا،عیادت کی،کہا:میں نے اس(کےجسم) پر اپنا ہاتھ رکھا تو میں نے کہا:اللہ کی قسم! میں نے آج کی طرح کسی شخص کو نہیں دیکھا جو اس سے زیادہ تپ رہا ہو،تو اللہ کے نبی صلی اللہ علیہ وسلم نے فرمایا:\"کیا میں تمھیں قیامت کے دن اس سے بھی زیادہ تپتے ہوؤں کے بارے میں نہ بتاؤں؟یہ دونوں شخص جو(اونٹوں پر) سوار ہیں،اپنے منہ دوسری طرف کیے ہوئے ہیں۔\"(آپ نے یہ بات) دو آدمیوں کے بارے میں(فرمائی) جو اس وقت(ظاہر طور) آپ کے ساتھیوں میں(شمار ہوتے) تھے۔"}],[7099,"عبیداللہ نے نافع سے ، انھوں نے سیدنا ابن عمر رضی اللہ تعالی عنہ سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" منافق کی مثال اس بکری کی طرح ہے جو بکریوں کے دو ریوڑوں کے درمیان ممیاتی ہوئی بھاگی پھرتی ہے کبھی بھاگ کر اس ریوڑ میں جاتی ہے اور کبھی اس طرف جاتی ہے ( کسی بھی ایک ریوڑ کا حصہ نہیں ہوتی ۔)","",{"u2":"عبیداللہ نے نافع سے،انھوں نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\" منافق کی مثال اس بکری کی طرح ہے جو بکریوں کے دو ریوڑوں کے درمیان ممیاتی ہوئی بھاگی پھرتی ہے کبھی بھاگ کر اس ریوڑ میں جاتی ہے اور کبھی اس طرف جاتی ہے (کسی بھی ایک ریوڑ کا حصہ نہیں ہوتی۔)"}],[7100,"موسی بن عقبہ نے نافع سے ، انھوں نے سیدنا ابن عمر رضی اللہ تعالی عنہ سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی ، مگر انھوں نے کہا : \" پلٹ کر ایک باراس ( ریوڑ ) میں آتی ہے اور دوسری بار اس میں ۔","",{"u2":"موسیٰ بن عقبہ نے نافع سے،انھوں نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی،مگر انھوں نے کہا:\" پلٹ کر ایک باراس(ریوڑ) میں آتی ہے اور دوسری بار اس میں۔\""}],[7101,"سیدنا ابو ہریرۃ رضی اللہ تعالی عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" ( قیامت کے دن ایک بہت بڑا ( اور ) موٹا آدمی آئے گا ، ( لیکن ) اللہ تعالی کے نزدیک وہ ( وزن میں ) مچھر کے پر کے برابر بھی نہ ہوگا ( یہ آیت ) پڑھ لو : \" پس ہم قیامت کے دن ان کے لئے کوئی وزن قائم نہیں کریں گے ۔","",{"u2":"حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\"(قیامت کے دن ایک بہت بڑا(اور) موٹا آدمی آئے گا،(لیکن) اللہ تعالیٰ کے نزدیک وہ(وزن میں) مچھر کے پر کے برابر بھی نہ ہوگا(یہ آیت) پڑھ لو:\"پس ہم قیامت کے دن ان کے لئے کوئی وزن قائم نہیں کریں گے۔\""}],[7102,"افضیل بن عیاض نے منصور سے ، انھوں نے ابراہیم سے ، انھوں نے عبیدہ سلمانی سے اور انھوں نے سیدنا عبداللہ بن مسعود رضی اللہ تعالی عنہ سے روایت کی ، کہا : ایک یہودی عالم نبی کریم صلی اللہ علیہ وسلم کے پاس آیا اور کہا : اے محمد ( صلی اللہ علیہ وسلم ) یا کہا : ابو القاسم! بے شک اللہ تعالی قیامت کے دن آسمانوں کو ایک انگلی پر رکھ لے گا ، اور زمینوں کو ایک انگلی پر ، اور پہاڑوں اور درختوں کو ایک انگلی پر اور پانی اور گیلی مٹی کو ایک انگلی پر اور تمام مخلوق کو ایک انگلی پر تھام لے گا ، پھر ان کو بلائے گا اور فرمائے گا : \" بادشاہ میں ہوں ، بادشاہ میں ہوں ۔ \" رسول اللہ صلی اللہ علیہ وسلم اس یہودی عالم کی بات پر تعجب اور اس کے تصدیق کرتے ہوئےہنسے ، پھر آپ نے ( یہ آیت ) پڑھی : \" انھوں نے اس طرح اللہ کی قدر نہیں کی جس طرح اس کی قدر کرنے کا حق ہے ۔ ساری زمین اور سب کے سب آسمان قیامت کے دن اس کے دائیں ہاتھ میں لپٹے ہوئے ہوں گے ۔ وہ ( ہراس چیز کی شراکت سے ) پاک اور بلند ہے جنھیں وہ ( اس کے ساتھ ) شریک کر تے ہیں ۔","",{"u2":"افضیل بن عیاض نے منصور سے،انھوں نے ابراہیم سے،انھوں نے عبیدہ سلمانی سے اور انھوں نے حضرت عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ سے روایت کی،کہا:ایک یہودی عالم نبی کریم صلی اللہ علیہ وسلم کے پاس آیا اور کہا:اے محمد(صلی اللہ علیہ وسلم) یا کہا:ابو القاسم! بے شک اللہ تعالیٰ قیامت کے دن آسمانوں کو ایک انگلی پر رکھ لے گا،اور زمینوں کو ایک انگلی پر،اور پہاڑوں اور درختوں کو ایک انگلی پر اورپانی اور گیلی مٹی کو ایک انگلی پر اور تمام مخلوق کو ایک انگلی پر تھام لے گا،پھر ان کو بلائے گا اور فرمائے گا:\" بادشاہ میں ہوں،بادشاہ میں ہوں۔\"رسول اللہ صلی اللہ علیہ وسلم اس یہودی عالم کی بات پر تعجب اور اس کے تصدیق کرتے ہوئےہنسے،پھر آپ نے(یہ آیت) پڑھی:\"انھوں نے اس طرح اللہ کی قدر نہیں کی جس طرح اس کی قدر کرنے کا حق ہے۔ساری زمین اور سب کے سب آسمان قیامت کے دن اس کے دائیں ہاتھ میں لپٹے ہوئے ہوں گے۔وہ(ہراس چیز کی شراکت سے) پاک اور بلند ہے جنھیں وہ(اس کے ساتھ) شریک کر تے ہیں۔\""}],[7103,"جریر نے منصور سے اسی سند کے ساتھ روایت کی ، کہا : یہود میں سے ایک عالم رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا ، فضیل کی حدیث کے مانند ، اور اس میں یہ بیان نہیں کیا : \"\" وہ ( اللہ ) ان ( انگلیوں ) کو ہلائے گا ۔ \"\" اور ( سیدنا عبداللہ بن مسعود رضی اللہ تعالی عنہ نے ) کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو د یکھا ، آپ اس بات پر تعجب سے اس کی تصدیق کرتے ہوئے ( اس طرح ) ہنسے کہ آپ سے پچھلے دندان مبارک ظاہر ہوگئے ، پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" انھوں نے ( اس طرح ) اللہ کی قدر نہیں کی ( جس طرح ) اس کی قدر کرنے کا حق ہے ۔ \"\" ( اور ( پوری ) آیت تلاوت فرمائی ۔","",{"u2":"جریر نے منصور سے اسی سند کے ساتھ روایت کی،کہا:یہود میں سے ایک عالم رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، فضیل کی حدیث کے مانند،اور اس میں یہ بیان نہیں کیا:\"وہ (اللہ) ان(انگلیوں) کو ہلائے گا۔\"\nاور(حضرت عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ نے) کہا:میں نے رسول اللہ صلی اللہ علیہ وسلم کو د یکھا،آپ اس بات پر تعجب سے اس کی تصدیق کرتے ہوئے(اس طرح) ہنسے کہ آپ سے پچھلے دندان مبارک ظاہر ہوگئے،پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"انھوں نے(اس طرح) اللہ کی قدر نہیں کی(جس طرح) اس کی قدر کرنے کا حق ہے۔\"(اور (پوری) آیت تلاوت فرمائی۔"}],[7104,"حفص بن غیاث نے کہا : ہمیں اعمش نے حدیث بیان کی ، انھوں نے کہا : میں نے ابراہیم کو کہتے ہوئے سنا : میں نے علقمہ کو کہتے ہوئے سنا کہ سیدنا عبداللہ بن مسعود رضی اللہ تعالی عنہ نے کہا : اہل کتاب میں سے ایک شخص رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں آیا اور اس نے کہا : ابو القاسم! بے شک اللہ تعالی تمام آسمانوں کو ایک انگلی پر ، زمینوں کو ایک انگلی پر اور درختوں اور گیلی مٹی کو ایک انگلی پر اور تمام مخلوق کو ایک انگلی پر تھام لے گا ، پھر فرمائے گا : \" بادشاہ میں ہوں بادشاہ میں ہوں ۔ \" ( ابن مسعود رضی اللہ تعالی عنہ نے ) کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا ، آپ ( اس بات پر ) ہنس پڑے یہاں تک کہ آپ کے پچھلے دندان مبارک ظاہر ہوئے ، پھرآپ نے ( اس آیت کی ) تلاوت کی : \" انھوں نے اللہ تعالی کی ( اس طرح قدر نہیں پہچانی جس طرح قدر پہچاننے کا حق ہے ۔)","",{"u2":"حفص بن غیاث نے کہا:ہمیں اعمش نے حدیث بیان کی،انھوں نے کہا:میں نے ابراہیم کو کہتے ہوئے سنا:میں نے علقمہ کو کہتے ہوئے سنا کہ حضرت عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ نے کہا:اہل کتاب میں سے ایک شخص رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں آیا اور اس نے کہا:ابو القاسم! بے شک اللہ تعالیٰ تمام آسمانوں کو ایک انگلی پر،زمینوں کو ایک انگلی پر اور درختوں اور گیلی مٹی کو ایک انگلی پر اور تمام مخلوق کو ایک انگلی پر تھام لے گا،پھر فرمائے گا:\"بادشاہ میں ہوں بادشاہ میں ہوں۔\"(ابن مسعود رضی اللہ تعالیٰ عنہ نے) کہا:میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا،آپ(اس بات پر) ہنس پڑے یہاں تک کہ آپ کے پچھلے دندان مبارک ظاہر ہوئے،پھرآپ نے(اس آیت کی) تلاوت کی:\"انھوں نے اللہ تعالیٰ کی(اس طرح قدر نہیں پہچانی جس طرح قدر پہچاننے کا حق ہے۔\""}],[7105,"ابو معاویہ ، عیسی بن یونس اور جریر سب نے اعمش سے اسی سند کے ساتھ روایت کی ، مگران سب کی روایتوں میں ہے : \" اور درختوں کو ایک انگلی پر اور گیلی مٹی کو ایک انگلی پر تھام لےگا اور جریر کی حدیث میں یہ نہیں ہے \" اور مخلوق کو ایک انگلی پر تھامے گا \" لیکن اس کی حدیث میں یہ ہے : \" اور پہاڑوں کو ایک انگلی پر تھام لے گا \" اور انھوں نے جریر کی حدیث میں مذید یہ کہا : \" اس کی بات کی تصدیق اور اس پر تعجب کا اظہار کرتے ہوئے ( آپ ہنسے ۔)","",{"u2":"ابو معاویہ،عیسی بن یونس اور جریر سب نے اعمش سے اسی سند کے ساتھ روایت کی،مگران سب کی روایتوں میں ہے:\" اور درختوں کو ایک انگلی پر اور گیلی مٹی کو ایک انگلی پر تھام لےگااور جریر کی حدیث میں یہ نہیں ہے\"اور مخلوق کو ایک انگلی پر تھامے گا\"لیکن اس کی حدیث میں یہ ہے:\"اور پہاڑوں کو ایک انگلی پر تھام لے گا\"اور انھوں نے جریر کی حدیث میں مذید یہ کہا:\"اس کی بات کی تصدیق اور اس پر تعجب کا اظہار کرتے ہوئے(آپ ہنسے۔)\""}],[7106,"ابن مسیب نے حدیث بیان کی کہ سیدنا ابو ہریرہ رضی اللہ تعالی عنہ بیان کیا کرتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ تعالی قیامت کے دن زمین کو اپنی مٹھی میں لے لے گا اور آسمان کو اپنے داہنے ہاتھ میں لپیٹ لے گا ، پھر فرمائے گا : \" بادشاہ میں ہوں ، زمین کے بادشاہ کہاں ہیں؟","",{"u2":"ابن مسیب نے حدیث بیان کی کہ حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ بیان کیا کرتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"اللہ تعالیٰ قیامت کے دن زمین کو اپنی مٹھی میں لے لے گا اور آسمان کو اپنے داہنے ہاتھ میں لپیٹ لے گا،پھر فرمائے گا:\"بادشاہ میں ہوں،زمین کے بادشاہ کہاں ہیں؟\""}],[7107,"سالم بن عبداللہ نے کہا : مجھے عبداللہ بن عمر رضی اللہ تعالی عنہ نے خبر دی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" اللہ عزوجل قیامت کےدن آسمانوں کو لپیٹے گا ، پھران کو دائیں ہاتھ سے پکڑ لے گا اور فرمائے گا : بادشاہ میں ہوں ۔ ( آج دوسروں پر ) جبر کرنے والے کہاں ہیں؟تکبر کرنے والے کہاں ہیں؟پھر بائیں ہاتھ سے زمین کو لپیٹ لے گا ، پھر فرمائے گا : \" بادشاہ میں ہوں ، ( آج ) جبر کرنےوالے کہاں ہیں؟تکبر کرنے والے کہاں ہیں؟ ‘‘","",{"u2":"سالم بن عبداللہ نے کہا:مجھے عبداللہ بن عمر رضی اللہ تعالیٰ عنہ نے خبر دی،کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"اللہ عزوجل قیامت کےدن آسمانوں کو لپیٹے گا،پھران کو دائیں ہاتھ سے پکڑ لے گا اور فرمائے گا:بادشاہ میں ہوں۔(آج دوسروں پر) جبر کرنے والے کہاں ہیں؟تکبر کرنے والے کہاں ہیں؟پھر بائیں ہاتھ سے زمین کو لپیٹ لے گا،پھر فرمائے گا:\"بادشاہ میں ہوں،(آج) جبر کرنےوالے کہاں ہیں؟تکبر کرنے والے کہاں ہیں؟‘‘"}],[7108,"یعقوب بن عبدالرحمان نے کہا : مجھے ابو حازم نے عبیداللہ بن مقسم سے حدیث بیان کی ، انھوں نے حضر ت عبداللہ بن عمر رضی اللہ تعالی عنہ کی طرف دیکھا کہ وہ ( حدیث بیان کرتے ہوئے عملاً ) کس طرح رسول اللہ صلی اللہ علیہ وسلم کی طرح کرکے دکھاتے ہیں ۔ ( ابن عمر رضی اللہ تعالی عنہ نے کہا : رسول اللہ صلی اللہ علیہ وسلم نے ) فرمایا : \" اللہ عزوجل اپنے آسمانوں اور اپنی زمینوں کو اپنے دونوں ہاتھوں سے پکڑ لے گا پھر فرمائے گا \" میں اللہ ، میں بادشاہ ہوں ۔ \" اور آپ صلی اللہ علیہ وسلم ا پنی انگلیوں کو بند کرتے تھے اور کھولتے تھے ۔ حتی کہ میں نے منبر کو دیکھا ، وہ اپنے نچلے حصے سے ( لے کر او پرکے حصے تک ) ہل رہاتھا ۔ یہاں تک کہ میں نے کہا : کیا وہ رسول اللہ صلی اللہ علیہ وسلم کو لے کر گرجائے گا؟","",{"u2":"یعقوب بن عبدالرحمان نے کہا:مجھے ابو حازم نے عبیداللہ بن مقسم سے حدیث بیان کی،انھوں نے حضر ت عبداللہ بن عمر رضی اللہ تعالیٰ عنہ کی طرف دیکھا کہ وہ(حدیث بیان کرتے ہوئے عملاً) کس طرح رسول اللہ صلی اللہ علیہ وسلم کی طرح کرکے دکھاتے ہیں۔(ابن عمر رضی اللہ تعالیٰ عنہ نے کہا:رسول اللہ صلی اللہ علیہ وسلم نے)فرمایا:\"اللہ عزوجل اپنے آسمانوں اور اپنی زمینوں کو اپنے دونوں ہاتھوں سے پکڑ لے گا پھر فرمائے گا\"میں اللہ،میں بادشاہ ہوں۔\"اور آپ صلی اللہ علیہ وسلم ا پنی انگلیوں کو بند کرتے تھے اور کھولتے تھے۔حتیٰ کہ میں نے منبر کو دیکھا،وہ اپنے نچلے حصے سے(لے کر او پرکے حصے تک) ہل رہاتھا۔یہاں تک کہ میں نے کہا:کیا وہ رسول اللہ صلی اللہ علیہ وسلم کو لے کر گرجائے گا؟"}],[7109,"عبدالعزیز بن ابی حازم نے کہا : مجھے میرے والد نے عبیداللہ بن مقسم سے حدیث بیان کی ، انھوں نے سیدنا عبداللہ بن عمر رضی اللہ تعالی عنہ سے روایت کی ، کہا : میں نے رسول اللہ صلی اللہ علیہ وسلم کو منبر پر دیکھا جب آپ صلی اللہ علیہ وسلم فرمارہے تھے : \" ( اللہ ) جبارعزوجل اپنے آسمانوں اور اپنی زمینوں کو اپنے ہاتھوں میں پکڑ لے گا ۔ \" پھر یعقوب کی حدیث کی طرح بیان کیا ۔","",{"u2":"عبدالعزیز بن ابی حازم نے کہا:مجھے میرے والد نے عبیداللہ بن مقسم سے حدیث بیان کی،انھوں نے حضرت عبداللہ بن عمر رضی اللہ تعالیٰ عنہ سے روایت کی،کہا:میں نے رسول اللہ صلی اللہ علیہ وسلم کو منبر پر دیکھا جب آپ صلی اللہ علیہ وسلم فرمارہے تھے:\"(اللہ) جبارعزوجل اپنے آسمانوں اور اپنی زمینوں کو اپنے ہاتھوں میں پکڑ لے گا۔\"پھر یعقوب کی حدیث کی طرح بیان کیا۔"}],[7110,"سریج بن یونس اور ہارون بن عبداللہ نے مجھے حدیث بیان کی ، دونوں نے کہا : ہمیں حجاج بن محمد نے حدیث بیان کی ، انھوں نے کہا : ابن جریج نے کہا : مجھے اسماعیل بن امیہ نے ایوب بن خالد سے حدیث بیان کی ۔ انھوں نے ام سلمہ رضی اللہ تعالی عنہا کے آزاد کردہ غلام عبداللہ بن رافع سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ تعالی عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے میرا ہاتھ پکڑا ، پھر فرمایا : \"\" اللہ عزوجل نے مٹی ( زمین ) کو ہفتے کےدن پیداکیا اور اس میں پہاڑوں کو اتوار کے دن پیدا کیا اور درختوں کو پیر کے دن پیدا کیا اور ناپسندیدہ چیزوں کو منگل کےدن پیدا کیا اور نور کو بدھ کے دن پیدا کیا اور اس میں چوپایوں کو جمعرات کے دن پھیلادیا اور سب مخلوقات کے آخر میں آخر میں آدم علیہ السلام کو جمعہ کے دن عصر کے بعد سے لے کر رات تک کے درمیان جمعہ ( کے دن کی آخری ساعتوں میں سے کسی ساعت میں پیدا فرمایا ۔ \"\" جلودی نے ہمیں حدیث بیان کی ، کہا : ہمیں امام مسلم رحمۃاللہ علیہ کے شاگرد ابراہیم نے حدیث بیان کی ، کہا : ہمیں حسین بن علی بسطامی ، سہل بن عمار ، حفص کے نواسے ابراہیم اور دوسروں نے حجاج سے یہی حدیث بیان کی ۔)"],[7111,"سریج بن یونس اور ہارون بن عبداللہ نے مجھے حدیث بیان کی ، دونوں نے کہا : ہمیں حجاج بن محمد نے حدیث بیان کی ، انھوں نے کہا : ابن جریج نے کہا : مجھے اسماعیل بن امیہ نے ایوب بن خالد سے حدیث بیان کی ۔ انھوں نے ام سلمہ رضی اللہ تعالی عنہا کے آزاد کردہ غلام عبداللہ بن رافع سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ تعالی عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے میرا ہاتھ پکڑا ، پھر فرمایا : \"\" اللہ عزوجل نے مٹی ( زمین ) کو ہفتے کےدن پیداکیا اور اس میں پہاڑوں کو اتوار کے دن پیدا کیا اور درختوں کو پیر کے دن پیدا کیا اور ناپسندیدہ چیزوں کو منگل کےدن پیدا کیا اور نور کو بدھ کے دن پیدا کیا اور اس میں چوپایوں کو جمعرات کے دن پھیلادیا اور سب مخلوقات کے آخر میں آخر میں آدم علیہ السلام کو جمعہ کے دن عصر کے بعد سے لے کر رات تک کے درمیان جمعہ ( کے دن کی آخری ساعتوں میں سے کسی ساعت میں پیدا فرمایا ۔ \"\" جلودی نے ہمیں حدیث بیان کی ، کہا : ہمیں امام مسلم رحمۃاللہ علیہ کے شاگرد ابراہیم نے حدیث بیان کی ، کہا : ہمیں حسین بن علی بسطامی ، سہل بن عمار ، حفص کے نواسے ابراہیم اور دوسروں نے حجاج سے یہی حدیث بیان کی ۔)","",{"u2":"سریج بن یونس اور ہارون بن عبداللہ نے مجھے حدیث بیان کی،دونوں نے کہا:ہمیں حجاج بن محمد نے حدیث بیان کی،انھوں نے کہا:ابن جریج نے کہا:مجھے اسماعیل بن امیہ نے ایوب بن خالد سے حدیث بیان کی۔انھوں نے ام سلمہ رضی اللہ تعالیٰ عنہا کے آزاد کردہ غلام عبداللہ بن رافع سے اور انھوں نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے میرا ہاتھ پکڑا، پھر فرمایا: \"اللہ عزوجل نے مٹی(زمین) کو ہفتے کےدن پیداکیا اور اس میں پہاڑوں کو اتوار کے دن پیدا کیا اور درختوں کو پیر کے دن پیدا کیا اور ناپسندیدہ چیزوں کو منگل کےدن پیدا کیا اور نور کو بدھ کے دن پیدا کیا اور اس میں چوپایوں کو جمعرات کے دن پھیلادیا اور سب مخلوقات کے آخر میں آخر میں آدم علیہ السلام کو جمعہ کے دن عصر کے بعد سے لے کر رات تک کے درمیان جمعہ(کے دن کی آخری ساعتوں میں سے کسی ساعت میں پیدا فرمایا۔\"\nجلودی نے ہمیں حدیث بیان کی،کہا:ہمیں امام مسلم رحمۃاللہ علیہ کے شاگرد ابراہیم نے حدیث بیان کی،کہا:ہمیں حسین بن علی بسطامی،سہل بن عمار،حفص کے نواسے ابراہیم اور دوسروں نے حجاج سے یہی حدیث بیان کی۔"}],[7112,"سیدنا سہل بن سعد رضی اللہ تعالی عنہ سے روایت ہے کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" قیامت کے دن لوگوں کو غبار کی رنگت ملی ، سفید زمین پر اکٹھا کیا جا ئے گا ، جیسے چھنے ہوئے آٹے کی روٹی ہو تی ہے اور اس کسی شخص کے لیے کو ئی علامت موجود نہیں ہو گی ۔","",{"u2":"حضرت سہل بن سعد رضی اللہ تعالیٰ عنہ سے روایت ہے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"قیامت کے دن لوگوں کو غبار کی رنگت ملی،سفید زمین پر اکٹھا کیا جا ئے گا،جیسے چھنے ہوئے آٹے کی روٹی ہو تی ہے اور اس کسی شخص کے لیے کو ئی علامت موجود نہیں ہو گی۔"}],[7113,"سیدہ عائشہ رضی اللہ تعالی عنہا سے روایت ہے انھوں نے کہا میں نے رسول اللہ صلی اللہ علیہ وسلم سے اللہ عزوجل کے اس قول کے متعلق سوال کیا : \" جس دن زمین دوسری زمین سے بدل دی جا ئے گی اور آسمان ( بھی بدل دیا جائےگا ) تو اللہ کے رسول اللہ صلی اللہ علیہ وسلم !اس دن لوگ کہاں ہوں گے؟آپ صلی اللہ علیہ وسلم نے فرمایا : \" ( پل صراط پر ۔)","",{"u2":"حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت ہے انھوں نے کہا میں نے رسول اللہ صلی اللہ علیہ وسلم سے اللہ عزوجل کے اس قول کے متعلق سوال کیا:\" جس دن زمین دوسری زمین سے بدل دی جا ئے گی اور آسمان (بھی بدل دیا جائےگا) تو اللہ کے رسول اللہ صلی اللہ علیہ وسلم!اس دن لوگ کہاں ہوں گے؟آپ صلی اللہ علیہ وسلم نے فرمایا:\"(پل صراط پر۔"}],[7114,"عطاءبن یسار نے سیدنا ابو سعید خدری رضی اللہ تعالی عنہ سے اور انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" قیامت کے دن یہ زمین ایک ہی روئی بن جائے گی ۔ جبار ( اللہ تعالی ) اہل جنت کی مہمانی کے لیے اسے اپنے ہاتھ سے الٹ پلٹ کرروئی کی طرح بنا دے گا جس طرح تم میں سے کو ئی شخص سفر میں روئی کو الٹ پلٹ کرتا ہے ۔ ( سیدنا ابو سعید خدری رضی اللہ تعالی عنہ نے ) کہا : اتنے میں یہودیوں میں سے ایک شخص آگیا اس نے کہا : ابو القاسم الرحمٰن آپ پر برکت نازل فرمائے !کیا میں آپ کو قیامت کے روز اہل جنت کی ضیافت کے بارے میں نہ بتاؤں ؟آپ نے ارشاد فرمایا : \" کیوں نہیں ! ( بتاؤ ) اس نے کہا : زمین ایک ( بڑی سی ) روئی بن جا ئے گی ۔ جس طرح ( اس کی آمد سے قبل خود ) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا ۔ ( ابو سعید رضی اللہ تعالی عنہ نے ) کہا : تو رسول اللہ صلی اللہ علیہ وسلم نے ہماری طرف دیکھا پھر آپ ہنسے حتی کہ آپ کے پچھلے دندان مبارک نظر آنے لگے ۔ اس نے ( پھر ) کہا : کیا میں آپ کو ان کے سالن کے بارے میں نہ بتاؤں ؟آپ نے فرمایا : \" کیوں نہیں ( بتاؤ ) \" اس نے کہا \" ان کا سالن بالام اور نون ہو گا یہ صحابہ کرام رضوان اللہ عنھم اجمعین نے پوچھا وہ کیا ہے ؟آپ صلی اللہ علیہ وسلم نے فرمایا : \" بیل اور مچھلی یہ اس کے جگر کے چھوٹے سے اضافی حصے کو ( جوا صل جگر کے ساتھ ایک طرف موجود ہو تا ہے ) ستر ہزار لوگ کھائیں ۔","",{"u2":"عطاءبن یسار نے حضرت ابو سعید خدری رضی اللہ تعالیٰ عنہ سے اور انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\"قیامت کے دن یہ زمین ایک ہی روئی بن جائے گی۔جبار (اللہ تعالیٰ) اہل جنت کی مہمانی کے لیے اسے اپنے ہاتھ سے الٹ پلٹ کرروئی کی طرح بنا دے گا جس طرح تم میں سے کو ئی شخص سفر میں روئی کو الٹ پلٹ کرتا ہے۔(حضرت ابو سعید خدری رضی اللہ تعالیٰ عنہ نے) کہا: اتنے میں یہودیوں میں سے ایک شخص آگیا اس نے کہا: ابو القاسم الرحمٰن آپ پر برکت نازل فرمائے!کیا میں آپ کو قیامت کے روز اہل جنت کی ضیافت کے بارے میں نہ بتاؤں؟آپ نے ارشاد فرمایا:\" کیوں نہیں!(بتاؤ)اس نے کہا: زمین ایک (بڑی سی) روئی بن جا ئے گی۔جس طرح (اس کی آمد سے قبل خود) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا۔(ابو سعید رضی اللہ تعالیٰ عنہ نے)کہا: تو رسول اللہ صلی اللہ علیہ وسلم نے ہماری طرف دیکھا پھر آپ ہنسے حتی کہ آپ کے پچھلے دندان مبارک نظر آنے لگے۔اس نے (پھر)کہا: کیامیں آپ کو ان کے سالن کے بارے میں نہ بتاؤں؟آپ نے فرمایا: \"کیوں نہیں (بتاؤ) \"اس نے کہا\" ان کا سالن بالام اور نون ہو گا یہ صحابہ کرام رضوان اللہ عنھم اجمعین نے پوچھا وہ کیا ہے؟آپ صلی اللہ علیہ وسلم نے فرمایا:\"بیل اور مچھلی یہ اس کے جگر کے چھوٹے سے اضافی حصے کو(جوا صل جگر کے ساتھ ایک طرف موجود ہو تا ہے) ستر ہزار لوگ کھائیں۔\""}],[7115,"محمد بن سیرین نے ہمیں سیدنا ابو ہریرۃ رضی اللہ تعالی عنہ سے حدیث بیان کی کہا : نبی صلی اللہ علیہ وسلم نے فرمایا : اگر دس ( بڑے ) یہودی ( عالم ) میری پیروی کر لیتے تو روئے زمین پر کوئی یہودی باقی نہ رہتا مگر مسلمان ہو جا تا ۔","",{"u2":"محمد بن سیرین نے ہمیں حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے حدیث بیان کی کہا: نبی صلی اللہ علیہ وسلم نے فرمایا:اگر دس (بڑے) یہودی (عالم) میری پیروی کر لیتے تو روئے زمین پر کوئی یہودی باقی نہ رہتا مگر مسلمان ہو جا تا۔\""}],[7116,"حفص بن غیاث نے کہا : ہمیں میرے والد نے حدیث بیان کی کہا : ہمیں اعمش نے حدیث بیان کی ، کہا : مجھے ابراہیم نے علقمہ سے حدیث بیان کی ، انھوں نے سیدنا عبد اللہ بن مسعود رضی اللہ تعالی عنہ سے روایت کی ، کہا : ایک مرتبہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک کھیت میں چلا جارہا تھا نبی صلی اللہ علیہ وسلم کھجور کی ایک شاخ کا سہارا لے ( کر چل ) رہے تھے کہ آپ کا یہود کے چند لوگوں کے قریب سے گزر ہوا ان میں سے ایک نے دوسرے سے کہا : ان سے روح کے بارے میں سوال کرو پھر وہ ایک دوسرے سے کہنے لگے : ان کے بارے میں تمھیں شک کس بات کا ہے؟ایسا نہ ہو کہ وہ آگے سے ایسی بات کہہ دیں جو تمھیں بری لگے پھر ان میں سے ایک شخص کھڑا ہوکر آپ کے پاس آگیا اور آپ صلی اللہ علیہ وسلم سے روح کے بارے میں سوال کیا ۔ ( سیدنا عبد اللہ بن مسعود رضی اللہ تعالی عنہ نے ) کہا : رسول اللہ صلی اللہ علیہ وسلم ( تھوڑی دیر کے لیے ) خاموش ہو گئے اور ان کو کو ئی جواب نہ دیا ۔ مجھے معلوم ہو گیا کہ آپ پروحی نازل ہو رہی ہے ۔ کہا میں بھی اپنی جگہ پر ( رک کر ) کھڑا ہو گیا ۔ جب وحی نازل ہو چکی تو آپ صلی اللہ علیہ وسلم نے ( یہ پڑھتے ہوئے ) فرمایا : \" یہ لوگ آپ سے روح کے بارے میں سوال کرتے ہیں ۔ کہہ دیجیے روح میرے رب کے حکم سے ہے اور تم ( انسانوں ) کو بہت کم علم دیا گیا ہے ۔","",{"u2":"حفص بن غیاث نے کہا: ہمیں میرے والد نے حدیث بیان کی کہا:ہمیں اعمش نے حدیث بیان کی، کہا: مجھے ابراہیم نے علقمہ سے حدیث بیان کی، انھوں نے حضرت عبد اللہ بن مسعود رضی اللہ تعالیٰ عنہ سے روایت کی، کہا: ایک مرتبہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک کھیت میں چلا جارہا تھا نبی صلی اللہ علیہ وسلم کھجور کی ایک شاخ کا سہارا لے (کر چل) رہے تھے کہ آپ کا یہود کے چند لوگوں کے قریب سے گزر ہوا ان میں سے ایک نے دوسرے سے کہا: ان سے روح کے بارے میں سوال کرو پھر وہ ایک دوسرے سے کہنے لگے:ان کے بارے میں تمھیں شک کس بات کا ہے؟ایسا نہ ہو کہ وہ آگے سے ایسی بات کہہ دیں جو تمھیں بری لگے پھر ان میں سے ایک شخص کھڑا ہوکر آپ کے پاس آگیا اور آپ صلی اللہ علیہ وسلم سے روح کے بارے میں سوال کیا۔ (حضرت عبد اللہ بن مسعود رضی اللہ تعالیٰ عنہ نے)کہا: رسول اللہ صلی اللہ علیہ وسلم (تھوڑی دیر کے لیے) خاموش ہو گئے اور ان کو کو ئی جواب نہ دیا۔مجھے معلوم ہو گیا کہ آپ پروحی نازل ہو رہی ہے۔ کہا میں بھی اپنی جگہ پر (رک کر) کھڑا ہو گیا۔جب وحی نازل ہو چکی تو آپ صلی اللہ علیہ وسلم نے(یہ پڑھتے ہوئے)فرمایا:\"یہ لوگ آپ سے روح کے بارے میں سوال کرتے ہیں۔ کہہ دیجیے روح میرے رب کے حکم سے ہے اور تم (انسانوں) کو بہت کم علم دیا گیا ہے۔"}],[7117,"ابو بکر بن ابی شیبہ اور ابو اشج نے ہمیں حدیث بیان کی ، دونوں نے کہا : ہمیں وکیع نے حدیث بیان کی ، نیز ہمیں اسحٰق بن ابراہیم حنظلی اور علی بن خشرم نے بھی حدیث بیان کی دونوں نے کہا : ہمیں عیسی بن یونس نے خبر دی ۔ ان دونوں ( وکیع اور عیسی ) نےاعمش سے ، انھوں نے ابراہیم سے ، انھوں نے سیدنا عبد اللہ ( بن مسعود رضی اللہ تعالی عنہ ) سے روایت کی ، کہا : میں نبی صلی اللہ علیہ وسلم کے ساتھ مدینہ کے ایک ( اجزائے ہوئے ) کھیت میں جارہاتھا ۔ حفص کی حدیث کے مانند مکروکیع کی حدیث میں ہے : \"\" «وَمَا أُوتِيتُم مِّنَ الْعِلْمِ إِلَّا قَلِيلًا» \"\" \"\" اور تم لوگوں کو علم کا تھوڑا حصہ ہی دیا گیا ہے ۔ \"\" ( جس طرح قرآن کی مشہور متواتر قرآءت ہے ۔ اور عیسی بن یو نس کی اس روایت میں جوان سے ( علی ) بن خشرم نے بیان کی ہے وما اوتوا \"\" انھیں نہیں دیا گیا \"\" کے الفاظ ہیں ۔","",{"u2":"ابو بکر بن ابی شیبہ اور ابو اشج نے ہمیں حدیث بیان کی، دونوں نے کہا:ہمیں وکیع نے حدیث بیان کی، نیز ہمیں اسحٰق بن ابراہیم حنظلی اور علی بن خشرم نے بھی حدیث بیان کی دونوں نے کہا: ہمیں عیسیٰ بن یونس نے خبر دی۔ان دونوں (وکیع اور عیسیٰ) نےاعمش سے، انھوں نے ابراہیم سے،انھوں نے حضرت عبد اللہ (بن مسعود رضی اللہ تعالیٰ عنہ)سے روایت کی، کہا:میں نبی صلی اللہ علیہ وسلم کے ساتھ مدینہ کے ایک (اجزائے ہوئے)کھیت میں جارہاتھا۔حفص کی حدیث کے مانند مکروکیع کی حدیث میں ہے:\n\"وَمَا أُوتِیتُم مِّنَ الْعِلْمِ إِلَّا قَلِیلًا \"\n\"اور تم لوگوں کو علم کا تھوڑا حصہ ہی دیا گیا ہے۔ \"(جس طرح قرآن کی مشہور متواتر قرآءت ہے۔ اور عیسیٰ بن یو نس کی اس روایت میں جوان سے (علی)بن خشرم نے بیان کی ہے وما اوتوا\"انھیں نہیں دیا گیا \"کے الفاظ ہیں۔"}],[7118,"ابو سعید اشج نے ہمیں حدیث بیان کی ، کہا : میں نے عبد اللہ بن ادریس سے سنا وہ کہہ رہے تھے ، میں نے اعمش سے سنا وہ اس روایت کو عبداللہ رضی اللہ تعالی عنہ بن مرہ سے اور وہ مسروق سے اور وہ سیدنا عبد اللہ بن مسعود رضی اللہ تعالی عنہ سے روایت کر رہے تھے ، انھوں نے کہا : نبی صلی اللہ علیہ وسلم کھجور کے درختوں میں ( کھجور کی ) ایک شاخ کا سہارا لیے ہوئے ( چلے جارہے ) تھے پھر اعمش سے ان سب کی حدیث کے مطابق بیان کیا اور انھوں نے ( بھی ) اپنی روایت میں مشہور اور متواتر قرآءت کے مطابق \"\" «وَمَا أُوتِيتُم مِّنَ الْعِلْمِ إِلَّا قَلِيلًا» \"\" بیان کیا ۔ ان روایات میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم حرث ( کھیت ) اور نخل ( کھجور کے درختوں ) کے درمیان جارہے تھے ۔ صحیح بخاری کی ایک روایت میں حرث ہے ۔ ( حدیث 4721 ۔ ) جبکہ دوسری روایت میں \"\" خرب \"\" ( اجازجگہ ) ہے ۔ ( حدیث : 125 ) اس سے معلوم ہوتا ہے کہ وہ کھیت جس میں آپ صلی اللہ علیہ وسلم چلے جارہے تھے ۔ مدینہ کے عام کھیتوں کی طرح کھجور کے باغ میں تھا اور اب اس میں کچھ کاشت نہیں ہو رہاتھا اجڑاہوا اور ناہموار ہونے کی وجہ سے آپ اس کے اندر کھجور کی شاخ کا سہارا لے کر چل رہے تھے ۔ جامع ترمذی میں سیدنا عبد اللہ بن عباس رضی اللہ تعالی عنہ سے روایت ہے کہ روح کے متعلق یہودیوں سے پوچھ کر قریش مکہ نے بھی سوال کیا تھا آپ صلی اللہ علیہ وسلم نے ان کو بھی یہی جواب دیا تھا ( جمع المومنین حدیث 3140 ) مدینہ میں جب یہود نے خود سوال کیا تو چونکہ وہ اہل کتاب تھے اس لیے یہ امکان تھا کہ ان کی کتاب میں یہی بات کسی اور رنگ میں کہی گئی ہو اور وہ انداز کے اس اختلاف کو اپنے لیے دلیل بنانے کی کو شش کریں اس لیے جواب دینے سے پہلے رسول اللہ صلی اللہ علیہ وسلم نے توقف کیا اور اللہ تعالی نے دوبارہ وہی جواب وحی فرمادیا جو تورات کےعین مطابق تھا اور یہود کو اپنے لیے آپ کی رسالت سے انکار کا کو ئی عذر نہ مل سکا ۔","",{"u2":"ابو سعید اشج نے ہمیں حدیث بیان کی، کہا: میں نے عبد اللہ بن ادریس سے سنا وہ کہہ رہے تھے،میں نے اعمش سے سنا وہ اس روایت کو عبداللہ رضی اللہ تعالیٰ عنہ بن مرہ سے اور وہ مسروق سے اور وہ حضرت عبد اللہ بن مسعود رضی اللہ تعالیٰ عنہ سے روایت کر رہے تھے،انھوں نے کہا: نبی صلی اللہ علیہ وسلم کھجور کے درختوں میں(کھجور کی) ایک شاخ کا سہارا لیے ہوئے (چلے جارہے)تھے پھر اعمش سے ان سب کی حدیث کے مطابق بیان کیا اور انھوں نے (بھی) اپنی روایت میں مشہور اور متواتر قرآءت کے مطابق \"وَمَا أُوتِیتُم مِّنَ الْعِلْمِ إِلَّا قَلِیلًا \"بیان کیا۔\nان روایات میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم حرث (کھیت)اور نخل (کھجورکے درختوں)کے درمیان جارہے تھے۔صحیح بخاری کی ایک روایت میں حرث ہے۔ (حدیث 4721۔)جبکہ دوسری روایت میں\"خرب\"(اجازجگہ) ہے۔(حدیث:125)اس سے معلوم ہوتا ہے کہ وہ کھیت جس میں آپ صلی اللہ علیہ وسلم چلے جارہے تھے۔مدینہ کے عام کھیتوں کی طرح کھجور کے باغ میں تھا اور اب اس میں کچھ کاشت نہیں ہو رہاتھا اجڑاہوا اور ناہموار ہونے کی وجہ سے آپ اس کے اندرکھجور کی شاخ کا سہارا لے کر چل رہے تھے۔جامع ترمذی میں حضرت عبد اللہ بن عباس رضی اللہ تعالیٰ عنہ سے روایت ہے کہ روح کے متعلق یہودیوں سے پوچھ کر قریش مکہ نے بھی سوال کیا تھا آپ صلی اللہ علیہ وسلم نے ان کو بھی یہی جواب دیا تھا (جمع المومنین حدیث 3140)مدینہ میں جب یہود نے خود سوال کیا تو چونکہ وہ اہل کتاب تھے اس لیے یہ امکان تھا کہ ان کی کتاب میں یہی بات کسی اور رنگ میں کہی گئی ہو اور وہ انداز کے اس اختلاف کو اپنے لیےدلیل بنانے کی کو شش کریں اس لیے جواب دینے سے پہلے رسول اللہ صلی اللہ علیہ وسلم نے توقف کیا اور اللہ تعالیٰ نے دوبارہ وہی جواب وحی فرمادیا جو تورات کےعین مطابق تھا اور یہود کو اپنے لیے آپ کی رسالت سے انکار کا کو ئی عذر نہ مل سکا۔"}],[7119,"وکیع نے کہا : ہمیں اعمش نے ابو ضحی سے حدیث بیان کی ، انھوں نے مسروق سے اور انھوں نے سیدنا خباب ( بن ارت رضی اللہ تعالی عنہ ) سے روایت کی ، کہا میرا کچھ قرض عاص بن وائل کے ذمے تھا ۔ میں اس سے قرض کا تقاضا کرنے کے لیے اس کے پاس گیا تو اس نے مجھ سے کہا : میں اس وقت تک تمھیں ادائیگی نہیں کروں گا ۔ یہاں تک کہ تم نعوذ باللہ محمد صلی اللہ علیہ وسلم سے کفر کرو ۔ کہا : میں نے اس سے کہا : تم مر کردوبارہ زندہ ہو جاؤ گے ۔ پھر بھی میں محمد صلی اللہ علیہ وسلم کے ساتھ کفر نہیں کروں گا ۔ اس نے کہا : اور میں موت کے بعد دوبارہ زندہ کیا جاؤں گا؟تو ( اس وقت ) جب میں دوبارہ مال اور اولاد کے پاس پہنچ جاؤں گاتو تمھیں ادائیگی کردوں گا ۔ وکیع نے کہا : اعمش نے اسی طرح کہا : انھوں نے کہا : اس پریہ آیت نازل ہوئی : \"\" کیا آپ نے اس شخص کو دیکھا جس نے ہماری آیات سے کفر کیا اور کہا : مجھے ( اپنا ) مال اور ( اپنی ) اولاد ضروری دی جائے گی \"\" سے لے کر اس ( اللہ ) کے فرمان \"\" اور وہ ہمارے پاس اکیلا آئے گا \"\" تک ۔","",{"u2":"وکیع نے کہا: ہمیں اعمش نے ابو ضحیٰ سے حدیث بیان کی، انھوں نے مسروق سے اور انھوں نے حضرت خباب (بن ارت رضی اللہ تعالیٰ عنہ)سے روایت کی، کہا میرا کچھ قرض عاص بن وائل کے ذمے تھا۔میں اس سے قرض کا تقاضا کرنے کے لیے اس کے پاس گیا تو اس نے مجھ سے کہا: میں اس وقت تک تمھیں ادائیگی نہیں کروں گا۔یہاں تک کہ تم نعوذ باللہ محمد صلی اللہ علیہ وسلم سے کفر کرو۔ کہا: میں نے اس سے کہا: تم مر کردوبارہ زندہ ہو جاؤ گے۔ پھر بھی میں محمد صلی اللہ علیہ وسلم کے ساتھ کفر نہیں کروں گا۔ اس نے کہا: اور میں موت کے بعد دوبارہ زندہ کیا جاؤں گا؟تو (اس وقت) جب میں دوبارہ مال اور اولاد کے پاس پہنچ جاؤں گاتو تمھیں ادائیگی کردوں گا۔\nوکیع نے کہا:اعمش نے اسی طرح کہا: انھوں نے کہا:اس پریہ آیت نازل ہوئی:\"کیا آپ نے اس شخص کو دیکھا جس نے ہماری آیات سے کفر کیا اور کہا: مجھے (اپنا)مال اور (اپنی) اولاد ضروری دی جائے گی\"سے لے کر اس (اللہ)کے فرمان \"اور وہ ہمارے پاس اکیلا آئے گا \"تک۔"}],[7120,"ابو معاویہ عبد اللہ بن نمیر جریر اور سفیان سب نے اعمش سے اسی سند کے ساتھ وکیع کی حدیث کی طرح بیان کیا اور جریر کی حدیث میں ہے ۔ ( سیدنا خباب رضی اللہ تعالی عنہ نے ) کہا : میں زمانہ جاہلیت میں لوہار تھا تو میں نے عاص بن وائل کے لیے کام کیا پھر میں اس سے ( اجرت کا ) تقاضا کرنے کے لیے آیا ۔","",{"u2":"ابو معاویہ عبد اللہ بن نمیر جریر اور سفیان سب نے اعمش سے اسی سند کے ساتھ وکیع کی حدیث کی طرح بیان کیا اور جریر کی حدیث میں ہے۔(حضرت خباب رضی اللہ تعالیٰ عنہ نے)کہا:میں زمانہ جاہلیت میں لوہار تھا تو میں نے عاص بن وائل کے لیے کام کیا پھر میں اس سے (اجرت کا)تقاضا کرنے کے لیے آیا۔"}],[7121,"شعبہ نے عبد الحمید زیادی سے روایت کی انھوں نے سیدنا انس بن مالک رضی اللہ تعالی عنہ سے سنا : وہ کہہ رہے تھے کہ ابو جہل نے کہا : اے اللہ !اگر ( یہ جو محمد صلی اللہ علیہ وسلم لے کر آئے ہیں ) یہی تیری طرف سے حق ہے تو ہم پر آسمان سے پتھر برسادے یا ہم پر کوئی دردناک عذاب لے آ ۔ تو اس پر ( آیت ) نازل ہوئی : \" اللہ تعالی اس وقت ان پر ( اس طرح کا ) عذاب بھیجنے والا نہ تھا جبکہ آپ بھی ان میں موجود تھے اور اللہ تعالی ان کو عذاب دینے والا نہ تھا جب وہ ( علیحدگی میں ) استغفار کیے جارہے تھے ۔ اور انھیں کیا ہے کہ اللہ انھیں عذاب نہ دےجبکہ وہ ( ایمان لانے والوں کو ) مسجد حرام سے روکتے ہیں ۔ \" آیت کے آخرتک ۔","",{"u2":"شعبہ نے عبد الحمید زیادی سے روایت کی انھوں نے حضرت انس بن مالک رضی اللہ تعالیٰ عنہ سے سنا:وہ کہہ رہے تھے کہ ابو جہل نے کہا:اے اللہ!اگر (یہ جو محمد صلی اللہ علیہ وسلم لے کر آئے ہیں)یہی تیری طرف سے حق ہے تو ہم پر آسمان سے پتھر برسادے یا ہم پر کوئی دردناک عذاب لے آ۔تو اس پر (آیت) نازل ہوئی:\"اللہ تعالیٰ اس وقت ان پر(اس طرح کا) عذاب بھیجنے والا نہ تھا جبکہ آپ بھی ان میں موجود تھے اور اللہ تعالیٰ ان کو عذاب دینے والا نہ تھا جب وہ(علیحدگی میں)استغفار کیے جارہے تھے۔اور انھیں کیا ہے کہ اللہ انھیں عذاب نہ دےجبکہ وہ (ایمان لانے والوں کو) مسجد حرام سے روکتے ہیں۔\"آیت کے آخرتک۔"}],[7122,"عبید اللہ بن معاذ اور محمد بن عبد الاعلی قیسی نے ہمیں حدیث بیان کی دونوں نے کہا : ہمیں معتمر نے اپنے والد سے حدیث سنائی ، انھوں نے کہا : مجھے نعیم بن ابی ہندنےابوحازم سے حدیث بیان کی ، انھوں نے سیدنا ابو ہریرہ رضی اللہ تعالی عنہ سے روایت کی کہا : ابوجہل نے کہا : کیا محمدتم لوگوں کے سامنے اپنا چہرہ زمین پر رکھتے ہیں؟ ( سیدنا ابو ہریرہ رضی اللہ تعالی عنہ نے ) کہا : تو کہا گیا : ہاں چنانچہ اس نے کہا : لات اور عزی کی قسم !اگر میں نے ان کو ایسا کرتے ہوئے دیکھ لیا تو میں ان کی گردن کو روندوں گا یا ان کے چہرے کو مٹی میں ملاؤں گا ( العیاذ باللہ! ) کہا : پھر جب رسول اللہ صلی اللہ علیہ وسلم نماز پڑھ رہے تھے وہ آپ کے پاس آیا اور یہ ارادہ کیا کہ آپ کی گردن مبارک کوروندے ( ابوہریرہ رضی اللہ تعالی عنہ نے ) کہا : تووہ انھیں اچانک ایڑیوں کے بل پلٹتا ہوا اور اپنے دونوں ہاتھوں ( کو آگے کر کے ان ) سے اپنا بچاؤ کرتا ہوا نظر آیا ۔ ( ابوہریرہ رضی اللہ تعالی عنہ نے ) کہا : تو اس سے کہا کیا : تمھیں کیا ہوا ؟تو اس نے کہا : میرے اور اس کے درمیان آگ کی ایک خندق اور سخت ہول ( پیدا کرنے والی مخلوق ) اور بہت سے پر تھے ۔ تو رسول اللہ صلی اللہ علیہ وسلم نےفرمایا : \"\" اگر وہ میرے قریب آتا تو فرشتے اس کے ایک ایک عضو کو اچک لیتے ۔ ( ابو ہریرہ رضی اللہ تعالی عنہ نے ) کہا : اس پر اللہ تعالی نے یہ آیاتنازل فرمائیں ۔ ( ابو حازم نے کہا ۔ ( ہمیں معلوم نہیں کہ یہ ابو ہریرہ رضی اللہ تعالی عنہ کی ( رسول اللہ صلی اللہ علیہ وسلم سے سنی ہوئی ) اپنی حدیث ہے یا انھیں ( کسی کی طرف سے ) پہنچی ہے ۔ ( وہ آیات یہ تھیں ) \"\" اس کے سواکوئی بات نہیں کہ انسان ہر صورت میں سر کشی کرتا ہے اس لیے کہ وہ خود کو دیکھتا ہے کہ وہ ہر ایک سے مستغنی ہے حقیقت یہ ہے کہ ( اسے ) آپ کے رب کی طرف واپس جانا ہے ۔ آپ نے اسے دیکھا جو روکتا ہے ۔ ( اللہ کے ) بندے کو جب وہ نماز ادا کرتا ہے ۔ کیا تم نے دیکھا کہ اگر وہ ( اللہ کا بندہ ) ہدایت پر ہو اور تقوی کا حکم دیتا ہو ( تو روکنے والے کا کیا بنے گا؟ ) کیا آپ نے دیکھا کہ آکر اس یعنی ابو جہل نے جھٹلایا ہے اور ہدایت سے منہ پھیرا ہے ۔ ( تو ) کیا وہ نہیں جانتا کہ اللہ دیکھتا ہے ۔ ہر گز نہیں !اگر وہ باز نہ آیا تو ہم ( اسے ) پیشانی سے پکڑ کر کھینچیں کے ۔ ( اس کی ) جھوٹی گناہ کرنے والی پیشانی سے پھر وہ اپنی مجلس کو ( مدد کے لیے ) پکارے ہم عذاب دینے والے فرشتوں کو بلائیں گے ۔ ہر گز نہیں!آپ اس کی ( کوئی بات بھی ) نہ مانیں ۔ \"\" عبید اللہ ( بن معاذ ) نے اپنی حدیث میں مزید کہا ۔ ( ابوہریرہ رضی اللہ تعالی عنہ نے «أَوْ أَمَرَ بِالتَّقْوَىٰ» کی تفسیر کرتے ہوئے ) کہا : اور اس بات کا حکم دیتا ہو جس کا اس ( اللہ ) نے اسے حکم دیا ہے ۔ اور ( محمد ) بن عبد الاعلی نے مزید یہ کہا : \"\" وہ اپنی مجلس کو پکارے \"\" یعنی اپنی قوم کو ۔","",{"u2":"عبید اللہ بن معاذ اور محمد بن عبد الاعلی قیسی نے ہمیں حدیث بیان کی دونوں نے کہا: ہمیں معتمر نے اپنے والد سے حدیث سنائی،انھوں نے کہا: مجھے نعیم بن ابی ہندنےابوحازم سے حدیث بیان کی،انھوں نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی کہا:ابوجہل نے کہا: کیا محمدتم لوگوں کے سامنے اپنا چہرہ زمین پر رکھتے ہیں؟ (حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ نے)کہا: تو کہا گیا: ہاں چنانچہ اس نے کہا: لات اور عزیٰ کی قسم!اگر میں نے ان کو ایسا کرتے ہوئے دیکھ لیا تو میں ان کی گردن کو روندوں گا یا ان کے چہرےکو مٹی میں ملاؤں گا(العیاذ باللہ!)کہا: پھر جب رسول اللہ صلی اللہ علیہ وسلم نماز پڑھ رہے تھے وہ آپ کے پاس آیا اور یہ ارادہ کیا کہ آپ کی گردن مبارک کوروندے(ابوہریرہ رضی اللہ تعالیٰ عنہ نے) کہا: تووہ انھیں اچانک ایڑیوں کے بل پلٹتا ہوا اور اپنے دونوں ہاتھوں (کو آگے کر کے ان)سے اپنا بچاؤ کرتا ہوا نظر آیا۔(ابوہریرہ رضی اللہ تعالیٰ عنہ نے) کہا:تو اس سے کہا کیا:تمھیں کیا ہوا؟تو اس نے کہا: میرے اور اس کے درمیان آگ کی ایک خندق اور سخت ہول (پیدا کرنے والی مخلوق)اور بہت سے پر تھے۔\nتو رسول اللہ صلی اللہ علیہ وسلم نےفرمایا:\"اگر وہ میرے قریب آتا تو فرشتے اس کے ایک ایک عضو کو اچک لیتے۔\n(ابو ہریرہ رضی اللہ تعالیٰ عنہ نے)کہا: اس پر اللہ تعالیٰ نے یہ آیاتنازل فرمائیں۔(ابو حازم نے کہا۔(ہمیں معلوم نہیں کہ یہ ابو ہریرہ رضی اللہ تعالیٰ عنہ کی (رسول اللہ صلی اللہ علیہ وسلم سے سنی ہوئی) اپنی حدیث ہے یا انھیں(کسی کی طرف سے) پہنچی ہے۔ (وہ آیات یہ تھیں)\"اس کے سواکوئی بات نہیں کہ انسان ہر صورت میں سر کشی کرتا ہے اس لیے کہ وہ خود کو دیکھتا ہے کہ وہ ہر ایک سے مستغنی ہے حقیقت یہ ہے کہ(اسے)آپ کے رب کی طرف واپس جانا ہے۔آپ نے اسے دیکھا جو روکتا ہے۔(اللہ کے)بندے کو جب وہ نماز اداکرتا ہے۔کیا تم نے دیکھا کہ اگر وہ (اللہ کا بندہ)ہدایت پر ہو اور تقوی کا حکم دیتا ہو(تو روکنے والے کا کیا بنے گا؟)کیا آپ نے دیکھا کہ آکر اس یعنی ابو جہل نے جھٹلایا ہے اور ہدایت سے منہ پھیراہے۔(تو) کیا وہ نہیں جانتا کہ اللہ دیکھتا ہے۔ہر گز نہیں!اگر وہ باز نہ آیا تو ہم (اسے) پیشانی سے پکڑ کر کھینچیں کے۔ (اس کی)جھوٹی گناہ کرنے والی پیشانی سے پھر وہ اپنی مجلس کو(مددکے لیے) پکارے\nہم عذاب دینے والے فرشتوں کو بلائیں گے۔ ہر گز نہیں!آپ اس کی(کوئی بات بھی) نہ مانیں۔\"\nعبید اللہ (بن معاذ)نے اپنی حدیث میں مزید کہا۔(ابوہریرہ رضی اللہ تعالیٰ عنہ نے أَوْ أَمَرَ بِالتَّقْوَیٰ کی تفسیر کرتے ہوئے)کہا:اور اس بات کا حکم دیتا ہو جس کا اس (اللہ) نے اسے حکم دیا ہے۔اور (محمد) بن عبد الاعلیٰ نے مزید یہ کہا: \"وہ اپنی مجلس کو پکارے \"یعنی اپنی قوم کو۔"}],[7123,"منصور نے ابو ضحی ( مسلم بن صحیح ) سے ، انھوں نے مسروق سے روایت کی ، کہا : ہم سیدنا عبداللہ ( بن مسعود رضی اللہ تعالی عنہ ) کے پاس بیٹھے ہوئے تھے اور وہ ہمارے درمیان ( اپنے بستر یا بچھونے پر ) لیٹے ہوئے تھے تو ایک شخص آیا اور کہنے لگا : ابو عبدالرحمان!ابواب کندہ ( کوفہ کا ایک محلہ ) میں ایک قصہ گو ( واعظ ) آیا ہوا ہے ، وہ وعظ کررہا ہے اور یہ کہتا ہے کہ دھوئیں والی ( اللہ کی ) نشانی آئے گی اور ( یہ د ھواں ) کافروں کی روحیں قبض کرلے گا اور مومنوں کو یہ زکام جیسی کیفیت سے دو چار کرے گا ۔ سیدنا عبداللہ ( بن مسعود رضی اللہ تعالی عنہ ) نے کہا اور وہ غصے کے عالم میں اٹھ کر بیٹھ گئے ، لوگو! اللہ سے ڈرو ، تم میں سے جو شخص کوئی چیز جانتا ہو ، وہ اتنی ہی بیان کرے جتنی جانتاہو اور جو نہیں جانتا ، وہ کہے : اللہ زیادہ جاننے والا ہے ۔ بے شک وہ ( اللہ تعالی ) تم میں سے اس کو ( بھی ) زیادہ جاننے والاہے ۔ جو اس بات کے بارے میں جو وہ نہیں جانتا ، یہ کہتا ہے : اللہ زیادہ جاننے والا ہے ۔ اللہ عزوجل نے ا پنے نبی کریم صلی اللہ علیہ وسلم سے فرمایا؛ \"\" کہہ دیجئے : میں تم سے کوئی اجر نہیں مانگتا اور نہ ہی بناوٹ کرنے والوں میں سے ہوں ۔ \"\" رسول اللہ صلی اللہ علیہ وسلم نے جب لوگوں کی دین سے روگردانی دیکھی تو آپ نے ( دعا کرتے ہوئے ) فرمایا : \"\" اے اللہ! ( ان پر ) یوسف علیہ السلام کےسات سالوں جیسے سات سال ( بھیج دے ۔ ) \"\" ( عبداللہ بن مسعود رضی اللہ تعالی عنہ نے ) کہا : تو انھیں ( قحط کے ) ایک سال نے آلیا جس نے ہر چیز کاصفایاکرایا ، یہاں تک کہ ان ( مشرک ) لوگوں نے بھوک سے چمڑے اور مردار تک کھائے ۔ ان میں سے کوئی شخص آسمان کی طرف دیکھتا تو اسے دھوئیں کے جیسی ایک چیز چھائی ہوئی نظر آتی ۔ چنانچہ ابو سفیان رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں آیا اور کہا : اے محمد ( صلی اللہ علیہ وسلم ) آپ آئے ہیں ، اللہ کی اطاعت اور صلہ رحمی کاحکم دیتے ہیں ، آپ کی قوم ( قحط اور بھوک سے ) ہلاک ہورہی ہے ۔ ان کےلیے اللہ سے دعا کریں ۔ اللہ عزوجل نے فرمایا : \"\" آپ اس دن کا انتظار کریں جب آسمان ایک نظر آنے والے دھوئیں کو لے آئے گا ۔ ( اور وہ ) لوگوں کو ڈھانپ لے گا ۔ یہ دردناک عذاب ہوگا ، سے لے کر اس کے فرمان : \"\" نے شک تم ( کفر میں ) لوٹ جانے والے ہوگئے \"\" تک ۔ ( سیدنا عبداللہ بن مسعود رضی اللہ تعالی عنہ نے ) کہا : کیا آخرت کا عذاب ہٹایا جائے گا؟ \"\" جس دن ہم تم پر بڑی گرفت کریں گے ( اس دن ) ہم انتقام لینے والے ہوں گے ۔ \"\" وہ گرفت بدر کے دن تھی ۔ اب تک دھوئیں کی نشانی گرفت اور چمٹ جانے والا عذاب ( بدر میں شکست فاش اور قتل ) اور روم ( کی فتح ) کی نشانی ( سب ) آکر گذر چکی ہیں ۔","",{"u2":"منصور نے ابو ضحیٰ(مسلم بن صحیح) سے،انھوں نے مسروق سے روایت کی،کہا:ہم حضرت عبداللہ(بن مسعود رضی اللہ تعالیٰ عنہ) کے پاس بیٹھے ہوئے تھے اور وہ ہمارے درمیان(اپنے بستر یا بچھونے پر) لیٹے ہوئے تھے تو ایک شخص آیا اور کہنے لگا:ابو عبدالرحمان!ابواب کندہ(کوفہ کا ایک محلہ) میں ایک قصہ گو(واعظ) آیا ہوا ہے،وہ وعظ کررہا ہے اور یہ کہتا ہے کہ دھوئیں والی(اللہ کی)نشانی آئے گی اور(یہ د ھواں) کافروں کی روحیں قبض کرلے گا اور مومنوں کو یہ زکام جیسی کیفیت سے دو چار کرے گا۔حضرت عبداللہ(بن مسعود رضی اللہ تعالیٰ عنہ) نے کہا اور وہ غصے کے عالم میں اٹھ کر بیٹھ گئے،لوگو! اللہ سے ڈرو،تم میں سے جو شخص کوئی چیز جانتا ہو،وہ اتنی ہی بیان کرے جتنی جانتاہو اور جو نہیں جانتا،وہ کہے:اللہ زیادہ جاننے والا ہے۔بے شک وہ(اللہ تعالیٰ) تم میں سے اس کو(بھی) زیادہ جاننے والاہے۔جو اس بات کے بارے میں جو وہ نہیں جانتا،یہ کہتا ہے:اللہ زیادہ جاننے والا ہے۔اللہ عزوجل نے ا پنے نبی کریم صلی اللہ علیہ وسلم سے فرمایا؛\"کہہ دیجئے:میں تم سے کوئی اجر نہیں مانگتا اور نہ ہی بناوٹ کرنے والوں میں سے ہوں۔\"رسول اللہ صلی اللہ علیہ وسلم نے جب لوگوں کی دین سے روگردانی دیکھی تو آپ نے (دعا کرتے ہوئے) فرمایا:\"اے اللہ!(ان پر) یوسف علیہ السلام کےسات سالوں جیسے سات سال(بھیج دے۔)\"(عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ نے) کہا:تو انھیں (قحط کے) ایک سال نے آلیا جس نے ہر چیز کاصفایاکرایا،یہاں تک کہ ان(مشرک)لوگوں نے بھوک سے چمڑے اور مردار تک کھائے۔ان میں سے کوئی شخص آسمان کی طرف دیکھتا تو اسے دھوئیں کے جیسی ایک چیز چھائی ہوئی نظر آتی۔چنانچہ ابو سفیان رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں آیا اور کہا:اے محمد(صلی اللہ علیہ وسلم) آپ آئے ہیں،اللہ کی اطاعت اور صلہ رحمی کاحکم دیتے ہیں،آپ کی قوم(قحط اور بھوک سے) ہلاک ہورہی ہے۔ان کےلیے اللہ سے دعا کریں۔اللہ عزوجل نے فرمایا:\" آپ اس دن کا انتظار کریں جب آسمان ایک نظر آنے والے دھوئیں کو لے آئے گا۔(اور وہ) لوگوں کو ڈھانپ لے گا۔یہ دردناک عذاب ہوگا،سے لے کر اس کے فرمان:\"نے شک تم(کفر میں) لوٹ جانے والے ہوگئے\"تک۔\n(حضرت عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ نے) کہا:کیا آخرت کا عذاب ہٹایا جائے گا؟\"جس دن ہم تم پر بڑی گرفت کریں گے(اس دن) ہم انتقام لینے والے ہوں گے۔\"وہ گرفت بدر کے دن تھی۔اب تک دھوئیں کی نشانی گرفت اور چمٹ جانےوالا عذاب(بدر میں شکست فاش اور قتل)اور روم(کی فتح) کی نشانی(سب) آکر گذر چکی ہیں۔"}],[7124,"ابو معاویہ ، وکیع ، اور جریر نے اعمش سے ، انھوں نے مسلم بن صحیح سے اور انھوں نے مسروق سے روایت کی کہ سیدنا عبداللہ ( بن مسعود رضی اللہ تعالی عنہ ) کے پاس ایک شخص آیا اور کہنے لگا : میں مسجد میں ایک ایسے شخص کو چھوڑ کر آرہا ہوں جو اپنی رائے سے قرآن مجید کی تفسیر کرتا ہے وہ ( قرآن کی ) آیت : \" جب آسمان سے واضح دھواں اٹھے گا \" کی تفسیر کرتا ہے ، کہتا ہے : \" قیامت کےدن لوگوں کے پاس ایک دھواں آئے گا جو لوگوں کی سانسوں کو گرفت میں لے لے گا ، یہاں تک کہ لوگوں کو زکام جیسی کیفیت ( جس میں سانس لینی مشکل ہوجاتی ہے ) درپیش ہوگی ، تو سیدنا عبداللہ ( بن مسعود رضی اللہ تعالی عنہ ) نے کہا : جس کے پاس علم ہو وہ اس کے مطابق بات کہے اور جو نہ جانتا ہو ، وہ کہے : اللہ زیادہ جاننے والا ہے ۔ یہ بات انسان کے فہم ( دین ) کا حصہ ہے ۔ کہ جس بات کو وہ نہیں جانتا اس کے بارے میں کہے : اللہ زیادہ جاننے والاہے ۔ اس ( دھوئیں ) کی حقیقت یہ تھی کہ قریش نے جب نبی کریم صلی اللہ علیہ وسلم کے خلاف سخت نافرمانی سے کام لیا تو آپ نے ان کے خلاف یوسف علیہ السلام ( کے زمانے والے ) قحط کے سالوں جیسی قحط سالی کی دعاکی ۔ انھیں قحط اور تنگ دستی نے آلیا یہاں تک کہ ( ان میں سے ) کوئی شخص آسمان کی طرف دیکھنے لگتا تو بھوک کی شدت سے اسے اپنے اور آسمان کے درمیان دھواں ساچھایا ہوا نظر آتا یہاں تک کہ ان لوگوں نے ( بھوک کی شدت سے ) ہڈیاں تک کھائیں ، چنانچہ ( ان میں سے ) ایک شخص نبی کریم صلی اللہ علیہ وسلم کے پاس آیا اور عرض کی : اللہ کے رسول صلی اللہ علیہ وسلم !آپ ( قبیلہ ) مضر کے لئے بخشش طلب فرمائیں ۔ وہ ہلاکت کا شکار ہیں ، تو آ پ صلی اللہ علیہ وسلم نے فرمایا : \" مضر کے لئے؟تو بہت جراءت والا ہے ( کہ اللہ سے شرک اور اس کے رسول سے بغض کے باوجود د رخواست کررہا ہے کہ میں تمہارے لئے اللہ سے دعا کروں ) \" کہا : آپ صلی اللہ علیہ وسلم نے ( پھر بھی ) ان کے حق میں دعا فرمادی ۔ اس پر اللہ عزوجل نے ( آیت ) نازل فرمائی : \" ہم ( تم سے ) تھوڑے عرصے کے لئے عذاب ہٹادیتے ہیں ۔ تم ( پھر کفر ہی میں ) لوٹنے والا ہو ۔ \" ( سیدنا عبداللہ بن مسعود رضی اللہ تعالی عنہ نے ) کہا : پھر ان پر بارش برسائی گئی ۔ انھیں خوشحالی مل گئی ، کہا : ( تو پھر ) وہ اپنی اسی روش پر لوٹ گئے جس سے پہلے تھے ۔ اس پر اللہ تعالی نے ( یہ حصہ ) نازل فرمایا : \" آپ انتظار کیجئے جب آسمان ظاہر دھواں لے آئے گا ۔ جو لوگوں کو ڈھانپ لے گا ، یہ دردناک عذاب ہوگا ۔ ( پھر یہ آیت نازل فرمائی ) جس دن ہم بڑ ی گرفت میں لیں گے ، ہم انتقام لینے والے ہوں گے ۔ \" کہا : یعنی جنگ بدر کو ۔","",{"u2":"ابو معاویہ،وکیع،اور جریر نے اعمش سے،انھوں نے مسلم بن صحیح سے اور انھوں نے مسروق سے روایت کی کہ حضرت عبداللہ(بن مسعود رضی اللہ تعالیٰ عنہ) کے پاس ایک شخص آیا اور کہنے لگا:میں مسجد میں ایک ایسے شخص کو چھوڑ کر آرہا ہوں جو اپنی رائے سے قرآن مجید کی تفسیر کرتا ہے وہ(قرآن کی) آیت:\"جب آسمان سے واضح دھواں اٹھے گا\"کی تفسیر کرتا ہے،کہتا ہے:\"قیامت کےدن لوگوں کے پاس ایک دھواں آئے گا جو لوگوں کی سانسوں کو گرفت میں لے لے گا،یہاں تک کہ لوگوں کو زکام جیسی کیفیت(جس میں سانس لینی مشکل ہوجاتی ہے)درپیش ہوگی،توحضرت عبداللہ(بن مسعود رضی اللہ تعالیٰ عنہ)نے کہا:جس کے پاس علم ہو وہ اس کے مطابق بات کہے اور جو نہ جانتا ہو،وہ کہے:اللہ زیادہ جاننے والا ہے۔یہ بات انسان کے فہم(دین) کاحصہ ہے۔ کہ جس بات کو وہ نہیں جانتا اس کے بارے میں کہے:اللہ زیادہ جاننے والاہے۔اس(دھوئیں) کی حقیقت یہ تھی کہ قریش نے جب نبی کریم صلی اللہ علیہ وسلم کے خلاف سخت نافرمانی سے کام لیا تو آپ نے ان کے خلاف یوسف علیہ السلام (کے زمانےوالے)قحط کے سالوں جیسی قحط سالی کی دعاکی۔انھیں قحط اور تنگ دستی نے آلیا یہاں تک کہ(ان میں سے) کوئی شخص آسمان کی طرف دیکھنے لگتا تو بھوک کی شدت سے اسے اپنے اور آسمان کے درمیان دھواں ساچھایا ہوا نظرآتا یہاں تک کہ ان لوگوں نے(بھوک کی شدت سے)ہڈیاں تک کھائیں،چنانچہ(ان میں سے) ایک شخص نبی کریم صلی اللہ علیہ وسلم کے پاس آیا اور عرض کی:اللہ کے رسول صلی اللہ علیہ وسلم!آپ(قبیلہ) مضر کے لئے بخشش طلب فرمائیں۔وہ ہلاکت کا شکار ہیں،تو آ پ صلی اللہ علیہ وسلم نے فرمایا:\"مضر کے لئے؟تو بہت جراءت والا ہے(کہ اللہ سے شرک اور اس کے رسول سے بغض کے باوجود د رخواست کررہا ہے کہ میں تمہارے لئے اللہ سے دعا کروں)\"کہا:آپ صلی اللہ علیہ وسلم نے(پھر بھی) ان کے حق میں دعا فرمادی۔اس پر اللہ عزوجل نے(آیت) نازل فرمائی:\"ہم(تم سے) تھوڑے عرصے کے لئے عذاب ہٹادیتے ہیں۔تم(پھر کفر ہی میں) لوٹنے والا ہو۔\"(حضرت عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ نے) کہا:پھر ان پر بارش برسائی گئی۔انھیں خوشحالی مل گئی،کہا:(تو پھر) وہ اپنی اسی روش پر لوٹ گئے جس سے پہلے تھے۔اس پر اللہ تعالیٰ نے (یہ حصہ) نازل فرمایا:\"آپ انتظار کیجئے جب آسمان ظاہر دھواں لے آئے گا۔جو لوگوں کو ڈھانپ لے گا،یہ دردناک عذاب ہوگا۔(پھر یہ آیت نازل فرمائی) جس دن ہم بڑ ی گرفت میں لیں گے،ہم انتقام لینے والے ہوں گے۔\"کہا:یعنی جنگ بدر کو۔"}],[7125,"قتیبہ بن سعید نے ہمیں حدیث بیان کی ، انھوں نے کہا : ہمیں جریر نے اعمش سے حدیث بیان کی ، انھوں نے ابو ضحی سے ، انھوں نے مسروق سے اور انھوں نے سیدنا عبداللہ ( بن مسعود ) رضی اللہ تعالی عنہ سے روایت کی ، کہا : پانچ ( نشانیاں گزر چکی ہیں : دھواں ، چمٹ جانے والا عذاب ( بدر کے دن شکست اور ہلاکتیں ) روم کی فتح ( بدر کےدن ستر مشرکوں کی گرفتاری ) سخت گرفت اور چاند ( کادو ٹکڑے ہونا ۔)","",{"u2":"قتیبہ بن سعید نے ہمیں حدیث بیان کی،انھوں نے کہا:ہمیں جریر نے اعمش سے حدیث بیان کی،انھوں نے ابو ضحیٰ سے،انھوں نے مسروق سے اور انھوں نے حضرت عبداللہ(بن مسعود) رضی اللہ تعالیٰ عنہ سے روایت کی،کہا:پانچ(نشانیاں گزر چکی ہیں:دھواں،چمٹ جانے والا عذاب(بدر کے دن شکست اور ہلاکتیں)روم کی فتح(بدر کےدن ستر مشرکوں کی گرفتاری) سخت گرفت اور چاند(کادو ٹکڑے ہونا۔)"}],[7126,"وکیع نے کہا : ہمیں اعمش نے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی ۔","",{"u2":"وکیع نے کہا:ہمیں اعمش نے اسی سند کے ساتھ اسی کے مانند حدیث بیان کی۔"}],[7127,"محمد بن جعفر نے شعبہ سے ، انھوں نے قتادہ سے ، انھوں نے عزرۃ سے انھوں نے حسن عرفی سے ، انھوں نے یحیی بن جزار سے ، انھوں نے عبدالرحمان بن ابی لیلی سے اور انھوں نے سیدنا ابی ابن کعب رضی اللہ تعالی عنہ سے اللہ عزوجل کے فرمان : \" اور بڑے عذاب سے پہلے ہم انھیں قریب کا ( چھوٹا ) عذاب چکھائیں گے ۔ \" ( کی تفسیر ) کے بارے میں روایت کی ، انھوں نے کہا ( اسی ) دنیا میں پیش آنے والے مصائب ، روم کی فتح ، گرفت ( جنگ بدر ) یا دھواں ( مراد ) ہیں ۔ گرفت اور دھوئیں کے بارے میں شک کرنے والے شعبہ ہیں ۔ ( ان سے اوپر کے راویوں نے یقین سے بتایا ۔ شعبہ نے کہا : انھیں شک ہوا ہے)","",{"u2":"محمد بن جعفر نے شعبہ سے،انھوں نے قتادہ سے،انھوں نے عزرۃ سے انھوں نے حسن عرفی سے،انھوں نے یحییٰ بن جزار سے،انھوں نے عبدالرحمان بن ابی لیلیٰ سے اور انھوں نے حضرت ابی ابن کعب رضی اللہ تعالیٰ عنہ سے اللہ عزوجل کے فرمان:\"اور بڑے عذاب سے پہلے ہم انھیں قریب کا(چھوٹا) عذاب چکھائیں گے۔\"(کی تفسیر) کے بارے میں روایت کی،انھوں نے کہا(اسی) دنیا میں پیش آنے والے مصائب،روم کی فتح،گرفت(جنگ بدر) یا دھواں(مراد) ہیں۔گرفت اور دھوئیں کے بارے میں شک کرنے والے شعبہ ہیں۔(ان سے اوپر کے راویوں نے یقین سے بتایا۔شعبہ نے کہا:انھیں شک ہوا ہے)"}],[7128,"مجاہد نے ابو معمر سے اور انھوں نے سیدنا عبداللہ ( بن مسعود رضی اللہ تعالی عنہ ) سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم کے عہد میں چاند تقسیم ہوکر دو ٹکڑے ہوگیاتو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا؛ \" ( لوگو! اس کو دیکھ لو اور ) گواہ بن جاؤ ۔","",{"u2":"مجاہد نے ابو معمر سے اور انھوں نے حضرت عبداللہ(بن مسعود رضی اللہ تعالیٰ عنہ) سے روایت کی،کہا:رسول اللہ صلی اللہ علیہ وسلم کے عہد میں چاند تقسیم ہوکر دوٹکڑے ہوگیاتو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا؛\"(لوگو! اس کو دیکھ لو اور) گواہ بن جاؤ۔\""}],[7129,"ابو معاویہ ، حفص بن غیاث اور ( علی ) ابن مسہر نے اعمش سے ، انھوں نے ابراہیم ( نخعی ) سے ، انھوں نے ابو معمر سے اور انھوں نے سیدنا عبداللہ بن مسعود رضی اللہ تعالی عنہ سے روایت کی ، کہا : ایک بار ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ منی میں موجودتھے کہ چاند دو ٹکڑوں میں تقسیم ہوگیا ، ایک ٹکڑا پہاڑ کے پیچھے ( نظر آتا ) تھا اور دوسرا ٹکڑا اس سے آگے ( دوسری طرف نظر آتا ) تھا ، تو رسول اللہ صلی اللہ علیہ وسلم نے ہم سے فرمایا : \" ( اس کے ) گواہ بن جاؤ ۔","",{"u2":"ابو معاویہ،حفص بن غیاث اور(علی) ابن مسہر نے اعمش سے،انھوں نے ابراہیم(نخعی) سے،انھوں نے ابو معمر سے اور انھوں نے حضرت عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ سے روایت کی،کہا:ایک بار ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ منیٰ میں موجودتھے کہ چاند دو ٹکڑوں میں تقسیم ہوگیا،ایک ٹکڑا پہاڑ کے پیچھے(نظر آتا) تھا اوردوسرا ٹکڑا اس سے آگے(دوسری طرف نظر آتا) تھا،تو رسول اللہ صلی اللہ علیہ وسلم نے ہم سے فرمایا:\"(اس کے) گواہ بن جاؤ۔\""}],[7130,"شعبہ نے اعمش سے ، انھوں نے ابراہیم سے ، انھوں نے ابو معمر سے اور انھوں نے سیدنا عبداللہ بن مسعود رضی اللہ تعالی عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم کے عہد میں چاند تقسیم ہوکردوٹکڑے ہوگیا ، ایک ٹکڑے کو پہاڑ نے ڈھانپ لیا ( اس پہاڑ کے پیچھے نظر آتا تھا ) اور ایک ٹکڑا پہاڑ کے اوپر تھا ، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا؛ \" اے اللہ ! تو گواہ رہ ۔","",{"u2":"شعبہ نے اعمش سے،انھوں نے ابراہیم سے،انھوں نے ابو معمر سے اور انھوں نے حضرت عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ سے روایت کی،کہا:رسول اللہ صلی اللہ علیہ وسلم کے عہد میں چاند تقسیم ہوکردوٹکڑے ہوگیا،ایک ٹکڑے کو پہاڑ نے ڈھانپ لیا(اس پہاڑ کے پیچھے نظر آتا تھا)اورایک ٹکڑا پہاڑ کے اوپر تھا،تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا؛\"اے اللہ! تو گواہ رہ۔\""}],[7131,"معاذ نے کہا : ہمیں شعبہ نے اعمش سے حدیث بیان کی ، انھوں نے مجاہد سے ، انھوں نے ابن عمر رضی اللہ تعالی عنہ سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی ۔","",{"u2":"معاذ نے کہا:ہمیں شعبہ نے اعمش سے حدیث بیان کی،انھوں نے مجاہد سے،انھوں نے ابن عمر رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی۔"}],[7132,"محمد بن جعفر اور ابن عدی دونوں نے شعبہ سے ، شعبہ سے ابن معاذ کی سند کے ساتھ اسی کی حدیث نے مانند روایت کی ، مکر ابن ابی عدی کی حدیث میں ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \" ( اس کے ) گواہ بن جاؤ ، گواہ بن جاؤ ۔","",{"u2":"محمد بن جعفر اور ابن عدی دونوں نے شعبہ سے، شعبہ سے ابن معاذ کی سند کے ساتھ اسی کی حدیث نے مانند روایت کی،مکر ابن ابی عدی کی حدیث میں ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\"(اس کے) گواہ بن جاؤ،گواہ بن جاؤ۔\""}],[7133,"۔ شیبان نےکہا : ہمیں قتادہ نے سیدنا انس رضی اللہ تعالی عنہ سے روایت کی کہ اہل مکہ نے رسول اللہ صلی اللہ علیہ وسلم سے مطالبہ کہ آپ انھیں ( اپنی نبوت کی سچائی کی ) کوئی نشانی دکھائیں تو آپ نے انھیں چاند کے دو ٹکڑے ہونا دکھایا ۔","",{"u2":"۔ شیبان نےکہا:ہمیں قتادہ نے حضرت انس رضی اللہ تعالیٰ عنہ سے روایت کی کہ اہل مکہ نے رسول اللہ صلی اللہ علیہ وسلم سے مطالبہ کہ آپ انھیں(اپنی نبوت کی سچائی کی) کوئی نشانی دکھائیں تو آپ نے انھیں چاند کے دو ٹکڑے ہونا دکھایا۔"}],[7134,"۔ شیبان نےکہا : ہمیں قتادہ نے سیدنا انس رضی اللہ تعالی عنہ سے روایت کی کہ اہل مکہ نے رسول اللہ صلی اللہ علیہ وسلم سے مطالبہ کہ آپ انھیں ( اپنی نبوت کی سچائی کی ) کوئی نشانی دکھائیں تو آپ نے انھیں چاند کے دو ٹکڑے ہونا دکھایا ۔","",{"u2":"معمر نے ہمیں قتادہ سے،انھوں نے حضرت انس رضی اللہ تعالیٰ عنہ سے شیبان کی حدیث سے ہم معنی روایت کی۔"}],[7135,"یحیی بن سعید ، محمد بن جعفر اور ابو داود سب نے شعبہ سے ، انھوں نے قتادہ سے اور انھوں نے سیدنا انس رضی اللہ تعالی عنہ سے روایت کی ، کہا : چاند دو ٹکڑوں میں پھٹ گیا ۔ اور ابو داود ( طیالسی ) کی حدیث میں ہے رسول اللہ صلی اللہ علیہ وسلم کے عہد مبارک میں چاند پھٹ گیا ۔","",{"u2":"یحییٰ بن سعید،محمد بن جعفر اور ابو داود سب نے شعبہ سے،انھوں نے قتادہ سے اور انھوں نے حضرت انس رضی اللہ تعالیٰ عنہ سے روایت کی،کہا:چاند دو ٹکڑوں میں پھٹ گیا۔\nاور ابو داود(طیالسی) کی حدیث میں ہے رسول اللہ صلی اللہ علیہ وسلم کے عہد مبارک میں چاند پھٹ گیا۔"}],[7136,"سیدنا ابن عباس رضی اللہ تعالی عنہ سے روایت ہے ، کہا : رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں چاند پھٹ گیا ۔","",{"u2":"حضرت ابن عباس رضی اللہ تعالیٰ عنہ سے روایت ہے،کہا:رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں چاند پھٹ گیا۔"}],[7137,"ابو بکر بن ابی شیبہ نے ہمیں حدیث بیان کی ، کہا : ہمیں ابو معاویہ اور ابو اسامہ نے اعمش سے حدیث بیان کی ، انھوں نے سعید بن جبیر سے ، انھوں نے ابو عبدالرحمان سلمی سے اور انھوں نے سیدنا ابو موسی رضی اللہ تعالی عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تکلیف دل باتیں سن کر اللہ سے زیادہ صبر کرنے والا کوئی نہیں ، ا س کے ساتھ دوسروں کو شریک ٹھہرایا جاتا ہے اور اس کی اولاد بنائی جاتی ہے پھر بھی وہ انھیں عافیت میں رکھتا ہے اور انھیں رزق عطا کرتا ہے ۔","",{"u2":"ابو بکر بن ابی شیبہ نے ہمیں حدیث بیان کی،کہا:ہمیں ابو معاویہ اور ابو اسامہ نے اعمش سے حدیث بیان کی،انھوں نے سعید بن جبیر سے،انھوں نے ابو عبدالرحمان سلمی سے اور انھوں نے حضرت ابو موسیٰ رضی اللہ تعالیٰ عنہ سے روایت کی،کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\" تکلیف دل باتیں سن کر اللہ سے زیادہ صبر کرنے والا کوئی نہیں،ا س کے ساتھ دوسروں کو شریک ٹھہرایا جاتا ہے اور اس کی اولاد بنائی جاتی ہے پھر بھی وہ انھیں عافیت میں رکھتا ہے اور انھیں رزق عطا کرتا ہے۔\""}],[7138,"ابو بکر بن ابی شیبہ نے ہمیں حدیث بیان کی ، کہا : ہمیں ابو معاویہ اور ابو اسامہ نے اعمش سے حدیث بیان کی ، انھوں نے سعید بن جبیر سے ، انھوں نے ابو عبدالرحمان سلمی سے اور انھوں نے سیدنا ابو موسی رضی اللہ تعالی عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تکلیف دل باتیں سن کر اللہ سے زیادہ صبر کرنے والا کوئی نہیں ، ا س کے ساتھ دوسروں کو شریک ٹھہرایا جاتا ہے اور اس کی اولاد بنائی جاتی ہے پھر بھی وہ انھیں عافیت میں رکھتا ہے اور انھیں رزق عطا کرتا ہے ۔","",{"u2":"وکیع نے کہا:ہمیں اعمش نے حدیث بیان کی،انھوں نے کہا:ہمیں سعید بن جبیر نے ابو عبدالرحمان سلمی سے،انھوں نے حضرت ابو موسیٰ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی،سوائے آپ صلی اللہ علیہ وسلم کے اس قول کے:\"اور اس کی اولاد بنائی جاتی ہے\"انھوں نے اس(قول) کو بیان نہیں کیا۔"}],[7139,"عبیداللہ بن سعید نے مجھے حدیث بیان کی ، کہا : ہمیں ابو اسامہ نے اعمش سے حدیث بیان کی ، انھوں نے کہا : ہمیں سعید بن جبیر نے ابو عبدالرحمان سلمی سے روایت کی ، انھوں نے کہا : سیدنا عبداللہ بن قیس ( ابو موسی اشعری ) رضی اللہ تعالی عنہ نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کوئی نہیں جو تکلیف دہ باتوں پر جنھیں وہ سنتا ہے اللہ تعالی سے زیادہ صبر کرنے والا ہو ، لوگ ( دوسروں کو ) اس کا شریک ٹھہراتے ہیں ، اس کی اولاد بناتے ہیں اور وہ اس ( سب کچھ ) ک باوجود انھیں رزق دیتا ہے ، عافیت بخشتا ہے اور ( جو مانگتے ہیں ) عطا کرتا ہے ۔","",{"u2":"عبیداللہ بن سعید نے مجھے حدیث بیان کی،کہا:ہمیں ابو اسامہ نے اعمش سے حدیث بیان کی،انھوں نے کہا:ہمیں سعید بن جبیر نے ابو عبدالرحمان سلمی سے روایت کی،انھوں نے کہا:حضرت عبداللہ بن قیس(ابو موسیٰ اشعری) رضی اللہ تعالیٰ عنہ نے کہا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"کوئی نہیں جو تکلیف دہ باتوں پر جنھیں وہ سنتا ہے اللہ تعالیٰ سے زیادہ صبر کرنے والا ہو،لوگ(دوسروں کو) اس کاشریک ٹھہراتے ہیں،اس کی اولاد بناتے ہیں اور وہ اس(سب کچھ) ک باوجود انھیں رزق دیتا ہے،عافیت بخشتا ہے اور(جو مانگتے ہیں) عطا کرتا ہے۔\""}],[7140,"معاذ عنبری نے کہا : ہمیں شعبہ نے ابو عوان جونی سے ، انھوں نے سیدنا انس بن مالک رضی اللہ تعالی عنہ سے ، انھوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا؛ \" اللہ تبارک وتعالی اس شخص سے ، جسے اہل جہنم میں سب سے کم عذاب ہوگا ، فرمائے گا : اگر پوری دنیا اور جو کچھ اس میں ہے ۔ تمہارے پاس ہوتو ( عذاب سے چھوٹ جانے کے لئے ) اسے بطور فدیہ دے دو گے؟وہ کہے گا : ہاں ، تو وہ ( اللہ تعالی ) فرمائے گا : میں نے تم سے اس وقت جب تم آدم علیہ السلام کی پشت میں تھے ، اس کی نسبت بہت کم کا مطالبہ کیا تھا کہ تم شرک نہ کرنا ۔ میرا خیال ہے کہ آپ صلی اللہ علیہ وسلم نے ( آگے یہ ) فرمایا ۔ ۔ ۔ اور میں تمھیں آگ میں نہیں ڈالوں گا ، مگر تم نے شرک ( کرنے ) کے سوا ہر چیز سے انکار کردیا ۔","",{"u2":"معاذ عنبری نے کہا:ہمیں شعبہ نے ابو عوان جونی سے،انھوں نے حضرت انس بن مالک رضی اللہ تعالیٰ عنہ سے،انھوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا؛\" اللہ تبارک وتعالیٰ اس شخص سے،جسے اہل جہنم میں سب سے کم عذاب ہوگا،فرمائے گا:اگر پوری دنیا اور جو کچھ اس میں ہے۔تمہارے پاس ہوتو(عذاب سے چھوٹ جانے کے لئے) اسے بطور فدیہ دے دو گے؟وہ کہے گا:ہاں،تو وہ(اللہ تعالیٰ) فرمائے گا:میں نے تم سے اس وقت جب تم آدم علیہ السلام کی پشت میں تھے،اس کی نسبت بہت کم کا مطالبہ کیا تھا کہ تم شرک نہ کرنا۔میرا خیال ہے کہ آپ صلی اللہ علیہ وسلم نے(آگے یہ) فرمایا۔۔۔اور میں تمھیں آگ میں نہیں ڈالوں گا،مگر تم نے شرک(کرنے) کے سوا ہر چیز سے انکارکردیا۔\""}],[7141,"محمد بن جعفر نے کہا : ہمیں شعبہ نے ابو عمران سے حدیث بیان کی ، کہا : میں نے سیدنا انس بن مالک رضی اللہ تعالی عنہ سے سنا ، وہ نبی اکرم صلی اللہ علیہ وسلم سے حدیث بیان کررہے تھے ، اسی کے مانند ، سوائے ( اللہ تعالی کے ) اس قول کے : \" اور میں تمھیں آگ میں نہیں ڈالوں گا \" انھوں نے اسے بیان نہیں کیا ۔","",{"u2":"محمد بن جعفر نے کہا:ہمیں شعبہ نے ابو عمران سے حدیث بیان کی،کہا:میں نے حضرت انس بن مالک رضی اللہ تعالیٰ عنہ سے سنا،وہ نبی اکرم صلی اللہ علیہ وسلم سے حدیث بیان کررہے تھے،اسی کے مانند،سوائے(اللہ تعالیٰ کے) اس قول کے:\"اور میں تمھیں آگ میں نہیں ڈالوں گا\"انھوں نے اسے بیان نہیں کیا۔"}],[7142,"ہشام ( دستوائی ) نے قتادہ سےروایت کی ، کہا : ہمیں سیدنا انس بن مالک رضی اللہ تعالی عنہ نے حدیث بیان کی کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا \" قیامت کے دن کافر سے کہا جائے گا : تمہارا کیا خیال ہے ، اگر تمہارے پاس زمین ( کی مقدار ) بھر سونا موجود ہوتو کیا تم ( جہنم کے عذاب سے بچنے کے لئے ) اس کو بطور فدیہ دے دو گے؟وہ کہے گا : ہاں ، تو اس سے کہا جائے گا : تم سے تو اس سے بہت آسان مطالبہ کیاگیا تھا ۔","",{"u2":"ہشام(دستوائی) نے قتادہ سےروایت کی،کہا:ہمیں حضرت انس بن مالک رضی اللہ تعالیٰ عنہ نے حدیث بیان کی کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا\"قیامت کے دن کافر سے کہا جائے گا:تمہارا کیا خیال ہے،اگر تمہارے پاس زمین(کی مقدار) بھر سونا موجود ہوتو کیا تم(جہنم کے عذاب سے بچنے کے لئے) اس کو بطور فدیہ دے دو گے؟وہ کہے گا:ہاں،تو اس سے کہا جائے گا:تم سے تو اس سے بہت آسان مطالبہ کیاگیا تھا۔\""}],[7143,"سعید بن ابی عرو بہ نے قتادہ سے ، انھوں نے سیدنا انس رضی اللہ تعالی عنہ سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی ، مگر انھوں نے ( اس طرح ) کہا؛ \" تو اس سے کہاجائے گا : تم جھوٹ بولتے ہو ، تم سے تو اس سے بہت آسان ( بات کا ) مطالبہ کیاگیا تھا ۔","",{"u2":"سعید بن ابی عرو بہ نے قتادہ سے،انھوں نے حضرت انس رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی،مگر انھوں نے (اس طرح) کہا؛\"تو اس سے کہاجائے گا:تم جھوٹ بولتے ہو،تم سے تو اس سے بہت آسان(بات کا) مطالبہ کیاگیا تھا۔\""}],[7144,"شیبان نے ہمیں قتادہ سے حدیث بیان کی ، کہا : ہمیں سیدنا انس بن مالک رضی اللہ تعالی عنہ نے حدیث بیان کی کہ ایک شخص نے کہا : اللہ کے رسول صلی اللہ علیہ وسلم ! قیامت کے روز کافر کو کس طرح منہ کے بل میدان حشر میں لایا جائے گا؟آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" کہ جس نے دنیا میں پاؤں کے بل چلایا ہےوہ اس بات پر قادر نہیں کہ قیامت کے دن اسے منہ کے بل چلائے؟ \"\" قتادہ نے ( حدیث سنانے کے بعد ) کہا : کیوں نہیں ، ہمارے رب کی عزت کی قسم! ( وہ قادر ہے)","",{"u2":"شیبان نے ہمیں قتادہ سے حدیث بیان کی،کہا:ہمیں حضرت انس بن مالک رضی اللہ تعالیٰ عنہ نے حدیث بیان کی کہ ایک شخص نے کہا:اللہ کے رسول صلی اللہ علیہ وسلم! قیامت کے روز کافر کو کس طرح منہ کے بل میدان حشر میں لایا جائے گا؟آپ صلی اللہ علیہ وسلم نے فرمایا:\"کہ جس نے دنیا میں پاؤں کے بل چلایا ہےوہ اس بات پر قادر نہیں کہ قیامت کے دن اسے منہ کے بل چلائے؟\"\nقتادہ نے(حدیث سنانے کے بعد) کہا:کیوں نہیں،ہمارے رب کی عزت کی قسم!(وہ قادر ہے)"}],[7145,"سیدنا انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : قیامت کے دن اہل دوزخ میں سے اس شخص کو لایا جائے گا جو دنیا میں سب سے زیادہ آسودہ تر اور خوشحال تھا ، پس دوزخ میں ایک بار غوطہ دیا جائے گا ، پھر اس سے پوچھا جائے گا کہ اے آدم کے بیٹے! کیا تو نے دنیا میں کبھی آرام دیکھا تھا؟ کیا تجھ پر کبھی چین بھی گزرا تھا؟ وہ کہے گا کہ اللہ کی قسم! اے میرے رب! کبھی نہیں اور اہل جنت میں سے ایک ایسا شخص لایا جائے گا جو دنیا میں سب لوگوں سے سخت تر تکلیف میں رہا تھا ، جنت میں ایک بار غوطہ دیا جائے گا ، پھر اس سے پوچھا جائے گا کہ اے آدم کے بیٹے! تو نے کبھی تکلیف بھی دیکھی ہے؟ کیا تجھ پر شدت اور رنج بھی گزرا تھا؟ وہ کہے گا کہ اللہ کی قسم! مجھ پر تو کبھی تکلیف نہیں گزری اور میں نے تو کبھی شدت اور سختی نہیں دیکھی ۔","",{"u2":"سیدنا انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: قیامت کے دن اہل دوزخ میں سے اس شخص کو لایا جائے گا جو دنیا میں سب سے زیادہ آسودہ تر اور خوشحال تھا، پس دوزخ میں ایک بار غوطہ دیا جائے گا، پھر اس سے پوچھا جائے گا کہ اے آدم کے بیٹے! کیا تو نے دنیا میں کبھی آرام دیکھا تھا؟ کیا تجھ پر کبھی چین بھی گزرا تھا؟ وہ کہے گا کہ اللہ کی قسم! اے میرے رب! کبھی نہیں اور اہل جنت میں سے ایک ایسا شخص لایا جائے گا جو دنیا میں سب لوگوں سے سخت تر تکلیف میں رہا تھا، جنت میں ایک بار غوطہ دیا جائے گا، پھر اس سے پوچھا جائے گا کہ اے آدم کے بیٹے! تو نے کبھی تکلیف بھی دیکھی ہے؟ کیا تجھ پر شدت اور رنج بھی گزرا تھا؟ وہ کہے گا کہ اللہ کی قسم! مجھ پر تو کبھی تکلیف نہیں گزری اور میں نے تو کبھی شدت اور سختی نہیں دیکھی۔"}],[7146,"ہمام بن یحیی نے قتادہ سے ، انھوں نے سیدنا انس بن مالک رضی اللہ تعالی عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" بے شک اللہ تعالی کسی مومن کے ساتھ ایک نیکی کے معاملے میں بھی ظلم نہیں فرماتا ۔ اس کے بدلے اسے دنیا میں بھی عطا کرتا ہے اور آخرت میں بھی اس کی جزا دی جاتی ہے ۔ رہا کافر ، اسے نیکیوں کے بدلے میں جو اس نے دنیا میں اللہ کے لئے کی ہوتی ہیں ، اسی دنیا میں کھلا ( پلا ) دیا جاتاہے حتی کہ جب وہ آخرت میں پہنچتا ہے تو اس کے پاس کوئی نیکی باقی نہیں ہوتی جس کی اسے جزا دی جائے ۔","",{"u2":"ہمام بن یحییٰ نے قتادہ سے،انھوں نے حضرت انس بن مالک رضی اللہ تعالیٰ عنہ سے روایت کی،کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\" بے شک اللہ تعالیٰ کسی مومن کے ساتھ ایک نیکی کے معاملے میں بھی ظلم نہیں فرماتا۔اس کے بدلے اسے دنیا میں بھی عطا کرتا ہے اور آخرت میں بھی اس کی جزا دی جاتی ہے۔رہا کافر،اسے نیکیوں کے بدلے میں جو اس نے دنیا میں اللہ کے لئے کی ہوتی ہیں،اسی دنیا میں کھلا(پلا) دیا جاتاہے حتیٰ کہ جب وہ آخرت میں پہنچتا ہے تو اس کے پاس کوئی نیکی باقی نہیں ہوتی جس کی اسے جزا دی جائے۔\""}],[7147,"معتمر کے والد ( سلیمان ) نے کہا : ہمیں قتادہ نے انس بن مالک رضی اللہ تعالی عنہ سے روایت کی کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے حدیث بیان کی : \" بلاشبہ ایک کافر جب کوئی نیک کام کر تا ہے ۔ تو اس کے بدلے اسے دنیا کے کھانوں ( نعمتوں ) میں سے ایک لقمہ ( نعمت کی صورت میں ) کھلادیتاہے اور مومن اللہ تعالی اس کی نیکیوں کا ذخیرہ آخرت میں کرتا جاتا ہے ۔ اور اس کی اطاعت شعاری پر دنیا میں ( بھی ) اسے رزق عطا فرماتا ہے ۔","",{"u2":"معتمر کے والد(سلیمان) نے کہا:ہمیں قتادہ نے انس بن مالک رضی اللہ تعالیٰ عنہ سے روایت کی کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے حدیث بیان کی:\"بلاشبہ ایک کافر جب کوئی نیک کام کر تا ہے۔ تو اس کے بدلے اسے دنیاکے کھانوں(نعمتوں) میں سے ایک لقمہ(نعمت کی صورت میں)کھلادیتاہے اور مومن اللہ تعالیٰ اس کی نیکیوں کا ذخیرہ آخرت میں کرتا جاتا ہے۔اور اس کی اطاعت شعاری پر دنیا میں(بھی) اسے رزق عطا فرماتا ہے۔\""}],[7148,"سعید ( بن ابی عروبہ ) نے قتادہ سے ، انہوں نے سیدنا انس رضی اللہ تعالی عنہ سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے ان دونوں ( ہمام اور سلیمان ) کی حدیث کے ہم معنی حدیث بیان کی ۔","",{"u2":"سعید(بن ابی عروبہ) نے قتادہ سے،انہوں نے حضرت انس رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے ان دونوں(ہمام اور سلیمان) کی حدیث کے ہم معنی حدیث بیان کی۔"}],[7149,"۔ عبدالاعلی نے ہمیں معمر سے حدیث بیان کی ، انھوں نے زہری سے ، انہوں نے سعید سے ، انھوں نے سیدنا ابو ہریرہ رضی اللہ تعالی عنہ سے روایت کی ، کہا رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" مومن کی مثال کھیتی کی طرح ہے ۔ ہوا مسلسل اس کو ( ایک یا دوسری طرف ) جھکاتی رہتی ہے اور مومن پر مسلسل مصیبتیں آتی رہتی ہیں ، اور منافق کی مثال ودیوار درخت کی طرح ہے ( جس کا تناؤ ہوا میں بھی تن کرکھڑا رہتا ہے ) ۔ بلتا نہیں حتی کہ ( ایک ہی بار ) اسے کاٹ کر گرادیاجاتا ہے ۔","",{"u2":"۔ عبدالاعلیٰ نے ہمیں معمر سے حدیث بیان کی،انھوں نے زہری سے،انہوں نے سعید سے،انھوں نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی،کہا رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\" مومن کی مثال کھیتی کی طرح ہے۔ ہوا مسلسل اس کو(ایک یا دوسری طرف) جھکاتی رہتی ہے اور مومن پر مسلسل مصیبتیں آتی رہتی ہیں،اور منافق کی مثال ودیوار درخت کی طرح ہے(جس کا تناؤ ہوا میں بھی تن کرکھڑا رہتا ہے)۔بلتا نہیں حتیٰ کہ(ایک ہی بار) اسے کاٹ کر گرادیاجاتا ہے۔"}],[7150,"عبدالرزاق نے کہا : ہمیں معمر نے زہری سے اسی سند کے ساتھ خبر دی مگر عبدالرزاق کی حدیث میں آپ صلی اللہ علیہ وسلم کے فرمان : \" اسے جھکاتی رہتی ہے \" کے بجائے \" اسے موڑتی رہتی ہے \" کے الفاظ ہیں ۔","",{"u2":"عبدالرزاق نے کہا:ہمیں معمر نے زہری سے اسی سند کے ساتھ خبر دی مگر عبدالرزاق کی حدیث میں آپ صلی اللہ علیہ وسلم کے فرمان:\"اسے جھکاتی رہتی ہے\"کے بجائے\"اسے موڑتی رہتی ہے\"کے الفاظ ہیں۔"}],[7151,"زکریا بن ابی زائدہ نے سعد بن ابراہیم سے روایت کی ، انھوں نے کہا : مجھے کعب بن مالک رضی اللہ تعالی عنہ کے بیٹے نے اپنے والد کعب بن مالک رضی اللہ تعالی عنہ سے حدیث بیان کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" مومن کی مثال کھیتی کے باریک تیلی جیسے تنے کی ہے ۔ ہوا اسے موڑ دیتی ، ایک مرتبہ زمین پر لٹادیتی ہے اور دوسری مرتبہ اسے سیدھا کریتی ہے ، یہاں تک کہ وہ پیلا ہوکر خشک ہوجاتا ہے اور کافر کی مثال ویودار درخت کی سی ہے جو اپنی جڑوں پر تن کر کھڑا ہوتا ہے ، اسے کوئی چیز موڑ نہیں سکتی ، یہاں تک کہ اس کا اکھڑ کاگرنا ایک ہی بار ہوتا ہے ۔","",{"u2":"زکریا بن ابی زائدہ نے سعد بن ابراہیم سے روایت کی،انھوں نے کہا: مجھے کعب بن مالک رضی اللہ تعالیٰ عنہ کے بیٹے نے اپنے والد کعب بن مالک رضی اللہ تعالیٰ عنہ سے حدیث بیان کی،کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"مومن کی مثال کھیتی کے باریک تیلی جیسے تنے کی ہے۔ہوا اسے موڑ دیتی،ایک مرتبہ زمین پر لٹادیتی ہے اور دوسری مرتبہ اسے سیدھا کریتی ہے،یہاں تک کہ وہ پیلا ہوکر خشک ہوجاتا ہے اور کافر کی مثال ویودار درخت کی سی ہے جو اپنی جڑوں پر تن کر کھڑا ہوتا ہے،اسے کوئی چیز موڑ نہیں سکتی،یہاں تک کہ اس کا اکھڑ کاگرنا ایک ہی بار ہوتا ہے۔\""}],[7152,"زہیر بن حرب نے مجھے حدیث بیان کی ، کہا : ہمیں بشر بن سری اور عبدالرحمان بن مہدی نے حدیث بیان کی ، دونوں نے کہا : ہمیں سفیان بن عینیہ نے سعد بن ابراہیم سے ، انھوں نے عبدالرحمان بن کعب بن مالک سے ، انھوں نے اپنے والد سے حدیث بیان کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا؛ \" مومن کی مثال کھیتی کے تیلی نمانرم تنے کی سی ہے جس کو ہوا موڑتی رہتی ہے ، کبھی اس کو لٹا دیتی ہے اور کبھی کھڑا کردیتی ہے ، حتی کہ اس ( کے پک کرکٹنے ) کا وقت آجاتا ہے ، اور منافق کی مثال ویودار کے مضبوط جڑوں والے درخت کی طرح ہے ، اس پر ( ایسی ) کوئی مشکل نہیں آتی ، حتی کہ ایک ہی دفعہ وہ جڑوں سے اکھڑ ( کرگر ) جاتا ہے ۔","",{"u2":"زہیر بن حرب نے مجھے حدیث بیان کی،کہا:ہمیں بشر بن سری اور عبدالرحمان بن مہدی نے حدیث بیان کی،دونوں نے کہا:ہمیں سفیان بن عینیہ نے سعد بن ابراہیم سے،انھوں نے عبدالرحمان بن کعب بن مالک سے،انھوں نے اپنے والد سے حدیث بیان کی،کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا؛\"مومن کی مثال کھیتی کے تیلی نمانرم تنے کی سی ہے جس کو ہوا موڑتی رہتی ہے،کبھی اس کو لٹا دیتی ہے اور کبھی کھڑا کردیتی ہے،حتیٰ کہ اس(کے پک کرکٹنے) کا وقت آجاتا ہے،اور منافق کی مثال ویودار کے مضبوط جڑوں والے درخت کی طرح ہے،اس پر(ایسی) کوئی مشکل نہیں آتی،حتیٰ کہ ایک ہی دفعہ وہ جڑوں سے اکھڑ(کرگر) جاتا ہے۔\"\nمحمد بن حاتم اور محمود بن غیلان نے مجھے یہی حدیث بیان کی،دونوں نے کہا:ہمیں بشر بن سری نے حدیث بیان کی،انھوں نے کہا:ہمیں سفیان نے سعد بن ابراہیم سے حدیث بیان کی،انھوں نے عبداللہ بن کعب بن مالک سے،انھوں نے ا پنے والد سے،اورانھوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی،مگر محمود نے بشر سے اپنی روایت میں کہا:\"کافر کی مثال ویودار کے درخت کی طرح ہے۔\"اور ابن حاتم نے\"منافق کی مثال\" کہا،جس طرح زہیر نے کہا ہے۔"}],[7153,"محمد بن حاتم اور محمود بن غیلان نے مجھے یہی حدیث بیان کی ، دونوں نے کہا : ہمیں بشر بن سری نے حدیث بیان کی ، انھوں نے کہا : ہمیں سفیان نے سعد بن ابراہیم سے حدیث بیان کی ، انھوں نے عبداللہ بن کعب بن مالک سے ، انھوں نے ا پنے والد سے ، اورانھوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی ، مگر محمود نے بشر سے اپنی روایت میں کہا : \" کافر کی مثال ویودار کے درخت کی طرح ہے ۔ \" اور ابن حاتم نے \" منافق کی مثال \" کہا ، جس طرح زہیر نے کہا ہے ۔"],[7154,"محمد بن بشار اور عبداللہ بن ہاشم نے ہمیں حدیث بیان کی ، دونوں نے کہا : ہمیں یحیی قطان نے سفیان سے ، انھوں نے سعد بن ابراہیم سے حدیث بیان کی ۔ ابن ہاشم نے کہا : عبداللہ بن کعب بن مالک رضی اللہ تعالی عنہ سے روایت ہے ، انھوں نے اپنے والد سے روایت کی اور ابن بشار نے کہا : ابن کعب بن مالک رضی اللہ تعالی عنہ سے ر وایت ہے انھوں نے اپنے والد سے ۔ انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی ، جیسے ان سب کی حدیث ہے ۔ اور ان دونوں نے اپنی حدیث میں کہا : یحیی سے روایت ہے : \" اور کافر کی مثال ویودار کے درخت جیسی ہے ۔","",{"u2":"محمد بن بشار اور عبداللہ بن ہاشم نے ہمیں حدیث بیان کی،دونوں نے کہا: ہمیں یحییٰ قطان نے سفیان سے،انھوں نے سعد بن ابراہیم سے حدیث بیان کی۔ابن ہاشم نے کہا:عبداللہ بن کعب بن مالک رضی اللہ تعالیٰ عنہ سے روایت ہے،انھوں نے اپنے والد سے روایت کی اور ابن بشار نے کہا:ابن کعب بن مالک رضی اللہ تعالیٰ عنہ سے ر وایت ہے انھوں نے اپنے والد سے۔انھوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی،جیسے ان سب کی حدیث ہے۔اور ان دونوں نے اپنی حدیث میں کہا:یحییٰ سے روایت ہے:\"اورکافر کی مثال ویودار کے درخت جیسی ہے۔\""}],[7155,"عبداللہ بن دینار نے کہا کہ انہوں نے سیدنا عبداللہ بن عمر رضی اللہ تعالی عنہ کو یہ کہتے ہوئےسنا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا؛ \"\" درختوں میں سے ایک درخت ہے جس کے پتے نہیں جھڑتے اور وہ درخت مسلمان کی طرح ہے ۔ لہٰذا مجھے بتاؤ کہ وہ کون سادرخت ہے؟ \"\" تو لوگوں کا دھیان جنگل کے مختلف درختوں کی طرف کیا ۔ سیدنا عبداللہ بن عمر رضی اللہ تعالی عنہ نے کہا : میرے دل میں یہ خیال آیا کہ وہ کھجور کا درخت ہے ۔ لیکن میں جھجک گیا پھر وہ ( لوگ ) کہنے لگے : اللہ کے رسول صلی اللہ علیہ وسلم ! آ پ بتائیے کہ وہ کون سا ( درخت ) ہے؟ کہا : تو آپ صلی اللہ علیہ وسلم نے فرمایا؛ \"\" وہ کھجور کا درخت ہے ۔ \"\" ( عبداللہ بن عمر رضی اللہ تعالی عنہ نے ) کہا : تو میں نے یہ ( بات اپنے والد ) سیدنا عمر رضی اللہ تعالی عنہ کو بتائی تو انھوں نے کہا : اگر تم نے کہہ دیا ہوتا کہ وہ کھجور کا درخت ہے تو میرے نزدیک یہ ( جواب ) فلاں فلاں ( سرخ اونٹوں ) سے بھی زیادہ پسندیدہ ہوتا ۔","",{"u2":"عبداللہ بن دینار نے کہا کہ انہوں نے حضرت عبداللہ بن عمر رضی اللہ تعالیٰ عنہ کو یہ کہتے ہوئےسنا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا؛\"درختوں میں سے ایک درخت ہے جس کے پتے نہیں جھڑتے اور وہ درخت مسلمان کی طرح ہے۔لہذا مجھے بتاؤ کہ وہ کون سادرخت ہے؟\"تو لوگوں کا دھیان جنگل کے مختلف درختوں کی طرف کیا۔\nحضرت عبداللہ بن عمر رضی اللہ تعالیٰ عنہ نے کہا:میرے دل میں یہ خیال آیا کہ وہ کھجور کا درخت ہے۔لیکن میں جھجک گیا پھر وہ(لوگ) کہنے لگے:اللہ کے رسول صلی اللہ علیہ وسلم! آ پ بتائیے کہ وہ کون سا(درخت) ہے؟ کہا:تو آپ صلی اللہ علیہ وسلم نے فرمایا؛\" وہ کھجور کا درخت ہے۔\"\n(عبداللہ بن عمر رضی اللہ تعالیٰ عنہ نے) کہا:تو میں نے یہ(بات اپنے والد) حضرت عمر رضی اللہ تعالیٰ عنہ کوبتائی تو انھوں نے کہا:اگر تم نے کہہ دیا ہوتا کہ وہ کھجور کا درخت ہے تو میرے نزدیک یہ(جواب) فلاں فلاں(سرخ اونٹوں)سے بھی زیادہ پسندیدہ ہوتا۔"}],[7156,"ابوخلیل الضبعی نے مجاہد سے اور انھوں نے سیدنا ابن عمر رضی اللہ تعالی عنہ سے روایت کی ، کہا : ایک دن رسول اللہ صلی اللہ علیہ وسلم نے ا پنے صحابہ سے فرمایا؛ \"\" مجھے اس درخت کے بارے میں بتاؤ جس کی مثال مومن جیسی ہے ۔ \"\" تو لوگ جنگلوں کے درختوں میں سے کوئی ( نہ کوئی ) درخت بتانے لگے ۔ ابن عمر رضی اللہ تعالی عنہ نے کہا : اور میرے دل میں یا ( کہا : ) میرے ذہن میں یہ بات ڈالی گئی کہ وہ کھجور کا د رخت ہے میں ارادہ کرنے لگا کہ بتادوں ، لیکن ( وہاں ) قوم کے معمر لوگ موجود تھے تو میں ان کی ہیبت سے متاثر ہوکر بولنے سے رک گیا ۔ جب وہ سب خاموش ہوگئے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا؛ \"\" وہ کھجور کا درخت ہے ۔","",{"u2":"ابوخلیل الضبعی نے مجاہد سے اور انھوں نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے روایت کی،کہا:ایک دن رسول اللہ صلی اللہ علیہ وسلم نے ا پنے صحابہ سے فرمایا؛\"مجھے اس درخت کے بارے میں بتاؤ جس کی مثال مومن جیسی ہے۔\"تو لوگ جنگلوں کے درختوں میں سے کوئی(نہ کوئی) درخت بتانے لگے۔\nابن عمر رضی اللہ تعالیٰ عنہ نے کہا:اور میرے دل میں یا(کہا:) میرے ذہن میں یہ بات ڈالی گئی کہ وہ کھجور کا د رخت ہے میں ارادہ کرنے لگا کہ بتادوں،لیکن(وہاں) قوم کے معمر لوگ موجود تھے تو میں ان کی ہیبت سے متاثر ہوکر بولنے سے رک گیا۔جب وہ سب خاموش ہوگئے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا؛\" وہ کھجور کا درخت ہے۔\""}],[7157,"ابن ابی نجیح نے مجاہد سے روایت کی ، کہا : میں مدینہ تک سیدنا ابن عمر رضی اللہ تعالی عنہ کے ساتھ رہا ، میں نے انھیں ایک حدیث کے سوا رسول اللہ صلی اللہ علیہ وسلم سے کوئی حدیث بیان کرتے ہوئے نہیں سنا ۔ انھوں نے کہا : ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس تھے تو آپ کے پاس کھجور کے تنے کا نرم گودا لایا گیا ۔ پھر ان دونوں ( ابوخلیل ضبعی اور عبداللہ بن دینار ) کی حدیث کی طرح بیان کیا ۔","",{"u2":"ابن ابی نجیح نے مجاہد سے روایت کی،کہا:میں مدینہ تک حضرت ابن عمر رضی اللہ تعالیٰ عنہ کے ساتھ رہا،میں نے انھیں ایک حدیث کے سوا رسول اللہ صلی اللہ علیہ وسلم سے کوئی حدیث بیان کرتے ہوئے نہیں سنا۔انھوں نے کہا:ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس تھے تو آپ کے پاس کھجور کے تنے کانرم گودا لایا گیا۔پھر ان دونوں(ابوخلیل ضبعی اورعبداللہ بن دینار) کی حدیث کی طرح بیان کیا۔"}],[7158,"سیف نے ہمیں حدیث بیان کی ، انھوں نے کہا : میں نے مجاہد کو سنا ، وہ کہہ رہے تھے : میں نے سیدنا ابن عمر رضی اللہ تعالی عنہ کو بیان کرتے ہوئے سنا کہ رسول اللہ صلی اللہ علیہ وسلم کے پا س کھجور کے تنے کا نرم گودا لایا کیا ، پھر ان کی حدیث کی طرح بیان کیا ۔","",{"u2":"سیف نے ہمیں حدیث بیان کی،انھوں نے کہا:میں نے مجاہد کو سنا،وہ کہہ رہے تھے:میں نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ کو بیان کرتے ہوئے سنا کہ رسول اللہ صلی اللہ علیہ وسلم کے پا س کھجور کے تنے کا نرم گودا لایا کیا،پھر ان کی حدیث کی طرح بیان کیا۔"}],[7159,"نافع نے سیدنا ابن عمر رضی اللہ تعالی عنہ سے روایت کی ، کہا : ہم رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر تھے ، آپ نے فرمایا : \"\" مجھے اس درخت کے متعلق بتاؤ جو ایک مسلمان آدمی سے مشابہ یا ( فرمایا : ) کی طرح ہے ، اس کے پتے نہیں جھڑتے ۔ \"\" ( امام مسلم رحمۃ اللہ علیہ کے شاگرد ) ابراہیم ( بن سفیان ) نے کہا : غالباً ( ہمارے شیخ ) امام مسلم نے \"\" اور وہ ( درخت ) اپنا پھل دیتاہے \"\" کہا ہوگا ( لیکن میرے پاس \"\" نہیں دیتا \"\" لکھا ہے ) اور میں نے اپنے دوسرے ساتھیوں کے ہاں بھی ( ان کے نسخوں میں ) یہی پایا ہے : اور وہ ہر وقت اپنا پھل نہیں دیتا ۔ سیدنا ابن عمر رضی اللہ تعالی عنہ نے کہا : تو میرے دل میں آیا کہ وہ کھجور کا درخت ہے ۔ مگر میں نے سیدنا ابو بکر وعمر رضی اللہ تعالی عنہ کو دیکھاکہ وہ نہیں بول رہے تھے تو میں نے یہ بات ناپسندی کہ میں بولوں اور کچھ کہوں ، چنانچہ ( میری بات سن کر سیدنا عمر رضی اللہ تعالی عنہ نے کہا : اگر تم یہ بات کہہ دیتے تو مجھے یہ فلاں فلاں ( سرخ اونٹوں ) سے زیادہ پسند ہوتا ۔","",{"u2":"نافع نے حضرت ابن عمر رضی اللہ تعالیٰ عنہ سے روایت کی،کہا:ہم رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر تھے،آپ نے فرمایا:\"مجھے اس درخت کے متعلق بتاؤ جو ایک مسلمان آدمی سے مشابہ یا(فرمایا:) کی طرح ہے،اس کے پتے نہیں جھڑتے۔\"\n(امام مسلم رحمۃ اللہ علیہ کےشاگرد) ابراہیم(بن سفیان) نے کہا:غالباً(ہمارے شیخ) امام مسلم نے\"اور وہ(درخت) اپنا پھل دیتاہے\"کہا ہوگا(لیکن میرے پاس\" نہیں دیتا\"لکھا ہے) اور میں نے اپنے دوسرے ساتھیوں کے ہاں بھی(ان کے نسخوں میں) یہی پایا ہے:اور وہ ہر وقت اپنا پھل نہیں دیتا۔\nحضرت ابن عمر رضی اللہ تعالیٰ عنہ نے کہا:تو میرے دل میں آیا کہ وہ کھجور کا درخت ہے۔مگر میں نے حضرت ابو بکر وعمر رضی اللہ تعالیٰ عنہ کو دیکھاکہ وہ نہیں بول رہے تھے تو میں نے یہ بات ناپسندی کہ میں بولوں اور کچھ کہوں،چنانچہ(میری بات سن کر حضرت عمر رضی اللہ تعالیٰ عنہ نے کہا:اگر تم یہ بات کہہ دیتے تو مجھے یہ فلاں فلاں (سرخ اونٹوں) سے زیادہ پسندہوتا۔"}],[7160,"جریر نےاعمش سے ، انھوں نے ابو سفیان سے اور انھوں نے سیدنا جابر رضی اللہ تعالی عنہ سے روایت کی ، کہا میں نے نبی صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا : \" شیطان اس بات سے ناامید ہوگیا ہے کہ جزیر ہ عرب میں نماز پڑھنے والے اس کی عبادت کریں گے لیکن وہ ان کے درمیان لڑائی جھگڑے کرانے سے ( مایوس نہیں ہوا ۔)","",{"u2":"جریر نےاعمش سے،انھوں نے ابو سفیان سے اور انھوں نے حضرت جابر رضی اللہ تعالیٰ عنہ سے روایت کی، کہا میں نے نبی صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا:\"شیطان اس بات سے ناامید ہوگیا ہے کہ جزیر ہ عرب میں نماز پڑھنے والے اس کی عبادت کریں گے لیکن وہ ان کے درمیان لڑائی جھگڑے کرانے سے (مایوس نہیں ہوا۔)"}],[7161,"وکیع اور ابو معاویہ دونوں نے اعمش سے اسی سند کے ساتھ حدیث بیان کی ۔","",{"u2":"وکیع اور ابو معاویہ دونوں نے اعمش سے اسی سند کے ساتھ حدیث بیان کی۔"}],[7162,"جریر اعمش سے ، انھوں نے ابو سفیان سے اور انھوں نے سیدنا جابر رضی اللہ تعالی عنہ سے روایت کی ، کہا : میں نے نبی صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا : \" ابلیس کا تخت سمندر پر ہے ۔ وہ اپنے لشکر روانہ کرتا رہتا ہے تاکہ وہ فتنے برپا کریں ۔ اس کے نزدیک ( شیطنت کے ) درجے میں سب سے بڑا وہ ہے جو زیادہ بڑا فتنہ برپا کرے ۔","",{"u2":"جریر اعمش سے، انھوں نے ابو سفیان سے اور انھوں نے حضرت جابر رضی اللہ تعالیٰ عنہ سے روایت کی، کہا: میں نے نبی صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا:\"ابلیس کا تخت سمندرپر ہے۔وہ اپنے لشکر روانہ کرتا رہتا ہے تاکہ وہ فتنے برپا کریں۔اس کے نزدیک (شیطنت کے) درجے میں سب سے بڑا وہ ہے جو زیادہ بڑا فتنہ برپا کرے۔\""}],[7163,"ابو معاویہ نے کہا : ہمیں اعمش نے ابو سفیان سے حدیث بیان کی ، انھوں نے سیدنا جابر رضی اللہ تعالی عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" ابلیس اپنا تخت پانی پر بچھاتا ہے پھر وہ اپنے لشکر روانہ کرتا ہے اس کے سب سے زیادہ قریب وہ ہوتا ہے جو سب سے بڑا فتنہ ڈالتا ہے ان میں سے ایک آکر کہتا ہے میں نے فلاں فلاں کا م کیا ہے ، وہ کہتا ہے ۔ تم نے کچھ نہیں کیا ، پھر ان میں سے ایک آکر کہتا ہے : میں نے اس شخص کو ( جس کے ساتھ میں تھا ) اس وقت تک نہیں چھوڑا ، یہاں تک کہ اس کے اور اس کی بیوی کے درمیان تفریق کرادی کہا : کہا : وہ اس کو اپنے قریب کرتا ہے اور کہتا ہے تم سب سے بہتر ہو ۔ \"\" اعمش نے کہا میراخیال ہے اس ( ابو سفیان طلحہ بن نافع ) نے کہا : \"\" پھر وہ اسے اپنے ساتھ لگا لیتا ہے ۔","",{"u2":"ابو معاویہ نے کہا: ہمیں اعمش نے ابو سفیان سے حدیث بیان کی، انھوں نے حضرت جابر رضی اللہ تعالیٰ عنہ سے روایت کی، کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"ابلیس اپنا تخت پانی پر بچھاتا ہے پھر وہ اپنے لشکر روانہ کرتا ہے اس کے سب سے زیادہ قریب وہ ہوتا ہے جو سب سے بڑا فتنہ ڈالتا ہے ان میں سے ایک آکر کہتا ہے میں نے فلاں فلاں کا م کیا ہے،وہ کہتا ہے۔تم نے کچھ نہیں کیا،پھر ان میں سے ایک آکر کہتا ہے: میں نے اس شخص کو(جس کے ساتھ میں تھا)اس وقت تک نہیں چھوڑا،یہاں تک کہ اس کے اور اس کی بیوی کے درمیان تفریق کرادی کہا: کہا: وہ اس کو اپنے قریب کرتا ہے اور کہتا ہے تم سب سے بہتر ہو۔\"\nاعمش نے کہا میراخیال ہے اس (ابو سفیان طلحہ بن نافع)نے کہا:\"پھر وہ اسے اپنے ساتھ لگالیتا ہے۔\""}],[7164,"ابو زبیر نے سیدنا جابر رضی اللہ تعالی عنہ سے روایت کی کہ انھوں نے نبی صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا : \" شیطان اپنے لشکروں کو بھیجتا ہے اور وہ لوگوں کو فتنوں میں ڈالتے ہیں اس کے نزدیک ان میں سے بڑے مرتبے والا وہ ہو تا ہے جو زیادہ بڑا فتنہ ڈالتا ہے ۔","",{"u2":"ابو زبیر نے حضرت جابر رضی اللہ تعالیٰ عنہ سے روایت کی کہ انھوں نے نبی صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا:\"شیطان اپنے لشکروں کو بھیجتا ہے اور وہ لوگوں کو فتنوں میں ڈالتے ہیں اس کے نزدیک ان میں سے بڑے مرتبے والا وہ ہو تا ہے جو زیادہ بڑا فتنہ ڈالتا ہے۔\""}],[7165,"عثمان بن ابی شیبہ اور اسحٰق بن ابراہیم نے کہا : ہمیں جریر نے منصور سے حدیث بیان کی ، انھوں نے سالم بن ابی جعد سے ، انھوں نے اپنے والد سے اور انھوں نےسیدنا عبد اللہ بن مسعود رضی اللہ تعالی عنہ سے روایت کی کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تم میں سے کو ئی شخص بھی نہیں مگر اللہ نے اس کے ساتھ جنوں میں سے اس کا ایک ساتھی مقرر کردیا ہے ( جو اسے برائی کی طرف مائل رہتا ہے ۔ ) \" انھوں ( صحابہ کرام رضوان اللہ عنھم اجمعین ) نے کہا : اللہ کے رسول اللہ صلی اللہ علیہ وسلم ! آپ کے ساتھ بھی؟ آپ صلی اللہ علیہ وسلم نے فرمایا : \" اور میرے ساتھ بھی لیکن اللہ تعالی نے اس کے مقابلے میں میری مدد فرمائی ہے اور وہ مسلمان ہوگیا ، اس لیے ( اب ) وہ مجھے خیر کے سواکوئی بات نہیں کہتا ۔","",{"u2":"عثمان بن ابی شیبہ اور اسحٰق بن ابراہیم نے کہا:ہمیں جریر نے منصور سے حدیث بیان کی،انھوں نے سالم بن ابی جعد سے، انھوں نےاپنے والد سے اور انھوں نےحضرت عبد اللہ بن مسعود رضی اللہ تعالیٰ عنہ سے روایت کی کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"تم میں سے کو ئی شخص بھی نہیں مگر اللہ نے اس کے ساتھ جنوں میں سے اس کا ایک ساتھی مقرر کردیا ہے (جو اسے برائی کی طرف مائل رہتا ہے۔)\"انھوں (صحابہ کرام رضوان اللہ عنھم اجمعین)نے کہا: اللہ کے رسول اللہ صلی اللہ علیہ وسلم! آپ کے ساتھ بھی؟ آپ صلی اللہ علیہ وسلم نے فرمایا:\"اور میرے ساتھ بھی لیکن اللہ تعالیٰ نے اس کے مقابلے میں میری مدد فرمائی ہے اور وہ مسلمان ہوگیا،اس لیے(اب)وہ مجھے خیر کے سواکوئی بات نہیں کہتا۔\""}],[7166,"سفیان اور عمار بن رزیق دونوں نے منصور سے جریر کی سند کے ساتھ انھی کی حدیث کے مانند روایت کی ، مگر سفیان کی حدیث میں ہے : \" ہر شخص کے لیے ایک ساتھی جنوں میں سے اور ایک ساتھی فرشتوں میں سے مقرر کر دیا ہے ۔ ( جن اسے برائی کی طرف مائل کرتا ہے اور فرشتہ نیکی کی طرف ۔ فیصلہ خود اسی کو کرنا ہوتا ہے ۔)","",{"u2":"سفیان اور عمار بن رزیق دونوں نے منصور سے جریر کی سند کے ساتھ انھی کی حدیث کے مانند روایت کی، مگر سفیان کی حدیث میں ہے:\"ہر شخص کے لیے ایک ساتھی جنوں میں سے اور ایک ساتھی فرشتوں میں سے مقرر کر دیاہے۔(جن اسے برائی کی طرف مائل کرتا ہے اور فرشتہ نیکی کی طرف۔فیصلہ خود اسی کو کرنا ہوتا ہے۔)"}],[7167,"عروہ نے کہا : نبی صلی اللہ علیہ وسلم کی اہلیہ سیدہ عائشہ رضی اللہ تعالی عنہا نے انھیں حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم ایک رات ان کے پاس سے اٹھ کر باہر نکل گئے ۔ ( سیدہ عائشہ رضی اللہ تعالی عنہا نے ) کہا : مجھے آپ کے معاملے میں شدید غیرت محسوس ہوئی ، پھر آپ واپس آئے اور دیکھا کہ میں کیا کر رہی ہوں ( شدید غصے کے عالم میں ہوں ) تو آپ صلی اللہ علیہ وسلم نے فرمایا : \" عائشہ رضی اللہ تعالی عنہا !تمھیں کیا ہوا ہے کیا تم غیرت میں مبتلا ہو گئی ہو؟ \" میں نے کہا : مجھے کیا ہوا ہے کہ مجھ جیسی عورت کو ( جس کی کئی سو کنیں ہوں ) آپ جیسے مرد پر ( جو ایک کو ایک سے بڑھ کر محبوب ہو ) غیرت نہ آئے \" تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کیا تمھارے پاس تمھارا شیطان آیا تھا ( اور اس نے تمھیں شک میں مبتلا کیا؟ ) \" ( سیدہ عائشہ رضی اللہ تعالی عنہ نے ) کہا : اللہ کے رسول صلی اللہ علیہ وسلم !کیا میرے ساتھ شیطان بھی ہے؟آپ صلی اللہ علیہ وسلم نے فرمایا : \" ہاں ۔ \" میں نے کہا : ہر انسان کے ساتھ شیطان ہوتا ہے؟ آپ نے فرمایا : \" ہاں ۔ \" میں نے کہا : اللہ کے رسول اللہ صلی اللہ علیہ وسلم !آپ کے ساتھ بھی ہے؟آپ نے فرمایا : \" ہاں لیکن میرے رب نے اس پر ( قابو پانے میں ) میری مدد فرمائی اور وہ اسلام لے آیا ہے ۔","",{"u2":"عروہ نے کہا: نبی صلی اللہ علیہ وسلم کی اہلیہ حضرت عائشہ رضی اللہ تعالیٰ عنہا نے انھیں حدیث بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم ایک رات ان کے پاس سے اٹھ کر باہر نکل گئے۔(حضرت عائشہ رضی اللہ تعالیٰ عنہا نے)کہا: مجھے آپ کے معاملے میں شدید غیرت محسوس ہوئی،پھر آپ واپس آئے اور دیکھا کہ میں کیا کر رہی ہوں (شدید غصے کے عالم میں ہوں) تو آپ صلی اللہ علیہ وسلم نے فرمایا:\"عائشہ رضی اللہ تعالیٰ عنہا!تمھیں کیاہوا ہے کیا تم غیرت میں مبتلا ہو گئی ہو؟\"میں نے کہا: مجھے کیا ہوا ہے کہ مجھ جیسی عورت کو (جس کی کئی سو کنیں ہوں)آپ جیسے مرد پر (جو ایک کو ایک سے بڑھ کر محبوب ہو) غیرت نہ آئے \"تورسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\" کیا تمھارے پاس تمھارا شیطان آیا تھا (اور اس نے تمھیں شک میں مبتلا کیا؟)\"(حضرت عائشہ رضی اللہ تعالیٰ عنہ نے)کہا: اللہ کے رسول صلی اللہ علیہ وسلم!کیا میرے ساتھ شیطان بھی ہے؟آپ صلی اللہ علیہ وسلم نے فرمایا:\"ہاں۔\"میں نے کہا: ہر انسان کے ساتھ شیطان ہوتا ہے؟ آپ نے فرمایا:\"ہاں۔\"میں نے کہا:اللہ کے رسول اللہ صلی اللہ علیہ وسلم!آپ کے ساتھ بھی ہے؟آپ نے فرمایا:\"ہاں لیکن میرے رب نے اس پر (قابو پانے میں)میری مددفرمائی اور وہ اسلام لے آیا ہے۔\""}],[7168,"لیث نے بکیر سے انھوں نے بسربن سعید سے ، انھوں نے سیدنا ابو ہریرہ رضی اللہ تعالی عنہ سے اور انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" تم میں سے کسی شخص کو محض اس کا عمل نجات نہیں دلائے گا ۔ \" ایک شخص نے کہا : اللہ کے رسول اللہ صلی اللہ علیہ وسلم !آپ کو بھی نہیں؟آپ نے فرمایا : \" مجھے بھی نہیں مگر یہ کہ اللہ تعالی اپنی طرف سے مجھے اپنی رحمت سے چھپالے ، لیکن تم سیدھے راستے پر چلو ۔","",{"u2":"لیث نے بکیر سے انھوں نے بسربن سعید سے، انھوں نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے اور انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا:\"تم میں سے کسی شخص کو محض اس کا عمل نجات نہیں دلائے گا۔\"ایک شخص نے کہا: اللہ کے رسول اللہ صلی اللہ علیہ وسلم!آپ کو بھی نہیں؟آپ نے فرمایا:\"مجھے بھی نہیں مگر یہ کہ اللہ تعالیٰ اپنی طرف سے مجھے اپنی رحمت سے چھپالے،لیکن تم سیدھے راستے پر چلو۔\""}],[7169,"لیث نے بکیر سے انھوں نے بسربن سعید سے ، انھوں نے سیدنا ابو ہریرہ رضی اللہ تعالی عنہ سے اور انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" تم میں سے کسی شخص کو محض اس کا عمل نجات نہیں دلائے گا ۔ \" ایک شخص نے کہا : اللہ کے رسول اللہ صلی اللہ علیہ وسلم !آپ کو بھی نہیں؟آپ نے فرمایا : \" مجھے بھی نہیں مگر یہ کہ اللہ تعالی اپنی طرف سے مجھے اپنی رحمت سے چھپالے ، لیکن تم سیدھے راستے پر چلو ۔","",{"u2":"عمرو بن حارث نے بکیر بن اشج سے اسی سند کے ساتھ روایت کی مگر (اس میں)کہا:\"اپنی رحمت اور فضل سے\"اور انھوں نے:\"اور لیکن تم سیدھے راستے پر چلو۔\"بیان نہیں کیا۔"}],[7170,"ایوب نے محمد ( بن سیرین ) اسے اور انھوں نے سیدنا ابوہریرہ رضی اللہ تعالی عنہ سے روایت کی ۔ کہ نبی صلی اللہ علیہ وسلم نے فرمایا : \" تم میں سے کسی شخص کو اس کا عمل جنت میں نہیں لے جائے گا ۔ \" پوچھا گیا : اللہ کے رسول اللہ صلی اللہ علیہ وسلم ! آپ کو بھی نہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا : \" مجھے بھی نہیں مگر یہ کہ میرا رب مجھے اپنی رحمت میں چھپالے ۔","",{"u2":"ایوب نے محمد (بن سیرین)اسے اور انھوں نے حضرت ابوہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی۔ کہ نبی صلی اللہ علیہ وسلم نے فرمایا:\"تم میں سے کسی شخص کو اس کا عمل جنت میں نہیں لے جائے گا۔\"پوچھا گیا: اللہ کے رسول اللہ صلی اللہ علیہ وسلم! آپ کو بھی نہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا:\"مجھے بھی نہیں مگر یہ کہ میرا رب مجھے اپنی رحمت میں چھپالے۔\""}],[7171,"ابن عون نے محمد ( بن سیرین ) سے اور انھوں نے سیدنا ابوہریرہ رضی اللہ تعالی عنہ سے روایت کی کہا : نبی صلی اللہ علیہ وسلم نے فرمایا : \" تم میں سے کسی شخص کو اس کا عمل نجات نہیں دلائے گا ۔ \" صحابہ کرام رضوان اللہ عنھم اجمعین نے عرض کی ، اللہ کے رسول اللہ صلی اللہ علیہ وسلم !آپ کو بھی نہیں؟آپ صلی اللہ علیہ وسلم نے فرمایا : \" مجھے بھی نہیں مگر یہ کہ اللہ تعالی مجھے اپنی رحمت اور مغفرت میں چھپالے ۔ \" اور ابن عون نے اس طرح اپنے ہاتھ سے بتایا اور اپنے سرکی طرف ( رحمت سے ڈھانپ لینے کا ) اشارہ کیا ( فرمایا ) \" اور مجھے بھی نہیں مگر یہ کہ اللہ مجھے ( اس طرح ) اپنی رحمت اور مغفرت سے ڈھانپ لے ۔","",{"u2":"ابن عون نے محمد (بن سیرین)سے اور انھوں نے حضرت ابوہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی کہا:نبی صلی اللہ علیہ وسلم نے فرمایا:\"تم میں سے کسی شخص کو اس کا عمل نجات نہیں دلائے گا۔\"صحابہ کرام رضوان اللہ عنھم اجمعین نے عرض کی، اللہ کے رسول اللہ صلی اللہ علیہ وسلم!آپ کو بھی نہیں؟آپ صلی اللہ علیہ وسلم نے فرمایا:\"مجھے بھی نہیں مگر یہ کہ اللہ تعالیٰ مجھے اپنی رحمت اور مغفرت میں چھپالے۔\"اور ابن عون نے اس طرح اپنے ہاتھ سے بتایا اور اپنے سرکی طرف (رحمت سے ڈھانپ لینےکا) اشارہ کیا(فرمایا)\"اور مجھے بھی نہیں مگر یہ کہ اللہ مجھے (اس طرح) اپنی رحمت اور مغفرت سے ڈھانپ لے۔\""}],[7172,"سہیل کے والد ( ابو صالح ) نے سیدنا ابو ہریرہ رضی اللہ تعالی عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" کسی کو اس کا عمل نجات نہیں دلائے گا ۔ \" انھوں ( صحابہ کرام رضوان اللہ عنھم اجمعین ) نے کہا : اللہ کے رسول اللہ صلی اللہ علیہ وسلم !آپ کو بھی نہیں ؟آپ صلی اللہ علیہ وسلم نے فرمایا : \" مجھے بھی نہیں مگر یہ کہ اللہ تعالی مجھے اپنی رحمت میں لے لے ۔","",{"u2":"سہیل کے والد (ابو صالح) نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\" کسی کو اس کا عمل نجات نہیں دلائے گا۔\"انھوں (صحابہ کرام رضوان اللہ عنھم اجمعین)نے کہا:اللہ کے رسول اللہ صلی اللہ علیہ وسلم!آپ کو بھی نہیں؟آپ صلی اللہ علیہ وسلم نے فرمایا:\" مجھے بھی نہیں مگر یہ کہ اللہ تعالیٰ مجھے اپنی رحمت میں لے لے۔\""}],[7173,"سیدنا عبدالرحمٰن بن عوف رضی اللہ تعالی عنہ کے آزاد کردہ غلام ابو عبید نے سیدنا ابو ہریرہ رضی اللہ تعالی عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" تم میں سے کسی شخص کو اس کا عمل جنت میں نہیں لے جائے گا ۔ \" انھوں ( صحابہ کرام رضوان اللہ عنھم اجمعین نے عرض کی ، اللہ کے رسول اللہ صلی اللہ علیہ وسلم !آپ کو بھی نہیں؟ آپ نے فرمایا : \" مجھے بھی نہیں مگر یہ کہ اللہ تعالی مجھے اپنے فضل اور رحمت سے ڈھانپ لے ۔)","",{"u2":"حضرت عبدالرحمٰن بن عوف رضی اللہ تعالیٰ عنہ کے آزاد کردہ غلام ابو عبید نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی،کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\" تم میں سے کسی شخص کو اس کا عمل جنت میں نہیں لے جائے گا۔\"انھوں(صحابہ کرام رضوان اللہ عنھم اجمعین نے عرض کی، اللہ کے رسول اللہ صلی اللہ علیہ وسلم!آپ کو بھی نہیں؟ آپ نے فرمایا:\" مجھے بھی نہیں مگر یہ کہ اللہ تعالیٰ مجھے اپنے فضل اور رحمت سے ڈھانپ لے۔\""}],[7174,"محمد بن عبد اللہ بن نمیر نے ہمیں حدیث بیان کی ، کہا : ہمیں میرے والد نے حدیث بیان کی ، کہا : ہمیں اعمش نے ابو صالح سے حدیث بیان کی ، انھوں نے سیدنا ابو ہریرہ رضی اللہ تعالی عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" ( عمل کے اعلی ترین معیار کے ) قریب تر رہنے کی کوشش کرو ۔ صحیح راستہ اختیار کرو اور یقین رکھو کہ تم میں سے کسی شخص کو اس کا عمل نجات نہیں دے گا ۔ \" انھوں نے ( صحابہ کرام رضوان اللہ عنھم اجمعین ) نے عرض کی ، اللہ کے رسول اللہ صلی اللہ علیہ وسلم !آپ کو بھی نہیں؟آپ صلی اللہ علیہ وسلم نے فرمایا : \" مجھے بھی نہیں مگر یہ کہ اللہ تعالی مجھے اپنی رحمت اور فضل سے ڈھانپ لے ۔","",{"u2":"محمد بن عبد اللہ بن نمیر نے ہمیں حدیث بیان کی،کہا: ہمیں میرے والد نے حدیث بیان کی، کہا:ہمیں اعمش نے ابو صالح سے حدیث بیان کی،انھوں نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی، کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"(عمل کے اعلیٰ ترین معیار کے) قریب تر رہنے کی کوشش کرو۔صحیح راستہ اختیار کرو اور یقین رکھو کہ تم میں سے کسی شخص کو اس کا عمل نجات نہیں دے گا۔\"انھوں نے (صحابہ کرام رضوان اللہ عنھم اجمعین) نے عرض کی، اللہ کے رسول اللہ صلی اللہ علیہ وسلم!آپ کو بھی نہیں؟آپ صلی اللہ علیہ وسلم نے فرمایا:\"مجھے بھی نہیں مگر یہ کہ اللہ تعالیٰ مجھے اپنی رحمت اور فضل سے ڈھانپ لے۔\""}],[7175,"ابن نمیر نے ہمیں حدیث بیان کی ، انھوں نے کہا : ہمیں میرے والد نے حدیث سنائی ، انھوں نے کہا : ہمیں اعمش نے ابو سفیان سے ، انھوں نے سیدنا جابر رضی اللہ تعالی عنہ سے روایت کی ، انھوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی ۔","",{"u2":"ابن نمیر نے ہمیں حدیث بیان کی،انھوں نے کہا: ہمیں میرے والد نے حدیث سنائی،انھوں نے کہا: ہمیں اعمش نے ابو سفیان سے، انھوں نے حضرت جابر رضی اللہ تعالیٰ عنہ سے روایت کی، انھوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی۔"}],[7176,"جریر نے اعمش سے گزشتہ دونوں سندوں کے ساتھ ابن نمیر کی روایت کی طرح بیان کیا ۔","",{"u2":"جریر نے اعمش سے گزشتہ دونوں سندوں کے ساتھ ابن نمیر کی روایت کی طرح بیان کیا۔"}],[7177,"ابو معاویہ نے اعمش سے انھوں نے ابو صالح سے ، انھوں نے سیدنا ابو ہریرہ رضی اللہ تعالی عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی اور اس میں مزید کہا : \" اور خوش خبری لو ۔ \" ( کہ اس کی رحمت بہت وسیع ہے ، اچھے عمل قبول ہو جائیں گے ۔)","",{"u2":"ابو معاویہ نے اعمش سے انھوں نے ابو صالح سے،انھوں نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی صلی اللہ علیہ وسلم سے اسی کے مانند روایت کی اور اس میں مزید کہا: \"اور خوش خبری لو۔\"(کہ اس کی رحمت بہت وسیع ہے،اچھے عمل قبول ہو جائیں گے۔)\""}],[7178,"ابو زبیر نے سیدنا جابر رضی اللہ تعالی عنہ سے روایت کی ، کہا : میں نے نبی صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا : \" تم میں سے کسی شخص کو اس کا عمل نہ جنت میں لے جائے گا ۔ نہ دوزخ سے محفوظ رکھے گا اور نہ مجھے سوائے اللہ کی طرف سے رحمت کے ( جو نجات کا سبب بنے گی ۔)","",{"u2":"ابو زبیر نے حضرت جابر رضی اللہ تعالیٰ عنہ سے روایت کی، کہا: میں نےنبی صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"تم میں سے کسی شخص کو اس کا عمل نہ جنت میں لے جائے گا۔نہ دوزخ سے محفوظ رکھے گا اور نہ مجھے سوائے اللہ کی طرف سے رحمت کے (جو نجات کا سبب بنے گی۔)\""}],[7179,"عبد العزیزبن محمد اور وہیب نے کہا : ہمیں موسی بن عقبہ نے حدیث بیان کی انھوں نے کہا : میں نے ابو سلمہ بن عبد الرحمٰن بن عوف کو سیدہ عائشہ رضی اللہ تعالی عنہا سے حدیث بیان کرتے ہوئے سنا ، وہ کہا کرتی تھیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" صحیح عمل کرو ( اعلی ترین معیار کے ) قریب تر رہو اور ( اللہ کی رحمت کی ) خوش خبری ( کی امید ) رکھو ۔ حقیقت یہی ہے کہ کسی کو اس کا عمل ہر گز جنت میں داخل نہیں کرے گا ۔ \" صحابہ کرام رضوان اللہ عنھم اجمعین نے کہا : اللہ کے رسول اللہ صلی اللہ علیہ وسلم !آپ کو بھی نہیں؟فرمایا : \" مجھے بھی نہیں الایہ کہ اللہ مجھے اپنی رحمت سے ڈھانپ لے اور جان رکھو کہ اللہ کے نزدیک محبوب ترین عمل وہ ہے جو ہمیشہ کیا جائے چاہے کم ہو ۔","",{"u2":"عبد العزیزبن محمد اور وہیب نے کہا: ہمیں موسیٰ بن عقبہ نے حدیث بیان کی انھوں نے کہا: میں نے ابو سلمہ بن عبد الرحمٰن بن عوف کو حضرت عائشہ رضی اللہ تعالیٰ عنہا سے حدیث بیان کرتے ہوئے سنا،وہ کہا کرتی تھیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"صحیح عمل کرو (اعلی ترین معیار کے) قریب تر رہواور (اللہ کی رحمت کی) خوش خبری (کی امید) رکھو۔حقیقت یہی ہے کہ کسی کو اس کا عمل ہر گز جنت میں داخل نہیں کرے گا۔\"صحابہ کرام رضوان اللہ عنھم اجمعین نے کہا: اللہ کے رسول اللہ صلی اللہ علیہ وسلم!آپ کو بھی نہیں؟فرمایا:\"مجھے بھی نہیں الایہ کہ اللہ مجھے اپنی رحمت سے ڈھانپ لے اور جان رکھو کہ اللہ کے نزدیک محبوب ترین عمل وہ ہے جو ہمیشہ کیا جائے چاہے کم ہو۔\""}],[7180,"عبد العزیز بن مطلب نے ہمیں موسی بن عقبہ سے اسی سند کے ساتھ حدیث بیان کی اور \" خوش خبری ( کی امید ) رکھو \" ذکر نہیں کیا ۔","",{"u2":"عبد العزیز بن مطلب نے ہمیں موسیٰ بن عقبہ سے اسی سند کے ساتھ حدیث بیان کی اور\"خوش خبری (کی امید)رکھو\"ذکر نہیں کیا۔"}],[7181,"ابو عوانہ نے زیاد بن علاقہ سے اور انھوں نے سیدنا مغیرہ بن شعبہ رضی اللہ تعالی عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے اتنی ( اتنی لمبی ) نمازیں پڑھیں کہ آپ کے قدم مبارک سوج گئے ۔ آپ سے کہاگیا کہ آپ اس قدر تکلیف اٹھاتے ہیں؟حالانکہ اللہ تعالی نے آپ کے اگلے اور پچھلےگناہوں کی مغفرت فرمادی ہے ، آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" کیا میں اللہ تعالی کا شکرگزار بندہ نہ بنوں ؟","",{"u2":"ابو عوانہ نے زیاد بن علاقہ سے اور انھوں نے حضرت مغیرہ بن شعبہ رضی اللہ تعالیٰ عنہ سے روایت کی کہ نبی صلی اللہ علیہ وسلم نے اتنی (اتنی لمبی) نمازیں پڑھیں کہ آپ کے قدم مبارک سوج گئے۔\nآپ سے کہاگیا کہ آپ اس قدر تکلیف اٹھاتے ہیں؟حالانکہ اللہ تعالیٰ نے آپ کے اگلے اور پچھلےگناہوں کی مغفرت فرمادی ہے،آپ صلی اللہ علیہ وسلم نے فرمایا:\"کیا میں اللہ تعالیٰ کا شکرگزار بندہ نہ بنوں؟\""}],[7182,"سفیان نے ہمیں زیاد بن علاقہ سے حدیث بیان کی ، انھوں نے سیدنا مغیرہ بن شعبہ رضی اللہ تعالی عنہ کو کہتے ہوئے سنا : نبی صلی اللہ علیہ وسلم نے اتنا ( اتنا لمبا ) قیام کیا کہ آپ کے قدم مبارک سوج گئے ۔ انھوں ( صحابہ کرام رضوان اللہ عنھم اجمعین ) نے کہا : اللہ تعالی نے آپ کے اگلے پچھلےتمام گناہ معافکردیے ہیں ( پھر اس قدر مشقت کیوں؟ ) تو آپ نے فرمایا : \" کیا میں اللہ کا شکرگزار بندہ نہ بنوں؟","",{"u2":"سفیان نے ہمیں زیاد بن علاقہ سے حدیث بیان کی،انھوں نے حضرت مغیرہ بن شعبہ رضی اللہ تعالیٰ عنہ کو کہتے ہوئے سنا: نبی صلی اللہ علیہ وسلم نے اتنا (اتنا لمبا) قیام کیا کہ آپ کے قدم مبارک سوج گئے۔انھوں (صحابہ کرام رضوان اللہ عنھم اجمعین)نے کہا: اللہ تعالیٰ نے آپ کے اگلے پچھلےتمام گناہ معافکردیے ہیں (پھر اس قدر مشقت کیوں؟)تو آپ نے فرمایا:\"کیا میں اللہ کا شکرگزار بندہ نہ بنوں؟"}],[7183,"عروہ بن زبیر نے سیدہ عائشہ رضی اللہ تعالی عنہا سے روایت کی ، کہا : نبی صلی اللہ علیہ وسلم جب نماز پڑھتے تو ( بہت لمبا ) قیام کرتے یہاں تک کہ آپ کے قدم مبارک سوج جاتے ، سیدہ عائشہ رضی اللہ تعالی عنہا نے کہا : اللہ کے رسول اللہ صلی اللہ علیہ وسلم !آپ ایسا کرتے ہیں ۔ حالانکہ آپ کے اگلےپچھلے تمام گناہوں کی مغفرت کی ( یقین دہانی کرائی ) جاچکی ہے؟آپ صلی اللہ علیہ وسلم نے فرمایا : \" اے عائشہ رضی اللہ تعالی عنہا !کیا میں ( اللہ تعالی کا ) شکرگزار بندہ نہ بنوں؟","",{"u2":"عروہ بن زبیر نے حضرت عائشہ رضی اللہ تعالیٰ عنہا سے روایت کی، کہا: نبی صلی اللہ علیہ وسلم جب نماز پڑھتے تو (بہت لمبا) قیام کرتے یہاں تک کہ آپ کے قدم مبارک سوج جاتے،حضرت عائشہ رضی اللہ تعالیٰ عنہا نے کہا: اللہ کے رسول اللہ صلی اللہ علیہ وسلم!آپ ایسا کرتے ہیں۔حالانکہ آپ کے اگلےپچھلے تمام گناہوں کی مغفرت کی(یقین دہانی کرائی) جاچکی ہے؟آپ صلی اللہ علیہ وسلم نے فرمایا:\"اے عائشہ رضی اللہ تعالیٰ عنہا!کیا میں (اللہ تعالیٰ کا)شکرگزار بندہ نہ بنوں؟\""}],[7184,"ابو معاویہ نے اعمش سے اور انھوں نے شقیق سے روایت کی ، کہا : ہم سیدنا عبد اللہ بن مسعود رضی اللہ تعالی عنہ کے انتظار میں ان کے گھر کے دروازےپربیٹھےہوئے تھے کہ اتنے میں یزید بن معاویہ نخعی ہمارے پاس سے گزرے تو ہم نے کہا : ان ( عبداللہ بن مسعود رضی اللہ تعالی عنہ ) کو ہمارے آنے کی اطلاع کردیں وہ ان کے پاس گئے تو تھوڑی ہی دیر میں سیدنا عبد اللہ ( بن مسعود رضی اللہ تعالی عنہ ) آگئے ۔ اور فرمایا : \" مجھے تمھارے آنے کی اطلاع کردی گئی تھی اور مجھے تمھارے پاس آنے سے صرف یہ ناپسندیدگی مانع تھی کہ میں تمھاری اکتاہٹ کا سبب نہ بن جاؤں ۔ بلاشبہ رسول اللہ صلی اللہ علیہ وسلم بھی ہمارے اکتا جانے کے ڈرسے صرف بعض دنوں میں ہی وعظو نصیحت سے نوازاکرتے تھے ۔","",{"u2":"ابو معاویہ نے اعمش سے اور انھوں نے شقیق سے روایت کی، کہا: ہم حضرت عبد اللہ بن مسعود رضی اللہ تعالیٰ عنہ کے انتظار میں ان کے گھر کے دروازےپربیٹھےہوئے تھے کہ اتنے میں یزید بن معاویہ نخعی ہمارے پاس سے گزرے تو ہم نے کہا: ان (عبداللہ بن مسعود رضی اللہ تعالیٰ عنہ)کو ہمارے آنے کی اطلاع کردیں وہ ان کے پاس گئے تو تھوڑی ہی دیر میں حضرت عبد اللہ (بن مسعود رضی اللہ تعالیٰ عنہ) آگئے۔اور فرمایا:\"مجھے تمھارے آنے کی اطلاع کردی گئی تھی اور مجھے تمھارے پاس آنے سے صرف یہ ناپسندیدگی مانع تھی کہ میں تمھاری اکتاہٹ کا سبب نہ بن جاؤں۔بلاشبہ رسول اللہ صلی اللہ علیہ وسلم بھی ہمارے اکتا جانے کے ڈرسے صرف بعض دنوں میں ہی وعظو نصیحت سے نوازاکرتے تھے۔"}],[7185,"ابو سعید اشج نے ہمیں حدیث بیان کی ، کہا : ہمیں ابن ادریس نے حدیث بیان کی ، نیز ہمیں منجانب بن حارث تمیمی نے حدیث بیان کی ، کہا : ہمیں ابن مسہر نے خبر دی ، نیز ہمیں اسحٰق بن ابراہیم اور علی بن خشرم نے حدیث بیان کی ، دونوں نے کہا : ہمیں عیسی بن یونس نے خبر دی ، نیز ہمیں ابن ابی عمر نے حدیث بیان کی ، انھوں نے کہا : ہمیں سفیان نے حدیث بیان کی ، ان سب نے اعمش سے اسی سند کے ساتھ اسی کے مطابق روایت کی ۔ اور منجانب نے اپنی روایت میں مزید یہ کہا : ابن مسہر سے روایت ہے اعمش نے کہا : اور مجھے عمرو بن مرہ نے شیقق سے اور انھوں نے عبد اللہ ( بن مسعود رضی اللہ تعالی عنہ ) سے اسی کے مانند حدیث بیان کی ۔","",{"u2":"ابو سعید اشج نے ہمیں حدیث بیان کی، کہا: ہمیں ابن ادریس نے حدیث بیان کی، نیز ہمیں منجانب بن حارث تمیمی نے حدیث بیان کی، کہا: ہمیں ابن مسہر نے خبر دی،نیز ہمیں اسحٰق بن ابراہیم اور علی بن خشرم نے حدیث بیان کی،دونوں نے کہا: ہمیں عیسیٰ بن یونس نے خبر دی، نیز ہمیں ابن ابی عمر نے حدیث بیان کی، انھوں نے کہا: ہمیں سفیان نے حدیث بیان کی،ان سب نے اعمش سے اسی سند کے ساتھ اسی کے مطابق روایت کی۔اور منجانب نے اپنی روایت میں مزید یہ کہا:ابن مسہر سے روایت ہے اعمش نے کہا: اور مجھے عمرو بن مرہ نے شیقق سے اور انھوں نے عبد اللہ (بن مسعود رضی اللہ تعالیٰ عنہ) سے اسی کے مانند حدیث بیان کی۔"}],[7186,"منصور نے شیقق ابو وائل سے روایت کی کہ سیدنا عبد اللہ ( بن مسعود رضی اللہ تعالی عنہ ) ہمیں ہر جمعرات کے دن وعظ و نصیحت فرمایا کرتے تھے تو ایک شخص نے کہا : ابو عبد الرحمٰن !ہمیں آپ کی باتیں ( بہت ) پسند ہیں اور ہم ان کی طرف شدید رغبت رکھتے ہیں ۔ ہم چاہتے ہیں کہ آپ ہر روز ہمیں احادیث بیان فرمایا کریں ۔ انھوں نے کہا : مجھے اس کے علاوہ تمھیں احادیث بیان کرنے سے صرف یہ ناپسندیدگی مانع ہے کہ میں تمھیں اکتاہٹ کا شکار نہ کردوں ۔ رسول اللہ صلی اللہ علیہ وسلم اس بات کو ناپسند کرتے ہوئے کہ ہم پر اکتاہٹ طاری ہو جائے کچھ ( خاص ) دنوں میں ہی ہمیں وعظ و نصیحت سے نواازاکرتے تھے ۔","",{"u2":"منصور نے شیقق ابو وائل سے روایت کی کہ حضرت عبد اللہ (بن مسعود رضی اللہ تعالیٰ عنہ) ہمیں ہر جمعرات کے دن وعظ و نصیحت فرمایا کرتے تھے تو ایک شخص نے کہا: ابو عبد الرحمٰن!ہمیں آپ کی باتیں (بہت) پسند ہیں اور ہم ان کی طرف شدید رغبت رکھتے ہیں۔ہم چاہتے ہیں کہ آپ ہر روز ہمیں احادیث بیان فرمایا کریں۔انھوں نے کہا: مجھے اس کے علاوہ تمھیں احادیث بیان کرنے سے صرف یہ ناپسندیدگی مانع ہے کہ میں تمھیں اکتاہٹ کا شکار نہ کردوں۔رسول اللہ صلی اللہ علیہ وسلم اس بات کو ناپسند کرتے ہوئے کہ ہم پر اکتاہٹ طاری ہو جائے کچھ (خاص) دنوں میں ہی ہمیں وعظ و نصیحت سے نواازاکرتے تھے۔"}],[7187,"حضر ت انس بن مالک رضی اللہ تعالی عنہ سے روایت ہے ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" جنت گراں امور میں گھری ہوئی ہے اور دوزخ خواہشات نفسانی میں گھری ہوئی ہے ۔","",{"u2":"حضر ت انس بن مالک رضی اللہ تعالیٰ عنہ سے روایت ہے،کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\" جنت گراں امور میں گھری ہوئی ہے اور دوزخ خواہشات نفسانی میں گھری ہوئی ہے۔\""}],[7188,"سیدنا ابوہریرہ رضی اللہ تعالی عنہ نے نبی کریم صلی اللہ علیہ وسلم سے اسی کی مانند روایت کی ۔","",{"u2":"حضرت ابوہریرہ رضی اللہ تعالیٰ عنہ نے نبی کریم صلی اللہ علیہ وسلم سے اسی کی مانند روایت کی۔"}],[7189,"سفیان نے ابو زناد سے ، انھوں نے اعرج سے ، انھوں نے سیدنا ابوہریرۃ رضی اللہ تعالی عنہ سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا : \"\" اللہ عزوجل نے ارشادفرمایا : میں نے اپنے نیک بندوں کےلیے وہ کچھ تیار کررکھا ہے جسے ن کسی آنکھ نے دیکھا ہے نہ کسی کان نے سنا ہے اور نہ کسی انسان کے دل میں ان کا خیال تک گزرا ہے ۔ \"\" کتاب اللہ میں اس کا مصداق ( یہ آیت ) ہے : \"\" کسی کومعلوم نہیں کہ جو نیک کام کرتے رہے ان کی جزا کے طور پر ان کی آنکھوں کو ٹھنڈا کرنے کےلیے کیا جو چھپا کررکھا گیا ہے ۔","",{"u2":"سفیان نے ابو زناد سے،انھوں نے اعرج سے،انھوں نے حضرت ابوہریرۃ رضی اللہ تعالیٰ عنہ سے اور انھوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا:\" اللہ عزوجل نے ارشادفرمایا:میں نے اپنے نیک بندوں کےلیے وہ کچھ تیار کررکھا ہے جسے ن کسی آنکھ نے دیکھا ہے نہ کسی کان نے سنا ہے اور نہ کسی انسان کے دل میں ان کا خیال تک گزرا ہے۔\"\nکتاب اللہ میں اس کا مصداق (یہ آیت) ہے:\"کسی کومعلوم نہیں کہ جو نیک کام کرتے رہے ان کی جزا کے طور پر ان کی آنکھوں کو ٹھنڈا کرنے کےلیے کیا جو چھپا کررکھا گیا ہے۔\""}],[7190,"مالک نے ابو زناد سے ، انھوں نے اعرج سے اور انھوں نے سیدنا ابو ہریرہ رضی اللہ تعالی عنہ سے روایت کی کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا؛ \" اللہ عزوجل نے ارشاد فرمایا : میں نے اپنے نیک بندوں کے لئے وہ کچھ تیار کرکے جمع کررکھا ہے جو نہ کسی آنکھ نے دیکھا نہ کسی کان نے سنا اور نہ کسی انسان کے دل میں ان ( کے تصور ) کا گزر ہوا ۔ ( یہ ) ان ( نعمتوں کے ) علاوہ ہے جن کے ) علاوہ ہے ۔ جن کے بارے میں تمھیں اللہ تعالی نے مطلع کردیاہے ۔","",{"u2":"مالک نے ابو زناد سے،انھوں نے اعرج سے اور انھوں نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت کی کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا؛\"اللہ عزوجل نے ارشاد فرمایا: میں نے اپنے نیک بندوں کے لئے وہ کچھ تیار کرکے جمع کررکھا ہے جو نہ کسی آنکھ نے دیکھا نہ کسی کان نے سنا اور نہ کسی انسان کے دل میں ان(کے تصور) کا گزر ہوا۔(یہ) ان(نعمتوں کے) علاوہ ہے جن کے)علاوہ ہے۔جن کے بارے میں تمھیں اللہ تعالیٰ نے مطلع کردیاہے۔\""}],[7191,"ابو صالح نے سیدنا ابو ہریرۃ رضی اللہ تعالی عنہ سے روایت کی ، کہا : رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \"\" اللہ عزوجل ارشاد فرماتاہے : میں نے اپنے نیک بندوں کے لئے وہ نعمتیں تیار کرکے جمع کی ہیں جن کو نہ کسی آنکھ نے دیکھا نہ کسی کان نے سنا اور نہ ان کا کسی بشر کے دل میں خیال گزرا ، ان نعمتوں کے علاوہ جن پر اللہ تعالی نے تمھیں مطلع کردیا ہے ۔ \"\" پھر آپ صلی اللہ علیہ وسلم نے ( یہ آیت ) پڑھی : \"\" کسی کو معلوم نہیں کہ ان کی آنکھوں کی ٹھنڈک کےلیے کیا کچھ چھپا کررکھاگیاہے ۔","",{"u2":"ابو صالح نے حضرت ابو ہریرۃ رضی اللہ تعالیٰ عنہ سے روایت کی،کہا:رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"اللہ عزوجل ارشاد فرماتاہے:میں نے اپنے نیک بندوں کے لئے وہ نعمتیں تیارکرکے جمع کی ہیں جن کو نہ کسی آنکھ نے دیکھا نہ کسی کان نے سنا اور نہ ان کا کسی بشر کے دل میں خیال گزرا،ان نعمتوں کے علاوہ جن پر اللہ تعالیٰ نے تمھیں مطلع کردیا ہے۔\"\nپھر آپ صلی اللہ علیہ وسلم نے(یہ آیت) پڑھی:\"کسی کو معلوم نہیں کہ ان کی آنکھوں کی ٹھنڈک کےلیے کیا کچھ چھپا کررکھاگیاہے۔\""}],[7192,"ابوحازم نے کہا : میں نے حضر ت سہل بن سعد ساعدی رضی اللہ تعالی عنہ کو بیان کرتے ہوئے سنا : میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک مجلس میں حاضر ہوا جس میں آپ نے جنت کی صفت بیان کی حتی کہ آ پ نے بات ختم کی ۔ پھر اپنی بات کے آخر میں فرمایا : \" اس ( جنت ) میں وہ کچھ ہے جو نہ کسی آنکھ نے دیکھا نہ کسی کان نے سنا نہ کسی انسان کے دل میں اس کا خیال گزرا ۔ \" پھر آپ نے یہ آیت پڑھی : \" ان کے پہلو بستروں سے دور رہتے ہیں وہ خوف کے عالم میں اور پوری امید کے ساتھ اپنے رب کو پکارتے ہیں اور ہم نے جو رزق ان کو دیا ہے اس میں سے ( اللہ کی راہ میں ) خرچ کر تے ہیں ۔ پس کوئی ذی حیات ( انسان ) نہیں جانتا کہ جو وہ کرتے ہیں اس کے صلے میں ان کی آنکھوں کی ٹھنڈک کےلیے کیا ( کچھ ) چھپا کررکھا گیاہے ۔","",{"u2":"ابوحازم نے کہا:میں نے حضر ت سہل بن سعد ساعدی رضی اللہ تعالیٰ عنہ کو بیان کرتے ہوئے سنا:میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک مجلس میں حاضر ہوا جس میں آپ نے جنت کی صفت بیان کی حتیٰ کہ آ پ نے بات ختم کی۔پھر اپنی بات کے آخر میں فرمایا:\"اس(جنت) میں وہ کچھ ہے جو نہ کسی آنکھ نے دیکھا نہ کسی کان نے سنا نہ کسی انسان کے دل میں اس کا خیال گزرا۔\"پھر آپ نے یہ آیت پڑھی:\"ان کے پہلو بستروں سے دور رہتے ہیں وہ خوف کے عالم میں اور پوری امید کے ساتھ اپنے رب کو پکارتے ہیں اور ہم نے جو رزق ان کو دیا ہے اس میں سے(اللہ کی راہ میں) خرچ کر تے ہیں۔پس کوئی ذی حیات(انسان) نہیں جانتا کہ جو وہ کرتے ہیں اس کے صلے میں ان کی آنکھوں کی ٹھنڈک کےلیے کیا(کچھ) چھپا کررکھا گیاہے۔\""}],[7193,"ابو سعید مقبری نے سیدنا ابو ہریرہ رضی اللہ تعالی عنہ سے ، انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا : \" جنت میں ایک درخت ہے جس کے سائے میں ایک اونٹ سوار سوسال تک چلتا رہے گا ۔","",{"u2":"ابو سعید مقبری نے حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے،انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے روایت کی کہ آپ نے فرمایا:\"جنت میں ایک درخت ہے جس کے سائے میں ایک اونٹ سوار سوسال تک چلتا رہے گا۔\""}],[7194,"اعرج نے سیدنا ابوہریرہ رضی اللہ تعالی عنہ سے ، انھوں نے نبی کریم صلی اللہ علیہ وسلم سے اسی کی مثل روایت کی اور مزید کہا : \" وہ اس ( کے سائے ) کو طے نہیں کرسکے گا ۔","",{"u2":"اعرج نے حضرت ابوہریرہ رضی اللہ تعالیٰ عنہ سے،انھوں نے نبی کریم صلی اللہ علیہ وسلم سے اسی کی مثل روایت کی اور مزید کہا:\"وہ اس (کے سائے) کو طے نہیں کرسکے گا۔\""}],[7195,"ابوحازم نے حضر ت سہل بن سعد رضی اللہ تعالی عنہ سے ، انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے ر وایت کی کہ آپ نے فرمایا : \" جنت میں ایک درخت ہے ، ایک سوار اس کے سائے میں سوسال تک چلتا رہے تو بھی اس کو طے نہ کرسکے ۔","",{"u2":"ابوحازم نے حضر ت سہل بن سعد رضی اللہ تعالیٰ عنہ سے،انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے ر وایت کی کہ آپ نے فرمایا:\"جنت میں ایک درخت ہے،ایک سوار اس کے سائے میں سوسال تک چلتا رہے تو بھی اس کو طے نہ کرسکے۔\"\nیعقوب بن عبدالرحمان القاری نے ہمیں ابوحازم سے حدیث بیان کی،انھوں نے حضرت سہل بن سعد رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا؛\"جنت والے جنت کے بالا خانے کو اس طرح دیکھیں گے جس طرح تم لوگ آسمان میں ستارے کو دیکھتے ہو۔\""}],[7196,"ابوحازم نے حضر ت سہل بن سعد رضی اللہ تعالی عنہ سے ، انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے ر وایت کی کہ آپ نے فرمایا : \" جنت میں ایک درخت ہے ، ایک سوار اس کے سائے میں سوسال تک چلتا رہے تو بھی اس کو طے نہ کرسکے ۔","",{"u2":"ابو حازم نے کہا:میں نے یہ حدیث نعمان بن ابی عیاش زرقی کو سنائی تو انھوں نے کہا:مجھے ابو سعید خدری رضی اللہ تعالیٰ عنہ نے نبی کریم صلی اللہ علیہ وسلم سے روایت کرتے ہوئے بیان کیا،آپ صلی اللہ علیہ وسلم نے فرمایا:\"جنت میں ایک درخت ہے(جس کے سائے میں) ایک تیز رفتار چھریرے کھوڑے پرسوار شخص سو سال چلے تو بھی اسے قطع نہ کرسکے۔\""}],[7197,"سیدنا ابو سعید خدری رضی اللہ تعالی عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا : \" اللہ عزوجل اہل جنت سے فرمائے گا : اے اہل جنت! وہ کہیں گے : لبیک ، اے ہمارے رب!زہے نصیب کہ تیرے سامنے حاضر ہیں اور بھلائی تیرے ہاتھوں میں ہے چنانچہ وہ فرمائے گا : کیا تم راضی ہوگئے ہو؟وہ سب کہیں گے : ہم راضی کیوں نہ ہوں؟اے ہمارے رب! جبکہ تو نے ہمیں وہ کچھ عطا کردیا ہے جو تونے اپنی ساری مخلوق میں سے کسی کو عطا نہیں فرمایا ۔ وہ فرمائے گا : کیا میں تمھیں اس سے بھی بہتر عطا نہ کروں؟تو وہ کہیں گے : اے رب! ( جوتو نے عطا کردیا ہے ) اس سے افضل کیا ہے؟وہ فرمائے گا : میں تم پر اپنی رضا نازل کرتا ہوں ، اس کے بعد میں تم سے کبھی ناراض نہ ہوں گا ۔","",{"u2":"حضرت ابو سعید خدری رضی اللہ تعالیٰ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا:\" اللہ عزوجل اہل جنت سے فرمائے گا:اے اہل جنت! وہ کہیں گے:لبیک،اے ہمارے رب!زہے نصیب کہ تیرے سامنےحاضر ہیں اور بھلائی تیرے ہاتھوں میں ہے چنانچہ وہ فرمائے گا:کیا تم راضی ہوگئے ہو؟وہ سب کہیں گے:ہم راضی کیوں نہ ہوں؟اے ہمارے رب! جبکہ تو نے ہمیں وہ کچھ عطا کردیا ہے جو تونے اپنی ساری مخلوق میں سے کسی کو عطا نہیں فرمایا۔وہ فرمائے گا:کیا میں تمھیں اس سے بھی بہتر عطا نہ کروں؟تو وہ کہیں گے:اے رب!(جوتو نے عطا کردیا ہے) اس سے افضل کیا ہے؟وہ فرمائے گا:میں تم پر اپنی رضا نازل کرتا ہوں،اس کے بعد میں تم سے کبھی ناراض نہ ہوں گا۔\""}],[7198,"یعقوب بن عبدالرحمان القاری نے ہمیں ابوحازم سے حدیث بیان کی ، انھوں نے سیدنا سہل بن سعد رضی اللہ تعالی عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا؛ \" جنت والے جنت کے بالا خانے کو اس طرح دیکھیں گے جس طرح تم لوگ آسمان میں ستارے کو دیکھتے ہو ۔","",{"u2":"(ابوحازم نے) کہا:میں نے یہ روایت نعمان بن ابی عیاش سے بیان کی تو انھوں نے کہا:میں نے حضرت ابو سعید خدری رضی اللہ تعالیٰ عنہ کو یہ کہتے ہوئے سنا؛\"جس طرح تم آسمان کے مشرقی یامغربی افق میں چمکتے ہوئے ستارے کو دیکھتے ہو\""}],[7200,"وہیب نے ابو حازم سے گزشتہ دونوں سندوں کے ساتھ یعقوب کی حدیث کے مانند بیان کیا ۔","",{"u2":"عطاء بن یسار نے حضرت ابوسعید خدری رضی اللہ تعالیٰ عنہ سے روایت کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"اہل جنت فضیلت میں باہمی فرق کی بنا پر اپنے اوپر بالا خانوں میں رہنے والوں کی اس طرح دیکھیں گے جس طرح تم آسمان کے مشرقی یا مغربی کنارے میں چمکتے ہوئے تنہا ستارے کو دیکھتے ہو۔\"انھوں(صحابہ رضوان اللہ عنھم اجمعین) نے عرض کی:اللہ کے رسول صلی اللہ علیہ وسلم! کیا وہ انبیاء علیہ السلام کے رہنے کی جگہیں ہوں گی جن تک دوسرا کوئی نہیں پہنچ سکتا؟آپ صلی اللہ علیہ وسلم نے فرمایا؛\"کیوں نہیں،اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! یہ ایسے مرد ہوں گے جو اللہ تعالیٰ پر ایمان لائے اور انھوں نے رسولوں کی تصدیق کی۔\""}],[7201,"سیدنا ابو ہریرہ رضی اللہ تعالی عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : \" میری امت میں میرے ساتھ سب سے زیادہ محبت کرنے والوں میں وہ لوگ ( بھی ) ہیں جو میرے بعد ہوں گے ، ان میں سے ( ہر ) ایک نہ چاہتا ہوگا کہ کاش! اپنے اہل وعیال اور مال کی قربانی دے کرمجھے دیکھ لے ۔","",{"u2":"حضرت ابو ہریرہ رضی اللہ تعالیٰ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\" میری امت میں میرے ساتھ سب سے زیادہ محبت کرنے والوں میں وہ لوگ(بھی) ہیں جو میرے بعد ہوں گے،ان میں سے(ہر) ایک نہ چاہتا ہوگا کہ کاش! اپنے اہل وعیال اور مال کی قربانی دے کرمجھے دیکھ لے۔\""}]]);
